struct ST {
	int n;
	vi t;
	ST(int n) : n(n){
		t.resize(2*n);
	}
	int que(int l, int r){
		int ans = 0;
		for(l += n, r += n; l < r; l /= 2, r /= 2){
			if(l&1) ans = max(ans, t[l++]);
			if(r&1) ans = max(ans, t[--r]);
		}
		return ans;
	}
	void upd(int val, int pos){
		for(pos += n; pos; pos /= 2) t[pos] = max(t[pos], val);
	}
};

