      if( i != n ) {
        vector<int> lista;
        for( int j = 0; i < n; ++j, ++i ) {
          if( y[0] <= p[i].SE && p[i].SE <= y[1] ) {
            lista.PB(p[i].SE);
          }
        }
        cnt = LongestIncreasingSubsequenceLength( lista );
      }
    }
    else {
      int i = 0, cur = 0;
      for( ; i < n; ++i ) {
        if( p[i].FI > x[0] ) break;
        if( p[i].FI == x[0] && p[i].SE < y[0] ) break;
      }
      if( i != n ) {
        vector<int> lista;
        for( int j = 0; i < n; ++j, ++i ) {
          if( y[1] <= p[i].SE && p[i].SE <= y[0] ) {
            lista.PB(-p[i].SE);
          }
        }
        cnt = LongestIncreasingSubsequenceLength( lista );
      }
    }
    if( cnt == min(x[0]-x[1], abs(y[0]-y[1]))+1 ) {
      ans -= 20;
      --cnt;
      ans += 2*C;
    }
    ans -= 20*cnt;
  }
  cout << ans + cnt*C << '\n';
  return 0;
}

