#pragma GCC optimize(3, "Ofast", "inline")
#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const int N = 200010;
const double PI = 3.141592653589793238462643383279502884197169399375;
int p[N], t[N];
struct Node {
    int x, y;
} w[N];

inline bool cmp(Node a, Node b)
{
    if (a.x == b.x) return a.y > b.y;
    return a.x < b.x;
}

inline void add(int x, int k)
{
    for (; x < N; x += (x & (-x))) {
        t[x] = max(t[x], k);
    }
}

inline int query(int x)
{
    int ret = 0;
    for (; x; x -= (x & (-x))) {
        ret = max(ret, t[x]);
    }
    return ret;
}

int main()
{
    int a, b, c, d, n;
    scanf("%d %d %d %d", &a, &b, &c, &d);
    scanf("%d", &n);
    int tot = 0;
    for (register int i = 1, x, y; i <= n; ++i) {
        scanf("%d %d", &x, &y);
        if (min(a, c) <= x && x <= max(a, c) && min(b, d) <= y && y <= max(b, d)) {
            w[++tot].x = x, w[tot].y = y;
            p[tot] = y;
        }
    }
    sort(p + 1, p + tot + 1);
    if (c < a) swap(a, c), swap(b, d);
    if (b > d) {
        for (register int i = 1; i <= tot; ++i) {
            w[i].x = -w[i].x;
        }
    }
    sort(w + 1, w + tot + 1, cmp);
    for (register int i = 1; i <= tot; ++i) {
        int pos = lower_bound(p + 1, p + tot + 1, w[i].y) - (p + 1) + 1;
        int pt = query(pos - 1);
        add(pos, pt + 1);
    }
    int num = query(max(b, d));
    double ans = 100.0 * (abs(c - a) + abs(d - b)) - 20.0 * num + 5.0 * PI * num;
    if (num == min(abs(c - a), abs(d - b)) + 1) ans += 5.0 * PI;
    printf("%.13f\n", ans);
    return 0;
}

