void upd(int pos, int val, int v = 1, int tl = 0, int tr = 1e8) {
	if(tl == tr) {
		t[v] = val;
		return;   
	}
	int mid = (tl + tr) >> 1;
	if(pos <= mid) {
		if(!L[v]) L[v] = ++ Sz;
		upd(pos, val, L[v], tl, mid);
	} else {
		if(!R[v]) R[v] = ++ Sz;
		upd(pos, val, R[v], mid + 1, tr);
	}
	t[v] = max(t[L[v]], t[R[v]]);
}

