const long double PI = acos(-1.0L);
int n;
P s, t;
vector<P> v;
map<long long, int> mp;

long double solve();
long double calc(P x) { return x.first * 5 * PI - 20 * x.second; }

int main() {
  cout << fixed << setprecision(15);
  cin >> s.first >> s.second >> t.first >> t.second >> n;
  if (s > t) swap(s, t);
  for (int i = 0; i < n; ++i) {
    P p;
    cin >> p.first >> p.second;
    if (s.first <= p.first && p.first <= t.first &&
        min(s.second, t.second) <= p.second &&
        p.second <= max(s.second, t.second))
      v.push_back(p);
  }
  n = v.size();
  if (s.second > t.second) {
    s.second = (long long)1e8 - 1 - s.second;
    t.second = (long long)1e8 - 1 - t.second;
    for (auto &p : v) p.second = (long long)1e8 - 1 - p.second;
  }
  sort(v.begin(), v.end());
  {
    vector<long long> tmp;
    tmp.push_back(s.second);
    tmp.push_back(t.second);
    for (auto p : v) tmp.push_back(p.second);
    sort(tmp.begin(), tmp.end());
    tmp.erase(unique(tmp.begin(), tmp.end()), tmp.end());
    for (int i = 0; i < tmp.size(); ++i) mp[tmp[i]] = i;
  }
  cout << solve() << endl;
  return 0;
}

long double solve() {
  vector<int> lis;
  for (int i = 0; i < n; ++i) {
    int id = mp[v[i].second];
    int now = lower_bound(lis.begin(), lis.end(), id) - lis.begin();
    if (now == lis.size())
      lis.push_back(id);
    else
      lis[now] = id;
  }
  int res = lis.size();
  return calc(P(res + (res == (t.second - s.second + 1) ||
                       res == (t.first - s.first + 1)),
                res)) +
         (t.first + t.second - s.first - s.second) * 100;
}

