int cmp1(punct a,punct b)
{
    return a.y>b.y;
}

int cmp2(punct a,punct b)
{
    return a.y<b.y;
}

int cmp3(punct a,punct b)
{
    return a.x<b.x;
}

void arbint_update(int nod,int st,int dr,int poz,int val)
{
    if(st==dr) arb[nod]=val;
    else
    {
        int mid=(st+dr)/2;
        if(poz<=mid) arbint_update(nod*2,st,mid,poz,val);
        else arbint_update(nod*2+1,mid+1,dr,poz,val);
        arb[nod]=max(arb[nod*2],arb[nod*2+1]);
    }
}

int arbint_query(int nod,int st,int dr,int left,int right)
{
    if(left<=st && dr<=right) return arb[nod];
    int mid=(st+dr)/2;s=0;
    if(left<=mid) s=max(s,arbint_query(nod*2,st,mid,left,right));
    if(mid<right) s=max(s,arbint_query(nod*2+1,mid+1,dr,left,right));
    return s;
}

int main()
{
    //freopen("file.in","r",stdin);
    //freopen("file.out","w",stdout);
    int x1,y1,x2,y2,n,x,y;
    scanf("%d%d%d%d",&x1,&y1,&x2,&y2);
    if(x1>x2) {swap(x1,x2);swap(y1,y2);}
    scanf("%d",&n);
    double sol=1LL*abs(x2-x1)*100+1LL*abs(y2-y1)*100;
    int l=0;
    for(int i=1;i<=n;i++)
    {
        scanf("%d%d",&x,&y);
        if(x>=x1 && x<=x2 && y>=min(y1,y2) && y<=max(y1,y2)) v[++l]={x,y};
    }
    if(y1==y2)
    {
        if(l>0) sol=sol-20+5.0*pi*2;
        printf("%.16f",sol);
        return 0;
    }
    if(x1==x2)
    {
        if(l>0) sol=sol-20+5.0*pi*2;
        printf("%.16f",sol);
        return 0;
    }
    if(y1>y2) sort(v+1,v+l+1,cmp1);
    else sort(v+1,v+l+1,cmp2);
    for(int i=1;i<=l;i++) v1[i]=v[i];
    sort(v1+1,v1+l+1,cmp3);
    for(int i=1;i<=l;i++)
        v1[i].y=i;
    int c=0;
    for(int i=1;i<=l;i++)
    {
        int st=1,dr=l;
        while(st<=dr)
        {
            int mid=(st+dr)/2;
            if(v1[mid].x<v[i].x) st=mid+1;
            else dr=mid-1;
        }
        int val=arbint_query(1,1,n,1,v1[st].y)+1;
        c=max(c,val);
        arbint_update(1,1,n,v1[st].y,val);
    }
    sol=sol-20*c+5.0*pi*c;
    printf("%.16f",sol);
    return 0;
}

