const int MAXSEG = 2e5+4;  // limit for array size
int segn=MAXSEG;  // array size
typedef int S;
S t[2 * MAXSEG];
S identity = 0;
S combine(const S& lefts, const S& rights) {
	return max(lefts,rights);
}
void build(S *t) {  // build the tree
	int n=segn;
  for (int i = n - 1; i > 0; --i) t[i] = combine(t[i<<1], t[i<<1|1]);
}

void modify(int p, const S& value) { // set value at position p
	int n=segn;
  for (t[p += n] = value; p >>= 1; ) t[p] = combine(t[p<<1], t[p<<1|1]);
}

S query(int l, int r) { // sum on interval [l, r]
	r++;
	int n=segn;
  S resl=identity, resr=identity;
  for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
    if (l&1) resl = combine(resl, t[l++]);
    if (r&1) resr = combine(t[--r], resr);
  }
  return combine(resl, resr);
}




const int REFL=1e8;
bool cmp(const pii &a, const pii &b) {
	if (a.fst==b.fst) {
		return a.snd>b.snd;
	}
	return a.fst>b.fst;
}
void makeunique(vector<int> &vx) {
  sort(vx.begin(),vx.end());
  auto it=unique(vx.begin(),vx.end());
  vx.resize(std::distance(vx.begin(),it));
}
int bins(vector<int> &vx, int x) {
  int imin=0,imax=vx.size();
  while(imin<imax) {
    int imid=(imin+imax)>>1;
    if (vx[imid]<x) imin=imid+1;
    else imax=imid;
  }
  return imin;
}
ld QUARTER=M_PI*5;
void solve(vector<long long> ox, vector<long long> oy, long long n, vector<long long> vx, vector<long long> vy){
	cout<<fixed<<setprecision(20);
	if (ox[0]>ox[1]) {
		swap(ox[0],ox[1]);
		swap(oy[0],oy[1]);
	}
	int sx=ox[0],sy=oy[0];
	int tx=ox[1],ty=oy[1];
	if (sy>ty) {
		sy=REFL-sy;
		ty=REFL-ty;
		for (auto &y:vy) {
			y=REFL-y;
		}
	}
	if (sx==tx||sy==ty) {
		int hit=0;
		for (int i=0;i<vx.size();i++) {
			int x=vx[i],y=vy[i];
			if (sx<=x&&x<=tx&&sy<=y&&y<=ty) {
				hit++;
			}
		}
		ld ans=100.0L*(abs(tx-sx)+abs(ty-sy))+2ll*(QUARTER-10)*hit;
		cout<<ans<<endl; return;
	}
	vector<pii> vp;
	vector<int> by;
	for (int i=0;i<vx.size();i++) {
		int x=vx[i],y=vy[i];
		if (sx<=x&&x<=tx&&sy<=y&&y<=ty) {
			vp.PB(MP(x,y));
			by.PB(y);
		}
	}
	sort(vp.begin(),vp.end(),cmp);
  makeunique(by);
  for (int i=0;i<vp.size();i++) {
    ll x=vp[i].fst,y=vp[i].snd;
    vp[i].snd=bins(by,y);
  }
  int ylim=MAXSEG-1;
  int best=0;
  for (int i=0;i<vp.size();i++) {
  	int y=vp[i].snd;
  	int got=query(y,ylim);
  	//printf("x:%d y:%d. got:%d\n",vp[i].fst,y,got);
  	got++;
  	chkmax(best,got);
  	modify(y,got);
  }
  ld save=20-QUARTER;
  ld final=100.0L*(abs(sx-tx)+abs(sy-ty))-save*best;
  cout<<final<<endl;
}

