class SegmTreeMax {
  vector<double> tree;
  vector<double> psh;
  int n;

  void push(int v, int l, int r) {
    tree[v] = max(tree[v], psh[v]);
    if (l != r) {
      psh[2 * v + 1] = max(psh[2 * v + 1], psh[v]);
      psh[2 * v + 2] = max(psh[2 * v + 2], psh[v]);
    }
    psh[v] = -INF;
  }

  void set_max(int v, int l, int r, int L, int R, double val) {
    push(v, l, r);
    if (L > R) return;
    if (L == l && r == R) {
      psh[v] = val;
      push(v, l, r);
      return;
    }

    int mid = (l + r) / 2;

    set_max(2 * v + 1, l, mid, L, min(mid, R), val);
    set_max(2 * v + 2, mid + 1, r, max(mid + 1, L), R, val);

    tree[v] = max(tree[2 * v + 1], tree[2 * v + 2]);
  }

  void set(int v, int l, int r, int pos, double val) {
    if (l == r) {
      tree[v] = val;
      return;
    }

    int mid = (l + r) / 2;
    if (pos <= mid) set(2 * v + 1, l, mid, pos, val);
    else set(2 * v + 2, mid + 1, r, pos, val);

    push(2 * v + 1, l, mid);
    push(2 * v + 2, mid + 1, r);

    tree[v] = max(tree[2 * v + 1], tree[2 * v + 2]);
  }

  double get(int v, int l, int r, int L, int R) {
    push(v, l, r);
    if (L > R) return -INF;
    if (L == l && r == R)
      return tree[v];
    int mid = (l + r) / 2;

    double a = get(2 * v + 1, l, mid, L, min(mid, R));
    double b = get(2 * v + 2, mid + 1, r, max(mid + 1, L), R);
    return max(a, b);
  }

public:
  void init(int n) {
    this->n = n;
    tree.assign(4 * n, -INF);
    psh.assign(4 * n, -INF);
  }

  void set(int pos, double val) {
    set(0, 0, n - 1, pos, val);
  }

  void set_max(int l, int r, double val) {
    set_max(0, 0, n - 1, l, r, val);
  }

  double get(int l, int r) {
    return get(0, 0, n - 1, l, r);
  }
};

