int flip(int s) {
  return 100000000 - s - 1;
}

int lis(const vector<int>& a) {
  const int n = a.size();
  if (n == 0) {
    return 0;
  }

  vector<int> A(n, INF), id(n);
  for (int i = 0; i < n; ++i) {
    id[i] = distance(A.begin(), lower_bound(A.begin(), A.end(), a[i]));
    A[id[i]] = a[i];
  }
  return *max_element(id.begin(), id.end()) + 1;
}

int main() {
  int sx = in();
  int sy = in();
  int gx = in();
  int gy = in();
  int N = in();

  for (int i = 0; i < N; ++i) {
    X[i] = in();
    Y[i] = in();
  }

  if (sx > gx) {
    sx = flip(sx);
    gx = flip(gx);
    for (int i = 0; i < N; ++i) {
      X[i] = flip(X[i]);
    }
  }
  if (sy > gy) {
    sy = flip(sy);
    gy = flip(gy);
    for (int i = 0; i < N; ++i) {
      Y[i] = flip(Y[i]);
    }
  }
  if (gx - sx < gy - sy) {
    swap(sx, sy);
    swap(gx, gy);
    for (int i = 0; i < N; ++i) {
      swap(X[i], Y[i]);
    }
  }

  map<int, int> xpos;
  for (int i = 0; i < N; ++i) {
    xpos[Y[i]] = X[i];
  }

  bool stairs = true;
  for (int y = sy, px = -1; y < gy; ++y) {
    if (xpos.count(y) == 0) {
      stairs = false;
      break;
    }
    int x = xpos[y];
    if (x < sx || x > gx) {
      stairs = false;
      break;
    }
    if (px != -1 && x < px) {
      stairs = false;
      break;
    }
    px = x;
  }

  if (stairs) {
    double res = 0;
    res += (5 * PI - 20) * (gy - sy);
    if (xpos.count(gy) > 0) {
      const int lx = xpos[gy];
      const int px = (sy < gy ? xpos[gy - 1] : sx);
      if (px <= lx && lx <= gx) {
        res += (10 * PI - 20);
      }
    }
    printf("%.13f\n", res + ((gx - sx) + (gy - sy)) * 100.0);
    return 0;
  }

  vector<pair<int, int>> F;
  for (int i = 0; i < N; ++i) {
    if (sy <= Y[i] && Y[i] <= gy && sx <= X[i] && X[i] <= gx) {
      F.emplace_back(Y[i], X[i]);
    }
  }
  sort(F.begin(), F.end());

  vector<int> xs;
  for (const auto& p : F) {
    xs.push_back(p.second);
  }

  int L = lis(xs);
  double res = (5 * PI - 20) * L;
  printf("%.13f\n", res + ((gx - sx) + (gy - sy)) * 100.0);

  return 0;
}

