int const maxn = 200005;
int tree[4 * maxn];

int sz = 1;

inline int get(int l, int r)
{
    int ans = 0;
    for(l += sz, r += sz; l <= r; l >>= 1, r >>= 1)
    {
        if (l&1)
            ans = max(ans, tree[l++]);
        if (~r&1)
            ans = max(ans, tree[r--]);
    }
    return ans;
}

inline void upd(int ind, int val)
{
    for(tree[ind += sz] = val; ind > 1; ind >>= 1)
        tree[ind >> 1] = max(tree[ind], tree[ind ^ 1]);
}

int main()
{
