				if (x1 <= P[i].first && P[i].first <= x2) continue;
			swap(P.back(), P[i]);
			P.pop_back(); N--; i--;
		}
		sort(P.begin(), P.end());
		bool special = true;
		for (UL i = 1; i < N; i++)
			if (!(P[i - 1].second < P[i].second)) special = false;
