int solve(int n, const vector<int>& a) {

  fill(dp, dp+n, INF);
  for (int i=0; i<n; ++i) {
    *lower_bound(dp, dp+n, a[i]) = a[i];
  }
  return lower_bound(dp, dp+n, INF) - dp ;
}

