template<typename A,typename B> inline A fexp(A x,B p,A mo){A ans=1;for(;p;p>>=1,x=1LL*x*x%mo)if(p&1)ans=1LL*ans*x%mo;return ans;}

int n;

ld ans;

int X1,Y1,X2,Y2;

int x[maxn],y[maxn];

int hs[maxn],dp[maxn],c[maxn],id[maxn];

ld d1=20.-5.*PI;
ld d2=10.*PI-20;

bool cmp(int i,int j){
	return x[i]<x[j]||(x[i]==x[j]&&y[i]<y[j]);
}

void add(int x,int y){
	for(;x<=n;x+=x&-x)c[x]=max(c[x],y);
}

int query(int x){
	int ans=-MAX;
	for(;x;x-=x&-x)ans=max(ans,c[x]);
	return ans;
}

void Work(){
	if(X1==X2){
		ld ok=0;
		REP(i,1,n)if(x[i]==X1&&Y1<=y[i]&&y[i]<=Y2)ok=1;
		printf("%.15Lf\n",(ld)(Y2-Y1)*100.0+ok*d2);
		return;
	}
	if(Y1==Y2){
		ld ok=0;
		REP(i,1,n)if(y[i]==Y1&&X1<=x[i]&&x[i]<=X2)ok=1;
		printf("%.15Lf\n",(ld)(X2-X1)*100.0+ok*d2);
		return;
	}
	n++;x[n]=X1;y[n]=Y1;
	n++;x[n]=X2;y[n]=Y2;
	REP(i,1,n)id[i]=i;
	sort(id+1,id+n+1,cmp);
	REP(i,1,n)hs[i]=y[i],c[i]=-MAX;
	sort(hs+1,hs+n+1);
	REP(tmp,1,n){
		int i=id[tmp];
		if(x[i]==X1&&y[i]==Y1)dp[i]=0;else dp[i]=-MAX;
		int t=lower_bound(hs+1,hs+n+1,y[i])-hs;
		dp[i]=max(dp[i],query(t)+1);
		add(t,dp[i]);
		if(x[i]==X2&&y[i]==Y2)ans=dp[i]-1;
	}
	if(ans==min(X2-X1+1,Y2-Y1+1))printf("%.15Lf\n",(ld)(X2-X1+Y2-Y1)*100.0-(ans-1)*d1+d2);else printf("%.15Lf\n",(ld)(X2-X1+Y2-Y1)*100.0-(ans)*d1);
}

void Init(){
	read(X1,Y1,X2,Y2);
	read(n);
	REP(i,1,n)read(x[i],y[i]);
	if(X1>X2)swap(X1,X2),swap(Y1,Y2);
	if(Y1>Y2){
		Y1=100000005-Y1;
		Y2=100000005-Y2;
		REP(i,1,n)y[i]=100000005-y[i];
	}
}

int main(){
	Init();
	Work();
	return 0;
}

