int bin_search(LL x) {
	int l = 0, r = len;
	int mid = 0, ans = 0;
	while(l <= r) {
		mid = (l + r) >> 1;
		if(d[mid] >= x) ans = mid, r = mid - 1;
		else l = mid + 1;
	}
	return ans;
}

