	for (int i = 1; i <= m; ++i) p[i].x = hs(tbX, p[i].x), p[i].y = hs(tbY, p[i].y);
	h = hs(tbX, h); w = hs(tbY, w);
	sort(p + 1, p + m + 1);
	int ret = 0;
	memset(C, 0x80, sizeof(C)); add(1, 0);
	for (int i = 1; i <= m; ++i) {
		f[i] = gmx(p[i].y - 1) + 1; add(p[i].y, max(f[i], 0)); ret = max(ret, f[i]); 
	} 
	return printf("%.10lf\n", 100.0 * (tbX[h] + tbY[w]) - ret * (20 - pi * 5) + (m >= min(h, w)) * (pi * 5)), 0;
}

