struct RMQ {
    int n;
    vector<int> data;
    RMQ(int n_=0) {
        n=1;
        while(n<n_) n<<=1;
        data.resize(n<<1,0);
    }
    void update(int i,int x) {
        i+=n-1;
        data[i]=x;
        while(i>0) {
            i=(i-1)/2;
            data[i]=max(data[i*2+1],data[i*2+2]);
        }
    }
    int getmax(int a,int b) {
        return getmax(a,b,0,0,n);
    }
    int getmax(int a,int b,int k,int l,int r) {
        if(r<=a or b<=l) return 0;
        if(a<=l and r<=b) return data[k];
        int ml=getmax(a,b,k*2+1,l,(r+l)/2);
        int mr=getmax(a,b,k*2+2,(r+l)/2,r);
        return max(ml,mr);
    }
};

