		cin>>x>>y;
		f[x]=y;
	}


	if(py1>py2){
		swap(py1,py2);
		swap(px1,px2);
	}

	duz=abs(px2-px1)+py2-py1;

	vector < lolo > lcs(2e5+5,1e9);
	lcs[0]=0;
	lolo lcsl=0;

	for(int i=px1;i!=px2;i+= (px1<px2) ? 1 : -1){
		if(i==px1 or i==px2)continue;
		if(py1<=f[i] and f[i]<=py2){
			auto it = lower_bound(lcs.begin(), lcs.end(), f[i]);
			lolo ind = it - lcs.begin();
			lcs[ind]=f[i];
			lcsl=max(lcsl,ind);
		}
	}

	//printf("duz=%lld lcsl=%lld \n",duz,lcsl);

	if(min(abs(px1-px2),py2-py1)+1==lcsl){
		cout<< duz*100 - (20-5*pi)*(lcsl-1) - (20 - 10*pi) << endl ;
	}
	else{
		cout<< duz*100 - (20-5*pi)*lcsl << endl;
	}

	return 0;
}

