using namespace std;
const int maxn=2e5+100;
const long double Pi=acos((long double)-1.0);
struct point {
  int x,y;
  bool operator<(const point &u) const{
    return x<u.x;
  }
};
point p[maxn];
void read(point &u){
  scanf("%d %d",&u.x,&u.y);
}

bool ok(point u,point v,point x){
  int mmx=min(u.x,v.x),mxx=max(u.x,v.x),mmy=min(u.y,v.y),mxy=max(u.y,v.y);
  return (x.x>=mmx && x.x<=mxx && x.y>=mmy && x.y<=mxy);
}
int f[maxn],a[maxn];
map<int,int> ma;
int mx[maxn*4],ql,qr;
void build(int o,int l,int r){
  mx[o]=0;
  if (l>=r) return;
  else {
     int mid=(l+r)>>1;
     build(o<<1,l,mid);
     build(o<<1|1,mid+1,r);
  }
}
void update(int o,int l,int r,int x){
  if (ql<=l && r<=qr){
    mx[o]=max(mx[o],x);
  } else {
    int mid=(l+r)>>1;
    if (ql<=mid) update(o<<1,l,mid,x);
    if (qr>mid) update(o<<1|1,mid+1,r,x);
    mx[o]=max(mx[o<<1],mx[o<<1|1]);
  }
}

int query(int o,int l,int r){
  if (ql<=l && r<=qr) return mx[o];
  else {
    int mid=(l+r)>>1;
    int ans=0;
    if (ql<=mid) ans=max(ans,query(o<<1,l,mid));
    if (qr>mid) ans=max(ans,query(o<<1|1,mid+1,r));
    return ans;
  }
}
int main()
{
    int i,j,n,cnt=0;
    point u,v;
    read(u);read(v);
    if (u.y>v.y) swap(u,v);
    cin>>n;
    for (i=1;i<=n;i++){
       read(p[cnt]);
       if (ok(u,v,p[cnt])) cnt++;
    }
    sort(p,p+cnt);
    if (u.y==v.y) {
        if (cnt) {
          long double ans=1ll*abs(u.x-v.x)*100-20+Pi*10;
          cout << setprecision(25) << ans <<endl;
        }
        else cout << setprecision(25) << 1ll*abs(u.x-v.x)*100 <<endl;
    } else {
      long double ans=1ll*abs(u.x-v.x)*100+1ll*abs(u.y-v.y)*100;
      if (u.x>v.x) reverse(p,p+cnt);
      for (i=0;i<cnt;i++) a[i]=p[i].y;
      sort(a,a+cnt);ma.clear();
      for (i=0;i<cnt;i++) ma[a[i]]=i+1;
      build(1,1,cnt);
      int k=0,k2;
      for (i=0;i<cnt;i++){
        ql=1;qr=ma[p[i].y];
        f[i]=query(1,1,cnt)+1;
        if (f[i]>k){k2=k;k=f[i];}
        ql=qr;
        update(1,1,cnt,f[i]);
      }
      ans=ans+(Pi*5-20)*k;
      if (k==abs(u.x-v.x)+1 || k==abs(u.y-v.y)+1) {
        ans=ans-(Pi*5-20)-20+10*Pi;
      }
      cout << setprecision(30) << ans <<endl;
    }
    return 0;
}

