const int MAXN=2e5+2+5;
const int MAXX=1e8+1+8;
const double PI = 3.141592653589793238462;
const double GAIN=20-2*PI*10/4;
const double LOSS=2*PI*10/2-20;

int x1,y1,x2,y2;
int N;
int X[MAXN], Y[MAXN];

int st[2*MAXX];
void update(int i, int v) {
        for (st[i += MAXX] = v; i>1; i>>=1)
                st[i>>1] = max(st[i],st[i^1]);
}

int query(int a, int b) {
        if (a > b) swap(a,b);
        b++;
        int res=0;
        for (a+=MAXX, b+=MAXX; a < b; a>>=1, b>>=1) {
                if (a&1) res = max(res,st[a++]);
                if (b&1) res = max(res,st[--b]);
        }
        return res;
}

int mxtrn() {
        if (x1 > x2) {
                swap(x1,x2);
                swap(y1,y2);
        }

        vector<pii> fountains;
        for (int i=0; i<N; i++)
                fountains.push_back(pii(X[i],i));

        sort(fountains.begin(), fountains.end());

        int i=0;
        while (i < N && fountains[i].first < x1)
                ++i;

        for (; i < N && fountains[i].first < x2; ++i) {
                int cur = fountains[i].second;
                update(Y[cur],1+query(y1,Y[cur]));
        }

        return query(y1,y2);
}

