	int seg[SIZE*2];
	void init(){
		for(int i=0;i<SIZE*2;i++)seg[i]=0;
	}
	void update(int k,int x){
		k+=SIZE-1;
		seg[k]=max(seg[k],x);
		while(k){
			k=(k-1)/2;
			seg[k]=max(seg[k*2+1],seg[k*2+2]);
		}
