    for(int i=1;i<=Size;i++)
    {
        Pos=D[i];
        Val=0;
        Query(1,1,MaxN);
        Max=max(Max,++Val);
        Update(1,1,MaxN);
    }
    if(Max<=min(x2-x1,y2-Y1))
        printf("%.12f",100.0*(x2-x1+y2-Y1)+Max*(5.0*pi-20.0));
    else printf("%.12f",100.0*(x2-x1+y2-Y1)+Max*(5.0*pi-20.0)+5.0*pi);
