  vector<int> val;
  if (s.second > t.second) reverse(a.begin(), a.end());
  for (int i = 0; i < n; i++) {
    if (s.first <= a[i].first && a[i].first <= t.first && (
      (s.second <= a[i].second && a[i].second <= t.second)
    ||(t.second <= a[i].second && a[i].second <= s.second)
    )) {
      val.push_back(a[i].second);
    }
  }
  vector<int> srd = val;
  int sz = val.size();
  sort(srd.begin(), srd.end());
  map<int, int> mp;
  for (int i = 0; i < sz; i++) mp[srd[i]] = i;
  segment_tree<int> sgt(sz, [](int a, int b) { return max(a, b); }, 0);
  for (int i = 0; i < sz; i++) {
    sgt.update(mp[val[i]], sgt.find(0, mp[val[i]]) + 1);
  }
  double pi = acos(0) * 2;
