	scanf("%d%d%d%d", &xs, &ys, &xf, &yf);
	if (xs > xf) {
		swap(xs, xf);
		swap(ys, yf);
	}

	scanf("%d", &n);
	for (int i = 0; i < n; ++i) {
		scanf("%d%d", &a[i].f, &a[i].s);
		b[i] = a[i].s;
	}

	if (ys == yf || xs == xf) {
		double res = 100.0 * (abs(xf - xs) + abs(yf - ys));
		for (int i = 0; i < n; ++i) {
			if (!in(a[i].f, xs, xf)) continue;
			if (!in(a[i].s, ys, yf)) continue;
			res += pi * 10 - 20;
		}
		printf("%.15f\n", res);
		return 0;
	}

	for (int i = 0; i + 1 < n; ++i) {
		if (!in(a[i].f, xs, xf)) continue;
		if (!in(a[i].s, ys, yf)) continue;
		if (!in(a[i + 1].f, xs, xf)) continue;
		if (!in(a[i + 1].s, ys, yf)) continue;
		if (a[i].f < a[i + 1].f && ((ys < yf && a[i + 1].s - a[i].s == 1) || (ys > yf && a[i].s - a[i + 1].s == 1)) && a[i + 1].s == yf) add[i] = pi * 10 - 20;
		if (a[i].f + 1 == a[i + 1].f && ((ys < yf && a[i].s < a[i + 1].s) || (ys > yf && a[i].s > a[i + 1].s)) && a[i + 1].f == xf) add[i] = pi * 10 - 20;
//		cout << i << ' ' << a[i].f << ' '<<a[i].s << ' ' << add[i] << endl;
	}

	sort(a, a + n);
	sort(b, b + n);
	m = unique(b, b + n) - b;

	double res = 1e15;
	int k = 0;
	for (int i = 0; i < n; ++i) {
		if (a[i].f == xf || a[i].s == yf) continue;
		if (!in(a[i].f, xs, xf)) continue;
		if (!in(a[i].s, ys, yf)) continue;
		++k;
		int y = lower_bound(b, b + m, a[i].s) - b;
		if (ys < yf)
			d[i] = get(0, y).val + 1;
		else
			d[i] = get(y, m - 1).val + 1;
		update(y, y, d[i]);
		res = min(res, add[i] + 100.0 * (abs(xf - xs) + abs(yf - ys)) - d[i] * (20.0 - pi * 5));
	}

	if (!k) res = 100.0 * (abs(xf - xs) + abs(yf - ys));

	printf("%.15f\n", res);

	return 0;
}

