	if(y1<y2) Case=1;else Case=0;
	for(int i=l;i<=r;i++)
	  if(a[i].useful)
	  {
		f[i]=1;
		int tmp;
		if(Case) tmp=ask(1,a[i].y-1,1,tot,1);
		else tmp=ask(a[i].y+1,tot,1,tot,1);
		f[i]=max(f[i],tmp+1);
		add(a[i].y,1,tot,1,f[i]);
	  }
	for(int i=l;i<=r;i++)
	  num=max(num,f[i]);
	ans-=num*(20.0-5.0*pi);
	printf("%.15lf",ans);
	return 0;
}

