      if( x1 > x2 ) {
         std::swap(x1, x2);
         std::swap(y1, y2);
      }
      if( y1 > y2 ) {
         y1 *= -1;
         y2 *= -1;
         for(long i = 0; i < n; ++i) {
            ys[i] *= -1;
         }
      }
      std::vector<std::pair<long, long>> ws;
      for(long i = 0; i < n; ++i) {
         if( x1 <= xs[i] and xs[i] <= x2 and y1 <= ys[i] and ys[i] <= y2 ) {
            ws.push_back(std::make_pair(ys[i], xs[i]));
         }
      }
      std::sort(ws.begin(), ws.end());
      std::set<long> set;
      for(auto yx : ws) {
         long x, y; std::tie(y, x) = yx;
         auto ite = set.upper_bound(x);
         if( ite == set.end() ) {
            set.insert(x);
         }
         else {
            set.erase(ite);
            set.insert(x);
         }
