int main() {
	long double x1,y1,x2,y2;
	scanf("%Lf%Lf%Lf%Lf", &x1, &y1, &x2, &y2);
	if (x1>x2) {
		swap(x1,x2);
		swap(y1,y2);
	}
	int n;
	scanf("%d", &n);
	vector<pair<long double, long double> > v;
	bool FLAG=false;
	for (int i=0; i<n; i++) {
		long double x, y;
		scanf("%Lf%Lf", &x, &y);
		if (x1<=x && x<=x2) {
			if (y1==y2) FLAG=true;
			if (y1<=y2 && y1<=y && y<=y2) {
				FLAG|=x1==x2;
				v.push_back({x,y});
			}
			if (y2<=y1 && y2<=y && y<=y1) {
				FLAG|=x1==x2;
				v.push_back({x,y});
			}
		}
	}
	sort(v.begin(), v.end());
	vector<pair<long double, long double> > vl;
	if (y1<=y2) {
		for (int i=0; i<v.size(); i++) {
		if (vl.empty()||v[i].second>vl.back().first) vl.push_back({v[i].second,v[i].first});
		else {
			int loc=lower_bound(vl.begin(),vl.end(),make_pair(v[i].second,(long double)0))-vl.begin();
			vl[loc].first=v[i].second;
			vl[loc].second=v[i].first;
		}
	}
}
else {
	for (int i=0; i<v.size(); i++) {
		if (vl.empty()||-v[i].second>vl.back().first) vl.push_back({-v[i].second,v[i].first});
		else {
			int loc=lower_bound(vl.begin(),vl.end(),make_pair(-v[i].second,(long double)-1e8))-vl.begin();
			vl[loc].first=-v[i].second;
			vl[loc].second=v[i].first;
		}
	}
}
	if (vl.size()>=2) {
		if (abs(vl[vl.size()-1].first)==y2 && abs(vl[vl.size()-2].first-y2)==1) FLAG=true;
		if (vl[vl.size()-1].second==x2 && abs(vl[vl.size()-2].second-x2)==1) FLAG=true;
	}
	//printf("%d\n", vl.size());
	long double ans=(long double)(abs(x2-x1)+abs(y2-y1))*(long double)100;
	if (!FLAG) ans+=(long double)(PI*5.0-20.0)*(long double)vl.size();
	if (FLAG) ans+=(PI*10.0-20.0);
	printf("%.12Lf\n", ans);
}

