  bool x2contains=f.back().first==x2;
  {
    i8t x=-1;i8t prevx=x1-1;
    for(auto& xy:f){if(xy.first>prevx+1)x+=2;else x++;prevx=xy.first=x;}
    x2=x2contains?x:x+1;
  }

  double const PI=3.14159265358979323846264338327950;
  double const delta_curve=10*(PI/2-2); // toku
  double const delta_pass=10*(PI-2); // son

  i8t x=0;
  // 初期化
  std::vector<double> T(y2+1, 0.0);
  if(x1contains){
    i8t y=f[0].second;
    T[y]=delta_curve;
    for(y++;y<T.size();y++)
      T[y]=delta_pass;
    x++;
  }

  int ix=0;
