struct point {
  int x, y;
  point() {}
  point(int a, int b) {
    x = a; y = b;
  }
};

void swap(point &a, point &b) {
  int temp = a.x;
  a.x = b.x;
  b.x = temp;
  temp = a.y;
  a.y = b.y;
  b.y = temp;
}

bool cmp (point a, point b) {
  if (a.x == b.x) {
    return a.y < b.y;
  }
  return a.x < b.x;
}

double ans = 0;

void printans() {
  cout << fixed << setprecision(15) << ans << endl;
  exit(0);
}

point p1, p2;
point ar[N];
