  scanf("%lld %lld", &a, &b);
  p2 = point(a, b);
  int n; scanf("%lld", &n);
  for (int i = 1; i <= n; i++) {
    scanf("%lld %lld", &a, &b);
    if (a < min(p1.x, p2.x) || a > max(p2.x, p1.x) || b < min(p1.y, p2.y) || b > max(p1.y, p2.y)) {
      n--;
      i--;
      continue;
    }
    ar[i] = point(a, b);
  }
  sort(ar + 1, ar + n + 1, cmp);
  for (int i = 0; i < N; i++)  {
    dp[i] = inf;
  }
  dp[0] = -inf;
  for (int i = 1; i <= n; i++) {
    int pos = lower_bound(dp, dp + N, ar[i].y) - dp;
    if (dp[pos + 1] == inf)
      dp[pos] = ar[i].y;
  }
  int val = N - 1;
//  cout << p1.x << ' ' << p2.x << endl;
  while (dp[val] == inf) val--;
  ans = 100 * (abs(p2.x - p1.x) + abs(p2.y - p1.y)) - 20 * val + val * pi * 5;
  if (val == min(abs(p2.x - p1.x), abs(p2.y - p1.y)) + 1) {
    ans -= pi * 5;
    ans += 10 * pi;
  }
  printans();
}

