typedef long long LL;
typedef pair<int, int> pii;

const int MAXN = (int) 2e5;

int X0, X1, Y0, Y1;

struct point
{
	int x, y;

	inline bool operator < (const point &rhs) const { return this->x < rhs.x; }

	point() { }
	point(int _x, int _y): x(_x), y(_y) { }
};

vector<point> P;

inline void input()
{
	X0 = read<int>(), Y0 = read<int>(), X1 = read<int>(), Y1 = read<int>();
	if(X0 > X1) swap(X0, X1), swap(Y0, Y1);
	for(int n = read<int>(); n--; )
	{
		int x = read<int>(), y = read<int>();
		if(X0 <= x && x <= X1 && min(Y0, Y1) <= y && y <= max(Y0, Y1)) P.emplace_back(x, y);
	}
	sort(ALL(P));
}

inline int get_LIS()
{
	static int seq[MAXN + 5], len;

	len = 0;
	for(auto i : P)
	{
		int p = lower_bound(seq + 1, seq + len + 1, i.y) - seq;
		seq[p] = i.y;
		chkmax(len, p);
	}
	return len;
}

inline void solve()
{
	if(Y0 > Y1) for(int i = 0; i < SZ(P); ++i) P[i].y *= -1;

	const double PI = acos(-1), delta = 5 * PI - 20;
	int m = get_LIS();

	double ans = (abs(X0 - X1) + abs(Y0 - Y1)) * 100;
	ans += m * delta;
	if(m == abs(X0 - X1) + 1 || m == abs(Y0 - Y1) + 1) ans += 5 * PI;
	printf("%.11lf\n", ans);
}

