		vector<pair<int,int> > p;
		for(int i = 0; i < n; i++) if(x[i] >= 0 && y[i] >= 0 && x[i] <= tx && y[i] <= ty) p.push_back({x[i], y[i]});
		sort(p.begin(), p.end());
		int fnt = 0;
		for(auto e : p){
			int x, y; tie(x, y) = e;
			int best = sum(y);
			add(y, best + 1);
			fnt = max(fnt, best + 1);
		}
		cout << (tx + ty) * 100 - fnt * 20 + fnt * 5 * pi << endl;
	}
	return 0;
}

