//Longest Increasing Subsequence
class LIS {
  vll result;
  int n;
public:
  LIS(vll a) {
    result = {};
    Loop(i, a.size()) {
      auto itr = lower_bound(result.begin(), result.end(), a[i]);
      if (itr == result.end()) {
        result.push_back(a[i]);
      }
      else *itr = a[i];
    }
    n = result.size();
    result = {};
    Loop(i, a.size()) {
      auto itr = lower_bound(result.begin(), result.end(), a[i]);
      if (itr == result.end()) {
        result.push_back(a[i]);
        if (result.size() == n) break;
      }
      else *itr = a[i];
    }
  }
  vll get_lis() {
    return result;
  }
  int get_lisn() {
    return n;
  }
};

int main() {
  ll x1, y1, x2, y2; cin >> x1 >> y1 >> x2 >> y2;
  if (x2 < x1) {
    swap(x1, x2);
    swap(y1, y2);
  }
  int n; cin >> n;
  double quarter = M_PI * 5;
  double ans = 0;
  if (x1 == x2) {
    if (y2 < y1) swap(y1, y2);
    int flag = 0;
    Loop(i, n) {
      ll x, y; cin >> x >> y;
      if (x == x1) {
        if (y1 < y && y < y2) flag = 1;
      }
    }
    ans = (y2 - y1) * 100 + flag * (quarter - 10) * 2;
  }
  else if (y1 == y2) {
    if (x2 < x1) swap(x1, x2);
    int flag = 0;
    Loop(i, n) {
      ll x, y; cin >> x >> y;
      if (y == y1) {
        if (x1 < x && x < x2) flag = 1;
      }
    }
    ans = (x2 - x1) * 100 + flag * (quarter - 10) * 2;
  }
  else {
    map<ll, ll> mp;
    Loop(i, n) {
      ll x, y; cin >> x >> y;
      if (y1 < y2) {
        if (x1 <= x && x <= x2 && y1 <= y && y <= y2) {
          mp[x] = y;
        }
      }
      else {
        if (x1 <= x && x <= x2 && y2 <= y && y <= y1) {
          mp[x] = y * -1;
        }
      }
    }

    vll a;
    for (auto itr = mp.begin(); itr != mp.end(); ++itr) {
      a.push_back(itr->second);
    }
    LIS lis(a);
    vll result = lis.get_lis();
    if (mp[x1] == result[0] && mp[x2] == result.back()) {
      ans = (x2 - x1 + abs(y2 - y1)) * 100 + (quarter - 20)*(lis.get_lisn() - 1) + (quarter - 10) * 2;
    }
    else {
      ans = (x2 - x1 + abs(y2 - y1)) * 100 + (quarter - 20)*lis.get_lisn();
    }
  }
  cout << setprecision(18) << ans << endl;
  return 0;
}

