	FOR(i,N) {
		cin>>XX[i]>>YY[i];
		if(XX[i]<min(X1,X2) || XX[i]>max(X1,X2) || YY[i]<min(Y1,Y2) || YY[i]>max(Y1,Y2)) i--,N--;
	}

	X2-=X1;
	Y2-=Y1;
	FOR(i,N) {
		XX[i]-=X1;
		if(X2<0) XX[i]=-XX[i];
		YY[i]-=Y1;
		if(Y2<0) YY[i]=-YY[i];
	}
	if(X2<0) X2=-X2;
	if(Y2<0) Y2=-Y2;

	double ret;

	if(X2==0) {
		ret=100.0*Y2+N*d2;
	}
	else if(Y2==0) {
		ret=100.0*X2+N*d2;
	}
	else if(N) {
		vector<pair<int,int>> V;
		vector<int> V2;
		FOR(i,N) V.push_back({XX[i],YY[i]});
		sort(ALL(V));
		FORR(v,V) V2.push_back(v.second);
		auto V3=LIS(V2);

		if(V3.size()==min(X2,Y2)+1) {
			ret=100.0*(X2+Y2)-d1*(V3.size()-1)+d2;
		}
		else {
			ret=100.0*(X2+Y2)-d1*V3.size();
		}

	}
	else {
