int ans, top, lst;
long double add;

int cmpY(const City &a, const City &b)
{
    if (a.y == b.y)
        return a.x < b.x;
    return a.y < b.y;
}

int bs(int x)
{
    int i = 0, p = 1 << 17;
    while (p)
    {
        if (i + p <= top && v[St[i + p]].y <= x)
            i += p;
        p >>= 1;
    }
    return i + 1;
}
void compSol()
{
    City prv = fi;
    v[0] = st;
    for (int i = lst; i > 0;)
    {
        if ((i == lst || pos[i] == 0) && ((v[i].x == v[pos[i]].x && prv.x == v[i].x) || (v[i].y == v[pos[i]].y && prv.y == v[i].y)))
            add += (long double)5.0 * pi;
        prv = v[i];
        i = pos[i];
    }
}
void reduc()
{
    sort(v + 1, v + n + 1, cmpY);
    for (int i = 1; i <= n; ++ i)
        if (v[i].y != v[i - 1].y || i == 1)
        {
            int j = i;
            while (j < n && v[j + 1].y == v[i].y)
                ++ j;
            if (j != i)
                v[++ N] = v[j - 1];
                    v[++ N] = v[j];
            i = j;
        }
    n = N;
    N = 0;
    sort(v + 1, v + n + 1);
    for (int i = 1; i <= n; ++ i)
        if (v[i].x != v[i - 1].x || i == 1)
        {
            int j = i;
            while (j < n && v[j + 1].x == v[i].x)
                ++ j;
            if (j != i)
                v[++ N] = v[j - 1];
                    v[++ N] = v[j];

            i = j;
        }
    n = N;
}
