bool cmp(const int &o,const int &p){
    if(x[o] == x[p])return y[o] < y[p];
    return x[o] < x[p];
}
void build(int o,int L,int R){
    tr[o] = 1e18;
    if(L == R)return;
    build(ls,L,mid);
    build(rs,mid + 1,R);
}

void update(int o,int L,int R,int pos,long double val){
    //cout << o <<" "<<L<<" "<<R<<endl;
    if(L == R){
        tr[o] = val;
        return;
    }
    if(pos <= mid){
        update(ls,L,mid,pos,val);
    }else{
        update(rs,mid + 1,R,pos,val);
    }
    tr[o] = min(tr[ls],tr[rs]);
}
long double Q(int o,int L,int R,int l,int r){
    if(l > r) return 1e18;
    if(l <= L && R<= r)return tr[o];
    long double res = 1e18;
    if(l <= mid){
        res = min(res,Q(ls,L,mid,l,r));
    }
    if(r > mid){
        res = min(res,Q(rs,mid +1,R,l,r));
    }
    return res;
}
