const double PI = acos(-1);

int sx, sy, tx, ty;
int N;
int X[200111], Y[200111];
int lis[200111];

void MAIN() {
    scanf("%d%d%d%d", &sx, &sy, &tx, &ty);
    scanf("%d", &N);
    REP (i, N) scanf("%d%d", X+i, Y+i);

    if (sx > tx) {
	swap(sx, tx);
	swap(sy, ty);
    }
    if (sy > ty) {
	sy = -sy;
	ty = -ty;
	REP (i, N) Y[i] = -Y[i];
    }
    tx -= sx;
    ty -= sy;
    REP (i, N) {
	X[i] -= sx;
	Y[i] -= sy;
    }
    sx = sy = 0;

    if (ty < tx) {
	swap(tx, ty);
	REP (i, N) swap(X[i], Y[i]);
    }

    double ans = (tx + ty) * 100.0;
    vector<pair<int, int> > v;
    REP (i, N) if (sy <= Y[i] && Y[i] <= ty && sx <= X[i] && X[i] <= tx) {
	v.emplace_back(X[i], Y[i]);
    }

    sort(v.begin(), v.end());

    memset(lis, 0x3f, sizeof lis);
    EACH (e, v) {
	*lower_bound(lis, lis+N, e->second) = e->second;
    }
    int len = lower_bound(lis, lis+N, lis[N]) - lis;

    if ((int)v.size() == len && tx + 1 == len) {
	ans += (len-1.0) * (5*PI - 20) + (10*PI - 20); 
    } else {
	ans += len * (5*PI - 20);
    }

    printf("%.20f\n", ans);
}

