int main() {
	int N;
	Point S, G;
	vector<Point> point;
	vector<long long> table;

	cin >> S.x >> S.y >> G.x >> G.y;
	cin >> N;
	for (int i = 0; i < N; i++) {
		Point p;
		cin >> p.x >> p.y;
		point.push_back(p);
	}

	if (G < S)swap(S, G);
	sort(point.begin(), point.end());

	vector<Point>::iterator begin = lower_bound(point.begin(), point.end(), S);
	vector<Point>::iterator end = upper_bound(point.begin(), point.end(), G);

