		if (G.x < S.x) {
			if (S.x < begin->x || begin->x < G.x) {
				begin++; 
				continue;
			}
		}
		else {
			if (S.x > begin->x || begin->x > G.x) {
				begin++;
				continue;
			}
		}
		long long x = abs(begin->x - S.x);
		vector<long long>::iterator it = lower_bound(table.begin(), table.end(), x);
		if (it == table.end()) {
			table.push_back(x);
		}
		else {
			*it = x;
		}
		begin++;
	}

