			if (x >= abs(G.x - S.x))continue;
			x = table[i] + 1;
			dif +=  20.0 - QUA;
		}
		len -= dif;
	}
	cout << fixed;
	cout << setprecision(15) << len << endl;


	cout << len << endl;
	cout << table.size() << endl;

	return 0;
}

