int s[N], dp[N];;

int get(int x ) {
	int r = 0;
	while (x >= 0) {
		r = max(r, s[x]);
		x = (x & (x + 1)) - 1;
	}
	return r;
}

void add(int x, int v) {
	while (x < w.size()) {
		s[x] = max(s[x], v);
		x |= x + 1;
	}
}

