} arr[200005]; 
int mx[200005], n, app[200005]; 
inline void modify(int pos, int x)
{
	for (; pos <= n; pos += pos & -pos)
		mx[pos] = max(mx[pos], x); 
}
inline int query(int pos)
{
	int res = 0; 
	for (; pos; pos -= pos & -pos)
		res = max(res, mx[pos]); 
	return res; 
}
int main()
{
	// freopen("AGC019-C.in", "r", stdin); 
	int stx, sty, enx, eny; 
	scanf("%d%d%d%d%d", &stx, &sty, &enx, &eny, &n);
	bool f = false; 
	if (stx > enx)
	{
		swap(stx, enx); 
		swap(sty, eny); 
	}
	if (sty > eny)
	{
		sty = 1e8 - sty; 
		eny = 1e8 - eny; 
		f = true; 
	}
	for (int i = 0; i < n; i++)
	{
		scanf("%d%d", &arr[i].x, &arr[i].y); 
		if (f)
			arr[i].y = 1e8 - arr[i].y; 
		if (arr[i].x < stx || arr[i].x > enx || arr[i].y < sty || arr[i].y > eny)
		{
			i--; 
			n--; 
		}
		app[i] = arr[i].y; 
	}
	sort(app, app + n); 
	for (int i = 0; i < n; i++)
		arr[i].y = lower_bound(app, app + n, arr[i].y) - app + 1; 
	sort(arr, arr + n); 
	int ans = 0; 
	for (int i = 0; i < n; i++)
	{
		int res = query(arr[i].y) + 1; 
		modify(arr[i].y, res); 
		ans = max(ans, res); 
	}
	int s = enx - stx + eny - sty, p = ans, q = 0; 
	if (p == min(enx - stx, eny - sty) + 1)
	{
		p--; 
		q++; 
	}
	printf("%.15lf\n", (double)s * 100 - (20 - 5 * acos(-1.0)) * p + (10 * acos(-1.0) - 20) * q);
	return 0; 
}

