  cin >> x1 >> y1 >> x2 >> y2 >> n;
  if(x1 > x2) {
    swap(x1, x2);
    swap(y1, y2);
  }
  if(y1 > y2) {
    y1 = INF - y1;
    y2 = INF - y2;
    flip = true;
  }
