  for(int i = 0; i < n; ++i) {
    cin >> xp >> yp;
    if(flip)
      yp = INF - yp;
    if(x1 <= xp && xp <= x2 && y1 <= yp && yp <= y2)
      v[n2++] = make_pair(xp, yp);
  }

  sort(v, v + n2, cmp);

