int BIT[MAXF];
void upd(int x, int v){
	int c = x;
	while(c < MAXF){
		BIT[c] = max(BIT[c], v);;
		c += c & -c;
	}	
}

int q(int x){
	int c = x;
	int a = 0;
	while(c > 0){
		a = max(a, BIT[c]);
		c -= c & -c;
	}
	return a;
}

