{
    int lw=1,hi=S2,mid;
    while(lw<=hi)
    {
        mid=(lw+hi)>>1;
        if(S[mid]>val)
            hi=mid-1;
        else if(S[mid]<val)
            lw=mid+1;
        else return mid;
    }
}
