        dbl ans = 100.0 * (X2 - X1);
        rep(i, N) {
            int x, y;
            cin >> x >> y;
            if (y == Y1 && X1 < x&&x < X2)ans += 11.415926535897938;
        }
        cout << ans << endl;
    } else {
        vi xs;
        vector<pii> p;

        // X1->X2
        if (X1 > X2) {
            swap(X1, X2);
            swap(Y1, Y2);
        }

        int miy = min(Y1, Y2), may = max(Y1, Y2);
        // Y1<Y2 or Y1>Y2 増加列、減少列
        rep(i, N) {
            int x, y;
