const double PAI = 3.141592653589793238;

void update() {
	if (sx == gx || sy == gy) return;
	if (p.size() <= 1) return;
	if (p[0].first != sx || p[p.size() - 1].first != gx) return;
	if (p[p.size() - 2].first != gx - 1) return;

	//p[p.size() - 2]を削除
	vector<P> Q;
	for (int i = 0; i < p.size(); i++) {
		if (i == (int)p.size() - 2) continue;
		Q.push_back(p[i]);
	}

	p.clear();
	for (int i = 0; i < Q.size(); i++) {
		p.push_back(Q[i]);
	}
}

signed main()
{
	int i;

	cin >> sx >> sy >> gx >> gy;
	cin >> n;
	for (i = 0; i < n; i++) cin >> x[i] >> y[i];

	if (sx > gx) { swap(sx, gx); swap(sy, gy); }
	if (sy > gy) {
		sy *= -1;
		gy *= -1;
		for (i = 0; i < n; i++) { y[i] *= -1; }
	}

	for (i = 0; i < n; i++) {
		if (sx <= x[i] && x[i] <= gx && sy <= y[i] && y[i] <= gy) {
			p.push_back(P(x[i], y[i]));
		}
	}
	sort(p.begin(), p.end());

	update();

	//LIS
	int INF = 1145141919810;
	for (i = 0; i <= n + 1; i++) dp[i] = INF;
	dp[0] = 0;
	for (i = 0; i < p.size(); i++) {
		dp[upper_bound(dp, dp + n + 1, p[i].second) - dp] = p[i].second;
	}
	for (i = n; i > 0; i--) {
		if (dp[i] < INF) break;
	}

	//LISの長さ
	int Count = i;

	//場合分け
	double ans;

	if (sx == gx) {
		ans = (gy - sy) * 100 + Count * (PAI - 2) * 10;
	}

	else if (sy == gy) {
		ans = (gx - sx) * 100 + Count * (PAI - 2) * 10;
	}

	else {
		ans = (gy - sy + gx - sx) * 100 - Count * (2 - PAI / 2) * 10;
		//assert(0);
	}

	printf("%.20Lf\n", ans);
	return 0;
}

