using namespace std;
const int Max_N(200050);
const double PI(acos(-1.0));
const double _0(100.0);
const double _180(10.0 * PI - 20.0);
const double _90(5.0 * PI - 20.0);

struct point
{
	int x, y;
	inline bool comp(const point &b) const
	{
		return x < b.x;
	}
};
int N, F[Max_N], LIS;
point S, T, V[Max_N];
map<int, int> P;
double Ans;

/*
通过一些翻转操作，使得起点在终点的左下角。特判掉一些特殊情况 
把一条路径写出来，答案 = 经过的边数 * 100 + 180度横向穿过的喷泉 * (10PI - 20) + 90度绕过去的喷泉 * (5PI - 20)
容易发现，min{经过的边数} = (TX - SX) + (TY - SY)。同时，为了避开180度横向穿过的喷泉而增加经过的边数显然是不优的
所以就是考虑最大化90度绕过去的喷泉个数和最小化180度横向穿过的喷泉个数
考虑求出点的LIS，显然最多90度绕过去LIS次喷泉，同时有LIS <= min(TX - SX, TY - SY) + 1。分情况讨论：
(1)LIS = min(TX - SX, TY - SY) + 1，可以走90度绕过去LIS - 1次喷泉，且180度横向穿过1个喷泉
   因为无论怎么走一定会180度横向穿过至少1个喷泉，所以这个方案达到了最优解
(2)LIS <= min(TX - SX, TY - SY)，那么可以90度绕过去LIS次喷泉同时不180度横向穿过任何1个喷泉，达到了最优解 
*/

int main()
{
	scanf("%d%d%d%d", &S.x, &S.y, &T.x, &T.y);
	scanf("%d", &N);
	for (int i = 1;i <= N;++i)
		scanf("%d%d", &V[i].x, &V[i].y);
	if (S.x > T.x)
		swap(S, T);
	if (S.y > T.y)
	{
		S.y = 100000000 - 1 - S.y, T.y = 100000000 - 1 - T.y;
		for (int i = 1;i <= N;++i)
			V[i].y = 100000000 - 1 - V[i].y;
	}
	for (int i = 1;i <= N;++i)
		if (S.x <= V[i].x && V[i].x <= T.x && S.y <= V[i].y && V[i].y <= T.y)
			P[V[i].x] = V[i].y;
	memset(F, 0X3F, sizeof(F)), F[0] = -0X3F3F3F3F;
	for (map<int, int>::iterator it = P.begin();it != P.end();++it)
	{
		int l = 0, r = N, mid;
		while (l < r)
		{
			mid = l + ((r - l) >> 1);
			if (F[mid] < it -> second)
				l = mid + 1;
			else
				r = mid;
		}
		F[l] = it -> second, LIS = max(LIS, l);
	}
	Ans = (T.x - S.x + T.y - S.y) * _0;
	if (LIS == min(T.x - S.x, T.y - S.y) + 1)
		--LIS, Ans += _180;
	Ans += LIS * _90;
	printf("%.12lf", Ans);
	return 0;
}

