void solve(){
  #define x first
  #define y second
  P s,g; in(s , g);
  ini(N);
  vp v(N); in(v);
  if(s.x > g.x) swap(s , g);
  if(s.y > g.y){
    s.y *= -1 , g.y *= -1;
    each(p , v) p.y *= -1;
  }

  {
    vp a;
    each(p , v){
      if(s.x <= p.x && p.x <= g.x && s.y <= p.y && p.y <= g.y) a.pb(p);
    }
    v.swap(a);
  }

  if(s.x == g.x){
    int cnt = 0;
    each(p , v){
      if(p.x == s.x) cnt++;
    }
    die((g.y - s.y) * 100.0 + tapi);
  }
  if(s.y == g.y){
    int cnt = 0;
    each(p , v){
      if(s.y == p.y) cnt++;
    }
    die((g.x - s.x) * 100.0 + tapi);
  }

  // 
  P init = P(infLL,infLL) , minit = P(-infLL , -infLL);
  P a = init , b = init , c = init , d = init;
  {
    vp cur;
    each(p , v){
      if(p.x == s.x) a = p;
      else if(p.x == g.x) c = p;
      else if(p.y == s.y) d = p;
      else if(p.y == g.y) b = p;
      else cur.pb(p);
    }
    cur.swap(v);
  }

  sort(all(v));

  auto f = [&](P ss,P gg) -> int{
    vl dp;
    each(p , v){
      if(ss.x <= p.x && p.x <= gg.x && ss.y <= p.y && p.y <= gg.y){
        auto it = lower_bound(all(dp) , p.y);
        if(it == dp.end()) dp.pb(p.se);
        else *it = p.se;
      }
    }
    return (int)dp.size();
  };

  int ans = f(minit , init);
  if(a != init) amax(ans , 1 + f(a , init));
  if(b != init) amax(ans , 1 + f(minit , b));
  if(c != init) amax(ans , 1 + f(minit , c));
  if(d != init) amax(ans , 1 + f(d , minit));
  if(a != init && b != init)
    amax(ans , 2 + f(a , b));
  if(a != init && c != init)
    amax(ans , 2 + f(a , c));  
  if(d != init && b != init)
    amax(ans , 2 + f(d , b)); 
  if(d != init && c != init)
    amax(ans , 2 + f(d , c));  

  out( (g.x+g.y-s.x-s.y)*100.0 - ans * nya);






}

