struct Fpos{
	int x,y,totFountain,id;
	Fpos(int x,int y,int totFountain) {
		this->x = x;
		this->y = y;
		this->totFountain = totFountain;
	}
	Fpos(int x,int y,int totFountain,int id) {
		this->x = x;
		this->y = y;
		this->totFountain = totFountain;
		this->id = id;
	}
	Fpos() {
		this->x = -1;
		this->y = -1;
		this->totFountain = 0;
	}
};

struct SegmentTree{
	typedef Fpos stt; //change data type here
	static const int MAXN = 4*N;
	stt tree[MAXN];

	stt merge(stt l,stt r)
	{
		if(l.totFountain < r.totFountain) return r;
		return l;
	}
	void build(int node,int start,int endd)
	{
		if(start==endd)
		{
			tree[node] = Fpos(-1,-1,0,start);
			return;
		}

		int mid = (start+endd)>>1;

		build(node<<1,start,mid);
		build((node<<1) + 1,mid+1,endd);

		tree[node] = merge(tree[node<<1],tree[(node<<1)+1]);
	}

	void update(int node,int start,int endd,int idx,stt val)
	{
		if(start==endd)
		{
			tree[node] = val; //increase value type update
			return;
		}

		int mid = (start+endd)>>1;

		if(idx<=mid)
			update(node<<1,start,mid,idx,val);
		else
			update((node<<1)+1,mid+1,endd,idx,val);

		tree[node] = merge(tree[node<<1],tree[(node<<1)+1]);
	}

	stt read(int node,int start,int endd,int l,int r)
	{
		if(start==l && endd==r)
			return tree[node];

		int mid = (start+endd)>>1;

		if(r<=mid)
			return read(node<<1,start,mid,l,r);
		if(l>mid)
			return read((node<<1)+1,mid+1,endd,l,r);

		return merge(read(node<<1,start,mid,l,mid),read((node<<1)+1,mid+1,endd,mid+1,r));
	}
}seg_tree;


