void Upd(int nod, int v){
    while(nod<=n){
        bit[nod]=max(bit[nod],v);
        nod+=(nod&-nod);
    }
}

int Qry(int nod){
    int ans=0;
    while(nod){
        ans=max(ans,bit[nod]);
        nod-=(nod&-nod);
    }
    return ans;
}

