    for(auto&point:pts){
      point.ff = dx - ( point.ff - sx );
    }
  }

  if(sy > dy){
    swap(sy,dy);
    for(auto&point:pts){
      point.ss = dy - ( point.ss - sy );
    }
  }

  for(auto&point:pts){
    point.ff -= sx;
    point.ss -= sy;
  }
  dx -= sx;dy -= sy;

  if(pts.empty()){
    cout << fixed << setprecision(20) << 100.0*(dx+dy) << endl;
    return 0;
  }

  if(dx==0 or dy==0){
    long double ans = 100.0*(dx+dy);
    long double delta = -20.0*pts.size();
    delta += 10*ppi*pts.size();
    cout << fixed << setprecision(20) << ans + delta << endl;
    return 0;
  }

  sort(pts.begin(),pts.end());

  int fts = 0;
  for(int i=0;i<pts.size();){
    int j = i;
    for(;j<pts.size() and pts[i].ff==pts[j].ff;j++);
    reverse(pts.begin()+i,pts.begin()+j);//
    i=j;
  }
  for(auto&point:pts){
    int v = point.ss;
    int mx = T.qry(0,v-1);
    T.upd(v,mx+1);
    fts = max(fts,1+mx);
  }
  //cerr << fts << endl;

  long double dist = 100.0*(dx+dy);
  long double delta = -20.0*fts;
  delta += 5.0*ppi*fts;
  cout << fixed << setprecision(20) << dist + delta << endl;

  return 0;
};

