struct SegTree {
    int size;
    vector<int> seg;

    SegTree(const vector<int>& v) {
        size = 1;
        while (size < v.size()) size <<= 1;
        seg.resize(2 * size);
        for (int i = 0; i < v.size(); i++) {
            seg[i + size] = v[i];
        }
        for (int i = size - 1; i > 0; i--) {
            seg[i] = max(seg[2 * i], seg[2 * i + 1]);
        }
    }

    SegTree(int n) : SegTree(vector<int>(n)) {}

    void update(int k, int x) {
        k += size;
        seg[k] += x;
        k /= 2;
        for (; k > 0; k /= 2) {
            seg[k] = max(seg[2 * k], seg[2 * k + 1]);
        }
    }

    int query(int a, int b, int k, int l, int r) {
        if (b <= l || r <= a) return 0;
        if (a <= l && r <= b) return seg[k];
        int x = query(a,b,2 * k,l,(l + r) / 2);
        int y = query(a,b,2 * k + 1,(l + r) / 2,r);
        return max(x,y);
    }

    int query(int a, int b) {
        return query(a,b,1,0,size);
    }

    void debug() {
        int i;
        REP (i,1,size) printf("%d ",seg[i]);
        puts("");
    }
};

pair<int,int> XY[200000];

constexpr double pi = 2 * acos(0);

int main(void) {
    int x1, y1, x2, y2;
    scanf("%d%d%d%d",&x1,&y1,&x2,&y2);
    if (x1 > x2) swap(x1,x2);
    if (y1 > y2) swap(y1,y2);

    int i, N;
    scanf("%d",&N);
    REP (i,N) scanf("%d%d",&XY[i].first,&XY[i].second);

    unordered_map<int,int> coX, coY;
    set<int> st;
    REP (i,N) st.insert(XY[i].first);
    i = 0;
    for (auto x: st) coX[x] = i++;
    st.clear();
    REP (i,N) st.insert(XY[i].second);
    i = 0;
    for (auto y: st) coY[y] = i++;
    sort(XY,XY+N,
            [](pair<int,int> a, pair<int,int> b) {
                if (a.first == b.first) return a.second > b.second;
                else return a.first < b.first;
            });

    SegTree s(N);
    REP (i,N) if (x1 <= XY[i].first && XY[i].second <= x2 && y1 <= XY[i].second && XY[i].second <= y2) {
        int mx = s.query(0,coY[XY[i].second]);
        s.update(coY[XY[i].second],mx + 1);
    }
    int fountains = s.query(0,coY.size());
    double ans = (x2 - x1 + y2 - y1) * 100;
    ans += fountains * (pi * 5 - 20);
    if (fountains == min(coX[x2] - coX[x1] + 1, coY[y2] - coY[y1] + 1)) ans += pi * 5;
    printf("%.12f\n",ans);
    return 0;
}

