void solve(){
	int sX,sY,gX,gY;
	cin >> sX >> sY >> gX >> gY;
	int N;
	cin >> N;
	int minX,maxX,minY,maxY;
	minX = min(sX,gX);
	maxX = max(sX,gX);
	minY = min(sY,gY);
	maxY = max(sY,gY);
	vector< pair<int,int> > pos;
	pos.reserve(N);
	for(int i=0;i<N;++i){
		int x,y;
		cin >> x >> y;
		if( minX <= x && x <= maxX && minY <= y && y <= maxY){
			pos.push_back( pair<int,int>(x,y) );
		}
	}
	if( sX == gX || sY== gY){
		int s = (maxX-minX) + (maxY-minY);
		LD ans = f(s,0,pos.size());
		cout << ans << endl;
		return;
	}
	int dirX,dirY;
	dirX = (sX<gX)?1:-1;
	dirY = (sY<gY)?1:-1;
	int size = pos.size();
	for(int i=0;i<size;++i){
		pos[i].first *= dirX;
		pos[i].second *= dirY;
	}
	sort(pos.begin(),pos.end());
	vector<int> v(size);
	for(int i=0;i<size;++i){
		v[i] = pos[i].second;
	}
	//LIS
	vector<int> dp(size,INF);
	for(int i=0;i<size;++i){
		*lower_bound(dp.begin(),dp.end(), v[i] ) = v[i];
	}
	int res = lower_bound(dp.begin(),dp.end(),INF) - dp.begin();

	///
	int s = (maxX-minX)+(maxY-minY);
	LD ans;
	if( min(maxX-minX,maxY-minY) < res ){
		ans = f(s,res-1,1);
	}else{
		ans = f(s,res,0);
	}
	cout << ans << endl;
}

