	if(yrev) { y1 *= -1; y2 *= -1; }
	int N;
	cin >> N;
	vector<pair<int, int>> fountains;
	for(int i = 0; i < N; ++i) {
		int X, Y;
		cin >> X >> Y;
		if(xrev) X *= -1;
		if(yrev) Y *= -1;
		if(!(x1 <= X && X <= x2)) continue;
		if(!(y1 <= Y && Y <= y2)) continue;
		fountains.push_back(make_pair(X, Y));
	}
	sort(fountains.begin(), fountains.end());
	if(x1 == x2 || y1 == y2) {
		if(fountains.size() != 0) {
			printf("%.15f\n", ((x2 - x1) + (y2 - y1)) * 100.0 + (10.0 * M_PI - 20.0));
		} else {
			printf("%.15f\n", ((x2 - x1) + (y2 - y1)) * 100.0);
		}
	} else {
		int m = 0;
		int counter = 0;
		for(int i = 0; i < static_cast<int>(fountains.size()) - 1; ++i) {
			if(fountains[i].second < fountains[i + 1].second) {
				++counter;
			} else {
				if(m <= counter) m = counter + 1;
				counter = 0;
			}
		}
		if(m <= counter) m = counter + 1;
		printf("%.15f\n", ((x2 - x1) + (y2 - y1)) * 100.0 - (20.0 - 5.0 * M_PI) * m);
	}
	return 0;
}

