void transf(int n, ll &x1, ll &y1, ll &x2, ll &y2) {
    if (x2 < x1) {
        swap(x1, x2);
        swap(y1, y2);
    }

    if (y2 < y1) {
        fr(i, n)
            a[i].y = M - a[i].y;
        y1 = M - y1;
        y2 = M - y2;
    }
}

bool cmpx(pt a, pt b) {
    return a.x < b.x;
}

ll t[4 * N];

ll get(int v, int tl, int tr, int l, int r) {
    if (tl > r || tr < l) return 0;
    if (l <= tl && tr <= r) return t[v];
    int tm = (tl + tr) / 2;
    return max(get(2 * v, tl, tm, l, r), get(2 * v + 1, tm + 1, tr, l, r));
}

void upd(int v, int tl, int tr, int pos, ll val) {
    if (tl == tr) {
        t[v] = val;
        return;
    }
    int tm = (tl + tr) / 2;
    if (pos <= tm)
        upd(2 * v, tl, tm, pos, val);
    else
        upd(2 * v + 1, tm + 1, tr, pos, val);
    t[v] = max(t[2 * v], t[2 * v + 1]);
}

