		x1 = M - x1;
		x2 = M - x2;
		for(int i = 1 ; i <= n ; ++i){
			arr[i].first = M - arr[i].first;
		}
	}
	if(y1 > y2){
		y1 = M - y1;
		y2 = M - y2;
		for(int i = 1 ; i <= n ; ++i){
			arr[i].second = M - arr[i].second;
		}
	}
