#define MaxN 200005
#define INF 2140000000
#define MOD 1000000007
#define pi 3.1415926535897932384626433832795
#define MaxT 1100005
using namespace std;

int x1,x2,Y1,y2,N,T[MaxT],Pos,Val,D[MaxN],Size=0,S2=0,S[MaxN],Max=0;
bool swaped=false;
pair<int,int> dots[MaxN];
void Update(int node,int Start,int End)
{
    if(Start==End)
        T[node]=Val;
    else
    {
        int mid=(Start+End)>>1;
        if(Pos>mid)
            Update(2*node+1,mid+1,End);
        else Update(2*node,Start,mid);
        T[node]=max(T[2*node],T[2*node+1]);
    }
}
void Query(int node,int Start,int End)
{
    if(End<=Pos)
        Val=max(Val,T[node]);
    else
    {
        int mid=(Start+End)>>1;
        Query(2*node,Start,mid);
        if(mid<Pos)
            Query(2*node+1,mid+1,End);
    }
}
int Search(int val)
{
    int lw=1,hi=S2,mid;
    while(lw<=hi)
    {
        mid=(lw+hi)>>1;
        if(S[mid]>val)
            hi=mid-1;
        else if(S[mid]<val)
            lw=mid+1;
        else return mid;
    }
}
