    memcpy(S,D,sizeof D);
    sort(S+1,S+1+Size);
    for(int i=1;i<=Size;i++)
        if(S[i]!=S[S2])
            S[++S2]=S[i];
    for(int i=1;i<=Size;i++)
        D[i]=Search(D[i]);
    for(int i=1;i<=Size;i++)
    {
        Pos=D[i];
