int LIS(vector<pt> &V) {
	vector<int> dp(V.size() + 1, (int)1e9);
	dp[0] = -(int)1e9;

	for (int i = 0; i < V.size(); ++i) {
		int ps = upper_bound(all(dp), V[i].y) - dp.begin();

		if (dp[ps - 1] < V[i].y && V[i].y < dp[ps]) {
			dp[ps] = V[i].y;
		}
	}

	int ret = V.size();

	while (dp[ret] == (int)1e9) {
		--ret;
	}

	return ret;
