int CeilIndexLess(std::vector<int> &v, int l, int r, int key) {
    while (r-l > 1) {
    int m = l + (r-l)/2;
    if (v[m] >= key)
        r = m;
    else
        l = m;
    }

    return r;
}

int LongestIncreasingSubsequenceLengthLess(std::vector< pair<int,int> > &v) {
    if (v.size() == 0)
        return 0;

    std::vector<int> tail(v.size(), 0);
    int length = 1; // always points empty slot in tail

    tail[0] = v[0].S;
    for (size_t i = 1; i < v.size(); i++) {
        if (v[i].S < tail[0])
            // new smallest value
            tail[0] = v[i].S;
        else if (v[i].S > tail[length-1])
            // v[i] extends largest subsequence
            tail[length++] = v[i].S;
        else
            // v[i] will become end candidate of an existing subsequence or
            // Throw away larger elements in all LIS, to make room for upcoming grater elements than v[i]
            // (and also, v[i] would have already appeared in one of LIS, identify the location and replace it)
            tail[CeilIndexLess(tail, -1, length-1, v[i].S)] = v[i].S;
    }

    return length;
}


int CeilIndexGreat(std::vector<int> &v, int l, int r, int key) {
    while (r-l > 1) {
    int m = l + (r-l)/2;
    if (v[m] <= key)
        r = m;
    else
        l = m;
    }

    return r;
}

int LongestIncreasingSubsequenceLengthGreat(std::vector< pair<int,int> > &v) {
    if (v.size() == 0)
        return 0;

    std::vector<int> tail(v.size(), 0);
    int length = 1; // always points empty slot in tail

    tail[0] = v[0].S;
    for (size_t i = 1; i < v.size(); i++) {
        if (v[i].S > tail[0])
            // new smallest value
            tail[0] = v[i].S;
        else if (v[i].S < tail[length-1])
            // v[i] extends largest subsequence
            tail[length++] = v[i].S;
        else
            // v[i] will become end candidate of an existing subsequence or
            // Throw away larger elements in all LIS, to make room for upcoming grater elements than v[i]
            // (and also, v[i] would have already appeared in one of LIS, identify the location and replace it)
            tail[CeilIndexGreat(tail, -1, length-1, v[i].S)] = v[i].S;
    }

    return length;
}



