		solve2();
		return ;
	}
	n = 0;
	if(y2>=y1 && x2>=x1 || y2<=y1 && x2<=x1){
		if(x2<x1){
			swap(y1, y2);
			swap(x1, x2);
		}
		for(i=0; i<N; i++){
			if(X[i]>=x1 && X[i]<=x2 && Y[i]>=y1 && Y[i]<=y2){
				XX[n] = X[i];
				YY[n] = Y[i];
				n ++;
			}
		}
		for(i=0; i<n; i++)
			idx[i] = i;
		qsort(idx, n, sizeof(int), cmp);
		for(i=0; i<n; i++){
			Y3[i] = YY[idx[i]];
		}
	}
	else{
		if(x2<x1){
			swap(y1, y2);
			swap(x1, x2);
		}
		for(i=0; i<N; i++){
			if(X[i]>=x1 && X[i]<=x2 && Y[i]>=y2 && Y[i]<=y1){
				XX[n] = X[i];
