int g(int y) {
	return abs(Y - y);
}

struct point {
	int x, y;
	bool operator < (const point q) const {
		if(this->x < q.x && g(this->y) < g(q.y))return true;
		return false;
	}
	bool operator >= (const point q) const {
		if(this->x >= q.x && g(this->y) >= g(q.y))return true;
		return false;
	}
};

int binary_search(point key, point *g, int low, int high)
{
    while (low < high)
    {
        int mid = (low + high) >> 1;
        if (key >= g[mid])
            low = mid + 1;
        else
            high = mid;
    }
    return low;
}


point a[maxn], d[maxn];

bool cmp(point w, point q) {
	if(w.x < q.x)return true;
	else if(w.x == q.x)return g(w.y) < g(q.y);
	return false;
}

