{
	Point sp, ep;
	int n,mytype,arrsize=0;
	vector<Point> arr;
	vector<int> dp;
	cin >> sp.x >> sp.y >> ep.x >> ep.y;
	cin >> n;
	arr.resize(n);
	dp.resize(n,0);
	mytype = ((ep.y - sp.y)*(ep.x -sp.x))>0 ? 1 : 0;
	int x1, x2, y1, y2;
	x1 = min(sp.x, ep.x);
	x2 = max(sp.x, ep.x);
	if (mytype)
	{
		y1 = min(sp.y, ep.y);
		y2 = max(sp.y, ep.y);
	}
	else
	{
		y2 = min(sp.y, ep.y);
		y1 = max(sp.y, ep.y);
	}
	sp.x = x1;
	ep.x = x2;
	sp.y = y1;
	ep.y = y2;
	int k=0;
	for (int i = 0; i < n; i++)
	{
