    if(y2 < y1) {
        y1 = MAXL - y1;
        y2 = MAXL - y2;
        for(auto &&ele : xy) {
            ll x, y;
            tie(x, y) = ele;
            y = MAXL - y;
            ele = PLL(x, y);
        }
    }

    double ans = (x2 - x1) + (y2 - y1);
    ans *= 100;

    if(x1 == x2 || y1 == y2) {
        for(auto &&ele : xy) {
            ll x, y;
            tie(x, y) = ele;
            if(x1 <= x && x <= x2 &&
               y1 <= y && y <= y2) {
                ans -= 20;
                ans += 20 / 2 * M_PI;
                return ans;
            }
        }
        return ans;
    }

    V<ll> coors(2 * N + 5);
    {
        for(ll i = 0; i < N; i++) {
            coors[2 * i] = xy[i].first;
            coors[2 * i + 1] = xy[i].second;
        }
        coors[2 * N] = x1;
        coors[2 * N + 1] = x2;
        coors[2 * N + 2] = y1;
        coors[2 * N + 3] = y2;
        coors[2 * N + 4] = -1;
        sort(ALL(coors));
        auto ite = unique(ALL(coors));
        coors.erase(ite, coors.end());
        auto get_idx = [&](ll x) {
            return distance(coors.begin(),
                            lower_bound(ALL(coors), x));
        };
        x1 = get_idx(x1);
        y1 = get_idx(y1);
        x2 = get_idx(x2);
        y2 = get_idx(y2);
        for(auto &&ele : xy) {
            ll x, y;
            tie(x, y) = ele;
            ele = PLL(get_idx(x), get_idx(y));
        }
    }

    SegmentTree<ll> seg_v(V<ll>(2 * N + 10, 0), [](ll a, ll b) { return max(a, b); }, 0);
    SegmentTree<ll> seg_h(V<ll>(2 * N + 10, 0), [](ll a, ll b) { return max(a, b); }, 0);
    sort(ALL(xy));
    ll px = x1, py = y1;
    bool ok = false;
    for(auto &&ele : xy) {
        ll x, y;
        tie(x, y) = ele;
        if(!(x1 <= x && x <= x2 &&
             y1 <= y && y <= y2)) continue;
        if(coors[px] + 1 < coors[x]) ok = true;
        if(coors[x] == coors[x1]) {
            seg_h.update(y, 1);
        } else if(coors[y] == coors[y1]) {
            seg_v.update(y, 1);
        } else {
            bool f = false;
            ll max_v = 0, max_h = 0;
            if(coors[px] + 1 == coors[x] && coors[py] + 1 == coors[y]) {
                f = true;
                ll vv = seg_v.query(py, py + 1);
                ll hv = seg_h.query(py, py + 1);
                chmax(max_v, vv + 1);
                chmax(max_h, hv + 1);
            }

            ll val = max(seg_v.query(0, (f ? py : y)), seg_h.query(0, (f ? py : y)));
            chmax(max_v, val + 1);
            chmax(max_h, val + 1);
            DEBUG(make_tuple(ele, max_v, max_h));
            if(ok) seg_v.update(y, max_v);
            seg_h.update(y, max_h);
        }
        px = x;
        py = y;
    }

    const double inf = 5e15;
    double dec = -inf;
    double d = 2 * 10 / 4 * M_PI;
    double diff = 2 * 10 - d;
    DEBUG(make_tuple(px, py, x1, y1, x2, y2));
    chmax(dec, diff * seg_h.query(y1, py), diff * seg_h.query(py + 1, y2));
    DEBUG(dec);
    chmax(dec, diff * seg_h.query(py, py + 1) - (px == x2 ? d : 0));
    chmax(dec, diff * seg_v.query(y1, y2));
    DEBUG(dec);
    chmax(dec, diff * seg_v.query(y2, y2 + 1) - d);
    DEBUG(dec);

    {
        ll pre_x = coors[xy[0].first];
        ll pre_y = coors[xy[0].second];
        bool f = true;
        for(ll i = 1; i < N; i++) {
            ll xi, yi;
            tie(xi, yi) = xy[i];
            if(!(x1 <= xi && xi <= x2 &&
                 y1 <= yi && yi <= y2)) continue;
            ll x = coors[xi];
            ll y = coors[yi];
            if(!(pre_y < y)) {
                f = false;
                break;
            }
            pre_x = x;
            pre_y = y;
        }
        DEBUG(pre_x,coors[x2]);
        if(pre_x == coors[x2] && f) {
            dec = dec + 2 * 10 - 2 * d;
        }
    }

    return ans - dec;
}

