struct SegTree{
    SegTree *l, *r;
    int left, right;
    ll value = 0;
    SegTree(int size):SegTree(0, size - 1){ }
    SegTree(int st, int lt): left(st), right(lt){
        if(left == right){
            l = r = nullptr;
        }else{
            l = new SegTree(left, (right - left) / 2 + left);
            r = new SegTree((right - left) / 2 + left + 1, right);
        }
    }
    void set(int idx, ll val){
        if(right < idx || idx < left){ return; }
        value = max(value, val);
        if(left != idx || right != idx){
            l -> set(idx, val);
            r -> set(idx, val);
        }
    }
	ll getMax(int le, int re){
		if(right < le || re < left){ return 0; }
		if(le <= left && right <= re){
			return value;
		}
		return max(l -> getMax(le, re), r -> getMax(le, re));
	}
};

