    int N;
    cin >> N;
    vector<pair<int, int>> R(N);
    rep(i, N){
        cin >> R[i].first >> R[i].second;
    }

    vector<ll> A;
    sort(all(R));
    for(auto r: R){
        if((r.first - S.first) * (r.first - G.first) <= 0 && (r.second - S.second) * (r.second - G.second) <= 0) {
            A.pb(r.second);
        }
    }

    vector<ll> L;
    if(A.size() > 0){
        LIS lis = LIS(A);
        L = lis.calc();
    }

    double ans = 0.0;
    int sz = (int)L.size();
    if(sz == abs(S.first - G.first) + 1 || sz == abs(S.second - G.second) + 1) {
        sz--;
        ans = pi * 10.0 - 20.0;
    }
    ans += (pi * 5.0 - 20.0) * sz;
    ans += 100.0 * (abs(S.first - G.first) + abs(S.second - G.second));

    output(ans, 15);

    return 0;
}

