int Pos,Val;
pair<int,int> dots[MaxN];
int D[MaxN],O[MaxN],Size=0,S2=0,S[MaxN];
void Update(int node,int Start,int End)
{
    if(Start==End)
        T[node]=Val;
    else
    {
        int mid=(Start+End)>>1;
        if(Pos>mid)
            Update(2*node+1,mid+1,End);
        else Update(2*node,Start,mid);
        T[node]=max(T[2*node],T[2*node+1]);
    }
}
void Query_Down(int node,int Start,int End)
{
    if(Start>=Pos)
        Val=max(Val,T[node]);
    else
    {
        int mid=(Start+End)>>1;
        Query_Down(2*node+1,mid+1,End);
        if(mid>=Pos)
            Query_Down(2*node,Start,mid);
    }
}
void Query_Up(int node,int Start,int End)
{
    if(End<=Pos)
        Val=max(Val,T[node]);
    else
    {
        int mid=(Start+End)>>1;
        Query_Up(2*node,Start,mid);
        if(mid<Pos)
            Query_Up(2*node+1,mid+1,End);
    }
}
int Search(int val)
{
    int lw=1,hi=S2,mid;
    while(lw<=hi)
    {
        mid=(lw+hi)>>1;
        if(S[mid]>val)
            hi=mid-1;
        else if(S[mid]<val)
            lw=mid+1;
        else return mid;
    }
}
void Normalize()
{
    for(int i=1;i<=Size;i++)
        S[i]=D[i];
    sort(S+1,S+1+Size);
    for(int i=1;i<=Size;i++)
        if(S[i]!=S[S2])
        S[++S2]=S[i];
    for(int i=1;i<=Size;i++)
        D[i]=Search(D[i]);
}
