const double PI = acos(-1);

void solve() {
  pii s, t; cin >> s >> t;
  int n; cin >> n;
  vector<pii> g;
  int xmin, ymin; tie(xmin, ymin) = s;
  int xmax, ymax; tie(xmax, ymax) = t;
  if(xmin > xmax) swap(xmin, xmax);
  if(ymin > ymax) swap(ymin, ymax);
  while(n--) {
    int x, y; cin >> x >> y;
    if(clamp(x, xmin, xmax) == x && clamp(y, ymin, ymax) == y) {
      g.emplace_back(x, y);
    }
  }

  if(s.first == t.first) {
    double ans = abs(s.second - t.second) * 100LL;
    for(auto &p : g) {
      if(p.first == s.first) {
        ans += PI * 10 - 20;
        break;
      }
    }
    cout << ans << endl;
    return;
  }

  if(s.second == t.second) {
    double ans = abs(s.first - t.first) * 100LL;
    for(auto &p : g) {
      if(p.second == s.second) {
        ans += PI * 10 - 20;
        break;
      }
    }
    cout << ans << endl;
    return;
  }

  if(s.second > t.second) swap(s, t);
  if(s.first < t.first) sort(ALL(g));
  else sort(RALL(g));

  vi dp;

  for(auto &p : g) {
    auto itr = lower_bound(ALL(dp), p.second);
    if(itr == dp.end()) {
      dp.emplace_back(p.second);
    } else {
      *itr = p.second;
    }
  }

  double ans = (abs(s.first - t.first) + abs(s.second - t.second)) * 100LL;
  ans += (PI * 5 - 20) * dp.size();
  if(min(abs(s.first - t.first), abs(s.second - t.second)) < dp.size()) {
    ans += PI * 5;
  }
  cout << ans << endl;
}


