bool isSameLine(info p,info a,info q)
{
	if( p.x == q.x ) return ( min(p.y,q.y) <= a.y && a.y <= max(p.y,q.y) );
	if( p.y == q.y ) return ( min(p.x,q.x) <= a.x && a.x <= max(p.x,q.x) );
	return 0;
}

