LL a[Max],N,dp[Max],c[Max];

LL bin(LL len,LL x)
{
	LL low = 1,high = len, mid, ans;
	if( x > c[len] ) return len + 1;
	while(low <= high)
	{
		mid = (low + high) / 2;
		LL my = c[mid];
		if( x <= my )
		{
			ans = mid;
			high = mid - 1;
		}
		else low = mid + 1;
	}
	return ans;
}

LL LIS()
{
    LL len = 1,i;
    c[0] = -1;
    c[1] = a[1];
    dp[1] = 1;
    for(i = 2; i <= N; i++)
    {
        LL k = bin(len,a[i]);
        c[k] = a[i];
        dp[i] = k;
        len = max(len,k);
    }
    LL ret = 0;
    rep(i,N) ret = max(ret,dp[i]);
    return ret;
}

void make()
{
	LL i;
    rep(i,n)
    {
		if( st.x <= ara[i].x && ara[i].x <= ed.x )
		{
			if( st.y <= ara[i].y && ara[i].y <= ed.y )
			{
				a[++N] = ara[i].y - st.y;
			}
		}
    }
    //D(N);
}

