int unutra(P tmp) {
  return (tmp.X >= poc.X && tmp.X <= kraj.X &&
	  tmp.Y >= poc.Y && tmp.Y <= kraj.Y);
}

int main()
{
  scanf("%d%d%d%d", &poc.X, &poc.Y, &kraj.X, &kraj.Y);
