    swap(poc, kraj);

  if (poc.Y > kraj.Y) {
    poc.Y = -poc.Y;
    kraj.Y = -kraj.Y;
    REP(i, n) V[i].Y *= -1;
  }

  sort(V.begin(), V.end());
