int ft[400005];
int nn=200005;

void update(int at, int by){
    while(at <= nn){ 
        ft[at] += by; 
        at |= (at+1);
    }   
}

int query(int at){
    int res = 0;
    while(at > 0){ 
        res += ft[at];
        at = (at & (at + 1)) - 1;
    }   
    return res;
}

