class Point {
public:
    long long x, y;

    Point(long long x = 0, long long y = 0) {
        this->x = x;
        this->y = y;
    }

    Point(const Point &other) {
        x = other.x;
        y = other.y;
    }

    const Point &operator=(const Point &point) {
        x = point.x;
        y = point.y;

        return *this;
    }

    Point operator+(const Point &second) const {
        return Point(x + second.x, y + second.y);
    }

    Point operator-(const Point &second) const {
        return Point(x - second.x, y - second.y);
    }

    friend istream &operator>>(istream &stream, Point &point) {
        stream >> point.x >> point.y;

        return stream;
    }

    friend ostream &operator<<(ostream &stream, Point &point) {
        stream << "Point(" << point.x << ", " << point.y << ")";

        return stream;
    }

    long long distance(const Point &second) const {
        return 100ll * (abs(x - second.x) + abs(y - second.y));
    }
};


