        // Подготавливаем internal_fountains к get_lis_len
        sort(internal_fountains.begin(), internal_fountains.end(), comp);
        if (start.y > end.y) {
            reverse(internal_fountains.begin(), internal_fountains.end());
        }
        /*
        cout << "sorted internal_fountains:" << endl;
        for (auto fountain : internal_fountains) {
            cout << fountain << endl;
        }
        cout << endl;
        */
        // Находим длину НВП, где значениями в массиве выступаю Point.x
        int lis_len = get_lis_len(internal_fountains);
        /*
        cout << "lis_len = " << lis_len << endl << endl;
        */
        // Окончательный ответ
        ans += lis_len * (5 * M_PI - 20);
    }

    void output_answer() {
        cout << ans << endl;
    }
};



bool comp(const Point &a, const Point &b) {
    return (a.y < b.y);
}

vector<Point> get_internal_fountains(const Point &end, const Point &start, const vector<Point> &fountains) {
    vector<Point> res;

    for (auto fountain : fountains) {
        if (is_internal(fountain, start, end)) {
            res.push_back(fountain);
        }
    }

    return res;
}

bool is_internal(const Point &fountain, const Point &start, const Point &end) {
    return (min(start.x, end.x) <= fountain.x && fountain.x <= max(start.x, end.x) &&
            min(start.y, end.y) <= fountain.y && fountain.y <= max(start.y, end.y));
}

int get_lis_len(const vector<Point> &points) {
    // Находит нвп по y

    vector<long long> dp(points.size() + 1, INF);
    dp[0] = -INF;

    for (auto point : points) {
        int l = 0;
        int r = dp.size() - 1;
        while (l < r) {
            int m = (l + r + 1) / 2;

            if (dp[m] < point.x) {
                l = m;
            } else {
                r = m - 1;
            }
        }

        dp[l + 1] = min(dp[l + 1], point.x);
    }
    /*
    cout << "dp:" << endl;
    for (auto num : dp) {
        cout << num << " ";
    }
    cout << endl << endl;
    */
    for (int i = dp.size() - 1; i >= 0; --i) {
        if (dp[i] != INF) {
            return i;
        }
    }

    return 0;
}


