struct hash_table
{
	int sz;
	vector<int> H, F, used;
	hash_table() { }

	hash_table(int n)
	{
		sz = n;
		H.resize(sz);
		F.resize(sz);
		used.resize(sz);
	}

	int getpos(int h) const
	{
		int i = h % sz;
		for (; used[i] && H[i] != h; ++i) if (i == sz) i = 0;
		return i;
	}

	int& operator[](int h)
	{
		int i = getpos(h);
		H[i] = h;
		return F[i];
	}
};

struct fenwick
{
	int n;
	hash_table F;

	fenwick() { n = inf, F = hash_table(maxn); }

	void upd(int i, int x)
	{
		for (; i < n; i |= i + 1)
			F[i] = max(F[i], x);
	}

	int get(int i)
	{
		int res = 0;

		for (; i >= 0; i &= i + 1, --i)
			res = max(res, F[i]);

		return res;
	}
};

