int sx,sy,ex,ey,n;
void Pre()
{
	bool f=0;
	if(sy>ey) swap(sx,ex),swap(sy,ey);
	if(sy==ey&&sx>ex) swap(sx,ex);
	if(sx>ex) f=1,ex=2*sx-ex;
	ex-=sx,ey-=sy;
	int x,y,m=0;
	for(int i=1;i<=n;i++)
	{
		scanf("%d%d",&x,&y);
		if(f) x=2*sx-x;
		x-=sx,y-=sy;
		if(x<0||x>ex||y<0||y>ey) continue;
		e[++m].x=x,e[m].y=y;
	}
	sx=0,sy=0;
	n=m;
}
int a[MAXN],st[MAXN],r;
void Solve()
{
	for(int i=1;i<=n;i++)
		a[i]=e[i].y;
	st[0]=-1;
	for(int i=1;i<=n;i++)
	{
		if(a[i]>st[r]) st[++r]=a[i];
		else
		{
			int p=upper_bound(st,st+r+1,a[i])-st;
			st[p]=a[i];
		}
	}
}
