bool inside (point p) {
	return min(start.x, finish.x) <= p.x && p.x <= max(start.x, finish.x) && min(start.y, finish.y) <= p.y && p.y <= max(start.y, finish.y); 
}

void compress () {
	sort (a + 1, a + 1 + n); 
	vector<int> rar; 
	for (int i = 1; i <= n; i++) {
		rar.push_back(a[i].y); 
	}
	removeDuplicate(rar); 
	for (int i = 1; i <= n; i++) {
		a[i].y = lower_bound(rar.begin(), rar.end(), a[i].y) - rar.begin() + 1; 
	}
}

