int n;
int st[MAXN];
int main(){
	SF("%d%d%d%d",&xl,&yl,&xr,&yr);
	if(xl>xr)
		fx=-1;
	else
		fx=1;
	if(yl>yr)
		fy=-1;
	else
		fy=1;
	xl*=fx,xr*=fx,yl*=fy,yr*=fy;
	SF("%d",&n);
	for(int i=1;i<=n;i++){
		SF("%d%d",&p[i].x,&p[i].y);
		p[i].x*=fx;
		p[i].y*=fy;
		if(p[i].x<xl||p[i].x>xr||p[i].y<yl||p[i].y>yr){
			n--;
			i--;
			continue;
		}
	}
	sort(p+1,p+1+n);
	int top=0;
	for(int i=1;i<=n;i++){
		if(top==0||st[top]<p[i].y)
			st[++top]=p[i].y;
		else{
			int pos=lower_bound(st+1,st+1+top,p[i].y)-st;
			st[pos]=p[i].y;	
		}
