int where[2 * MAXN];
int bit[2 * MAXN];
int dp[2 * MAXN];
void upd(int pos, int val){
    while(pos < 2 * MAXN){
        bit[pos] = max(bit[pos], val);
        pos += pos & -pos;
    }
}
int get(int pos){
    int ret = 0;
    while(pos){
        ret = max(ret, bit[pos]);
        pos -= pos & -pos;
    }
    return ret;
}
