#define MAX(a,b) ((a)>(b)?(a):(b))
#define INF ((lint)1000000000)
#define PI 3.14159265358979323846

lint dp[200010];
lint a[200010];

lint LIS(lint N) {
	for (lint i = 0; i < N; i++) dp[i] = INF;
	for (lint i = 0; i < N; i++) {
		*lower_bound(dp, dp + N, a[i]) = a[i];
	}
	return lower_bound(dp, dp + N, INF) - dp;
}

int main()
{
	lint xs, ys, xg, yg;
	lint N;

	cin >> xs >> ys >> xg >> yg;
	if (xs == xg)
		if (ys > yg) SWAP(ys, yg);
	if (xs > xg) SWAP(xs, xg), SWAP(ys, yg);

	cin >> N;

	vector<Pii> Points;
	int x, y;
	for (lint i = 0; i < N; i++) {
		cin >> x >> y;
