const int N = 200010;
const double pi = acos(-1);
struct data {
	int x, y, pos;
	bool friend operator < (const data &a, const data &b) {
		return a.x == b.x ? a.y < b.y : a.x < b.x;		
	}
} a[N];
int n, X1, X2, Y1, Y2, cnt, mx;
double ans;
int dp[N], tree[N], last[N], nxt[N], pre[N];
vector<int> v;
void update(int l, int r, int x, int pos, int d) 
{
	if(l == r)
	{
		tree[x] = d;
		return;
	}
	int mid = (l + r) >> 1;
	if(pos <= mid) update(l, mid, x << 1, pos, d);
	else update(mid + 1, r, x << 1 | 1, pos, d);
	tree[x] = max(tree[x << 1], tree[x << 1 | 1]);
}
int query(int l, int r, int x, int a, int b)
{
	if(l > b || r < a) return 0;
	if(l >= a && r <= b) return tree[x];
	int mid = (l + r) >> 1;
	return max(query(l, mid, x << 1, a, b), query(mid + 1, r, x << 1 | 1, a, b));
} 
int query(int x)
{
	int ret = 0;
	for(; x; x -= x & (-x)) ret = max(ret, tree[x]);
	return ret;
}
int main()
{
	scanf("%d%d%d%d%d", &X1, &Y1, &X2, &Y2, &n);
	if(X1 > X2) swap(X1, X2), swap(Y1, Y2);
	for(int i = 1; i <= n; ++i) 
	{
		int x, y;
		scanf("%d%d", &x, &y);
		if(x < X1 || x > X2 || y < Y1 || y > Y2) continue;
		a[++cnt].x = x;
		a[cnt].y = y;
		v.push_back(y);
	}
	sort(v.begin(), v.end());
	sort(a + 1, a + cnt + 1);
	for(int i = 1; i <= cnt; ++i) a[i].pos = lower_bound(v.begin(), v.end(), a[i].y) - v.begin() + 1;
	for(int i = 1; i <= cnt; ++i)
	{
		if(last[a[i].pos]) pre[i] = last[a[i].pos], nxt[last[a[i].pos]] = i;
		else pre[i] = 1;
		last[a[i].pos] = i; 
	}
	for(int i = 1; i <= cnt; ++i) if(!nxt[i]) nxt[i] = cnt;
	for(int i = 1; i <= cnt; ++i) 
	{
		if(Y1 <= Y2) dp[i] = query(1, cnt, 1, 1, a[i].pos) + 1;	
		else dp[i] = query(1, cnt, 1, a[i].pos, cnt) + 1;
		update(1, cnt, 1, a[i].pos, dp[i]);
		mx = max(mx, dp[i]);
	}
	ans = ( abs(X1 - X2) + abs(Y1 - Y2) ) * 100.0;
	ans -= mx * (20.0 - pi * 5.0);
	printf("%.14f\n", ans);
	return 0;
}

