using namespace std;
const double pi = acos(-1.0);
const double circle = 2*pi*10;

int LIS(const vector<pair<int, int> > &XY){
    const int inf = 1<<30;
    int n = XY.size();
    if(n==0)return 0;
    vector<int> L(n, inf);
    int p = 0;
    REP(i, n){
        int v = XY[i].second;
        if(L[p] < v){
            L[++p] = v;
        }else{
            int j = lower_bound(ALL(L), v) - L.begin();
            L[j] = v;
        }
    }
    return p+1;
}

int main(){
    int x1, y1, x2, y2, N;
    vector<pair<int, int> > XY;
    cin >> x1 >> y1 >> x2 >> y2 >> N;
    if(x1>x2){
        swap(x1, x2);
        swap(y1, y2);
    }
    REP(i, N){
        int x, y;
        cin >> x >> y;
        if(x<x1 || x>x2 || y<min(y1, y2) || y>max(y1, y2))continue;
        XY.push_back(make_pair(x, y));
    }
    sort(ALL(XY));
    if(y1>y2)REP(i, XY.size())XY[i].second *= -1;
    int lis = LIS(XY);
    cerr << lis << endl;
    double res = (abs(y1-y2) + x2-x1) * 100.0;
    if(y1!=y2){
        double diff = 20 - circle / 4.0;
        res -= lis*diff;
    }else{
        double diff = circle / 2.0 - 20;
        res += lis*diff;
    }
    printf("%.18f\n", res);

    return 0;
}

