			LL flag = 1;
			for(LL i = st.x, k = 0; i <= ed.x; i++,k++)
			{
				LL xx = i;
				LL yy = first + k;
				if( mp.find( make_pair(xx,yy) ) == mp.end() )
				{
					flag = 0;
					break;
				}
			}
			if( flag ) return true;
		}
	}

	///dane
	first = -1;
	rep(i,n)
	{
		if( ara[i].y == st.y )
		{
            first = ara[i].x;
            break;
		}
	}
	if( first != -1 )
	{
		LL d = ed.y - st.y + 1;
