int que(int val){
    int r=0;
    for(;val;val-=lowbit(val))
        r=max(c[val],r);
    return r;
}
void add(int val,int r){
    for(;val<=maxi;val+=lowbit(val))
        c[val]=max(c[val],r);
    return ;
}

