#include<bits/stdc++.h>
using namespace std;

#define PI 3.1415926535

int N;
bool need_reverse;
bool x_accord;
bool y_accord;
typedef long long int LLI;
LLI xs[2];
LLI ys[2];
int size;
int seg[1 << 20];
typedef pair<LLI, LLI> Pair;
vector<Pair> ps;
vector<LLI> comp;

void update_if(int k, int x) {
  k += size-1;
  if (seg[k] > x) return;
  seg[k] = x;
  while (k > 0) {
    k /= 2;
    seg[k] = max(seg[k*2+1], seg[k*2+2]);
  }
}

int getmax(int wishl, int wishr, int k, int watchl, int watchr) {
  int mid;
  int lval, rval;

  if (wishr <= watchl || watchr <= wishl) return 0;
  if (wishl <= watchl && watchr <= wishr) return seg[k];

  mid = (watchl+watchr)/2;
  lval = getmax(wishl, wishr, k*2+1, watchl, mid);
  rval = getmax(wishl, wishr, k*2+2, mid, watchr);
  return max(lval, rval);
}

int main() {
  for (int i=0; i<2; i++) {
    scanf("%lld%lld", &xs[i], &ys[i]);
  }
  if (xs[1] < xs[0]) {
    swap(xs[0], xs[1]);
    swap(ys[0], ys[1]);
  }

  if (ys[1] < ys[0]) {
    need_reverse = true;
    ys[0] = -ys[0];
    ys[1] = -ys[1];
  }
  xs[1] -= xs[0];
  ys[1] -= ys[0];
  if (ys[1] == 0) y_accord = true;
  if (xs[1] == 0) x_accord = true;
  ps.emplace_back(Pair(ys[1], xs[1]));
  comp.emplace_back(xs[1]);

  scanf("%d", &N);
  size = 1;
  while(size < N) size*=2;
  for (int i=0; i<N; i++) {
    LLI x, y;
    scanf("%lld%lld", &x, &y);
    if (need_reverse) y = -y;
    x -= xs[0];
    y -= ys[0]; 
    if (x == 0 && x_accord) {
      printf("%.13f\n", ys[1]*100+(PI-2)*10);
      return 0;
    }
    if (y == 0 && y_accord) {
      printf("%.13f\n", xs[1]*100+(PI-2)*10);
      return 0;
    }
    comp.emplace_back(x);
    ps.emplace_back(Pair(y, x));
  }
  sort(comp.begin(), comp.end());
  comp.erase(unique(comp.begin(), comp.end()), comp.end());
  sort(ps.begin(), ps.end());

  for (auto &p : ps) {
    LLI x = p.second;
    LLI y = p.first;
    if (x < 0) continue;
    int idx = lower_bound(comp.begin(), comp.end(), x) - comp.begin();
    assert (comp[idx] == x);
    int t = getmax(0, idx+1, 0, 0, size);
    if (x == xs[1] && y == ys[1]) {
      printf("%.13f\n", ((ys[1]+xs[1])*100 - (2-PI/2)*10*t));
      return 0;
    } else {
      update_if(idx, t+1);
    }
  }
}

#include <bits/stdc++.h>

