#include <cstdio>
#include <algorithm>
#include <utility>
#include <vector>
#include <cmath>
#define MAX_N (200000)

using namespace std;

typedef pair<int,int> P;
P points[MAX_N];
P sortedX[MAX_N];
P sortedY[MAX_N];
int cX[MAX_N];
int cY[MAX_N];

int cmp(const P& p1, const P& p2) {
  return p1.second > p2.second;
}
struct SegmentTree {
  int Storage[MAX_N*8];
  int N;
  void init(int n) {
    N=1;
    while(N<n) N*=2;

    for(int i=0;i<N*2;++i) {
      Storage[i]=0;
    }
  }

  void updateLeaf(int i, int value) {
    i += N-1;
    Storage[i]=value;
    while(i>0) {
      i = (i-1) / 2;
      Storage[i] = max(Storage[i*2+1], Storage[i*2+2]);
    }
  }

  int calcRangeGCD(int a,int b,int k,int l, int r) {
    if(b<=l || a>=r) return 0;
    if(a<=l && b>=r) {
      return Storage[k];
    } else {
      int tl = calcRangeGCD(a,b,k*2+1,l,(l+r)/2);
      int tr = calcRangeGCD(a,b,k*2+2,(l+r)/2,r);
      return max(tl,tr);
    }
  }
};
SegmentTree segmentTree;
int main() {
  int x1,y1,x2,y2;
  int N;
  bool flip=false;
  scanf("%d%d%d%d", &x1, &y1, &x2, &y2);
  if (y1>y2) {
    swap(y1,y2);
    swap(x1,x2);
  }
  if (x1>x2) {
    flip=true;
    x1= (1000 * 1000 * 100 - 1) - x1;
    x2= (1000 * 1000 * 100 - 1) - x2;
  }
  scanf("%d", &N);
  int subN=0;
  for(int i=0;i<N;++i) {
    int X,Y;
    scanf("%d%d", &X, &Y);
    if (flip) {
      X= (1000 * 1000 * 100 - 1) - X;
    }
    if (X>=x1&&X<=x2 && Y>=y1&&Y<=y2) {
      sortedX[subN]=P(X,subN);
      sortedY[subN]=P(Y,subN);
      subN++;
    }
  }
  N=subN;
  sort(sortedX, sortedX+N);
  sort(sortedY, sortedY+N);
  for(int i=0;i<N;++i) {
    P sX=sortedX[i];
    cX[i]=sX.first;
    P sY=sortedY[i];
    cY[i]=sY.first;
    points[sX.second].first=i;
    points[sY.second].second=i;
  }
  sort(points,points+N,cmp);
  segmentTree.init(N);
  for(int i=0;i<N;++i) {
    P p=points[i];
    int m=segmentTree.calcRangeGCD(p.first,N,0,0,segmentTree.N);
    segmentTree.updateLeaf(p.first, m+1);
  }
  int num=segmentTree.calcRangeGCD(0,N,0,0,segmentTree.N);
  bool flag=false;
  if (num==min(x2-x1+1,y2-y1+1)) {
    flag=true;
  }

  long double answer = 0;
  answer += ((x2-x1) + (y2-y1))*100;
  answer += (5.0 * M_PI-20.0) * num;
  if (flag) {
    answer -= (5.0*M_PI-20.0);
    answer += (10.0*M_PI-20.0);
  }

  printf("%.20Lf\n", answer);
  return 0;
}

