  fill(dp, dp + m, INT_MAX);
  for_each(ps.begin(), ps.end(), [&dp, m](const auto &p) {
    *lower_bound(dp, dp + m, p.second) = p.second;
  });
  long k = lower_bound(dp, dp + m, INT_MAX) - dp;

  double ans = 100 * (abs(tx) + abs(ty));
  ans += (((tx == 0 || ty == 0) && 0 < k ? 10 : 5) * M_PI - 20) * k;

  cout << setprecision(18) << ans << endl;
}

