    vector<ii> fountains;
    for(int i=0;i<N;++i){
        int x, y;
        cin>>x>>y;
        if(x>=xm && x<=xM && y>=ym && y<= yM) fountains.push_back(ii(x,y));
    }
    cout <<setprecision(31);
    cout<<FountainWalk().Solution(x1, y1, x2, y2, fountains)<<endl;
}

