        else ans = min(ans, (long double)((abs(b-d)+abs(a-c))*100.0L+Q*(C)));

        if( b < d ) sort(T, T+cnt, [](JK a, JK b){ return a.y < b.y; });
        else sort(T, T+cnt, [](JK a, JK b){ return a.y > b.y; });
        lis[0] = T[0].x; ed = 0;
        for(int i = 1 ; i < cnt ; i++ )
        {
            if( lis[ed] < T[i].x ) ed++, lis[ed] = T[i].x;
            else
            {
                v = (int)(lower_bound(lis, lis+ed+1, T[i].x) - lis);
                lis[v] = T[i].x;
            }
        }
        C = ed+1;
        if( C == abs(b-d) ) ans = min(ans, (long double)((abs(b-d)+abs(a-c))*100.0L+Q*(C-1)+H));
        else ans = min(ans, (long double)((abs(b-d)+abs(a-c))*100.0L+Q*(C)));
    }
    cout<<setprecision(20)<<ans<<endl;
    return 0;
}

