int n;

void initiate(vector<pt> &V, pt &p1, pt &p2) {
	if (p1.x > p2.x) {
		swap(p1, p2);
	}

	{
		vector<pt> tmp;

		for (pt p : V) {
			if (p1.x <= p.x && p.x <= p2.x && min(p1.y, p2.y) <= p.y && p.y <= max(p1.y, p2.y)) {
				tmp.pb(p);
			}
		}

		V = tmp;
	}

	pt tmp = p1;
	p1 = pt(0, 0);
	V.pb(p2);

	for (pt &p : V) {
		p -= tmp;

		if (p.y < 0) {
			p.y *= -1;
		}
	}

	p2 = V.back();
	V.pop_back();
}

int LIS(vector<pt> &V) {
	vector<int> dp(V.size() + 1, (int)1e9);
	dp[0] = -(int)1e9;

	for (int i = 0; i < V.size(); ++i) {
		int ps = upper_bound(all(dp), V[i].y) - dp.begin();

		if (dp[ps - 1] < V[i].y && V[i].y < dp[ps]) {
			dp[ps] = V[i].y;
		}
	}

	int ret = V.size();

	while (dp[ret] == (int)1e9) {
		--ret;
	}

	return ret;
}

double calcFast() {	            
	double ret = -1e15;
	int lim = pB.x;

	for (int step = 0; step < 2; ++step) {		
		sort(all(arr));

        int cnt = 0;

        for (int i = 1; i < arr.size(); ++i) {
        	if (arr[i - 1].y < arr[i].y) {
        		++cnt;
        	}
        }

        if (cnt == lim) {
        	ret = lim * (20.0 - DI) + 20.0 - 2.0 * DI;
        	return 100.0 * (pB.x + pB.y) - ret;
        }
        else {
        	ret = max(ret, (20.0 - DI) * LIS(arr));
        }

		for (pt &p : arr) {
			swap(p.x, p.y);
		}

		lim = pB.x + pB.y - lim;
	}	

	return 100.0 * (pB.x + pB.y) - ret;
}

void solve() {
	pA.read();
	pB.read();                  	
