int get(int l, int r, int v = 1, int tl = 0, int tr = 1e8) {
	if(!v || l > r || tl > tr || tl > r || l > tr)
		return 0;
	if(l <= tl && tr <= r)
		return t[v];
	int mid = (tl + tr) >> 1;
	return max(get(l, r, L[v], tl, mid), get(l, r, R[v], mid + 1, tr));                                                        	
}

void upd(int pos, int val, int v = 1, int tl = 0, int tr = 1e8) {
	if(tl == tr) {
		t[v] = val;
		return;   
	}
	int mid = (tl + tr) >> 1;
	if(pos <= mid) {
		if(!L[v]) L[v] = ++ Sz;
		upd(pos, val, L[v], tl, mid);
	} else {
		if(!R[v]) R[v] = ++ Sz;
		upd(pos, val, R[v], mid + 1, tr);
	}
	t[v] = max(t[L[v]], t[R[v]]);
}

