namespace Fenwick {
    int f[N];

    int get(int x) {
        int ans = 0;
        for (int i = x; i >= 0; i = (i & (i + 1)) - 1) {
            ans = max(ans, f[i]);
        }
        return ans;
    }

    void set(int x, int val) {
        for (int i = x; i < N; i = (i | (i + 1))) {
            f[i] = max(f[i], val);
        }
    }
}

int lis(vector<pair<int, int>>  v) {
    vector<int> sn;
    for (auto t : v) {
        sn.push_back(t.second);
    }
    sort(sn.begin(), sn.end());
    sn.resize(unique(sn.begin(), sn.end()) - sn.begin());
    vector<int> a;
    for (auto t : v) {
        a.push_back(lower_bound(sn.begin(), sn.end(), t.second) - sn.begin());
    }
    int n = (int)a.size();
    for (auto t : a) {
        int val = 1 + Fenwick::get(t - 1);
        Fenwick::set(t, val);
    }
    return Fenwick::get(n);
}

