		f.erase(remove(f.begin(),f.end(),-1),f.end());
		vector<int> dp(f.size(),INF);
		for(int i=0;i<(int)f.size();++i)*lower_bound(dp.begin(),dp.end(),f[i])=f[i];
		l=lower_bound(dp.begin(),dp.end(),INF)-dp.begin();
	}
