			if(min(x1,x2)<=p.first && p.first<=max(x1,x2) && min(y1,y2)<=p.second && p.second<=max(y1,y2))coord.push_back(p);
		}
		sort(coord.begin(),coord.end(),[](pp& a,pp& b){return a.second<b.second;});
		for(int i=0;i<(int)coord.size();++i)f[i]=coord[i].first;
		f.erase(remove(f.begin(),f.end(),-1),f.end());
		vector<int> dp(f.size(),INF);
		for(int i=0;i<(int)f.size();++i)*lower_bound(dp.begin(),dp.end(),f[i])=f[i];
		l=lower_bound(dp.begin(),dp.end(),INF)-dp.begin();
		dp=vector<int>(f.size(),INF);
		reverse(f.begin(),f.end());
		for(int i=0;i<(int)f.size();++i)*lower_bound(dp.begin(),dp.end(),f[i])=f[i];
		l=max(l,(int)(lower_bound(dp.begin(),dp.end(),INF)-dp.begin()));
	}
	else{
		if(y2<y1||(y2==y1&&x2<x1))swap(x1,x2),swap(y1,y2);
		f=vector<int>(n,-1);
		for(int i=0;i<n;++i){
			cin>>p.first>>p.second;
			if(min(x1,x2)<=p.first && p.first<=max(x1,x2) && min(y1,y2)<=p.second && p.second<=max(y1,y2))coord.push_back(p);
		}
		sort(coord.begin(),coord.end(),[](pp& a,pp& b){return a.first<b.first;});
		for(int i=0;i<(int)coord.size();++i)f[i]=coord[i].second;
		f.erase(remove(f.begin(),f.end(),-1),f.end());
		vector<int> dp(f.size(),INF);
		for(int i=0;i<(int)f.size();++i)*lower_bound(dp.begin(),dp.end(),f[i])=f[i];
		l=lower_bound(dp.begin(),dp.end(),INF)-dp.begin();
		dp=vector<int>(f.size(),INF);
		reverse(f.begin(),f.end());
		for(int i=0;i<(int)f.size();++i)*lower_bound(dp.begin(),dp.end(),f[i])=f[i];
		l=max(l,(int)(lower_bound(dp.begin(),dp.end(),INF)-dp.begin()));
	}
	bool fl=min(dx,dy)+1==l;
	res=(dx+dy)*100.0+(5.0*PI-20.0)*(l-fl)+(10.0*PI-20.0)*fl;
	cout<<fixed<<setprecision(15)<<res<<endl;
}

