struct segtree{
  ll M=1;
  vector<ll> dat;
  segtree(ll N, ll num){
    while(M<N) M*=2;
    for(int i=0;i<M*2-1;i++)  dat.push_back(num);
  }
  void upd(int x, int k, int l=0, int r=-1){
    if(r==-1) r = M;
    k+=M-1;
    dat[k] += x;
    while(k>0) k = (k-1)/2, dat[k] = max(dat[k*2+1], dat[k*2+2]);
  }
  ll find(int a, int b=-1, int k=0, int l=0, int r=-1){
    if(r==-1) r = M;
    if(b==-1) b = M;
    if(r<=a || b<=l) return 0;
    if(a<=l && r<=b) return dat[k];
    ll A = find(a, b, k*2+1, l, (l+r)/2);
    ll B = find(a, b, k*2+2, (l+r)/2, r);
    return max(A, B);
  }
};
//-------------------------------------------------------------------
int main(int argc, char const *argv[]) {
  ld x, y, x2, y2, a, b; std::cin >> x >> y >> x2 >> y2;
  ll n;std::cin >> n;
  vvld f = vv(0, 2, 0, ld);
  ll mode = 0;
  if(x>x2) swap(x, x2), swap(y, y2);
  if(y2>y) mode = 1;
  map<ll, ll> Y;
  for(int i=0;i<n;i++){
    std::cin >> a >> b;
    if(!(min(x, x2)<=a&&a<=max(x, x2)&&min(y, y2)<=b&&b<=max(y, y2))) continue;
    f.push_back(vector<ld> {a, b});
    Y.emplace(b, 0);
  }
  ll c=0, k=0;
  for(auto itr=Y.begin();itr!=Y.end();itr++, c++) (*itr).second=c;
  multimap<ll, ll> num;
  sort(f.begin(), f.end());
  segtree seg(Y.size()+1, 0);

  for(int i=0;i<f.size();i++){
    if(mode==1) c = seg.find(0, Y.at(f[i][1]));
    else c = seg.find(Y.at(f[i][1]), Y.size()+1);
    k = max(k, c+1);
    seg.upd(c+1, Y.at(f[i][1]));
  }
  if((x==x2||y==y2)&&k==1) std::cout << fixed << setprecision(20) << (ld)abs(x2-x)*100.0 + (ld)abs(y2-y)*100.0 + (ld)(10.0*M_PI - 20.0) << '\n';
  else std::cout << fixed << setprecision(20) << (ld)abs(x2-x)*100.0 + (ld)abs(y2-y)*100.0 - (ld)k*(20.0-5.0*M_PI) << '\n';
  return 0;
}

