				LL ans = ((x2 - x1) + (y2 - y1)) * 100 * AA2 - (20 * AA2 - 5 * PI2)*(kazu.size() - 1);
				cout << ans / AA2 << "." << ans%AA2 << endl;
			}
		}
}

