	P(int a, int b):x(a), y(b) {}
	int gtidx() { return lower_bound(mpx.begin(), mpx.end(), x) - mpx.begin(); }
	int gtidy() { return lower_bound(mpy.begin(), mpy.end(), y) - mpy.begin(); }
	void pl(){
		idx = gtidx();
		idy = gtidy();
	}
	void rd() { scanf("%d%d", &x, &y); }
	void psh(){
		mpx.push_back(x);
		mpy.push_back(y);
	}
	void fl(){
		y = -y;
	}
	bool operator <(P const o)const { return idx < o.idx; }
}p[200002];

double s[800010], z[800010];

inline void sl(int id){
	int a = id << 1, b = a | 1;
	s[a] = min(s[a], z[id]);
	s[b] = min(s[b], z[id]);
	z[a] = min(z[a], z[id]);
	z[b] = min(z[b], z[id]);
	z[id] = 1e10;
}

void bld(int l = 0, int r = n + 2, int id = 1){
	if (l + 1 == r) { s[id] = z[id] = 1e10; return; }
	int m = l + r >> 1, a = id << 1, b = a | 1;
	bld(l, m, a);
	bld(m, r, b);
	s[id] = z[id] = 1e10;
}

void up(int x, int y, double v, int l = 0, int r = n + 2, int id = 1){
	if (l >= y || r <= x)return;
	if (l >= x && r <= y) { s[id] = min(s[id], v), z[id] = min(z[id], v); return; }
	sl(id);
	int m = l + r >> 1, a = id << 1, b = a | 1;
	up(x, y, v, l, m, a);
	up(x, y, v, m, r, b);
	s[id] = min(s[a], s[b]);
}

void upH(int i, double v, int l = 0, int r = n + 2, int id = 1){
	if (l + 1 == r) { s[id] = v; return; }
	int m = l + r >> 1, a = id << 1, b = a | 1;
	sl(id);
	if (i < m)upH(i, v, l, m, a);
	else upH(i, v, m, r, b);
	s[id] = min(s[a], s[b]);
}

double gt(int x, int y, int l = 0, int r = n + 2, int id = 1){
	if (l >= y || r <= x)return 1e10;
	if (l >= x && r <= y)return s[id];
	sl(id);
	int m = l + r >> 1, a = id << 1, b = a | 1;
	return min(gt(x, y, l, m, a), gt(x, y, m, r, b));
}

