		tot=max(tot,k);
	}
	ans=abs(ty-sy)+abs(tx-sx);
	ans*=100;
	if(tot==min(abs(sx-tx)+1,abs(sy-ty)+1))
		ans+=5*pi;
	ans-=(double)tot*20;
	ans+=(double)tot*pi/2*10;
	printf("%.20lf",ans);
}

