using namespace std;

const int max_coordinate = 100000000;
const double pi = 3.1415926535897932384626433832795;

vector<pair<int, int>> ps;
pair<int, int> p1;
pair<int, int> p2;
int n;

double solve() {
	vector<pair<int, int>> fs;

	if (p1.first > p2.first) {
		swap(p1, p2);
	}
	fs.reserve(n);
	for (int i = 0; i < n; i++) {
		if (ps[i].first >= p1.first && ps[i].first <= p2.first &&
			ps[i].second >= min(p1.second, p2.second) && ps[i].second <= max(p1.second, p2.second))
		{
			fs.push_back(ps[i]);
		}
	}

	sort(fs.begin(), fs.end());

	set<pair<int, int>> s;
	vector<int> m(fs.size() + 1);
	int fc = 0;

	for (int i = 0; i < (int)fs.size(); i++) {
		int j = -1;

		if (p1.second <= p2.second) {
			set<pair<int, int>>::iterator it = s.lower_bound({ fs[i].second - 1, max_coordinate });
			if (it != s.end()) {
				j = it->second;
			}
		}
		else {
			set<pair<int, int>>::iterator it = s.lower_bound({ max_coordinate - (fs[i].second - 1), max_coordinate });
			if (it != s.end()) {
				j = it->second;
			}
		}

		if (j == -1) {
			m[i] = 1;
		}
		else {
			m[i] = 1 + m[j];
		}

		fc = max(fc, m[i]);

		if (p1.second <= p2.second) {
			s.insert({ fs[i].second, i });
		}
		else {
			s.insert({ max_coordinate - fs[i].second, i });
		}
	}

	double coeff = -(20.0 - pi / 2 * 10);

	if (p1.second == p2.second || p1.first == p2.first) {
		coeff = -(20.0 - pi * 10);
	}

	return 100.0 * (abs(p2.first - p1.first) + abs(p2.second - p1.second)) + coeff * fc;
}

int main() {

	cin >> p1.first >> p1.second >> p2.first >> p2.second;
	cin >> n;
	ps.resize(n);
	for (int i = 0; i < n; i++) {
		cin >> ps[i].first >> ps[i].second;
	}

	cout << fixed << setprecision(18) << solve() << "\n";

	return 0;
}

