struct node
{
	int l,r;
	int maxi;
	node *ls,*rs;
} *root;
int x1,y1,x2,y2;
int st,xx,yy;
int ans;
int n,s=1,cntx,cnty;
vector<pii> f;
map<int,int> lsh;
int dp[maxn][2];

void init(node *p,int l,int r)
{
	p->l=l;p->r=r;
	if (l==r) return;
	p->ls=new node;
	p->rs=new node;

	init(p->ls,l,(l+r)>>1);
	init(p->rs,((l+r)>>1)+1,r);
	return;
}

void clean(node *p)
{
	p->maxi=0;
	if (p->l==p->r) return;
	else 
	{
		clean(p->ls);
		clean(p->rs);
	}
	return;
}

int search(node *p,int l,int r)
{
	if (l>r) return 0;
	if (l<=p->l && p->r<=r) return p->maxi;

	int ans=0;
	if (l<=p->ls->r) ans=max(ans,search(p->ls,l,r));
	if (p->rs->l<=r) ans=max(ans,search(p->rs,l,r));
	return ans;
}

void add(node *p,int index,int pos)
{
	if (p->l==p->r)
	{
		p->maxi=max(p->maxi,index);
		return;
	}

	if (pos<=p->ls->r) add(p->ls,index,pos);
	else add(p->rs,index,pos);
	p->maxi=max(p->ls->maxi,p->rs->maxi);
	return;
}

