		yy*=s;
		if (x1<=xx && xx<=x2 && y1<=yy && yy<=y2)
			f.push_back(mp(xx,yy));
	}

	if (x1==x2 || y1==y2)
	{
		printf("%.15lf\n",(double)st*100.+(double)f.size()*(10.*pi-20.));
		return 0;
	}
	else if (!f.size())
	{
		printf("%.15lf\n",(double)st*100.);
		return 0;
	}

	lsh.clear();
	for(int i=0;i<f.size();i++)
		lsh[f[i].x]=0;
	cntx=0;
	for(map<int,int>::iterator ii=lsh.begin();ii!=lsh.end();ii++)
	{
		cntx++;
		ii->second=cntx;
	}
	for(int i=0;i<f.size();i++)
		f[i].x=lsh[f[i].x];

	lsh.clear();
	for(int i=0;i<f.size();i++)
		lsh[f[i].y]=0;
	cnty=0;
	for(map<int,int>::iterator ii=lsh.begin();ii!=lsh.end();ii++)
	{
		cnty++;
		ii->second=cnty;
	}
	for(int i=0;i<f.size();i++)
		f[i].y=lsh[f[i].y];

	sort(f.begin(),f.end());
	root=new node;
	init(root,1,f.size());

	clean(root);
	for(int i=0;i<f.size();i++)
	{
		dp[i][0]=search(root,1,f[i].y-1)+1;
		add(root,dp[i][0],f[i].y);
	}

	clean(root);
	for(int i=f.size()-1;i>=0;i--)
	{
		dp[i][1]=search(root,f[i].y+1,f.size())+1;
		add(root,dp[i][1],f[i].y);
	}

	ans=0;
	for(int i=0;i<f.size();i++)
		ans=max(ans,dp[i][0]+dp[i][1]-1);

	printf("%.15lf\n",(double)st*100.-(double)ans*(20.-5*pi));
	return 0;
}

