int lis()
{
    memset(dp, 0, sizeof(dp));
    int len = 0;
    for (int i = 1; i <= n; ++i)
    {
        int pos = lower_bound(dp, dp + len, a[i]) - dp;
        if(pos==len)
        {
        	dp[len++]=a[i];
        }
        else
        {
        	dp[pos]=a[i];
        }
        len = max(len, pos + 1);
    }
    return len;
}
