int x1, yy1, x2, y2, n;

double calc(int num)
{
	return 100.0 * (abs(x2 - x1) + abs(y2 - yy1)) - (20.0 - 5.0 * pi) * num;
}

double getans(vector<pair<int, int> > v)
{
	vector<int> result;
	for(int i = 0; i < v.size(); i++){
		if(result.size() == 0 || result[result.size() - 1] < v[i].second){
			result.push_back(v[i].second);
		} else {
			int l = 0, r = result.size();
			while(r - l > 1){
				int mid = (r + l) / 2;
				if(result[mid] > v[i].second) r = mid;
				else l = mid;
			}
			result[l] = v[i].second;
		}
	}
	double ans = calc(result.size());
	if(result.size() == v.size()){
		int maxsub = 0;
		for(int i = 1; i < result.size(); i++){
			maxsub = max(maxsub, result[i] - result[i - 1]);
		}
		if(maxsub == 1) ans += 5.0 * pi - 10.0;
	}
	return ans;
}

bool isin(int x, int y)
{
	return (x >= min(x1, x2) && x <= max(x1, x2) && y >= min(yy1, y2) && y <= max(yy1, y2));
}

int main()
{
	cin >> x1 >> yy1 >> x2 >> y2 >> n;
	vector<pair<int, int> > X, Y;
	for(int i = 0; i < n; i++){
		int tmpx, tmpy;
		cin >> tmpx >> tmpy;
		if(isin(tmpx, tmpy)){
			X.push_back(make_pair(tmpx, tmpy));
			Y.push_back(make_pair(tmpy, tmpx));
		}
	}
	sort(X.begin(), X.end());
	sort(Y.begin(), Y.end());
	if(x1 == x2 || yy1 == y2){
		printf("%.15f\n", 100.0 * (abs(x2 - x1) + abs(y2 - yy1)) - (20.0 - 10.0 * pi) * X.size());
		return 0;
	}
	if((x1 > x2 && yy1 < y2) || (x1 < x2 && yy1 > y2)){
		reverse(X.begin(), X.end());
		reverse(Y.begin(), Y.end());
	}
	printf("%.15f\n", min(getans(X), getans(Y)));
	return 0;
}

