}
int find(int k){
	int l=1,r=t+1,m;
	while (l<r){m=l+r>>1;
		if (k<=q[m]) r=m; else l=m+1; 
	}
	return l;
}
void add(int k){int x=find(k);q[x]=k;if (x>t) t++;}
int main(){
