const double pi = acos(-1.0);

struct node{
    int x, y;
    friend bool operator < (node xx, node yy){
        if(xx.x == yy.x)
            return xx.y  < yy.y;
        return xx.x < yy.x;
    }
}a[201010];
int aa[201000];
int n;
int rem[201010],dp[201010];
int main(){
    node s,e;
    scanf("%d%d%d%d",&s.x,&s.y,&e.x,&e.y);
    scanf("%d",&n);
    for(int i = 1; i <= n; i ++)
        scanf("%d%d",&a[i].x,&a[i].y);
    if(s.x > e.x){
        node tem = s;
        s = e;
        e = tem;
    }
    sort(a+1, a+1+n);
    if(s.y == e.y){
        int ff = 0;
        for(int i = 1; i <= n; i ++)
            if(s.x <= a[i].x && a[i].x <= e.x)
                ff = 1;
        double ans = 0;
        ans = (e.x - s.x) * 100.0;
        ans += ff ? 10*pi-20 : 0;
        printf("%.12f",ans);
    }
    else{
        int cnt = 0;
        if(s.y < e.y){
            int j = 1;
            for(; a[j].x < s.x && j <= n; j ++);
            for(cnt = 0; j <= n && a[j].x <= e.x; j ++){
                if(s.y <= a[j].y && a[j].y <= e.y)
                    aa[cnt++] = a[j].y;
            }
        }
        else{
            int j = n;
            for(; a[j].x > e.x && j > 0; j --);
            for(cnt = 0; j > 0 && a[j].x >= s.x; j --){
                if(s.y >= a[j].y && a[j].y >= e.y)
                    aa[cnt++] = a[j].y;
            }
        }

        dp[1]=aa[0];//长度为一的子序列的末尾最小值  初始化为a[0]
        int maxlen=1;
        for(int i=1; i<cnt; i++)
        {
            int l=0;
            int r=maxlen,mid;
            if(dp[maxlen]<aa[i])
                dp[++maxlen]=aa[i];
            else
            {
                r=maxlen;
                while(l<=r)
                {
                    mid=(l+r)/2;
                    if(dp[mid]<aa[i])
                        l=mid+1;
                    else
                        r=mid-1;
                }
                //找到第一个大于a[i]的数 更新其的值 使其值更小
                dp[l]=aa[i];
            }
        }
        /*  for(int i=0; i<n; i++) 
	        printf("%d ",dp[i]); 
         printf("\n");
         */
        if(cnt==0)
            maxlen = 0;

        int dx = (s.x-e.x) < 0 ? -(s.x-e.x) : (s.x-e.x), dy = s.y-e.y < 0 ?-(s.y-e.y) : s.y-e.y ;
        int pp = min(dx+1, dy+1);
        if(maxlen == pp){
            printf("%.12f",100.0*(dx+dy)+(pp-1)*(5*pi-20)+(10*pi-20));
        }
        else
            printf("%.12f",100.0*(dx+dy)+ maxlen * (5*pi-20));
    }
    return 0;
}

