		for (int i = 0; i < V.size(); i++) V[i].first -= X1;
		X2 -= X1, X1 = 0;
	}
	else {
		for (int i = 0; i < V.size(); i++) V[i].first -= X2;
		X1 -= X2, X2 = 0;
		swap(X1, X2);
	}
	if (Y1 <= Y2) {
		for (int i = 0; i < V.size(); i++) V[i].second -= Y1;
		Y2 -= Y1, Y1 = 0;
	}
	else {
		for (int i = 0; i < V.size(); i++) V[i].second -= Y2;
		Y1 -= Y2, Y2 = 0;
		swap(Y1, Y2);
	}
	long double INF = 10000000000;
	vector<long double> DP(N + 2, INF);
	DP[0] = 0;
	sort(V.begin(), V.end());
	for (int i = 0; i < V.size(); i++) {
		long long it = lower_bound(DP.begin(), DP.end(), V[i].second) - DP.begin();
		DP[it] = V[i].second;
	}
	long double COUNT = 0;
	while (DP[COUNT + 1] < INF) COUNT++;
	if (COUNT < min(X2, Y2) + 1) {
		long double ANS = (X2 + Y2) * 100.0 - COUNT * (20.0 - 5.0 * PI);
		printf("%.15llf\n", ANS);
	}
	else {
		long double ANS = (X2 + Y2) * 100.0 - (COUNT - 1.0) * (20.0 - 5.0 * PI) + 10.0 * PI - 20.0;
		printf("%.15llf\n", ANS);
	}
}

