namespace TreeArray {
  void modify(int t, int v) {
    for (int i = t; i <= cnt; i += i & -i) 
      tree[i] += v;
  }
  int query(int t) {
    int res = 0;
    for (int i = t; i; i -= i & -i) 
      res += tree[i];
    return res;
  }
}

