int lsb(int k) {return k & (-k); }


int que(int pos) {
	pos++;
	int ret = 0;
	for(; pos; pos -= lsb(pos))
		ret = max(aib[pos], ret);
	return ret;
}

void upd(int pos, int val) {
	pos++;
	for(; pos < MX; pos += lsb(pos))
		aib[pos] = max(aib[pos], val);
}


