const double PI = 2 * acos(0);

int dp[200005];
int lis(vector<int> v) {
  if(v.empty()) return 0;
  dp[1] = 0;
  int ret = 1;
  for(int i = 1; i < v.size(); i++) {
    int lhs = 0;
    int rhs = ret;
    while(lhs != rhs) {
      int mid = (lhs+rhs+1)/2;
      if(v[i] > v[mid]) lhs = mid;
      else rhs = mid-1;
    }
    dp[++lhs] = i;
    ret = max(ret, lhs);
  }
  return ret;
}

