    for(int i = 0; i < n; i++) {
      if(l[i].first >= xa && l[i].first <= xb && l[i].second >= ya && l[i].second <= yb) {
        ret -= 20;
        ret += 10 * PI;
      }
    }
  }
  else {
    bool rev = false;
    if(ya > yb) {
      swap(ya, yb);
      rev = true;
    }
    vector<int> v;
    for(int i = 0; i < n; i++) {
