struct Lis
{
    static inline int index_of(const std::vector<int>& as, int x)
    {
        return (int)std::distance(as.begin(), lower_bound(as.begin(), as.end(), x));
    }

    static std::vector<int> solve(const std::vector<int>& a) {
        const int n = (int)a.size();
        const int inf = 1 << 30;
        std::vector<int> A(n, inf);
        std::vector<int> id(n);
        for (int i = 0; i < n; ++i) {
            id[i] = (int)index_of(A, a[i]);
            A[ id[i] ] = a[i];
        }
        int m = *std::max_element(id.begin(), id.end());
        std::vector<int> b(m+1);
        for (int i = n-1; i >= 0; --i)
            if (id[i] == m) b[m--] = a[i];
        return b;
    }
};


