template<typename Monoid>
class SegTree {

//半開区間!!!!!!!!!!!!!!!
public:
    int p = 2;
    vector<Monoid> node;
    using Func = function<Monoid(Monoid,Monoid)>;
    Func pick; Monoid init;//操作と単位元

    SegTree(vector<Monoid> A, string type, Monoid m) {
        if (type == "min") {
            pick = [](Monoid a, Monoid b){return min(a,b);};
        } else if (type == "max") {
            pick = [](Monoid a, Monoid b){return max(a,b);};
        } else if (type == "sum") {
            pick = [](Monoid a, Monoid b){return a + b;};
        }

        init = m;
        while (A.size() > p) p *= 2;
        node = vector<Monoid>(2*p-1,init);

        for (int i = 0;i < A.size();i++) {
            node[p-1+i] = A[i];
        }

        for (int i = p - 2;i >= 0;i--) {
            node[i] = pick(node[i*2+1],node[i*2+2]);
        }
    }

    SegTree(vector<Monoid> A, Func f, Monoid m) {
        pick = f; init = m;
        while (A.size() > p) p *= 2;
        node = vector<Monoid>(2*p-1,init);

        for (int i = 0;i < A.size();i++) {
            node[p-1+i] = A[i];
        }

        for (int i = p - 2;i >= 0;i--) {
            node[i] = pick(node[i*2+1],node[i*2+2]);
        }
    }

    //1点更新
    void update(int i, Monoid v) {
        for (node[(i+=p)-1] = v; i >>= 1;) {
            node[i-1] = pick(node[i*2-1], node[i*2]);
        }
    }

    //1点加算
    void add(int i, Monoid v) {
        update(i, this[i] + v);
    }

    Monoid getval(int start,int end,int k = 0,int l = 0,int r = -1) {
        if (r < 0) r = p;
        if (r <= start || end <= l) {return init;}
        if (start <= l && r <= end) {return node[k];}
        Monoid L,R;
        L = getval(start,end,k*2+1,l,(l+r)/2);
        R = getval(start,end,k*2+2,(l+r)/2,r);
        return {pick(L,R)};
    }

    inline Monoid operator [] (int i) {
        return node[i+p-1];
    }
};

void solve() {
    cout << fixed << setprecision(35);
    int x1, y1, x2, y2; cin >> x1 >> y1 >> x2 >> y2;
    bool rev = false;
    if (x1 > x2) swap(x1, x2), swap(y1, y2);
    if (y1 > y2) rev = true, y1 = 100000000-y1, y2 = 100000000-y2;
    int n; cin >> n;
    vector<pair<int, int>> xy;
    vector<int> Y;
    rep (i, n) {
        int x, y; cin >> x >> y;
        if (rev) y = 100000000-y;
        if (x1 <= x && x <= x2 && y1 <= y && y <= y2) {
            xy.pb({x, y});
            Y.pb(y);
        }
    }
    n = Y.size();
    sort(all(xy));
    sort(all(Y));

    if (n == 0) {
        cout << 100*(x2-x1+y2-y1) << endl;
        return;
    }

    vector<int> to(n); //y座標で何番目か
    {
        vector<int> idx(n); iota(all(idx), 0);
        sort(all(idx), [&](int i, int j){
            return xy[i].second < xy[j].second;
        });
        rep (i, n) to[idx[i]] = i;
    }

    if (x1 == x2) {
        rep (i, n) {
            if (xy[i].first == x1 && y1 < xy[i].second && xy[i].second < y2) {
                cout << (y2-y1) * 100 - 20 + 10 * pi << endl;
                return;
            }
        }
        cout << (y2-y1) * 100 << endl;
        return;
    }

    if (y1 == y2) {
        rep (i, n) {
            if (xy[i].second == y1 && x1 < xy[i].first && xy[i].first < x2) {
                cout << (x2-x1) * 100 - 20 + 10 * pi << endl;
                return;
            }
        }
        cout << (x2-x1) * 100 << endl;
        return;
    }

    SegTree<int> seg(vector<int>(n), "max", 0);
    vector<pair<int, int>> ope;
    rep (i, n) {
        if (ope.size() && xy[i].first != xy[i-1].first) {
            for (auto e : ope) seg.update(e.first, e.second);
            ope.clear();
        }
        ope.pb({to[i], seg.getval(0, lower_bound(all(Y), xy[i].second)-Y.begin())+1});
    }
    for (auto e : ope) seg.update(e.first, e.second);
    int maru = 0;
    rep (i, n) {
        chmax(maru, seg[i]);
    }

    vector<int> X(n); rep (i, n) X[i] = xy[i].first;
    int p = lower_bound(all(X), x1) - X.begin();
    bool yaba1 = true;
    FOR (i, x1, x2+1) {
        if (p == xy.size() || xy[p].first != i) {
            yaba1 = false;
            break;
        }
        if (i != x1) {
            if (xy[p].second < xy[p-1].second) {
                yaba1 = false;
                break;                
            }
        }
        if (xy[p].second <= y1 || y2 <= xy[p].second) {
            yaba1 = false;
            break;
        }
        p++;
    }
    bool yaba2 = true;
    rep (i, n) swap(xy[i].first, xy[i].second);
    sort(all(xy));
    p = lower_bound(all(Y), y1) - Y.begin();
    FOR (i, y1, y2+1) {
        if (p == xy.size() || xy[p].first != i) {
            yaba2 = false;
            break;
        }
        if (i != y1) {
            if (xy[p].second < xy[p-1].second) {
                yaba2 = false;
                break;
            }
        }
        if (xy[p].second <= x1 || x2 <= xy[p].second) {
            yaba2 = false;
            break;
        }
        p++;
    }
    if (yaba1 || yaba2) maru -= 3;

    cout << 100*(x2-x1+y2-y1)-maru*(20-5*pi) << endl;
}

