void solve(int x)
{
	if (!Ans) {mn[++Ans]=x; return;}
	int L=1,R=Ans,mid;
	while (L<=R)
	{
		mid=(L+R)>>1;
		if (mn[mid]<x) L=mid+1;
		else R=mid-1;
	}
	if (L>Ans) mn[++Ans]=x;
	else mn[L]=min(mn[L],x);
}

