int main (int argc, char const* argv[])
{
	int x1,y1,x2,y2;
	scanf("%d %d",&x1,&y1);
	scanf("%d %d",&x2,&y2);

	int n;
	scanf("%d",&n);

	if (x1 > x2)
	{
		swap(x1,x2);
		swap(y1,y2);
	}

	pt.push_back(pii(x1,y1));
	for (int i = 0; i < n; i += 1)
	{
		int x,y;
		scanf("%d %d",&x,&y);

		int mnX = min(x1,x2);
		int mxX = max(x1,x2);
		int mnY = min(y1,y2);
		int mxY = max(y1,y2);

		if (x >= mnX && x <= mxX && y >= mnY && y <= mxY)
			pt.push_back(pii(x,y));
	}

	pt.push_back(pii(x2,y2));

	sort(pt.begin()+1,pt.end()-1);

	n = pt.size();
	for (int i = 1; i < pt.size(); i += 1)
	{
		dist[i] = pii(INF,INF);
	}

	priority_queue<piii,vector<piii>,greater<piii> >q;
	q.push(piii(0,0,0));

	while (!q.empty())
	{
		int dst, qt, v;
		tie(dst,qt,v) = q.top(); q.pop();

		if (v == n-1)
		{
			//printf("S %d %d\n",ans.first,ans.second);

			double dd = 100.0*dst-5.0*M_PI*qt + 2*10*qt;

			if ((y1 == y2 || x1 == x2) && qt)
				dd += 5.0*M_PI;

			printf("%.11f\n",dd);
			break;
		}

		//printf("B = %d | %d %d\n",v,dst,qt);


		{
			int ddst = dst + abs(pt[v].first-pt[n-1].first)+abs(pt[v].second-pt[n-1].second);
			int dqt = qt;

			if (dist[n-1] > pii(ddst,dqt))
			{
				dist[n-1] = pii(ddst,dqt);
				q.push(piii(ddst,dqt,n-1));
			}

			//double dd = 100.0*ddst+5.0*M_PI*dqt;
			//printf("TF %.11f\n",dd);
		}

		int mnX = min(x2,pt[v].first);
		int mxX = max(x2,pt[v].first);
		int mnY = min(y2,pt[v].second);
		int mxY = max(y2,pt[v].second);

		auto pos = lower_bound(pt.begin()+v+1,pt.end()-1,pii(mnX,0));

		while (pos != pt.end()-1)
		{
			pii p = *pos;

			if (p.first > mxX)
				break;

			if (p.second < mnY || p.second > mxY)
			{
				++pos;
				continue;
			}

			int idx = pos-pt.begin();
			int ddst = dst + abs(pt[v].first-p.first)+abs(pt[v].second-p.second);
			int dqt = qt-1;

			if (dist[idx] > pii(ddst,dqt))
			{
				//printf("Trying %d to %d | (%d %d) - (%d %d)\n",v,idx,pt[v].first,pt[v].second,p.first,p.second);
				//printf("DST = %d %d\n",ddst,dqt);

				dist[idx] = pii(ddst,dqt);
				q.push(piii(ddst,dqt,idx));
			}

			++pos;
		}
	}

	return 0;
}

