	for(int i=0;i<n;i++) {
		scanf("%d%d",&a[i].x,&a[i].y);
		if(a[i].x <= x2 && a[i].x >= x1 && 
		(ll)(a[i].y - y1) * (ll)(a[i].y - y2) <= 0)
			a[cnt++] = a[i];
	}
	sort(a, a + cnt, cmp);
    //memset(g, 0, sizeof(g));
    //cout<<cnt<<endl;
    d[1] = a[0], len = 1;//初始化子序列长度为1，最小右边界
    for (int i = 1; i < cnt; i++)
    {
        if (d[len] < a[i])//(如果允许子序列相邻元素相同 g[len]<=a[i],默认为不等）
            j = ++len; //a[i]>g[len],直接加入到g的末尾,且len++
        else
            j = binary_search(a[i], d, 1, len + 1);
        d[j] = a[i];//二分查找,找到第一个比a[i]小的数g[k],并g[k+1]=a[i]
