void normalize(vector<pair<ll,ll>>& v) {
  const int N = (int)v.size();
  vector<pair<ll,int> > t(N);
  {
    REP(i, N) {
      t[i].first = v[i].first;
      t[i].second = i;
    }
    sort(ALL(t));
    int r = 0;
    REP(i, N) {
      r += (i > 0 && t[i - 1].first != t[i].first);
      v[t[i].second].first = r;
    }
  }
  {
    REP(i, N) {
      t[i].first = v[i].second;
      t[i].second = i;
    }
    sort(ALL(t));
    int r = 0;
    REP(i, N) {
      r += (i > 0 && t[i - 1].first != t[i].first);
      v[t[i].second].second = r;
    }
  }
  return;
}

struct BITMAX {
	int n;
	int vs[MAX_N];
	BITMAX(int n) : n(n) {
    clear();
  }
  void clear() {
    memset(vs, 0, sizeof(vs));
  }
	/** [idx, ∞] の範囲の最大値を val で更新しようと試みる */
	void update(int idx, int val) {
		for (int x = idx + 1; x <= n; x += x & -x) vs[x] = max(vs[x], val);
	}

	/** [idx, ∞] の範囲の最大値を取得 */
	int get(int idx) {
		int ma = 0;
		for (int x = idx + 1; x > 0; x -= x & -x) ma = max(ma, vs[x]);
		return ma;
	}

};
