template <typename T>
struct seg_pL {
  // 一点更新、区間取得 1~N
  using F = function<T(T,T)>;
  // f: [](int x, int y){return min(x,y);}
  // g: [](int x, int y){return y;} // 新しい者が常に正しい！

  int n0, n1; const F f, g; const T first_t; vector<T> seg;
  // f: 子の計算 g: 親と子(f)の計算

  seg_pL(int n, const F _f, const F _g, const T& _t) : f(_f), g(_g), first_t(_t) {
    n0 = n, n1 = 1; while(n0 > n1) n1<<=1; seg.assign(2*n1, first_t);
  }

  void set(int k, const T& _t) {seg[k+n1]=_t;} // 1~Nのk番目に値を入れる
  void build() { for(int k=n1-1; k>=0; k--) seg[k] = f(seg[2*k], seg[2*k+1]);}

  void update(int k, const T& t) {
    k += n1; seg[k] = g(seg[k], t); k /= 2;
    while(k > 0) {seg[k] = g(seg[k], f(seg[2*k], seg[2*k+1])); k /= 2;}
    //cout << seg << endl;
  }

  T query(int a, int b, int k, int l, int r) { // (0, 4+1)
    if (r<=a || l>=b) return first_t;
    if (a<=l && r<=b) return seg[k];
    else {
      T q1 = query(a, b, 2*k, l, (l+r)/2);
      T q2 = query(a, b, 2*k+1, (l+r)/2, r);
      //cout << q1 << " " << q2 << endl;
      return f(q1, q2);
    }
  }

  T query(int a, int b) {
    return query(a, b, 1, 0, n1);
  }
};

int main(){
  ld x1,y1,x2,y2; cin>>x1>>y1>>x2>>y2;
  if (x1>x2) swap(x1,x2); if (y1>y2) swap(y1,y2);
  int n; cin>>n;
  vector<int> f,g;
  for(int i=0;i<n;i++) {
    int a,b; cin>>a>>b;
    if (x1 <= a && a <= x2 && y1 <= b && b <= y2) {
      f.push_back(a); g.push_back(b);
    }
  }
  n = f.size();
  int a[n],b[n],c[n],d[n];
  for(int i=0;i<n;i++) {
    a[i]=f[i]; b[i]=g[i];
  }

  copy(a,a+n,c); copy(b,b+n,d);
  sort(c,c+n); sort(d,d+n);

  seg_pL<int> se(n, [](int x, int y){return max(x,y);}, [](int x,int y){return y;}, 0);
  P e[n];
  for(int i=0;i<n;i++) {
    e[i] = {lower_bound(c,c+n,a[i])-c, lower_bound(d,d+n,b[i])-d};
  }
  sort(e,e+n);

  for(int i=0;i<n;i++) {
    int p = e[i].second;
    int mx = se.query(0, p+1);
    se.update(e[i].second, mx+1);
  }
  ld mu;
  if (x1==x2 || y1==y2) {
    mu = (ld)20.0 - (ld)10.0*PI;
    mu *= n;
  } else {
    mu = (ld)20.0 - (ld)5.0*PI;
    mu *= (ld)se.query(0, n);
  }
  cout.precision(20);
  cout<<abs(x2-x1)*(ld)100+abs(y2-y1)*(ld)100-mu<<endl;
}

