#include <bits/stdc++.h>
using namespace std;
const int N = 400005;
const int T8 = 100000000;
const long double PI = 3.14159265358979323846264338327950288419716939937510L;

struct point {
	int x, y;
	point(int x=0, int y=0): x(x), y(y) {}
	bool operator < (const point& p) const {
		return x < p.x;
	}
};

int n;
point a, b, p[N];
int lis[N], size;

int main() {
	// printf("%.50lf\n", PI);
	scanf("%d%d%d%d", &a.x, &a.y, &b.x, &b.y);
	scanf("%d", &n);
	for (int i = 0; i < n; ++i)
		scanf("%d%d", &p[i].x, &p[i].y);
	sort(p, p + n);
	if (a.x > b.x) swap(a, b);
	long double ans = 100.0L * (abs(1ll*a.x - b.x) + abs(1ll*a.y - b.y));
	int mx = min(a.x, b.x);
	int Mx = max(a.x, b.x);
	int my = min(a.y, b.y);
	int My = max(a.y, b.y);
	// special cases
	if (a.x == b.x) {
		for (int i = 0; i < n; ++i) {
			if (p[i].x == a.x) {
				// cout << "here" << endl;
				if (my < p[i].y && p[i].y < My) {
					ans += 10*PI - 20;
				}
				break;
			}
		}
	} else if (a.y == b.y) {
		for (int i = 0; i < n; ++i) {
			if (p[i].y == a.y) {
				if (mx < p[i].x && p[i].x < Mx) {
					ans += 10*PI - 20;
				}
				break;
			}
		}
	} else {
		for (int i = 0; i < n; ++i) {
			if (p[i].x < mx || p[i].x > Mx || p[i].y < my || p[i].y > My) {
				continue;
			}
			int y = abs(p[i].y - a.y);
			int lb = lower_bound(lis, lis + size, y) - lis;
			lis[lb] = y;
			if (lb == size) ++size;
		}
		ans += size * (5*PI - 20);
	}
	cout.precision(15);
	cout << fixed <<  ans << endl;
}

