			return 0;			
		}
		if (xs <= xx && xx <= xt){
			if ((ys <= yy && yy <= yt) || (ys >= yy && yy >= yt))
				q.pb(mp(xx, yy));
		}
	}
	if (ys > yt){
		for(int i = 0; i < q.size(); ++i)
			q[i].second *= -1;
	}
