typedef long double ldouble;

using namespace std;

const int MAX_VERTEX = 1 << 18;

struct fountain {
  int x, y;

  fountain () {}

  fountain (int _x, int _y) {
    x = _x;
    y = _y;
  }
};

bool ltr (fountain p, fountain q) {
  return p.x < q.x;
}

bool rtl (fountain p, fountain q) {
  return p.x > q.x;
}

class fenwick {
  int *tree;

public:
  fenwick () {
    tree = new int [MAX_VERTEX];

    for (int i = 0; i < MAX_VERTEX; i++) {
      tree[i] = 0;
    }
  }

  void set (int index, int val) {
    for (int i = index; i < MAX_VERTEX; i += i & -i) {
      tree[i] = min(tree[i], val);
    }
  }

  int get (int index) {
    int ans = 0;
    for (int i = index; i != 0; i -= i & -i) {
      ans = min(ans, tree[i]);
    }

    return ans;
  }
};

bool between (int left, int right, int x) {
  return (min(left, right) <= x) && (x <= max(left, right));
}

