    if (between(startx, endx, x) &&
        between(starty, endy, y)) {
      cmpr[y] = 0;
      fountains.push_back(fountain(x, y));
    }
  }

  if (startx == endx || starty == endy) {
    int turnc = fountains.size();

    ldouble ans = abs(startx - endx) * 100.0L +
      abs(starty - endy) * 100.0L +
      turnc * (10 * M_PI - 20);

    cout << fixed << setprecision(12) << ans << endl;
    return 0;
  }


  int cur = 1;
  for (auto i = cmpr.begin(); i != cmpr.end(); i++) {
    i->second = cur;
    cur++;
  }

  if (startx < endx) {
    sort(fountains.begin(), fountains.end(), ltr);
  } else {
    sort(fountains.begin(), fountains.end(), rtl);
  }

  fenwick dp;
  for (int i = 0; i < (int) fountains.size(); i++) {
    dp.set(cmpr[fountains[i].y], dp.get(cmpr[fountains[i].y]) - 1);
  }

