LL search(LL k){
	LL l = 1, r = cnt, mid;
	while (l < r){
		mid = (l + r) >> 1;
		if (k <= X[mid]) r = mid;
		else l = mid + 1;
	}
	return l;
}

bool cmp(LL a, LL b){
	return y[a] < y[b];
}

void update(LL x, LL y){
	for (; x<=cnt; x+=lowbit(x)) c[x] = max(c[x], y);
}

LL query(LL x){
	LL res = 0;
	for (; x; x-=lowbit(x)) res = max(res, c[x]);
	return res;
}

signed main(){
