int main() {
    bool swaped = 0;
    scanf("%d%d%d%d%d" , &s.first,  &s.second , &t.first , &t.second , &n);
    int dd = abs(s.first - t.first) + abs(s.second - t.second);
    if (s.second == t.second) {
        swaped = 1;
        swap(s.first , s.second);
        swap(t.first , t.second);
    }
    if (s > t) {
        swap(s , t);
    }

    for (int i = 0 ; i < n ; ++ i) {
        scanf("%d%d" , &a[i].first , &a[i].second);
        if (swaped) {
            swap(a[i].first , a[i].second);
        }
    }
    sort(a , a + n);

    if (s.first == t.first) {
        bool find = 0;
        double res = dd * 100.0;
        for (int i = 0 ; i < n ; ++ i) {
            if (a[i].first == s.first &&
                s.second < a[i].second && a[i].second < t.second) {
                find = 1;
                break;
            }
        }
        if (find) res += 10 * pi - 20;
        printf("%f\n" , res);
        return 0;
    }

    if (t.second < s.second) {
        s.second = -s.second;
        t.second = -t.second;
        for (int i = 0 ; i < n ; ++ i) {
            a[i].second = -a[i].second;
        }
    }
    d[D ++] = s.second;
    d[D ++] = t.second;
    for (int i = 0 ; i < n ; ++ i) {
        d[D ++] = a[i].second;
    }
    sort(d , d + D);
    D = unique(d , d + D) - d;

    s.second = lower_bound(d , d + D , s.second) - d + 1;
    t.second = lower_bound(d , d + D , t.second) - d + 1;
    for (int i = 0 ; i < n ; ++ i) {
        a[i].second = lower_bound(d , d + D , a[i].second) - d + 1;
    }

    for (int i = 0 ; i < n ; ++ i) {
        f[i] = -1 << 30;
        if (a[i].first >= s.first && a[i].second >= s.second) {
            f[i] = 0;
        }
    }
    memset(c , 0xC0 , sizeof(c));
    int res = 0;
    for (int i = 0 ; i < n ; ++ i) {
        //printf("%d %d\n" , a[i].first , a[i].second);
        for (int j = a[i].second ; j > 0 ; j -= j & -j) {
            f[i] = max(f[i] , c[j]);
        }
        if (a[i].first <= t.first && a[i].second <= t.second) {
            res = max(res , ++ f[i]);
        }
        for (int j = a[i].second ; j <= D ; j += j & -j) {
            c[j] = max(c[j] , f[i]);
        }
    }
    __float128 ans = res * (5 * pi - 20);
    __float128 dis = 100.0;
    dis *= dd;
    ans += dis;

    printf("%f\n" , (double)ans);
}

