#define MAXT (1 << 20)

struct seg {
	int val;
	seg() : val(0) {}
	void merge(const seg& v1, const seg& v2) {
		val = max(v1.val, v2.val);
	}
};

seg tree[MAXT * 2];

void update(int ql, int qr, int val, int v = 1, int l = 0, int r = MAXT - 1) {
	if (qr < l || r < ql) return;
	if (ql <= l && r <= qr) {
		tree[v].val = max(tree[v].val, val);
		return;
	}
	int m = (l + r) / 2;
	update(ql, qr, val, v + v, l, m);
	update(ql, qr, val, v + v + 1, m + 1, r);
	tree[v].merge(tree[v + v], tree[v + v + 1]);
}

seg get(int ql, int qr, int v = 1, int l = 0, int r = MAXT - 1) {
   if (qr < l || r < ql) return seg();
   if (ql <= l && r <= qr) return tree[v];
   int m = (l + r) / 2;
   seg t1 = get(ql, qr, v + v, l, m);
   seg t2 = get(ql, qr, v + v + 1, m + 1, r);
   seg res;
   res.merge(t1, t2);
	return res;
}

