#define double long double
const int N = 2e5 + 10;
const int inf = 0x3f3f3f3f;
const double pi = acos(-1);
struct poi {
	int x, y;
	poi(int _x = 0, int _y = 0) {x = _x, y = _y;}
	inline bool operator < (const poi &a) const {
		return x == a.x ? y < a.y : x < a.x;
	}
} p[N];
int n, xs, ys, xt, yt, top, stk[N]; double ans;

inline int max(int a, int b) {return a > b ? a : b;}
inline int min(int a, int b) {return a < b ? a : b;}
template <class T> inline void in(T &x) {
	x = 0; int f = 1; char ch = getchar();
	for (; ch<'0' || ch>'9';) {if (ch=='-') f=-1; ch = getchar();}
	for (; ch>='0' && ch<='9';) x = x*10 + ch-'0', ch = getchar();
	x *= f;
}

inline void init() {
	in(xs), in(ys), in(xt), in(yt), in(n);
	for (int i = 1; i <= n; ++i) in(p[i].x), in(p[i].y);
	if (xs > xt) {
		xs = inf - xs, xt = inf - xt;
		for (int i = 1; i <= n; ++i) p[i].x = inf - p[i].x;
	}
	if (ys > yt) {
		ys = inf - ys, yt = inf - yt;
		for (int i = 1; i <= n; ++i) p[i].y = inf - p[i].y;
	}
	for (int i = n; i; -- i)
		if (p[i].x < xs || p[i].x > xt || p[i].y < ys || p[i].y > yt)
			p[i] = p[n--];
}

inline void work() {
	int l, r, mid;
	sort(p + 1, p + n + 1);
	for (int i = 1; i <= n; ++i) {
		for (l = 1, r = top + 1; l < r;) {
			mid = l + r >> 1;
			if (stk[mid] > p[i].y) r = mid;
			else l = mid + 1;
		}
		stk[l] = p[i].y, top = max(top, l);
	}
	ans = ((double)xt - xs + yt - ys) * 100.0 + top * (5 * pi - 20);
	if (top == min(xt - xs, yt - ys) + 1) ans += 5 * pi;
	printf("%.15Lf\n", ans);
}

int main() {init(), work(); return 0;}

