int n;


void update(int ss, int se, int cur, int up, int spot) {
	if (spot < ss || se < spot || ss > se) return;
	if (ss == se && ss == spot) {
		seg[cur] = up;
		return;
	}
	int mid = (ss+se)/2;
	update(ss, mid, cur*2+1, up, spot);
	update(mid+1, se, cur*2+2, up, spot);
	seg[cur] = max(seg[cur*2+1], seg[cur*2+2]);
}

void upd(int val, int spot) {
	update(0, n-1, 0, val, spot);
}

int qu(int qs, int qe, int ss, int se, int cur) {
	if (qe < ss || se < qs) return -1;
	// cout << "   " << ss << " " << se << endl;

	if (qs <= ss && se <= qe) return seg[cur];
	int mid = (ss+se)/2;
	return max(qu(qs, qe, ss, mid, cur*2+1), 
		qu(qs, qe, mid+1, se, cur*2+2));
}


int query(int qs, int qe) {
	return qu(qs, qe, 0, n-1, 0);
}

