using namespace std;
typedef pair <int, int> pii;
pii p[200010];
struct node
{
    node* l;
    node* r;
    int val;
    node():l(NULL),r(NULL),val(0){}
};
node* t;
int getval(node* t)
{
    if (t==NULL) return 0;
    return t->val;
}
void update(node* t,int l, int r, int pos, int val)
{
    if (l==r)
    {
        t->val=val;
        return;
    }
    int m=(l+r)/2;
    if (pos<=m)
    {
        if (t->l==NULL) t->l=new node();
        update(t->l,l,m,pos,val);
    }
    else
    {
        if (t->r==NULL) t->r=new node();
        update(t->r,m+1,r,pos,val);
    }
    t->val=max(getval(t->l),getval(t->r));
}
int query(node* t, int l, int r, int L, int R)
{
    if (L>R) return 0;
    if (l==L && r==R)
        return t->val;
    if (t->l==NULL) t->l=new node();
    if (t->r==NULL) t->r=new node();
    int m=(l+r)/2;
    return max(query(t->l,l,m,L,min(m,R)),query(t->r,m+1,r,max(m+1,L),R));
}
