      Y[i]=MX-Y[i];
    }
  }
  static pair<int,int> P[200000];
  int N=0;
  for(int i=0;i<n;i++){
    if(x1<=X[i]&&X[i]<=x2&&y1<=Y[i]&&Y[i]<=y2){
      P[N]=make_pair(X[i],Y[i]);
      N++;
    }
  }
  P[N]=make_pair(x1,y1);
  N++;
  P[N]=make_pair(x2,y2);
  N++;
  if(x1==x2){
    printf("%.15lf\n",(y2-y1)*100.+(N>2?10.*Pi-20:0));
    return 0;
  }
  if(y1==y2){
    printf("%.15lf\n",(x2-x1)*100.+(N>2?10.*Pi-20:0));
    return 0;
  }
  sort(P,P+N);
  static int YY[200000];
  for(int i=0;i<N;i++){
    YY[i]=P[i].second;
  }
  sort(YY,YY+N);
  double ans=-INF;
  static double seg[1<<(BS+1)];
  double d1=(20.-10.*Pi/2),d2=10.*Pi-20;
  for(int i=0;i<1<<(BS+1);i++){
    seg[i]=-INF;
  }
  for(int i=0;i<N;i++){
    int k=lower_bound(YY,YY+N,P[i].second)-YY;
    double s1,s2;
    if(P[i].first==x1&&P[i].second==y1){
      s1=s2=0;
    }
    else if(P[i].first==x1){
      s1=d1;
      s2=-d2;
    }
    else if(P[i].second==y1){
      s1=-d2;
      s2=d1;
    }
    else{
      double m1=segmax(seg,1,0,1<<18,0,2*k);
      double m2=segmax(seg,1,0,1<<18,0,2*k+1);
      s1=m1+d1;
      s2=m2+d1;
    }
    if(P[i].first>x1+1){
      s2=max(s2,0.);
    }
    if(P[i].second>y1+1){
      s1=max(s1,0.);
    }
    //printf("%d %d %lf %lf %d\n",P[i].first,P[i].second,s1,s2,k);
    segset(seg,2*k,s1);
    segset(seg,2*k+1,s2);
    if(P[i].first==x2&&P[i].second==y2){
      ans=max(ans,max(s1-d1,s2-d1));
      break;
    }
    if(P[i].first==x2){
      ans=max(ans,s1-d1-d2);
    }
    if(P[i].second==y2){
      ans=min(ans,s2-d1-d2);
    }
    if(P[i].first<x2-1){
      ans=min(ans,s1);
    }
    if(P[i].second<y2-1){
      ans=min(ans,s2);
    }
  }
  //printf("%d\n",ans);
  printf("%.15lf\n",100.*(y2-y1+x2-x1)-ans);
  return 0;
}

