        swap(z[0], z[1]);
        swap(t[0], t[1]);
    }
    if (t[0] > t[1]) {
        t[0] *= -1, t[1] *= -1;
        FOR(i, 0, n) y[i] *= -1;
    }
    vii v;
    FOR(i, 0, n) {
        if (x[i] >= z[0] && x[i] <= z[1] && y[i] >= t[0] && y[i] <= t[1]) {
            v.pb(mp(x[i], y[i]));
        }
    }
    sort(all(v));
    n = sz(v);
    vi dc;
    FOR(i, 0, sz(v)) {
        x[i] = v[i].fi;
        y[i] = v[i].se;
        dc.pb(x[i]);
        dc.pb(y[i]);
    }
    sort(all(dc)), uni(dc);
    if (z[0] == z[1] || t[0] == t[1]) {
        cout << prec(15) << ans + (long double) n * (10 * PI - 20) << "\n";
        return;
    }
    int x = 0;
    FOR(i, 0, n) {
        int iy = lower_bound(all(dc), y[i]) - dc.begin();
        int mx = query(iy);
        upd(iy, mx + 1);
        chkmax(x, mx + 1);
    }
    if (x < min(z[1] - z[0], t[1] - t[0]) + 1) {
        cout << prec(15) << ans - (long double) x * (20 - 10 * PI / 2) << "\n";
    }
    else {
        cout << prec(15) << ans - (long double) (x - 1) * (20 - 10 * PI / 2) + (10 * PI - 20) << "\n";
    }
}

