const double PI = acos(-1);
const double nya = 20.0 - 5.0 * PI;
const double tapi= 10 * PI - 20.0;

void solve(){

  #define x first
  #define y second
  P s,g; in(s , g);
  ini(N);
  vp v(N); in(v);
  if(s.x > g.x) swap(s , g);
  if(s.y > g.y){
    s.y *= -1 , g.y *= -1;
    each(p , v) p.y *= -1;
  }

  {
    vp a;
    each(p , v){
      if(s.x <= p.x && p.x <= g.x && s.y <= p.y && p.y <= g.y) a.pb(p);
    }
    v.swap(a);
  }

  if(s.x == g.x){
    exit(1);
    int cnt = 0;
    each(p , v){
      if(p.x == s.x) cnt++;
    }
    die((g.y - s.y) * 100.0 + tapi);
  }
  if(s.y == g.y){
    exit(1);
    int cnt = 0;
    each(p , v){
      if(s.y == p.y) cnt++;
    }
    die((g.x - s.x) * 100.0 + tapi);
  }

  sort(all(v));
  // 単調増加列
  vl dp;
  each(p , v){
    auto it = lower_bound(all(dp) , p.se);
    if(it == dp.end()) dp.pb(p.se);
    else *it = p.se;
  }
  trc(dp.size());
  int cnt = min( (ll)sz(dp) , min( g.y - s.y , g.x - s.x) );
  out( (g.x + g.y - s.x - s.y) * 100.0 - cnt * nya + (sz(dp) - cnt) * tapi);


}

