int dat[NODES],lind[NODES],rind[NODES],lrange[NODES],rrange[NODES],last = 1;

void create(int k){
	lind[k] = last;
	rind[k] = last + 1;
	lrange[last] = lrange[k];
	rrange[last] = (lrange[k] + rrange[k]) / 2;
	lrange[last + 1] = (lrange[k] + rrange[k]) / 2;
	rrange[last + 1] = rrange[k];
	last += 2;
}

void update(int i,int x,int k){
	dat[k] = max(dat[k],x);
	if(rrange[k] - lrange[k] == 1) return;
	if(lind[k] == -1) create(k);
	if(lrange[lind[k]] <= i && i < rrange[lind[k]]) update(i,x,lind[k]);
	else update(i,x,rind[k]);
}

int get(int a,int b,int k){
	if(b <= lrange[k] || rrange[k] <= a) return 0;
	if(a <= lrange[k] && rrange[k] <= b) return dat[k];
	if(lind[k] == -1) create(k);
	return max(get(a,b,lind[k]),get(a,b,rind[k]));
}


