  int x1, y1, x2, y2;
  cin >> x1 >> y1 >> x2 >> y2;
  int n;
  cin >> n;
  vector<int> x(n), y(n);
  REP(i, n) cin >> x[i] >> y[i];

  if(x2 < x1) {
    swap(x1, x2);
    swap(y1, y2);
  }
  if(y2 < y1) {
    y1 *= -1, y2 *= -1;
    REP(i, n) y[i] *= -1;
  }

  vector<PII> vp;
  REP(i, n) {
    if(x1 <= x[i] && x[i] <= x2 && y1 <= y[i] && y[i] <= y2) {
      vp.push_back({x[i], y[i]});
    }
  }
  sort(ALL(vp));
  vector<int> ny;
  REP(i, vp.size()) ny.push_back(vp[i].second);

  // nyのLISを求める
  vector<int> dp(ny.size(), INF);
  REP(i, ny.size()) {
    *lower_bound(ALL(dp), ny[i]) = ny[i];
  }
  int lis = lower_bound(ALL(dp), INF) - dp.begin();

  // cout << ma << endl;
  long double PI = acos(-1);
  long double ans = 100 * (ll)(x2-x1) + 100 * (ll)(y2-y1);
  ans += lis * (5*PI-20);
  if(lis == min(x2-x1,y2-y1)+1) ans += 5*PI;

  cout << fixed << setprecision(15) << ans << endl;

  return 0;
}

