		if (Xl <= x && x <= Xr && Yl <= y && y <= Yr) {
			++m; p[m].x = x - Xl; p[m].y = y - Yl;
		}
	}
	int h = Xr - Xl, w = Yr - Yl;
	if (Xs > Xt) {
		for (int i = 1; i <= m; ++i) p[i].x = h - p[i].x;
	}
	if (Ys > Yt) {
		for (int i = 1; i <= m; ++i) p[i].y = w - p[i].y;
	}
	tbX[++tbX[0]] = 0; tbY[++tbY[0]] = 0;
	for (int i = 1; i <= m; ++i) tbX[++tbX[0]] = p[i].x, tbY[++tbY[0]] = p[i].y;
	tbX[++tbX[0]] = h; tbY[++tbY[0]] = w;
	sort(tbX + 1, tbX + tbX[0] + 1);
	tbX[0] = unique(tbX + 1, tbX + tbX[0] + 1) - tbX - 1;
	sort(tbY + 1, tbY + tbY[0] + 1);
	tbY[0] = unique(tbY + 1, tbY + tbY[0] + 1) - tbY - 1;
	for (int i = 1; i <= m; ++i) p[i].x = hs(tbX, p[i].x), p[i].y = hs(tbY, p[i].y);
	h = hs(tbX, h); w = hs(tbY, w);
	sort(p + 1, p + m + 1); int X = 1, Y = 1;
	for (int i = 1; i <= m; ++i) {
		f[i] = gmx(p[i].y - 1) + 1; add(p[i].y, f[i]);
		if (p[i].x == h) Y = max(Y, p[i].y); if (p[i].y == w) X = max(X, p[i].x); 
	}
	double ret = m == max(h, w) ? -(pi * 10 - 20) : 0;
	for (int i = 1; i <= m; ++i) {
		ret = max(ret, (20.0 - pi * 5) * f[i] - (pi * 10 - 20)); 
		if (tbX[p[i].x] + 1 < tbX[h] || tbY[p[i].y] + 1 < tbY[w] || (p[i].y < w && p[i].x >= X) || (p[i].x < h && p[i].y >= Y) || p[i].x > X || p[i].y > Y) ret = max(ret, (20 - pi * 5) * f[i]);
	}
	return printf("%.10lf\n", 100.0 * (tbX[h] + tbY[w]) - ret), 0;
}

