		REP(i, n) {
			int a, b;
			cin >> a >> b;
			if (x_swap == 1) {
				a = (x1 - a) + x1;
			}
			if (y_swap == 1) {
				b = (y1 - b) + y1;
			}
			if (b == y1&&x1 <= a&&a <= x2) {
				double hoge = Ma_PI * (double)10.0000000000000000000;
				hoge -= (double)20.0000000000000000000;
				ans += hoge;
			}
		}
		cout << ans << endl;
		return 0;
	}
	double pre_ans = 5.0000000000000000000*Ma_PI;
	REP(i, n) {
		int a, b;
		cin >> a >> b;
		if (x_swap == 1) {
			a = (x1 - a) + x1;
		}
		if (y_swap == 1) {
			b = (y1 - b) + y1;
