		gekogeko.push_back(prego[i].second);
	}
	sort(gekogeko.begin(), gekogeko.end());
	if (prego.size() == y2 - y1+1) {
		int failed = false;
		for (int q = 0;q < prego.size();++q) {
			if (prego[q].second != y1 + q) failed = true;
		}
		if (failed == true) {
