};

const ld pi = acos(-1.0L);

using Data = int;
const Data INF = 1000000000;

vector<Data> lis(const vector<Data>& a) {
  const int n = a.size();
  if (n == 0) return vector<Data>(0);
  vector<Data> A(n, INF);
  vector<int> id(n);
  for (int i = 0; i < n; i++) {
    id[i] = distance(A.begin(), lower_bound(A.begin(), A.end(), a[i]));
    A[id[i]] = a[i];
  }
  int m = *max_element(id.begin(), id.end());
  vector<Data> res(m + 1);
  for (int i = n - 1; i >= 0; i--)
    if (id[i] == m) res[m--] = a[i];
  return res;
}

void solve(vector<ll> x, vector<ll> y, ll N, vector<ll> X, vector<ll> Y) {
  int l = min(x[0], x[1]);
  int r = max(x[0], x[1]);
  int t = min(y[0], y[1]);
  int b = max(y[0], y[1]);
  vector<pair<int,int>> point;
  REP(i,N) {
    if (l <= X[i] && X[i] <= r && t <= Y[i] && Y[i] <= b) {
      point.emplace_back(abs(X[i] - x[0]), abs(Y[i] - y[0]));
    }
  }
  sort(ALL(point));
  vector<int> ys;
  for (auto p: point) ys.push_back(p.second);
  auto v = lis(ys);
  ld res = ((r - l) + (b - t)) * 100.00L;
  if (v.empty()) { cout << res << endl; }
  else{
    int n = v.size();
    chmin(n, r - l);
    chmin(n, b - t);
    res += (5 * pi - 20) * n;
    if (r - l < int(v.size()) || b - t < int(v.size())) {
      res += 10 * pi - 20;
    }
    cout << res << endl;
  }
}

