const double PI = 2 * acos(0);

int dp[200005];
int lis(vector<int> v) {
  if(v.empty()) return 0;
  dp[1] = 0;
  int ret = 1;
  for(int i = 1; i < v.size(); i++) {
    int lhs = 0;
    int rhs = ret;
    while(lhs != rhs) {
      int mid = (lhs+rhs+1)/2;
      if(v[i] > v[mid]) lhs = mid;
      else rhs = mid-1;
    }
    dp[++lhs] = i;
    ret = max(ret, lhs);
  }
  return ret;
}

pii l[200005];
void solve() {
  int xa, ya, xb, yb;
  cin >> xa >> ya >> xb >> yb;
  int n;
  cin >> n;
  for(int i = 0; i < n; i++) {
    cin >> l[i].first >> l[i].second;
  }
  sort(l, l+n);
  double ret = 0;
  if(xa > xb) {
    swap(xa, xb);
    swap(ya, yb);
  }
  ret = fabs(xa-xb) + fabs(ya-yb);
  ret *= 100;
  bool rev = false;
  if(ya > yb) {
    swap(ya, yb);
    rev = true;
  }
  vector<int> v;
  for(int i = 0; i < n; i++) {
    if(l[i].first >= xa && l[i].first <= xb && l[i].second >= ya && l[i].second <= yb) {
      v.push_back(l[i].second);
    }
  }
  if(rev) reverse(v.begin(), v.end());
  int amt = lis(v);
  ret -= 20 * amt;
  ret += 5 * amt * PI;
  if(amt == min(yb-ya, xb-xa) + 1) {
    ret += 5 * PI;
  }
  cout << fixed << setprecision(13) << ret << "\n";
}

