//----------------LIS---------------------
int len;
LL a[MaxN + 5], d[MaxN + 5];

int bin_search(LL x) {
    int l = 0, r = len;
    int mid = 0, ans = 0;
    while(l <= r) {
        mid = (l + r) >> 1;
        if(d[mid] >= x) ans = mid, r = mid - 1;
        else l = mid + 1;
    }
    return ans;
}

void get_LIS(bool c)
{
    len = 0;
    d[len] = -INF;
    //初始d[0] == 0的,如果LIS中有0,就会少算一个
    if(c == 1) {
        for(int i = 1; i <= tot; i++) 
            a[i] = tmp[i].y;
    }
    else {
        //求下降时将数组倒过来求最长
        for(int i = 1; i <= tot; i++)
            a[i] = tmp[tot - i + 1].y;
    }
    for(int i = 1; i <= tot; i++) {
        if(a[i] > d[len]) d[++len] = a[i];
        else {
            int pos = bin_search(a[i]);
            d[pos] = a[i];
        }
    }
}
