        //取最长下降子序列
        get_LIS(0);
    }
    else if(sy <= ty) {
        //取最长上升子序列
        get_LIS(1);
    }
    int num = min(abs(tx - sx), abs(ty - sy)) + 1;
    if(len == num) {
        //肯定会直线经过一个喷泉,其他都是拐角
