double cnt[1<<19];

void lazy_eval(int k){
	cnt[k]=max(cnt[k],lazy[k]);
	if(k<n_-1){
		lazy[k*2+1]=max(lazy[k*2+1],lazy[k]);
		lazy[k*2+2]=max(lazy[k*2+2],lazy[k]);
	}
	lazy[k]=-1e21;
}

void lazy_upd(int k){
	cnt[k]=max(cnt[k*2+1],cnt[k*2+2]);
}

void update(int a,int b,double x,int k=0,int l=0,int r=n_){
	lazy_eval(k);
	if(b<=l || r<=a)return;
	if(a<=l && r<=b){
		lazy[k]=max(lazy[k],x);
		lazy_eval(k);
		return;
	}
	update(a,b,x,k*2+1,l,(l+r)/2);
	update(a,b,x,k*2+2,(l+r)/2,r);
	lazy_upd(k);
}

double query(int a,int b,int k=0,int l=0,int r=n_){
	lazy_eval(k);
	if(b<=l || r<=a)return -1145141;
	if(a<=l && r<=b)return cnt[k];
	double vl=query(a,b,k*2+1,l,(l+r)/2);
	double vr=query(a,b,k*2+2,(l+r)/2,r);
	lazy_upd(k);
	return max(vl,vr);
}

