int calcLis()
{
	cerr << "calcLis called\n";
	for (int i = 1; i <= pp.size() + 10; i++)
		d[i] = 1e9;
	d[0]= -1;
	int ans = 0;
	for (pii p : pp) {
		int l = 0, r = ans;
		while (l < r) {
			int m = (l + r + 1)/2;
			if (p.second > d[m])
				l= m;
			else
				r = m-1;
		}
		if (d[l+1] > p.second) {
			d[l+1] = p.second;
			ans = max(ans, l+1);
		}
	}
	cerr << "calcLis completed\n ans = " << ans << "\n";
	return ans;
}

