const int maxn=1000000+16;

struct Point
{
	int x,y;
	void readin()
	{
		cin>>x>>y;
	}
};

int n;
Point p[maxn];
Point src,dst;
int m;

double cost=10.0*pi-10.0*2.0;
double save=10.0*2.0-10.0*pi/2.0;

double w1[maxn],w2[maxn];
int my[maxn];

void update(double w[],int p,double d)
{
	for (;p<=m;p=(p|(p-1))+1) ckmin(w[p],d);
}
double getw(double w[],int p)
{
	double ret=1e100;
	for (;p>0;p&=(p-1)) ckmin(ret,w[p]);
	return ret;
}
double solve()
{
	m=dst.y;
	if (n==0) return 0.0;
	REP(i,m+1) w1[i]=w2[i]=1e100;
	sort(p,p+n,[](const Point& a,const Point& b) { return a.x<b.x; });
	double ret=1e100;
	my[n]=-1;
	for (int i=n-1;i>=0;i--) my[i]=max(my[i+1],p[i].y);
	queue<pair<int,pair<int,double>>> q1;
	int gy=1000000000;
	REP(i,n)
	{
		int key=p[i].y;
		ckmin(gy,p[i].y);
		double t1=1e100;
		double t2=1e100;
		if (gy==p[i].y)
		{
			if (p[i].x!=src.x) 
				t2=-save;
			else
				t2=cost;
			if (p[i].y!=src.y) 
				t1=-save;
			else
				t1=cost;
		}
		else
		{
			double t3=1e100;
			double t4=1e100;
			if (p[i].x==src.x)
				t4=0;
			else if (p[i].y==src.y)
				t3=0;
			else
			{
				for (;!q1.empty() && q1.front().first<=p[i].x-2;q1.pop()) update(w1,q1.front().second.first,q1.front().second.second);
				t3=min(getw(w1,key),getw(w2,key-1));
				for (;!q1.empty() && q1.front().first<=p[i].x-1;q1.pop()) update(w1,q1.front().second.first,q1.front().second.second);
				t4=min(getw(w1,key-1),getw(w2,key-2));
			}
			t1=min(t4-save,t3+cost);
			t2=min(t3-save,t4+cost);
		}
		q1.push(MP(p[i].x,MP(key,t1)));
		update(w2,key,t2);
		if (my[i]==p[i].y)
		{
			if (p[i].x<dst.x) ckmin(ret,t1);
			if (p[i].y<dst.y) ckmin(ret,t2);
		}
	}
	return ret;
}

void preprocess()
{
	set<int64> w;
	w.insert(src.x);
	w.insert(dst.x);
	REP(i,n) w.insert(p[i].x);
	vector<int64> w1(ALL(w));
	int cnt=0;
	map<int64,int64> g;
	for (int i=0;i<SIZE(w1);i++) g[w1[i]]=(++cnt);
	src.x=g[src.x];
	dst.x=g[dst.x];
	REP(i,n) p[i].x=g[p[i].x];
}

int main()
{
#ifdef _MSC_VER
	freopen("input.txt","r",stdin);
#endif
	std::ios::sync_with_stdio(false);
	src.readin();
	dst.readin();
	cin>>n;
	REP(i,n) p[i].readin();
	if (src.x>dst.x)
	{
		src.x=-src.x;
		dst.x=-dst.x;
		REP(i,n) p[i].x=-p[i].x;
	}
	if (src.y>dst.y)
	{
		src.y=-src.y;
		dst.y=-dst.y;
		REP(i,n) p[i].y=-p[i].y;
	}
	double edst=fabs(src.x-dst.x)+fabs(src.y-dst.y);
	int old_n=n;
	n=0;
	REP(i,old_n) 
		if (p[i].x>=src.x && p[i].x<=dst.x && p[i].y>=src.y && p[i].y<=dst.y)
			p[n++]=p[i];
	preprocess();
	REP(i,n) swap(p[i].x,p[i].y);
	swap(src.x,src.y);
	swap(dst.x,dst.y);
	preprocess();
	double ret=solve();
	printf("%.18lf\n",ret+edst*100.0);
	return 0;
}

