		ymap[ys[i]]=i;
	}
	for (int i=0;i<ip.size();i++)
	{
		ip[i].first=xmap[ip[i].first];
		ip[i].second=ymap[ip[i].second];
	}
}

void update(int v,int tl,int tr,int ps,int val){
	if (tl==tr)
	{
		t[v]=max(t[v],val);
		return;
	}
	int tm=tl+tr;
	tm/=2;
	if (ps<=tm)
		update(v*2,tl,tm,ps,val);
	else
		update(v*2+1,tm+1,tr,ps,val);
	t[v]=max(t[v*2],t[v*2+1]);
}

int get(int v,int tl,int tr,int l,int r){
	if (l>r)
		return 0;
	if (tl==l&&tr==r)
		return t[v];
	int tm=tl+tr;
	tm/=2;
	return max(get(v*2,tl,tm,l,min(r,tm)),get(v*2+1,tm+1,tr,max(tm+1,l),r));
}

int lis()
{
	sort(ip.begin(),ip.end());

	run_compress();

	for (int i=0;i<ip.size();i++)
	{
		if (i>0&&ip[i].first!=ip[i-1].first)
		{
			for (int j=i-1;j>=0;--j)
			{
				if (ip[j].first!=ip[i-1].first)
					break;
				int ps=ip[j].second;
				update(1,0,N-1,ps,dp[j]);
			}
		}

		int here=get(1,0,N-1,0,ip[i].second-1);
		dp[i]=here+1;
	}
	int res=0;
	for (int i=0;i<ip.size();i++)
	{
		res=max(res,dp[i]);
	}
	return res;
}

