    for(int i=0; i<n; i++){
      if( f[i].second != s.second ) continue;
      if( f[i].first < s.first ) continue;
      if( f[i].first > t.first ) continue;
      ans += 10*PI - 20;
    }
    printf("%.18f\n", ans);
    return 0;
  }

  map<int, vector<int>> xx;
  vector<int> yy;
  for(int i=0; i<n; i++){
    yy.push_back( f[i].second );
    if( f[i].first < s.first || f[i].first > t.first ) continue;
    if( f[i].second < s.second || f[i].second > t.second ) continue;
