// Binary search (note boundaries in the caller)
int CeilIndex(vector<int> &v, int l, int r, int key) {
    while (r-l > 1) {
    int m = l + (r-l)/2;
    if (v[m] >= key)
        r = m;
    else
        l = m;
    }

    return r;
}

int LongestIncreasingSubsequenceLength(vector<int> &v) {
    if (v.size() == 0)
        return 0;

    vector<int> tail(v.size(), 0);
    int length = 1; // always points empty slot in tail

    tail[0] = v[0];
    for (size_t i = 1; i < v.size(); i++) {
        if (v[i] < tail[0])
            // new smallest value
            tail[0] = v[i];
        else if (v[i] > tail[length-1])
            // v[i] extends largest subsequence
            tail[length++] = v[i];
        else
            // v[i] will become end candidate of an existing subsequence or
            // Throw away larger elements in all LIS, to make room for upcoming grater elements than v[i]
            // (and also, v[i] would have already appeared in one of LIS, identify the location and replace it)
            tail[CeilIndex(tail, -1, length-1, v[i])] = v[i];
    }

    return length;
}

bool compasc(int a, int b){
	return x[a] < x[b];
}

bool compdesc(int a, int b){
	return x[a] > x[b];
}

int main(){
	int xi, yi, xf, yf, minx, miny, maxx, maxy, lis, n, i;
	vector<int> v;
	double ans;

	scanf("%d%d%d%d", &xi, &yi, &xf, &yf);
	scanf("%d", &n);

	minx = min(xi, xf);
	miny = min(yi, yf);
	maxx = max(xi, xf);
	maxy = max(yi, yf);

	for (i = 0; i < n; i++){
		scanf("%d%d", x + i, y + i);
		p[i] = i;
	}

	if (xi == xf or yi == yf){
		// Straight line
		for (i = 0; i < n; i++){
			if (minx <= x[p[i]] and x[p[i]] <= maxx and miny <= y[p[i]] and y[p[i]] <= maxy){
				v.push_back(y[p[i]]);
			}
		}

		if (v.empty()){
			ans = ((maxx - minx) + (maxy - miny)) * 100.0;
		}
		else{
			ans = ((maxx - minx) + (maxy - miny)) * 100.0 + 10.0 * PI - 20.0;
		}
	}
	else{
		// Initial is always lowest
		if (yi > yf){
			swap(xi, xf);
			swap(yi, yf);
		}

		// Sorting
		if (xf > xi){
			sort(p, p + n, compasc);
		}
		else{
			sort(p, p + n, compdesc);
		}

		for (i = 0; i < n; i++){
			if (minx <= x[p[i]] and x[p[i]] <= maxx and miny <= y[p[i]] and y[p[i]] <= maxy){
				v.push_back(y[p[i]]);
			}
		}

		lis = LongestIncreasingSubsequenceLength(v);
		ans = ((maxx - minx) + (maxy - miny)) * 100.0 + lis * 5.0 * PI - lis * 20.0;
	}

	printf("%.13lf\n", ans);

	return 0;
}

