double ans;

int longest(vector<pair<int, int>> vv) {
	vector<int> dp(vv.size() + 1, INF);
	dp[0] = -INF;

	for (int i = 0; i < vv.size(); ++i) {
		int p = upper_bound(all(dp), vv[i].se) - dp.begin();

		if (dp[p - 1] < vv[i].se && vv[i].se < dp[p]) {
			dp[p] = vv[i].se;
		}
	}

	int ret = 1;

	while (ret <= vv.size() && dp[ret] != INF) {
		++ret;
	}

	return ret - 1;	
}

int calc(vector<pair<int, int>> vv, bool p) {
	if (vv.empty()) {
		return 0;
	}

	int ret = 0;

	if (p == 0) {
		for (pair<int, int> &x : vv) {
			x.se *= -1;
		}
	}

	for (int step = 0; step < 2; ++step) {
		sort(all(vv));
		ret = max(ret, longest(vv));

		for (pair<int, int> &x : vv) {
			swap(x.fi, x.se);
		}
	}

	return ret;                                 
}

void solve() {                   
	scanf("%d %d", &ax, &ay);
	scanf("%d %d", &bx, &by);
	scanf("%d", &n);

	if (ax > bx) {
		swap(ax, bx);
		swap(ay, by);
	}

	for (int i = 1; i <= n; ++i) {
		pair<int, int> p;
		scanf("%d %d", &p.fi, &p.se);

		if (ax <= p.fi && p.fi <= bx) {
			if (min(ay, by) <= p.se && p.se <= max(ay, by)) {
				arr.pb(p);		
			}
		}
	}

	ans = (abs(ax - bx) + abs(ay - by)) * 100.0;	

	if (ax == bx || ay == by) {
		if (!arr.empty()) {
			ans += (PI * 10.0 - 20.0);
		}

		printf("%.15f\n", ans);
		return;
	}

	ans -= (20.0 - PI * 5.0) * calc(arr, ay <= by); 
	printf("%.15f\n", ans);    
}

