}

int query(int x){
	int res = 0;
	for(++x; x > 0; x -= x&-x) res = max(res,bit[x]);
		return res;
}

int get(vector<int> &arr){
	vector<int> v = arr;
	sort(v.begin(),v.end());
	int a = v.size();
	v.erase(unique(v.begin(),v.end()),v.end());
	int b = v.size();
	assert(a==b);
	for(int i = 0; i < arr.size(); i++ ){
		arr[i] = lower_bound(v.begin(),v.end(),arr[i])-v.begin();
	}
	int res = 0;
	for(int i = 0; i < arr.size(); i++ ){
		dp[i] = query(arr[i])+1;
		res = max(res, dp[i]);
		update(arr[i],dp[i]);
	}
	return res;
}

