    X.push_back(Y1);
    X.push_back(Y2);
    P.resize(N);
    for(int i = 0; i < N; i++) {
        scanf("%d %d", &P[i].first, &P[i].second);
        X.push_back(P[i].second);
    }

    cout<<fixed;
    cout.precision(20);

    if(X1 == X2) {
        int cnt = 0;
        for(int i = 0; i < N; i++) {
            if(P[i].first == X1 && min(Y1, Y2) <= P[i].second && P[i].second <= max(Y1, Y2)) cnt++;
        }
        lf ans = 100LL * abs(Y1 - Y2);
        ans += (10*PI - 20);
        cout << ans;
        return 0;
    }
    if(Y1 == Y2) {
        int cnt = 0;
        for(int i = 0; i < N; i++) {
            if(P[i].first == Y1 && min(X1, X2) <= P[i].first && P[i].first <= max(X1, X2)) cnt++;
        }
        lf ans = 100LL * abs(X1 - X2);
        ans += (10*PI - 20);
        cout << ans;
        return 0;
    }

    sort(X.begin(), X.end());
    X.resize(unique(X.begin(), X.end()) - X.begin());
    Xn = X.size();
    for(int i = 0; i < Xn; i++) dx[X[i]] = i;
    for(int i = 0; i < N; i++) P[i].second = dx[P[i].second];
    st.second = dx[st.second];
    ed.second = dx[ed.second];

    P.push_back(st);
    P.push_back(ed);
    sort(P.begin(), P.end(), cmp);

    bit.init();
    dp.resize(P.size());
    for(int i = P.size() - 1; i >= 0; i--) {
        if(ed.first < P[i].first) continue;
        if(P[i].second < min(st.second, ed.second) || max(st.second, ed.second) < P[i].second) continue;

        dp[i] = (P[i] != st && P[i] != ed) + bit.quer(min(P[i].second, ed.second), max(P[i].second, ed.second), 0, Xn - 1, 1);
        bit.upd(P[i].second, dp[i], 0, Xn - 1, 1);

        if(P[i] == st) {
