		return y < p.y;
	}
	long long x,y;
};

int main() {
	int N;
	Point S, G;
	vector<Point> point;
	vector<long long> table;

	cin >> S.x >> S.y >> G.x >> G.y;
	cin >> N;
	for (int i = 0; i < N; i++) {
		Point p;
		cin >> p.x >> p.y;
		point.push_back(p);
	}

	if (G < S)swap(S, G);
	sort(point.begin(), point.end());

	vector<Point>::iterator begin = lower_bound(point.begin(), point.end(), S);
	vector<Point>::iterator end = upper_bound(point.begin(), point.end(), G);

	while (begin != end) {
		if (G.x < S.x) {
			if (S.x < begin->x || begin->x < G.x) {
				begin++; 
				continue;
			}
		}
		else {
			if (S.x > begin->x || begin->x > G.x) {
				begin++;
				continue;
			}
		}
		long long x = abs(begin->x - S.x);
		vector<long long>::iterator it = lower_bound(table.begin(), table.end(), x);
		if (it == table.end()) {
			table.push_back(x);
		}
		else {
			*it = x;
		}
		begin++;
	}

	double len = (abs(G.x - S.x) + abs(G.y - S.y)) * 100;
	if (S.x == G.x || S.y == G.y) {
		len = len - 20.0 + QUA * 2;
	}
	else {
		if (table.size() < (G.y - S.y) && table.size() < (G.x - S.x)) {
			len -= table.size() * (20.0 - QUA);
		}
		else {
			len -= (table.size() - 1) * (20.0 - QUA);
			len = len - 20.0 + QUA * 2;
		}

	}
	cout << fixed;
	cout << setprecision(15) << len << endl;

	return 0;
}

