int t[2 * 200000];

void upd(int v, int x) {
	t[v += n] = x;
	for(v >>= 1; v; v >>= 1) t[v] = max(t[v * 2], t[v * 2 + 1]);
}

int get(int l, int r) {
	int ret = 0;
	for(l += n, r += n; l <= r; l = (l + 1) >> 1, r = (r - 1) >> 1) {
		if(l & 1) ret = max(ret, t[l]);
		if(!(r & 1)) ret = max(ret, t[r]);
	}
	return ret;
}

