ll gcd(ll a,ll b) { return b==0?a:gcd(b,a%b); }

const int MAXN=200000;
const double MPI=acos(-1.0);

typedef struct P { int x,y; } P;
bool operator<(const P &a,const P &b) { return a.x<b.x; }

int n;
P s,t;
P p[MAXN];

int lis[MAXN],nlis;

double solve() {
	{ int nn=0; REP(i,n) if(!(p[i].x<s.x&&p[i].x<t.x||p[i].x>s.x&&p[i].x>t.x||p[i].y<s.y&&p[i].y<t.y||p[i].y>s.y&&p[i].y>t.y)) p[nn++]=p[i]; n=nn; }
	REP(i,n) p[i].x-=s.x,p[i].y-=s.y; t.x-=s.x,t.y-=s.y,s.x-=s.x,s.y-=s.y;
	if(t.x<0) { REP(i,n) p[i].x=-p[i].x; t.x=-t.x; }
	if(t.y<0) { REP(i,n) p[i].y=-p[i].y; t.y=-t.y; }
	if(t.x==0) { bool any=false; REP(i,n) if(p[i].x==0) any=true; return 100.0*t.y+(any?1:0)*(10.0*MPI-20.0); }
	if(t.y==0) { bool any=false; REP(i,n) if(p[i].y==0) any=true; return 100.0*t.x+(any?1:0)*(10.0*MPI-20.0); }

	sort(p,p+n); nlis=0;
	REP(i,n) {
		int l=-1,h=nlis; while(l+1<h) { int m=l+(h-l)/2; if(p[i].y<=lis[m]) h=m; else l=m; } int idx=h;
		lis[idx]=p[i].y; if(idx==nlis) ++nlis;
	}
	double ret=100.0*(t.x+t.y)-nlis*(20.0-5.0*MPI);
	return ret;
}


void run() {
	scanf("%d%d%d%d",&s.x,&s.y,&t.x,&t.y);
	scanf("%d",&n); REP(i,n) scanf("%d%d",&p[i].x,&p[i].y);

	printf("%.12lf\n",solve());
}

int main() {
	run();
	return 0;
}

