    for(int i = 0; i < int(P.size()); ++i) {
        if(S.empty() || P[i].snd > S.back()) 
            S.pb(P[i].snd);
        else {
            *lower_bound(S.begin(), S.end(), P[i].snd) = P[i].snd;
        }
    }
    return S.size();
}

int DOWN() {
    vector<int> S;
    for(int i = 0; i < int(P.size()); ++i) {
        P[i].snd = - P[i].snd;
        if(S.empty() || P[i].snd > S.back()) 
            S.pb(P[i].snd);
        else {
            *lower_bound(S.begin(), S.end(), P[i].snd) = P[i].snd;
        }
    }
    return S.size();
}

