	  }
	sort(a+1,a+n+1);
	if(sx==tx || sy==ty)
	  {
	   printf("%.15lf\n",(tx-sx+ty-sy)*100.0+(n?(2*r-20):0));
	   return 0;
	  }
	for(i=1;i<=n;i++)
	  {
	   k=maxx(a[i].bb);
	   mdf(a[i].bb,k+1);
	  }
	k=maxx(n);
	printf("%.15lf\n",(tx-sx+ty-sy)*100.0+k*(r-20)+(k==min(tx-sx+1,ty-sy+1)?0:10));
	return 0;
}

