void push_up(int pos)
{
    tree[pos]=max(tree[pos<<1],tree[pos<<1|1]);
}
void upd(int l,int r,int pos,int x,int v)
{
    if (l==r){
        tree[pos]=v;
        return ;
    }
    int mid=(l+r)>>1;
    if (mid>=x)upd(lson,x,v);
    else upd(rson,x,v);
    push_up(pos);
}
int query(int l,int r,int pos,int l1,int r1)
{
    if (l1<=l&&r1>=r){
        return tree[pos];
    }
    int mid=(l+r)>>1;
    int ret=0;
    if (mid>=l1)ret=query(lson,l1,r1);
    if (mid+1<=r1)ret=max(ret,query(rson,l1,r1));
    return ret;
}
