int getLIS(){
	vector<int> v;
	fr(i, 0, sz(p)){
		int l = -1;
		int r = sz(v);
		while(r-l>1){
			int m = (l+r)/2;
			if(v[m] > p[i].second) r = m;
			else l = m;
		}
		if(r == sz(v)) v.pb(p[i].second);
		else v[r] = p[i].second;
	}
	return sz(v);
}

