class BIT {
public:
    explicit BIT(ll N, ll v) : V_NUM(N) {
        data.resize(N);
        fill(ALL(data), v);
    }

    ll query(ll i) {
        ll ret = 0;
        while (i > 0) {
            ret = max(ret, data[i]);
            i -= (i & -i);
        }
        return ret;
    }

    void update(ll i, ll v) {
        while (i < V_NUM) {
            data[i] = max(data[i], v);
            i += (i & -i);
        }
    }

    ll V_NUM;
    V<ll> data;
};

struct coo {
    coo(ll _x = 0, ll _y = 0) : x(_x), y(_y){};
    ll x;
    ll y;

    bool operator<(const coo& r) const {
        return x == r.x ? y < r.y : x < r.x;
    }
};

map<ll, ll> compress(const V<coo>& a) {
    set<ll> sety;
    for (coo c : a) {
        sety.insert(c.y);
    }

    map<ll, ll> ret;
    ll idx = 1;
    for (ll y : sety) {
        ret[y] = idx;
        ++idx;
    }

    return ret;
}

void solve() {
    coo s, g;
    cin >> s.x >> s.y >> g.x >> g.y;

    if (s.y > g.y) swap(s, g);

    ll N;
    cin >> N;
    V<coo> a;
    FOR(_, 0, N) {
        ll x, y;
        cin >> x >> y;
        if (y < s.y || g.y < y) continue;

        if (s.x < g.x) {
            if (s.x <= x && x <= g.x) {
                a.push_back(coo(x - s.x, y - s.y));
            }
        } else {
            if (g.x <= x && x <= s.x) {
                a.push_back(coo(s.x - x, y - g.y));
            }
        }
    }

    SORT(a);
    map<ll, ll> com = compress(a);

    BIT bit(SIZE(com) + 10, 0);

    for (coo c : a) {
        ll y = com[c.y];
        bit.update(y, bit.query(y) + 1);
    }

    ll turn = bit.query(SIZE(com) + 5);
    double ans = (abs(g.x - s.x) + abs(g.y - s.y)) * 100;
    ans -= (20 - PI * 5) * turn;
    if (turn == abs(g.y - s.y) + 1 || turn == abs(g.x - s.y) + 1) {
        ans += PI * 5;
    }

    cout << ans << endl;
    return;
}


