using P = std::pair<int, int>;

int n;

bool used[200000];

std::vector<P> vec;

int memo[200000];

int dfs(int m) {

	if (memo[m] >= 0)
		return memo[m];

	int res = 0;

	used[m] = true;

	int v = std::upper_bound(vec.begin(), vec.end(), vec[m]) - vec.begin();

	for (int i = v; i<vec.size(); ++i) {
		if (vec[m].second<vec[i].second)
			res = std::max(res, dfs(i));
	}

	used[m] = false;

	return memo[m] = res + 1;
}

int main() {

	int x1, y1, x2, y2;

	std::cin >> x1 >> y1 >> x2 >> y2 >> n;

	std::memset(memo, -1, sizeof(memo));

	P p;

	for (int i = 0; i<n; ++i) {
		std::cin >> p.first >> p.second;

		if (( (x1 <= p.first&&p.first <= x2) || (x2 <= p.first&&p.first <= x1) )&&
		((y1 <= p.second&&p.second <= y2) || (y2 <= p.second&&p.second <= y1))) {
			vec.emplace_back(p);
		}
	}

	std::sort(vec.begin(), vec.end());

	int cnt = 0;

	for (int i = 0; i<vec.size(); ++i) {

		if (!used[i])
			cnt = std::max(cnt, dfs(i));
	}

	double ans = (std::abs(x1 - x2) + std::abs(y1 - y2)) * 100.0 - 20.0 * (1.0 - atan(1.0))*(double)cnt;

	std::cout << std::fixed << ans << std::setprecision(17) << std::endl;

	system("pause");

	return 0;
}

