void solve()
{
	int n, i, x1, y1, x2, y2, A = 0, B = 0, val;
	double ans;
	cin >> x1 >> y1 >> x2 >> y2;
	cin >> n;
	fo(i,1,n+1)
		cin >> a[i].F >> a[i].S;
	if(x1 > x2)
	{
		x1 = MAX-1-x1;
		x2 = MAX-1-x2;
		fo(i,1,n+1)
			a[i].F = MAX-1-a[i].F;
	}
	if(y1 > y2)
	{
		y1 = MAX-1-y1;
		y2 = MAX-1-y2;
		fo(i,1,n+1)
			a[i].S = MAX-1-a[i].S;
	}
	A = x2-x1 + y2-y1;
	arr.pb({-1,-1});
	diffy.pb(-1);
	fo(i,1,n+1)
		if(a[i].F >= x1 && a[i].F <= x2 && a[i].S >= y1 && a[i].S <= y2)
		{
			diffy.pb(a[i].S);
			arr.pb(a[i]);
		}
	cnt = sz(diffy)-1;
	sort(all(arr));
	sort(all(diffy));
	fo(i,1,cnt+1)
		mapy[diffy[i]] = i;
	fo(i,1,sz(arr))
	{
		val = query(mapy[arr[i].S])+1;
		B = max(B, val);
		update(mapy[arr[i].S],val);
	}
	ans = 100.0*A;
	if(x1 == x2 || y1 == y2)
	{
		if(sz(arr) > 1)
			ans += (10.0*PI - 20.0);
	}
	else
		ans += (5.0*PI - 20.0)*B;
	cout << ans << '\n';
	return;
}

