constexpr long double PI = 3.1415926535897932384626;
constexpr int MX = 99999999;

struct point {
    int x, y;
    point(int x = 0, int y = 0) : x(x), y(y) { }
    bool operator < (const point& rhs) {
        if(x == rhs.x) return y < rhs.y;
        return x < rhs.x;
    }
    friend istream& operator >> (istream& st, point& p) {
        return st >> p.x >> p.y;
    }
    void x_swap() {
        x = MX - x;
    }
    void y_swap() {
        y = MX - y;
    }
};

int main() {

    point start, goal;
    cin >> start >> goal;

    bool swap_x = start.x > goal.x;
    bool swap_y = start.y > goal.y;
    if(swap_x) {
        start.x_swap();
        goal.x_swap();
    }   
    if(swap_y) {
        start.y_swap();
        goal.y_swap();
    }

    int N;
    cin >> N;
    vector<point> fountains;
    rep(i, N) {
        point tmp;
        cin >> tmp;
        if(swap_x) tmp.x_swap();
        if(swap_y) tmp.y_swap();
        if(tmp.x >= start.x && tmp.y >= start.y && tmp.x <= goal.x && tmp.y <= goal.y) {
            fountains.push_back(tmp);
        }
    }

    long double answer = 100.0 * ((goal.x - start.x) + (goal.y - start.y));
    if(start.x == goal.x || start.y == goal.y) {
        if(fountains.size() > 0) {
            answer -= 20.0;
            answer += 10.0 * PI;
        }
    } else {
        sort(all(fountains));
        vector<int> dp(fountains.size() + 1, inf);
        dp[0] = -inf;
        for(const point& p : fountains) {
            *lower_bound(all(dp), p.y) = p.y;
        }
        int cnt = lower_bound(all(dp), inf) - dp.begin() - 1;
        answer -= 20.0 * cnt;
        answer += 5.0 * PI * cnt;
    }

    cout << fixed << setprecision(30) << answer << '\n';
    return 0;

}

