bool intersect(ll l1, ll r1, ll l2, ll r2)
{
	if(r2<l2||r1<l1) return false;
	if(l1>=l2) 
	{
		swap(l1,l2); swap(r1,r2);
	}
	if(l2<=r1) return true;
	else return false;
}

int CeilIndex(std::vector<int> &v, int l, int r, int key) {
    while (r-l > 1) {
    int m = l + (r-l)/2;
    if (v[m] >= key)
        r = m;
    else
        l = m;
    }

    return r;
}

int LongestIncreasingSubsequenceLength(std::vector<int> &v) {
    if (v.size() == 0)
        return 0;

    std::vector<int> tail(v.size(), 0);
    int length = 1; // always points empty slot in tail

    tail[0] = v[0];
    for (size_t i = 1; i < v.size(); i++) 
    {
        if (v[i] < tail[0])
            // new smallest value
            tail[0] = v[i];
        else if (v[i] > tail[length-1])
            // v[i] extends largest subsequence
            tail[length++] = v[i];
        else
            // v[i] will become end candidate of an existing subsequence or
            // Throw away larger elements in all LIS, to make room for upcoming grater elements than v[i]
            // (and also, v[i] would have already appeared in one of LIS, identify the location and replace it)
            tail[CeilIndex(tail, -1, length-1, v[i])] = v[i];
    }

    return length;
}

ld st[2][1000001];

void build(int t, int id, int l, int r)
{
	if(r-l<2)
	{
		st[t][id] = 0;
		return ;
	}
	int mid=(l+r)>>1;
	build(t,id*2,l,mid);
	build(t,id*2+1,mid,r);
	st[t][id]=min(st[t][id*2],st[t][id*2+1]);
}

void update(int t, int id, int l, int r, int pos, ld v)
{
	if(pos>=r||pos<l) return ;
	if(r-l<2)
	{
		st[t][id] = v;
		return ;
	}
	int mid=(l+r)>>1;
	update(t,id*2,l,mid,pos,v);
	update(t,id*2+1,mid,r,pos,v);
	st[t][id]=min(st[t][id*2],st[t][id*2+1]);
}

ld query(int t, int id, int l, int r, int ql, int qr)
{
	if(ql>=r||l>=qr) return ld(ld(1e18));
	if(ql<=l&&r<=qr) return st[t][id];
	int mid=(l+r)>>1;
	return min(query(t,id*2,l,mid,ql,qr),query(t,id*2+1,mid,r,ql,qr));
}

