int lis(vector < pair <int, int> > &v, bool up) {
  int ret = 0;
  int n = v.size();
  vector <int> opt;
  opt.push_back(-L - 1);
  for (int i = 0; i < v.size(); ++i) {
    int t = lower_bound(opt.begin(), opt.end(), up ? v[i].second : -v[i].second) - opt.begin();
    if (t == opt.size()) opt.push_back(up ? v[i].second : -v[i].second);
    else opt[t] = min(opt[t], up ? v[i].second : -v[i].second);
    ret = max(ret, t);
  }
  return ret;
}

