		long long L = min(y1, y2);
		long long R = max(y1, y2);
		bool f = 0;
		for(int i = 1; i <= n; i++)
			if(a[i].x == x1 && L <= a[i].y && a[i].y <= R)
				f = 1;
		double ans = R - L;
		ans *= 100;
		if(f){
			ans -= 20;
			ans += pi * 10;
		}
		printf("%.20f\n", ans);
	}
	else if(y1 == y2){
		long long L = min(x1, x2);
		long long R = max(x1, x2);
		bool f = 0;
		for(int i = 1; i <= n; i++)
			if(a[i].y == y1 && L <= a[i].x && a[i].x <= R)
				f = 1;
		double ans = R - L;
		ans *= 100;
		if(f){
			ans -= 20;
			ans += pi * 10;
		}
		printf("%.20f\n", ans);
	}
	else{
		long long Lx = min(x1, x2);
		long long Rx = max(x1, x2);
		long long Ly = min(y1, y2);
		long long Ry = max(y1, y2);
		for(int i = 1; i <= n; i++){
			if(Lx <= a[i].x && a[i].x <= Rx && Ly <= a[i].y && a[i].y <= Ry){
				b[++tot] = a[i];
			}
		}
		int cnt = 0;
