int gcnt() {
    for (int i = 0; i < p.size(); ++i) {
        dp[i] = 1;
        swap(p[i].F, p[i].S);
    }
    set<pair<pair<int, int>, int> > s;
    for (int i = 0; i < p.size(); ++i) {
        //cout << p[i].F << " " << p[i].S << endl;
        int mxres = 0;
        set<pair<pair<int, int>, int> >::iterator it = s.lower_bound(make_pair(p[i], 0));
        set<pair<pair<int, int>, int> >::iterator it1 = it;
        if (s.size() != 0 && it1 != s.begin()) {
            --it1;
            while (true) {
                mxres = max(mxres, it1->S);
                //cout << it1->S << " " << mxres << endl;
                if (it1 == s.begin()) break;
                --it1;
            }
        }
        //cout << (it == s.begin()) << endl;
        s.erase(s.begin(), it);
        s.insert(make_pair(p[i], mxres + 1));
        //cout << s.size() << endl;
    }
    int ans = 0;
    for (set<pair<pair<int, int>, int> >::iterator it = s.begin(); it != s.end(); ++it) {
        ans = max(ans, it->S);
    }
    return ans;
}

