struct state {
	double posX, posY, cost;
	int dir, idx;
	state(int _idx, double _posX, double _posY , double _cost, int _dir) {
		idx = _idx;
		posX = _posX;
		posY = _posY;
		cost = _cost;
		dir = _dir;
	};
	bool operator<(const state &rhs) const {
		if (dir == rhs.dir)
			return idx < rhs.idx;
		return dir < rhs.dir;
	}
};
bool vis[N][5];
double cost[N][5];


double go(double x1 , double y1 , double x2 , double y2) {
	return (abs(x1 - x2) + abs(y2 - y1)) * 100.0;;
}
const double rb3 = acos(-1) * 2 * 10.0 * 0.25;

int main() {
	//freopen("input.txt", "r", stdin);
	scanf("%lf%lf%lf%lf", &sx, &sy, &ex, &ey);
	scanf("%d", &n);

	for (int i = 0 ; i < N ; i++)
		for (int j = 0 ; j <= 4 ; j++)
			cost[i][j] = 1e18;
	for (int i = 1; i <= n; ++i) {
		scanf("%lf%lf", &X[i], &Y[i]);
		nx.pb(mp(X[i], i));
		ny.pb(mp(Y[i], i));
	}
	X[0] = sx;
	Y[0] = sy;
	nx.pb(mp(-1, -1));
	ny.pb(mp(-1, -1));
	nx.pb(mp(1e9, -1));
	ny.pb(mp(1e9, -1));
	nx.pb(mp(ex, n + 1));
	ny.pb(mp(ey, n + 1));
	nx.pb(mp(sx, 0));
	ny.pb(mp(sy, 0));
	X[n + 1] = ex;
	Y[n + 1] = ey;
	sort(nx.begin(), nx.end());
	sort(ny.begin(), ny.end());
	priority_queue< pair<double, state> > q;
	q.push(make_pair(0, state(0, sx, sy, 0, 4)));
	cost[0][4] = 0;
	double mn = go(sx, sy, ex, sy);
	while (q.size()) {
		pair<double, state> cur = q.top();
		cur.first = -cur.first;
		q.pop();
		if (cur.second.idx == n + 1) {
			mn = cur.second.cost;
			break;
		}
		if (vis[cur.second.idx][cur.second.dir])continue;
		vis[cur.second.idx][cur.second.dir] = 1;
		if (cur.second.dir != 4) {
			double newCost = rb3 + cur.second.cost;
			state nw = state(cur.second.idx, cur.second.posX, cur.second.posY, newCost, (cur.second.dir + 1) % 4);
			if (cur.second.dir == 0) {
				nw.posX += 0.1;
				nw.posY -= 0.1;
			} else if (cur.second.dir == 1) {
				nw.posX += 0.1;
				nw.posY += 0.1;
			} else if (cur.second.dir == 2) {
				nw.posX -= 0.1;
				nw.posY += 0.1;
			} else if (cur.second.dir == 3) {
				nw.posX -= 0.1;
				nw.posY -= 0.1;
			}
			if (nw.cost < cost[nw.idx][nw.dir]) {
				cost[nw.idx][nw.dir] = nw.cost;
				q.push(mp(-nw.cost, nw));
			}
		}
		if (cur.second.dir != 4) {
			double newCost = rb3 + cur.second.cost;
			state nw = state(cur.second.idx, cur.second.posX, cur.second.posY, newCost, (cur.second.dir - 1 + 4) % 4);
			if (cur.second.dir == 0) {
				nw.posX += 0.1;
				nw.posY += 0.1;
			} else if (cur.second.dir == 1) {
				nw.posX -= 0.1;
				nw.posY += 0.1;
			} else if (cur.second.dir == 2) {
				nw.posX -= 0.1;
				nw.posY -= 0.1;
			} else if (cur.second.dir == 3) {
				nw.posX += 0.1;
				nw.posY -= 0.1;
			}
			if (nw.cost < cost[nw.idx][nw.dir]) {
				cost[nw.idx][nw.dir] = nw.cost;
				q.push(mp(-nw.cost, nw));
			}
		}
		for (int u = 0 ; u < 4 ; u++) {
			int nxtIdx = -1;
			if (abs(dx[u]) > 0.5000) {
				nxtIdx = dx[u] == -1 ? fndNxt(nx, cur.second.posX) : fndPrev(nx, cur.second.posX);
			} else {
				nxtIdx = dy[u] == -1 ? fndNxt(ny, cur.second.posY) : fndPrev(ny, cur.second.posY);
			}
			if (nxtIdx == -1)continue;
			int realDir = (nxtIdx != n + 1 && nxtIdx != 0) ? u : 4;
			double npx = X[nxtIdx] + (nxtIdx != n + 1 && nxtIdx != 0) * dx[u] * 0.1;
			double npy = Y[nxtIdx] + (nxtIdx != n + 1 && nxtIdx != 0) * dy[u] * 0.1;
			state newS = state(nxtIdx, npx, npy, go(cur.second.posX, cur.second.posY, npx, npy) + cur.second.cost, realDir);
			if (newS.cost < cost[newS.idx][newS.dir]) {
				cost[newS.idx][newS.dir] = newS.cost;
				q.push(mp(-newS.cost, newS));
			}
		}
	}
	printf("%.12lf\n", mn );
	return 0;
}

