const int inf = 0x3f3f3f3f;

int lis(vector<pair<int, int>> &p) {
  int n = p.size();
  int ret = 0, dp[n] = {}, l[n];
  memset(l, inf, sizeof(l));
  for (int i = 0; i < n; ++i) {
    auto it = upper_bound(l, l+p.size(), p[i].second);
    if (*it==inf) {
      dp[i] = 1;
      l[0] = min(l[0], p[i].second);
    } else {
      dp[i] = dp[it-l] + 1;
      l[dp[i]-1] = min(l[dp[i]-1], p[i].second);
    }
  }
  for (int i = 0; i < n; ++i) {
    ret = max(ret, dp[i]);
  }
  return ret;
}

