    } else {
      *lower_bound(all(l), xy[i].y) = xy[i].y;
    }
  }
  int n_s = l.size();
  int n_p = 0;
  if (n_s == 1 + min(x_max - x_min, y_max - y_min)) {
    n_s -= 1;
    n_p = 1;
  }

  double shortcut = 20 - M_PI * 5;
