using namespace std;

const double pi = acos(-1.0);

class fenwick {
 public:
  int n;
  vector<int> f;

  fenwick(int _n) : n(_n) {
    f.resize(n);
  }

  void add(int x, int y) {
    for (int i = x; i < n; i = i | (i + 1)) {
      f[i] = max(f[i], y);
    }
  }

  int get(int x) {
    int ret = 0;
    for (int i = x; i >= 0; i = (i & (i + 1)) - 1) {
      ret = max(ret, f[i]);
    }
    return ret;
  }
};

