using D = long double;
const D PI = acos(-1);
const D C = 2.0 * PI * 10.0;

struct Point {D x, y;};
bool operator<(Point l, Point r) {return l.y < r.y;}

D LIS(auto S) {
  vector<Point> dp = {S.front()};
  for(const auto& i: S) {
    if(dp.back() < i) dp.push_back(i);
    else              *lower_bound(dp.begin(), dp.end(), i) = i;
  }
  return dp.size();
}

int main() {
  Point S, G;
  cin >> S.x >> S.y >> G.x >> G.y;

  int N;
  cin >> N;

  vector<Point> P;
  for(auto i = 0; i < N; ++i) {
    D x, y;
    cin >> x >> y;
    auto lx = min(S.x, G.x), hx = max(S.x, G.x);
    auto ly = min(S.y, G.y), hy = max(S.y, G.y);
    if(lx <= x && x <= hx && ly <= y && y <= hy) P.push_back({x, y});
  }

  if(S.x > G.x) {
    S.x = -S.x;
    G.x = -G.x;
    for(auto& i: P) i.x = -i.x;
  }
  if(S.y > G.y) {
    S.y = -S.y;
    G.y = -G.y;
    for(auto& i: P) i.y = -i.y;
  }
  if(G.x-S.x > G.y-S.y) {
    swap(S.x, S.y);
    swap(G.x, G.y);
    for(auto& i: P) swap(i.x, i.y);
  }

  sort(begin(P), end(P), [](auto l, auto r) {return l.x < r.x;});
  auto res = 100 * (G.x - S.x) + 100 * (G.y - S.y);
  if(!P.empty()) {
    auto s = LIS(P);
    auto d = G.x-S.x;
    if(s < d+1) res += s * (C / 4 - 20);
    else        res += (s-1) * (C / 4 - 20) + C / 2 - 20;
  }
  cout << setprecision(10) << fixed << res << endl;
}

