#define MN 200000
using namespace std;
inline int read()
{
	int x=0,f=1;char ch=getchar();
	while(ch<'0'||ch>'9'){if(ch=='-')f=-1;ch=getchar();}
	while(ch>='0'&&ch<='9'){x=x*10+ch-'0';ch=getchar();}
	return x*f;
}
double ans=0,R=acos(-1)*20/4;
int n,a,b,c,d,flag,top,f[MN+5],mx=0;
pair<int,int> s[MN+5];
int main()
{
	a=read();b=read();c=read();d=read();n=read();
	if(a>c) swap(a,c),swap(b,d);
	if(d<b) d=int(1e8)-1-d,b=int(1e8)-1-b,flag=1;
	ans=100.*(c-a+d-b);
	for(int i=1;i<=n;++i)
	{
		int x=read(),y=read();
		if(flag) y=int(1e8)-1-y;
		if(x>=a&&x<=c&&y>=b&&y<=d) s[++top]=make_pair(x,y);
	}
	sort(s+1,s+top+1);
	if((a==c||b==d)&&top) return 0*printf("%.12lf\n",ans-20+2*R);
	if((a==c||b==d)||!top) return 0*printf("%.12lf\n",ans);
	f[0]=-1;for(int i=1;i<=top;++i) f[i]=1e9;
	int conx=1,cony=1;
	for(int i=1;i<top;++i) conx&=(s[i].first+1==s[i+1].first),cony&=(s[i].second+1==s[i+1].second);
	conx&=(s[1].first==a&&s[top].first==c);
	cony&=(s[1].second==b&&s[top].second==d);
	for(int i=1;i<=top;++i)
	{
		int l=0,r=i-1,mid,res;
		while(l<=r)
		{
			mid=l+r>>1;
			if(f[mid]<s[i].second) res=mid,l=mid+1;
			else r=mid-1;
		}
		mx=max(mx,res+1);f[res+1]=min(f[res+1],s[i].second);
	}
	if((conx||cony)&&mx==top&&mx) ans+=R;
	printf("%.12lf\n",ans-mx*20+mx*R);
	return 0;
}

