struct cc
{
	int x,y;
}pos[200010];
int n,m,i,j,x1,yy,x2,y2,xs=1,ys=1,x,y,l,r,mid,res;
double s; 
vector<cc> ans;
bool cmp(cc x,cc y)
{
	return x.x<y.x;
}
int main()
{
	ios::sync_with_stdio(false);
	cin>>x1>>yy>>x2>>y2>>n;
	if (x1>x2)
	{
		xs=-1;
	}
	if (yy>y2)
	{
		ys=-1;
	}
	x1*=xs;
	x2*=xs;
	yy*=ys;
	y2*=ys;
	for (i=1;i<=n;i++)
	{
		cin>>x>>y;
		x*=xs;
		y*=ys;
		if (x>=x1&&x<=y2&&y>=yy&&y<=y2)
		{
			pos[++m]={x,y};
		}
	}
	sort(pos+1,pos+m+1,cmp);
	for (i=1;i<=m;i++)
	{
		if (ans.empty()||(ans.back().x<pos[i].x&&ans.back().y<pos[i].y)) ans.push_back(pos[i]);
		else
		{
			res=ans.size()-1;
			l=0;r=ans.size()-1;
			while (l<r)
			{
				mid=(l+r)/2;
				if (ans[mid].x<pos[i].x&&ans[mid].y<pos[i].y)
				{
					res=mid;
					r=mid-1;
				}
				else l=mid;
			}
			while (res&&ans[res-1].x<pos[i].x&&ans[res-1].y<pos[i].y) res--;
			ans[res]=pos[i];
		}
	}
	//cout<<m<<' '<<ans.size()<<endl;
	if (ans.size()-1==min(x2-x1,y2-yy))
	{
		 s=10.0*acos(-1)-20;
		 ans.pop_back();
	}
	printf("%.15f",s+ans.size()*5.0*acos(-1)-ans.size()*20+(x2-x1+y2-yy)*100);
	return 0;
}

