const int INF = 1e9;
const long double PI = 3.1415926535;

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	int x1, y1, x2, y2;
	cin >> x1 >> y1 >> x2 >> y2;
	if (y1 > y2) {
		swap(x1, x2);
		swap(y1, y2);
	}

	bool flag = false;
	if (x1 > x2) {
		flag = true;
		x1 = -x1;
		x2 = -x2;
	}

	int n;
	cin >> n;
	vector<int> X(n), Y(n), idxs;
	int hogex = INF, hogey = INF;
	for (int i = 0; i < n; i++) {
		cin >> X[i] >> Y[i];
		if (flag) X[i] = -X[i];

		if (Y[i] < y1 || Y[i] > y2) continue;
		if (X[i] < x1 || X[i] > x2) continue;
		if (Y[i] == y1){
			hogex = X[i];
		} 
		if (X[i] == x1) {
			hogey = Y[i];
		}
		idxs.push_back(i);
	}
	sort(idxs.begin(), idxs.end(), [&](const int& i1, const int& i2){return X[i1] < X[i2];});

	long double ans = (y2 - y1) + (x2 - x1);
	ans *= 100;
	if (x1 == x2) {
		if (hogey != INF) ans += (PI - 2) * 10;
	} else if (y1 == y2) {
		if (hogex != INF) ans += (PI - 2) * 10;
	} else if (!idxs.empty()) {
		vector<int> dp(idxs.size(), INF);
		for (int idx : idxs) {
			*lower_bound(dp.begin(), dp.end(), Y[idx]) = Y[idx];
		}
		int foo = lower_bound(dp.begin(), dp.end(), INF) - dp.begin();

		if (hogex != INF) {
			bool f = (X[idxs[0]] == hogex);
			for (int i = 1; i < idxs.size(); i++) {
				if (!f) break;
				if (X[idxs[i]] != X[idxs[i - 1]] + 1 || Y[idxs[i]] != Y[idxs[i - 1]] + 1) {
					f = false;
				}
			}
			if (f && Y[idxs.back()] == y2) {
				foo -= 1;
				ans += (PI - 2) * 10;
			}
		}

		if (hogey != INF) {
			bool f = true;
			for (int i = 1; i < idxs.size(); i++) {
				if (X[idxs[i]] != X[idxs[i - 1]] + 1 || Y[idxs[i]] != Y[idxs[i - 1]] + 1) {
					f = false;
				}
				if (!f) break;
			}
			if (f && X[idxs.back()] == x2) {
				foo -= 1;
				ans += (PI - 2) * 10;
			}
		}		
		ans -= (2 - PI / 2) * 10 * foo;
	}
	cout << fixed << setprecision(15) << ans << endl;
	return 0;
}

