vector<P> XY;
double rec(ll i){
	if (dp[i]!=-1) return dp[i];
	else{
		double ans = double((x_e-XY[i].first+y_e-XY[i].second)*100);
		bool flag = false;
		REP(j,N+1){
			if (j!=0 
