  punkty.emplace_back(x2, y2);
  while (n--) {
    int x, y;
    scanf("%d%d", &x, &y);
    x *= il_x;
    y *= il_y;
    if (x1 <= x and x <= x2 and y1 <= y and y <= y2) {
      punkty.emplace_back(x, y);
    }
  }
  vector<int> num;
  for (const auto& p : punkty) {
    num.push_back(p.first);
    num.push_back(p.second);
  }
  sort(num.begin(), num.end());
  num.resize(unique(num.begin(), num.end()) - num.begin());
  n2 = 1;
  while (n2 <= (int) num.size()) n2 *= 2;
  for (auto& p : punkty) {
    for (int* x : {&p.first, &p.second}) {
      *x = lower_bound(num.begin(), num.end(), *x) - num.begin();
    }
  }
  sort(punkty.begin(), punkty.end());
  int wynik = 0;
  for (const auto& p : punkty) {
