  long double result = razem + 5.0l * pi * wynik;
  if (wynik == 1 and x1 == x2 or y1 == y2) {
    result = razem + 5.0l * 2 * pi * wynik;
  }
  printf("%.20Lf\n", result);
  return 0;
}

