double calc1(int qx, int wx, int ex, int rx) {
	if(!(qx <= ex) || !(wx <= rx)) {
		return (double)1e12;
	}
	//cerr << qx << ' '<< wx << ' '<< ex << ' '<< rx << nxtl;
	if(qx == 4 && wx == 2) {
	//	exit(0);
	}
	if(qx == ex && wx == rx) return 0.0;
	double ans = ((ex - qx) + (rx - wx)) * 100.0000;
	auto it = my.lower_bound(wx);
	if(it != my.end()) {
		if(it->first == wx && it->second >= qx) {
			updmin(ans, calc1(it->second + 1, it->first, ex, rx) + (it -> second - qx + 1) * 100.000 - 20.000 + len * 2.000);
			updmin(ans, calc1(it->second, it->first + 1, ex, rx) + (it->second - qx) * 100.000 - 10.00 + len + 90.000);
		} else {
			int nx = max(it->second, qx), ny = it->first;
			if(mp(nx, ny) != mp(qx, wx))
				updmin(ans, calc1(nx, ny, ex, rx) + ((nx - qx) + (ny - wx)) * 100.0000);
			else {
				it = my.upper_bound(wx);
				if(it != my.end()) {
					nx = max(it->second, qx), ny = max(it->first,wx);
					if(mp(nx, ny) != mp(qx, wx))
						updmin(ans, calc1(nx, ny, ex, rx) + ((nx - qx) + (ny - wx)) * 100.0000);
					}
			}
		}
	}
	it = mx.lower_bound(qx);
	if(it != mx.end()) {
		if(it->first == qx && it->second >= wx) {
			updmin(ans, calc1(qx, it->second + 1, ex, rx) + (it -> second - wx + 1) * 100.000 - 20.000 + len * 2.000);
			updmin(ans, calc1(qx + 1, it->second, ex, rx) + (it->second - wx) * 100.000 - 10.00 + len + 90.000);
		} else {
			int nx = max(it->first,qx), ny = max(it->second, wx);
			if(mp(nx, ny) != mp(qx, wx))
				updmin(ans, calc1(nx, ny, ex, rx) + ((nx - qx) + (ny - wx)) * 100.0000);
			else {
				it = mx.upper_bound(qx);
				if(it != mx.end()) {
					nx = max(it->first, qx), ny = max(it->first,wx);
					if(mp(nx, ny) != mp(qx, wx))
						updmin(ans, calc1(nx, ny, ex, rx) + ((nx - qx) + (ny - wx)) * 100.0000);
					}
			}
		}
	}
	return ans;
}

