		mx[o] = tar;
		return;
	}
	const int mid = (L + R) / 2;
	if (q < mid)
	{
		update(q, tar, L, mid, o << 1);
	}
	else
	{
		update(q, tar, mid, R, o << 1 | 1);
	}
	pushup(o);
}
int query(int ql, int qr, int L = 0, int R = disc.size(), int o = 1)
{
	if (ql <= L && R <= qr)
	{
		return mx[o];
	}
	const int mid = (L + R) / 2;
	int ret = 0;
	if (ql < mid)
	{
		ret = query(ql, qr, L, mid, o << 1);
	}
	if (mid < qr)
	{
		ret = max(ret, query(ql, qr, mid, R, o << 1 | 1));
	}
	return ret;
}
