const int N = 2e5 + 7;
const double pi = 3.1415926535897932;
const int inf = (int)1e9 + 7;

struct point {
  int x, y;
  point() {}
  point(int a, int b) {
    x = a; y = b;
  }
};

void swap(point &a, point &b) {
  int temp = a.x;
  a.x = b.x;
  b.x = temp;
  temp = a.y;
  a.y = b.y;
  b.y = temp;
}

bool cmp (point a, point b) {
  if (a.x == b.x) {
    return a.y < b.y;
  }
  return a.x < b.x;
}

long double ans = 0;

void printans() {
  cout << fixed << setprecision(15) << ans << endl;
  exit(0);
}

point p1, p2;
point ar[N];
int dp[N];

main() {
  int a, b; scanf("%lld %lld", &a, &b);
  p1 = point(a, b);
  scanf("%lld %lld", &a, &b);
  p2 = point(a, b);
  int n; scanf("%lld", &n);
  for (int i = 1; i <= n; i++) {
    scanf("%lld %lld", &a, &b);
    if (a < min(p1.x, p2.x) || a > max(p2.x, p1.x) || b < min(p1.y, p2.y) || b > max(p1.y, p2.y)) {
      n--;
      i--;
    } else
      ar[i] = point(a, b);
  }
  sort(ar + 1, ar + n + 1, cmp);
  for (int i = 0; i < N; i++)  {
    dp[i] = inf;
  }
  dp[0] = -inf;
  int val = 0;
  for (int i = 1; i <= n; i++) {
    int pos = upper_bound(dp, dp + N, ar[i].y) - dp;
    if (dp[pos - 1] < ar[i].y && dp[pos] > ar[i].y) {
      dp[pos] = ar[i].y;
      if (pos > val) {
        val = pos;
      }
    }
  }
  ans = 100 * (abs(p2.x - p1.x) + abs(p2.y - p1.y)) - 20 * val + val * pi * 5;
  if (val == min(abs(p2.x - p1.x), abs(p2.y - p1.y)) + 1) {
    ans -= pi * 5;
    ans += 10 * pi;
  }
  printans();
}

