struct PT {
    int x, y;

    PT() {}
    PT(int x, int y) : x(x), y(y) {}

    bool operator<(const PT &rhs) const {
        if (x < rhs.x)
            return true;
        if (rhs.x < x)
            return false;
        return y < rhs.y;
    }

    bool operator>(const PT &rhs) const {
        return rhs < *this;
    }

    bool operator<=(const PT &rhs) const {
        return !(rhs < *this);
    }

    bool operator>=(const PT &rhs) const {
        return !(*this < rhs);
    }

    bool operator==(const PT &rhs) const {
        return x == rhs.x &&
               y == rhs.y;
    }

    bool operator!=(const PT &rhs) const {
        return !(rhs == *this);
    }

    friend ostream &operator<<(ostream &os, const PT &pt) {
        os << "x: " << pt.x << " y: " << pt.y;
        return os;
    }

    friend istream &operator>>(istream &is, PT &pt) {
        is >> pt.x >> pt.y;
        return is;
    }
};

PT readPT() {
    PT tmp;
    cin >> tmp;
    return tmp;
}

typedef vector<PT> VPT;
typedef vector<int> VI;
typedef pair<PT,int> PII;
typedef vector<PII> VPII;

VPT LIS(VPT v) {
    VPII best;
    VI dad(v.size(), -1);

    for (int i = 0; i < v.size(); i++) {
        PII item = make_pair(v[i], i);
        VPII::iterator iter = upper_bound(best.begin(), best.end(), item);
        if (iter == best.end()) {
            dad[i] = (best.size() == 0 ? -1 : best.back().second);
            best.push_back(item);
        } else {
            dad[i] = dad[iter->second];
            *iter = item;
        }
    }

    VPT ret;
    for (int i = best.back().second; i >= 0; i = dad[i])
        ret.push_back(v[i]);
    reverse(ret.begin(), ret.end());
    return ret;
}

