class BIT {
    public:
        int size;
        vector<int> node;

        BIT(int n, long long init_num) {
            size = n;
            for (int i = 0; i <= size; i++){
                node.pb(init_num);
            }
        }

        void add(int i, long long x) {
            while (i <= size) {
                node[i] += x;
                i += i & -i;
            }
        }

        long long sum(int i) {
            long long ret = 0;
            while (i > 0) {
                ret += node[i];
                i -= i & -i;
            }
            return ret;
        }

        long long range_sum(int l, int r) {
            return sum(r) - sum(l - 1);
        }
};

