void upd(int p, int val) {
    p++;
    for (; p < maxn; p += p & -p) {
        chkmax(fen[p], val);
    }
}

int query(int p) {
    p++;
    int res = 0;
    for (; p > 0; p -= p & -p) {
        chkmax(res, fen[p]);
    }
