void solve() {
    FOR(i, 0, 2) cin >> z[i] >> t[i];
    cin >> n;
    FOR(i, 0, n) cin >> x[i] >> y[i];
    long double ans = (long double) (abs(z[0] - z[1]) + abs(t[0] - t[1])) * 100;
    if (z[0] > z[1]) {
        swap(z[0], z[1]);
        swap(t[0], t[1]);
    }
    if (t[0] > t[1]) {
        t[0] *= -1, t[1] *= -1;
        FOR(i, 0, n) y[i] *= -1;
    }
    vii v;
    FOR(i, 0, n) {
        if (x[i] >= z[0] && x[i] <= z[1] && y[i] >= t[0] && y[i] <= t[1]) {
            v.pb(mp(x[i], y[i]));
        }
    }
    sort(all(v));
    n = sz(v);
    vi dc;
    FOR(i, 0, sz(v)) {
        x[i] = v[i].fi;
        y[i] = v[i].se;
        dc.pb(x[i]);
        dc.pb(y[i]);
    }
    sort(all(dc)), uni(dc);
    int tot = 0;
    FOR(i, 0, n) {
        x[i] = lower_bound(all(dc), x[i]) - dc.begin();
        y[i] = lower_bound(all(dc), y[i]) - dc.begin();
        int mx = query(y[i]);
        upd(y[i], mx + 1);
        chkmax(tot, mx + 1);
    }
    if (z[0] == z[1] || t[0] == t[1]) {
        cout << prec(15) << ans + n * (10 * PI - 20) << "\n";
        return;
    }
    ans -= (long double) tot * (20 - 10 * PI / 2);
    cout << prec(15) << ans << "\n";
}

