		else
		{
			for (;cl<SIZE(q1) && q1[cl].first<=p[i].x-2;++cl) update(w1,q1[cl].second.first,q1[cl].second.second);
			double t3=min(getw(w1,key),getw(w2,key-1));
			for (;cl<SIZE(q1) && q1[cl].first<=p[i].x-1;++cl) update(w1,q1[cl].second.first,q1[cl].second.second);
			double t4=min(getw(w1,key-1),getw(w2,key-2));
			t1=min(t4-save,t3+cost);
			t2=min(t3-save,t4+cost);
		}
		q1.push_back(MP(p[i].x,MP(key,t1)));
		update(w2,key,t2);
		if (my[i]==p[i].y)
		{
			if (p[i].x<dst.x) ckmin(ret,t1);
			if (p[i].y<dst.y) ckmin(ret,t2);
		}
	}
	return ret;
}

void preprocess()
{
	set<int64> w;
	w.insert(src.x);
	w.insert(dst.x);
	REP(i,n) w.insert(p[i].x);
	vector<int64> w1(ALL(w));
	int cnt=0;
	map<int64,int64> g;
	for (int i=0;i<SIZE(w1);i++) 
	{
		if (i>0 && w1[i]-1>w1[i-1]) g[w1[i]-1]=(++cnt);
		g[w1[i]]=(++cnt);
	}
	src.x=g[src.x];
	dst.x=g[dst.x];
	REP(i,n) p[i].x=g[p[i].x];
}

