int DFS(int x1, int y1, int x2, int y2){
    //cout << "(" << x1 << ", " << y1 << "), (" << x2 << ", " << y2 << ")" << endl;
    auto nx = fy.upper_bound(y1);
    auto ny = fx.upper_bound(x1);

    int cx = -1, cy = -1;
    if(nx == fy.end() || nx->second > x2 || nx->second < x1) cx = 0;
    if(ny == fx.end() || ny->second > y2 || ny->second < y1) cy = 0;

    if(cx == 0 && cy == 0) return 0;

    if(cx == -1) cx = DFS(nx->second, nx->first, x2, y2);
    if(cy == -1) cy = DFS(ny->first, ny->second, x2, y2);
    return 1 + max(cx, cy);
}

