struct Point
{
    int x, y;
    int ny;
};

bool cmpx (const Point &a, const Point &b)
{
    return a.x < b.x;
}

bool cmpy (const Point &a, const Point &b)
{
    return a.y < b.y;
}

Point a, b;

int n;

Point f[N_MAX];

int dp[N_MAX];

int BIT[N_MAX];

void update (int pos, int val)
{
    for(int i = pos; i <= n; i += i & -i)
        BIT[i] = max(BIT[i], val);
}

int query (int pos)
{
    int ans = 0;
    for(int i = pos; i >= 1; i -= i & -i)
        ans = max(ans, BIT[i]);
    return ans;
}

