    for(auto r: R){
        if((r.first - S.first) * (r.first - G.first) <= 0 && (r.second - S.second) * (r.second - G.second) <= 0) {
            A.pb(r.second);
        }
    }

    vector<ll> L;
    if(A.size() > 0){
        LIS lis(A);
        L = lis.calc();
    }

    double ans = 0.0;
    int sz = (int)L.size();
    if(sz == min(abs(S.first - G.first), abs(S.second - G.second)) + 1) {
        sz--;
        ans = 10.0 * pi - 20.0;
    }
    ans += (5.0 * pi - 20.0) * sz;
    ans += 100.0 * (abs(S.first - G.first) + abs(S.second - G.second));

    output(ans, 15);

    return 0;
}

