        has_space = false;
        for (int j = 1; j < cnt; j++) {
            if (y[j] - y[j - 1] > 1) {
                has_space = true;
                break;
            }
        }
    }

    ans -= cnt * 20 - cnt * 5 * M_PI;
    if (!has_space) {
        ans += 5 * M_PI;
    }

    cout << setprecision(15) << ans << endl;

    return 0;

}

#include <iostream>
