bool operator < (node a, node b) {
	return a.x != b.x ? a.x < b.x : a.y < b.y;
}

inline int hs(int a[], int x) {
	return lower_bound(a + 1, a + a[0] + 1, x) - a;
}

inline int gmx(int x) {
	if (x == 1) return -233;
	int ret = 0; for (; x; x -= lowbit(x)) ret = max(ret, C[x]); return ret;	
}

inline void add(int x, int v) {
	for (; x <= tbY[0]; x += lowbit(x)) C[x] = max(C[x], v);
}

int main() {
	int Xs, Ys, Xt, Yt;
