        Hash2[dots[i].second]=make_pair(true,dots[i].first);
    }
    sort(dots+1,dots+1+N);
    for(int i=1;i<=N;i++)
    {
        if(dots[i].first>=min(x2,x1)&&dots[i].first<=max(x1,x2)&&dots[i].second>=min(Y1,y2)&&dots[i].second<=max(Y1,y2))
            D[++Size]=dots[i].second;
    }
    Normalize();
    int Max=0;
    if(x1>x2)
        swap(Y1,y2);
    for(int i=1;i<=Size;i++)
    {
        Pos=D[i];
        Val=0;
