	}
	if(Sx>Tx) swap(Sx,Tx), swap(Sy,Ty);
	if(Sy<Ty)
		F(i,1,n) if(Sx<=x[i]&&x[i]<=Tx&&Sy<=y[i]&&y[i]<=Ty) X[++cnt]=x[i], Y[cnt]=y[i], P[cnt]=cnt;
	if(Sy>Ty)
