	if(it != my.begin()) {
		--it;
		if(it->first == wx && it->second >= qx) {
			updmin(ans, calc2(it->second + 1, it->first, ex, rx) + abs(it -> second - qx + 1) * 100.000 - 20.000 + len * 2.000);
