int find(int n)
{
	int n1 = 0;
	for(int i = 0; i < n; i++){
		int t = lower_bound(s, s+n1, c[i].y) - s;
		s[t] = c[i].y;
		if(t == n1) n1++;
	}
	return n1;
}

