    if (pexit)result += 10 * M_PI - 20;

  } else {

    Point start;
    Point end;
    if (p1<p2){
      start = p1;
      end   = p2;
    }else{
      start = p2;
      end   = p1;
    }
    sort(points.begin(),points.end());

    int xmin = min(start.x,end.x);
    int xmax = max(start.x,end.x);

    int ymin = min(start.y,end.y);
    int ymax = max(start.y,end.y);

    vector<int> data;
    for (int i=0;i<N;i++) {
      if (start.x<=points[i].x&&points[i].x<=end.x&&
	  ymin<=points[i].y&&points[i].y<=ymax)
	{
	  int d;
	  if (start.y<start.y)
	    d=points[i].y - start.y;
	  else
	    d=start.y - points[i].y;
	  data.push_back(d);
	}
    }
    int lis = solve(data.size(), data);
    if (lis!=0 && lis == data.size())
      result = 100 * (xmax - xmin + ymax - ymin) + (lis - 1) * (5 * M_PI - 20) + (10 * M_PI - 20);
    else 
      result = 100 * (xmax - xmin + ymax - ymin) + lis * (5 * M_PI - 20);
  }

  cout << setprecision(18) << result << endl;
  return 0;
}

