		int r = l;
		while(r < n && p[r].x == p[l].x) 
			r++;
		int ll = l;
		while(ll < r) {
			dp[ll] = get(p[ll].y) + 1;
			ll++;
		}
		for (int i = r - 1; i >= l; --i) {
			int up = -1;
			if (l && i - 1 >= l) {
				up = dp[i - 1] + 1;
				inc(p[i].y, up);
			}
			inc(p[i].y + 1, dp[i]);
			dp[i] = max(dp[i], up);
		}
		l = r;
	}	
	int cnt = get(N - 1);
	cerr << cnt << endl;
	ans -= 20 * cnt - 5 * cnt * PI;
	cout << ans << endl;
}

