void solve(int i)
{
	int res = 0;
	int v = next_x[i];
	if (v != -1)
	{
		if (rem[v] == 0 && in_y[i] > in_y[v])
			solve(v);
		if(in_y[i] > in_y[v])
			res = max(res, rem[v]);
	}

	v = next_y[i];

	if (v != -1)
	{
		if (rem[v] == 0 && i < v)
			solve(v);
		if (i < v)
			res = max(res, rem[v]);
	}

	rem[i] = res + 1;
}

