	FOR(i, 0, N)
		max_font = max(max_font, rem[i]);

	ans = (ld)(abs(s.X - f.X) + abs(s.Y - f.Y))*100.0;
	ans -= (max_font*5.0*(4.0 - PI));
	cout << fixed << setprecision(15) << ans;
	return 0;
}

