int n2;
int drz[nax * 2];

int odczyt(int a, int b) {
  assert(a <= b);
  a += n2;
  b += n2;
  int wynik = max(drz[a], drz[b]);
  while ((a / 2) != (b / 2)) {
    if (a % 2 == 0) wynik = max(wynik, drz[a + 1]);
    if (b % 2 == 1) wynik = max(wynik, drz[b - 1]);
    a /= 2;
    b /= 2;
  }
  return wynik;
}

void ustaw(int w, int x) {
  w += n2;
  while (w) {
    drz[w] = max(drz[w], x);
    w /= 2;
  }
}

