int loadvec(vector<int>& v, int N=-1) {
    if (N == -1) {
        N = loadint();
        if (N==0) return 0;
    }
    int bufsize = INTSPACE*N + 3;
    if (fgets(_buf, bufsize, stdin)==NULL) return 0;
    v.resize(N);

    int i=0;
    bool last = false;
    for (char *p=&_buf[0]; ;) {
        char *q = p;
        while (*q > ' ') ++q;
        if (*q == 0x0D || *q == 0x0A) last = true;
        *q = 0;
        v[i++] = atoi(p);
        if (last || i == N) break;
        p = q+1;
    }
    return i;
}


int lis(vector<int>& a) {
    int M = a.size();
    // cout << a << endl;
    assert(0 < M && M <= 200000);

    vector<int> dp(M, 1e9);
    dp[0] = a[0];
    int maxlen = 1;
    for (int i=1; i<M; ++i) {
        int len = (int)(lower_bound(dp.begin(),dp.begin()+i, a[i]) - dp.begin())+1;
        maxlen = max(maxlen, len);
        dp[len-1] = min(dp[len-1], a[i]);
    }
    // cout << dp << endl;
    return maxlen;
}

