vector<int> Symmetry(vector<int> x) {
  for (int i = 0; i < x.size(); ++i) x[i] *= -1;
  return x;
}

const int inf = 1000 * 1000 * 1000;

int LIS(const vector<int>& a) {
  int n = a.size();
  vector<int> d(n + 1);
  d[0] = -inf;
  for (int i = 1; i <= n; ++i) d[i] = inf; 

  for (int i = 0; i < n; ++i) {
    int j = int (upper_bound(d.begin(), d.end(), a[i]) - d.begin());
    if (d[j - 1] < a[i] && a[i] < d[j]) d[j] = a[i];
  }
  int j = n;
  while (d[j] == inf) --j;
  return j;
}

void Output(double x) {
  printf("%.10lf\n", x);
  exit(0);
}

int main()
{
