  for (int i = 0; i < n; ++i) cin >> x[i] >> y[i];
  if (x1 > x2) {
    x1 *= -1;
    x2 *= -1;
    x = Symmetry(x);
  }
  if (y1 > y2) {
    y1 *= -1;
    y2 *= -1;
    Symmetry(y);
  }
  if (x2 - x1 > y2 - y1) {
    swap(x1, y1);
    swap(x2, y2);
    swap(x, y);
  }

  vector<pair<int, int>> p(n);
