  sort(p.begin(), p.end());
  vector<int> a;
  for (auto q : p) if (x1 <= q.first && q.first <= x2) a.push_back(q.second);

  int len = LIS(a);
  cerr << "len = " << len << endl;
  double result1 = result + (5 * pi - 20) * (len - 1) + 10 * pi - 20;
  double result2 = result + (5 * pi - 20) * len;

  Output((len == x2 - x1 + 1) ? result1 : result2);

  return 0;
}

