    sort(all(pt));
    SegmentTreeBottomUp tree(vector<int>(n, -1));
    int qs = 0;
    forn(i, 0, n) {
        if (pt[i].fs < x1 || pt[i].fs > x2 || pt[i].sn < y1 || pt[i].sn > y2)
