using namespace std;
const double pi = acos(-1.0);
const double circle = 2*pi*10;

int LIS(const vector<pair<int, int> > &XY){
    const int inf = 1<<30;
    int n = XY.size();
    if(n==0)return 0;
    vector<int> L(n, inf);
    int p = 0;
    REP(i, n){
        int v = XY[i].second;
        if(L[p] < v){
            L[++p] = v;
        }else{
            int j = lower_bound(ALL(L), v) - L.begin();
            L[j] = v;
        }
    }
    return p+1;
}

