	int x;
    int y;
	point() : x(0), y(0) {}
};

struct fenwick_tree {
	int n;
  HashMap<int, int> F;

    fenwick_tree() : n(INF) {

    }
	void upd(int i, int x) {
		for (; i < n; i |= i + 1)
			F[i] = max(F[i], x);
	} 
	int get(int i) {
		int res = 0;
		for (; i >= 0; i &= i + 1, --i)
			res = max(res, F[i]);
		return res;
	}
};


