const int LO = 0 , HI = (int)1e8;
struct segtree{
  struct node{
    ll rs,mx;
    node *lt,*rt;
    node(){rs=mx=0;lt=rt=NULL;}
  };
  typedef node* pn;
  pn root=NULL;
  void pull(pn&it){
    it->rs = (it->lt?it->lt->rs:0)+(it->rt?it->rt->rs:0);
    it->mx = max((it->lt?it->lt->mx:0),(it->rt?it->rt->mx:0));
  }

  void upd(int &pos,ll &val,pn&it,int lx=LO,int rx=HI){
    if(it==NULL)it=new node();
    if(lx==rx){//==pos
      it->rs+=val;
      it->mx = it->rs;
      return;
    }
    int m = lx+rx>>1;
    if(pos<=m)upd(pos,val,it->lt,lx,m);
    if(pos>m)upd(pos,val,it->rt,m+1,rx);
    pull(it);
  }void upd(int pos,ll val){upd(pos,val,root);}

  ll qry(int &u,int &v,pn&it,int lx=LO,int rx=HI){
    if(it==NULL or u>rx or v<lx)return 0;
    if(u<=lx and rx<=v)return it->mx;
    int m = lx+rx>>1;
    return max(qry(u,v,it->lt,lx,m),qry(u,v,it->rt,m+1,rx));
  }ll qry(int u,int v){return qry(u,v,root);}

} T;

