bool cmp1(node u, node v) { return u.y < v.y; }
bool cmp2(node u, node v) { return u.y > v.y; }
LL a[maxn];
int main() {
    scanf("%lld%lld%lld%lld", &s.x, &s.y, &t.x, &t.y);
    double ans = 1.0 * (abs(s.x-t.x)+abs(s.y-t.y)) * 100;
    LL n;
//    printf("%.15f\n", ans);

    scanf("%lld", &n);
    for (LL i = 0; i < n; ++i) scanf("%lld%lld", &p[i].x, &p[i].y);
    if (s.x == t.x) {
        LL lo = s.y, hi = t.y;
        if (lo > hi) swap(lo, hi);
        bool flag = false;
        for (LL i = 0; i < n; ++i) {
            if (p[i].x == s.x && p[i].y > lo && p[i].y < hi) { flag = true; break; }
        }
        if (flag) ans += (PI * 10 - 20);
    }
    else {
        if (s.x > t.x) swap(s, t);
        if (s.y < t.y) {
            sort(p, p + n, cmp1);
            LL i = 0, tot = 0, cnt = 0;
            while (p[i].y < s.y) ++i;
            for (; i < n; ++i) {
                if (p[i].y > t.y) break;
                if (p[i].x < s.x || p[i].x > t.x) continue;
                while (tot > 0 && p[i].x < a[tot-1]) --tot;
                a[tot++] = p[i].x;
                cnt = max(cnt, tot);
            }
            if (cnt == min(t.y-s.y, t.x-s.x)+1) {
                --cnt;
                ans += (PI * 5 - 20) * cnt;
                ans += (PI * 10 - 20);
            }
            else ans += (PI * 5 - 20) * cnt;
        }
        else if (s.y > t.y) {
            sort(p, p + n, cmp2);
            LL i = 0, tot = 0, cnt = 0;
            while (p[i].y > s.y) ++i;
            for (; i < n; ++i) {
                if (p[i].y < t.y) break;
                if (p[i].x < s.x || p[i].x > t.x) continue;
                while (tot > 0 && p[i].x < a[tot-1]) --tot;
                a[tot++] = p[i].x;
                cnt = max(cnt, tot);
