namespace sgt {
// Single value modification, range maximum query

static const int MAXN = ::MAXN * 35;
int sz;
struct node { int l, r, lch, rch; int max; } t[MAXN];

inline void rebuild(int L, int R) {
    sz = 1;
    t[0] = (struct node){ L, R, -1, -1, 0 };
}

inline void assure(int &idx, int L, int R) {
    if (idx == -1) {
        idx = sz++;
        t[idx] = (struct node){ L, R, -1, -1, 0 };
    }
}

int QL, QR, QV;

inline int query(int idx) {
    if (idx == -1) return 0;
    if (t[idx].l >= QL && t[idx].r <= QR) return t[idx].max;
    int ans = 0, M = (t[idx].l + t[idx].r) / 2;
    if (M >= QL) ans = std::max(ans, query(t[idx].lch));
    if (M + 1 <= QR) ans = std::max(ans, query(t[idx].rch));
    return ans;
}
inline int query(int L, int R) { if (L > R) return 0; QL = L, QR = R; return query(0); }

inline void modify(int idx) {
    if (t[idx].l == t[idx].r) { t[idx].max = std::max(t[idx].max, QV); return; }
    if ((t[idx].l + t[idx].r) / 2 >= QL) {
        assure(t[idx].lch, t[idx].l, (t[idx].l + t[idx].r) / 2);
        modify(t[idx].lch);
    } else {
        assure(t[idx].rch, (t[idx].l + t[idx].r) / 2 + 1, t[idx].r);
        modify(t[idx].rch);
    }
    t[idx].max = 0;
    if (t[idx].lch != -1) t[idx].max = std::max(t[idx].max, t[t[idx].lch].max);
    if (t[idx].rch != -1) t[idx].max = std::max(t[idx].max, t[t[idx].rch].max);
}
inline void modify(int P, int V) { QL = P, QV = V; modify(0); }

}

