int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout << fixed << setprecision(20);

    int X1, Y1, X2, Y2, N;
    cin >> X1 >> Y1 >> X2 >> Y2 >> N;

    if (X1 == X2) {
        if (Y1 > Y2)swap(Y1, Y2);
        dbl ans = 100 * (Y2 - Y1);
        rep(i, N) {
            int x, y;
            cin >> x >> y;
            if (x == X1 && Y1 < y&&y < Y2)ans += 11.415926535897938;
        }
        cout << ans << endl;
    } else if (Y1 == Y2) {
        if (X1 > X2)swap(X1, X2);
        dbl ans = 100 * (X2 - X1);
        rep(i, N) {
            int x, y;
            cin >> x >> y;
            if (y == Y1 && X1 < x&&x < X2)ans += 11.415926535897938;
        }
        cout << ans << endl;
    } else {
        vi xs;
        vector<pii> p;

        // X1->X2
        if (X1 > X2) {
            swap(X1, X2);
            swap(Y1, Y2);
        }

        int miy = min(Y1, Y2), may = max(Y1, Y2);
        // Y1<Y2 or Y1>Y2 増加列、減少列
        rep(i, N) {
            int x, y;
            cin >> x >> y;

            if (X1 <= x&&x <= X2&&miy <= y&&y <= may) {
                xs.push_back(x);
                if (Y1 < Y2) {
                    p.push_back({ y,x });
                } else {
                    p.push_back({ -y,x });
                }
            }
        }
        sort(all(xs));
        xs.erase(unique(all(xs)), end(xs));
        sort(all(p));

        if (sz(xs) == 0) {
            cout << (may - miy + X2 - X1) * 100.0 << endl;
        } else {
            int M = sz(xs);
            RMaxQ32 rmq(M, 0);

            rep(i, M) {
                int k = distance(xs.begin(), lower_bound(all(xs), p[i].second));
                rmq.update(k, rmq.query(0, k) + 1);
            }

            dbl ans = (may - miy + X2 - X1) * 100.0;
            ans -= rmq.query(0, M)*4.292036732051031;
            cout << ans << endl;
        }
    }
}

