#include <bits/stdc++.h>
using namespace std;

typedef pair<int,int> Point;
#define x first
#define y second

const int N = 200010;
const int MAX = 1e8;

int n;
Point a[N];
Point p1, p2;
vector <Point> vec;
vector <int> Z;

double ans = 1e18;
const double pi = acos(-1);

// BIT
int T[N];
void upd(int x, int v) { for (; x < N; x += x & -x) T[x] = max(T[x], v); } 
int get(int x) { int res = 0; for (; x > 0; x -= x & -x) res = max(res, T[x]); return res; }
//

void solve() {
	if (p1 > p2) swap(p1, p2);
	if (p1.y > p2.y) {
		p1.y = MAX - p1.y; p2.y = MAX - p2.y;
		for (int i = 1; i <= n; ++i) a[i].y = MAX - a[i].y;
	}

	sort(a + 1, a + n + 1);
	vec.clear();

	for (int i = 1; i <= n; ++i) {
		if (a[i].x >= p1.x && a[i].x <= p2.x && a[i].y >= p1.y && a[i].y <= p2.y) {
			vec.push_back(a[i]);
		}
	}

	double res = 100.0 * (abs(p1.x - p2.x) + abs(p1.y - p2.y));

	if (!vec.size()) { cout << res << endl; exit(0); }
	else {
		if (vec[0].x == p1.x && vec.back().x == p2.x) {
			bool ok = 1;
			for (int i = 1; i < (int)vec.size(); ++i) {
				if (vec[i].x == vec[i-1].x + 1 && vec[i].y == vec[i-1].y + 1) continue;
				else { ok = 0; break; }
			}
			if (ok) {
				res -= 20.0 * (int)vec.size();
				res += ((int)vec.size() + 1) * pi * 5.0;
				cout << res << endl; exit(0);
			}
		}
	}

	Z.clear();
	for (auto cur: vec) Z.push_back(cur.y);
	sort(Z.begin(), Z.end());
	memset(T, 0, sizeof T);

	int mx = 0;
	for (auto cur: vec) {
		int pos = lower_bound(Z.begin(), Z.end(), cur.y) - Z.begin() + 1;
		int rr = get(pos - 1) + 1;
		upd(pos, rr);
		mx = max(mx, rr);
	}

	res -= 20.0 * mx;
	res += 5.0 * pi * mx;
	ans = min(ans, res);
}

int main() {
	ios_base::sync_with_stdio(false); cin.tie(0);
	cin >> p1.x >> p1.y >> p2.x >> p2.y;
	cout << setprecision(11) << fixed;
	cin >> n;
	for (int i = 1; i <= n; ++i) cin >> a[i].x >> a[i].y;
	solve();

	swap(p1.x, p1.y); swap(p2.x, p2.y);
	for (int i = 1; i <= n; ++i) swap(a[i].x, a[i].y);

	solve();

	cout << ans << endl;
}

