const int64_t INF=10000000000000000;

int main(){
	pair<int64_t,int64_t> start;
	pair<int64_t,int64_t> goal;
	const int64_t size=100000001;
	cin>>start.first>>start.second>>goal.first>>goal.second;
	int64_t n;
	cin>>n;
	vector<pair<int64_t,int64_t> > fountains;
	fountains.resize(n);
	for(int64_t i1=0;i1<n;i1++){
		cin>>fountains[i1].first>>fountains[i1].second;
	}
	sort(fountains.begin(),fountains.end());
	if(start.first>goal.first){
		swap(start,goal);
	}
	bool mirror=false;
	if(start.second>goal.second){
		mirror=true;
	}
	vector<pair<int64_t,int64_t> > on_way;
	on_way.reserve(n);
	for(auto i1=fountains.begin();i1!=fountains.end();i1++){
		if(start.first<=i1->first&&i1->first<=goal.first){
			if((start.second<=i1->second&&i1->second<=goal.second)||(start.second>=i1->second&&i1->second>=goal.second)){
				if(mirror){
					on_way.push_back(make_pair(i1->first,size-i1->second));
				}else{
					on_way.push_back((*i1));
				}
			}
		}
	}
	if(mirror){
		start.second=size-start.second;
		goal.second=size-goal.second;
	}
	int64_t f_num=0;
	if(!on_way.empty()){
		int64_t dp[on_way.size()];
		fill(dp,dp+on_way.size(),INF);
		for(int64_t i1=0;i1<on_way.size();i1++){
			*lower_bound(dp,dp+on_way.size(),on_way[i1].second)=on_way[i1].second;
		}
		f_num=lower_bound(dp,dp+on_way.size(),INF)-dp;
	}
	double ans=(goal.second-start.second)*100+(goal.first-start.first)*100;


	if(f_num==min(goal.second-start.second+1,goal.first-start.first+1)){
		ans=ans+(10*M_PI-20)-(f_num-1)*(20-5*M_PI);
	}else{
		ans=ans-f_num*(20-5*M_PI);
	}
	cout<<fixed<<setprecision(15)<<ans<<endl;





}

