int solve(){
	static int st[N],mx;
	mx=0;memset(st,0,sizeof(st));
	for(int i=1;i<=m;i++){
		int now=upper_bound(st,st+mx+1,v[i].se)-st;
		if(now>mx)mx=now,st[mx]=v[i].se;else st[now]=min(v[i].se,st[now]);
	}
	return mx;
