const int mxn = 3e5;

struct BIT {
	int tree[mxn];
	BIT() {
		f(i,0,mxn) tree[i] = 0;
	}
	void add(int i, int v) {
		for (; i<mxn; i|=i+1)
			Max(tree[i],v);
	}
	int sum(int i) {
		int ans = 0;
		for (; i >= 0; i = (i&(i+1))-1) {
			Max(ans,tree[i]);
		}
		return ans;
	}

};

