}
struct MaST{
private:
    ll n;
    vector<pll> dat;
public:
    MaST(vector<ll> v){
        ll sz=v.size();
        n=1;while(n<sz)n*=2;
        pll p={-inf,-inf};
        dat.resize(2*n-1,p);
        rep(i,0,sz)dat[i+n-1]={v[i],i};
        rrep(i,n-2,0){
            dat[i]=max(dat[i*2+1],dat[i*2+2]);
        }
    }
    void add(ll k,ll x){
        ll i=k+n-1;
        dat[i]={x,k};
        while(i>0){
            i=(i-1)/2;
            dat[i]=max(dat[2*i+1],dat[2*i+2]);
        }
    }
    pll que(ll a,ll b,ll k=0,ll l=0,ll r=-1){
        if(r<0)r=n;
        if(b<=l||a>=r)return {-inf,-inf};
        if(a<=l&&b>=r)return dat[k];
        pll m1=que(a,b,2*k+1,l,(l+r)/2);
        pll m2=que(a,b,2*k+2,(l+r)/2,r);
        return max(m1,m2);
    }
};
bool ok(int sx,int sy,int gx,int gy,int x,int y){
    if(sx<=x&&gx>=x&&sy<=y&&gy>=y)return true;
    else return false;
}
int main(){
    ios::sync_with_stdio(false);cin.tie(0);
