        gx=-gx;
        kx=-1;
    }
    if(sy>gy){
        sy=-sy;
        gy=-gy;
        ky=-1;
    }
    int kk=0;
    int sax=gx-sx,say=gy-sy;
    if(sax<say){
        gx=sx+say;
        gy=sy+sax;
        kk=1;
    }
    int n;cin>>n;
    vector<ppii> v;
    vector<int> w;
    rep(i,0,n){
        int x,y;cin>>x>>y;
        x*=kx;
        y*=ky;
        if(kk){
            sax=x-sx,say=y-sy;
            x=sx+say,y=sy+sax;
        }
        int pax=x,pay=y-1,nex=x+1,ney=y;
        if(ok(sx,sy,gx,gy,pax,pay)&&ok(sx,sy,gx,gy,nex,ney)){
            v.push_back({{nex,ney},1});
            v.push_back({{pax,pay},0});
            w.push_back(pay);
            w.push_back(ney);
        }
        pax=x-1,pay=y,nex=x,ney=y+1;
        if(ok(sx,sy,gx,gy,pax,pay)&&ok(sx,sy,gx,gy,nex,ney)){
            v.push_back({{nex,ney},1});
            v.push_back({{pax,pay},0});
            w.push_back(pay);
            w.push_back(ney);
        }
        if(x==gx&&y>sy&&y<gy){
            v.push_back({{x,y-1},2});
            w.push_back(y-1);
        }
        if(y==gy&&x>sx&&x<gx){
            v.push_back({{x-1,y},3});
            w.push_back(y);
        }
    }
    sort(w.begin(),w.end());
    w.erase(unique(w.begin(),w.end()),w.end());
    map<int,int> mp;
    rep(i,0,w.size())mp[w[i]]=i;
    sort(v.begin(),v.end());
    int m=w.size();
    MaST seg0(vector<ll>(m,-1)),seg1(vector<ll>(m,-1));
    map<pii,int> mp20,mp21;
    seg0.add(m-1,0);
    rrep(i,v.size()-1,0){
        int num=v[i].second,nx=v[i].first.first,ny=v[i].first.second;
        //cout<<num<<" "<<nx<<" "<<ny<<endl;
        int nny=mp[ny];
        if(num==1){
            pll p=seg0.que(nny,m);
            int ax=p.first;
            if(ax>=0)ax++;
            mp20[{nx-1,ny-1}]=ax;
            p=seg1.que(nny,m);
            ax=p.first;
            if(ax>=0)ax++;
            mp21[{nx-1,ny-1}]=ax;
        }
        else if(num==0){
            seg0.add(nny,mp20[{nx,ny}]);
            seg1.add(nny,mp21[{nx,ny}]);
        }
        else if(num==2){
            seg1.add(nny,0);
        }
        else{
            seg1.add(m-1,0);
            seg0.add(m-1,-1);
        }
    }
    //cout<<m<<endl;
    pll p=seg0.que(0,m);
    int h=p.first;
    double ans=1000000000000000;
    //cout<<h<<endl;
    if(h>=0){
        double sum=((gx-sx)+(gy-sy))*100.0;
        sum-=1.0*h*(20.0-5*pi);
