struct p{
    int x, y;
    p(int x, int y): x(x), y(y) {}
};
vector<p> need;

bool cmp1(const p &lhs, const p &rhs){
    return lhs.y < rhs.y;
}

bool cmp2(const p &lhs, const p &rhs){
    return lhs.y > rhs.y;
}

int main()
{
    ios_base::sync_with_stdio(0);
    int x1, y1, x2, y2;
    cin >> x1 >> y1 >> x2 >> y2;
    if(x1 > x2){
        swap(x1, x2);
        swap(y1, y2);
    }
    cin >> n;
    for(int i = 0; i < n; i++){
        int x, y;
        cin >> x >> y;
        if(x >= x1 && x <= x2 && y >= min(y1, y2) && y <= max(y1, y2)){
            need.pb(p(x, y));
        }
    }
    if(need.empty()){
        double ans = 100.0 * (abs(x1 - x2) + abs(y1 - y2));
        cout << fixed << setprecision(12) << ans << endl;
        exit(0);
    }
    if(x1 == x2 || y1 == y2){
        double ans = 100.0 * (abs(x1 - x2) + abs(y1 - y2));
        if(!need.empty()){
            ans -= 20;
            ans += 2.0 * pi * 10.0 / 2;
        }
        cout << fixed << setprecision(12) << ans << endl;
        exit(0);
    }
    if(y1 < y2) sort(need.begin(), need.end(), cmp1);
    else sort(need.begin(), need.end(), cmp2);
    int cnt = 1;
    int last = need.front().x;
    for(int i = 1; i < need.size(); i++){
        if(need[i].x > last){
            last = need[i].x;
            cnt++;
        }
    }
    double ans = 100.0 * (abs(x1 - x2) + abs(y1 - y2));
    ans -= 20.0 * (double)cnt;
    ans += 2.0 * pi * 10.0 / 4 * (double)cnt;
    cout << fixed << setprecision(12) << ans << endl;
    return 0;
}

