typedef pair<int,int> pun;
typedef long long ll;

const long double PI = 3.141592653589793238462643383279;

int MAX[N];

void ustaw(int v, int p, int k, int a, int x) {
	if (k <= a) return;
	if (p > a) return;
	if (p + 1 == k) MAX[v] = max(MAX[v], x);
	else {
		int s = (p + k) / 2;
		ustaw(2*v, p, s, a, x);
		ustaw(2*v+1, s, k, a, x);
		MAX[v] = max(MAX[2 * v], MAX[2 * v + 1]);
	}
}

int czytaj(int v, int p, int k, int a, int b) {
	if (k <= a || p >= b) return 0;
	if (a <= p && k <= b) return MAX[v];
	int s = (p+k)/2;
	return max(czytaj(2*v, p, s, a, b), czytaj(2*v+1, s, k, a, b));
}

