            swap(y1,y2);
        }
        if (y1>y2)
        {
            swap(y1,y2);
            for (i=0;i<n;i++)
            {
                y[i]=y1+y2-y[i];
            }
        }
        int num=0;
        for (i=0;i<n;i++)
        {
            if ((x1<x[i])&&(x[i]<x2)&&(y1<y[i])&&(y[i]<y2))
            {
                c[num].x=x[i];
                c[num].y=y[i];
                num++;
            }
        }
        sort(c,c+num);
        for (i=0;i<num;i++)
        {
            ans[i]=999999999;
        }
        int now_max_ans=0;
        for (i=0;i<num;i++)
        {
            int t=lower_bound(ans,ans+now_max_ans,c[i].y)-ans;
            if (t==now_max_ans) now_max_ans++;
            ans[t]=c[i].y;
        }
        double final_ans=(y2-y1)*100ll+(x2-x1)*100ll-now_max_ans*10*(2-pi/2);
        printf("%.15lf\n",final_ans);
    }
    return 0;
}

