long long LIS(vector<long long>R) {
	for (int i = 0; i <= R.size(); i++) S[i] = -(1LL << 60);

	int sz = 0;
	for (int i = 0; i < R.size(); i++) {
		int pos1 = lower_bound(S, S + sz, R[i]) - S;
		if (pos1 == sz) sz++;
		S[pos1] = R[i];
	}
	return 1LL * sz;
}

