template<typename T>
int lis(const vector<T> &a, bool is_strict = true) {
    T INF = numeric_limits<T>::max();
    vector<T> dp(a.size(), INF);
    for (T ai: a) {
        if (is_strict) *lower_bound(begin(dp), end(dp), ai) = ai;
        else *upper_bound(begin(dp), end(dp), ai) = ai;
    }
    return lower_bound(begin(dp), end(dp), INF) - begin(dp);
}

