}

main() {
//    freopen("input.txt", "r", stdin);
    int x1, y1, x2, y2;
    scanf("%d%d%d%d", &x1, &y1, &x2, &y2);
    if (x1 > x2) {
        swap(x1, x2);
    }
    if (y1 > y2) {
        swap(y1, y2);
    }
    int n;
    scanf("%d", &n);
    vector<ii> arr;
    for (int i = 0; i < n; ++i) {
        int x, y;
        scanf("%d%d", &x, &y);
        if (x >= x1 && x <= x2 && y >= y1 && y <= y2) {
            arr.push_back({x, y});
        }
    }
    n = arr.size();
    int d = x2 - x1 + y2 - y1;
    if (n == 0) {
        printf("%lld", 100ll * d);
        return 0;
    }
    cout.precision(40);
    cout.fixed;
    if (x1 == x2 || y1 == y2) {
        long double ans = 100ll * d - 20 + 10 * PI;
        cout << ans << endl;
        return 0;
    }
    sort(arr.begin(), arr.end(), &cmp);
    vector<int> dp(n + 1, INF);
    dp[0] = -INF;
    int kek = 0;
    for (int i = 0; i < n; ++i) {
        int j = lower_bound(dp.begin(), dp.end(), arr[i].sc) - dp.begin();
        if (dp[j - 1] < arr[i].sc && dp[j] > arr[i].sc) {
            dp[j] = arr[i].sc;
            if (kek < j) {
                kek = j;
            }
        }
    }
    int mn = min(x2 - x1, y2 - y1);
    long double ans = 100ll * d - 20 * kek + kek * 5 * PI + 5 * PI * (kek == mn);
    cout << ans;
}

