struct BIT {
    vector<int> tree;
    void init() {
        tree = vector<int>(4*Xn, 0);
    }
    void upd(int idx, int val, int l, int r, int n) {
        if(idx < l || r < idx) return;
        if(l == r) {
            tree[n] = max(tree[n], val);
            return;
        }
        int m = (l + r)>>1;
        upd(idx, val, l, m, 2*n);
        upd(idx, val, m + 1, r, 2*n + 1);
        tree[n] = max(tree[2*n], tree[2*n + 1]);
    }
    int quer(int a, int b, int l, int r, int n) {
        if(b < l || r < a) return 0;
        if(a <= l && r <= b) return tree[n];
        int m = (l + r)>>1;
        int L = quer(a, b, l, m, 2*n);
        int R = quer(a, b, m + 1, r, 2*n + 1);
        return max(L, R);
    }
} bit;

pii st, ed;
vector<int> dp;

bool cmp(pii a, pii b) {
    return a.first < b.first || (a.first == b.first && ((st.second < ed.second)? (a.second < b.second) : (a.second > b.second)));
}

int main() {
    scanf("%d %d %d %d %d", &X1, &Y1, &X2, &Y2, &N);
    st = pii(X1, Y1);
