    X.push_back(Y1);
    X.push_back(Y2);
    P.resize(N);
    for(int i = 0; i < N; i++) {
        scanf("%d %d", &P[i].first, &P[i].second);
        X.push_back(P[i].second);
    }

    cout<<fixed;
