struct segtree
{
  int tree[1048576];
  int size;

  void reset()
  {
    size = 1;
    while(size < n + 1){
      size <<= 1;
    }
  }

  void add(int x, int much)
  {
    int now = size - 1 + x;
    tree[now] += much;
    now = (now - 1) / 2;
    while(true){
      tree[now] = max(tree[now * 2 + 1], tree[now * 2 + 2]);
      if(now == 0){
	break;
      }
      now = (now - 1) / 2;
    }
  }

  int mx(int start, int end, int left, int right, int now)
  {
    if(end < left || right < start){
      return 0;
    }
    if(start <= left && right <= end){
      return tree[now];
    }
    return max(mx(start, end, left, (left + right) / 2, now * 2 + 1), mx(start, end, (left + right) / 2 + 1, right, now * 2 + 2));
  }
} tr;


