            cin >> a >> b;
            if(a >= X1 and a <= X2 and b == Y1){
                ans = abs(X1 - X2) * 100.0 + pi * 10 - 20;
            }
        }
        cout << ans << endl;
    }else{
        tot = 0;
        for(int i = 1;i <= n;i++){
            cin >> l[i] >> r[i];
        }
        if(Y1 > Y2){
            Y1 = -Y1;
            Y2 = -Y2;
            for(int i = 1;i <= n;i++){
                r[i] = -r[i];
            }
        }
        vector<pair<int, int> > A;
        for(int i = 1;i <= n;i++){
            if(l[i] >= X1 and l[i] <= X2 and r[i] >= Y1 and r[i] <= Y2){
                v[++tot] = r[i];
                A.eb(l[i], r[i]);
            }
        }
        sort(A.begin(), A.end());
        int m = tot;
        vector<int> B(m, 0);
        sort(v + 1, v + 1 + tot);
        tot = unique(v + 1, v + 1 + tot) - v - 1;
        for(int i = 0;i < m;i++){
            B[i] = lower_bound(v + 1, v + 1 + tot, A[i].se) - v;
        }
        memset(dp, 0x3f, sizeof(dp));
        dp[0] = 0;
        int ans = 0;
        for(int i = 0;i < m;i++){
            int id = lower_bound(dp, dp + n + 1, B[i]) - dp - 1;
            dp[id + 1] = min(dp[id + 1], B[i]);
        }
        for(int i = 0;i <= n;i++){
            if(dp[i] != 0x3f3f3f3f){
                ans = max(ans, i);
            }
        }
        if(ans == min(Y2 - Y1, X2 - X1) + 1){
            cout << (abs(X1 - X2) + abs(Y1 - Y2)) * 100.0 + (ans - 1) * (pi * 5 - 20) + (pi * 10 - 20) << endl;
        }else{
            cout << (abs(X1 - X2) + abs(Y1 - Y2)) * 100.0 + ans * (pi * 5 - 20) << endl;
        }
    }
    return 0;
}

