void solve(){

    i64 x1,y1,x2,y2,N;
    cin >> x1 >> y1 >> x2 >> y2 >> N;

    vector<pair<i64,i64>> XY(N);
    rep(i,0,N) cin >> XY[i].first >> XY[i].second;

    if(x1>x2){
        x1=100000000-1-x1;
        x2=100000000-1-x2;
        rep(i,0,N) XY[i].first=100000000-1-XY[i].first;
    }

    if(y1>y2){
        y1=100000000-1-y1;
        y2=100000000-1-y2;
        rep(i,0,N) XY[i].second=100000000-1-XY[i].second;
    }

    const long double pi=acosl(-1);
    if(x1==x2){
        i64 count=0;
        rep(i,0,N) if(XY[i].first==x1 and y1<=XY[i].second and XY[i].second<=y2) ++count;
        cout << 100*(y2-y1)+10*2*(pi/2-1)*count << endl;
        return;
    }
    if(y1==y2){
        i64 count=0;
        rep(i,0,N) if(XY[i].second==y2 and x1<=XY[i].first and XY[i].first<=x2) ++count;
        cout << 100*(x2-x1)+10*2*(pi/2-1)*count << endl;
        return;
    }

    vector<i64> ys;
    ys.push_back(y1);
    ys.push_back(y2);
    rep(i,0,N) ys.push_back(XY[i].second);
    sort(ys.begin(),ys.end());
    ys.erase(unique(ys.begin(),ys.end()),ys.end());

    unordered_map<i64,i64> y_to_i;
    rep(i,0,ys.size()) y_to_i[ys[i]]=i;

    segtree<i64,max_> seg(ys.size(),-inf64,0);
    sort(XY.begin(),XY.end());

    i64 lb=y_to_i[y1],ub=y_to_i[y2];
    rep(i,0,N){
        if(XY[i].first<x1) continue;
        if(x2<XY[i].first) break;
        i64 i_=y_to_i[XY[i].second];
        if(i_<lb or ub<i_) continue;
        seg.add(i_,seg.query(lb,i_+1)+1);
    }

    cout << 100*((x2-x1)+(y2-y1))+10*(pi/2-2)*seg.query(lb,ub+1) << endl;
}

