using P = std::pair<int, int>;

constexpr double PI = 3.141592653589793238;

int n;

bool used[200000];

std::vector<P> vec;

int memo[200000];

int dx, dy;

int dfs(int m) {

	if (memo[m] >= 0)
		return memo[m];

	int res = 0;

	int v;

	if (dx > 0)
		v = std::upper_bound(vec.begin(), vec.end(), vec[m]) - vec.begin();
	else
		v = std::lower_bound(vec.begin(), vec.end(), vec[m]) - vec.begin() - 1;

	if (v < 0)
		return memo[m] = 0;

	for (int i = v; i < vec.size(); ++i) {
		if (dy > 0 && vec[m].second < vec[i].second)
			res = std::max(res, dfs(i));
		else if (dy<0 && vec[m].second>vec[i].second)
			res = std::max(res, dfs(i));
	}

	return memo[m] = res + 1;
}

int main() {

	int x1, y1, x2, y2;

	std::cin >> x1 >> y1 >> x2 >> y2 >> n;

	std::memset(memo, -1, sizeof(memo));

	P p;

	for (int i = 0; i<n; ++i) {
		std::cin >> p.first >> p.second;

		if (( (x1 <= p.first&&p.first <= x2) || (x2 <= p.first&&p.first <= x1) )&&
		((y1 <= p.second&&p.second <= y2) || (y2 <= p.second&&p.second <= y1))) {
			vec.emplace_back(p);
		}
	}

	if (x1 == x2 || y1 == y2) {

		int cnt = 0;

		for (int i = 0; i < vec.size(); ++i) {
			if (x1 == vec[i].first || y1 == vec[i].second)
				++cnt;
		}

		long double ans = (std::abs(x1 - x2) + std::abs(y1 - y2)) * 100.0 - 20.0 * (1.0 - PI / 2)*(double)cnt;

		std::cout << std::fixed << std::setprecision(15) << ans << std::endl;

		return 0;
	}

	if (x1 < x2)
		dx = 1;
	else
		dx = -1;
	if (y1 < y2)
		dy = 1;
	else
		dy = -1;

	std::sort(vec.begin(), vec.end());

	int cnt = 0;

	for (int i = 0; i < vec.size(); ++i) {

		if (!used[i])
			cnt = std::max(cnt, dfs(i));
	}

	double ans = double(std::abs(x1 - x2) + std::abs(y1 - y2)) * 100.0 - 20.0 * (1.0 - PI/4)*(double)cnt;

	std::cout << std::fixed << std::setprecision(15) << ans << std::endl;

	return 0;
}

