            last = p[i].fr;
        }
    }
    return cn == (en.sc - st.sc + 1);
}
inline bool Check2 ()
{
    if ( en.fr - st.fr + 1 > n )
        return false;


    int cn = 0, last = -1;

    for (int i = 1; i <= n; i++)
    {
        if ( p[i].fr >= st.fr && p[i].fr <= en.fr )
        {
            cn++;
