using namespace std;
typedef pair<int,int> pii;

const int MAXN=2e5+2+5;
const double PI = 3.141592653589793238462;
const double GAIN=20-2*PI*10/4;
const double LOSS=2*PI*10/2-20;

int x1,y1,x2,y2;
int N;
int X[MAXN], Y[MAXN];

int st[2*MAXN];
void update(int i, int v) {
        for (st[i += N] = v; i>1; i>>=1)
                st[i>>1] = max(st[i],st[i^1]);
}

int query(int a, int b) {
        if (a > b) swap(a,b);
        b++;
        int res=0;
        for (a+=N, b+=N; a < b; a>>=1, b>>=1) {
                if (a&1) res = max(res,st[a++]);
                if (b&1) res = max(res,st[--b]);
        }
        return res;
}

int mxtrn() {
        if (x1 > x2) {
                swap(x1,x2);
                swap(y1,y2);
        }

        vector<pii> fountains;
        for (int i=0; i<N; i++)
                fountains.push_back(pii(X[i],i));

        sort(fountains.begin(), fountains.end());

        int i=0;
        while (i < N && fountains[i].first < x1)
                i++;

        for (; i < N && fountains[i].first < x2; ++i) {
                int cur = fountains[i].second;
                update(Y[cur],1+query(y1,Y[cur]));
        }

        return query(y1,y2);
}

int main()
{
        cin >> x1 >> y1 >> x2 >> y2;
        cin >> N;
        for (int i=0; i<N; ++i)
                cin >> X[i] >> Y[i];

        cout << setprecision(11) << fixed;
        if (x1 == x2) {
                for (int i=0; i<N; ++i) {
                        if (X[i] == x1 && Y[i] > min(y1,y2) && Y[i] < max(y1,y2)) {
                                cout << 100*abs(y1-y2) + LOSS << "\n";
                                return 0;
                        }
                }
                cout << 100*abs(y1-y2) << "\n";
        } else if (y1 == y2) {
                for (int i=0; i<N; ++i) {
                        if (Y[i] == y1 && X[i] > min(x1,x2) && X[i] < max(x1,x2)) {
                                cout << 100*abs(x1-x2) + LOSS << "\n";
                                return 0;
                        }
                }
                cout << 100*abs(x1-x2) << "\n";
        } else {
                cout << 100*abs(x1-x2) + 100*abs(y1-y2) - mxtrn()*GAIN << "\n";
        }
}

