void flip(int &x) {
	x=100000000-x;
}
vector< pair<int,int> > v;
vector<int> vec;
int id(int x){
	return lower_bound(vec.begin(),vec.end(),x) - vec.begin() + 1;
}
long double bit[N];
void add(int pos,long double x) {
	while(pos<N){
		bit[pos]=max(bit[pos],x); pos+=pos&(-pos);
	}
}
long double query(int pos){
	long double ans=0;
	while(pos){
		ans=max(ans,bit[pos]); pos-=pos&-pos;
	}
	return ans;
}
bool WANDAN = 0;
long double dp[N];
long double LIS() {
	if(v.size()==0) return 0;
	for(int i=0;i<N;i++)dp[i]=-1e18;
	sort(v.begin(),v.end());
	for(auto p: v) {
		//printf("%d %d\n", p.first,p.second);
		vec.push_back(p.second);
	}
	sort(vec.begin(),vec.end()); 
	int low = -1e9;
	for(auto p: v) {
		if(p.first==x2-x1) low=p.second;
	}
	long double ans=-1e18;
	for(int i=0;i<v.size();i++){
		bool fg=0;
		if(v[i].first==x2-x1 || v[i].second==y2-y1) fg=1;
		if(fg==0) {
			dp[i]=query(id(v[i].second))+20-5*PI;
			if(WANDAN || (v[i].first+1 == x2-x1 && v[i].second < low))
				ans=max(ans,dp[i]-(10*PI-20));
			else
				ans=max(ans,dp[i]);
		}
		add(id(v[i].second),dp[i]);
	}
	//printf("%.8Lf\n", ans);
	return ans;
}
