	for(int i=1;i<=n;i++){
		scanf("%d%d",&x[i],&y[i]);
	}
	if(x1>x2){
		flip(x1), flip(x2);
		for(int i=1;i<=n;i++){
			flip(x[i]);
		}
	}
	if(y1>y2){
		flip(y1), flip(y2);
		for(int i=1;i<=n;i++){
			flip(y[i]);
		}
	}
	for(int i=1;i<=n;i++){
		if(x[i]<=x2 && x[i]>=x1 && y[i]<=y2 && y[i]>=y1) {
			v.push_back(make_pair(x[i]-x1, y[i]-y1));
		}
