	bool f1=0,f2=0;
	for(int i=1;i<=n;i++){
		if(x[i]>=x1&&x[i]<=x2&&y[i]>=y1&&y[i]<=y2){
			if(x[i]==x2 && y[i]==y2-1) f1=1;
			if(x[i]==x2-1 && y[i]==y2) f2=1;
		}
	}
	if (f1 && f2) WANDAN = 1;

	long double ans = 100.0 * ((x2-x1)+(y2-y1)) - LIS();

	printf("%.12Lf\n", ans);
