const ld r = 10;
const ld PI = acos(-1.0);

int lis(vi a) {
	vi c;
	for (int x : a) {
		c.pb(x);
	}
	sort(all(c));
	c.resize(unique(all(c)) - c.begin());
	for (int& x : a) {
		x = lower_bound(all(c), x) - c.begin(); 
	}

	const int INF = 1e9;
	vi dp(sz(a) + 1, INF);
	dp[0] = -INF;
	for (int x : a) {
		int pos = upper_bound(all(dp), x) - dp.begin();
		--pos;
		assert(pos >= 0);
		dp[pos + 1] = min(dp[pos + 1], x);
	}
	ford(i, sz(dp)) {
		if  (dp[i] < INF) {
			return i;
		}
	}
	assert(0);
	return -1;
}

ld solve() {
	if  (S.x > F.x) {
		swap(S, F);
	}

	int x1 = S.x;
	int x2 = F.x;
	int y1 = S.y;
	int y2 = F.y;
	if  (y1 > y2) {
		swap(y1, y2);
	}

	auto contain = [&](const pnt& p) {
		return (x1 <= p.x && p.x <= x2) && (y1 <= p.y && p.y <= y2);
	};

	if  (S.x == F.x || S.y == F.y) {
		bool bad = 0;
		for (const auto& p : ps) {
			if  (contain(p)) {
				assert(!bad);
				bad = 1;
			}
		}

		ld ans = (abs(S.x - F.x) * 1ll + abs(S.y - F.y)) * 100.0;
		if  (bad) {
			ans -= r * 2;
			ans += PI * r;
		}
		return ans;
	}

	vector<pnt> nps;
	for (const auto& p : ps) {
		if  (contain(p)) {
			nps.pb(p);
		}
	}
	ps.swap(nps);

	sort(all(ps));
	forn(i, sz(ps) - 1) {
		assert(ps[i].x != ps[i + 1].x);
	}
	vi ys;
	for (const auto& p : ps) {
		ys.pb(p.y);
	}

	if  (S.y > F.y) {
		reverse(all(ys));
	}

	ld corners = lis(ys);

	ld ans = (abs(S.x - F.x) * 1ll + abs(S.y - F.y)) * 100.0;

	// printf("init ans = %.10f\n", (double) ans);

	ans -= corners * (2 * r);
	ans += corners * ((r / 2) * PI);
	return ans;
}

