unordered_map<int, ld> t;

void upd(int v, int tl, int tr, int pos, ld val) {
    if (tl == tr)
        t[v] = val;
    else {
        int tm = (tl + tr) / 2;
        if (pos <= tm)
            upd(v * 2, tl, tm, pos, val);
        else
            upd(v * 2 + 1, tm + 1, tr, pos, val);
        ld x = t.count(v * 2)? t[v * 2] : 2e8;
        ld y = t.count(v * 2 + 1)? t[v * 2 + 1] : 2e8;
        t[v] = min(x, y);
    }
}

ld get(int v, int tl, int tr, int l, int r) {
    if (l > r)
        return 2e8;
    if (l == tl && r == tr)
        return t.count(v)? t[v] : 2e8;
    int tm = (tl + tr) / 2;
    return min(get(v * 2, tl, tm, l, min(r, tm)),
               get(v * 2 + 1, tm + 1, tr, max(l, tm + 1), r));
}

