vector<int> a;

bool cmpl( int a, int b ) {
	return a < b;
}
bool cmpg( int a, int b ) {
	return a > b;
}

int f[MAXN], fn = 0;
int lis( bool cmp(int,int) ) {
	for( int i = 0; i < (int)a.size(); ++i ) {
		int x = a[i];
		int low = 0, high = fn;
		while( low < high ) {
			int mid = (low + high)/2;
			if( cmp( f[mid], x ) ) low = mid + 1;
			else high = mid;
		}
		f[low] = x;
		if( low == fn ) ++fn;
	}
	return fn;
}

void solve() {
	if( sx > tx )
		swap(sx, tx), swap(sy, ty);
	int up = min(sx, tx);
	int down = max(sx, tx);
	int left = min(sy, ty);
	int right = max(sy, ty);
	for( int i = 0; i < n; ++i )
		if( x[i] >= up && x[i] <= down && y[i] >= left && y[i] <= right )
			pt.push_back( pii( x[i], y[i] ) );
	sort( pt.begin(), pt.end() );
	for( int i = 0; i < (int)pt.size(); ++i )
		a.push_back( pt[i].second );
	int cnt = lis( sy < ty ? cmpl : cmpg );
	double ans = down - up + right - left;
	ans *= 100;
	ans -= cnt * (20 - 5*PI);
	if( cnt == min(right-left+1, down-up+1) )
		ans += 5*PI;
	printf( "%.16lf\n", ans );
}

