		f(i,0,n) Y[i] = y2-Y[i]+y1;
	}
	map<int,int> com;
	f(i,0,n) com[Y[i]]=0;
	int t = 0;
	for (pii pp : com) 
		com[pp.first] = t++;
	f(i,0,n) Y[i] = com[Y[i]];
	vi p(n);
	f(i,0,n) p[i] = i;
	sort(begin(p),end(p),[&](int i, int j) {
		return X[i] < X[j];
	});
	BIT ds;
	int num = 0;
	f(j,0,n) {
		int i = p[j];
		int z = ds.query(Y[i])+1;	
		ds.cmod(Y[i],z);
		Max(num,z);
	}
	if (((x1==x2)||(y1==y2))&&n)
		res += 10*M_PI-20;
	else
		res += num*(5*M_PI-20);
	cout << setprecision(30) << res << endl;

#ifdef LOCAL
	cout << setprecision(12) << (long double)(clock()-start) / CLOCKS_PER_SEC << endl;
#endif

	return 0;
}

