const double inf = 5e15;
typedef pair<double, PI> PDPI;

double tertia(PL p1, PL p2, int n, vector<PL> &pt) {
  const double coef = 5 * pi - 20;
  // LIS, longest increasing subsequence
  // VI m(n + 1);
  map<PDPI, int> mulier;
  vector<bool> zugzwang(n, false);
  vector<bool> unflee(n, false);
  vector<PL> pamo(n);
  REP(i, 0, n) {
    pamo[i] = PL(pt[i].second, i);
  }
  sort(pamo.begin(), pamo.end());
  REP(i, 0, n) {
    if (pamo[i].first == i + p1.second) {
      unflee[pamo[i].second] = true;
      if (DEBUG) cerr << "unflee: " << i << endl;
    } else {
      break;
    }
  }
  for (int i = n - 1; i >= 0; --i) {
    if ((i == n - 1 && pt[i].first == p2.first)
	|| (i < n - 1 && pt[i].first == pt[i + 1].first - 1
	    && pt[i].second < pt[i + 1].second)) {
      zugzwang[i] = true;
      if (DEBUG) cerr << "zugzwang: " << i << endl;
    } else {
      break;
    }
  }
  double mi = inf;
  if (n == 0) {
    return 0.0;
  }
  REP(i, 0, n) {
    double lo = -1e10;
    double hi = 1e10;
    bool hit = false;
    PI corde(-1, -1);
    REP(beatavirgo, 0, 100) {
      double mid = (hi + lo) / 2;
      map<PDPI, int>::iterator it = mulier.lower_bound(PDPI(-mid, PI(-1, -1)));
      if (it != mulier.end() && pt[it->second].second < pt[i].second) {
	lo = mid;
	hit = true;
      } else {
	hi = mid;
      }
      if (it != mulier.end()) {
	corde = it->first.second;
      }
    }
    assert (!hit || corde.first >= 0);
    if (DEBUG) {
      cerr << "found corde: " << corde.first << " " << corde.second << endl;
    }
    if (not hit) {
      lo = hi = 0;
      corde = PI(0, 0);
    }
    corde.first += 1;
    if (unflee[i]) {
      corde.second += 1;
    }
    double dist = corde.first * coef + 5 * pi * corde.second;
    if (DEBUG) {
      cerr << "[" << i << "]:" << endl;
      cerr << "lo = " << lo << endl;
      cerr << "dist = " << dist << endl;
      cerr << "corde = " << corde.first << " " << corde.second << endl;
    }
    // normalize
    mulier[PDPI(-dist, corde)] = i;
    if (DEBUG) {
      cerr << "pt[i]:" << pt[i].first << " " << pt[i].second << endl;
      cerr << "p2:" << p2.first << " " << p2.second << endl;
    }
    mi = min(mi, dist + (zugzwang[i] ? 5 * pi : 0));
  }
  if (DEBUG) {
    cerr << "mi = " << mi << endl << endl;
  }
  return mi;
}

double solve(PL p1, PL p2, int n, vector<PL> &pt) {
  // preprocess
  if (p1.first > p2.first) {
    p1.first = -p1.first;
    p2.first = -p2.first;
    REP(i, 0, n) {
      pt[i].first = -pt[i].first;
    }
  }
  if (p1.second > p2.second) {
    p1.second = -p1.second;
    p2.second = -p2.second;
    REP(i, 0, n) {
      pt[i].second = -pt[i].second;
    }
  }
  // trim
  vector<PL> pool;
  REP(i, 0, n) {
    if (p1.first <= pt[i].first && pt[i].first <= p2.first
	&& p1.second <= pt[i].second && pt[i].second <= p2.second) {
      pool.push_back(pt[i]);
    }
  }
  sort(pool.begin(), pool.end());
  int nn = pool.size();
  double mi = tertia(p1, p2, nn, pool);
  // swap x/y
  swap(p1.first, p1.second);
  swap(p2.first, p2.second);
  REP(i, 0, nn) {
    swap(pool[i].first, pool[i].second);
  }
  sort(pool.begin(), pool.end());
  mi = min(mi, tertia(p1, p2, nn, pool));
  return mi;
}

int main(void) {
  PL p1 = get();
  PL p2 = get();
  int n;
  cin >> n;
  vector<PL> pt(n);
  REP(i, 0, n) {
    pt[i] = get();
  }
  double res = abs(p1.first - p2.first) + abs(p1.second - p2.second);
  res *= 100;
  double add = solve(p1, p2, n, pt);
  printf("%.15f\n", res + add);
}

