int main() {
  vector<int> a(2), b(2);
  scanf("%d %d %d %d", &a[0], &a[1], &b[0], &b[1]);
  if (a[0] > b[0]) {
    swap(a, b);
  }
  int n;
  vector<vector<int>> var;
  scanf("%d", &n);
  int flag = a[1] <= b[1] ? 1 : -1;
  while (n--) {
    int x, y;
    scanf("%d %d", &x, &y);
    if (x >= a[0] && x <= b[0] && y >= min(a[1], b[1]) && y <= max(a[1], b[1])) {
      var.push_back({x, flag * y});
    }
  }
  sort(var.begin(), var.end());
  vector<int> t;
  for (auto &v : var) {
    if (t.empty() || t.back() < v[1]) {
      t.push_back(v[1]);
    }
    else {
      int low = 0, high = t.size() - 1;
      while (low < high) {
        int mid = (low + high) >> 1;
        if (t[mid] < v[1]) {
          low = mid + 1;
        }
        else {
          high = mid;
        }
      }
      t[low] = v[1];
    }
  }
  double res = 100.00 * (abs(a[0] - b[0]) + abs(a[1] - b[1]));
  if (t.size() == min(abs(a[0] - b[0]), abs(a[1] - b[1])) + 1) {
