vector<int> ys;
vector<pii> xy;
int N;

struct Seg {
    int N;
    int data[800000];

    Seg(int n) {
        N = 1;
        while (N < n)N *= 2;
        memset(data, 0, sizeof(data));
        data[0] = 0;
    }

    //[a,b)->x
    void query(int k, int l, int r, int a, int b, int x) {
        //cerr << "called" << endl;
        if (r <= a || b <= l)return;
        if (a <= l && r <= b) {
            data[k] = x;
            return;
        }
        data[k] = -1;
        int m = (l + r) / 2;
        query(2 * k + 1, l, m, a, b, x);
        query(2 * k + 2, m, r, a, b, x);
    }

    void query(int a, int b, int x) {
        query(0, 0, N, a, b, x);
    }

    int val(int i) {
        i = i + N - 1;
        int res = data[i];
        while (i) {
            i = (i - 1) / 2;
            if (data[i] != -1)res = data[i];
        }
        return res;
    }
};

const int n108 = 100000000;
bool yrev = false;

signed main() {
    cin >> X1 >> Y1 >> X2 >> Y2;
    if (X1 > X2) {
        swap(X1, X2);
        swap(Y1, Y2);
    }
    if (Y1 > Y2) {
        Y1 = n108 - Y1;
        Y2 = n108 - Y2;
        yrev = true;
    }
    long double ans = (X2 - X1 + Y2 - Y1) * 100;
    xs.push_back(X1);
    xs.push_back(X2);
    ys.push_back(Y1);
    ys.push_back(Y2);
    int n;
    cin >> n;
    rep(i, n) {
        int x, y;
        cin >> x >> y;
        if (yrev) {
            y = n108 - y;
        }
        if (X1 <= x && x <= X2) {
            if (Y1 <= y && y <= Y2) {
                xs.push_back(x);
                ys.push_back(y);
                xy.push_back(pii(x, y));
                N++;
            }
        }
    }
    sort(xs.begin(), xs.end());
    sort(ys.begin(), ys.end());
    xs.erase(unique(xs.begin(), xs.end()), xs.end());
    ys.erase(unique(ys.begin(), ys.end()), ys.end());
    assert(xy.size() == N);
    rep(i, N) {
        xy[i].FI = l_b(xs.begin(), xs.end(), xy[i].FI) - xs.begin();
        xy[i].SE = l_b(ys.begin(), ys.end(), xy[i].SE) - ys.begin();
    }
    X1 = l_b(xs.begin(), xs.end(), X1) - xs.begin();
    X2 = l_b(xs.begin(), xs.end(), X2) - xs.begin();
    Y1 = l_b(ys.begin(), ys.end(), Y1) - ys.begin();
    Y2 = l_b(ys.begin(), ys.end(), Y2) - ys.begin();
    sort(xy.begin(), xy.end());
    Seg seg = Seg(N + 10);
    rep(i, xy.size()) {
        int x = xy[i].FI;
        int y = xy[i].SE;
        seg.query(y + 1, ys.size(), seg.val(y) + 1);
    }
    if (seg.val(ys.size() - 1) == 0) {
        assert(0);
    }
    printf("%.15lf", (double) ans + seg.val(ys.size() - 1) * (5 * M_PI - 20));
}

