void stupdate(int in, int l, int r , int i, int v) {
    if (i<l || r<i) return;
    if ( l==r && l==i) {
        val[in] = v;
        return;
    }
    int mid = (l+r)/2;
    stupdate( getlft(in) , l , mid,  i , v );
    stupdate( getrgt(in) , mid+1, r , i , v );
    val[in] = max( val[ getlft(in) ] , val[ getrgt(in) ] );
}

void update(int i, int v) {
    //st[i] = v;
    stupdate(1,0,1e8,i,v);
}

int stquery(int in, int l, int r, int ql, int qr) {

    if (r<ql || qr<l) return 0;
    if ( ql<=l && r<=qr ) return val[in];
    int mid = (l+r)/2;
    return max(
               stquery( getlft(in) , l , mid , ql , qr ) ,
               stquery( getrgt(in) , mid+1 , r , ql , qr )
               );
}

