int tree[2*SIZ];
int query(int a, int b) {
    a += SIZ; b += SIZ;
    int res = max(tree[a], tree[b]);
    while (a/2 != b/2) {
        if (a%2 == 0) res = max(res, tree[a+1]);
        if (b%2 == 1) res = max(res, tree[b-1]);
        a/=2; b/=2;
    }
    return res;
}

void put(int x, int v) {
    x += SIZ;
    tree[x] = max(tree[x], v);
    x /= 2;
    while (x > 0) {
        tree[x] = max(tree[2*x], tree[2*x+1]);
        x/=2;
    }
}
