#define PI (3.1415926535897938)

using namespace std;

int x1, y1, x2, y2;
int N;
vector<int> X;
vector<int> Y;

double ans;

void input()
{
	cin >> x1 >> y1 >> x2 >> y2;
	cin >> N;
	X = vector<int>(N);
	Y = vector<int>(N);
	for (int i = 0; i < N; i++){
		cin >> X[i] >> Y[i];
	}
}

void process()
{
	ans = (abs(x2 - x1) + abs(y2 - y1)) * 100;
	if (x1 == x2){
		sort(X.begin(), X.end());
		if (binary_search(X.begin(), X.end(), x1)){
			ans -= 20;
			ans += PI * 10;
		}
	} else if (y1 == y2){
		sort(Y.begin(), Y.end());
		if (binary_search(Y.begin(), Y.end(), y1)){
			ans -= 20;
			ans += PI * 10;
		}
	} else {
		vector<long long int> A = vector<long long int>(N);
		for (int i = 0; i < N; i++){
			A[i] = (long long int)X[i] * 100000000 + Y[i];
		}
		sort(A.begin(), A.end());
		vector<long long int>::iterator start = lower_bound(A.begin(), A.end(), (long long int)x1 * 100000000);
		if (x1 > x2 && *start >= ((long long int)x1 + 1) * 100000000) start--;

		vector<int> point = vector<int>(abs(x1 - x2) + 1, -1);
		while (*start % 100000000 != x2){
			if (x1 < x2){
				if (*start > ((long long int)x2 + 1) * 100000000) break;

				int nx = *start / 100000000;
				int ny = *start % 100000000;
				if (y1 < y2){
					point[nx - x1] = ny - y1;
				} else {
					point[nx - x1] = y1 - ny;
				}

				start++;
				if (start == A.end()) break;
			} else {
				if (*start < (long long int)x2 * 100000000) break;

				int nx = *start / 100000000;
				int ny = *start % 100000000;
				if (y1 < y2){
					point[x1 - nx] = ny - y1;
				} else {
					point[x1 - nx] = y1 - ny;
				}

				start--;
