int main() {
    ios_base::sync_with_stdio(false);
    ll a, b, c, d;
    cin >> a >> b >> c >> d;
    if(a > c){
        swap(a, c);
        swap(b, d);
    }
    bool inv = false;
    if(b > d){
        swap(b, d);
        inv = true;
    }
    ll n;
    cin >> n;
    vector<pll> p;
    ll o, oo;
    for(ll i = 0; i < n; ++i){
        cin >> o >> oo;
        if(o >= a && o <= c && oo >= b && oo <= d){
            p.push_back({o, oo});
        }
    }
    if(a == c || b == d){
        ld ans = ((d - b) + (c - a)) * 100;
        ld fo = pi * 10 - 20;
        ans += min((ld)200, fo * p.size());
        cout << setprecision(18) << fixed << ans << endl;
        return 0;
    }
    ld ans = (c - a) + (d - b);
    ans *= 100;
    ld foun = -20 + 5 * pi;
    sort(p.begin(), p.end());
    ll cur = 0;
    if(!inv) {
        vector<ll> mx(p.size() + 1, INF);
        for (ll i = 0; i < p.size(); ++i) {
            ll l = 0, r = p.size(), mid;
            while (r - l > 1) {
                mid = (r + l) >> 1LL;
                if (mx[mid] > p[i].second) {
                    r = mid;
                } else {
                    l = mid;
                }
            }
            mx[r] = p[i].second;
            cur = max(cur, r);
        }
    }else{
        vector<ll> mx(p.size() + 1, INF);
        for (ll i = 0; i < p.size(); ++i) {
            ll l = 0, r = p.size(), mid;
            while (r - l > 1) {
                mid = (r + l) >> 1LL;
                if (mx[mid] > -p[i].second) {
                    r = mid;
                } else {
                    l = mid;
                }
            }
            mx[r] = -p[i].second;
            cur = max(cur, r);
        }
    }
    ans += foun * cur;
    if(cur == min(c - a, d - b) + 1){
        ans += 5 * pi;
    }
    cout << setprecision(18) << fixed << ans << endl;
    return 0;
}

