typedef long double ld;
struct Node
{
	ld val;
	int left, right;
};
Node rangetree[7000000];
int upto;
void update(int node, ld val, int curr = 1, int cstart = 0, int cend = 100000000)
{
	if (cstart == cend)
	{
		rangetree[curr].val = val;
		return;
	}

	int mid = (cstart+cend)/2;
	if (node <= mid) { 
		if (!rangetree[curr].left) rangetree[curr].left = ++upto;
		update(node, val, rangetree[curr].left, cstart, mid);
	}
	else {
		if (!rangetree[curr].right) rangetree[curr].right = ++upto;
		update(node, val, rangetree[curr].right, mid+1, cend);
	}
	rangetree[curr].val = max(rangetree[rangetree[curr].left].val, rangetree[rangetree[curr].right].val);
}
ld query(int start, int end, int curr = 1, int cstart = 0, int cend = 100000000)
{
	if (start <= cstart && cend <= end)
	{
		return rangetree[curr].val;
	}
	int mid = (cstart+cend)/2;
	if (end <= mid)
	{
		return query(start, end, rangetree[curr].left, cstart, mid);
	}
	else if (start > mid) return query(start, end, rangetree[curr].right, mid+1, cend);
	else return max(query(start, end, rangetree[curr].left, cstart, mid), query(start, end, rangetree[curr].right, mid+1, cend));
}
