const double PI = acos(-1.0);

bool inside(int x, int a, int b) {
  return min(a, b) <= x and x <= max(a, b);
}

long long dist(int x1, int y1, int x2, int y2) {
  return abs(x1 - x2) + abs(y1 - y2);
}

int LIS(vector<int> &v) {
  vector<int> lis;

  for (auto &x : v) {
    auto it = upper_bound(lis.begin(), lis.end(), x);
    if (it == lis.end()) {
      lis.push_back(x);
    } else {
      *it = x;
    }
  }

  return lis.size();
}

int main() { IO;
  int x1, y1, x2, y2;
  cin >> x1 >> y1 >> x2 >> y2;

  int n;
  cin >> n;

  vector<pair<int,int>> v(n);
  for (auto &p : v) {
    cin >> p.first >> p.second;
  }
  sort(v.begin(), v.end());

  vector<int> points;
  for (auto &p : v) {
    if (inside(p.first, x1, x2) and inside(p.second, y1, y2)) {
      points.push_back(p.second);
    }
  }

  if (y1 > y2) {
    reverse(points.begin(), points.end());
  }

  int lis = LIS(points);
  int d = dist(x1, y1, x2, y2);
  double ans = 100. * (d - 2 * lis) + 2. * lis * 90. + 5. * lis * PI;

  int sz = min(abs(x1 - x2), abs(y1 - y2))  + 1;
  if (sz == lis) {
    ans += 5 * PI;
  }

  cout.precision(15);
  cout << fixed << ans << endl;

  return 0;
}

