int dp[200002];		//dp[length] = min(max)
const double PAI = 3.141592653589793238;

signed main()
{
	int i;

	cin >> sx >> sy >> gx >> gy;
	cin >> n;
	for (i = 0; i < n; i++) cin >> x[i] >> y[i];

	if (sx > gx) { swap(sx, gx); swap(sy, gy); }
	if (sy > gy) {
		sy *= -1;
		gy *= -1;
		for (i = 0; i < n; i++) { y[i] *= -1; }
	}

	for (i = 0; i < n; i++) {
		if (sx <= x[i] && x[i] <= gx && sy <= y[i] && y[i] <= gy) {
			p.push_back(P(x[i], y[i]));
		}
	}
	sort(p.begin(), p.end());

	//LIS
	int INF = 1145141919810;
	for (i = 0; i <= n + 1; i++) dp[i] = INF;
	dp[0] = 0;
	for (i = 0; i < p.size(); i++) {
		dp[lower_bound(dp, dp + n + 1, p[i].second) - dp] = p[i].second;
	}
	for (i = n; i > 0; i--) {
		if (dp[i] < INF) break;
	}

	//LISの長さ
	int Count = i;

	//場合分け
	double ans;

	if (sx == gx) {
		ans = (gy - sy) * 100 + Count * (PAI - 2) * 10;
	}

	else if (sy == gy) {
		ans = (gx - sx) * 100 + Count * (PAI - 2) * 10;
	}

	else {
		ans = (gy - sy + gx - sx) * 100 - Count * (2 - PAI / 2) * 10;
		if (Count == min(gx - sx, gy - sy) + 1) ans += ((PAI - 2) - (2 - PAI / 2)) * 10;
	}

	printf("%.20Lf\n", ans);
	return 0;
}

