int cal(vector<int>& a) {
  if(a.size()==0)return 0;
  n = a.size();
  int len = 1; b[0] = a[0];
  for (int i = 1; i < n; i++) {
    b[a[i] > b[len - 1] ? len++ : lower_bound(b, b + len, a[i]) - b] = a[i];
  }
  return len;
}

