int lc(vector<int>& a) {
    int n = a.size();
    if (n == 0) {
        return 0;
    }
    vector<int> d(n + 1);
    d[0] = -INF;
    for (int i=1; i<=n; ++i) {
        d[i] = INF;
    }

    for (int i=0; i<n; i++) {
        int j = upper_bound(d.begin(), d.end(), a[i]) - d.begin();
        if (d[j-1] < a[i] && a[i] < d[j]) {
            d[j] = a[i];
        }
    }
    for (int i = n; i >= 0; --i) {
        if (d[i] != INF) {
            return i;
        }
    }
    return 0;
}

long double find_min(vector<pair<int, int>>& a, int x1, int y1, int x2, int y2) {
