						LD zouka = nextXXX - 20 + 5.0*PI;
						if( nextLineY.find(resY) != nextLineY.end() ){
							nextLineY[resY] = min(nextLineY[resY],itr->second + res1 + zouka);
						}else{
							nextLineY[ resY ] = itr->second + res1 + zouka;
						}
						/*噴水の位置がずれている場合
						通り過ぎる必要はない。Ｘ一つに付き噴水は１以下。
						*/

