							int index = itr->first + nextY;//下に移動
							//噴水がありそうは座標に移動でいいよね？
							LD res = zY[index]-zY[index-nextY];//下の移動分
							res = abs(res);
							LD res2 = res + nextXXX - 20 + 5.0*PI;

							if( nextLineY.find(index) != nextLineY.end() ){
								nextLineY[index] = min(nextLineY[index],itr->second + res + res2);
							}else{
								nextLineY[ resY ] = itr->second + res + res2;
