			end = LineY.end();

			for(;itr!=end;++itr){
				//まっすぐ進む分増やす
				nextLineY[itr->first] = itr->second + nextXXX;
			}
		}
		LineY = nextLineY;
	}

	LD ANS = LINF;
	//最後のライン
	if( zXY.find( goal.first ) != zXY.end() ){
