const double pi = acos(-1.);
const int maxn = 200100;

vector<pair<int, int> > vc;

int solution() {

	double dec = 20 - pi * 10 / 2.;
	int x1, y1, x2, y2;
	scanf("%d%d%d%d", &x1, &y1, &x2, &y2);
	int mx = 1, my = 1;
	if(x1 > x2) {
		mx = -1;
		x1 *= mx;
		x2 *= mx;
	}
	if(y1 > y2) {
		my = -1;
		y1 *= my;
		y2 *= my;
	}
	int n;
	scanf("%d", &n);
	for(int i = 0; i < n; i++) {
		int x, y;
		scanf("%d%d", &x, &y);
		x *= mx, y *= my;
		if(x1 <= x && x <= x2 && y1 <= y && y <= y2) {
			vc.pb(mp(x, y));
		}
	}
	sort(vc.begin(), vc.end());
	vector<int> p;
	n = vc.size();
	for(int i = 0; i < n; i++) {
		int pos = lower_bound(p.begin(), p.end(), vc[i].sc) - p.end();
		if(pos == p.size()) {
			p.pb(0);
		}
		p[pos] = vc[i].sc;
	}
	double ans = (x2 - x1 + y2 - y1) * 100ll - ll(p.size()) * dec;
	if((x1 == x2 || y1 == y2) && n) {
		ans += pi * 10 - 20 + dec;
	}
	printf("%.10lf", ans);

	return (0);
}

