struct pos_t
{
	int x, y;
};


bool cmp_x(const pos_t&a, const pos_t&b)
{
	return a.x<b.x;
}


bool cmp_y(const pos_t&a, const pos_t&b)
{
	return a.y<b.y;
}


void calc(int rq, ll&b, ll&s)
{
//  2^63=9223372036854775808
	ll p=4292036732051033808LL;
	ll m=1000000000000000000LL;

	b=0;
	s=0;
	for(int i=0;i<rq;i++)
	{
		s+=p;
		b+=s/m;
		s%=m;
	}

	if(s)
	{
		b++;
		s=m-s;
	}
}


void print(int dx, int dy, int rq, int hq)
{
	ll ans=(abs(dx)+abs(dy))*100LL;

	if(hq)
	{
		ans+=11;
		printf("%lld.415926535897932384626433832795\n", ans);
	}
	else
	{
		ll b, s;
		calc(rq, b, s);
		ans-=b;
		printf("%lld.%018lld\n", ans, s);
	}
}


