#define MaxN 200005
#define INF 2140000000
#define MOD 1000000007
#define pi 3.1415926535897932384626433832795
#define MaxT 1100005
using namespace std;

int x1,x2,Y1,y2,N,T[MaxT],Pos,Val,D[MaxN],Size=0,S2=0,S[MaxN],Max=0;
pair<int,int> dots[MaxN];
void Update(int node,int Start,int End)
{
    if(Start==End)
        T[node]=Val;
    else
    {
        int mid=(Start+End)>>1;
        if(Pos>mid)
            Update(2*node+1,mid+1,End);
        else Update(2*node,Start,mid);
        T[node]=max(T[2*node],T[2*node+1]);
    }
}
void Query(int node,int Start,int End)
{
    if(End<=Pos)
        Val=max(Val,T[node]);
    else
    {
        int mid=(Start+End)>>1;
        Query(2*node,Start,mid);
        if(mid<Pos)
            Query(2*node+1,mid+1,End);
    }
}
int Search(int val)
{
    int lw=1,hi=S2,mid;
    while(lw<=hi)
    {
        mid=(lw+hi)>>1;
        if(S[mid]>val)
            hi=mid-1;
        else if(S[mid]<val)
            lw=mid+1;
        else return mid;
    }
}
int main()
{
    cin>>x1>>Y1>>x2>>y2>>N;
    for(int i=1;i<=N;i++)
        cin>>dots[i].first>>dots[i].second;
    sort(dots+1,dots+1+N);
    for(int i=1;i<=N;i++)
        if(dots[i].first>=min(x2,x1)&&dots[i].first<=max(x1,x2)&&dots[i].second>=min(Y1,y2)&&dots[i].second<=max(Y1,y2))
            D[++Size]=dots[i].second;
    if(x1>x2)swap(Y1,y2),swap(x1,x2);
    if(Y1>y2)for(int i=1;i<=Size;i++)D[i]=Y1+y2-D[i];
    memcpy(S,D,sizeof D);
    sort(S+1,S+1+Size);
    for(int i=1;i<=Size;i++)
        if(S[i]!=S[S2])
            S[++S2]=S[i];
    for(int i=1;i<=Size;i++)
        D[i]=Search(D[i]);
    for(int i=1;i<=Size;i++)
    {
        Pos=D[i];
        Val=0;
        Query(1,1,MaxN);
        Max=max(Max,++Val);
        Update(1,1,MaxN);
    }
    if(Max<=min(max(x1,x2)-min(x1,x2),max(Y1,y2)-min(Y1,y2)))
        printf("%.12lf",100.0*(abs(x1-x2)+abs(Y1-y2))+Max*(5.0*pi-20.0));
    else printf("%.12lf",100.0*(abs(x1-x2)+abs(Y1-y2))+Max*(5.0*pi-20.0)+5.0*pi);
    return 0;
}

