    X1 *= inv_x; X2 *= inv_x;
    Y1 *= inv_y; Y2 *= inv_y;
    if (inv_y < 0) {
        cout << -1 << endl;
    }

    for (int i = 0; i < N; i++) {
        cin >> x[i] >> y[i];
        x[i] *= inv_x; y[i] *= inv_y;
        if (X1 <= x[i] && x[i] <= X2 && Y1 <= y[i] && y[i] <= Y2) {
            a.push_back(pii(x[i], y[i]));
        }
    }
    sort(a.begin(), a.end());
    K = a.size();

    fill(dp, dp + K, INF);
    for (int j = 0; j < K; j++) {
        *lower_bound(dp, dp + K, a[j].second) = a[j].second;
    }
    cnt = lower_bound(dp, dp + K, INF) - dp;
    arcs = (cnt == min(X2 - X1, Y2 - Y1) + 1) ? cnt + 1 : cnt;

    ans = ((X2 - X1) + (Y2 - Y1)) * 100;
    ans -= cnt * 20 - arcs * 5 * PI_L;

    cout << fixed << setprecision(15) << ans << endl;

    return 0;

}

