        t[v].val = max( t[v].val, val );
    }
    else
    {
        int tm = (tl + tr) >> 1;
        if (pos <= tm)
        {
            if (!t[v].l) t[v].l = ++Sz;
            update( pos, val, t[v].l, tl, tm );
        }
        else {
            if (!t[v].r) t[v].r = ++Sz;
            update( pos, val, t[v].r, tm + 1, tr );
        }
        t[v].val = max(t[ t[v].l ].val , t[ t[v].r ].val);
    }
