struct Node{
    ll posX;
    ll posY;
    double cost;
    bool operator< (const Node &r) const{
        return cost > r.cost;
    }
};

int main(){
    ll srcX, srcY, sinkX, sinkY;
    cin >> srcX >> srcY >> sinkX >> sinkY;

    ll n;
    cin >> n;

    map<ll, set<ll>> x2ys;
    rep(i, n){
        ll fx, fy;
        cin >> fx >> fy;
        x2ys[fx].insert(fy);
    }

    double d = M_PI*20.0/4.0;
    int dX = (srcX < sinkX)? 1:-1;
    int dY = (srcY < sinkY)? 1:-1;

    priority_queue<Node> que;
    que.push({srcX, srcY, 0.0});

    double INF = 1e10;
    vector<vector<double>> visited(abs(sinkX-srcX)+1, vector<double>(abs(sinkY-srcY)+1, INF));

    while(!que.empty()){
        Node node = que.top(); que.pop();

        if(visited[abs(node.posX-srcX)][abs(node.posY-srcY)] != INF){
            continue;
        }

        visited[abs(node.posX-srcX)][abs(node.posY-srcY)] = node.cost;


        if(node.posX == sinkX && node.posY == sinkY) break;

        if(node.posX != sinkX){
            ll nextX = node.posX+dX;
            if(0 == x2ys[nextX].count(node.posY)){
                que.push({nextX, node.posY, node.cost+100});
            }
            else{
                if(nextX != sinkX){
                    que.push({nextX+dX, node.posY, node.cost+200-20+(2*d)});
                }
                if(node.posY != sinkY){
                    que.push({nextX, node.posY+dY, node.cost+200-20+d});
                }
            }
        }

        if(node.posY != sinkY){
            ll nextY = node.posY+dY;
            if(0 == x2ys[node.posX].count(nextY)){
                que.push({node.posX, nextY, node.cost+100});
            }
            else{
                if(nextY != sinkY){
                    que.push({node.posX, nextY+dY, node.cost+200-20+(2*d)});
                }
                if(node.posX != sinkX){
                    que.push({node.posX+dX, nextY, node.cost+200-20+d});
                }
            }
        }
    }

    cout << fixed << setprecision(15) <<
        visited[abs(srcX-sinkX)][abs(srcY-sinkY)] << endl;




    return 0;
}

