		if(r<=a || b<=l){
			return mp(-(1ll<<31),-1);
		}

		pa v1=segmax(a,b,k*2,l,(l+r)/2),v2=segmax(a,b,k*2+1,(l+r)/2,r);

		if(v1.first>=v2.first)return v1;
		else return v2;
	}



