int get (int l, int r, int v = 1, int tl = 0, int tr = 1e8)
{
    if (l > tr || tl > r || v == 0)
        return 0;

    if (l <= tl && tr <= r)
        return t[v].val;

    int tm = (tl + tr) >> 1;

