inline void add(ll x){
	work(x); zl=Max(zl,po);
	for (int i=1; i<=zl; ++i) zs[i]+=f[i];
	for (int i=1; i<=zl; ++i) zs[i+1]+=zs[i]/10,zs[i]%=10;
	if (zs[zl+1]) ++zl;
	return;
}

inline void del(ll x){
	work(x);
	for (int i=1; i<=zl; ++i) zs[i]-=f[i];
	for (int i=1; i<=zl; ++i) if (zs[i]<0) --zs[i+1],zs[i]+=10;
	while(zs[zl]==0 && zl) --zl;
	return;
}

inline void mul(int x){
	for (int i=1; i<=zl; ++i) zs[i]*=x;
	for (int i=1; i<=zl; ++i) zs[i+1]+=zs[i]/10,zs[i]%=10;
	while(zs[zl+1]) ++zl,zs[zl+1]+=zs[zl]/10,zs[zl]%=10;
	return;
}

