int comp(vector<int> ss)
{
    vector<int> dp(ss.size());
    for (int i = 0; i < ss.size(); i++)
    {
        dp[i] = 1;
        for (int j = 0; j < i; j++)
        {
            if (ss[j] < ss[i]) dp[i] = max(dp[i], dp[j] + 1);
        }
    }
    if (dp.size() == 0) return 0;
    return *max_element(all(dp));
