// Longest (Strictly) Increasing Sequence
class LIS{
public:
    vector<ll> S, L;
    LIS(vector<ll> S) : S(S) {}

    vector<ll> calc(){
        int len = 1; // length of LIS
        L.push_back(S[0]);
        rep(i, 1, S.size()){
            if (L[len - 1] < S[i]) {
                L.push_back(S[i]);
                len++;
            }
            else{
                int l = -1, r = len - 1;
                while (r - l > 1) {
                    int mid = (r + l) / 2;
                    if (L[mid] >= S[i]) {
                        r = mid;
                    }
                    else{
                        l = mid;
                    }
                }
                if(L[r] > S[i]) L[r] = S[i];
            }
        }
        return L;
    }
};
double pi = acos(-1.0);

