  	if(nextPar.x == -1) break;
  	currIdx = nextPar.id;
  }

  if(foutainInPath == 0) {
  	cout<<res;
  	return 0;
  }

  double delta = R*2.0 - ((PI * R) / (double)2.0);

  if(foutainInPath == min(abs(x1-x2),abs(y1-y2)) + 1) {
  	res += (PI-(double)2)*R;
  	foutainInPath--;
  }

  res -= delta * foutainInPath;
  cout<<setprecision(15)<<res;
  return 0;
}


