int dfs(int v,vector<vector<int>> &edge,vector<int> &size){
    if(size[v]!=-1) return size[v];
    int res=0;
    for(auto to:edge[v]){
        res=max(res,dfs(to,edge,size));
    }
    return size[v]=res+1;
}

