#include <bits/stdc++.h>
using namespace std;

int lis(const vector<int>& xs)
{
    set<int> s;
    for (const int x : xs)
    {
        s.insert(x);
        const auto it = s.upper_bound(x);
        if (it != s.end())
            s.erase(it);
    }
    return int(s.size());
}

int main()
{
    cout << setprecision(15) << fixed;

    int x1, y1, x2, y2;
    cin >> x1 >> y1 >> x2 >> y2;

    if (x1 > x2)
    {
        swap(x1, x2);
        swap(y1, y2);
    }

    const bool flipped = y1 > y2;
    if (flipped)
        y1 = -y1, y2 = -y2;

    const double path_length = 100.0*((x2-x1) + (y2-y1));
    const double extra = 2*(20*atan(1) - 10);
    const double savings = 20 - 20*atan(1);

    int N;
    cin >> N;

    struct Point { int x, y; };
    vector<Point> points;
    for (int i = 0; i < N; i++)
    {
        int X, Y;
        cin >> X >> Y;

        if (flipped) Y = -Y;

        if (x1 <= X && X <= x2 && y1 <= Y && Y <= y2)
            points.push_back({X, Y});
    }

    if (x1 == x2 || y1 == y2)
    {
        assert(points.size() <= 1);
        cout << + path_length + (points.size() == 1) * extra << endl;
        exit(0);
    }

    const auto compare = [](const Point a, const Point b)
    {
        assert(a.x != b.x);
        return a.x < b.x;
    };
    sort(begin(points), end(points), compare);

    vector<int> ys;
    for (const Point p : points)
        ys.push_back(p.y);
    const int fountains_reached = lis(ys);

    double total = path_length - fountains_reached*savings;
    if (fountains_reached == min(x2-x1+1, y2-y1+1))
    {
        total += savings;
        total += extra;
    }
    cout << total << endl;
}

