long double solve() {
  if (!n) return (t.first + t.second - s.first - s.second) * 100;
  for (int i = 0; i < n; ++i) {
    int id = mp[v[i].second];
    int now = 0;
    {  // over
      if (id != 0) now = seg.query(0, id);
      now = max(now, seg.query(id, id + 1));
      if (id + 1 != mp.size()) seg.update(id + 1, mp.size(), dat(++now, 0));
    }
    {  // just
      now = seg.query(id, id + 1);
      if (id != 0) now = max(now, seg.query(0, id));
      seg.update(id, id + 1, dat(++now, 1));
    }
  }
  int res;
  if (n && v[n - 1].first == t.first)
    res = seg.query(mp[v[n - 1].second], mp.size());
  else
    res = seg.query(0, mp.size());
  return calc(P(res + (res == (t.second - s.second + 1) ||
                       res == (t.first - s.first + 1)),
                res)) +
         (t.first + t.second - s.first - s.second) * 100;
}

