		inc(i, n) { p[i] = MP(x[i], y[i]); }
		sort(p, p + n);

		SegTree<int> st;
		st.init(n, MAX, 0);
		inc(i, n) {
			if(inII(p[i].FI, sx, gx) && inII(p[i].SE, sy, gy)) {
				st.update(m[p[i].SE], st.range(0, m[p[i].SE]) + 1);
			}
		}
		int c = st.range(0, n);
		// cout << c << endl;
		ans = 100.0 * ((gx - sx) + (gy - sy)) + c * (5.0 * PI - 20.0);
	}

	printf("%.13f\n", ans);

	return 0;
}

