int x1,y1,x2,y2;

int solve(vector<pii> v,int endd) {
	vector<int> dp;
	dp.resize(v.size()+2,INF);
	dp[0] = -INF;
	sort(v.begin(),v.end());
	int qq2=0;
	int check=-1;
	if (!v.empty()) {
		if (v[v.size()-1].first == endd) check=v[v.size()-1].second;
	}
	for (int i=0;v.size()>i;i++) {
		int t=v[i].second;
		int tt=t;
		int pos=lower_bound(dp.begin(),dp.end(),tt) - dp.begin();
		dp[pos] = t;
		if (check!=-1 && t>check) qq2 = max(qq2,pos);
	}
	int qq=0;
	for (int i=0;dp.size()>i;i++) {
		if (dp[i+1] == INF) {
			qq=i;
			break;
		}
	}
	if (check != -1) qq-=2;
	return max(qq,qq2);
}

