		cout<<fixed<<setprecision(15)<<ans<<endl;
		return 0;
	}
	ans *= 100;
	int mx=0;
	if (ala) {
		for (pii &p:v) p.second = -p.second;
		mx = max(mx,solve(v,x2));
		reverse(v.begin(),v.end());
