bool cmp1(pii a,pii b){
	if(a.fi!=b.fi)return a.fi>b.fi;
	return y[a.se]<y[b.se];
}

bool cmp2(pii a,pii b){
	if(a.fi!=b.fi)return a.fi<b.fi;
	return y[a.se]<y[b.se];
}

bool inside(int a,int b){
	return min(x1,x2)<=a&&a<=max(x1,x2)&&yy<=b&&b<=y2;
}

void MAX(int &a,int b){a=max(a,b);}

void get_leaf(int l,int r,int node){
	if(l==r){
		leaf[l]=node;
		return;
	}
	int mid=(l+r)>>1;
	get_leaf(l,mid,node*2);
	get_leaf(mid+1,r,node*2+1);
}

void update(int pos,int val){
	pos=leaf[pos];
	tree[pos]=val;
	pos>>=1;
	while(pos){
		tree[pos]=max(tree[pos*2],tree[pos*2+1]);
		pos>>=1;
	}
}

int query(int l,int r,int vl,int vr,int node){
	if(vr<vl)return 0;
	if(l>vr||r<vl)return 0;
	if(l>=vl&&r<=vr)return tree[node];
	int mid=(l+r)>>1;
	return max(query(l,mid,vl,vr,node*2),query(mid+1,r,vl,vr,node*2+1));
}

