		double dis=((double)(abs(x1-x2))+(double)(abs(yy-y2)))*(double)(100);
		printf("%.15f",dis);
		return 0;
	}
	if(x1<x2){
		sort(X.begin(),X.end(),cmp1);
	}
	else{
		sort(X.begin(),X.end(),cmp2);
	}
	sort(Y.begin(),Y.end());
	Y.resize(unique(Y.begin(),Y.end())-Y.begin());
	get_leaf(0,Y.size()-1,1);
	rep(i,X.size()){
		int id=X[i].se;
		int pos=lower_bound(Y.begin(),Y.end(),y[id])-Y.begin();
		int val=query(0,Y.size()-1,0,pos-1,1);
		dp[id]=val+1;
		update(pos,dp[id]);
	} 
	rep(i,n){
		if(!inside(x[i],y[i]))continue;
		mx=max(mx,dp[i]);
	}
	double dis=((double)(abs(x1-x2))+(double)(abs(yy-y2)))*(double)(100);
	dis-=double(20)*(double)mx;
	if(x1==x2||yy==y2)dis+=(double)(10)*(double)mx*pi;
	else dis+=(double)(5)*(double)mx*pi;
	printf("%.15f",dis);
	return 0;
}

