	}
	if(m < 0) {
		m *= -1;
		for(auto &i : a) i.second *= -1;
	}
	map<int, int> xty, ytx;
	{
		vpi t;
		for(auto &i : a) {
			if(i.first >= 0 && i.first <= n && i.second >= 0 && i.second <= m) t.pb(i);
		}
		a = t;
		for(auto i : a) {
			xty[i.first] = i.second;
			ytx[i.second] = i.first;
		}
	}
	if(a.empty()) return cout << fixed << setprecision(15) << 100.*(n+m), 0;
