	for(auto &i : a) {
		auto it = lower_bound(all(lis), i.second);
		if(it == lis.end()) {
			lis.pb(i.second), it = --lis.end();
			ux.pb(ux.size()?ux.back():0);
			uy.pb(uy.size()?uy.back():0);
		} else {
			*it = i.second;
		}
		int p = it-lis.begin();
		if(p) {
			ux[p] |= ytx[lis[p]]-ytx[lis[p-1]]>1;
			uy[p] |= lis[p]-lis[p-1]>1;
		}
		cur.pb(p+1);
	}
	vi rlis;
	for(int t = lis.size(), i = a.size(); i-- && t;) {
		if(t == cur[i]) rlis.pb(a[i].second), t--;
	}
	reverse(all(rlis));
	lis = rlis;
	int border = 0;
	pi pos;
	for(auto i : a) {
		if(!binary_search(all(lis), i.second)) continue;
		if(i.first==0 || i.first==n || i.second==0 || i.second==m) pos = i, border = 1;
