    int cnt, arcs;

    cin >> X1 >> Y1 >> X2 >> Y2;
    cin >> N;
    inv_x = X1 > X2 ? -1 : 1;
    inv_y = Y1 > Y2 ? -1 : 1;
    X1 *= inv_x; X2 *= inv_x;
    Y1 *= inv_y; Y2 *= inv_y;

    for (int i = 0; i < N; i++) {
