map<int, int> maps[2];

bool cmp1(const struct node &u, const struct node &v) {
    if(u.x == v.x)
        return u.y < v.y;
    return u.x < v.x;
}

bool cmp2(const struct node &u, const struct node &v) {
    if(u.x == v.x)
        return u.y < v.y;
    return u.x > v.x;
}

int b[N];

