        scanf("%d%d", &E[i].x, &E[i].y);
        if(E[i].y >= y1 && E[i].y <= y2)
            maps[0][E[i].x]++;
        if(E[i].x >= x1 && E[i].x <= x2)
            maps[1][E[i].y]++;
        if(E[i].x >= x1 && E[i].x <= x2 && E[i].y >= y1 && E[i].y <= y2) {
            Ans[++cnt] = E[i];
        }
