        if(maps[1].find(A.y) != maps[1].end()) {
            answer += p1 - 20.0;
        }
        printf("%.11lf\n", answer);
        return 0;
    }
    if(A.y > B.y)
        swap(A, B);
    if(A.x < B.x)
        sort(Ans+1, Ans+1+cnt, cmp1);
    else
        sort(Ans+1, Ans+1+cnt, cmp2);
    int len = 1;
    b[1] = Ans[1].y;
    for(int i=2; i<=cnt; i++) {
