const ll MAXSEG = 4e5+4;  // limit for array size
ll segn=MAXSEG;  // array size
typedef ll S;
S t[2 * (MAXSEG+1)];
S identity = 0;
S combine(const S& lefts, const S& rights) {
	return max(lefts,rights);
}
void build(S *t) {  // build the tree
	ll n=segn;
  for (ll i = n - 1; i > 0; --i) t[i] = combine(t[i<<1], t[i<<1|1]);
}

void modify(ll p, const S& value) { // set value at position p
	ll n=segn;
  for (t[p += n] = value; p >>= 1; ) t[p] = combine(t[p<<1], t[p<<1|1]);
}

S query(ll l, ll r) { // sum on interval [l, r]
	r++;
	ll n=segn;
  S resl=identity, resr=identity;
  for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
    if (l&1) resl = combine(resl, t[l++]);
    if (r&1) resr = combine(t[--r], resr);
  }
  return combine(resl, resr);
}




