  auto it=unique(vx.begin(),vx.end());
  vx.resize(std::distance(vx.begin(),it));
}
ll bins(vector<ll> &vx, ll x) {
  ll imin=0,imax=vx.size();
  while(imin<imax) {
    ll imid=(imin+imax)>>1;
    if (vx[imid]<x) imin=imid+1;
    else imax=imid;
  }
  return imin;
}
