  sort(cy.begin(),cy.end());
  cy.erase(unique(cy.begin(),cy.end()),cy.end());

  map<int,int> mx,my;
  for(int i=0;i<(int)cx.size();i++) mx[cx[i]]=i;
  for(int i=0;i<(int)cy.size();i++) my[cy[i]]=i;
  map<int,int> px,py;
  for(int i=0;i<n;i++){
    px[p[i].second]=p[i].first;
    py[p[i].first]=p[i].second;
  }
  RMQ rmq(cy.size()+100);
  double base=(abs(x1-x2)+abs(y1-y2))*100;
  double diff=5*PI-20,diff2=10*PI-20;
  double  ans=1e15;
  if(px.count(y1)&&px[y1]==x2) ans=min(ans,base-diff);

  for(int i=my[y1];i<=my[y2];i++){
    if(!py.count(x1)||cy[i]<py[x1]){
      rmq.update(i,0);
    }else if(cy[i]==py[x1]){
      rmq.update(i,-1);
    }else{
      rmq.update(i,-1);
    }
  }

  for(int i=mx[x1]+1;i<=mx[x2];i++){
    int x=cx[i];
    if(!py.count(x)) continue;
    int y=py[x];
    int t=rmq.query(0,my[y]-1);
    //cout<<i<<" "<<cx[i]<<":"<<t<<endl;

    rmq.update(my[y]+1,t-1);

    t=rmq.query(0,my[y]);
    rmq.update(my[y],t-1);

    if(y==y1) rmq.update(my[y1],-1);
  }
  /*//
  for(int i=0;i<(int)cy.size();i++)
    cout<<cy[i]<<":"<<rmq.query(i,i+1)<<endl;
  //*/
  int k=-rmq.query(my[y1],my[y2]+1);
  //cout<<k<<endl;
  if(k==min(abs(x2-x1),abs(y2-y1))+1) ans=base+diff*(k-1)+diff2;
  else ans=base+diff*k;
  printf("%.15Lf\n",ans);
  return 0;
}

