#define SWAP(a,b) (a ^= b,b = a ^ b,a ^= b)
#define MIN(a,b) ((a)<(b)?(a):(b))
#define MAX(a,b) ((a)>(b)?(a):(b))
#define INF ((lint)1000000000)
#define PI 3.14159265358979323846

lint dp[200001];
lint a[200001];

lint LIS(lint N) {
	for (lint i = 0; i < N; i++) dp[i] = INF;
	for (lint i = 0; i < N; i++) {
		*lower_bound(dp, dp + N, a[i]) = a[i];
	}
	return lower_bound(dp, dp + N, INF) - dp;
}

int main()
{
	lint xs, ys, xg, yg;
	lint N;

	cin >> xs >> ys >> xg >> yg;
	if (xs == xg)
		if (ys > yg) SWAP(ys, yg);
