	cin >> N;

	vector<Pii> Points;
	int x, y;
	for (lint i = 0; i < N; i++) {
		cin >> x >> y;
		if (x < xs || xg < x) continue;
		if (y < MIN(ys, yg) || MAX(ys, yg) < y) continue;
		Points.push_back(Pii(x, y));
	}

	double shortcut = 0;
	if (!Points.empty()) {
		if (xs != xg && ys != yg) {
			if (ys < yg)
				sort(Points.begin(), Points.end());
