	}
	if(Y1 > Y2) {
		Y1 = -Y1, Y2 = -Y2;
		for(pii &p : P)
			p.se = -p.se;
	}
	for(int i = 0; i < n; ++i) {
		pii p = P[i];
		if(X1 <= p.fi && p.fi <= X2 && Y1 <= p.se && p.se <= Y2) {
