	n = ir.size();
	t = segt<int>(n);
	int ans = 0;
	for(int i = 0; i < n; ++i) {
		int a = lab[ir[i].se];
		int bst = 1+t.query(0,a);
		t.update(a,bst-t.query(a,a));
		ans = max(ans,bst);
