inline int read(int f = 1, int x = 0, char ch = ' ')
{
    while(!isdigit(ch = getchar())) if(ch == '-') f = -1;
    while(isdigit(ch)) x = x*10+ch-'0', ch = getchar();
    return f*x;
}
const int N = 2e5+5;
const double PI = acos(-1);
int m, sx, sy, tx, ty, rx, ry;
int n, a[N], b[N], px[N], py[N], t[N], k;
vector<int> s[N];
double ans;
void change(int x, int d) { for( ; x <= n; x += x&-x) t[x] = max(t[x], d); }
int ask(int x) { int ret = 0; for( ; x; x -= x&-x) ret = max(ret, t[x]); return ret; }
int main()
{
    sx = read(), sy = read(), tx = read()-sx, ty = read()-sy, m = read(), rx = ry = 1;
    if(tx < 0) rx = -1, tx = -tx; if(ty < 0) ry = -1, ty = -ty;
    for(int i = 1; i <= m; ++i)
    {
        int x = rx*(read()-sx), y = ry*(read()-sy);
        if(0 <= x&&x <= tx&&0 <= y&&y <= ty) px[++n] = x, a[n] = x, py[n] = y, b[n] = y;
    }
    sort(a+1, a+1+n), sort(b+1, b+1+n);
    for(int i = 1; i <= n; ++i)
        px[i] = lower_bound(a+1, a+1+n, px[i])-a,
        py[i] = lower_bound(b+1, b+1+n, py[i])-b,
        s[py[i]].push_back(px[i]);
    for(int i = 1; i <= n; ++i)
    {
        sort(s[i].begin(), s[i].end());
        reverse(s[i].begin(), s[i].end());
        for(int j = 0; j < s[i].size(); ++j) change(s[i][j], ask(s[i][j]-1)+1);
    }
    ans = 100.0*(tx+ty)+(5*PI-20)*(k = ask(n));
    if(k == min(tx, ty)+1) ans += 5*PI;
    printf("%.12lf\n", ans);
    return 0;
}

