void emit() {
	tot = 0;
	for(int i = 1; i <= n; i++) {
		if((min(sx, tx) <= PP[i].x && PP[i].x <= max(sx, tx))
				&& (min(sy, ty) <= PP[i].y && PP[i].y <= max(sy, ty)))
			tmp[++tot] = PP[i];
	}
	/*for(int i = 1; i <= tot; i++) {
	  printf("%lld %lld\n", tmp[i].x, tmp[i].y);
	}*/
}

int len;
LL a[MaxN + 5], d[MaxN + 5];

int bin_search(LL x) {
	int l = 0, r = len;
	int mid = 0, ans = 0;
	while(l <= r) {
		mid = (l + r) >> 1;
		if(d[mid] >= x) ans = mid, r = mid - 1;
		else l = mid + 1;
	}
	return ans;
}

void get_LIS(bool c)
{
	len = 0;
	d[len] = -INF;
	if(c == 1) {
		for(int i = 1; i <= tot; i++) 
			a[i] = tmp[i].y;
	}
	else {
		for(int i = 1; i <= tot; i++)
			a[i] = tmp[tot - i + 1].y;
	}
	//printf("\n");
	for(int i = 1; i <= tot; i++) {
		if(a[i] > d[len]) d[++len] = a[i];
		else {
			int pos = bin_search(a[i]);
			d[pos] = a[i];
		}
	}
}

