template< typename T >
size_t longest_increasing_subsequence(const vector< T > &a, bool strict) {
	vector< T > lis;
	for (auto &p : a) {
		typename vector< T >::iterator it;
		if (strict) it = lower_bound(begin(lis), end(lis), p);
		else it = upper_bound(begin(lis), end(lis), p);
		if (end(lis) == it) lis.emplace_back(p);
		else *it = p;
	}
	return lis.size();
}


void solve() {
	int sx, sy, gx, gy;
	cin >> sx >> sy >> gx >> gy;
	int N; cin >> N;
	vector<pii>v;

	REP(i, N) {
		int x, y; cin >> x >> y;
		x -= sx, y -= sy;
		v.push_back({ x,y });
	}
	gx -= sx, gy -= sy;
	sx = 0, sy = 0;
	if (gx < 0 && gy >= 0) {
		gx = -gx;
		REP(i, N)v[i].first = -v[i].first;
	}
	else if (gx < 0 && gy < 0) {
		gx = -gx;
		gy = -gy;
		REP(i, N) { v[i].first = -v[i].first, v[i].second = -v[i].second; }
	}
	else if (gx >= 0 && gy < 0) {
		gy = -gy;
		REP(i, N)v[i].second = -v[i].second;
	}
	VSORT(v);
	vector<pii>vxy, vyx;
	REP(i, N) {
		int x = v[i].first, y = v[i].second;
		if (sx <= x && x <= gx && sy <= y && y <= gy) {
			vxy.push_back({ x,y });
			vyx.push_back({ y,x });
		}
	}
	VSORT(vxy);
	VSORT(vyx);
	vector<int>vx, vy;
	for (auto p : vxy)vy.push_back(p.second);
	for (auto p : vyx)vx.push_back(p.second);
	int c = max(longest_increasing_subsequence<int>(vx, true), longest_increasing_subsequence<int>(vy, true));
	//DEBUG(c);
	double res = 100 * (gx + gy);
	if (c <= min(gx, gy))res -= (20-pi * 5)*c;
	else {
		res -= pi * 5 * (c - 1);
		res += pi * 10 - 20;
	}
	cout << fixed << setprecision(15) << res << endl;
}


