int n, sx, sy, gx, gy, x[200000], y[200000];
double PI = 3.1415926535897932;
pair<int, int> p[200000];
map<int, int> m;

int main() {
	cin >> sx >> sy >> gx >> gy >> n;
	inc(i, n) { cin >> x[i] >> y[i]; }

	double ans = -123.4;
	if(sx == gx) {
		if(sy > gy) { swap(sy, gy); }
		LL c = 0;
		inc(i, n) { if(x[i] == sx && inII(y[i], sy, gy)) { c++; } }
		ans = 100.0 * (gy - sy) + c * (10.0 * PI - 20.0);
	} else if(sy == gy) {
		if(sx > gx) { swap(sx, gx); }
		LL c = 0;
		inc(i, n) { if(y[i] == sy && inII(x[i], sx, gx)) { c++; } }
		ans = 100.0 * (gx - sx) + c * (10.0 * PI - 20.0);
	} else {
		LL M = 1e8 - 1;
		if(sx > gx) {
			sx = M - sx;
			gx = M - gx;
			inc(i, n) { x[i] = M - x[i]; }
		}
		if(sy > gy) {
			sy = M - sy;
			gy = M - gy;
			inc(i, n) { y[i] = M - y[i]; }
		}

		inc(i, n) { p[i] = MP(y[i], x[i]); }
		sort(p, p + n);
		inc(i, n) { m[p[i].FI] = i; }

		inc(i, n) { p[i] = MP(x[i], y[i]); }
		sort(p, p + n);

		SegTree<int> st;
		st.init(n, MAX, 0);
		inc(i, n) {
			if(inII(p[i].FI, sx, gx) && inII(p[i].SE, sy, gy)) {
				st.update(m[p[i].SE], st.range(0, m[p[i].SE]) + 1);
			}
		}
		int c = st.range(0, n);
		// cout << c << endl;
		int xx = gx - sx;
		int yy = gy - sy;
		ans = 100.0 * (xx + yy) + c * (5.0 * PI - 20.0) + (c == min(xx, yy) + 1 ? 5.0 * PI : 0.0);
	}

	printf("%.13f\n", ans);

	return 0;
}

