int n,x[N],y[N],Ans[N],a[N];
struct opt{int x,y,id;}Q[N];
bool cmp(opt a,opt b){
    return a.y==b.y?a.x<b.x:a.y<b.y;
}
struct bit{
    int Max[N];
    bit(){for (int i=0;i<N;i++) Max[i]=-1e9;}
    void change(int p,int v){
        for (p++;p<N;p+=p&-p) Max[p]=max(Max[p],v);
    }
    int query(int p){
        int ans=-1e9;
        for (p++;p;p-=p&-p) ans=max(ans,Max[p]);
        return ans;
    }
}T;
int main()
{
    int x0,y0,x1,y1;
    scanf("%d%d%d%d%d",&x0,&y0,&x1,&y1,&n);
