    x[0]=x0;y[0]=y0;n++;x[n]=x1;y[n]=y1;
    if (y0>y1) for (int i=0;i<=n;i++) y[i]=-y[i];
    if (x0>x1) for (int i=0;i<=n;i++) x[i]=-x[i];
    for (int i=0;i<=n;i++) a[i]=x[i];
