    for (int i=0;i<=n;i++) Q[i]=(opt){x[i],y[i],i};
    sort(Q,Q+n+1,cmp);
    for (int i=0;i<=n;i++){
        int id=Q[i].id;
        Ans[id]=(id?T.query(Q[i].x)+1:0);
        T.change(Q[i].x,Ans[id]);
    }
    Ans[n]--;
    if (Ans[n]<min(abs(x0-x1),abs(y0-y1)))
        printf("%.15Lf\n",ans-Ans[n]*(20-5*pi));
    else
        printf("%.15Lf\n",ans-(Ans[n]-1)*(20-5*pi)+10*pi-20);
    return 0;
}

