const int mxn = 4e5+7;

struct BIT {
	um<int,um<int,int>> tree;	
	void cmod(int i, int j, int x) {
		for (int a = i; a < mxn; a|=a+1)		
			for (int b = j; b < mxn; b|=b+1)
				Max(tree[i][j],x);
	}
	int query(int i, int j) {
		int ans = 0;
		for (int a = i; a >= 0; a = (a&(a+1))-1)
			for (int b = j; b >= 0; b = (b&(b+1))-1)
				if (tree.count(a) && tree[a].count(b))
					Max(ans,tree[a][b]);
		return ans;
	}
};

