		swap(ay, by);
	}

	for (int i = 1; i <= n; ++i) {
		pair<int, int> p;
		scanf("%d %d", &p.fi, &p.se);

		if (ax <= p.fi && p.fi <= bx) {
			if (min(ay, by) <= p.se && p.se <= max(ay, by)) {
				arr.pb(p);
			}
		}
	}

	ans = 100.0 * (bx - ax + abs(ay - by));

  	if (ax == bx || ay == by) {
  		if (!arr.empty()) {
  			ans = ans - 20.0 + PI * 10.0;
  		}

  		printf("%.13f\n", ans);
  		return;
  	}

  	assert(arr.size() <= 5000);

	if (ay > by) {
		swap(ay, by);

		for (pair<int, int> &x : arr) {
			x.se *= -1;
		}
	}

    ans -= calc(arr);  	
    printf("%.13f\n", ans);
}

int main() {    
    int tt = 1;

    while (tt--) {
        solve();
    }

    return 0;
}

