struct Node{
	int mi, ma;

	Node(int mi, int ma) : mi(mi), ma(ma) {}
	Node operator*(const Node r){return Node(std::min(mi, r.mi), std::max(ma, r.ma));}
} e(1e9, -1e9);

struct SegmentTree{
	std::vector<Node> seg;
	int sz = 1;

	SegmentTree(int n){
		while(sz < n) sz <<= 1;
		seg.assign(sz * 2, e);
	}

	void update(int k, Node x){
		k += sz - 1;
		seg[k] = x;

		while(k){
			k = (k - 1) / 2;
			seg[k] = seg[2 * k + 1] * seg[2 * k + 2];
		}
	}

	Node get(int a, int b){
		return get(a, b, 0, 0, sz);
	}

	Node get(int a, int b, int k, int l, int r){
		if(b<=l||r<=a) return e;
		if(a<=l&&r<=b) return seg[k];

		return get(a, b, 2 * k + 1, l, (l + r) / 2) * get(a, b, 2 * k + 2, (l + r) / 2, r);
	}
};

int main(){
	int sx, sy, gx, gy, n; cin >> sx >> sy >> gx >> gy >> n;
	std::vector<int> X(1, 0), Y(1, 0), x(n), y(n);
	for(int i = 0; i < n; i++){
		cin >> x[i] >> y[i];

		X.push_back(x[i]);
		Y.push_back(y[i]);
