  }
};

void swap(point &a, point &b) {
  int temp = a.x;
  a.x = b.x;
  b.x = temp;
  temp = a.y;
  a.y = b.y;
  b.y = temp;
}

bool cmp (point a, point b) {
  if (a.x == b.x) {
    return a.y < b.y;
  }
  return a.x < b.x;
}

