map<int,int> rank;
int st[2*MAXN];
void update(int i, int v) {
        i = rank[i];
        //cout << "Update " << i << " " << v << "\n";
        for (st[i += N+2] = v; i>1; i>>=1)
                st[i>>1] = max(st[i],st[i^1]);
}

int query(int a, int b) {
        if (a > b) swap(a,b);
        a = rank[a];
        b = rank[b];
        b++;
        //cout << "Query " << a << " " << b << "\n";
        int res=0;
        for (a+=N+2, b+=N+2; a < b; a>>=1, b>>=1) {
                if (a&1) res = max(res,st[a++]);
                if (b&1) res = max(res,st[--b]);
        }
        return res;
}

void set_rank() {
        vector<int> yf;
        for (int i=0; i<N; ++i)
                yf.push_back(Y[i]);
        yf.push_back(y1);
        yf.push_back(y2);
        sort(yf.begin(),yf.end());
        for (int i=0; i<yf.size(); ++i)
                rank[yf[i]] = i;
}

int mxtrn() {
        if (x1 > x2) {
                swap(x1,x2);
                swap(y1,y2);
        }

        set_rank();

        vector<pii> xf;
        for (int i=0; i<N; i++)
                xf.push_back(pii(X[i],i));

        sort(xf.begin(), xf.end());

        int i=0;
        while (i < N && xf[i].first < x1)
                ++i;

        //cout << "y1 y2 " << rank[y1] << " " << rank[y2] << "\n";
        for (; i < N && xf[i].first < x2; ++i) {
                int cur = xf[i].second;
                //cout << "Processing fountain " << cur << " at " << X[cur] << ", " << Y[cur] << "\n";
                //cout << "\tRank is " << rank[Y[cur]] << "\n";
                int k = 1+query(y1,Y[cur]);
                //cout << "\tGets value " << k << "\n";
                update(Y[cur],k);
        }

        return query(y1,y2);
}

