using namespace std;

typedef double Real;
typedef pair<int, int> P;

const Real PI = acos(-1.0);

P ps[200200];
int N;

P s, t;

P readP(){
	int x, y;
	scanf("%d%d", &x, &y);
	return P(x, y);
}

void input(){
	s = readP();
	t = readP();
	scanf("%d", &N);
	for(int i = 0; i < N; ++i){
		ps[i] = readP();
	}
}

void flipY(){
	for(int i = 0; i < N; ++i){
		ps[i] = P(ps[i].first, -ps[i].second);
	}
	s = P(s.first, -s.second);
	t = P(t.first, -t.second);
}

vector<P> cands;

bool isCand(P p){
	return s.first <= p.first && s.second <= p.second && p.first <= t.first && p.second <= t.second;
}

int dp[200200];

int lis(vector<int> vec){
	for(int i = 0; i < 200200; ++i) dp[i] = 1e9;
	for(int i = 0; i < vec.size(); ++i){
		int id = lower_bound(dp, dp + 200200, vec[i]) - dp;
		dp[id] = max(dp[id], vec[i]);
	}
	int ans = 0;
	for(int i = 0; i < 200200; ++i){
		if(dp[i] < (1e9)) ans++;
	}
	return ans;
}

Real solve2(){
	bool flg = false;
	for(int i = 0; i < N; ++i){
		if(isCand(ps[i])){
			flg = true;
			break;
		}
	}
	if(flg){
		return (t.first - s.first) * 100.0 + (t.second - s.second) * 100.0 - 20 + 10.0 * PI;
	}else{
		return (t.first - s.first) * 100.0 + (t.second - s.second) * 100.0;
	}
}

Real solve(){
	if(s.first > t.first) swap(s, t);
	if(s.second > t.second) flipY();
	if(s.first == t.first || s.second == t.second){
		return solve2();
	}
	for(int i = 0; i < N; ++i){
		if(isCand(ps[i])){
			cands.push_back(P(ps[i].first - s.first, ps[i].second - s.second));
		}
	}
	sort(cands.begin(), cands.end());
	vector<int> tmp;
	for(int i = 0; i < cands.size(); ++i){
		tmp.push_back(cands[i].second);
	}
	int l = lis(tmp);
	Real a = 20.0 - 5.0 * PI;
	return (t.first - s.first) * 100.0 + (t.second - s.second) * 100.0 - a * l;
}

int main(){
	input();
	Real ans = solve();
	printf("%.12f\n", ans);
	return 0;
}

