		else {
			getIdx(cur.fi.se, st);
			auto nxt = *st.begin();
			if(cur.fi.se > nxt.fi.se) return;
			es[cur.se].pb(nxt.se);
		}
		if(nxt.fi.se > nxtY) return;
	}
	return;
}


