	scanf("%d", &n);

	// Bounding box
	minx = min(xi, xf);
	miny = min(yi, yf);
	maxx = max(xi, xf);
	maxy = max(yi, yf);

	// Points
	for (i = 0; i < n; i++){
		scanf("%d%d", x + i, y + i);
		p[i] = i;
	}

	// Initial is always lowest
	if (yi > yf){
		swap(xi, xf);
		swap(yi, yf);
	}

	// Sorting by X
	if (xf > xi){
		sort(p, p + n, compasc);
	}
	else{
		sort(p, p + n, compdesc);
	}

	// Points inside the bounding box
	for (i = 0; i < n; i++){
