};

int main() {
  int x1, y1, x2, y2;
  scanf("%d %d %d %d", &x1, &y1, &x2, &y2);
  if (x1 > x2) {
    swap(x1, x2);
    swap(y1, y2);
  }
  int x_min, x_max, y_min, y_max;
  x_min = min(x1, x2);
  x_max = max(x1, x2);
  y_min = min(y1, y2);
  y_max = max(y1, y2);

  int n;
  scanf("%d", &n);

  vector<Point> xy;

  rep (i, n) {
    int x_, y_;
    scanf("%d %d", &x_, &y_);
    if (x_min <= x_ && x_ <= x_max && y_min <= y_ && y_ <= y_max) {
      xy.push_back(Point(x_, y_));
    }
  }
  n = xy.size();

  if (x_max == x_min || y_max == y_min) {
    printf("%.11f\n", 100.0 * (x_max - x_min + y_max - y_min) + (int)xy.size() * (M_PI * 10 - 20));
    return 0;
  }

  if (n == 0) {
    printf("%d\n", 100 * (x_max - x_min + y_max - y_min));
    return 0;
  }

  sort(all(xy), [](Point a, Point b) {
      if (a.x == b.x) {
      return a.y <= b.y;
      }
      return a.x < b.x;
      });

  if (y1 > y2) {
    reverse(all(xy));
  }

  vi l;
  l.push_back(xy[0].y);
  for (int i = 1; i < n; ++i) {
    if (l[(int)l.size() - 1] < xy[i].y) {
      l.push_back(xy[i].y);
    } else {
      *lower_bound(all(l), xy[i].y) = xy[i].y;
    }
  }

  double shortcut = 20 - M_PI * 5;
  printf("%.11f\n", 100.0 * (x_max - x_min + y_max - y_min) - (int)l.size() * shortcut);

  return 0;
}

