signed main() {
	int i;

	cin >> x1 >> sy >> x2 >> y2;
	cin >> n;
	rep(i, n) cin >> x[i] >> y[i];

	if (x1 > x2) {
		rep(i, n) x[i] *= -1;
		x1 *= -1;
		x2 *= -1;
	}
	if (sy > y2) {
		rep(i, n) y[i] *= -1;
		sy *= -1;
		y2 *= -1;
	}

	rep(i, n) {
		if (x1 <= x[i] && x[i] <= x2 && sy <= y[i] && y[i] <= y2) {
			pos.push_back(P(x[i], y[i]));
