int loadvec(vector<int>& v, int N=-1) {
    if (N == -1) {
        N = loadint();
        if (N==0) return 0;
    }
    int bufsize = INTSPACE*N + 3;
    if (fgets(_buf, bufsize, stdin)==NULL) return 0;
    v.resize(N);

    int i=0;
    bool last = false;
    for (char *p=&_buf[0]; ;) {
        char *q = p;
        while (*q > ' ') ++q;
        if (*q == 0x0D || *q == 0x0A) last = true;
        *q = 0;
        v[i++] = atoi(p);
        if (last || i == N) break;
        p = q+1;
    }
    return i;
}


int lis(vector<int>& a) {
    int M = a.size();
    // cout << a << endl;
    assert(0 < M && M <= 200000);

    vector<int> dp(M, 1e9);
    dp[0] = a[0];
    int maxlen = 1;
    for (int i=1; i<M; ++i) {
        int len = (int)(lower_bound(dp.begin(),dp.begin()+i, a[i]) - dp.begin())+1;
        maxlen = max(maxlen, len);
        dp[len-1] = min(dp[len-1], a[i]);
    }
    // cout << dp << endl;
    return maxlen;
}

int main() {
    vector<int> tmp(4);
    loadvec(tmp,4);
    int x1=tmp[0], y1=tmp[1], x2=tmp[2], y2=tmp[3];
    int xmin=min(x1,x2), xmax=max(x1,x2);
    int ymin=min(y1,y2), ymax=max(y1,y2);
    if (x2 < x1) {
        swap(x1,x2); swap(y1,y2);
    }
    long double ans = 100.0 * ((xmax - xmin) + (ymax - ymin));
    long double pi = 3.141592653589793238462643;

    int N = loadint();
    vector<ii> ft;
    ft.reserve(N);
    rep(i,N){
        loadvec(tmp,2);
