        if (IN(Xi,xmin,xmax) && IN(Yi,ymin,ymax)) {
            ft.pb(ii(Xi,Yi));
        }
    }
    sort(ALL(ft));
    int M = ft.size();
    vector<int> a(M);
    rep(i,M) a[i] = ft[i].second;
    if (xmax == xmin || ymax == ymin) {
        // cout << a << endl;
        assert(M == 0 || M == 1);
        ans += (pi*10 - 20)*M; // M = 0 or 1
    } else if (M > 0) {
        assert(x1 < x2);
        if (y1 > y2) {
            rep(i,M) a[i] = ymax - a[i];
        } else {
            rep(i,M) a[i] -= ymin;
        }
        // cout << a << endl;
        int L = lis(a); // 1..M

        if (a[0] == 0 && a[M-1] == (ymax-ymin)) {
            ans -= (20.0 - pi*5) * (L-1);
            ans += (pi*10 - 20);
        } else {
            ans -= (20.0 - pi*5) * L;
