      }
      int y = y_[idx];
      long long cnt = seg.RangeEvaluation(0, y+1);
      cnt++;
      long long cnt2 = seg.RangeEvaluation(y, y+1);

      seg.update( y, max(cnt,cnt2) );
    }
    itr = next(itr);
  }

  long long mx_f = seg.RangeEvaluation(0, y_[n]+1);
  long double ans = (long double)100.0 * (fabs(t.first - s.first) + fabs(t.second - s.second));
  ans += (5.0*PI - 20.0) * mx_f;

  assert(ans > 0 && ans <= 100.0 * (fabs(t.first - s.first) + fabs(t.second - s.second)) + 1e-18);

  printf("%.18f\n", (double)ans);


  return 0;
}

