	{
		tot = 0;
		ld ans = 0;
		if (x1 != x2 && y1 != y2)
		{
			bool xflip = false, yflip = false;
			if (x1 > x2)
			{
				xflip = true;
				x1 = up - x1;
				x2 = up - x2;
			}
			if (y1 > y2)
			{
				yflip = true;
				y1 = up - y1;
				y2 = up - y2;
			}
