		return memo[m];

	int res = 0;

	int v;

	if (dx > 0)
		v = std::upper_bound(vec.begin(), vec.end(), vec[m]) - vec.begin();
	else
		v = std::lower_bound(vec.begin(), vec.end(), vec[m]) - vec.begin() - 1;

