  maxi -= 1;
  assert( maxi >= 0 );
  if( debug ) {
    cout << "FINAL MAXI = " << maxi << endl;
  }
  printf("%.20lf\n",mini - 20.0 * maxi + ( M_PI * 10.0 * 0.5 ) * maxi );
}

