typedef pair<int, int> PII;
typedef pair<LL, LL> PLL;

int NN = 200005;
class SegmentTree {
    vector<int> data;
public:
    SegmentTree() {
        data = vector<int>(4*NN,0);
    }

    void update(int a, int v, int i = 1, int l = 0, int r = NN) {
        if (a < l || a >= r) return;
        if (a == l && (r-l) == 1) {
            data[i] += v;
            return;
        }
        int mid = l + (r - l) / 2;
        update(a, v, 2*i, l, mid);
        update(a, v, 2*i+1, mid, r);
        data[i] = max(data[2*i], data[2*i+1]);
    }

    int query(int a, int b, int i = 1, int l = 0, int r = NN) {
        if (b <= l || a >= r) return 0;
        if (a <= l && r <= b) return data[i];
        int mid = l + (r - l) / 2;
        return max(query(a,b,2*i,l,mid),query(a,b,2*i+1,mid,r));
    }

};

int main() {
#ifdef LOCAL_PROJECT
    freopen("input.txt", "r", stdin);
#endif
    int x1, y1, x2, y2, N, x, y;
    scanf("%d %d %d %d", &x1, &y1, &x2, &y2);
    scanf("%d", &N);
    if (x1 > x2) {
        swap(x1, x2);
        swap(y1, y2);
    }
    vector<PII> pts, pty;
    unordered_map<int, int> M;
    for(int i = 0; i < N; i++) {
        scanf("%d %d", &x, &y);
        if (x < min(x1, x2) || x > max(x1, x2) || y < min(y1,y2) || y > max(y1,y2)) continue;
        pts.push_back(PII(x,y));
        pty.push_back(PII(y,x));
    }
    sort(pts.begin(), pts.end());
    if (y2 >= y1) {
        sort(pty.begin(), pty.end());
    } else {
        sort(pty.begin(), pty.end(), greater<PII>());
    }
    int L = pts.size();
    for(int i = 0; i < L; i++) M.insert(PII(pty[i].first, i+1));
    SegmentTree st;
    for(int i = 0; i < L; i++) {
        // cerr << M[pts[i].second] << "," << st.query(0, M[pts[i].second]) << endl;
        st.update(M[pts[i].second], st.query(0, M[pts[i].second])+1);
    }
    long double res = 100.0 * (max(y1,y2) - min(y1,y2) + max(x1,x2) - min(x1,x2));
    int qqq = st.query(0, L+1);
    res = res + (5 * M_PI - 20) * qqq;
    if ((qqq-1) == (max(y1,y2) - min(y1,y2))) res = res + 5 * M_PI;
    cout << fixed << setprecision(16) << res << endl;
    return 0;
}

