#ifndef M_PI
#define M_PI 3.14159265358979323846L
#endif

double run()
{
  int64_t x1, y1, x2, y2;
  size_t n;
  cin >> x1 >> y1 >> x2 >> y2 >> n;
  vector<pair<int64_t, int64_t>> a(n);
  cin >> a;

  if(x2 < x1)
  {
    swap(x2, x1);
    swap(y2, y1);
  }

  if(y2 < y1)
  {
    int64_t s = y1;
    for(const auto & pr: a) s = max(s, pr.second);
    y1 = s - y1;
    y2 = s - y2;
    for(auto & pr: a) pr.second = s - pr.second;
  }

  const double dist = ((x2 - x1) + (y2 - y1)) * 100;

  if(x1 == x2)
  {
    for(const auto & pr: a)
      if(pr.first == x1 && y1 < pr.second && pr.second < y2)
        return dist - 2 * 10 + 10 * M_PI;

    return dist;
  }

  if(y1 == y2)
  {
    for(const auto & pr: a)
      if(pr.second == y1 && x1 < pr.first && pr.first < x2)
        return dist - 2 * 10 + 10 * M_PI;

    return dist;
  }

  sort(begin(a), end(a));
  reverse(begin(a), end(a));
  map<int64_t, size_t> cnt;
  for(const auto & pr: a)
  {
    const auto x = pr.first;
    const auto y = pr.second;
    if (x < x2 + 1 && y < y2 + 1 && x1 < x + 1 && y1 < y + 1)
    {
      auto iter = cnt.lower_bound(y);
      if (iter == end(cnt))
        cnt.insert({y, 1});
      else
      {
        const auto val = iter->second + 1;
        iter = cnt.emplace_hint(iter, y, val);
        while(iter != begin(cnt))
        {
          --iter;
          if(val < iter->second) break;
          iter = cnt.erase(iter);
        }
      }
    }
  }

  auto iter = cnt.lower_bound(y1);
  const double k = iter != end(cnt) ? iter->second : 0;

  return dist + k * 10 * (M_PI / 2 - 2);
}

int main(const int argc, char * argv [])
{
  ios_base::sync_with_stdio(0); cin.tie(0); cout.tie(0);
  cout << std::fixed << setprecision(17) << run();

  return EXIT_SUCCESS;
}

