int X1, Y1, X2, Y2, N;
vector<int> X, Y;

struct SegTree {
	const int n = 1<<18;
	vector<int> dat;
	SegTree() : dat(2*n-1, 0) {}
	void set(int i, int x) {
		i += n - 1;
		dat[i] = x;
		while (i > 0) {
			i = (i-1)/2;
			dat[i] = max(dat[i*2+1], dat[i*2+2]);
		}
	}
	int f(int a, int b, int k, int l, int r) {
		if (r <= a || b <= l) return 0;
		if (a <= l && r <= b) return dat[k];
		return max(
			f(a, b, k*2+1, l, (l+r)/2),
			f(a, b, k*2+2, (l+r)/2, r)
		);
	}
	int get(int a, int b) {
		return f(a, b, 0, 0, n);
	}
};

int f() {
	int x1 = X1;
	int x2 = X2;
	int y1 = Y1;
	int y2 = Y2;
	if (y1 > y2) { swap(x1, x2); swap(y1, y2); }
	vector<pair<int,int>> a;
	set<int> b;
	for (int i = 0; i < N; ++ i) {
		if (min(X1, X2) <= X[i] && X[i] <= max(X1, X2) && min(Y1, Y2) <= Y[i] && Y[i] <= max(Y1, Y2)) {
			int x = X[i];
			if (x1 > x2) x = -x;
			a.push_back({Y[i],x});
			b.insert(x);
		}
	}
	map<int, int> d;
	int c = 0;
	for (int x : b) d[x] = c++;
	vector<int> e;
	sort(a.begin(), a.end());
	for (auto p : a) e.push_back(d[p.second]);
	SegTree seg;
	for (auto x : e) {
		seg.set(x, seg.get(0, x)+1);
	}
	return seg.get(0, c+1);
}

int main() {
	cin >> X1 >> Y1 >> X2 >> Y2 >> N;
	X = vector<int>(N);
	Y = vector<int>(N);
	for (int i = 0; i < N; ++ i) cin >> X[i] >> Y[i];

	int x1 = min(X1, X2);
