void solve(int a)
{
    num[0] = 0;
    if(a == 1)
    {
        for(LL i = 1;i <= nn;i++)
        {
            if(!num[0]||num[num[0]] < nd[i].y)
                num[++num[0]] = nd[i].y;
            else
            {
                LL l = 1, r = num[0], res = -1;
                while(l <= r)
                {
                    LL mid = (l + r) / 2;
                    if(num[mid] >= nd[i].y)
                        r = mid - 1, res = mid;
                    else
                        l = mid + 1;
                }
                if(res == -1)
                    continue;
                num[res] = nd[i].y;
            }
        }
    }
    else
    {
        for(LL i = 1;i <= nn;i++)
        {
            if(!num[0]||num[num[0]] > nd[i].y)
                num[++num[0]] = nd[i].y;
            else
            {
                LL l = 1, r = num[0], res = -1;
                while(l <= r)
                {
                    LL mid = (l + r) / 2;
                    if(num[mid] <= nd[i].y)
                        r = mid - 1, res = mid;
                    else
                        l = mid + 1;
                }
                if(res == -1)
                    continue;
                num[res] = nd[i].y;
            }
        }
    }
    ans = ((double)(mxx - mix) + (double)(mxy - miy)) * 100.0;
    if(stx != edx&&sty != edy)
    {
        if(num[0] == mxx - mix + 1||num[0] == mxy - miy + 1)
            num[0]--, ans += (10.0 * pi - 20.0);
        double res = (20.0 - 5.0 * pi) * (double)num[0];
        ans = ans - res;
    }
    else
    {
        double res = (10.0 * pi - 20.0) * (double)num[0];
        ans = ans + res;
    }
}

