    if(min(x, x2)<a&&a<max(x, x2)) Z.insert(b);
    if(a==x||a==x2) xflag = false;
    if(b==y||b==y2) yflag = false;
  }
  ll c=0, k=0;
  for(auto itr=Y.begin();itr!=Y.end();itr++, c++) (*itr).second=c;
  multimap<ll, ll> num;
  sort(f.begin(), f.end());
