struct info
{
	LL x,y;
	info() {}
	info(LL _x, LL _y) { x = _x; y = _y; }
	bool operator < ( const info &p ) const
	{
		return x < p.x;
	}
};
info st,ed,ara[Max];
long double cut = 5.0 * acos(-1.0);

map < pair<LL,LL> , bool > mp;

bool isSameLine(info p,info a,info q)
{
	if( p.x == q.x ) return ( min(p.y,q.y) <= a.y && a.y <= max(p.y,q.y) );
	if( p.y == q.y ) return ( min(p.x,q.x) <= a.x && a.x <= max(p.x,q.x) );
	return 0;
}

