				}
			}
			if( flag ) return true;
		}
	}

	///dane
	first = -1;
	rep(i,n)
	{
		if( ara[i].y == st.y )
		{
            first = ara[i].x;
            break;
		}
	}
	if( first != -1 )
	{
		LL d = ed.y - st.y + 1;
		if( d <= n )
		{
			LL flag = 1;
			for(LL i = st.y, k = 0; i <= ed.y; i++,k++)
			{
				LL yy = i;
				LL xx = first + k;
				if( xx > ed.x )
