int lislength(vector<int> &a){
    vector<int> lis;
    for(int i=0; i<a.size(); i++){
        auto itr = upper_bound(lis.begin(), lis.end(), a[i]);
        if(itr == lis.end())
            lis.push_back(a[i]);
        else if(a[i] < *itr)
            *itr = a[i];
    }
    return lis.size();
}

