long int getLIS(vector<loc> &locs){
  long int dp[locs.size()];
  const long int INF = 11451419;
  for (long int i=0; i<locs.size(); ++i) {
    dp[i]=INF;
  }
  for (long int i=0; i<locs.size(); ++i) {
    *lower_bound(dp, dp+locs.size(), locs[i].y) = locs[i].y;
    //debug
    /*
    for (int j=0; j<locs.size(); ++j) {
      cerr<<dp[j]<<",";
    }
    cerr<<endl;
    */
  }

  return lower_bound(dp, dp+locs.size(), INF) - dp;
}


