int lis(vector<int>& v) {
  vector<int> p;
  for (int i = 0; i < v.size(); i ++) {
    if (p.size() == 0 || p.back() < v[i]) {
      p.pb(v[i]);
    } else {
      auto it = lower_bound(p.begin(), p.end(), v[i]);
      *it = v[i];
    }
  }
  return p.size();
}

