t[M];

int get (int l, int r, int v = 1, int tl = 0, int tr = 1e8)
{
    if (l > tr || tl > r || v == 0)
        return 0;

    if (l <= tl && tr <= r)
        return t[v].val;

    int tm = (tl + tr) >> 1;

    return max( get(l, r, t[v].l, tl, tm), get(l, r, t[v].r, tm + 1, tr) );
}
void update (int pos, int val, int v = 1, int tl = 0, int tr = 1e8)
{
    if (tl == tr)
    {
        t[v].val = max( t[v].val, val );
    }
    else
    {
        int tm = (tl + tr) >> 1;
        if (pos <= tm)
        {
            if (!t[v].l) t[v].l = ++Sz;
            update( pos, val, t[v].l, tl, tm );
        }
        else {
            if (!t[v].r) t[v].r = ++Sz;
            update( pos, val, t[v].r, tm + 1, tr );
        }
        t[v].val = max(t[ t[v].l ].val , t[ t[v].r ].val);
    }
}
