		p1.x = mx - p1.x;
		p2.x = mx - p2.x;
		for(int i = 0 ; i < N ; i++) ps[i].x = mx - ps[i].x;
	}
	assert(p1.x <= p2.x);

	if( p1.y == p2.y ){
		swap(p1.y,p1.x);
		swap(p2.y,p2.x);
		for(int i = 0 ; i < N ; i++) swap(ps[i].x,ps[i].y);
	}
	if( p1.x == p2.x ){
		for(int i = 0 ; i < ps.size() ; i++){
			if( ps[i].x == p1.x && p1.y < ps[i].y && ps[i].y < p2.y ){
