		}
		printf("%.15lf\n", 100.0 * (p2.y - p1.y));
		exit(0);
	}

	// 端を含むバージョン
	int b1 = 0;
	{
		vector< pair<int,int> > w;
		for(int i = 0 ; i < N ; i++){
			if( p1.y <= ps[i].y and ps[i].y <= p2.y ){
				if( p1.x <= ps[i].x and ps[i].x <= p2.x ){
					w.push_back({ps[i].x,ps[i].y});
				}
			}
		}
		sort(w.begin(),w.end());
		vector<int> v;
		for(int i = 0 ; i < w.size() ; i++) v.push_back(w[i].second);

		auto b = lis_fast(v);
		b1 = b.size();
	}
	// 端を含まないバージョン
	int b2 = 0;
	{
		vector< pair<int,int> > w;
		for(int i = 0 ; i < N ; i++){
			if( p1.y <= ps[i].y and ps[i].y < p2.y ){
				if( p1.x <= ps[i].x and ps[i].x < p2.x ){
					w.push_back({ps[i].x,ps[i].y});
				}
			}
		}
		sort(w.begin(),w.end());
		vector<int> v;
		for(int i = 0 ; i < w.size() ; i++) v.push_back(w[i].second);

		auto b = lis_fast(v);
		b2 = b.size();
	}
	double wow = 100.0 * (p2.y - p1.y + p2.x - p1.x) + b2 * (pi * 5 - 20);
	if( b1 == b2 ){
		printf("%.15lf\n", 100.0 * (p2.y - p1.y + p2.x - p1.x) + b2 * (pi * 5 - 20));
	}else{
		assert(0);
	}



}

