int main(int argc, char const *argv[]) {
	ios_base::sync_with_stdio(false);
	cin >> sx >> sy >> gx >> gy >> n;
	if (sx > gx) {
		swap(sx, gx);
		swap(sy, gy);
	}
	bool flag = true;
	if (sy > gy) {
		flag = false;
		swap(sy, gy);
	}

	vector<pair<ll, ll> > v;

	FOR(i, n) {
		ll x, y;
