      cout << ans + (res - 1) * q + h << endl;
    } else {
      cout << ans + res * q << endl;
    }
  }
  int LIS(const vector<int> &a) {
    if (a.size() == 0) return 0;
    const int n = a.size();
    vector<int> A(n, 1 << 30);
    vector<int> id(n);
    for (int i = 0; i < n; i++) {
      id[i] = distance(A.begin(), upper_bound(A.begin(), A.end(), a[i]));
      A[id[i]] = a[i];
    }
    int m = *max_element(id.begin(), id.end());
    return m + 1;
  }
};

