							dp[i]=j;
							x[j]=p[i].y;
							break;
						}
					}
				}
			}
			maxn=dp[p.size()-1];
			if(maxn==abs(s.x-t.x+1)||maxn==abs(s.y-t.y+1))
				ans+=5*PI;
			ans=ans-20*maxn+5*PI*maxn;
		}
		else if(s.y>t.y&&p.size()>0)
		{
			int maxn;
			x[1]=p[p.size()-1].y;
			int k=1;
			for(int i=p.size()-2;i>=0;i--)
			{
				if(x[k]<p[i].y)
				{
					x[++k]=p[i].y;
					dp[i]=k;
				}
				else
				{
