  if (n == 0) {
    return 0;
  }

  vector<int> A(n, INF), id(n);
  for (int i = 0; i < n; ++i) {
    id[i] = distance(A.begin(), lower_bound(A.begin(), A.end(), a[i]));
    A[id[i]] = a[i];
  }
  return *max_element(id.begin(), id.end()) + 1;
}

