const ll MAXL = 1e8;
const ll inf = 5e15;

double solve() {
    ll x1, y1, x2, y2;
    cin >> x1 >> y1 >> x2 >> y2;
    ll N;
    cin >> N;
    V<PLL> xy(N);
    for(auto &&ele : xy) {
        ll x, y;
        cin >> x >> y;
        ele = PLL(x, y);
    }

    if(x2 < x1) {
        swap(x1, x2);
        swap(y1, y2);
    }
    if(y2 < y1) {
        y1 = MAXL - y1;
        y2 = MAXL - y2;
        for(auto &&ele : xy) {
            ll x, y;
            tie(x, y) = ele;
            y = MAXL - y;
            ele = PLL(x, y);
        }
    }

    double dist = (x2 - x1) + (y2 - y1);
    dist *= 100;
    double d1 = 2 * 10;
    double d2 = 2 * 10 / 4 * M_PI;
    double diff = d1 - d2;

    {
        auto cpy = move(xy);
        xy.clear();
        for(auto &&ele : cpy) {
            ll x, y;
            tie(x, y) = ele;
            if(!(x1 <= x && x <= x2 &&
                 y1 <= y && y <= y2)) continue;
            xy.push_back(ele);
        }
    }

    sort(ALL(xy));
    V<ll> lcs(N + 10, inf);
    map<ll, ll> y2x;
    y2x[inf] = -1;
    for(auto &&ele : xy) {
        ll x, y;
        tie(x, y) = ele;
        y2x[y] = x;
        auto ite = lower_bound(ALL(lcs), y);
        *ite = y;
    }

    auto ite = lower_bound(ALL(lcs), inf);
    ll idx = distance(lcs.begin(), ite);
    bool cx = y2x[lcs[0]] == x1;
    bool cy = lcs[0] == y1;
    ll px = x1, py = y1;
    for(ll i = 1; i < idx; i++) {
        ll y = lcs[i];
        ll x = y2x[y];
        if(px + 1 != x) cx = false;
        if(py + 1 != y) cy = false;
        px = x;
        py = y;
    }
    if(px != x2) cx = false;
    if(py != y2) cy = false;

    double ans = dist - idx * diff;
    if(cx || cy) ans += d2;
    return ans;
}

