#define SWAP(x, y) { auto tmp = x; x = y; y = tmp; }

double dp[MAX_W+1][MAX_W+1];
int inx1, iny1, inx2, iny2;
int N;
set<pair<int, int> > fountains;

bool on_fountain(int x, int y) {
    auto it = fountains.find(make_pair(x, y));
    if (it != fountains.end()) {
        return true;
    } else {
        return false;
    }
}
double get_distance(int prevx, int prevy, int x, int y, int nextx, int nexty) {
    double res = 100.0;
    if (on_fountain(x, y)) {
        if (prevx == -1 || prevy == -1) {
            // discard
        } else if (prevx != nextx && prevy == nexty) { // VERT
            res += -10.0 + 20.0*M_PI/4.0;
        } else if (prevy != nexty && prevx == nextx) { // HORI
            res += -10.0 + 20.0*M_PI/4.0;
        } else {
            res -= 10.0;
        }
    }
    if (on_fountain(nextx, nexty)) {
        res += -10.0 + 20.0*M_PI/4.0;
    }
    return res;
}

double dp1(int prevx, int prevy, int x, int y) {
    if (dp[x][y] >= 0){
        return dp[x][y];
    }
    double res;
    if (x == inx2 && y == iny2) {
        res = 0;
    } else if (x == inx2) {
        res = dp1(x, y, x, y+1) + get_distance(prevx, prevy, x, y, x, y+1);
    } else if (y == iny2) {
        res = dp1(x, y, x+1, y) + get_distance(prevx, prevy, x, y, x+1, y);
    } else {
        double res1 = dp1(x, y, x+1, y) + get_distance(prevx, prevy, x, y, x+1, y);
        double res2 = dp1(x, y, x, y+1) + get_distance(prevx, prevy, x, y, x, y+1);
        // int res3 = dp1(x+1, y+1) + get_distance(x, y, x+1, y+1);
        res = min(res1, res2);
    }
    return dp[x][y] = res;
}

