const double Pi = 3.14159265358979326;
const double r = 10.0;
typedef long long LL;
const LL INF = 1LL << 60;
const int maxn = 2e5;
double res;
int cnt, ans;
struct NOOD {
	int x, y;
};
NOOD a, b, num[maxn + 10];
int n;
bool cmp1(NOOD x, NOOD y) {
	if(x.x == y.x)return x.y < y.y;
	return x.x < y.x;
}
bool cmp2(NOOD x, NOOD y) {
	if(x.y == y.y)return x.x < y.x;
	return x.y < y.y;
}
bool cmp3(NOOD x, NOOD y) {
	if(x.y == y.y)return x.x > y.x;
	return x.y < y.y;
}
bool cmp4(NOOD x, NOOD y) {
	if(x.x == y.x)return x.y < y.y;
	return x.x > y.x;
}
void solve() {
	res = fabs(a.x - b.x) + fabs(a.y - b.y);
	res *= 100.0;
	if(a.x <= b.x && a.y <= b.y || a.x >= b.x && a.y >= b.y) {
		if(a.x >= b.x && a.y >= b.y)swap(a, b);
		int x = a.x, y = a.y;
		sort(num + 1, num + n + 1, cmp1);
		for(int i = 1; i <= n; i++) {
			if(num[i].x >= x && num[i].y >= y && num[i].x <= b.x && num[i].y <= b.y)cnt++, x = num[i].x, y = num[i].y;
		}
		ans = cnt, cnt = 0;
		x = a.x, y = a.y;
		sort(num + 1, num + n + 1, cmp2);
		for(int i = 1; i <= n; i++) {
			if(num[i].x >= x && num[i].y >= y && num[i].x <= b.x && num[i].y <= b.y)cnt++, x = num[i].x, y = num[i].y;
		}
		ans = max(cnt, ans);
	}
	else {
		if(a.x <= b.x && a.y >= b.y)swap(a, b);
		int x = a.x, y = a.y;
		cnt = 0;
		sort(num + 1, num + n + 1, cmp3);
		for(int i = 1; i <= n; i++) {
			if(num[i].x <= x && num[i].y >= y && num[i].x >= b.x && num[i].y <= b.y)cnt++, x = num[i].x, y = num[i].y;
		}
		ans = cnt, cnt = 0;
		x = a.x, y = a.y;
		sort(num + 1, num + n + 1, cmp4);
		for(int i = 1; i <= n; i++) {
			if(num[i].x <= x && num[i].y >= y && num[i].x >= b.x && num[i].y <= b.y)cnt++, x = num[i].x, y = num[i].y;
		}
		ans = max(ans, cnt);
	}
	res -= ans * r * 2;
	res += ans * Pi * r / 2;
	if(a.x == b.x || a.y == b.y)
		res += ans * Pi * r / 2;
	printf("%.15lf\n",res);
}
int main() {
	scanf("%d%d%d%d", &a.x, &a.y, &b.x, &b.y);
	scanf("%d", &n);
	for(int i = 1; i <= n; i++) {
		scanf("%d%d", &num[i].x, &num[i].y);
	}
	solve();
	return 0;
}

