            S[++S2]=S[i];
    for(int i=1;i<=Size;i++)
        D[i]=Search(D[i]);
    for(int i=1;i<=Size;i++)
    {
        Pos=D[i];
        Val=0;
        Query(1,1,S2+1);
        O[i]=++Val;
        Max=max(Max,O[i]);
