        cin >> f[i].first >> f[i].second;
        f[i].second *= k;
        g[i].first = f[i].second;
        g[i].second = f[i].first;
    }
    sort(f.begin(), f.end());
    sort(g.begin(), g.end());
    vector<ll> a, b;
    for (int i = 0; i < n; ++i) {
        if (f[i].first < sx || f[i].first > fx || f[i].second < sy || f[i].second > fy) {
            continue;
        }
        a.push_back(f[i].second);
        b.push_back(g[i].second);
    }
    int m = a.size();
    vector<ll> t(m + 1, INF);
    t[0] = -INF;
    int ans = 0;
    for (int i = 0; i < m; ++i) {
        int p = upper_bound(t.begin(), t.end(), a[i]) - t.begin();
        t[p] = min(t[p], a[i]);
        ans = max(ans, p);
    }
    t.assign(m + 1, INF);
    t[0] = -INF;
    for (int i = 0; i < m; ++i) {
        int p = upper_bound(t.begin(), t.end(), b[i]) - t.begin();
        t[p] = min(t[p], b[i]);
        ans = max(ans, p);
    }
    long double dist = abs(fx - sx + fy - sy) * 100;
    if (ans - 1 == min(fx - sx, fy - sy)) {
        --ans;
        dist += pi * 10 - 20;
    }
    cout << fixed << setprecision(30) << dist - (20.0 - 5 * pi) * ans;
    return 0;
}

