int getmin(string s, int t) {
	int c = 0;
	for (int i = 0;i < 3; i++) {
		c += s[i] - '0';
	}
	if (c > t) {
		int d = c - t;
		int c1, c2, c3;
		c1 = s[0] - '0';
		c2 = s[1] - '0';
		c3 = s[2] - '0';
		if (c1 >= d || c2 >= d || c3 >= d) {
			return 1;
		}
		else if (c1 + c2 >= d || c2 + c3 >= d || c3 + c1 >= d) {
			return 2;
		}
		else
			return 3;
	}
	else if (c < t) {
		int d = t - c;
		int c1, c2, c3;
		c1 = '9' - s[0];
		c2 = '9' - s[1];
		c3 = '9' - s[2];
		if (c1 >= d || c2 >= d || c3 >= d) {
			return 1;
		}
		else if (c1 + c2 >= d || c2 + c3 >= d || c3 + c1 >= d) {
			return 2;
		}
		else
			return 3;
	}
	return 0;
}

