	while (pos <= cnt + 2){
		ft[pos] = max(ft[pos], val);
		pos += (pos & (-pos));
	}
}
int query(int pos){
	int res = 0;
	while (pos > 0){
		res = max(res, ft[pos]);
		pos -= (pos & (-pos));
	}
	return res;
}
