#define Q (5.0*PI - 20.0L)
#define H (20.0L - 10.0*PI)
using namespace std;

INT a, b, c, d, n, X[200020], Y[200020], lis[200020], cnt, ed, v, C;
long double ans;
struct JK{ INT x, y; } T[200020];

int main()
{
    ios::sync_with_stdio(false);
    cin>>a>>b>>c>>d>>n;
    for(int i = 0 ; i < n ; i++ )
    {
        cin>>X[i]>>Y[i];
        if( a <= c and b <= d )
        {
            if( (a <= X[i]&&X[i] <= c) and ( b <= Y[i]&&Y[i] <= d ) )
                T[cnt++] = { X[i], Y[i] };
        }
        else if( a >= c and b <= d )
        {
            if( (c <= X[i]&&X[i] <= a) and ( b <= Y[i]&&Y[i] <= d ) )
                T[cnt++] = { X[i], Y[i] };
        }
        else if( a <= c and b >= d )
        {
            if( (a <= X[i]&&X[i] <= c) and ( d <= Y[i]&&Y[i] <= b ) )
                T[cnt++] = { X[i], Y[i] };
        }
        else if( a >= c and b >= d )
        {
            if( (c <= X[i]&&X[i] <= a) and ( d <= Y[i]&&Y[i] <= b ) )
                T[cnt++] = { X[i], Y[i] };
        }
    }
    if( a == c ) return cout<<setprecision(20)<<(long double)(abs(b-d)*100.0+(cnt?H:0))<<endl, 0;
    if( b == d ) return cout<<setprecision(20)<<(long double)(abs(a-c)*100.0+(cnt?H:0))<<endl, 0;

    if( cnt )
    {
        if( a < c ) sort(T, T+cnt, [](JK a, JK b){ return a.x < b.x; });
        else sort(T, T+cnt, [](JK a, JK b){ return a.x > b.x; });
        lis[0] = T[0].y; ed = 0;
        for(int i = 1 ; i < cnt ; i++ )
        {
            if( lis[ed] < T[i].y ) ed++, lis[ed] = T[i].y;
            else
            {
                v = (int)(lower_bound(lis, lis+ed+1, T[i].y) - lis);
                lis[v] = T[i].y;
            }
        }
        C = ed+1;
        INT X = min(abs(a-c), abs(b-d)) + 1;
        if( C == X ) ans = (long double)((abs(b-d)+abs(a-c))*100.0L+Q*(C-1)+H);
        else ans = (long double)((abs(b-d)+abs(a-c))*100.0L+Q*(C));
    }
    else ans = (long double)((abs(b-d)+abs(a-c)))*100.0L;
    cout<<setprecision(20)<<ans<<endl;
    return 0;
}

