#include <bits/stdc++.h>
using namespace std;
template< typename T >
struct segment_tree {
  int sz;
  vector<T> seg;
  const function<T(T, T)> o;
  const T id;
  segment_tree(int n, const function<T(T, T)> o, const T &id)
    : o(o)
    , id(id)
  {
    sz = 1;
    while(sz < n) sz <<= 1;
    seg.assign(2 * sz, id);
  }
  void update(int k, const T &x) {
    k += sz;
    seg[k] = x;
    while(k >>= 1) {
      seg[k] = o(seg[2 * k], seg[2 * k + 1]);
    }
  }
  T find(int l, int r) {
    T L = id, R = id;
    for(l += sz, r += sz; l < r; l >>= 1, r >>= 1) {
      if(l & 1) L = o(L, seg[l++]);
      if(r & 1) R = o(seg[--r], R);
    }
    return o(L, R);
  }
  T operator[](const int &k) const {
    return seg[k + sz];
  }
  void print() {
    cout << "segment_tree:" << endl;
    int crr = 1;
    for (int p = sz; p; p >>= 1) {
      for (int i = 0; i < sz; i++) {
        cout
            << setw(12)
            << (i % p == 0 ? to_string(seg[crr++]) : "")
            << (i < sz - 1 ? "" : "\n");
      }
    }
    cout << endl;
  }
};
int main() {
  pair<int, int> s, t;
  cin >> s.first >> s.second >> t.first >> t.second;
  int n;
  cin >> n;
  vector<pair<int, int>> a(n);
  for (int i = 0; i < n; i++) cin >> a[i].first >> a[i].second;
  sort(a.begin(), a.end());
  if (s.first > t.first) swap(s, t);
  vector<int> val;
  if (s.second < t.second) reverse(a.begin(), a.end());
  for (int i = 0; i < n; i++) {
    if (s.first <= a[i].first && a[i].first <= t.first && (
      (s.second <= a[i].second && a[i].second <= t.second)
    ||(t.second <= a[i].second && a[i].second <= s.second)
    )) {
      val.push_back(a[i].second);
    }
  }
  vector<int> srd = val;
  int sz = val.size();
  sort(srd.begin(), srd.end());
  map<int, int> mp;
  for (int i = 0; i < sz; i++) mp[srd[i]] = i;
  segment_tree<int> sgt(sz, [](int a, int b) { return max(a, b); }, 0);
  for (int i = 0; i < sz; i++) {
    sgt.update(mp[val[i]], sgt.find(0, mp[val[i]]) + 1);
  }
  double pi = acos(0) * 2;
  int w = abs(t.first - s.first);
  int h = abs(t.second - s.second);
  int cnt = sgt.find(0, sz);
  double ret = 100 * (w + h);
  ret += cnt * (20 * pi / 4 - 20);
  if (w < cnt || h < cnt) ret += 20 * pi / 4;
  cout << ret << endl;
  return 0;
}

