#include <algorithm>
using namespace std;

typedef pair<int, int> pii;

const int INF = (int)2e9;
const double PI = acos(-1.0);
int N;
pii S, G;
vector<pii> W;

void input_data(void) {
	int x1, y1, x2, y2;
	cin >> x1 >> y1 >> x2 >> y2;
	S = make_pair(x1, y1);
	G = make_pair(x2, y2);
	if (x1 > x2)
		swap(S, G);
	int min_x = S.first;
	int max_x = G.first;
	int min_y = min(y1, y2);
	int max_y = max(y1, y2);
	cin >> N;
	for (int i = 0; i < N; ++i) {
		int a, b;
		cin >> a >> b;
		if ((a >= min_x && a <= max_x) && (b >= min_y && b <= max_y))
			W.push_back(make_pair(a, b));
	}
	N = W.size();
}

int get_w_count(void) {
	if (N == 0)
		return 0;
	if (S.second > G.second)
		sort(W.begin(), W.end(), greater<pii>());
	else
		sort(W.begin(), W.end());
	vector<int> A(N);
	for (int i = 0; i < N; ++i)
		A[i] = W[i].second;

	vector<int> dp(N, INF);
	for (int i = 0; i < N; ++i)
		*lower_bound(dp.begin(), dp.end(), A[i]) = A[i];
	int cnt = lower_bound(dp.begin(), dp.end(), INF) - dp.begin();
	return cnt;
}

int main(void) {
	input_data();

	int dx = G.first - S.first;
	int dy = abs(G.second - S.second);
	int s = dx + dy;
	int k = get_w_count();
	int p = k;
	int q = 0;
	if (k == min(dx, dy) + 1) {
		p = k - 1;
		q = 1;
	}
	double dst = 100.0 * s;
	double sht = (20.0 - 5.0 * PI) * p;
	double lng = (10.0 * PI - 20.0) * q;
	double ans = dst - sht + lng;

	cout << fixed << setprecision(15) << ans << '\n';
	return 0;
}

