template<typename T>
class SegTree {
public:
  int n;
  vector<T> data;
  SegTree(int m){
    n=1;
    while(n<m) n*=2;
    data.resize(2*n, 0);
  }
  inline T query(int l, int r){
    T ret = 0;
    for(l+=n, r+=n; l<r; l/=2, r/=2){
      if(l&1) ret = max(ret, data[l++]);
      if(r&1) ret = max(ret, data[--r]);
    }
    return ret;
  }
  inline void update(int k, T a){
    k+=n;
    data[k]=a;
    while(k>0){
      k = k/2;
      data[k] = max(data[k*2], data[k*2+1]);
    }
  }
  inline T operator[](int idx){ return data[idx+n]; }
};

