int dat[600000];

class Segment{
    public :
        int n;
        void init(int n_){
            n=1;
            while(n<n_)n*=2;
            for(int i=0;i<2*n-1;++i)dat[i]=-INT_MAX;
        }

        void update(int k,int a){
            k+=n-1;
            dat[k]=a;
            while(k>0){
                k=(k-1)/2;
                dat[k]=max(dat[k*2+1],dat[k*2+2]);
            }
        }

        int query(int a,int b,int k,int l,int r){
            if(a<=l&&r<=b)return dat[k];
            if(r<=a||b<=l)return -INT_MAX;
            else {
                int vl=query(a,b,k*2+1,l,(l+r)/2);
                int vr=query(a,b,k*2+2,(l+r)/2,r);
                return max(vl,vr);
            }
        }
};

int sx,sy,ex,ey;
int N;
vector<P1> pos;
vector<P1> V;
Segment dp;
int flip_x=1,flip_y=1;

void Flip(){
    if(sx>ex){
        if(sy<ey){
            flip_x=-1;
        }
        else {
            flip_x=-1;
            flip_y=-1;
        }
    }
    else if(sy>ey){
        if(sx<ex){
            flip_y=-1;
        }
        else {
            flip_x=-1;
            flip_y=-1;
        }
    }
    sx*=flip_x,ex*=flip_x,sy*=flip_y,ey*=flip_y;
    //cout<<sx<<" "<<sy<<" "<<ex<<" "<<ey<<endl;
}

int LIS(){
    Segment dp;
    dp.init(N);
    for(int i=0;i<pos.size();++i){
        V.PB(P1(pos[i].second,i));
    }
    sort(V.begin(),V.end());
    for(int i=0;i<V.size();++i){
        int j=-V[i].second;
        dp.update(j,1);
        dp.update(j,max(dat[j+dp.n-1],dp.query(0,j,0,0,dp.n)+1));
    }
    return dat[0];
}

double Distance(int p,int q){
    int s = abs(ex-sx)+abs(ey-sy);
    return (double)100*s-(20-5*PI)*p-(20-10*PI)*q;
}

