        {
            if( lis[ed] < T[i].x ) ed++, lis[ed] = T[i].x;
            else
            {
                v = (int)(lower_bound(lis, lis+ed+1, T[i].x) - lis);
                lis[v] = T[i].x;
            }
        }
        C = max(C, ed+1);
    }
    cout<<setprecision(20)<<(long double)((abs(b-d)+abs(a-c))*100.0L+Q*(C))<<endl;
    return 0;
}

