const int MAXN = 200050;  // limit for array size
int n;  // array size
LL t[2 * MAXN];

inline void calc(int p, int k) {
    t[p] = max(t[p << 1], t[p << 1 | 1]);
}

void up(int l, int r) {
    int k = 2;

    for (l += n, r += n - 1; l > 1; k <<= 1) {
        l >>= 1, r >>= 1;
        for (int i = r; i >= l; --i) calc(i, k);
    }
}


inline void apply(int p, LL value, int k) {
    t[p] = value;
}

void update(int l, int r, LL value) {  // increment interval [l, r) by value
    int l0 = l, r0 = r, k = 1;

    //dn(l0, l0 + 1);
    //dn(r0 - 1, r0);

    for (l += n, r += n; l < r; l >>= 1, r >>= 1, k <<= 1) {
        if (l & 1) apply(l++, value, k);
        if (r & 1) apply(--r, value, k);
    }

    up(l0, l0 + 1);
    up(r0 - 1, r0);
}


LL query(int l, int r) {  // sum on interval [l, r)
//    dn(l, l + 1);
//    dn(r - 1, r);

    LL res = -1;
    for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
        if (l & 1) res = max(res, t[l++]);
        if (r & 1) res = max(res, t[--r]);
    }
    return res;
}

const int MAXC = 100000000;

int dp[MAXN];

int xs, ys, xe, ye, x, y;

vector<PII> pts;

vector<int> vy;
map<int, int> compress;

int main() {
    GI(xs);
    GI(ys);
    GI(xe);
    GI(ye);

    if (xs > xe) {
        swap(xs, xe);
        swap(ys, ye);
    }

    bool rev = ys > ye;

    if (rev) {
        ys = MAXC - ys;
        ye = MAXC - ye;
    }

    assert(xs <= xe && ys <= ye);

    GI(n);

    FORN(i, n) {
        GI(x);
        GI(y);

        if (rev) y = MAXC - y;
        vy.PB(y);

        pts.PB(MP(x, y));
    }

    sort(vy.begin(), vy.end());

    FORN(i, n) {
        compress[vy[i]] = i;
    }

    sort(pts.begin(), pts.end());

    memset(t, -1, sizeof t);
    memset(dp, -1, sizeof dp);

    int valid = 0;

    FORD(i, n) {
        PII pt = pts[i];

        if (pt.FF >= xs && pt.FF <= xe && pt.SS >= ys && pt.SS <= ye) {
            int best = query(compress[pt.SS], n);
            dp[i] = best + 1;

            update(compress[pt.SS], compress[pt.SS] + 1, dp[i]);

            valid++;
        }
    }

//    PR0(dp, n);

    long double res = 100.0 * abs(xs - xe) + 100.0 * abs(ys - ye);

    if (xs == xe || ys == ye) {
        if (valid) res += 10.0 * (PI - 2);
    }
    else {
        FORN(i, n) {
            if (dp[i] != -1) {
                res = min(res, 100.0 * abs(xs - xe) + 100.0 * abs(ys - ye) - 10.0 * (dp[i] + 1) * (2 - PI/2));
            }
        }
    }

    cout << setprecision(18) << res << endl;

    return 0;
}

