ld ans;

vector<ll> temp;

ll fen[maxn];

void add(ll x, ll val){
	while(x < maxn){
		fen[x] += val;
		x += (x & -x);
	}
}

ll get(ll x){
	ll ret = 0;
	while(x){
		ret += fen[x];
		x -= (x & -x);
	}
	return ret;
}

int main(){
	ll xs, xe, ys, ye, n;
	scanf("%lld%lld%lld%lld", &xs, &ys, &xe, &ye);
	ll pot = abs(xs - xe) + abs(ys - ye);
	pot *= 100LL;
	if(xs > xe){
		swap(xs, xe);
		swap(ys, ye);
	}

	scanf("%lld", &n);
	for(ll i = 0; i < n; i++){
		ll x, y;
		scanf("%lld%lld", &x, &y);
		if(xs <= x && x <= xe && min(ye, ys) <= y && y <= max(ye, ys))
			p.pb(mp(x, y));
	}

	sort(p.begin(), p.end());

	if(xs == xe || ys == ye){
		ans = 1.0 * pot;
		if(p.size())
			ans += 2.0 * del - 20.0; 

		cout << fixed << setprecision(22) << ans << endl;
		return 0;
	}

	n = p.size();
	for(ll i = 0; i < n; i++)
		temp.pb(p[i].se);

	sort(temp.begin(), temp.end());

	ll cnt = 0;

	for(ll i = 0; i < n; i++)
		p[i].se = lower_bound(temp.begin(), temp.end(), p[i].se) - temp.begin() + 1;

	for(ll i = 0; i < n; i++){
		if(ys <= ye)
			cnt = max(cnt, get(p[i].se) + 1);
		else
			cnt = max(cnt, get(n + 1) - get(p[i].se) + 1);
		add(p[i].se, 1);
	}
	ans = pot - cnt * (20.0 - del);
	cout << fixed << setprecision(44) << ans << endl;
	return 0;
}

