    if (xs > xe) {
        swap(xs, xe);
        swap(ys, ye);
    }

    bool rev = ys > ye;

    if (rev) {
        ys = MAXC - ys;
        ye = MAXC - ye;
    }

    assert(xs <= xe && ys <= ye);

    GI(n);

    FORN(i, n) {
        GI(x);
