        if (rev) y = MAXC - y;
        vy.PB(y);

        pts.PB(MP(x, y));
    }

    sort(vy.begin(), vy.end());

    FORN(i, n) {
        compress[vy[i]] = i;
    }

    sort(pts.begin(), pts.end());

    memset(t, -1, sizeof t);
