void transf(int n, ll &x1, ll &y1, ll &x2, ll &y2) {
    if (x2 < x1) {
        swap(x1, x2);
        swap(y1, y2);
    }

    if (y2 < y1) {
        fr(i, n)
            a[i].y = M - a[i].y;
        y1 = M - y1;
        y2 = M - y2;
    }
}

bool cmpx(pt a, pt b) {
    return a.x < b.x;
