using namespace std;

typedef long long ll;

struct pt {
    /// Point structure for Int in C++
    int x, y;

    /// CONSTRUCTORS

    pt() : x(0), y(0) {}
    pt(int x, int y) : x(x), y(y) {}

    /// INPUT/OUTPUT

    void print() {
        printf("(%d, %d)", x, y);
    }

    void println() {
        print();
        printf("\n");
    }

    bool read() {
        return scanf("%d %d", &x, &y) == 2;
    }

    /// OPERATORS

    const pt operator +(pt other) {
        return pt(x + other.x, y + other.y);
    }

    const pt operator +(int c) {
        return pt(x + c, y + c);
    }

    const pt operator -(pt other) {
        return pt(x - other.x, y - other.y);
    }

    const pt operator -(int c) {
        return pt(x - c, y - c);
    }

    pt& operator +=(pt other) {
        x += other.x;
        y += other.y;
        return *this;
    }

    pt& operator +=(int c) {
        x += c; y += c;
        return *this;
    }

    pt& operator -=(pt other) {
        x -= other.x;
        y -= other.y;
        return *this;
    }

    pt& operator -=(int c) {
        x -= c; y -= c;
        return *this;
    }

    const pt operator *(int c) {
        return pt(x * c, y * c);
    }

    pt& operator *=(int c) {
        x *= c; y *= c;
        return *this;
    }

    const pt operator /(int c) {
        return pt(x / c, y / c);
    }

    pt& operator /=(int c) {
        x /= c; y /= c;
        return *this;
    }

    pt& operator =(pt other) {
        x = other.x;
        y = other.y;
        return *this;
    }

    /// FUNCTIONS

    ll distSq(pt p) {
        return (x - p.x) * 1ll * (x - p.x) + (y - p.y) * 1ll * (y - p.y);
    }

    double dist(pt p) {
        return sqrt(distSq(p));
    }

    double magnitude() {
        return dist(pt(0, 0));
    }

    int orient(pt a, pt b) {
        ll val = (a.y - y) * 1ll * (b.x - a.x) - (a.x - x) * 1ll * (b.y - a.y);

        if (val == 0) {
            return 0;
        }

        return (val < 0 ? -1 : 1);
    }
};

/// COMPARISON

const bool operator <(pt a, pt b) {return (a.x == b.x ? a.y < b.y : a.x < b.x);}
const bool operator >(pt a, pt b) {return b < a;}
const bool operator ==(pt a, pt b) {return (a.x == b.x && a.y == b.y);}
const bool operator <=(pt a, pt b) {return !(a > b);}
const bool operator >=(pt a, pt b) {return !(a < b);}
const bool operator !=(pt a, pt b) {return !(a == b);}

const double DI = 5.0 * acos(-1.0); 
const bool SEND = 0;

