#include <cstdio>
using namespace std;
#define double long double
const int N = 2e5 + 10;
const int inf = 0x3f3f3f3f;
const double pi = 3.1415926535897932384626;
struct poi {
	int x, y;
	poi(int _x = 0, int _y = 0) {x = _x, y = _y;}
	inline bool operator == (const poi &a) const {return x == a.x && y == a.y;}
	inline bool operator < (const poi &a) const {
		return x == a.x ? y < a.y : x < a.x;
	}
} p[N];
int n, x1, y1, x2, y2, tot, Y[N], bts[N], lis[N]; double ans;

inline int max(int a, int b) {return a > b ? a : b;}
inline int min(int a, int b) {return a < b ? a : b;}
inline void update(int o, int v) {
	for (; o<=n; o += o&-o) bts[o] = max(bts[o], v);
}
inline int query(int o) {
	int ret = -inf;
	for (; o; o -= o&-o) ret = max(ret, bts[o]);
	return ret;
}

template <class T> inline void in(T &x) {
	x = 0; int f = 1; char ch = getchar();
	for (; ch<'0' || ch>'9';) {if (ch=='-') f=-1; ch = getchar();}
	for (; ch>='0' && ch<='9';) x = x*10 + ch-'0', ch = getchar();
	x *= f;
}

inline void init() {
	in(x1), in(y1), in(x2), in(y2), in(n);
	fill(bts, bts + N, -inf);
	for (int i = 1; i <= n; ++i) in(p[i].x), in(p[i].y);
	if (x1 > x2) {
		x1 = -x1, x2 = -x2;
		for (int i = 1; i <= n; ++i) p[i].x = -p[i].x;
	}
	if (y1 > y2) {
		y1 = -y1, y2 = -y2;
		for (int i = 1; i <= n; ++i) p[i].y = -p[i].y;
	}
	p[++n] = poi(x1, y1);
	p[++n] = poi(x2, y2);
	for (int i = 1; i <= n; ++i) Y[i] = p[i].y;
}

inline void work() {
	int cnt;
	sort(p + 1, p + n + 1);
	sort(Y + 1, Y + n + 1);
	y1 = lower_bound(Y + 1, Y + n + 1, y1) - Y;
	y2 = lower_bound(Y + 1, Y + n + 1, y2) - Y;
	for (int i = 1; i <= n; ++i)
		p[i].y = lower_bound(Y + 1, Y + n + 1, p[i].y) - Y;
	for (int i = 1; i <= n; ++i) {
		lis[i] = query(p[i].y) + 1;
		if (p[i] == poi(x1, y1)) lis[i] = 0;
		else if (p[i] == poi(x2, y2)) cnt = lis[i] - 1;
		update(p[i].y, lis[i]);
	}
	ans = ((double) x2 - x1) + ((double) y2 - y1);
	ans *= 100.0;
	ans += ((double) cnt * 5 * (pi - 4));
	if (cnt == min(x2 - x1 + 1, y2 - y1 + 1) && cnt) ans += 5 * pi;
	printf("%.11Lf\n", ans);
}

int main() {init(), work(); return 0;}

