using namespace std;

struct dot{int x, y;} d[N]; int cnt;
int q[N], len;
int n;
double ans;
bool rev;

bool cmp(dot a, dot b){return a.x < b.x;}

int main(){
	int x, y, i, x1, y1, x2, y2, l, r, mid, t;
	scanf("%d %d %d %d", &x1, &y1, &x2, &y2);
	if(x2 < x1){swap(x1, x2); swap(y1, y2);}
	if(y1 > y2){y1 = -y1; y2 = -y2; rev = 1;} 

	scanf("%d", &n);
	for(i = 1; i <= n; ++i){
		scanf("%d %d", &x, &y);
		if(rev) y = -y;
		if(x >= x1 && x <= x2 && y >= y1 && y <= y2)
			d[++cnt] = (dot){x, y};
	}
	//for(i = 1; i <= cnt; ++i) printf("%d %d\n", d[i].x, d[i].y);


	sort(d + 1, d + cnt + 1, cmp);
	for(i = 1; i <= cnt; ++i){
		l = 1; r = len; t = 0;
		while(l <= r){
			mid = l + r >> 1;
			if(d[i].y > q[mid]) l = (t = mid) + 1; else r = mid - 1;
		}
		if(t == len) q[++len] = d[i].y; else q[t+1] = min(q[t+1], d[i].y);
	}

	ans = (x2 - x1 + y2 - y1) * 100.0;
	if(x1 == x2 || y1 == y2){
		if(cnt) ans += 10.0 * Pi - 20.0;
	} else
		ans-= (20.0 - 5.0 * Pi) * len;
	printf("%.13lf\n", ans);
	return 0;
}

