#include<bits/stdc++.h>
using namespace std;
typedef long long ll;
const int N = 2e5 + 5;
const int INF = 1e8;
const double PI = acos(-1.0);

int b[N];

inline void umax(int& a, int b)
{
	if (b > a) a = b;
}

struct Node{
	int x, y;
	bool operator<(const Node& o) const
	{
		if (x == o.x) return y < o.y;
		return x < o.x;
	}
}a[N];

struct BIT{
	int dp[N];
	int n;
	void init(int _n)
	{
		n = _n;
		memset(dp, 0, sizeof dp);
	}
	void modify(int i, int val)
	{
		for (; i <= n; i += i & -i) umax(dp[i], val);
	}
	int query(int i)
	{
		int ret = 0;
		for (; i; i -= i & -i) umax(ret, dp[i]);
		return ret;
	}
}bit;

int main()
{
	int x1, y1, x2, y2; scanf("%d%d%d%d", &x1, &y1, &x2, &y2);
	if (x1 > x2) swap(x1, x2), swap(y1, y2);
	int flag = 0;
	if (y1 > y2)
	{
		y1 = INF - y1, y2 = INF - y2;
		flag = 1;
	}
	int n, cnt = 0; scanf("%d", &n);
	for (int i = 0; i < n; i++)
	{
		int x, y; scanf("%d%d", &x, &y);
		if (flag) y = INF - y;
		if (x >= x1 && x <= x2 && y >= y1 && y <= y2)
		{
			a[cnt] = Node{x, y};
			b[cnt++] = y;
		}
	}
	sort(a, a + cnt);
	sort(b, b + cnt);
	bit.init(cnt);
	for (int i = 0; i < cnt; i++)
	{
		int k = lower_bound(b, b + cnt, a[i].y) - b;
		bit.modify(k + 1, bit.query(k) + 1);
	}
	int maxv = bit.query(cnt);
	double ans = (x2 - x1 + y2 - y1) * 100.0 + maxv * (5 * PI - 20);
	if (maxv == min(x2 - x1, y2 - y1) + 1) ans += 5 * PI;
	printf("%.15f\n", ans);
	return 0;
}

