typedef long long ll;

template <class T> int LIS(vector<T> &a) {
    T INF = numeric_limits<T>::max() / 2;
    vector<T> res(a.size()+1,INF);
    for (int i = 0; i < a.size(); i++) {
        *(lower_bound(res.begin(),res.end(),a[i])) = a[i];
    }
    for (int i = 0; i < a.size(); i++) {
        if (res[i] == INF) return i;
    }
    return (int) a.size();
}

double get_ans(ll x1, ll x2, ll y1, ll y2, ll N, vector<ll> X, vector<ll> Y) {
	bool dir;
	if (x1 <= x2 && y1 <= y2) dir = true;
	if (x1 <= x2 && y1 > y2) dir = false;
	if (x1 > x2 && y1 <= y2) dir = false;
	if (x1 > x2 && y1 > y2) dir = true;

	ll u = max(y1,y2);
	ll d = min(y1,y2);
	ll l = min(x1,x2);
	ll r = max(x1,x2);

	vector< pair<ll,ll> > arr;
	REP(i,N) {
		if (X[i] >= l && X[i] <= r && Y[i] >= d && Y[i] <= u) {
			if (!dir) Y[i] *= -1;
			arr.push_back(make_pair(X[i],Y[i]));
		}
	}

	sort(arr.begin(), arr.end());

	vector<ll> lis;
	REP(i,arr.size()) lis.push_back(arr[i].second);

	ll cross = LIS<ll> (lis);
	ll t = abs(x1 - x2) + abs(y1 - y2);
	double ans = (double) t * 100.0;
	ans -= 20.0 * (double) cross;
	ans += M_PI * (double) cross / 2.0 * 10.0;

	if (x1 == x2 || y1 == y2) {
		ans = (double) t * 100.0;
		ans -= 20.0;
		ans += M_PI * 10.0;
	}
	return ans;
}

int main() {

	ll x1,y1,x2,y2;
	ll N;
	vector<ll> X,Y;

	cin >> x1 >> y1 >> x2 >> y2;
	cin >> N;

	X.resize(N);
