	REP(i,N) cin >> X[i] >> Y[i];

	double ans = get_ans(x1,x2,y1,y2,N,X,Y);
	swap(X,Y);
	ans = min(ans,get_ans(x1,x2,y1,y2,N,X,Y));

	cout << fixed << setprecision(15) << ans << endl;

	return 0;
}

