typedef int T_CC;
const int CC_MAX = 200010;

class CC{
	T_CC unzip[CC_MAX];
	map<T_CC , int> zip;
	int size;

public:

	void dft(){
		size = 0;
		zip.clear();
	}

	int insert(T_CC a){
		if(size == CC_MAX) return -1;
		zip[a] = size;
		unzip[size] = a;
		return ++size;
	}

	int arrange(){
		int a = 0;
		for(map<T_CC , int>::iterator it = zip.begin() ; it != zip.end() ; ++it){
			(*it).second = a;
			unzip[a] = (*it).first;
			++a;
		}
		size = a;
		return size;
	}

	int get_size(){
		return size;
	}

	int code(T_CC a){
		map<T_CC , int>::iterator it = zip.find(a);
		return it != zip.end() ? (*it).second : -1;
	}

	T_CC decode(int a){
		if(a >= size) return 0;
		return unzip[a];
	}
} cc;

const int ST_MAX = (1 << 18);

template <class T> class ST{
	T x[ST_MAX * 2];

	T eval(T a , T b){
		return max(a,b);
	}

	void ren(int a){
		x[a] = eval(x[2 * a] , x[2 * a + 1]);
		if(a > 0) ren(a / 2);
	}

	T read_ST(int a , int b , int e , int s , int f){
		if(e <= s || f <= b) return 0;
		if(s <= b && e <= f) return x[a];
		return eval(read_ST(2 * a , b , (b + e) / 2 , s , f) , read_ST(2 * a + 1 , (b + e) / 2 , e , s , f));
	}

public:

	void dft(){
		fill(x,x+ST_MAX*2,0);
	}

	void put(int a , T b){
		if(x[a + ST_MAX] >= b) return;
		x[a + ST_MAX] = b;
		ren((a + ST_MAX) / 2);
	}

	T get(int s , int f){
		return read_ST(1 , 0 , ST_MAX , s , f);
	}
};

