	ll xs, ys, xt, yt;
	cin >> xs >> ys >> xt >> yt;

	int n;
	cin >> n;

	vector<ll> x(n), y(n);
	for (int i = 0; i < n; ++i) {
		cin >> x[i] >> y[i];
	}

	ld bad = 0;

	vector<pll> v;
	for (int i = 0; i < n; ++i) {
		if (x[i] >= min(xs, xt) && x[i] <= max(xs, xt) && y[i] >= min(ys, yt) && y[i] <= max(ys, yt)) {
			v.pb({x[i], y[i]});
			if (xs == xt) {
				bad = abs(ys - yt) * 100 + (pi - 2) * 10;
				break;
			}
			if (ys == yt) {
				bad = abs(xs - xt) * 100 + (pi - 2) * 10;
				break;
			}
		}
	}

	if (bad != 0) {
		cout << fixed;
		cout.precision(12);
		cout << bad << "\n";
		return 0;
	}

	sort(all(v));

	ll xmin = min(xs, xt);
	ll xmax = max(xs, xt);
	ll ymin = min(ys, yt);
	ll ymax = max(ys, yt);
	ll dx = 0, dy = 0;
	bool cons = true;
	if (sz(v) <= 1) {
		cons = false;
	}
	if (sz(v) > 1) {
		dy = v[1].second - v[0].second;
		dx = v[1].first - v[0].first;
	}
	if (abs(dx) != 1) {
		cons = false;
	}
	if (abs(dy) != 1) {
		cons = false;
	}
	if (cons) {
		for (int i = 2; i < sz(v); ++i) {
			if (v[i].first - v[i - 1].first != dx || v[i].second - v[i - 1].second != dy) {
				cons = false;
			}
		}
	}

	bool f = false;
	if (cons) {
		if (v[0].first == xmin && v.back().first == xmax) {
			f = true;
		}
		if (min(v[0].second, v.back().second) == ymin && max(v[0].second, v.back().second) == ymax) {
			f = true;
		}
	}

	bool inc;
	if (ys < yt && xs < xt) {
		inc = true;
	} else if (ys < yt) {
		inc = false;
	} else if (ys > yt && xs < xt) {
		inc = false;
	} else {
		inc = true;
	}

	if (!inc) {
		for (int i = 0; i < sz(v); ++i) {
			v[i].second = -v[i].second;
		}
	}

	vector<ll> dp;
	dp.pb(-inf);
	for (int i = 0; i < sz(v); ++i) {
		int lf = 0, rg = sz(dp);
		while (rg - lf > 1) {
			int md = (lf + rg) >> 1;
			if (dp[md] < v[i].second) {
				lf = md;
			} else {
				rg = md;
			}
		}
		if (lf + 1 == sz(dp)) {
			dp.pb(v[i].second);
		} else {
			dp[lf + 1] = v[i].second;
		}
	}

	ll k = sz(dp) - 1;
	//cout << xs << " " << xt << " " << ys << " " << yt << "\n";
	ld ans = abs(xs - xt) + abs(ys - yt);
	ans *= 100;
	ans -= ld(k) * (2 - pi / 2) * 10;

	if (f) {
		ans += pi / 2 * 10;
	}

	cout << fixed;
	cout.precision(20);
	cout << ans << "\n";

}

