    for (int i = 0; i < n; ++i) {
        int cnt = 1 + get(1, 0, MAXC, 0, max(0, a[i].y - 1));
        if (cnt > dp[a[i].y]) {
            if (a[i].x == x2 ||
                a[i].y == y2)
                ++bad;
            dp[a[i].y] = cnt;
            upd(1, 0, MAXC, a[i].y, cnt);
        }
    }
    long double ans = (x2 - x1) + abs(y2 - y1);
    int cc = get(1, 0, MAXC, 0, MAXC);
    if (x1 == x2 || y1 == y2)
        ans = ans * 100.0 + (pi * 10.0 - 20.0) * cc;
    else
        ans = ans * 100.0 - fo * cc + (pi * 10.0 - 20.0) * bad;
    printf("%.11Lf", ans);
    return 0;
}

