const int INF = 1e9;
int lc(vector<int>& a) {
    int n = a.size();
    if (n == 0) {
        return 0;
    }
    vector<int> d(n + 1);
    d[0] = -INF;
    for (int i=1; i<=n; ++i) {
        d[i] = INF;
    }

    for (int i=0; i<n; i++) {
        int j = upper_bound(d.begin(), d.end(), a[i]) - d.begin();
        if (d[j-1] < a[i] && a[i] < d[j]) {
            d[j] = a[i];
        }
    }
    for (int i = n; i >= 0; --i) {
        if (d[i] != INF) {
            return i;
        }
    }
    return 0;
}

long double find_min(vector<pair<int, int>>& a, int x1, int y1, int x2, int y2) {
    int n = a.size();
    if (y2 < y1) {
        y1 *= -1;
        y2 *= -1;
        for (int i = 0; i < n; ++i) {
            a[i].second *= -1;
        }
    }
    std::vector<pair<int, int>> cur;
    for (int i = 0; i < n; ++i) {
        if (a[i].first <= x2 && a[i].first >= x1 && a[i].second <= y2 && a[i].second >= y1) {
            // printf("%d %d %d %d\n", x1, y1, x2, y2);
            // printf("%d %d\n", a[i].first, a[i].second);

            cur.push_back(a[i]);
        }
    }
    int f1 = 1;
    int f2 = 1;
    if ((int)cur.size() == x2 - x1 + 1) {
        sort(cur.begin(), cur.end());
        for (int i = 0; i + 1 < (int)cur.size(); ++i) {
            if (cur[i + 1].second < cur[i].second) {
                f1 = 0;
                break;
            }
        }
    }
    if ((int)cur.size() == y2 - y1 + 1) {
        sort(cur.begin(), cur.end());
        for (int i = 0; i + 1 < (int)cur.size(); ++i) {
            if (cur[i + 1].second < cur[i].second) {
                f2 = 0;
                break;
            }
        }
    }
    long double ans = 0;
    if (!(f1 && f2)) {
        ans += 10 * M_PI - 20;
    }
    vector<int> k(cur.size());
    sort(cur.begin(), cur.end());
    for (int i = 0; i < (int)cur.size(); ++i) {
        k[i] = cur[i].second;
    }
    int lcs = lc(k);
    // printf("%d %d %d %d\n", x1, y1, x2, y2);
    // printf("%d\n", lcs);
    return 100.0*((long double)x2 - (long double)x1 + (long double)y2 - (long double)y1) + ans - (long double)lcs * (20 - 5 * M_PI);
}

