int lis(vector<int> a){
	if(a.size() == 0) return 0;
	vector<int> s(a.size());
	int l = 0;
	s[l++]=a[0];
	for(int i=1;i<(int)a.size();i++)
		if(a[i]>s[l-1])
			s[l++]=a[i];
		else
			*lower_bound(s.begin(),s.begin()+l,a[i])=a[i];
	return l;
}

