bool cmp_x(const pos_t&a, const pos_t&b)
{
	return a.x<b.x;
}


bool cmp_y(const pos_t&a, const pos_t&b)
{
	return a.y<b.y;
}


void print(int dx, int dy, int rq, int hq)
{
	ld round=5*M_PI;
	ld d=abs(dx)+abs(dy);
	ld ans;

	if(hq)
	{
		ans=d*100.0-20.0+round*2;
	}
	else if(rq)
	{
		ans=d*100.0-(20-round)*rq;
	}
	else
	{
		ans=d*100.0;
	}
	printf("%.10Lf\n", ans);
}


int main(void)
{
	pos_t s, g;
	int n;

	while(scanf("%d%d%d%d%d", &s.x, &s.y, &g.x, &g.y, &n)==5)
	{
		vector<pos_t> p(n);

		for(int i=0;i<n;i++)
		{
			scanf("%d%d", &p[i].x, &p[i].y);
		}

		if(s.x==g.x)
		{
			sort(p.begin(), p.end(), cmp_x);
			auto it=lower_bound(p.begin(), p.end(), s, cmp_x);
			int is_hq=0;
			if(it->x==s.x)
			{
				if(s.y>g.y) swap(s, g);
				if(s.y<it->y && it->y<g.y) is_hq=1;
			}
			print(0, g.y-s.y, 0, is_hq);
			continue;
		}

		if(s.y==g.y)
		{
			sort(p.begin(), p.end(), cmp_y);
			auto it=lower_bound(p.begin(), p.end(), s, cmp_y);
			int is_hq=0;
			if(it->y==s.y)
			{
				if(s.x>g.x) swap(s, g);
				if(s.x<it->x && it->x<g.x) is_hq=1;
			}
			print(g.x-s.x, 0, 0, is_hq);
			continue;
		}

		if(s.x>g.x)
		{
			swap(s, g);
			swap(s, g);
		}
		if(s.y>g.y)
		{
			for(auto&pe:p) pe.y=-pe.y;
			s.y=-s.y;
			g.y=-g.y;
		}

		int min_y=min(s.y, g.y);
		int max_y=max(s.y, g.y);

		vector<pos_t> w;

		sort(p.begin(), p.end(), cmp_x);
		for(auto it=lower_bound(p.begin(), p.end(), s, cmp_x);it!=p.end();++it)
		{
			if(it->x>g.x) break;
			if(it->y<min_y || max_y<it->y) continue;
//printf("it=(%d,%d)\n", it->x, it->y);
			auto wit=lower_bound(w.begin(), w.end(), *it, cmp_y);
			if(wit==w.end())
			{
				w.push_back(*it);
			}
			else
			{
				*wit=*it;
			}
		}
//		for(auto&we:w) printf("%d %d\n", we.x, we.y);
		print(s.x-g.x, s.y-g.y, w.size(), 0);
	}

	return 0;
}

