        cout << (x2 - x1) * 100 + diff * (a.size()) << endl;
        return 0;
    }
    sort(a.begin(), a.end());
    if (y1 < y2) {
        ld ans = 100 * ((x2 - x1) + (y2 - y1));
        int add = lis(a);
        ans -= 20 * add;
        ans += (ld)add * ((2 * pi * 10) / 4);
