	for(int i=0;i<n;i++)
	{
		int x,y;
		scanf("%d %d",&x,&y);
		vx.push_back(P(x,y));
	}
	double ret=solve(vx,x1,x2,y1,y2);
	printf("%.12f\n",ret);
	return 0;
}

