template < typename TP, const TP& (*F)(const TP&, const TP&) >
struct SegmentTree {
    int MAX;
    vector < TP > tree;
    SegmentTree(int n, TP zero) { MAX = 1 << (32 - __builtin_clz(n)); tree.resize(2 * MAX + 7, zero); }
    SegmentTree(int n, vector < TP > &t)
    {
        MAX = 1 << (32 - __builtin_clz(n)); tree.resize(2 * MAX + 7, 0);
        for(int i = 0; i < sz(t); i++)
            tree[i + MAX] = t[i];
        for(int i = MAX - 1; i; i--)
            tree[i] = F(tree[2 * i], tree[2 * i + 1]);
    }
    void update(int id, TP val)
    {
        id += MAX, tree[id] = val;
        while(id > 1)
        {
            id >>= 1;
            tree[id] = F(tree[2 * id], tree[2 * id + 1]);
        }
    }
    TP query(int a, int b)
    {
        int va = a + MAX, vb = b + MAX;
        TP res = F(tree[va], tree[vb]);
        while(va / 2 != vb / 2)
        {
            if(va % 2 == 0) res = F(res, tree[va + 1]);
            if(vb % 2 == 1) res = F(res, tree[vb - 1]);
            va >>= 1, vb >>= 1;
        }
        return res;
    }
};

