const int N = 2e5 + 10;  // limit for array size
int n;  // array size
int t[2 * N][2];

void modify(int p, int value, int wsk) {  // set value at position p
	for (t[p += n][wsk] = value; p > 1; p >>= 1) t[p >> 1][wsk] = max(t[p][wsk], t[p ^ 1][wsk]);
}

int query(int l, int r, int wsk) {  // max on interval [l, r)
	int res = 0;
	for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
		if (l & 1) res = max(res, t[l++][wsk]);
		if (r & 1) res = max(res, t[--r][wsk]);
	}
	return res;
}

