int lis(vector<int> a){
	if(a.size() == 0) return 0;
	vector<int> s(a.size());
	int l = 0;
	s[l++]=a[0];
	for(int i=1;i<(int)a.size();i++)
		if(a[i]>s[l-1])
			s[l++]=a[i];
		else
			*lower_bound(s.begin(),s.begin()+l,a[i])=a[i];
	return l;
}

int solve(){
	cin >> xx1 >> yy1 >> xx2 >> yy2 >> n;
	for(int i=0;i<n;i++) cin >> a[i].xx >> a[i].yy;
	if(xx1 > xx2){
		for(int i=0;i<n;i++) a[i].xx *= -1;
		xx1 *= -1, xx2 *= -1;
	}
	if(yy1 > yy2){
		for(int i=0;i<n;i++) a[i].yy *= -1;
		yy1 *= -1, yy2 *= -1;
	}

	long double orig = 100LL * (xx2 - xx1 + yy2 - yy1);

	if(xx1 == xx2){
		long double wtf = 20LL * atan((long double) 1) * 2LL - 20LL;
		int ok = 1;
		for(int i=0;i<n;i++) if(a[i].yy >= yy1 && a[i].yy <= yy2 && a[i].xx == xx1) ok = 0;
		cout << fixed << setprecision(15) << orig + (1 - ok) * wtf << endl;
		return 0;
	}
	if(yy1 == yy2){
		long double wtf = 20LL * atan((long double) 1) * 2LL - 20LL;
		int ok = 1;
		for(int i=0;i<n;i++) if(a[i].xx >= xx1 && a[i].xx <= xx2 && a[i].yy == yy1) ok = 0;
		cout << fixed << setprecision(15) << orig + (1 - ok) * wtf << endl;
		return 0;
	}
	if(xx2 - xx1 == 1){
		long double wtf = 20LL * atan((long double) 1) * 2LL - 20LL;
		long double cand = 20LL - 20LL * atan((long double) 1LL);
		int lo = INF, hi = INF;
		for(int i=0;i<n;i++) if(a[i].yy >= yy1 && a[i].yy <= yy2 && a[i].xx == xx1) lo = a[i].yy;
		for(int i=0;i<n;i++) if(a[i].yy >= yy1 && a[i].yy <= yy2 && a[i].xx == xx2) hi = a[i].yy;
		// cerr << lo << ' ' << hi << endl;
		if(lo == INF && hi == INF)
			cout << fixed << setprecision(15) << orig << endl;
		else if(lo == INF && hi != INF || lo != INF && hi == INF)
			cout << fixed << setprecision(15) << orig - cand << endl;
		else if(lo < hi)
			cout << fixed << setprecision(15) << orig - cand + wtf << endl;
		else
			cout << fixed << setprecision(15) << orig - cand << endl;
		return 0;
	}
	if(yy2 - yy1 == 1){
		long double wtf = 20LL * atan((long double) 1) * 2LL - 20LL;
		long double cand = 20LL - 20LL * atan((long double) 1LL);
		int lo = INF, hi = INF;
		for(int i=0;i<n;i++) if(a[i].xx >= xx1 && a[i].xx <= xx2 && a[i].yy == yy1) lo = a[i].xx;
		for(int i=0;i<n;i++) if(a[i].xx >= xx1 && a[i].xx <= xx2 && a[i].yy == yy2) hi = a[i].xx;
		if(lo == INF && hi == INF)
			cout << fixed << setprecision(15) << orig << endl;
		else if(lo == INF && hi != INF || lo != INF && hi == INF)
			cout << fixed << setprecision(15) << orig - cand << endl;
		else if(lo < hi)
			cout << fixed << setprecision(15) << orig - cand + wtf << endl;
		else
			cout << fixed << setprecision(15) << orig - cand << endl;
		return 0;
	}


	sort(a, a+n);
	vector<int> b;
	for(int i=0;i<n;i++) if(a[i].yy >= yy1 && a[i].yy <= yy2 && a[i].xx >= xx1 && a[i].xx <= xx2) b.push_back(a[i].xx);
	long double cand = 20LL - 20LL * atan((long double) 1LL);
	int lss = lis(b);
	long double ans = orig - 1LL * lss * cand;
	cout << fixed << setprecision(15) << ans << endl;
    return 0;
}

