struct SEG{ // min
    int d[_M * 2];
    int m;
    void init(int m){
        this->m = m;
        REP(i, m * 2 - 1)d[i] = INF;
    }
    void update(int i, int x){
        i += m - 1;
        d[i] = x;
        while(i>0){
            i = (i -1) / 2;
            d[i] = min(d[i * 2 + 1], d[i * 2 + 2]);
        }
    }
    int query(int a, int b){
        return _query(a, b, 0, 0, m);
    }
    private:int _query(int a, int b, int k, int l, int r){
        if(r <= a || b <= l) return INF;
        if(a <= l && r <=b) return d[k];
        int vl = _query(a, b, k * 2 + 1, l, (l + r) / 2);
        int vr = _query(a, b, k * 2 + 2, (l + r) / 2, r);
        return min(vl, vr);
    }
};

bool inside(int x, int y){
	return x1 <= x && x <= x2 &&
			yy1 <= y && y <= yy2;
}
SEG seg;
int main() {
	cin >> x1 >> yy1 >> x2 >> yy2 >> n;
	//init
	REP(i, n)cnt[i] = -1;
	int m = 1;
    while(m<n)m*=2;
    seg.init(m);
	//
	int xk = 1, yk = 1;
	if(x1>x2&&yy1>yy2){
		swap(x1,x2);
		swap(yy1,yy2);
	}else if(x1>x2){
		x1*=-1;x2*=-1;
		xk=-1;
	}else if(yy1>yy2){
		yy1*=-1;yy2*=-1;
		yk=-1;
	}
	REP(i, n){
		int xx, yy;
		cin >> xx >> yy;
		p[i] = MP(xx * xk, yy * yk);
	}
	sort(p, p+n);
	REP(i,n)dump(p[i].first);
	int M = 0;
	RREP(i,n){
		if(!inside(p[i].X, p[i].Y)){
			cnt[i] = 0;
			seg.update(i, 0);
			continue;
		}
		cnt[i]=seg.query(i, n);
		if(cnt[i]==INF)cnt[i] = 0;
		seg.update(i, cnt[i]);
		cnt[i]++;
	}
	REP(i, n){ //count (right and top) s
		M = max(M,cnt[i]);
	}
	long double ans = (ll)((x2-x1)+(yy2-yy1)) * 100;
	cout << fixed << setprecision(13);

	if(M==min((x2-x1),(yy2-yy1))+1){
		ans += (M-1) * (5*PI - 20) - 20 + 10 * PI;
	}else{
		ans += M * (5*PI - 20);
	}
	cout << fixed << setprecision(13) << ans << endl;
	return 0;
}

