using namespace std;
typedef long long LL;
//const int MOD = 1e9+7;
const auto INF = 0x3f3f3f3f;
const int N = 2e5+5;
const double pri = acos(-1.0);
struct node {
    int x, y;
}A, B, E[N], Ans[N];

map<int, int> maps[2];

bool cmp1(const struct node &u, const struct node &v) {
    if(u.x == v.x)
        return u.y < v.y;
    return u.x < v.x;
}

bool cmp2(const struct node &u, const struct node &v) {
    if(u.x == v.x)
        return u.y < v.y;
    return u.x > v.x;
}

int b[N];

int main() {
    double p1 = (double)10*pri;
    double p2 = (double)5*pri;
    int n;
    scanf("%d%d%d%d", &A.x, &A.y, &B.x, &B.y);
    scanf("%d", &n);
    int x1 = min(A.x, B.x), x2 = max(A.x, B.x);
    int y1 = min(A.y, B.y), y2 = max(A.y, B.y);
    int cnt = 0;
    for(int i=1; i<=n; i++) {
        scanf("%d%d", &E[i].x, &E[i].y);
        if(E[i].y >= y1 && E[i].y <= y2)
            maps[0][E[i].x]++;
        if(E[i].x >= x1 && E[i].x <= x2)
            maps[1][E[i].y]++;
        if(E[i].x >= x1 && E[i].x <= x2 && E[i].y >= y1 && E[i].y <= y2) {
            Ans[++cnt] = E[i];
        }
    }
    if(A.x == B.x) {
        double answer = (double)100*(y2 - y1);
        if(maps[0].find(A.x) != maps[0].end()) {
            answer += p1 - 20.0;
        }
        printf("%.11lf\n", answer);
        return 0;
    }
    if(A.y == B.y) {
        double answer = (double)100*(x2 - x1);
        if(maps[1].find(A.y) != maps[1].end()) {
            answer += p1 - 20.0;
        }
        printf("%.11lf\n", answer);
        return 0;
    }
    if(A.y > B.y)
        swap(A, B);
    if(A.x < B.x)
        sort(Ans+1, Ans+1+cnt, cmp1);
    else
        sort(Ans+1, Ans+1+cnt, cmp2);
    int len = 1;
    b[1] = Ans[1].y;
    for(int i=2; i<=cnt; i++) {
        if(Ans[i].y > b[len]) {
            b[++len] = Ans[i].y;
        } else {
            int pos = (int)(lower_bound(b+1, b+1+len, Ans[i].y) - b);
            b[pos] = Ans[i].y;
        }
    }
    if(cnt == 0)
        len = 0;
    double answer = (double)100*(double)(y2 - y1 + x2 - x1);
    if(len == x2-x1+1 || len == y2-y1+1) {
        len--;
        answer += (double)len * p2 - (double)len * 20.0;
        answer += p1 - 20;
    } else
        answer += (double)len * p2 - (double)len * 20.0;
    printf("%.11lf\n", answer);
}

