map<int, int> compress(vector<int> &x) {
    map<int,int> zip;
    sort(x.begin(), x.end());
    x.erase(unique(x.begin(),x.end()),x.end());
    for(int i = 0; i < x.size(); i++){
        zip[x[i]] = i;
    }
    return zip;
}


class Solver {
  public:
    double solve2(int sx, int ex, P s, P e, vector<P> &S, int y_size) {
        RangeMaxQuery<ll, 0LL> query(y_size);
        for(int i = S.size() - 1; i >= 0; i--) {
            if(S[i].x >= e.x) continue;
            if(S[i].x <= s.x) break;
            if(s.y <= S[i].y and S[i].y <= e.y)
                query.update(0, S[i].y + 1, query.query(S[i].y) + 1);
        }
        ll num = query.query(s.y);
        return num;
    }

    bool solve() {
        P s, e; cin >> s >> e;
        if(s.x > e.x) swap(s, e);
        bool reverse_y = e.y < s.y;
        if(reverse_y) {
            s.y *= -1;
            e.y *= -1;
        }
        ll N; cin >> N;
        vector<int> xs, ys;
        xs.push_back(s.x);
        ys.push_back(s.y);
        xs.push_back(e.x);
        ys.push_back(e.y);
        vector<P> S(N);
        rep(i, N) {
            cin >> S[i];
            if(reverse_y) S[i].y *= -1;
            xs.push_back(S[i].x);
            ys.push_back(S[i].y);
        }
        double ans = e.x - s.x + e.y - s.y;
        ans *= 100;
        map<int, int> map_x = compress(xs);
        map<int, int> map_y = compress(ys);
        auto map = [&] (P &a) {
            a.x = map_x.at(a.x);
            a.y = map_y.at(a.y);
        };
        map(s); map(e);
        rep(i, S.size()) map(S[i]);

        vector<P> Sx = S;
        sort(all(Sx), [](P &a, P &b) { return a.x < b.x; });

        int num = solve2(s.x, e.x, s, e, Sx, map_y.size());

        bool x_exist= false, y_exist = false;
        rep(i, N) {
            x_exist |= S[i].x == s.x;
            y_exist |= S[i].y == s.y;
        }
        if(s.x == e.x and x_exist) ans += 2 * M_PI * 10 / 2.0 - 20.0;
        else if(s.y == e.y and y_exist) ans += 2 * M_PI * 10 / 2.0 - 20.0;
        else {
            ans -= num * 20.0;
            ans += 2 * M_PI * 10.0 / 4.0 * num;
        }

        printf("%.10lf\n", ans);

        return 0;
    }
};

int main() {
    Solver s;
    s.solve();
    return 0;
}

