int CeilIndex(vi &v, int l, int r, int key) {
    while (r-l > 1){
        int m = l + (r-l)/2;
        if (v[m] >= key) r = m;
        else l = m;
    }

    return r;
}

int LISLength(vi &v){
    if (sz(v) == 0) return 0;

    vi tail(sz(v), 0);
    int length = 1;

    tail[0] = v[0];
    lp(i,1,sz(v)-1){
        if (v[i] < tail[0])
            tail[0] = v[i];
        else if (v[i] > tail[length-1])
            tail[length++] = v[i];
        else
            tail[CeilIndex(tail, -1, length-1, v[i])] = v[i];
    }

    return length;
}

