const int M = 1 << 20;
int drz[2 * M + 5];
int Read(int a, int b) {
  a += M;
  b += M;
  int res = max(drz[a], drz[b]);
  while (a / 2 != b / 2) {
    if (a % 2 == 0) {
      maxi(res, drz[a + 1]);
    }
    if (b % 2 == 1) {
      maxi(res, drz[b - 1]);
    }
    a /= 2;
    b /= 2;
  }
  return res;
}
void Upd(int a, int v) {
  a += M;
  while (a) {
    maxi(drz[a], v);
    a /= 2;
  }
}

