#define db double
const int N = 3e5 + 233;
const db red = 4.2920367320510338076867830836025;
const db gr = 15.707963267948966192313216916398;
struct Point {
  int x, y;
}p[N];
unordered_map<int, set<int> > mpx, mpy;
int fx, fy, sx, sy, dist, k, n, m;
db ans = 0.0;
int x[N], y[N], yy[N], yy_cnt = 0;

inline bool cmp_xy(Point a, Point b) {
  return a.x < b.x || a.x == b.x && a.y < b.y;
}
namespace bit {
  int tr[N];
  inline void add(int x, int y) {
    for (; x <= yy_cnt; x += x & -x)
      tr[x] = max(tr[x], y);
  }
  inline int query(int x) {
    int ans = 0;
    for (; x; x -= x & -x)
      ans = max(ans, tr[x]);
    return ans;
  }      
}

inline db doit(void) {
  int ans = dist * 100;
  for (int i = 1; i <= n; i ++)
    if (fx <= x[i] && x[i] <= sx && 
        fy <= y[i] && y[i] <= sy) {
      p[++ m] = {x[i], y[i]};
      yy[++ yy_cnt] = y[i];
    }
  sort(p + 1, p + m + 1, cmp_xy);
  sort(yy + 1, yy + yy_cnt + 1);
  yy_cnt = unique(yy + 1, yy + yy_cnt + 1) - (yy + 1);
  for (int i = 1; i <= m; i ++) {
    int id = lower_bound(yy + 1, yy + yy_cnt + 1, p[i].y) - yy;
    bit::add(id, bit::query(id - 1) + 1);
  }
  int k = bit::query(yy_cnt);
  int p = 0;
  if(k == sx - fx + 1 || k == sy - fy + 1)
    p = 1;
  return ans - k * red + p * gr;
}

