class Point {
public:
    long long x, y;

    Point(long long x = 0, long long y = 0) {
        this->x = x;
        this->y = y;
    }

    Point(const Point &other) {
        x = other.x;
        y = other.y;
    }

    const Point &operator=(const Point &point) {
        x = point.x;
        y = point.y;

        return *this;
    }

    Point operator+(const Point &second) const {
        return Point(x + second.x, y + second.y);
    }

    Point operator-(const Point &second) const {
        return Point(x - second.x, y - second.y);
    }

    friend istream &operator>>(istream &stream, Point &point) {
        stream >> point.x >> point.y;

        return stream;
    }

    friend ostream &operator<<(ostream &stream, Point &point) {
        stream << "Point(" << point.x << ", " << point.y << ")";

        return stream;
    }

    long long distance(const Point &second) const {
        return 100ll * (abs(x - second.x) + abs(y - second.y));
    }
};


class Solver {
 private:
    Point start, end;
    vector<Point> fountains;
    int n;
    long double ans;
    long long int_ans;
    long long float_ans;

 public:
    void input_data() {
        cin >> start >> end;
        cin >> n;

        fountains.resize(n);
        for (int i = 0; i < n; ++i) {
            cin >> fountains[i];
        }
        /*
        cout << "start, end = " << start << ", " << end << endl;
        cout << "n = " << n << endl;
        cout << "fountains:" << endl;
        for (auto fountain : fountains) {
            cout << fountain << endl;
        }
        cout << endl;
        */
    }

    void solve() {
        // Свапнем start и end если нужно
        if (start.x > end.x) {
            swap(start, end);
        }

        // Находим фонтаны внутри прямоугольника с вершинами в start, end
        vector<Point> internal_fountains = get_internal_fountains(start, end, fountains);
        /*
        cout << "internal_fountains:" << endl;
        for (auto fountain : internal_fountains) {
            cout << fountain << endl;
        }
        cout << endl;
        */
        // Обработка вырожденных случаев
        ans = start.distance(end);
        int_ans = start.distance(end);
        float_ans = 0;

        if (start.x == end.x || start.y == end.y) {
            if (!internal_fountains.empty()) {
                ans += 10 * (long double)(M_PI) - 20;
                int_ans += 10 * floor((long double)(M_PI));
                int_ans -= 20;
                long double add = 10 * ((long double)(M_PI) - floor((long double)(M_PI)));
                int_ans += floor(add);
                float_ans += floor((add - floor(add)) * 1e15);
            }

            return;
        }

        // Подготавливаем internal_fountains к get_lis_len
        sort(internal_fountains.begin(), internal_fountains.end(), comp);
        if (start.y > end.y) {
            reverse(internal_fountains.begin(), internal_fountains.end());
        }
        /*
        cout << "sorted internal_fountains:" << endl;
        for (auto fountain : internal_fountains) {
            cout << fountain << endl;
        }
        cout << endl;
        */
        // Находим длину НВП, где значениями в массиве выступаю Point.x
        int lis_len = get_lis_len(internal_fountains);
        /*
        cout << "lis_len = " << lis_len << endl << endl;
        */
        // Окончательный ответ
        ans += lis_len * 5 * ((long double)(M_PI) - 4);

        int_ans -= lis_len * 5 * 4;
        int_ans += lis_len * 5 * floor((long double)(M_PI));
        long double add = lis_len * 5 * ((long double)(M_PI) - floor((long double)(M_PI)));
        int_ans += floor(add);
        float_ans += floor((add - floor(add)) * 1e15);
    }

    void output_answer() {
        //cout << ans << endl;
        cout << int_ans << "." << float_ans << endl;
    }
};



bool comp(const Point &a, const Point &b) {
    return (a.y < b.y);
}

vector<Point> get_internal_fountains(const Point &start, const Point &end, const vector<Point> &fountains) {
    vector<Point> res;

    for (auto fountain : fountains) {
        if (is_internal(fountain, start, end)) {
            res.push_back(fountain);
        }
    }

    return res;
}

bool is_internal(const Point &fountain, const Point &start, const Point &end) {
    return (min(start.x, end.x) <= fountain.x && fountain.x <= max(start.x, end.x) &&
            min(start.y, end.y) <= fountain.y && fountain.y <= max(start.y, end.y));
}

int get_lis_len(const vector<Point> &points) {
    // Находит нвп по y

    vector<long long> dp(points.size() + 1, INF);
    dp[0] = -INF;

    for (auto point : points) {
        int l = 0;
        int r = dp.size() - 1;
        while (l < r) {
            int m = (l + r + 1) / 2;

            if (dp[m] < point.x) {
                l = m;
            } else {
                r = m - 1;
            }
        }

        dp[l + 1] = min(dp[l + 1], point.x);
    }
    /*
    cout << "dp:" << endl;
    for (auto num : dp) {
        cout << num << " ";
    }
    cout << endl << endl;
    */
    for (int i = dp.size() - 1; i >= 0; --i) {
        if (dp[i] != INF) {
            return i;
        }
    }

    return 0;
}


