ld const PI = acos(-1.0);
int const N = 2e5 + 41;

int n;
vector<pii> p;
int x2, y2, x3, y3;

int getLIS(){
	vector<int> v;
	fr(i, 0, sz(p)){
		int l = -1;
		int r = sz(v);
		while(r-l>1){
			int m = (l+r)/2;
			if(v[m] > p[i].second) r = m;
			else l = m;
		}
		if(r == sz(v)) v.pb(p[i].second);
		else v[r] = p[i].second;
	}
	return sz(v);
}

void solve(){
	cin >> x2 >> y2 >> x3 >> y3;
	cin >> n;
	fr(i, 0, n){
		int x, y;
		cin >> x >> y;
		if(x >= min(x2, x3) && x <= max(x2, x3)){
			if(y >= min(y2, y3) && y <= max(y2, y3)){
				p.pb(mp(x, y));
			}
		}
	}

	sort(p.begin(), p.end());
	if( (x2 == min(x2, x3)) ^ (y2 == min(y2, y3)) ){
		reverse(p.begin(), p.end());
	}
	ld ans;
	ld dx = max(x2, x3) - min(x2, x3);
	ld dy = max(y2, y3) - min(y2, y3);
	ans = (dx + dy) * 100;
	int cnt = getLIS();
	ans -= cnt * 20.0;
	if(cnt == max(y2, y3) - min(y2, y3) + 1) ++cnt;
	ans += PI * 5 * cnt;
	if(x2 == x3 || y2 == y3){
		ld pans = (dx + dy + 2) * 100;
		ans = min(ans, pans);
	}
	printf("%.15Lf\n",ans);
}

int main(){
#ifdef _DEBUG
	freopen("input.txt","r",stdin);
	freopen("output.txt","w",stdout);
#endif

	solve();



	return 0;
}

