		if (My.find(x1) != My.end() && My[x1] > min(y1, y2) && My[x1] < max(y1, y2)
			&& My.find(x2) != My.end() && My[x2] > min(y1, y2) && My[x2] < max(y1, y2))
		{
			printf("%.15lf\n", (abs(y1 - y2) + x2 - x1) * 100LL - 40 + 15 * pi);
			return 0;
		}
	}

	if (y1 > y2)
	{
		swap(y1, y2);
		swap(x1, x2);
	}

	xpos.insert(x1);
	xpos.insert(x2);
	int cnt = 0;
	for (auto it = xpos.begin(); it != xpos.end(); it++)
		ind[*it] = cnt++;
	n = xpos.size();

	int prevX = -1, prevV = 0;
	bool special = 0, modified = 0;
	int p1 = ind[x1], p2 = ind[x2];
	for (auto it = Mx.lower_bound(y1); it != Mx.end(); it++)
	{
		// spr czy nie jestes za daleko
		if (it->first > y2)
			break;

		if (it->first == y2)
		{
			// special case - wywal ostatni potencjalnie
			if (prevX != -1 && My[prevX] == y2 - 1)
			{
				if (My[prevX] == y1)
					special = 1;
				else		// mozesz wywalic
				{
					modify(ind[prevX], 0);
					modified = 1;
				}
			}
		}

		int p = ind[it->second], v = 0;

		if (x1 < x2 && p <= p2)
			v = query(p1, p);
		if (x1 > x2 && p >= p2)
			v = query(p, p1 + 1);

		if (special && !v)	// jeszcze bardziej special...
			special = 0;

		modify(p, v + 1);


		if (modified)
			modify(ind[prevX], prevV);

		prevX = it->second;
		prevV = v + 1;
	}

	int l;

	if (x1 < x2)
		l = query(p1, p2 + 1);
	else
		l = query(p2, p1 + 1);

	double res = (abs(x2 - x1) + (y2 - y1)) * 100LL + 5 * l*(pi - 4);

	if (special)
		res += 5 * pi;

	printf("%.15lf\n", res);

	return 0;
}

