int main(){

    ll X1, Y1, X2, Y2, N;
    cin >> X1 >> Y1 >> X2 >> Y2 >> N;
    for(ll i = 0; i < N; ++i){
        cin >> Z[i][0] >> Z[i][1];
    }
    if(X1 > X2){
        swap(X1, X2);
        swap(Y1, Y2);
    }

    Q = Z;
    sort(Q.begin(), Q.begin() + N, [](auto& a, auto& b){
        return a[0] < b[0];
    }); // x
    sort(Z.begin(), Z.begin() + N, [](auto& a, auto& b){
        return a[1] < b[1];
    }); // y

    ll m = 1000000, n = -1000000;
    for(ll i = 0; i < N; ++i){
        if(Q[i][0] >= X1){
            m = i; break;
        }
    }
    for(ll i = N - 1; i >= 0; --i){
        if(Q[i][0] <= X2){
            n = i; break;
        }
    }

    ll maxu = 0, u = 0;
    if(Y1 <= Y2){
        ll lasty = 1000000000000;
        for(ll i = m; i <= n; ++i){
            if(Y1 <= Q[i][1] && Q[i][1] <= Y2){
                if(lasty < Q[i][1]){
                    u += 1;
                }else{
                    u = 1;
                }
                lasty = Q[i][1];
                maxu = max(maxu, u);
            }
        }
    }else{
        ll lasty = -1000000000000;
        for(ll i = m; i <= n; ++i){
            if(Y2 <= Q[i][1] && Q[i][1] <= Y1){
                if(lasty > Q[i][1]){
                    u += 1;
                }else{
                    u = 1;
                }
                lasty = Q[i][1];
                maxu = max(maxu, u);
            }
        }
    }

    const long double pi = 3.14159265358979323846264338327950288L;
    const long double d = 20 - pi * 5;
    const long double bd = pi * 10 - 20;

    long double ans;
    if((X1 == X2 || Y1 == Y2) && maxu == 1){
        ans = (X2 - X1) * 100 + abs(Y2 - Y1) * 100 + maxu * bd;
    }else{
        ans = (X2 - X1) * 100 + abs(Y2 - Y1) * 100 - maxu * d;
    }
    printf("%.16Lf\n", ans);

    return 0;
}

