inline int lowbit(int x){
	return x & (-x);
}

void add(int x, int v){
	while(x <= n){
		c[x] = max(c[x], v);
		x += lowbit(x);
	}
}

int sum(int x){
	int ret = 0;
	while(x){
		ret = max(ret, c[x]);
		x -= lowbit(x);
	}
	return ret;
}

