	For(i, 1, n){
		rk[i] = i;
		if(Sy > Ty) P[i].y = -P[i].y;
	}
	sort(rk + 1, rk + n + 1, cmp);
	For(i, 1, n) val[rk[i]] = i;
	int ans = 0;
	For(i, 1, n){
		int ret = sum(val[i]) + 1;
		ans = max(ans, ret);
