void write(int index,int l,int r,int aim,int num){
    if (l==r){
        t[index]=max(t[index],num);
        return;
    }
    int mid=(l+r)>>1;
    if (mid>=aim)       write(index<<1,l,mid,aim,num);
    else                write(index<<1|1,mid+1,r,aim,num);
    t[index]=max(t[index<<1],t[index<<1|1]);
}

int read(int index,int l,int r,int aiml,int aimr){
    if (aiml<=l&&r<=aimr){
        return t[index];
    }
    int mid=(l+r)>>1,ans=0;
    if (mid>=aiml)  ans=max(ans,read(index<<1,l,mid,aiml,aimr));
    if (mid<aimr)   ans=max(ans,read(index<<1|1,mid+1,r,aiml,aimr));
    return ans;
}

