map<int, int> compress(vector<int> &x) {
    map<int,int> zip;
    sort(x.begin(), x.end());
    x.erase(unique(x.begin(),x.end()),x.end());
    for(int i = 0; i < x.size(); i++){
        zip[x[i]] = i;
    }
    return zip;
}


class Solver {
  public:
    ll solve2(int sx, int ex, P s, P e, vector<P> &S, int y_size) {
        RangeMaximumQuery<ll, 0LL> query(y_size, 0LL);
        for(int i = S.size() - 1; i >= 0; i--) {
            if(S[i].x > e.x) continue;
            if(S[i].x < s.x) break;
            if(s.y <= S[i].y and S[i].y <= e.y) {
                ll v = query.query(S[i].y, y_size);
                query.update(S[i].y, v + 1);
            }
        }
        ll num = query.query(s.y, y_size);
        return num;
    }

    bool solve() {
        P s, e; cin >> s >> e;        
        if(s.x > e.x) swap(s, e);
        bool reverse_y = e.y < s.y;
        if(reverse_y) {
            s.y *= -1;
            e.y *= -1;
        }
        P s_org = s, e_org = e;
        ll N; cin >> N;
        vector<int> ys, xs;
        ys.reserve(N + 2);
        ys.push_back(s.y);
        ys.push_back(e.y);
