        bool xe_exist= false, ye_exist = false;
        rep(i, N) {
            P ss; cin >> ss;
            if(reverse_y) ss.y *= -1;
            if(s.x <= ss.x and ss.x <= e.x and s.y <= ss.y and ss.y <= e.y) {                
                ys.push_back(ss.y);
                S.push_back(ss);
                xs_exist |= ss.x == s.x;
                ys_exist |= ss.y == s.y;
                xe_exist |= ss.x == e.x;
                ye_exist |= ss.y == e.y;                
            }
        }
        double ans = (ll)e.x - (ll)s.x + (ll)e.y - (ll)s.y;
        ans *= 100;
        map<int, int> map_y = compress(ys);
        auto map = [&] (P &a) { a.y = map_y[a.y]; };
        map(s); map(e);
        rep(i, S.size()) map(S[i]);

        vector<P> Sx = S;
        sort(all(Sx), [](P &a, P &b) { return a.x < b.x; });
        ll num = solve2(s.x, e.x, s, e, Sx, map_y.size());
        const double half_round = 2 * M_PI * 10 / 2.0 - 20.0;
        {
            debug(s_org);
