            if(num == e_org.x - s_org.x + 1) {
                ans += half_round;
                num--;
            }
            else if(num == e_org.y - s_org.y + 1) {
                ans += half_round;
                num--;
            }
            ans -= num * 20.0;
            ans += 2 * M_PI * 10.0 / 4.0 * num;
        }
        printf("%.15lf\n", ans);
        return 0;
    }
};

