bool extra(int x1,int y1,int x2, int y2, vector<ii> ft){
	bool ok = true;
	if((LL)(x1-x2)*(LL)(y1-y2) <0) ok = false;
	int n = (int)ft.size();
	int xm = min(x1,x2), xM = max(x1,x2), ym = min(y1,y2), yM = max(y1,y2);
	if(n==xM-xm+1){
		if(!ok) reverse(ft.begin(),ft.end());
		for(int i=1;i<n;++i) if(ft[i].second<ft[i-1].second)  return false;
		return true;
	}
	if(n==yM-ym+1){
		if(!ok) reverse(ft.begin(),ft.end());
		for(int i=0;i<n;++i) if(ft[i].second != ym+i) return false;
		return true;
	}
	return false;
}

int longestAsc(vi A){
	int n = (int)A.size();
	set<ii> ans;
	ans.insert(ii(A[0],1));
	for(int i=1;i<n;++i){
		auto it = ans.upper_bound(ii(A[i],0));
		auto it1 = it;
		int l = 1;
		if(it!=ans.begin()){
			it--;
			l = it->second + 1;
		}
		while(it1!=ans.end() && it1->second <= l) it1 = ans.erase(it1);
		ans.insert(ii(A[i],l));
	}
	return (--ans.end())->second;
}

LD minDis(int x1,int y1, int x2, int y2, vector<ii> ft){
	if(x1 == x2){
		LD ans = 100.*LD(abs(y1-y2));
		if(ft.empty()) return ans;
		ans += (pi-2.)*(LD)10.;
		return ans;
	}
	if(y1 == y2){
		LD ans = 100.*LD(abs(x1-x2));
		if(ft.empty()) return ans;
		ans += (pi-2.)*(LD)10.;
		return ans;
	}
	LD ans = 100.*LD(abs(x1-x2) + abs(y1-y2));
	if(ft.empty()) return ans;
	sort(ft.begin(),ft.end());
	int cnt = 1;
	bool ok = true, ed = false;
	if((LL)(x1-x2)*(LL)(y1-y2) <0) ok = false;
	int L = (int)ft.size();
	if(ok){
		vi tmp(L);
		for(int i=0;i<L;++i) tmp[i] = ft[i].second;
		cnt = longestAsc(tmp);
	}
	else{
		vi tmp(L);
		for(int i=L-1;i>=0;--i) tmp[L-i-1] = ft[i].second;
		cnt = longestAsc(tmp);
	}
	ans -= (LD)cnt*10.*(2.-pi/2.);
	if(extra(x1,y1,x2,y2,ft)) ans += pi/2.*(LD)(10.);
	return ans;
}

