		cin >> a >> b;
		if (a < x.first || a > y.first) {
			i--;
			n--;
		} else arr[i] = make_pair(a, b);

	}
	sort(arr, arr + n);
	bool which = (x.second <= y.second);
	dp[0] = x.second; 
	for (int i = 1; i <= 200000; i++)
		dp[i] = which ? INF : 0;
	int cnt = 0;
	for (int i = 0; i < n; i++) {
		if (arr[i].second > max(x.second, y.second) || arr[i].second < min(x.second, y.second)) continue;
		int l = 0, r = n;
		int ans = -1;
		while (l <= r) {
			int mid = (l + r) / 2;
			if ((dp[mid] <= arr[i].second) != which) r = mid - 1;
			else { 
				ans = mid;
				l = mid + 1;
			}
		}
		if (ans == -1)
			continue;
		if (which) dp[ans + 1] = min(dp[ans + 1], arr[i].second);
		else dp[ans + 1] = max(dp[ans + 1], arr[i].second);
		cnt = max(cnt, ans + 1);
	}
	if (cnt == 1 && (x.first == y.first || x.second == y.second)) 
		printf("%.16lf\n", PI * 10 + 100 * abs(x.first - y.first) + 100 * abs(x.second - y.second) - 20);
	else {
		printf("%.16lf\n", PI * 5 * cnt + 100 * abs(x.first - y.first) + 100 * abs(x.second - y.second) - 20 * cnt);
	}
	return 0;
}

