const int MAX_N = 200050;
const int MAX_L = 100000000;

int N;
int X[MAX_N], Y[MAX_N];

int seq[MAX_N], dp_lis[MAX_N];

int main(int argc, char **argv) {
    int x1, y1, x2, y2;
    std::cin >> x1 >> y1 >> x2 >> y2;
    std::cin >> N;

    for (int i = 1; i <= N; i++) {
        std::cin >> X[i] >> Y[i];
    }

    if (x2 < x1) {
        for (int i = 1; i <= N; i++) {
            X[i] = MAX_L - 1 - X[i];
        }
        x1 = MAX_L - 1 - x1;
        x2 = MAX_L - 1 - x2;
    }

    if (y2 < y1) {
        for (int i = 1; i <= N; i++) {
            Y[i] = MAX_L - 1 - Y[i];
        }
        y1 = MAX_L - 1 - y1;
        y2 = MAX_L - 1 - y2;
    }

    std::vector<std::pair<int, int>> vec;

    for (int i = 1; i <= N; i++) {
        if (x1 <= X[i] && X[i] <= x2 && y1 <= Y[i] && Y[i] <= y2) {
            vec.push_back(std::pair<int, int>({X[i], Y[i]}));
        }
    }

    std::sort(vec.begin(), vec.end(),
        [](const std::pair<int, int>& a, const std::pair<int, int> b) { return a.first < b.first; }
    );

    int seq_size = vec.size();

    for (int i = 1; i <= seq_size; i++) {
        seq[i] = vec[i-1].second;
    }

    for (int i = 1; i <= seq_size; i++) {
        dp_lis[i] = MAX_L;
    }
    dp_lis[0] = 0;

    for (int i = 1; i <= seq_size; i++) {
        int lb = 0;
        int ub = seq_size;
        while(lb + 1 < ub) {
            int mid = (lb + ub) / 2;
            if (dp_lis[mid] < seq[i]) {
                lb = mid;
            } else {
                ub = mid;
            }
        }
        dp_lis[ub] = std::min(dp_lis[ub], seq[i]);
    }

    int length = 0;
    for (int i = 1; i <= seq_size; i++) {
        if (dp_lis[i] < MAX_L) {
            length++;
        } else {
            break;
        }
    }

    double PI = acos(-1.0);

    double ret = (x2 - x1 + y2 - y1) * 100.0;

    if (length == std::min(x2 - x1 + 1, y2 - y1 + 1)) {
        ret += (length - 1) * (5.0 * PI - 20.0);
        ret += 10.0 * PI - 20.0;
    } else {
        ret += length * (5.0 * PI - 20.0);
    }

    std::cout << std::setprecision(14) << ret << std::endl;

    return 0;
}

