const ld PI = acosl(-1.0);
const int MX = (int)1e8;

void inv(int &x) {
	x = MX - x;
}

struct ST {
	vector<int> t;
	ST(int n) {
		t.resize(4 * n + 3);
	}
	void ch(int v, int tl, int tr, int pos, int val) {
		if (tl == tr) {
			t[v] = val;
		} else {
			int tm = (tl + tr) >> 1;
			if (pos <= tm) {
				ch(v + v, tl, tm, pos, val);
			} else {
				ch(v + v + 1, tm + 1, tr, pos, val);
			}
			t[v] = max(t[v + v], t[v + v + 1]);
		}
	}
	int gm(int v, int tl, int tr, int l, int r) {
		if (r < tl || l > tr) return 0;
		if (tl >= l && tr <= r) return t[v];
		int tm = (tl + tr) >> 1;
		return max(gm(v + v, tl, tm, l, r), gm(v + v + 1, tm + 1, tr, l, r));
	}
};

const int MAXN = 200 * 1000 + 7;

int pos[MAXN];

bool in(int l, int r, int x) {
	return x >= l && x <= r;
}

