		scanf("%d %d", &pts[i].first, &pts[i].second);
	}
	if (x1 > x2) {
		inv(x1);
		inv(x2);
		for (auto &x : pts) inv(x.first);
	}
	if (y1 > y2) {
		inv(y1);
		inv(y2);
		for (auto &x : pts) inv(x.second);
	}
	vector<pair<int, int> > tmp;
	for (int i = 0; i < n; i++) {
		if (in(x1, x2, pts[i].first) && in(y1, y2, pts[i].second)) {
			tmp.push_back(pts[i]);
		}
	}
	pts = tmp;
	vector<int> xx, yy;
	for (auto &x : pts) {
		xx.push_back(x.first);
		yy.push_back(x.second);
	}
	sort(xx.begin(), xx.end());
	sort(yy.begin(), yy.end());
	int cnt = 0;
	for (auto &p : pts) {
		if (in(x1, x2, p.first) && in(y1, y2, p.second)) {
			int x = lower_bound(xx.begin(), xx.end(), p.first) - xx.begin() + 1;
			int y = lower_bound(yy.begin(), yy.end(), p.second) - yy.begin() + 1;
			pos[x] = y;
