	for (int i = 1; i <= n; i++) {
		if (pos[i] != 0) {
			int cur = t.gm(1, 1, n, 1, pos[i]) + 1;
			ress = max(ress, cur);
			t.ch(1, 1, n, pos[i], cur);
		}
	}
	bool bad = false;;
	if ((int)pts.size() == min(abs(x1 - x2), abs(y1 - y2)) + 1) {
		bad = true;
		sort(pts.begin(), pts.end());
		for (int i = 1; i < (int)pts.size(); i++) {
			if (pts[i].second < pts[i - 1].second) bad = false;
		}
	}
	ld res = abs(x1 - x2) + abs(y1 - y2);
	res *= 100LL;
	ld diff = 20.0 - 5.0 * PI;
	res -= diff * ress;
	if (bad) {
		res += diff;
		res -= 20;
		res += 10.0 * PI;
	}
	cout.precision(20);
	cout << fixed << res << endl;
}

