    if (p.X < min(a.X, b.X)) continue;
    if (p.X > max(a.X, b.X)) continue;
    if (p.Y < min(a.Y, b.Y)) continue;
    if (p.Y > max(a.Y, b.Y)) continue;
    ::p.push_back(p);
  }
}

int max_x, max_y;

void prep() {
  map<int, int> xc;
  {
    bool mrr = a.X > b.X;
    set<int> x;
    x.insert((mrr ? -1 : 1) * a.X);
    x.insert((mrr ? -1 : 1) * b.X);
    for (auto p : ::p) x.insert((mrr ? -1 : 1) * p.X);
    int cp = 0;
    for (int xx : x)
      xc[(mrr ? -1 : 1) * xx] = cp++;
  }

  map<int, int> yc;
  {
    bool mrr = a.Y > b.Y;
    set<int> y;
    y.insert((mrr ? -1 : 1) * a.Y);
    y.insert((mrr ? -1 : 1) * b.Y);
    for (auto p : ::p) y.insert((mrr ? -1 : 1) * p.Y);
    int cp = 0;
    for (int yy : y)
      yc[(mrr ? -1 : 1) * yy] = cp++;
  }

  for (auto& p : ::p) {
    p.X = xc[p.X];
    p.Y = yc[p.Y];
  }

  a.X = xc[a.X];
  b.X = xc[b.X];

  a.Y = yc[a.Y];
  b.Y = yc[b.Y];

  max_x = xc.size();
  max_y = yc.size();
}

const double e1 = 1.1415926535897931;
const double e2 = 0.42920367320510344;

void upd_l(SegmTreeMax& tree, int pos) {
  double x = tree.get(pos, pos);
  tree.set_max(pos + 1, max_y - 1, x);
}

double solve() {
  prep();
  SegmTreeMax tree;
  tree.init(max_y);
  sort(p.begin(), p.end());


  if (p.size() == 0)
    return 0;

  if (p[0].X == 0) {
    tree.set_max(0, p[0].Y - 1, 0);
    tree.set(p[0].Y, e2);
    tree.set_max(p[0].Y + 1, max_y - 1, -e1);
    if (p.size() >= 2 && p[1].X > p[0].X + 1) {
      upd_l(tree, p[0].Y);
    }

    if (p.size() == 1 && b.X > p[0].X) {
      upd_l(tree, p[0].Y);
    }

    p.erase(p.begin());
  } else {
    tree.set_max(0, max_y - 1, 0);
  }

  const int n = p.size();
  for (int i = 0; i < n; ++i) {
    int x = p[i].X;
    int y = p[i].Y;

    {
      double a = tree.get(y, y);
      double b = tree.get(0, y - 1);
      tree.set(y, max(a - e1, b + e2));
      tree.set_max(y + 1, max_y - 1, max(a + e2, b - e1));
    }

    bool xx = (i != (n - 1) && p[i + 1].X > p[i].X + 1);
    bool yy = (i == (n - 1) && b.X >= p[i].X + 1);
    if (xx || yy) {
      upd_l(tree, y);
    }
  }

  return tree.get(b.Y, b.Y);
}

int main() {
  read();
  double add = abs(a.X - b.X) + abs(a.Y - b.Y);
  add *= 100;
  double res = 10 * solve();
  cout << fixed << setprecision(20) << (add - res) << endl;
}

