		E.y -= S.y;
		E.x = -1 * E.x;
		for (auto &c : p){
			c.x -= S.x;
			c.y -= S.y;
			c.x = -1 * c.x;
		}
		S.x = 0, S.y = 0;
	}
	else if (S.x <= E.x && S.y > E.y){
		E.y -= S.y;
		E.x -= S.x;
		E.y = -1 * E.y;
		for (auto &c : p){
			c.x -= S.x;
			c.y -= S.y;
			c.y = -1 * c.y;	
		}
		S.x = S.y = 0;
	}
	else{
		E.y -= S.y;
		E.x -= S.x;
		for (auto &c : p){
			c.x -= S.x;
			c.y -= S.y;
		}
		S.x = S.y = 0;
	}
	if (E.x == 0){
		LD dist = E.y * 100;
		for (auto c : p){
			if (c.y <= E.y){
				dist += (PI * 10) - 20;
				break;
			}
		}
		cout << fixed << setprecision(20) << dist;
		return 0;
	}
	if (E.y == 0){
		LD dist = E.x * 100;
		for (auto c : p){
			if (c.x <= E.x){
				dist += (PI * 10) - 20;
				break;
			}
		}
		cout << fixed << setprecision(20) << dist;
		return 0;
	}
	m[S.x], m[E.x];
	for (auto c : p)
		m[c.x];
	for (auto &c : m){
		c.second = ++cnt;
	}++cnt;
	LD dist = 100.0 * (E.x + E.y);
	if (!p.empty())
	{
		sort(p.begin(), p.end(), cmp());
		for (auto c : p){
			LL q = query(m[c.x]);
			update(m[c.x], q + 1);
		}
		LL fountains = query(cnt);
		if (fountains == min(E.x, E.y) + 1)
		{
			fountains--;
			dist += (10 * PI) - 20;
		}
		while (fountains --){
			dist -= (20.0 - (PI * 5));
		}
	}
	cout << fixed << setprecision(20) << dist;
	return 0;
}

