		for(int i=1;i<=n;++i)a[i]=100000000-a[i];
		Sx=100000000-Sx;Tx=100000000-Tx;}
	if(Sy>Ty){
		for(int i=1;i<=n;++i)b[i]=100000000-b[i];
		Sx=100000000-Sx;Tx=100000000-Tx;}
	std::sort(p+1,p+n+1,cmp);
	for(int i=1;i<=n;++i)if(a[p[i]]>=Sx&&b[p[i]]>=Sy&&a[p[i]]<=Tx&&b[p[i]]<=Ty){
		int k=std::lower_bound(f,f+ans,b[p[i]])-f;
		f[k]=b[p[i]];
		ans=Max(ans,k+1);
	}
	res=100.0*(Tx+Ty-Sx-Sy);
	res+=acos(-1)*5.0*ans-20.0*ans;
	if(Min(Tx-Sx,Ty-Sy)+1==ans)res+=acos(-1)*5;
	printf("%.15lf",res);
	return 0;
}

