vector<pii> ir;
set<int> cc;
map<int,int> lab;
int A[N];

//point SET update, range MAX query
template <class T>
struct segt {
	int N;
	vector<T> t;
	segt(int N):N(N),t(2*N){}

	constexpr static T NONE = numeric_limits<T>::lowest();
	static inline T combine(T a, T b) {return max(a,b);}

	//update point i
	void update(int i, T val) {
		for(t[i+=N] = val;i>1;i>>=1)
			t[i>>1] = combine(t[i],t[i^1]);
	}

	//query range [l,r]
	T query(int l, int r) const {
		T ans = NONE;
		if(r < l) return 0;
		for(l+=N,r+=N+1;l<r;l>>=1,r>>=1) {
			if(l&1) ans = combine(ans,t[l++]);
			if(r&1) ans = combine(ans,t[--r]);
		}
		return ans;
	}
};

segt<int> t(0);

int main() {	
	scanf("%d%d%d%d",&X1,&Y1,&X2,&Y2);
	scanf("%d",&n);
	for(int i = 0; i < n; ++i)
		scanf("%d%d",&P[i].fi,&P[i].se);
	if(X1 > X2) {
		X1 = -X1, X2 = -X2;
		for(pii &p : P)
			p.fi = -p.fi;
	}
	if(Y1 > Y2) {
		Y1 = -Y1, Y2 = -Y2;
		for(pii &p : P)
			p.se = -p.se;
	}
	for(pii &p : P)
		if(X1 <= p.fi && p.fi <= X2 && Y1 <= p.se && p.se <= Y2) {
			ir.pb(p);
			cc.insert(p.se);
		}
	int ctr = 0;
	for(int a : cc)
		lab[a] = ctr++;
	sort(ir.begin(),ir.end());
	n = ir.size();
	t = segt<int>(n);
	int ans = 0;
	for(int i = 0; i < n; ++i) {
		int a = lab[ir[i].se];
		int bst = 1+t.query(0,a-1);
		t.update(a,bst-t.query(a,a));
		ans = max(ans,bst);
	}
	double pi = 2*acos(0);
	double ra = double(Y2-Y1 + X2-X1) * 100.0;
	if(ans == Y2-Y1+1 || ans == X2-X1+1) {
		ra += 10*pi-20;
		--ans;
	}
	ra += (5*pi-20) * ans;
	printf("%.12lf\n",ra);
}

