			s=0;
			for (t=k-1;t;t^=t&-t) s=max(s,c[t]);
			ans=max(ans,++s);
			for (t=k;t<=len;t+=t&-t) c[t]=max(c[t],s);
		}
		printf("%.15Lf\n",100.0*(x2-x1+y2-y1)-ans*(20-5*pi));
