int LIS() {
    if((int)A.size() == 0)
        return 0;

    dp[0] = A[0].second;
    int C = 1;

    for(int i = 1;i < (int)A.size();i++) {
        if(A[i].second > dp[C-1]) {
            dp[C++] = A[i].second;
            continue;
        }

        dp[lower_bound(dp, dp+C, A[i].second)-dp] = A[i].second;
    }

    return C;
}

