int calc(vector<int> v) {
    vector<int> best(szof(v) + 1, INF);
    best[0] = -INF;

    int ret = 0;
    for (int i = 0; i < szof(v); ++i) {
        int l = 0, r = szof(v) + 1;
        while (r - l > 1) {
            int mid = (l + r) / 2;
            if (best[mid] < v[i]) {
                l = mid;
            } else {
                r = mid;
            }
        }
        best[l + 1] = v[i];
        ret = max(ret, l + 1);
    }
    return ret;
}

