inline int BS(ll k){
	int l=0,r=cnt,mid,ans;
	while(l<=r){
		mid=l+r>>1;
		if(tmp[mid]>k) ans=mid, l=mid+1;
		else r=mid-1;
	}
	return ans;
}

int main(){
