#define y1 dfljk
#define fi first
#define se second

const double C = 5.0 * acos(-1.0);

int n, x1, y1, x2, y2;
pair<int, int> a[200000];
map<pair<int, int>, int> pos;
int dp[200000];
int opt;

int t[2 * 200000];

void upd(int v, int x) {
	t[v += n] = x;
	for(v >>= 1; v; v >>= 1) t[v] = max(t[v * 2], t[v * 2 + 1]);
}

int get(int l, int r) {
	int ret = 0;
	for(l += n, r += n; l <= r; l = (l + 1) >> 1, r = (r - 1) >> 1) {
		if(l & 1) ret = max(ret, t[l]);
		if(!(r & 1)) ret = max(ret, t[r]);
	}
	return ret;
}

int main() {
	ios::sync_with_stdio(0), cin.tie(0), cout.tie(0); cout.precision(15);
	cin >> x1 >> y1 >> x2 >> y2 >> n;
	if(x1 > x2) swap(x1, x2), swap(y1, y2);
	for(int i = 0; i < n; i++) {
		cin >> a[i].fi >> a[i].se;
		if(a[i].fi < x1 || a[i].fi > x2 || a[i].se < min(y1, y2) || a[i].se > max(y1, y2)) n--, i--;
	}
	//if(x1 == x2) return cout << fixed << 100LL * abs(y1 - y2) + (n != 0 ? 2 * C - 20 : 0), 0;
	//if(y1 == y2) return cout << fixed << 100LL * abs(x1 - x2) + (n != 0 ? 2 * C - 20 : 0), 0;
	if(n != 0) {
		sort(a, a + n);
		for(int i = 0; i < n; i++) pos[a[i]] = i;
		sort(a, a + n, [](pair<int, int> a, pair<int, int> b){ if(y1 < y2) return a.se < b.se; else return a.se > b.se; });
		for(int i = 0; i < n; i++) {
			int j = pos[a[i]];
			dp[j] = 1 + get(0, j);
			upd(j, dp[j]);
			opt = max(opt, dp[j]);
		}
	}
	cout << fixed << 100LL * (x2 - x1 + abs(y1 - y2)) + opt * (C - 20) + (opt == min(abs(x1 - x2), abs(y1 - y2)) + 1 ? 2 * C - 20 : 0);
}

