const int maxn = 200010;
struct Segment {
  int n, t[maxn * 2];
  void build() {
    for (int i = n - 1; i; --i)
      t[i] = t[i<<1] + t[i<<1|1];
  }
  void modify(int p, int v) {
    p += n;
    t[p] = max(t[p], v);
    for (; p > 1; p >>= 1)
      t[p >> 1] = max(t[p], t[p ^ 1]);
  }
  int query(int l, int r) {
    r += 1;
    int sum = 0;
    for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
      if (l&1) sum = max(sum, t[l++]);
      if (r&1) sum = max(sum, t[--r]);
    }
    return sum;
  }
} seg;

vector<int> a;

int solve() {
  vector<int> b = a;
  sort(ALL(b));
  b.erase(unique(ALL(b)), b.end());
  seg.n = b.size() + 5;
  int ret = 0;
  for (int x : a) {
    x = lower_bound(ALL(b), x) - b.begin();
    int t = seg.query(0, x) + 1;
    ret = max(ret, t);
    seg.modify(x, t);
  }
  return ret;
}

