void calc(int rq, ll&b, ll&s)
{
	ll p=4292036732051033807LL;
	ll m=1000000000000000000LL;

	b=0;
	s=0;
	for(int i=0;i<rq;i++)
	{
		s+=p;
		b+=s/m;
		s%=m;
	}

	if(s)
	{
		b++;
		s=m-s;
	}
}


