	}

	//get good fountains
	for (int i = 0; i < N; i++){
		if (arr[i].first < xone || arr[i].first > xtwo) continue;
		if (arr[i].second < yone || arr[i].second > ytwo) continue;
		vx.push_back(arr[i]);
		vy.push_back(make_pair(arr[i].second, arr[i].first));
	}
	sort(vx.begin(), vx.end()); //sort by x, y is the lis
	sort(vy.begin(), vy.end()); //sort by y, x is the lis
	//run lis
	memset(h, -1, sizeof(h));
	l = 0;
	for (int i = 0; i < vx.size(); i++) {
	    ll p = lower_bound(h, h+l, vx[i].second)-h;
	    h[p] = vx[i].second;
	    l = max(p+1, l);
	}
	long double answer = (long double)((long double)100.0)*(xtwo - xone + ytwo - yone) - ((long double)l)*((long double)20.0) + ((long double)l)*(pii*((long double)5.0));
	long double subanswer = (long double)((long double)100.0)*(xtwo - xone + ytwo - yone) - ((long double)(l - 1))*((long double)20.0) + ((long double)(l - 1))*(pii*((long double)5.0));

	memset(h, -1, sizeof(h));
	l = 0;
	for (int i = 0; i < vy.size(); i++) {
	    ll p = lower_bound(h, h+l, vy[i].second)-h;
	    h[p] = vy[i].second;
	    l = max(p+1, l);
	}

	answer = min(answer, (long double)((long double)100.0)*(xtwo - xone + ytwo - yone) - ((long double)l)*((long double)20.0) + ((long double)l)*(pii*((long double)5.0)));
	subanswer = min(subanswer, (long double)((long double)100.0)*(xtwo - xone + ytwo - yone) - ((long double)(l - 1))*((long double)20.0) + ((long double)(l - 1))*(pii*((long double)5.0)));

	//check if got special case, then need + 1/2*pi*r
	if ((long long)vx.size() == min(xtwo - xone, ytwo - yone) + 1){
		bool ascending = true;
		for (int i = 0; i < N - 1; i++){
			if (vx[i].second >= vx[i + 1].second){
				ascending = false;
				break;
			}
		}
		if (ascending){
			answer = subanswer - ((long double)20.0) + ((long double)10.0)*pii;
			//answer += (pii*5.0);
		}
	}
	printf("%.20Lf\n", answer);


}

