	{
		return x<other.x;
	}
}a[200005];
int f[200005],t[1000005],tmp[1000005];
int x1,x2,y1,y2,n,tot;
double ans;
void add(int p,int l,int r,int now,int num)
{
	t[now]=max(t[now],num);
	if(l==r) return;
	int mid=(l+r)>>1;
	if(p<=mid) add(p,l,mid,now<<1,num);
	else add(p,mid+1,r,now<<1|1,num);
}
int ask(int L,int R,int l,int r,int now)
{
	if(L>R) return 0;
	if(L<=l&&r<=R) return t[now];
	int mid=(l+r)>>1,ans=0;
	if(L<=mid) ans=ask(L,R,l,mid,now<<1);
	if(R>mid) ans=max(ans,ask(L,R,mid+1,r,now<<1|1));
	return ans;
}
int main()
{
	scanf("%d%d%d%d%d",&x1,&y1,&x2,&y2,&n);
	for(int i=1;i<=n;i++)
	  scanf("%d%d",&a[i].x,&a[i].y),tmp[++tot]=a[i].y;
	tmp[++tot]=y1,tmp[++tot]=y2;
	if(x1==x2)
	{
		for(int i=1;i<=n;i++)
		  if(a[i].x==x1)
