			else return printf("%.15lf",(double)100.0*abs(y1-y2)-(double)20.0+10.0*pi),0;
		  }
		return printf("%.15lf",(double)100.0*abs(y1-y2)),0;
	}
	if(y1==y2)
	{
		for(int i=1;i<=n;i++)
		  if(a[i].y==y1)
		  {
		  	if(a[i].x<min(x1,x2)||a[i].x>max(x1,x2)) return printf("%.15lf",(double)100.0*abs(x1-x2)),0;
		  	else return printf("%.15lf",(double)100.0*abs(x1-x2)-(double)20.0+10.0*pi),0;
		  }
		return printf("%.15lf",(double)100.0*abs(x1-x2)),0;
	}
	sort(tmp+1,tmp+tot+1);
	tot=unique(tmp+1,tmp+tot+1)-tmp-1;
	for(int i=1;i<=n;i++)
	  a[i].y=lower_bound(tmp+1,tmp+tot+1,a[i].y)-tmp;
	sort(a+1,a+n+1);
	ans=1.0*abs(x1-x2)+1.0*abs(y1-y2);
	ans*=100.0;
	y1=lower_bound(tmp+1,tmp+tot+1,y1)-tmp;
	y2=lower_bound(tmp+1,tmp+tot+1,y2)-tmp;
	int num=0,l=n+1,r=0;
	for(int i=1;i<=n;i++)
		if(a[i].x>=min(x1,x2)){l=i;break;}
	for(int i=n;i;i--)
		if(a[i].x<=max(x1,x2)){r=i;break;}
	for(int i=l;i<=r;i++)
	  if(a[i].y<min(y1,y2)||a[i].y>max(y1,y2)) continue;
	  else a[i].useful=1;
	if(x1>x2) swap(x1,x2),swap(y1,y2);
	int Case;
	if(y1<y2) Case=1;else Case=0;
	for(int i=l;i<=r;i++)
	  if(a[i].useful)
	  {
		f[i]=1;
		int tmp;
		if(Case) tmp=ask(1,a[i].y-1,1,tot,1);
		else tmp=ask(a[i].y+1,tot,1,tot,1);
		f[i]=max(f[i],tmp+1);
		add(a[i].y,1,tot,1,f[i]);
	  }
	for(int i=l;i<=r;i++)
	  num=max(num,f[i]);
	ans-=(double)num*(20.0-5.0*pi);
	printf("%.15lf",ans);
	return 0;
}

