void update(int idx , int val){
	while(idx <= n){
		bit[idx] = max(bit[idx] , val);
		idx += idx & -idx;
	}
}
int query(int idx){
	int res = 0;
	while(idx){
		res = max(res , bit[idx]);
		idx -= idx & -idx;
	}
	return res;
}
int main(){
