typedef pair<int, int> pii;
typedef pair<double, int> pdi;
typedef pair<double,double> pdd;
const int MOD = 1000000007;
const int oo = 1000000001;
const int N = 200011;

int n;

double sx , sy , ex , ey,X[N],Y[N];

double dx[4] = {-1,0,1,0};
double dy[4] = {0,-1,0,1};
vector< pdi > nx,ny;

vector< pdi > g[N];


int fndNxt(vector<pdi> &ar,double me){
	return (*upper_bound(ar.begin(),ar.end(),make_pair(me,oo))).second;
}
int fndPrev(vector<pdi> &ar,double me){
	return (*--lower_bound(ar.begin(),ar.end(),make_pair(me,-1))).second;
}
struct state{
	double posX,posY,cost;
	int dir;
	state(double _posX,double _posY , double _cost,int _dir){
		posX = _posX;
		posY = _posY;
		cost = _cost;
		dir = _dir;
	};
	bool operator<(const state &rhs) const{
		if(posX == rhs.posX){
			return posY < rhs.posY;
		}
		if(dir == rhs.dir)
			return posX < rhs.posX;
		return dir < rhs.dir;
	}
};
map< state, int > vis;
map<state, double> cost;

double go(double x1 , double y1 , double x2 , double y2){
	return (abs(x1-x2)+abs(y2-y1))*100.0;;
}
const double rb3 = acos(-1) * 2 * 10.0 * 0.25;

int main() {
	//freopen("input.txt", "r", stdin);
	scanf("%lf%lf%lf%lf",&sx,&sy,&ex,&ey);
	scanf("%d",&n);

	for (int i = 1; i <= n; ++i){
		scanf("%lf%lf",&X[i],&Y[i]);
		nx.pb(mp(X[i],i));
		ny.pb(mp(Y[i],i));
	}
	nx.pb(mp(-1,-1));
	ny.pb(mp(-1,-1));
	nx.pb(mp(1e9,-1));
	ny.pb(mp(1e9,-1));
	nx.pb(mp(ex,n+1));
	ny.pb(mp(ey,n+1));
	X[n+1] = ex;
	Y[n+1] = ey;
	sort(nx.begin(),nx.end());
	sort(ny.begin(),ny.end());
	priority_queue< pair<double,state> > q;
	q.push(make_pair(0,state(sx,sy,0,4)));
	double mn = go(sx,sy,ex,sy);
	while(q.size()){
		pair<double,state> cur = q.top();
		cur.first = -cur.first;
		q.pop();
		if(cur.second.posX == ex && cur.second.posY == ey){
			mn = cur.second.cost;
			break;
		}
		if(vis.find(cur.second) != vis.end())continue;
		vis[cur.second] = 1;
		if(cur.second.dir != 4){
			double newCost = rb3 + cur.second.cost;
			state nw = state(cur.second.posX,cur.second.posY,newCost,(cur.second.dir+1)%4);
			if(cur.second.dir == 0){
				nw.posX += 0.1;
				nw.posY -= 0.1;
			}else if(cur.second.dir == 1){
				nw.posX += 0.1;
				nw.posY += 0.1;
			}else if(cur.second.dir == 2){
				nw.posX -= 0.1;
				nw.posY += 0.1;
			}else if(cur.second.dir == 3){
				nw.posX -= 0.1;
				nw.posY -= 0.1;
			}
			if(cost.find(nw) == cost.end())
				cost[nw] = 1e18;
			if(nw.cost < cost[nw]){
				cost[nw] = nw.cost;
				q.push(mp(-nw.cost,nw));
			}
		}
		for(int u = 0 ; u < 4 ; u++){
			int nxtIdx = -1;
			if(abs(dx[u]) > 0.5000){
				nxtIdx = dx[u] == -1 ? fndNxt(nx,cur.second.posX) : fndPrev(nx,cur.second.posX);
			}else{
				nxtIdx = dy[u] == -1 ? fndNxt(ny,cur.second.posY) : fndPrev(ny,cur.second.posY);
			}
			if(nxtIdx == -1)continue;

			double npx = X[nxtIdx] + (nxtIdx != n+1)* dx[u] * 0.1;
			double npy = Y[nxtIdx] + (nxtIdx != n+1)* dy[u] * 0.1;
			state newS = state(npx,npy,go(cur.second.posX,cur.second.posY,npx,npy)+cur.second.cost,u);
			if(cost.find(newS) == cost.end())
				cost[newS] = 1e18;
			if(newS.cost < cost[newS]){
				cost[newS] = newS.cost;
				q.push(mp(-newS.cost,newS));
			}
		}
	}
	printf("%.12lf\n",mn );
	return 0;
}

#include<iostream>
