#define P 3.14159265358979323846
#define lol(i,n) for(int i=0;i<n;i++)
#define mod 1000000007
typedef long long ll;
using namespace std;
#define N 200010
int sx,sy,gx,gy,n;
pair<int,int> c[N];

vector<int> lis;

int main(){
  cin>>sx>>sy>>gx>>gy;
  bool flipx=false,flipy=false;
  if(sx>gx)flipx=true,sx=-sx,gx=-gx;
  if(sy>gy)flipy=true,sy=-sy,gy=-gy;
  cin>>n;
  lol(i,n){
    int x,y;cin>>x>>y;
    if(flipx)x=-x;
    if(flipy)y=-y;
    c[i]=make_pair(x,y);
  }
  sort(c,c+n);

  int befx=mod,befy=mod;
  int firstx=mod,firsty,lastx,lasty;
  bool corner=true;

  lol(i,n){
    int x=c[i].first,y=c[i].second;
    if(x<sx||gx<x)continue;
    if(y<sy||gy<y)continue;

    //V-LIS-V
    vector<int>::iterator it;
    it=lower_bound(lis.begin(),lis.end(),y);
    if(it==lis.end())lis.push_back(y);
    else *it=y;
    //A-LIS-A

    //V-corner-V
    if(befx==mod&&befy==mod){
      firstx=x,firsty=y;
    }
    else if(!(befx+1==x&&befy+1==y)){
      corner=false;
    }
    befx=x,befy=y;
    lastx=x,lasty=y;
    //A-corder-A
  }

  if(!((firstx==sx&&lastx==gx)||(firsty==sy&&lasty==gy))){
    corner=false;
  }

  double ans=(gx-sx+gy-sy)*(ll)100;
  ans-=(double)lis.size()*(20-5.0*P);
  if(corner)ans+=5.0*P;

  //cout<<lis.size()<<" "<<corner<<endl;
  cout<<fixed<<setprecision(15)<<ans<<endl;
  return 0;
}

