    swap(ys[0], ys[1]);
  }

  if (ys[1] < ys[0]) {
    need_reverse = true;
    ys[0] = -ys[0];
    ys[1] = -ys[1];
  }
  xs[1] -= xs[0];
  ys[1] -= ys[0];
  if (ys[1] == 0) y_accord = true;
  if (xs[1] == 0) x_accord = true;
  ps.emplace_back(Pair(ys[1], xs[1]));
  comp.emplace_back(xs[1]);

  scanf("%d", &N);
  int x_cnt = 0;
  bool found = false;
  for (int i=0; i<N; i++) {
    LLI x, y;
    scanf("%lld%lld", &x, &y);
    if (need_reverse) y = -y;
    x -= xs[0];
    y -= ys[0]; 
    if (x == xs[1]) x_cnt++;
    if (x == 0 && x_accord) {
      ans = ys[1]*100+(PI-2)*10;
      found = true;
    }

    if (y == 0 && y_accord) {
      ans = xs[1]*100+(PI-2)*10;
      found = true;
    }
    comp.emplace_back(x);
    ps.emplace_back(Pair(y, x));
  }

  if (found) {
    printf("%.17f\n", ans);
    return 0; 
  }

  sort(comp.begin(), comp.end());
  comp.erase(unique(comp.begin(), comp.end()), comp.end());
  sort(ps.begin(), ps.end());//, cmp);
  size = 1;
  while(size < (int)comp.size()) size*=2;

  int cnt = 0;
  for (auto &p : ps) {
    LLI x = p.second;
    LLI y = p.first;
    if (x < 0) continue;
    int idx = lower_bound(comp.begin(), comp.end(), x) - comp.begin();
    assert (comp[idx] == x);
    if (x == xs[1] && y == ys[1]) {
      int t = getmax(0, idx+1, 0, 0, size);
      //printf("%lld %lld %d\n", x, y, t);
      ans = min(ans, (ys[1]+xs[1])*100 - (2-PI/2)*10*t);
    } else {
      int t = getmax(0, idx+1, 0, 0, size);
      //printf("%lld %lld %d\n", x, y, t);
      update_if(idx, t+1);
      /*if (y == ys[1]) {
        ans = min(ans, (ys[1]+xs[1])*100 - (2-PI/2)*10*t + (PI-2)*10*cnt);
        cnt++;
      }*/

      /*if (x == xs[1]) {
        ans = min(ans, (ys[1]+xs[1])*100 - (2-PI/2)*10*t + (PI-2)*10*x_cnt);
        x_cnt--;
      }*/
    }
  }
  printf("%.17f\n", ans);
}

