bool cmp(int i,int j){
	return x[i]<x[j]||(x[i]==x[j]&&y[i]>y[j]);
}

void add(int x,int y){
	for(;x<=n;x+=x&-x)c[x]=max(c[x],y);
}

int query(int x){
	int ans=-MAX;
	for(;x;x-=x&-x)ans=max(ans,c[x]);
	return ans;
}

void Work(){
	if(X1==X2){
		bool ok=0;
		REP(i,1,n)if(x[i]==X1&&Y1<y[i]&&y[i]<Y2)ok=1;
