struct BIT
{
  vi arr;
  void sz(int x) 
  {
    arr.resize(x+1);
    REP(i,x+1) arr[i] = 0;
  }
  void update(int x,int y)
  {
    int m = SIZE(arr);
    while (x < m)
    {
      MAX(arr[x],y);
      x += (x & -x);
    }
  }
  int query(int x)
  {
    int ret = 0;
    while (x > 0)
    {
      MAX(ret,arr[x]);
      x -= (x & -x);
    }
    return ret;
  }
};

