using namespace std;
typedef pair<int,int> pii;

const int MAXN=2e5+2+5;
const int MAXX=1e8+1+8;
const long double PI = 3.14159265358979323846264338327950288419716939937510582097494459230781640628620899L;
const long double GAIN=20-2*PI*10/4;
const long double LOSS=2*PI*10/2-20;

int x1,y1,x2,y2;
int N;
int X[MAXN], Y[MAXN];

map<int,int> ranky;
int st[2*MAXN];
void update(int i, int v) {
        i = ranky[i];
        //cout << "Update " << i << " " << v << "\n";
        for (st[i += N+2] = v; i>1; i>>=1)
                st[i>>1] = max(st[i],st[i^1]);
}

int query(int a, int b) {
        if (a > b) swap(a,b);
        a = ranky[a];
        b = ranky[b];
        b++;
        //cout << "Query " << a << " " << b << "\n";
        int res=0;
        for (a+=N+2, b+=N+2; a < b; a>>=1, b>>=1) {
                if (a&1) res = max(res,st[a++]);
                if (b&1) res = max(res,st[--b]);
        }
        return res;
}

void set_rank() {
        vector<int> yf;
        for (int i=0; i<N; ++i)
                yf.push_back(Y[i]);
        yf.push_back(y1);
        yf.push_back(y2);
        sort(yf.begin(),yf.end());
        for (int i=0; i<yf.size(); ++i)
                ranky[yf[i]] = i;
}

int mxtrn() {
        if (x1 > x2) {
                swap(x1,x2);
                swap(y1,y2);
        }

        set_rank();

        vector<pii> xf;
        for (int i=0; i<N; i++)
                xf.push_back(pii(X[i],i));

        sort(xf.begin(), xf.end());

        int i=0;
        while (i < N && xf[i].first < x1)
                ++i;

        //cout << "y1 y2 " << rank[y1] << " " << rank[y2] << "\n";
        for (; i < N && xf[i].first < x2; ++i) {
                int cur = xf[i].second;
                //cout << "Processing fountain " << cur << " at " << X[cur] << ", " << Y[cur] << "\n";
                //cout << "\tRank is " << rank[Y[cur]] << "\n";
                int k = 1+query(y1,Y[cur]);
                //cout << "\tGets value " << k << "\n";
                update(Y[cur],k);
        }

        return query(y1,y2);
}

int main()
{
        cin >> x1 >> y1 >> x2 >> y2;
        cin >> N;
        for (int i=0; i<N; ++i)
                cin >> X[i] >> Y[i];

        cout << setprecision(20) << fixed;
        if (x1 == x2) {
                for (int i=0; i<N; ++i) {
                        if (X[i] == x1 && Y[i] > min(y1,y2) && Y[i] < max(y1,y2)) {
                                cout << 100*abs(y1-y2) + LOSS << "\n";
                                return 0;
                        }
                }
                cout << 100*abs(y1-y2) << "\n";
        } else if (y1 == y2) {
                for (int i=0; i<N; ++i) {
                        if (Y[i] == y1 && X[i] > min(x1,x2) && X[i] < max(x1,x2)) {
                                cout << 100*abs(x1-x2) + LOSS << "\n";
                                return 0;
                        }
                }
                cout << 100*abs(x1-x2) << "\n";
        } else {
                cout << 100*abs(x1-x2) + 100*abs(y1-y2) - mxtrn()*GAIN << "\n";
        }
}

