int lcs(const vector<pii> &pts){
  int n=pts.size();
  vi m(n+1);
  int maxl=0;
  rep(i,n){
    int p=0;
    int f=maxl+1;
    while(f-p>1){
      int x=(f+p)/2;
      if(pts[m[x]].second<pts[i].second){
	p=x;
      }else{
	f=x;
      }
    }
    m[p+1]=i;
    maxl=max(maxl,p+1);
  }
  return maxl;
}

double f(int goalx,int goaly,vector<pii> pts){
