  sort(pts.begin(),pts.end());
  int lc=lcs(pts);
  double ans=1e30;
  int lim=min(goalx,goaly)+1;
  assert((int)pts.size()<=lim);
  rep(i,lc+1){
    if((int)pts.size()>=lim&&i==0)continue;
    ans=min(ans,base+(5*pi-20)*i+(i==lim?5*pi:0));
  }
  return ans;
}


