}

void change(int it, int l, int r, int pos, int x) {
	if (l == r) {
		t[it] = x;
	} else {
		int m = (l + r) >> 1;

		if (pos <= m) {
			change(2 * it, l, m, pos, x);
		} else {
			change(2 * it + 1, m + 1, r, pos, x);
		}

		t[it] = max(t[it], x);
	}
}

int go() {
	vector <int> c;

	for (int i = 0; i < (int)g.size(); i++) {
		c.push_back(g[i].second);
	}

	sort(c.begin(), c.end());

	for (int i = 0; i < (int)g.size(); i++) {
		g[i].second = lower_bound(c.begin(), c.end(), g[i].second) - c.begin();
	}

	int ans = 0;

	for (int i = (int)g.size() - 1; i >= 0; i--) {
		int res = 1 + go(1, 0, maxn - 1, g[i].second, maxn - 1);
		change(1, 0, maxn - 1, g[i].second, res);
		ans = max(ans, res);
	}

	return ans;
}

