map<int, int> compress(vector<int> &x) {
    map<int,int> zip;
    sort(x.begin(), x.end());
    x.erase(unique(x.begin(),x.end()),x.end());
    for(int i = 0; i < x.size(); i++){
        zip[x[i]] = i;
    }
    return zip;
}


class Solver {
  public:
    double solve2(int sx, int ex, P s, P e, vector<P> &S, int y_size) {
        RangeMaximumQuery<ll, 0LL> query(y_size, 0LL);
        for(int i = S.size() - 1; i >= 0; i--) {
            if(S[i].x > e.x) continue;
            if(S[i].x < s.x) break;
            if(s.y <= S[i].y and S[i].y <= e.y) {
                ll v = query.query(S[i].y, y_size);
                query.update(S[i].y, v + 1);
            }
        }
        ll num = query.query(s.y, y_size);
        return num;
    }

    bool solve() {
        P s, e; cin >> s >> e;
        P s_org = s, e_org = e;
        if(s.x > e.x) swap(s, e);
        bool reverse_y = e.y < s.y;
        if(reverse_y) {
            s.y *= -1;
            e.y *= -1;
        }
        ll N; cin >> N;
        vector<int> ys, xs;
        ys.reserve(N + 2);
        ys.push_back(s.y);
        ys.push_back(e.y);
        vector<P> S;
        S.reserve(N);
        bool xs_exist= false, ys_exist = false;
        bool xe_exist= false, ye_exist = false;
        rep(i, N) {
            P ss; cin >> ss;
            if(reverse_y) ss.y *= -1;
            if(s.x <= ss.x and ss.x <= e.x and s.y <= ss.y and ss.y <= e.y) {                
                ys.push_back(ss.y);
                S.push_back(ss);
                xs_exist |= ss.x == s.x;
                ys_exist |= ss.y == s.y;
                xe_exist |= ss.x == e.x;
                ye_exist |= ss.y == e.y;                
            }
        }
        double ans = e.x - s.x + e.y - s.y;
        ans *= 100;
        map<int, int> map_y = compress(ys);
        auto map = [&] (P &a) { a.y = map_y[a.y]; };
        map(s); map(e);
        rep(i, S.size()) map(S[i]);

        vector<P> Sx = S;
        sort(all(Sx), [](P &a, P &b) { return a.x < b.x; });
        //debug(Sx);
        int num = solve2(s.x, e.x, s, e, Sx, map_y.size());
        //debug(num);
        const double half_round = 2 * M_PI * 10 / 2.0 - 20.0;
        if(s.x == e.x and xs_exist) ans += half_round;
        else if(s.y == e.y and ys_exist) ans += half_round;
        else {
            if(xs_exist and xe_exist and num == e_org.x - s_org.x + 1) {
                debug("foo");
                ans += 2 * M_PI * 10.0 / 2.0 - 20.0;
                num--;
            }
            else if(ys_exist and ye_exist and num == e_org.y - s_org.y + 1) {
                debug("bar");
                ans += 2 * M_PI * 10.0 / 2.0 - 20.0;
                num--;
            }
            ans -= num * 20.0;
            ans += 2 * M_PI * 10.0 / 4.0 * num;
        }
        printf("%.10lf\n", ans);
        return 0;
    }
};

