struct Seg {
    int N;
    int data[800000];

    Seg(int n) {
        N = 1;
        while (N < n)N *= 2;
        memset(data, 0, sizeof(data));
        data[0] = 0;
    }

    //[a,b)->x
    void query(int k, int l, int r, int a, int b, int x) {
        //cerr << "called" << endl;
        if (r <= a || b <= l)return;
        if (a <= l && r <= b) {
            data[k] = x;
            return;
        }
        data[k] = -1;
        int m = (l + r) / 2;
        query(2 * k + 1, l, m, a, b, x);
        query(2 * k + 2, m, r, a, b, x);
    }

    void query(int a, int b, int x) {
        query(0, 0, N, a, b, x);
    }

    int val(int i) {
        i = i + N - 1;
        int res = data[i];
        while (i) {
            i = (i - 1) / 2;
            if (data[i] != -1)res = data[i];
        }
        return res;
    }
};

