        }
        output(ans, 16);
        return 0;
    }

    vector<ll> A;
    for(auto p: R){
        if((p.first - S.first) * (p.first - G.first) <= 0 && (p.second - S.second) * (p.second - G.second) <= 0)
        A.pb(p.second);
    }


    vector<ll> L;
    if(A.size() > 0){
        LIS lis = LIS(A);
        L = lis.calc();
    }
    double ans = 100.0 * (abs(S.first - G.first) + abs(S.second - G.second));
    ans += (pi * 5.0 - 20.0) * L.size();
    output(ans, 16);


