{
	return 100.0 * line + (5.0 * M_PI - 20.0) * qua + (10.0 * M_PI - 20.0) * hal;
}

void solve()
{
	sort(s + 1, s + n + 1);
	for(int i = 1; i <= n; i++)
	{
