    SegTree(const vector<int>& v) {
        size = 1;
        while (size < v.size()) size <<= 1;
        seg.resize(2 * size);
        for (int i = 0; i < v.size(); i++) {
            seg[i + size] = v[i];
        }
        for (int i = size - 1; i > 0; i--) {
            seg[i] = max(seg[2 * i], seg[2 * i + 1]);
        }
    }

    SegTree(int n) : SegTree(vector<int>(n)) {}

    void update(int k, int x) {
        k += size;
        seg[k] += x;
        k /= 2;
        for (; k > 0; k /= 2) {
            seg[k] = max(seg[2 * k], seg[2 * k + 1]);
        }
    }

    int query(int a, int b, int k, int l, int r) {
        if (b <= l || r <= a) return 0;
        if (a <= l && r <= b) return seg[k];
        int x = query(a,b,2 * k,l,(l + r) / 2);
        int y = query(a,b,2 * k + 1,(l + r) / 2,r);
        return max(x,y);
    }

    int query(int a, int b) {
        return query(a,b,1,0,size);
    }
};

