const int MX = (int)1e8 + 10;

signed main() {

    SS(int, x1, y1, x2, y2);
    SS(int, N);

    bool rev_x = x1 > x2;
    bool rev_y = y1 > y2;

    if (rev_x) { x1 = MX - x1; x2 = MX - x2; }
    if (rev_y) { y1 = MX - y1; y2 = MX - y2; }

    vector<pair<int, int>> coor;

    auto inside = [&](int x, int y) -> bool {
        return x1 <= x and x <= x2 and y1 <= y and y <= y2;
    };

    REP(i, N) {
        SS(int, x, y);
        if (rev_x) x = MX - x;
        if (rev_y) y = MX - y;
        if (not inside(x, y)) continue;
        coor.emplace_back(x, y);
    }

    double res = double(x2 - x1 + y2 - y1) * 100;

    int sz = coor.size();
    if (sz == 0) return print(res);
    if (x1 == x2 or y1 == y2) {
        return print(res + double(10 * PI - 20) * sz);
    }

    // compress
    vector<int> x_com, y_com;
    for (auto& e: coor) {
        x_com.emplace_back(e.fi);
        y_com.emplace_back(e.se);
    }
    auto x_aft = compress(x_com);
    auto y_aft = compress(y_com);
    REP(i, sz) coor[i].fi = x_aft[i];
    REP(i, sz) coor[i].se = y_aft[i];
    debug(coor);

    auto solve = [&](vector<pair<int, int>> &v) -> int {
        // secondのLISを考える
        SegmentTree<int> dp(sz, [](int a, int b){ return max(a, b); }, 0);
        stack<pair<int, int>> lazy;     // [idx, val]
        int mx = 0;
        REP(i, sz) {
            int x, y;
            tie(x, y) = v[i];
            int cand1 = dp.query(0, y) + 1; // 同列からの遷移なし
            int cand2 = max(cand1, mx + 1); // 同列からの遷移あり
            chmax(mx, cand1);
            lazy.emplace(y, cand2);
            if (i == sz - 1 or x != v[i + 1].fi) {
                while (not lazy.empty()) {
                    int idx, val;
                    tie(idx, val) = lazy.top(); lazy.pop();
                    dp.update(idx, val);
                    mx = 0;
                }
            }
        }
        return dp.query(0, sz);
    };

    int mx = 0;

    sort(coor.begin(), coor.end());
    chmax(mx, solve(coor));

    for (auto& e: coor) swap(e.fi, e.se);
    sort(coor.begin(), coor.end());
    chmax(mx, solve(coor));

    res -= double(20 - 5 * PI) * mx;

    print(res);

}

