		if(a[i].fi < x1 || a[i].fi > x2 || a[i].se < min(y1, y2) || a[i].se > max(y1, y2)) n--, i--;
	}
	if(x1 == x2) return cout << fixed << 100LL * abs(y1 - y2) + (n != 0 ? 2 * C - 20 : 0), 0;
	if(y1 == y2) return cout << fixed << 100LL * abs(x1 - x2) + (n != 0 ? 2 * C - 20 : 0), 0;
	if(abs(y1 - y2) == 1 && x1 + 1 == x2) {
		return cout << fixed << 200 + (n != 0 ? C - 20 : 0), 0;
	}
	if(abs(y1 - y2) == 1 && n == 2) {
		if(y1 < y2) {
			if(a[0].se > a[1].se) swap(a[0], a[1]);
		} else {
			if(a[0].se < a[1].se) swap(a[0], a[1]);
		}
		if(a[0].fi < a[1].fi) return cout << fixed << 100LL * (x2 - x1 + 1) - 40 + 3 * C, 0;
		else if(a[0].fi == a[1].fi) return cout << fixed << 100LL * (x2 - x1 + 1) - 40 + 2 * C, 0;
		else return cout << fixed << 100LL * (x2 - x1 + 1) - 20 + C, 0;
	}
	if(x1 + 1 == x2 && n == 2) {
		if(a[0].fi > a[1].fi) swap(a[0], a[1]);
		if(y1 < y2) {
			if(a[0].se < a[1].se) return cout << fixed << 100LL * (abs(y1 - y2) + 1) - 40 + 3 * C, 0;
			else if(a[0].se == a[1].se) return cout << fixed << 100LL * (abs(y1 - y2) + 1) - 40 + 2 * C, 0;
			else return cout << fixed << 100LL * (abs(y1 - y2) + 1) - 20 + C, 0;
		} else {
			if(a[0].se > a[1].se) return cout << fixed << 100LL * (abs(y1 - y2) + 1) - 40 + 3 * C, 0;
			else if(a[0].se == a[1].se) return cout << fixed << 100LL * (abs(y1 - y2) + 1) - 40 + 2 * C, 0;
			else return cout << fixed << 100LL * (abs(y1 - y2) + 1) - 20 + C, 0;
		}
	}
	bool flag = false;
	if(n != 0) {
		sort(a, a + n);
		for(int i = 0; i < n; i++) pos[a[i]] = i;
		flag = (x1 == a[0].fi);
		sort(a, a + n, [](pair<int, int> a, pair<int, int> b){ if(y1 < y2) return a.se < b.se; else return a.se > b.se; });
		for(int i = 0; i < n; i++) {
			int j = pos[a[i]];
			dp[j] = 1 + get(0, j);
			upd(j, dp[j]);
			opt = max(opt, dp[j]);
		}
	}
	cout << fixed << 100LL * (x2 - x1 + abs(y1 - y2)) + opt * (C - 20) + flag * C;
}

