inline int gi(){
  char ch=getchar();int x=0,q=0;
  while(ch<'0' || ch>'9') ch=='-'?q=1:0,ch=getchar();
  while(ch>='0' && ch<='9') x=x*10+ch-'0',ch=getchar();
  return q?(-x):x;
}
struct dot{
  int x,y;
  bool operator < (const dot &c) const {
    return x<c.x;
  }
}d[N];
int lx,rx,ly,ry,mx,my,xx,yy;
int mn[N],top;
int work(int n){
  for (int i=1; i<=n; ++i){
    int l=1,r=top,mid,ans=0;
    while(l<=r){
      mid=(l+r)>>1;
      if (mn[mid]<d[i].y)
	ans=mid,l=mid+1;
      else
	r=mid-1;
    }
    if (ans==top) ++top,mn[top]=d[i].y;
    else mn[ans+1]=min(mn[ans+1],d[i].y);
  }
  return top;
}
double ans;
int main(){
  lx=gi(),ly=gi(),rx=gi(),ry=gi();
  mx=min(lx,rx),xx=max(lx,rx);
  my=min(ly,ry),yy=max(ly,ry);
  if (lx>rx) swap(lx,rx),swap(ly,ry);
  int n=gi();
  for (int i=1; i<=n; ++i){
    d[i]=(dot){gi(),gi()};
    if (d[i].x<mx||d[i].x>xx||d[i].y<my||d[i].y>yy)
      --i,--n;
  }
  sort(d+1,d+n+1);
  if (ly>ry)
    for (int i=1; i<=n; ++i)
      d[i].y=-d[i].y;
  int v=work(n);
  ans=(xx-mx+yy-my)*100;
  if (v==min(xx-mx+1,yy-my+1))
    ans+=5*pi;
  ans-=v*(20-5*pi);
  printf("%.12lf",ans);
  return 0;
}

