{
	int l=1,r=n,mid=(l+r)/2;
	while(l<r)
	{
		if(mi>p[mid].x) l=mid+1;
		else r=mid;
		mid=(l+r)/2;
	}
	mi=mid;
	l=1,r=n,mid=(l+r)/2;
