int sx, sy, tx, ty, n, N, cnt, flag, ans, p, flag2;

int search(int k){
	int l = 1, r = cnt, mid;
	while (l < r){
		mid = (l + r) >> 1;
		if (k <= X[mid]) r = mid;
		else l = mid + 1;
	}
	return l;
}

bool cmp(int a, int b){
	return y[a] < y[b];
}

void update(int x, int y){
	for (; x<=cnt; x+=lowbit(x)) c[x] = max(c[x], y);
}

int query(int x){
	int res = 0;
	for (; x; x-=lowbit(x)) res = max(res, c[x]);
	return res;
}

int main(){
	scanf("%d%d%d%d%d", &sx, &sy, &tx, &ty, &n);
	if (sx <= tx && sy > ty){
		flag = 1; 
		sy = 1e8 - sy; ty = 1e8 - ty;
	}
	else if (sx > tx && sy > ty){
		flag = 2; 
		sx = 1e8 - sx; sy = 1e8 - sy;
		tx = 1e8 - tx; ty = 1e8 - ty;
	}
	else if (sx > tx && sy <= ty){
		flag = 3; 
		sx = 1e8 - sx; tx = 1e8 - tx;
	}
	for (int i=1; i<=n; i++){ N++;
		scanf("%d%d", &x[N], &y[N]);
		if (flag == 1) y[N] = 1e8 - y[N];
		else if (flag == 2) { x[N] = 1e8 - x[N]; y[N] = 1e8 - y[N]; }
		else if (flag == 3) x[N] = 1e8 - x[N];
		if (x[N] < sx || x[N] > tx || y[N] < sy || y[N]  > ty){
			N--; continue;
		}
