#define rep(i, a, b) for (int i = a; i <= b; ++ i) 
const int lim = 100000000, N = 200005 ;
const double BY_delta = M_PI * 10.0 - 20.0 ;
const double FY_delta = M_PI * 5.0 - 20.0 ;
using namespace std ; 

int n ; 
struct poi {
	int x, y ; 
} s, t, a[N] ;

bool cmpx(poi a, poi b) {
	return a.x < b.x ;
}

bool cmpy(poi a, poi b) {
	return a.y < b.y ;
}

inline double SUCCESS() {
	return 100.0 * (t.x - s.x + t.y - s.y) + BY_delta + FY_delta * (t.x - s.x) ;
}

int bit[N], d[N] ;

int find(int x) {
	int l = 1, r = d[0] ;
	for ( ; l <= r ; ) {
		int mid = (l + r) / 2 ;
		if (d[mid] == x) return mid ;
		if (x < d[mid]) r = mid - 1 ;
			else l = mid + 1 ;
	}
	return 0 ;
}

void pre() {
	d[0] = 0 ;
	d[++ d[0]] = s.x ;
	d[++ d[0]] = t.x ;
	rep(i, 1, n) {
		d[++ d[0]] = a[i].x ;
	}
	sort(d + 1, d + d[0] + 1) ;
	d[0] = unique(d + 1, d + d[0] + 1) - (d + 1) ;
	s.x = find(s.x) ;
	t.x = find(t.x) ;
	rep(i, 1, n) {
		a[i].x = find(a[i].x) ;
	}
}

void put(int x, int y) {
	for ( ; x <= d[0] ; x += x & (- x)) {
		bit[x] = max(bit[x], y) ;
	}
}

int get(int x) {
	int res = 0 ;
	for ( ; x; x -= x & (- x)) {
		res = max(res, bit[x]) ;
	}
	return res ;
}

inline double FAILED() {
	pre() ;
	sort(a + 1, a + n + 1, cmpy) ;
	put(s.x, 1) ;
	int res = 0 ;
	rep(i, 1, n) {
		if (a[i].y < s.y) continue ;
		int tmp = get(a[i].x) ;
		if (!tmp) continue ;
		put(a[i].x, tmp + 1) ;
		if (a[i].y <= t.y && a[i].x <= t.x) res = max(res, tmp) ;
	}
	return 100.0 * (t.x - s.x + t.y - s.y) + FY_delta * res ;
}

double solve() {
	int k = 0 ;
	sort(a + 1, a + n + 1, cmpx) ;
	rep(i, 1, n) if (a[i].x == s.x && a[i].y >= s.y && a[i].y <= t.y) {
		k = i ;
		break ;
	}
	if (!k) return FAILED() ;
	if (a[n].x < t.x) return FAILED() ;
	if (s.x == t.x) return SUCCESS() ;
	rep(i, k + 1, n) {
		if (a[i].x != s.x + i - k) return FAILED() ;
		if (a[i].y < a[i - 1].y || a[i].y > t.y) return FAILED() ;
		if (i - k == t.x - s.x) break ;
	}
	return SUCCESS() ;
}

int main() {
	scanf("%d%d%d%d%d", &s.x, &s.y, &t.x, &t.y, &n) ;
	rep(i, 1, n) {
		scanf("%d%d", &a[i].x, &a[i].y) ;
	}
	if (s.x > t.x) swap(s, t) ;
	if (s.y > t.y) {
		s.y = lim - s.y ;
		t.y = lim - t.y ;
		rep(i, 1, n) a[i].y = lim - a[i].y ;
	}
	if (t.x - s.x > t.y - s.y) {
		swap(s.x, s.y) ;
		swap(t.x, t.y) ;
		rep(i, 1, n) swap(a[i].x, a[i].y) ;
	}
	printf("%.15lf\n", solve()) ;
	return 0 ; 
}

