		if(!valid()) continue;
		double want=bf();
		double have=solve();
		double diff=abs(want-have),rdiff=diff/want;
		if(rdiff>1e-12) { 
			printf("err %d (have=%lf want=%lf)\n",rep,have,want);
		} else printf(".");
		//break;
	}
}

