#include <bits/stdc++.h>
using namespace std;
const int MX=100000000;
const double Pi=2*asin(1);
const double INF=1e10;
const int BS=19;

double segmax(double *seg,int i,int j,int k,int a,int b)
{
  double ret=-INF;
  if(a<=j&&k<=b){
    ret=seg[i];
  }
  else if(!(k<=a||b<=j)){
    ret=max(segmax(seg,2*i,j,(j+k)/2,a,b),segmax(seg,2*i+1,(j+k)/2,k,a,b));
  }
  return ret;
}

void segset(double *seg,int i,double v)
{
  int p=i+(1<<BS);
  seg[p]=v;
  while(p>1){
    p/=2;
    seg[p]=max(seg[2*p],seg[2*p+1]);
  }
}

