} a[maxn];

int n, type, bit[maxn];
ii b[maxn];

bool cmp(point a, point b) {
    return a.y<b.y;
}

void compress() {
    FOR(i, 1, n) b[i] = ii(a[i].x, i);
    sort(b+1, b+n+1);
    b[0] = ii(-1, -1);
    int cnt = 0;
    FOR(i, 1, n) {
        if (b[i].fi!=b[i-1].fi) ++cnt;
        a[b[i].se].x = cnt;
    }
}

int get(int id) {
    int res = -inf;
    for (; id>0; id -= id&(-id)) res = max(res, bit[id]);
    return res;
}

void update(int id, int val) {
    for (; id<=n; id += id&(-id)) bit[id] = max(bit[id], val);
}

