inline bool Check1 ()
{
    if ( en.sc - st.sc + 1 > n )
        return false;

    int cn = 0, last = -1;

    for (int i = 1; i <= n; i++)
    {
        if ( p[i].sc >= st.sc && p[i].sc <= en.sc )
        {
            mp[ p[i].sc ] = 1;
            if ( p[i].fr < last )
                return false;
            last = p[i].fr;
        }
    }
    for (int i = st.sc; i <= en.sc; i++)
        if (!mp.count( i ))
            return false;
    return true;
}
inline bool Check2 ()
{
    if ( en.fr - st.fr + 1 > n )
        return false;

    mp.clear();

    int cn = 0, last = -1;

    for (int i = 1; i <= n; i++)
    {
        if ( p[i].fr >= st.fr && p[i].fr <= en.fr )
        {
            mp[ p[i].fr ] = 1;
            if ( p[i].sc < last )
                return false;
            last = p[i].sc;
        }
    }
    for (int i = st.fr; i <= en.fr; i++)
        if (!mp.count( i ))
            return false;
    return true;
}
struct st
{
    int val, l, r;
}
t[M];

int get (int l, int r, int v = 1, int tl = 0, int tr = 1e8)
{
    if (l > tr || tl > r || v == 0)
        return 0;

    if (l <= tl && tr <= r)
        return t[v].val;

    int tm = (tl + tr) >> 1;

    return max( get(l, r, t[v].l, tl, tm), get(l, r, t[v].r, tm + 1, tr) );
}
void update (int pos, int val, int v = 1, int tl = 0, int tr = 1e8)
{
    if (tl == tr)
    {
        t[v].val = max( t[v].val, val );
    }
    else
    {
        int tm = (tl + tr) >> 1;
        if (pos <= tm)
        {
            if (!t[v].l) t[v].l = ++Sz;
            update( pos, val, t[v].l, tl, tm );
        }
        else {
            if (!t[v].r) t[v].r = ++Sz;
            update( pos, val, t[v].r, tm + 1, tr );
        }
        t[v].val = max(t[ t[v].l ].val , t[ t[v].r ].val);
    }
}
