#include <bits/stdc++.h>

using namespace std;

const double pi = acos(-1.0);

class fenwick {
 public:
  int n;
  vector<int> f;

  fenwick(int _n) : n(_n) {
    f.resize(n);
  }

  void add(int x, int y) {
    for (int i = x; i < n; i = i | (i + 1)) {
      f[i] = max(f[i], y);
    }
  }

  int get(int x) {
    int ret = 0;
    for (int i = x; i >= 0; i = (i & (i + 1)) - 1) {
      ret = max(ret, f[i]);
    }
    return ret;
  }
};

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(0);
  int x1, y1, x2, y2;
  cin >> x1 >> y1 >> x2 >> y2;
  int n;
  cin >> n;
  vector<pair<int, int>> ps;
  for (int i = 0; i < n; i++) {
    int x, y;
    cin >> x >> y;
    if (min(x1, x2) <= x && x <= max(x1, x2) && min(y1, y2) <= y && y <= max(y1, y2)) {
      ps.emplace_back(x, y);
    }
  }
  sort(ps.begin(), ps.end());
  map<int, int> map_y;
  for (auto& p : ps) {
    map_y[p.second];
  }
  int size_y = 0;
  for (auto& it : map_y) {
    it.second = size_y++;
  }
  if (x1 > x2) {
    swap(x1, x2);
    swap(y1, y2);
  }
  fenwick f((int) ps.size());
  if (y1 > y2) {
    reverse(ps.begin(), ps.end());
  }
  for (auto& p : ps) {
    p.second = map_y[p.second];
  }
  int use = 0;
  for (int i = 0; i < (int) ps.size(); i++) {
    int y = ps[i].second;
    int g = f.get(y);
    f.add(y, g + 1);
    use = max(use, g + 1);
  }     
  int half_turn = 0;
  if (min(abs(x1 - x2), abs(y1 - y2)) + 1 == use) {
    half_turn = 1;  
  }
  double ans = abs(x1 - x2) * 100LL + abs(y1 - y2) * 100LL - 20 * use + pi * 20 * (use - half_turn) / 4 + pi * 20 * half_turn / 2;
  cout << setprecision(10) << fixed << ans << '\n';   
  return 0;
}

