int main()
{
    scanLLInt(x1);
    scanLLInt(y1);
    scanLLInt(x2);
    scanLLInt(y2);
    double result = (abs(x1 - x2) + abs(y1 - y2)) * 100;
    auto inrange = [](ll x, ll a, ll b){return ((a <= x && x <= b) || (b <= x && x <= a));};

    scanLLInt(N);
    map<ll, ll> XY;
    map<ll, ll> YX;
    loop(i, N){
        scanLLInt(Xi);
        scanLLInt(Yi);
        if (inrange(Xi, x1, x2) && inrange(Yi, y1, y2)){
            XY.emplace(Xi, Yi);
            YX.emplace(Yi, Xi);
        }
    }
    if (x2 < x1){
        swap(x1, x2);
        swap(y1, y2);
    }
    // x1 <= x2
    if (x1 == x2){
        if (0 < XY.count(x1) && inrange(XY[x1], y1, y2)){
            result += (M_PI * 10 - 20);
        }
    }else if (y1 == y2){
        if (0 < YX.count(x1) && inrange(YX[x1], x1, x2)){
            result += (M_PI * 10 - 20);
        }
    }else if (y1 < y2){
        map<ll, ll, greater<ll>> temp;
        temp.emplace(y1, 0);
        ll temp_max = 0;
        for (auto& elem : XY){
            auto& xi = elem.first;
            auto& yi = elem.second;
            auto it = temp.upper_bound(yi);
            temp_max = max(temp_max, it->second + 1);
            temp.emplace(yi, it->second + 1);
        }
        result -= (20 - M_PI * 5) * temp_max;
    }else if (y2 < y1){
        map<ll, ll> temp;
        temp.emplace(y1, 0);
        ll temp_max = 0;
        for (auto& elem : XY){
            auto& xi = elem.first;
            auto& yi = elem.second;
            auto it = temp.upper_bound(yi);
            temp_max = max(temp_max, it->second + 1);
            temp.emplace(yi, it->second + 1);
        }
        result -= (20 - M_PI * 5) * temp_max;
    }
    printf("%.12lf\n", result);
}

