  cin >> sx >> sy >> gx >> gy;

  int N;
  cin >> N;

  vector<pair<long, long>> F(N);
  for (int i = 0; i < N; ++i) {
    long x, y;
    cin >> x >> y;
    F[i] = make_pair(x, y);
  }

  while (!(sx <= gx && sy <= gy)) {
    tie(sx, sy) = make_pair(-sy, sx);
    tie(gx, gy) = make_pair(-gy, gx);
    for (auto& p : F)
      p = make_pair(-p.second, p.first);
  }

  sort(F.begin(), F.end());

  int bi = lower_bound(F.begin(), F.end(), make_pair(sx, 0),
		       [](pair<long, long> p, pair<long, long> q) {
			 return p.first < q.first;
		       }) - F.begin();
  int ei = upper_bound(F.begin(), F.end(), make_pair(gx, 0),
		       [](pair<long, long> p, pair<long, long> q) {
			 return p.first < q.first;
		       }) - F.begin();

  vector<long> tab(N + 2, INF);
  tab[0] = sy;

  // cerr << "sx = " << sx << ", sy = " << sy << endl;
  // cerr << "gx = " << gx << ", gy = " << gy << endl;

  for (int i = bi; i < ei; ++i) {
    long x, y;
    tie(x, y) = F[i];
    // cerr << i << ": " << x << " " << y << endl;
    if (y < sy || y > gy)
      continue;

    int j = lower_bound(tab.begin(), tab.end(), y) - tab.begin();
    if (tab[j] > y) {
      assert(j > 0);
      --j;
    }
    assert(tab[j] <= y);
    // cerr << "tab =";
    // for (int k = 0; k < 5; ++k)
    //     cerr << ' ' << tab[k];
    // cerr << endl;
    // cerr << "lb = " << j << ": " << tab[j] << endl;
    if (tab[j + 1] > y)
      tab[j + 1] = y;
  }

  int cnt = 0;
  for (int i = N; i >= 0; --i) {
    if (tab[i] != INF) {
      cnt = i;
      break;
    }
  }

  double ans = 100. * (gx - sx + gy - sy) + cnt * (-20. + 5. * M_PI);
  if ((sx == gx) || (sy == gy) || cnt == min(gx-sx,gy-sy) )
    ans += 5. * M_PI);
  cout << setprecision(20) << ans << '\n';

  return 0;
}

