	long double ans = 100.0L * (abs(1ll*a.x - b.x) + abs(1ll*a.y - b.y));
	int y = a.y, yy = b.y;
	if (y > yy) swap(y, yy);
	// special cases
	if (a.x == b.x) {
		for (int i = 0; i < n; ++i) {
			if (p[i].x == a.x) {
				// cout << "here" << endl;
				if (y < p[i].y && p[i].y < yy) {
					ans += 10*PI - 20;
					break;
				}
			}
		}
	} else if (a.y == b.y) {
		for (int i = 0; i < n; ++i) {
			if (p[i].y == a.y) {
				if (a.x < p[i].x && p[i].x < b.x) {
					ans += 10*PI - 20;
					break;
				}
			}
		}
	} else {
		for (int i = 0; i < n; ++i) {
