				continue;
			}
			int y = p[i].y - a.y;
			if (y < 0) y *= -1;
			int lb = lower_bound(lis, lis + size, y) - lis;
			lis[lb] = y;
			if (lb == size) ++size;
		}
		ans += size * (5*PI - 20);
	}
	cout.precision(15);
	cout << fixed <<  ans << endl;
}

