void solve() {
    cin >> u1 >> v1 >> u2 >> v2;
    cin >> n;
    rep(i, 0, n) {
        scanf("%d%d", &p[i].x, &p[i].y);
    }

    if (u1 > u2) {
        inv(u1); inv(u2);
        rep(i, 0, n) {
            inv(p[i].x);
        }
    }
    if (v1 > v2) {
        inv(v1); inv(v2);
        rep(i, 0, n) inv(p[i].y);
    }

    if (u1 == u2 || v1 == v2) {
        ll res = (abs(u1 - u2) + abs(v1 - v2)) * 100ll;
        ll shit = 0;
        rep(i, 0, n) {
            if (p[i].x >= u1 && p[i].x <= u2 && p[i].y >= v1 && p[i].y <= v2) {
                shit += 10 * pi - 10 * 2 * pw;
            }
        }
        cout << res + shit / pw;
        print(shit % pw);
        return;
    }
    int k = 0;
    rep(i, 0, n) {
        st[p[i].x] = 0;
        id[i] = i;
    }
    st[u1] = 0;
    st[u2] = 0;

    for (auto& it : st) {
        it.second = ++k;
    }

    sort(id, id + n, cmp);

    segmentTree.init(1, k);


    for (int j = 0; j < n; ++j) {
        int i = id[j];

        if (p[i].y >= v1 && p[i].y <= v2) {
            int xpoint = st[p[i].x];
            if (xpoint >= st[u1] && xpoint <= st[u2]) {
                int tmp = 0;
                tmp = segmentTree.get(1, xpoint);
                segmentTree.update(xpoint, tmp + 1);
            }
        }
    }

    ll res = (abs(u1 - u2) + abs(v1 - v2)) * 100ll;
    int tmp = segmentTree.get(st[u1], st[u2]);
    ll shit = 0;
    if (tmp == (min(abs(u1 - u2), abs(v1 - v2)) + 1)) {
        shit += 10 * pi - 10 * 2 * pw;
        --tmp;
    }
    if (!tmp) {
        cout << res;
        return;
    }
    shit = - tmp * 20 * pw + tmp * 5 * pi;
    cout << (res + shit / pw - (shit % pw == 0 ? 0 : 1));
    print(pw + (shit % pw));
}

