#define index_of(as, x) \
  distance(as.begin(), lower_bound(as.begin(), as.end(), x))
vector<int> lis_fast(const vector<int>& a) {
	if( a.size() == 0 ) return {};
  const int n = a.size();
  vector<int> A(n, inf);
  vector<int> id(n);
  for (int i = 0; i < n; ++i) {
    id[i] = index_of(A, a[i]);
    A[ id[i] ] = a[i];
  }
  int m = *max_element(id.begin(), id.end());
  vector<int> b(m+1);
  for (int i = n-1; i >= 0; --i)
    if (id[i] == m) b[m--] = a[i];
  return b;
}

void solve(vector<long long> x, vector<long long> y, long long N, vector<long long> X, vector<long long> Y){
	vector<P> ps,ps2;
	for(int i = 0 ; i < N ; i++) ps.push_back({X[i],Y[i]});
	P p1 = P{x[0],y[0]};
	P p2 = P{x[1],y[1]};
	if( p1.y > p2.y ){
		swap(p1,p2);
	}
	if( p1.x > p2.x ){
		p1.x = mx - p1.x;
		p2.x = mx - p2.x;
		for(int i = 0 ; i < N ; i++) ps[i].x = mx - ps[i].x;
	}
	assert(p1.x <= p2.x);

	if( p1.y == p2.y ){
		swap(p1.y,p1.x);
		swap(p2.y,p2.x);
		for(int i = 0 ; i < N ; i++) swap(ps[i].x,ps[i].y);
	}
	if( p1.x == p2.x ){
		for(int i = 0 ; i < ps.size() ; i++){
			if( ps[i].x == p1.x && p1.y < ps[i].y && ps[i].y < p2.y ){
				printf("%.15lf\n", 100.0 * (p2.y - p1.y) - 20 + pi * 10);
				exit(0);
			}
		}
		printf("%.15lf\n", 100.0 * (p2.y - p1.y));
		exit(0);
	}

	// 端を含むバージョン
	int b1 = 0;
	{
		vector< pair<int,int> > w;
		for(int i = 0 ; i < N ; i++){
			if( p1.y <= ps[i].y and ps[i].y <= p2.y ){
				if( p1.x <= ps[i].x and ps[i].x <= p2.x ){
					w.push_back({ps[i].x,ps[i].y});
				}
			}
		}
		sort(w.begin(),w.end());
		vector<int> v;
		for(int i = 0 ; i < w.size() ; i++) v.push_back(w[i].second);

		auto b = lis_fast(v);
		b1 = b.size();
	}
	// 端を含まないバージョン
	int b2 = 0;
	{
		vector< pair<int,int> > w;
		for(int i = 0 ; i < N ; i++){
			if( p1.y <= ps[i].y and ps[i].y < p2.y ){
				if( p1.x <= ps[i].x and ps[i].x < p2.x ){
					w.push_back({ps[i].x,ps[i].y});
				}
			}
		}
		sort(w.begin(),w.end());
		vector<int> v;
		for(int i = 0 ; i < w.size() ; i++) v.push_back(w[i].second);

		auto b = lis_fast(v);
		b2 = b.size();
	}
	double wow = 100.0 * (p2.y - p1.y + p2.x - p1.x) + b2 * (pi * 5 - 20);
	if( b1 == b2 ){
		printf("%.15lf\n", 100.0 * (p2.y - p1.y + p2.x - p1.x) + b2 * (pi * 5 - 20));
	}else{
		assert(b1 > b2);
		printf("%.15lf\n", min(wow,100.0 * (p2.y - p1.y + p2.x - p1.x) + (b1-1) * (pi * 5 - 20) - 20 + pi * 10));		
	}



}

