int dfs(int cur, int g) {
	if(used[cur]) return dp[cur];
	used[cur] = true;
	if(cur == g) return dp[cur] = 0;
	int ret = -1e9;
	for(auto& to : es[cur]) {
		ret = max(ret, dfs(to, g));
	}
	return dp[cur] = ret+1;
}
void getIdx(double nxtY, set<P>& st) {
	while(st.size() > 1) {
		auto cur = *st.begin();
		st.erase(cur);
		auto nxt = *st.begin();
		if(cur.fi.se < nxt.fi.se) {
			es[cur.se].pb(nxt.se);
		}
		else {
			getIdx(cur.fi.se, st);
			auto nxt = *st.begin();
			if(cur.fi.se > nxt.fi.se) return;
			es[cur.se].pb(nxt.se);
		}
		if(nxt.fi.se > nxtY) return;
	}
	return;
}


