    if (s.first == t.first) {
        bool find = 0;
        double res = dd * 100.0;
        for (int i = 0 ; i < n ; ++ i) {
            if (a[i].first == s.first &&
                s.second < a[i].second && a[i].second < t.second) {
                find = 1;
                break;
            }
        }
        if (find) res += 10 * pi - 20;
        printf("%.20f\n" , res);
        return 0;
    }

    if (t.second < s.second) {
        s.second = -s.second;
        t.second = -t.second;
        for (int i = 0 ; i < n ; ++ i) {
            a[i].second = -a[i].second;
        }
    }
    d[D ++] = s.second;
    d[D ++] = t.second;
    for (int i = 0 ; i < n ; ++ i) {
        d[D ++] = a[i].second;
    }
    sort(d , d + D);
    D = unique(d , d + D) - d;

    s.second = lower_bound(d , d + D , s.second) - d + 1;
    t.second = lower_bound(d , d + D , t.second) - d + 1;
    for (int i = 0 ; i < n ; ++ i) {
        a[i].second = lower_bound(d , d + D , a[i].second) - d + 1;
    }

    for (int i = 0 ; i < n ; ++ i) {
        f[i] = -1 << 30;
        if (a[i].first >= s.first && a[i].second >= s.second) {
            f[i] = 0;
        }
    }
    memset(c , 0xC0 , sizeof(c));
    int res = 0;
    for (int i = 0 ; i < n ; ++ i) {
        //printf("%d %d\n" , a[i].first , a[i].second);
        for (int j = a[i].second ; j > 0 ; j -= j & -j) {
            f[i] = max(f[i] , c[j]);
        }
        if (a[i].first <= t.first && a[i].second <= t.second) {
            res = max(res , ++ f[i]);
        }
        for (int j = a[i].second ; j <= D ; j += j & -j) {
            c[j] = max(c[j] , f[i]);
        }
    }
    __float128 ans = res * (5 * pi - 20);
    __float128 dis = 100.0;
    dis *= dd;
    ans += dis;

    printf("%.20f\n" , (double)ans);
}

