		ld cur;
		if(fixed || y != pmax) {
			auto it = lower_bound(all(lis), y);
			if(it == lis.end()) lis.pb(y), it = --lis.end();
			else *it = y;
			//if(lis.size() == 2) cout << i.first << " " << i.second << '\n';
			cur = (it - lis.begin() + !fixed)*A + fixed*B + (i.first < rx ? B : 0);
		} else {
			auto it = lower_bound(all(lis), y);
			cur = (it == lis.end() ? lis.size() : (it - lis.begin() + !fixed))*A + fixed*B + (i.first < rx ? B : 0);
			cur += B;
		}
		//	cout << i.first << " " << i.second << " / " << pmax << " " << cur << " / " << ans << " " << lis.size() << " " << B << endl;
		ans = min(ans, cur);
	}
