#include <algorithm>
typedef long long ll ;
#define rep(i, a, b) for (int i = a; i <= b; ++ i) 
const int lim = 100000000, N = 500005 ;
const double BY_delta = M_PI * 10.0 - 20.0 ;
const double FY_delta = M_PI * 5.0 - 20.0 ;
using namespace std ;

int n, d[N] ; 
struct poi {
	int x, y ; 
} s, t, a[N] ;
double f[N][2], bit[N][2], ans ;

bool cmpy(poi a, poi b) {
	return a.y < b.y ;
}

int find(int x) {
	int l = 1, r = d[0] ;
	for ( ; l <= r; ) {
		int mid = (l + r) / 2 ;
		if (d[mid] == x) return mid ;
		if (x < d[mid]) r = mid - 1 ; 
			else l = mid + 1 ;
	}
	return 0 ;
}

void pre() {
	d[0] = 0 ;
	d[++ d[0]] = s.x ;
	d[++ d[0]] = t.x ;
	rep(i, 1, n) {
		d[++ d[0]] = a[i].x ;
	}
	sort(d + 1, d + d[0] + 1) ;
	d[0] = unique(d + 1, d + d[0] + 1) - (d + 1) ;
	s.x = find(s.x) ;
	t.x = find(t.x) ;
	rep(i, 1, n) {
		a[i].x = find(a[i].x) ;
	}
}

void put(int c, int x, double y) {
	for ( ; x <= d[0] ; x += x & (- x)) {
		bit[x][c] = min(bit[x][c], y) ;
	}
}

double get(int c, int x) {
	double res = 1e17 ;
	for ( ; x; x -= x & (- x)) {
		res = min(res, bit[x][c]) ;
	}
	return res ;
}

void solve() {
	sort(a + 1, a + n + 1, cmpy) ;
	rep(i, 1, n) {
		f[i][0] = f[i][1] = 1e17 ;
	}
	rep(i, 1, d[0]) {
		bit[i][0] = bit[i][1] = 1e17 ;
	}
	int sx = 0, sy = 0, tx = 0, ty = 0 ;
	rep(i, 1, n) {
		if (a[i].x == s.x) sx = i ;
		if (a[i].y == s.y) sy = i ;
		if (a[i].x == t.x) tx = i ;
		if (a[i].y == t.y) ty = i ;
	}
	rep(i, 1, n) {
		// from s 
		if (s.x <= a[i].x && s.y <= a[i].y) ; else continue ;
		if (s.x < a[i].x && s.y < a[i].y) {
			if (!sx || a[sx].y > a[i].y) f[i][1] = FY_delta ;
			if (!sy || a[sy].x > a[i].x) f[i][0] = FY_delta ;
		} else
		if (s.x == a[i].x) {
			f[i][0] = FY_delta ;
			f[i][1] = BY_delta ;
		} else {
			f[i][1] = FY_delta ;
			f[i][0] = BY_delta ;
		}
	}
	rep(i, 1, n) {
		double tmp = min(get(0, a[i].x), get(1, a[i].x)) ;
		if (tmp < 1e17) {
			f[i][0] = min(f[i][0], tmp + FY_delta) ;
			f[i][1] = min(f[i][1], tmp + FY_delta) ;
		}
		put(0, a[i].x, f[i][0]) ;
		put(1, a[i].x, f[i][1]) ;
	}
	rep(i, 1, n) {
		// to t
		double res = 1e17 ;
		if (a[i].x <= t.x && a[i].y <= t.y) ; else continue ;
		if (a[i].x < t.x && a[i].y < t.y) {
			if (!tx || a[tx].y < a[i].y) res = min(res, f[i][0]) ;
			if (!ty || a[ty].x < a[i].x) res = min(res, f[i][1]) ;
		} else
		if (a[i].x == t.x) {
			res = min(res, f[i][1]) ;
		} else {
			res = min(res, f[i][0]) ;
		}
		ans = min(ans, res) ;
	}
	// s to t
	if ((!tx || a[tx].y < s.y) && s.y != t.y) ans = min(ans, 0.0) ;
	if ((!ty || a[ty].x < s.x) && s.x != t.x) ans = min(ans, 0.0) ;
}

int main() {
	scanf("%d%d%d%d", &s.x, &s.y, &t.x, &t.y) ;
	scanf("%d", &n) ;
	rep(i, 1, n) {
		scanf("%d%d", &a[i].x, &a[i].y) ;
	}
	if (s.x > t.x) swap(s, t) ;
	if (s.y > t.y) {
		s.y = lim - s.y ;
		t.y = lim - t.y ;
		rep(i, 1, n) {
			a[i].y = lim - a[i].y ;
		}
	}
	pre() ;
	ans = 1e17 ;
	solve() ;
	ans += 100.0 * (d[t.x] - d[s.x] + t.y - s.y) ;
	printf("%.15lf\n", ans) ;
	return 0 ;
}

