};
info st,ed,ara[Max];
long double cut = 5.0 * acos(-1.0);

bool isSameLine(info p,info a,info q)
{
	if( p.x == q.x && a.x == p.x ) return ( min(p.y,q.y) <= a.y && a.y <= max(p.y,q.y) );
	if( p.y == q.y && a.y == p.y ) return ( min(p.x,q.x) <= a.x && a.x <= max(p.x,q.x) );
	return 0;
}

