void change()
{
	LL i;
	rep(i,n) ara[i].y = 100000000 - ara[i].y;
	st.y = 100000000 - st.y;
	ed.y = 100000000 - ed.y;
}

LL a[Max],N,dp[Max],c[Max];
LL bin(LL len,LL x)
{
	LL low = 1,high = len, mid, ans;
	if( len == 0 || x > c[len] ) return len + 1;
	while(low <= high)
	{
		mid = (low + high) / 2;
		LL my = c[mid];
		if( x <= my )
		{
			ans = mid;
			high = mid - 1;
		}
		else low = mid + 1;
	}
	return ans;
}

LL LIS()
{
	LL len = 0;
    for(LL i = 1; i <= N; i++)
    {
        LL k = bin(len,a[i]);
        c[k] = a[i];
        dp[i] = k;
        len = max(len,k);
    }
    return len;
}

void make()
{
	LL i;
    rep(i,n)
    {
		if( st.x <= ara[i].x && ara[i].x <= ed.x )
		{
			if( st.y <= ara[i].y && ara[i].y <= ed.y )
			{
				a[++N] = ara[i].y - st.y;
			}
		}
    }
}

