		swap(x1, x2);
		swap(y1, y2);
	}
	if (y1 > y2)
		for(auto &u : vec)
			u.S *= -1;
	VI dp;
	dp.PB(-1e9);
	for (auto u : vec) {
		debug("%d - %d\n", u.F, u.S);
		auto p = lower_bound(ALL(dp), u.S);
		if (p == dp.end())
