#include <algorithm>
using namespace std;
const int N=200000;
const double pi=acos(-1);
int sx,sy,tx,ty,n,nx=0,viss[200005],vist[200005];
struct point {
	int x,y,num,nxt,lat,loc;
}a[200005],b[200005];
double ans1[200005],ans2[200005];
bool ansjudge;
namespace bit {
	double t[N+10];
	void clear() {
		for (int i=0;i<=N;i++) t[i]=1e18;
		return;
	}
	int lowbit(int x) {
		return x&(-x);
	}
	double Query(int x) {
		double minx=1e18;
		while (x>0) {
			minx=min(minx,t[x]);
			x-=lowbit(x);
		}
		return minx;
	}
	void Add(int x,double va) {
		while (x<=N) {
			t[x]=min(t[x],va);
			x+=lowbit(x);
		}
	}
}
bool cmpx(point p,point q) {
	return p.x<q.x;
}
bool cmpy(point p,point q) {
	return p.y<q.y;
}
void discretization() {
	sort(a+1,a+n+1,cmpy);
	for (int i=1;i<=n;i++) {
		a[i].num=i;
		a[i].nxt=a[i-1].loc;
		a[i].lat=a[i+1].loc;
	}
	sort(a+1,a+n+1,cmpx);
	a[0].x=a[0].y=0;
	a[n+1].x=tx;
	a[n+1].y=ty;
}
bool find(int x,int y) {
	int l=1,r=n;
	while (l<=r) {
		int mid=(l+r)/2;
		if (b[mid].x==x) {
			if (b[mid].y!=y) return 0;
			return 1;
		}
		if (b[mid].x<x) l=r+1;else r=l-1;
	}
	return 0;
}
void prework() {
	sort(a+1,a+n+1,cmpx);
	for (int i=0;i<=n+1;i++) a[i].loc=i;
	for (int i=1;i<=n;i++) b[i]=a[i];
	discretization();
	int k=1e9;
	for (int i=1;i<=n;i++) {
		bool judge=1;
		for (int j=max(0,i-ty);j<=i&&j<=tx;j++) {
			int nowx=j,nowy=i-j;
			if (!find(nowx,nowy)) {
				judge=0;
				break;
			}
		}
		if (judge) {
			k=i;
			break;
		}
	}
	for (int i=1;i<=n;i++)
		if (a[i].x+a[i].y<=k) {
			viss[i]=1;
			if (a[i].x-a[i-1].x==1&&a[i-1].y<=a[i].y) {
				int nowy1=a[i-1].y,nowy2=nowy1;
				bool judge1=1,judge2=1;
				for (int j=a[i-1].x-1;j>=0;j--) {
					nowy1--;
					nowy2++;
					if (!find(j,nowy1)) judge1=0;
					if (!find(j,nowy2)) judge2=0;
					if (!judge1&&!judge2) break;
				}
				if (judge1||judge2) viss[i]=2;
			}
			if (a[i].y-a[a[i].nxt].y==1&&a[i].nxt<=i) {
				int nowx1=a[a[i].nxt].x,nowx2=nowx1;
				bool judge1=1,judge2=1;
				for (int j=a[a[i].nxt].y-1;j>=0;j--) {
					nowx1--;
					nowx2++;
					if (!find(nowx1,j)) judge1=0;
					if (!find(nowx2,j)) judge2=0;
					if (!judge1&&!judge2) break;
				}
				if (judge1||judge2) viss[i]=3;
			}			
		}
	if (k==1e9) ansjudge=1;
	k=-1e9;
	for (int i=tx+ty;i>=tx+ty-n&&i>=0;i--) {
		bool judge=1;
		for (int j=max(0,i-ty);j<=i&&j<=tx;j++) {
			int nowx=j,nowy=i-j;
			if (!find(nowx,nowy)) {
				judge=0;
				break;
			}
		}
		if (judge) {
			k=i;
			break;
		}
	}
	for (int i=1;i<=n;i++)
		if (a[i].x+a[i].y>=k) {
			vist[i]=1;
			if (a[i+1].x-a[i].x==1&&a[i+1].y>=a[i].y) {
				int nowy1=a[i+1].y,nowy2=nowy1;
				bool judge1=1,judge2=1;
				for (int j=a[i+1].x+1;j<=tx;j++) {
					nowy1--;
					nowy2++;
					if (!find(j,nowy1)) judge1=0;
					if (!find(j,nowy2)) judge2=0;
					if (!judge1&&!judge2) break;
				}
				if (judge1||judge2) vist[i]=2;
			}
			if (a[a[i].lat].y-a[i].y==1&&a[i].lat>=i) {
				int nowx1=a[a[i].lat].x,nowx2=nowx1;
				bool judge1=1,judge2=1;
				for (int j=a[a[i].lat].y+1;j<=ty;j++) {
					nowx1--;
					nowx2++;
					if (!find(nowx1,j)) judge1=0;
					if (!find(nowx2,j)) judge2=0;
					if (!judge1&&!judge2) break;
				}
				if (judge1||judge2) vist[i]=3;
			}
		}
}
double work() {
	prework();
	bit::clear();
	int nowk=1;
	for (int i=1;i<=n;i++) {
		if (viss[i]==1) ans1[i]=ans2[i]=(a[i].x+a[i].y)*100.0-10+5*pi;//1 right 2 up
			else if (viss[i]==2) {
				ans1[i]=(a[i].x+a[i].y)*100.0-10+5*pi;
				ans2[i]=(a[i].x+a[i].y)*100.0-10+10*pi;
			}
			else if (viss[i]==3) {
				ans2[i]=(a[i].x+a[i].y)*100.0-10+5*pi;
				ans1[i]=(a[i].x+a[i].y)*100.0-10+10*pi;				
			}
			else ans1[i]=ans2[i]=1e18;
		double now=a[i].x*100.0+a[i].y*100.0-20.0+5*pi;
		if (a[i].nxt==0||a[i].y-a[a[i].nxt].y>1||a[i].nxt>i)
			now+=bit::Query(a[i].num-1);
			else now+=bit::Query(a[i].num-2);
		ans1[i]=min(ans1[i],now);
		ans2[i]=min(ans2[i],now);
		if (i>1&&a[i-1].x+1==a[i].x&&a[i-1].y<a[i].y) {
			double nowx=100.0*(a[i].x+a[i].y-a[i-1].x-a[i-1].y);
			ans1[i]=min(ans1[i],ans1[i-1]+nowx-20.0+5*pi);
			ans1[i]=min(ans1[i],ans2[i-1]+nowx-20.0+10*pi);
			if (a[i].y-a[i-1].y!=1)
				ans2[i]=min(ans2[i],min(ans2[i-1],ans1[i-1])+nowx-20.0+5*pi);
		}
		if (a[i].nxt&&a[a[i].nxt].y+1==a[i].y&&a[i].nxt<i) {
			int kx=a[i].nxt;
			double nowx=100.0*(a[i].x+a[i].y-a[kx].x-a[kx].y);
			ans2[i]=min(ans2[i],ans2[kx]+nowx-20.0+5*pi);
			ans2[i]=min(ans2[i],ans1[kx]+nowx-20.0+10*pi);
			if (a[i].x-a[kx].x!=1)
				ans2[i]=min(ans2[i],min(ans2[kx],ans1[kx])+nowx-20.0+5*pi);
		}
		if (i==n) break;
		while (nowk<=i&&a[i+1].x-a[nowk].x>1) {
			bit::Add(a[nowk].num,min(ans1[nowk],ans2[nowk]));
			nowk++;
		}
	}
	double ans=1e18;
	if (ansjudge) ans=100.0*(tx+ty);
	for (int i=1;i<=n;i++) {
		if (!vist[i]) continue;
		double now=100.0*(tx+ty-a[i].x-a[i].y)-10;
		if (vist[i]==1) ans=min(ans,min(ans1[i],ans2[i])+now);
		else if (vist[i]==2) ans=min(ans,ans2[i]+now);
		else ans=min(ans,ans1[i]+now);
	}
	return ans;
}
int main() {
	scanf("%d%d%d%d",&sx,&sy,&tx,&ty);
	bool judge=1;
	if (sx>tx) {
		swap(sx,tx);
		judge^=1;
	}
	if (sy>ty) {
		swap(sy,ty);
		judge^=1;
	}
	scanf("%d",&n);
	for (int i=1;i<=n;i++) {
		int nowx,nowy;
		scanf("%d%d",&nowx,&nowy);
		if (nowx<sx||nowy<sy||nowx>tx||nowy>ty) continue;
		a[++nx].x=nowx;
		if (judge) a[nx].y=nowy;else a[nx].y=sy+ty-nowy;
	}
	n=nx;
	tx-=sx;
	ty-=sy;
	for (int i=1;i<=n;i++) {
		a[i].x-=sx;
		a[i].y-=sy;
	}
	double ans=work();
	printf("%.15lf\n",ans);
	return 0;
}

