  ll mode = 0;
  if(x>x2) swap(x, x2), swap(y, y2);
  if(y2>y) mode = 1;
  map<ll, ll> Y;
  set<ll> X, Z;
  for(int i=0;i<n;i++){
    std::cin >> a >> b;
    if(!(min(x, x2)<=a&&a<=max(x, x2)&&min(y, y2)<=b&&b<=max(y, y2))) continue;
    f.push_back(vector<ld> {a, b});
    Y.emplace(b, 0);
    if(min(y, y2)<b&&b<max(y, y2)) X.insert(a);
    if(min(x, x2)<a&&a<max(x, x2)) Z.insert(b);
  }
  ll c=0, k=0;
  for(auto itr=Y.begin();itr!=Y.end();itr++, c++) (*itr).second=c;
  multimap<ll, ll> num;
  sort(f.begin(), f.end());
  segtree seg(Y.size()+1, 0);

  for(int i=0;i<f.size();i++){
    if(mode==1) c = seg.find(0, Y.at(f[i][1]));
    else c = seg.find(Y.at(f[i][1]), Y.size()+1);
    k = max(k, c+1);
    seg.upd(c+1, Y.at(f[i][1]));
  }
  ll d = 0;
  if(k==min(abs(x2-x)+1, abs(y2-y)+1)) k--;
  if(X.size()==abs(x2-x)+1||Z.size()==abs(y2-y)+1) d++;
  //std::cout << k << " " << d << '\n';
  std::cout << fixed << setprecision(20) << (ld)abs(x2-x)*100.0 + (ld)abs(y2-y)*100.0 - (ld)k*(20.0-5.0*M_PI) + (ld)d*(10.0*M_PI-20.0) << '\n';
