// uniq, compress {{{
#include <algorithm>
#include <map>
#include <vector>
template < class T >
void uniq(vector< T > &v) {
  sort(v.begin(), v.end());
  v.erase(unique(v.begin(), v.end()), v.end());
}
template < class T >
map< T, int > compress(const vector< T > &v) {
  map< T, int > mp;
  int i = -1;
  for(auto &e : v) mp[e] = ++i;
  return mp;
}
// }}}


int main() {
  ios::sync_with_stdio(false), cin.tie(0);
  cin >> fromX >> fromY >> toX >> toY;
  cin >> n;
  bool revX = 0, revY = 0;
  if(fromX > toX) fromX *= -1, toX *= -1, revX = 1;
  if(fromY > toY) fromY *= -1, toY *= -1, revY = 1;
  using P = pair<int, int>;
  vector<P> v;
  vector<int> xs;
  toX -= fromX, toY -= fromY;
  for(int i = 0; i < n; i++) {
    cin >> x[i] >> y[i];
    if(revX) x[i] *= -1;
    if(revY) y[i] *= -1;
    x[i] -= fromX;
    y[i] -= fromY;
    if(0 <= x[i] && x[i] <= toX && 0 <= y[i] && y[i] <= toY) {
      xs.emplace_back(x[i]);
      v.emplace_back(x[i], y[i]);
    }
  }
  fromX = fromY = 0;

  sort((v).begin(), (v).end());

  // 座圧
  xs.emplace_back(toX);
  uniq(xs);
  auto mp = compress(xs);

  for(auto p : v) ecas.index(mp[p.first], p.second);

  ecas.init(1);

  for(auto p : v) {
    int val = ecas.query(0, mp[p.first], 0, p.second) + 1;
    ecas.set(mp[p.first], p.second, val);
  }

  cout << fixed << setprecision(20);
  constexpr double PI = acos(-1);
  constexpr double A = 20 - 5 * PI;
  constexpr double B = 10 * PI - 20;

  int num = ecas.query(0, mp[toX] + 1, 0, toY + 1);

  double ans = 0;
  if(min(toX, toY) + 1 != num) {
    ans += (double) - num * A;
    ans += 100.0 * (toX + toY);
  } else {
    ans -= (double) A * (num - 1);
    ans += B;
    ans += (toX + toY) * 100.0;
  }

  cout << ans << endl;

  return 0;
}

