struct FenTree
{
    int a[N];
    FenTree(): a() {}
    void relax(int v, int x)
    {
        for (int i = v; i < N; i |= i + 1)
            a[i] = max(a[i], x);
    }
    int get(int v)
    {
        int s = 0;
        for (int i = v; i >= 0; i = (i & (i + 1)) - 1)
            s = max(s, a[i]);
        return s;
    }
};

