        return;
    }

    if (y1 == y2)
    {
        int n;
        scanf("%d", &n);
        double cost = (x2 - x1) * 100;
        for (int i = 0; i < n; i++)
        {
            int x, y;
            scanf("%d%d", &x, &y);
            if (y == y1 && x1 <= x && x <= x2)
                cost += 10 * PI - 20;
        }
        printf("%.20lf\n", cost);
        return;
    }

    int n;
    scanf("%d", &n);
    for (int i = 0; i < n; i++)
    {
        int x, y;
        scanf("%d%d", &x, &y);
        if (!(x1 <= x && x <= x2))
            continue;
        if (!(y1 <= y && y <= y2))
            continue;
        ys.push_back(y);
        founts.emplace_back(x, y);
    }

    make_unique(ys);
    sort(founts.begin(), founts.end());
    int best = 0;

    for (auto f : founts)
    {
        int y = get_crd(ys, f.second);
        int ans = fen.get(y) + 1;
        best = max(best, ans);
        fen.relax(y, ans);
    }

    double cost = (x2 - x1 + y2 - y1) * 100.0 + (5 * PI - 20) * best;
    printf("%.20lf\n", cost);
}

