struct SegT {
private:
	int sz; vector<ld> node;
	const ld init_c = mod;
public:
	SegT(int n) {
		sz = 1;
		while (sz < n)sz *= 2;
		node.resize(2 * sz - 1, init_c);
	}
	ld f(ld a, ld b) {
		return min(a, b);
	}
	void update(int k, ld a,bool b) {
		k += sz - 1;
		if (b) {
			node[k] = a;
		}
		else {
			node[k] = f(node[k],a);
		}
		while (k > 0) {
			k = (k - 1) / 2;
			node[k] = f(node[k * 2 + 1], node[k * 2 + 2]);
		}
	}
	ld query(int a, int b, int k = 0, int l = 0, int r = -1) {
		if (r < 0)r = sz;
		if (r <= a || b <= l)return init_c;
		else if (a <= l && r <= b)return node[k];
		else {
			ld vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
			ld vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
			return f(vl, vr);
		}
	}
};

void solve() {
	int sx[2], sy[2];
	rep(i, 2)cin >> sx[i] >> sy[i];
	if (sy[0] > sy[1]) {
		swap(sx[0], sx[1]);
		swap(sy[0], sy[1]);
	}
	bool rx = false;
	if (sx[0] > sx[1]) {
		rx = true;
		rep(i, 2)sx[i] = -sx[i];
	}
	ld add = 0;
	add += sx[1] - sx[0];
	add += sy[1] - sy[0];
	add *= 100;
	vector<int> vx, vy;
	vector<P> al;
	rep(i, 2) {
		vx.push_back(sx[i]);
		vy.push_back(sy[i]);
	}
	ld c1 =5*pi-20;
	ld c2 = 10 * pi - 20;
	int n; cin >> n;
	rep(i, n) {
		int x, y; cin >> x >> y;
		if (rx)x = -x;
		if (y<sy[0] || y>sy[1])continue;
		if (x<sx[0] || x>sx[1])continue;
		vx.push_back(x);
		if (x + 1 < sx[1]) {
			vx.push_back(x);
		}
		vy.push_back(y);
		al.push_back({ x,y });
	}
	sort(vx.begin(), vx.end());
	vx.erase(unique(vx.begin(), vx.end()), vx.end());
	map<int, int> mpx, mpy;
	sort(vy.begin(), vy.end());
	vy.erase(unique(vy.begin(), vy.end()), vy.end());
	rep(i, vx.size())mpx[vx[i]] = i;
	rep(i, vy.size())mpy[vy[i]] = i;
	rep(i, 2) {
		sx[i] = mpx[sx[i]];
		sy[i] = mpy[sy[i]];
	}
	rep(i, al.size()) {
		int &x = al[i].first, &y = al[i].second;
		x = mpx[x];
		y = mpy[y];
	}
	al.push_back({ sx[1],sy[1] });
	sort(al.begin(), al.end());
	SegT st(vx.size());
	//SegT stw(vx.size());
	st.update(0, 0,true);
	vector<vector<int>> loc(vy.size());
	rep(i, al.size()) {
		loc[al[i].second].push_back(al[i].first);
	}
	rep(i, loc[0].size()) {
		int x = loc[0][i];
		ld cost = i * c2 + c1;
		if (sx[1] == x && sy[1] == 0) {
			cout << add+cost-c1 << endl; return;
		}
		st.update(x, cost,true);
		st.update(x + 1, cost - c1 + c2,false);
	}
	rep1(i, (int)vy.size() - 1) {
		int le = 0; ld pre = mod;
		vector<LDP> upds;
		rep(j, loc[i].size()) {
			int x = loc[i][j];
			ld left = mod;
			if (le == 0)left = st.query(0, x);
			else {
				left = st.query(le, x);
				left = min(left, pre);
			}
			le = x + 1, pre = left + c2;
			ld down = st.query(x, x + 1);
			int id;
			if (vy[i] - vy[i - 1] == 1) {
				int id = upper_bound(loc[i - 1].begin(), loc[i - 1].end(), x) - loc[i - 1].begin();
				id--;
				if (id >= 0) {
					id = loc[i - 1][id];
				}
				id++;
			}
			else {
				id = 0;
			}
			down = min(down, st.query(id, x + 1));
			pre = min(pre, down + c1);
			upds.push_back({ left,down });
			if (x == sx[1] && i == sy[1]) {
				cout << add+min(down, left) << endl; return;
			}
		}
		rep(j, upds.size()) {
			int x = loc[i][j];
			ld left = upds[j].first, down = upds[j].second;
			ld up = min(down + c2, left + c1);
			ld right = min(down + c1, left + c2);
			st.update(x, up, true);
			st.update(x, right, false);
			//if (i == 1)cout << left<<" "<<down << endl;
		}
	}
}


