const int mxn = 4e5+7;

struct BIT {
	um<int,int> tree;	
	void cmod(int i, int x) {
		for (; i < mxn; i |= i+1)		
			Max(tree[i],x);
	}
	int query(int i) {
		int ans = 0;
		for (; i >= 0; i = (i&(i+1))-1)
			if (tree.count(i))
				Max(ans,tree[i]);
		return ans;
	}
};

