const int MAXN = 2e5 + 5;
const long double PI = acosl(-1);

Pii S, T;
int N;
Pii A[MAXN];

void input()
{
    read(S.x); read(S.y); read(T.x); read(T.y);
    read(N);
    for (int i = 1; i <= N; ++i) {
        read(A[i].x); read(A[i].y);
    }
}

void solve()
{
    if (S > T)
        std::swap(S, T);
    if (S.y > T.y) {
        for (int i = 1; i <= N; ++i) {
            A[i].y = S.y - A[i].y;
        }
        T.y = S.y - T.y;
        S.y = 0;
    }

    assert(S.x <= T.x);
    assert(S.y <= T.y);

    vector<Pii> list;

    for (int i = 1; i <= N; ++i) {
        if (S.x <= A[i].x && A[i].x <= T.x && S.y <= A[i].y && A[i].y <= T.y)
            list.push_back(A[i]);
    }
    std::sort(ALL(list));

    static int g[MAXN];

    int max = 0;
    memset(g, +oo, sizeof(g));
    g[0] = -oo;
    for (int i = 0; i < SZ(list); ++i) {
        int x = list[i].y;
        int t = std::lower_bound(g, g + i + 1, x) - g;
        g[t] = x;
        chkmax(max, t);
    }

    long double fq = 2 * PI * 10 * 0.25 - 20;
    long double yj = 2 * PI * 10 * 0.50 - 20;
    long double ans = 100.0 * (T.x - S.x + T.y - S.y) + max * fq + (max == std::min(T.x - S.x, T.y - S.y) + 1) * (yj - fq);
    printf("%.15Lf\n", ans);
}

