void solve() {
    FOR(i, 0, 2) cin >> z[i] >> t[i];
    cin >> n;
    FOR(i, 0, n) cin >> x[i] >> y[i];
    long long tmp = (long long) (abs(z[0] - z[1]) + abs(t[0] - t[1])) * 100;
    if (z[0] > z[1]) {
        swap(z[0], z[1]);
        swap(t[0], t[1]);
    }
    if (t[0] > t[1]) {
        t[0] *= -1, t[1] *= -1;
        FOR(i, 0, n) y[i] *= -1;
    }
    vii v;
    FOR(i, 0, n) {
        if (x[i] >= z[0] && x[i] <= z[1] && y[i] >= t[0] && y[i] <= t[1]) {
            v.pb(mp(x[i], y[i]));
        }
    }
    sort(all(v));
    n = sz(v);
    vi dc;
    FOR(i, 0, sz(v)) {
        x[i] = v[i].fi;
        y[i] = v[i].se;
        dc.pb(x[i]);
        dc.pb(y[i]);
    }
    sort(all(dc)), uni(dc);
    if (z[0] == z[1] || t[0] == t[1]) {
        cout << prec(15) << tmp + (long double) n * (10 * PI - 20) << "\n";
        return;
    }
    if (!n) {
        cout << prec(15) << tmp << "\n";
        return;
    }
    long double ans = 1e18;
    FOR(msk, 0, 1 << 4) {
        ms(fen, 0);
        FOR(i, 0, n) {
            if (bit(msk, 0) && x[i] == z[0]) continue;
            if (bit(msk, 1) && y[i] == t[0]) continue;
            if (bit(msk, 2) && x[i] == z[1]) continue;
            if (bit(msk, 3) && y[i] == t[1]) continue;
            int k = lower_bound(all(dc), y[i]) - dc.begin();
            int r = query(k) + 1;
            upd(k, r);
            if (x[i] < z[1] && y[i] < t[1]) {
                chkmin(ans, tmp - (long double) r * (20 - 10 * PI / 2));
            }
            else if (x[i] == z[1] || y[i] == t[1]) {
                if (bit(msk, 0) + bit(msk, 2) > 0 && bit(msk, 1) + bit(msk, 3) > 0) {
                    chkmin(ans, tmp - (long double) r * (20 - 10 * PI / 2));
                }
                else if (r & 1) {
                    chkmin(ans, tmp - (long double) r * (20 - 10 * PI / 2));
                }
                else {
                    chkmin(ans, tmp - (long double) (r - 1) * (20 - 10 * PI / 2) + (10 * PI - 20));
                }
            }
        }
    }
    cout << prec(15) << ans << "\n";
}

