struct PT {
    int x, y;

    PT() {}

    PT(int x, int y) : x(x), y(y) {}

    bool operator<(const PT &rhs) const {
        if (x < rhs.x)
            return true;
        if (rhs.x < x)
            return false;
        return y < rhs.y;
    }

    bool operator>(const PT &rhs) const {
        return rhs < *this;
    }

    bool operator<=(const PT &rhs) const {
        return !(rhs < *this);
    }

    bool operator>=(const PT &rhs) const {
        return !(*this < rhs);
    }

    bool operator==(const PT &rhs) const {
        return x == rhs.x &&
               y == rhs.y;
    }

    bool operator!=(const PT &rhs) const {
        return !(rhs == *this);
    }

    friend ostream &operator<<(ostream &os, const PT &pt) {
        os << "x: " << pt.x << " y: " << pt.y;
        return os;
    }

    friend istream &operator>>(istream &is, PT &pt) {
        is >> pt.x >> pt.y;
        return is;
    }
};


typedef vector<int> VI;
typedef pair<int,int> PII;
typedef vector<PII> VPII;

#define STRICTLY_INCREASNG

VI LongestIncreasingSubsequence(VI v) {
    if (v.empty()) {
        return VI();
    }
    VPII best;
    VI dad(v.size(), -1);

    for (int i = 0; i < v.size(); i++) {
#ifdef STRICTLY_INCREASNG
        PII item = make_pair(v[i], 0);
        VPII::iterator iter = lower_bound(best.begin(), best.end(), item);
        item.second = i;
#else
        PII item = make_pair(v[i], i);
    VPII::iterator iter = upper_bound(best.begin(), best.end(), item);
#endif
        if (iter == best.end()) {
            dad[i] = (best.size() == 0 ? -1 : best.back().second);
            best.push_back(item);
        } else {
            dad[i] = dad[iter->second];
            *iter = item;
        }
    }

    VI ret;
    for (int i = best.back().second; i >= 0; i = dad[i])
        ret.push_back(v[i]);
    reverse(ret.begin(), ret.end());
    return ret;
}

