    if (downward) {
        s.y = 1e8 - s.y;
        t.y = 1e8 - t.y;
    }
    int n;
    cin >> n;
    vector<PT> fountains(n);
    FOR(i,0,n-1) {
        cin >> fountains[i];
        if (downward) fountains[i].y = 1e8 - fountains[i].y;
    }

    vector<PT> window;
    for (auto p : fountains) {
        if (p.x >= s.x && p.x <= t.x && p.y >= s.y && p.y <= t.y) {
            window.push_back(p);
        }
    }
    sort(window.begin(), window.end());
    vector<int> Y(window.size());
    for (int i = 0; i < window.size(); i++){
        Y[i] = window[i].y;
    }
    vector<int> LIS = LongestIncreasingSubsequence(Y);
    int k = LIS.size();
