void update(long long nod, long long l, long long r)
{
    long long mid=(l+r)/2;
    if(l==r)
    {
        aint[nod]=d[i];
        return;
    }
    else
    {
        if(poz<=mid) update(2*nod,l,mid);
        else update(2*nod+1,mid+1,r);
        aint[nod]=max(aint[2*nod],aint[2*nod+1]);
    }
}

void query(long long nod, long long l, long long r)
{
    long long mid=(l+r)/2;
    if(l>=st && r<=dr) val=max(val,aint[nod]);
    else if(l!=r)
    {
        if(dr<=mid) query(2*nod,l,mid);
        if(st>mid) query(2*nod+1,mid+1,r);
    }
}

