bool outside(pair<int, int> a, pair<int, int> s, pair<int, int> g) {
  return a.first < s.first || g.first < a.first ||
         a.second < s.second || g.second < a.second;
}

long double dist(pair<int, int> a, pair<int, int> b) {
  long double res = (long double)b.first - (long double)a.first + (long double)b.second - (long double)a.second;
  return res * (long double)100.0;
}

