      val.push_back(a[i].second);
    }
  }
  vector<int> srd = val;
  int sz = val.size();
  sort(srd.begin(), srd.end());
  map<int, int> mp;
  for (int i = 0; i < sz; i++) mp[srd[i]] = i;
  segment_tree<int> sgt(sz, [](int a, int b) { return max(a, b); }, 0);
  for (int i = 0; i < sz; i++) {
    sgt.update(mp[val[i]], sgt.find(0, mp[val[i]]) + 1);
  }
  double pi = acos(0) * 2;
  int w = abs(t.first - s.first);
  int h = abs(t.second - s.second);
  int cnt = sgt.find(0, sz);
  double ret = 100 * (w + h);
  ret += cnt * (20 * pi / 4 - 20);
  if (w < cnt || h < cnt) ret += 20 * pi / 4;
  cout << setprecision(12) << ret << endl;
  return 0;
}

