const int N = 200010;
const double pi = acos(-1);
struct data {
	int x, y, pos;
	bool friend operator < (const data &a, const data &b) {
		return a.x == b.x ? a.y < b.y : a.x < b.x;		
	}
} a[N];
int n, X1, X2, Y1, Y2, cnt;
double ans;
int dp[N], tree[N], last[N], nxt[N], pre[N];
vector<int> v;
void update(int l, int r, int x, int pos, int d) 
{
	if(l == r)
	{
		tree[x] = d;
		return;
	}
	int mid = (l + r) >> 1;
	if(pos <= mid) update(l, mid, x << 1, pos, d);
	else update(mid + 1, r, x << 1 | 1, pos, d);
	tree[x] = max(tree[x << 1], tree[x << 1 | 1]);
}
int query(int l, int r, int x, int a, int b)
{
	if(l > b || r < a) return 0;
	if(l >= a && r <= b) return tree[x];
	int mid = (l + r) >> 1;
	return max(query(l, mid, x << 1, a, b), query(mid + 1, r, x << 1 | 1, a, b));
} 
int query(int x)
{
	int ret = 0;
	for(; x; x -= x & (-x)) ret = max(ret, tree[x]);
	return ret;
}
int main()
{
