		a[++cnt].x = x;
		a[cnt].y = y;
		v.push_back(y);
	}
	sort(v.begin(), v.end());
	sort(a + 1, a + cnt + 1);
	for(int i = 1; i <= cnt; ++i) a[i].pos = lower_bound(v.begin(), v.end(), a[i].y) - v.begin() + 1;
	for(int i = 1; i <= cnt; ++i)
	{
		if(last[a[i].pos]) pre[i] = last[a[i].pos], nxt[last[a[i].pos]] = i;
		else pre[i] = 1;
		last[a[i].pos] = i; 
	}
	for(int i = 1; i <= cnt; ++i) if(!nxt[i]) nxt[i] = cnt;
	for(int i = 1; i <= cnt; ++i) 
	{
		if(Y1 <= Y2) dp[i] = query(1, cnt, 1, a[i].pos, a[i].pos) + 1;	
		else dp[i] = query(1, cnt, 1, a[i].pos, cnt) + 1;
		update(1, cnt, 1, a[i].pos, dp[i]);
	}
