long double solve(){
    double res = 0;
    if(start.first==goal.first){
        auto swapp = [](pll &x){
            swap(x.first, x.second);
        };
        swapp(start);
        swapp(goal);
        foreach(i, supring){
            swapp(i);
        }
    }
    if(start.second>goal.second){
        auto flip = [](pll &x){
            return x = pll(x.first, -x.second);
        };
        flip(start);
        flip(goal);
        foreach(i, supring){
            flip(i);
        }
    }
    if(start.first>goal.first){
        auto flip = [](pll &x){
            return x = pll(-x.first, x.second);
        };
        flip(start);
        flip(goal);
        foreach(i, supring){
            flip(i);
        }
    }
    if(start.second==goal.second){
        foreach(i, supring){
            if(i.second!=start.second)continue;
            if(start.first<=i.first&&i.first<goal.first){
                return abs(start.first-goal.first)*100 + half_cir - 20;
            }
        }
        return abs(start.first-goal.first) * 100;
    }
    vector<ll> memo(n+2, INFLL);
    sort(all(supring));
    foreach(i, supring){
        if(i.first<start.first||goal.first<i.first)continue;
        if(i.second<start.second||goal.second<i.second)continue;
        *lower_bound(all(memo), i.second) = i.second;
    }

    rep(i, n+2){
        if(memo[i]!=INFLL){
            chmin(res, (i+1)*(quot_cir-20));
        }
    }
    return (abs(start.first-goal.first)+abs(start.second-goal.second))*100+res;
}

