            //if (ma[id[i] + 1] <= v[i]) info[i] = 1;
            // 広義単調増加列
            if (ma[id[i] + 1] < v[i]) info[i] = 1;

            else cnt[id[i]]++, ma[id[i]] = max(ma[id[i]], v[i]);
        }

        rrep(i, n - 1, 0) if (info[i] == 0 && cnt[id[i]] == 1) info[i] = 3;
        rep(i, 0, n) if (info[i] == 0) info[i] = 2;
    }
};

