#include <bits/stdc++.h>
using namespace std;

constexpr int kInf = 100'000'000;

struct SegTree {
    vector<double> st;
    int n;

    SegTree(int n) : n(n) { st.resize(n * 4, -kInf); }
    void Modify(int p, double v) { Modify(0, n, p, v); }
    double Query(int l, int r) { return Query(0, n, l, r); }
    double Query(int p) { return Query(0, n, 0, p + 1); }

    void Modify(int l, int r, int p, double v, int o = 0) {
        if (r - l == 1) {
            st[o] = v;
            return;
        }
        int m = (l + r) >> 1;
        if (p < m) Modify(l, m, p, v, o * 2 + 1);
        else Modify(m, r, p, v, o * 2 + 2);
        st[o] = max(st[o * 2 + 1], st[o * 2 + 2]);
    }

    double Query(int l, int r, int ql, int qr, int o = 0) {
        if (l >= qr || ql >= r) return -kInf;
        if (l >= ql && r <= qr) return st[o];
        int m = (l + r) >> 1;
        return max(Query(l, m, ql, qr, o * 2 + 1), Query(m, r, ql, qr, o * 2 + 2));
    }
};

int main() {
    int x1, y1, x2, y2; scanf("%d%d%d%d", &x1, &y1, &x2, &y2);
    int n; scanf("%d", &n);
    vector<int> x(n), y(n);
    for (int i = 0; i < n; ++i) scanf("%d%d", &x[i], &y[i]);

    constexpr int kMod = 100'000'000;

    if (x1 > x2) {
        x1 = kInf - x1;
        x2 = kInf - x2;
        for (int i = 0; i < n; ++i) x[i] = kInf - x[i];
    }
    if (y1 > y2) {
        y1 = kInf - y1;
        y2 = kInf - y2;
        for (int i = 0; i < n; ++i) y[i] = kInf - y[i];
    }

    constexpr double kDiff = 20 - 5 * acos(-1);
    constexpr double kDiff2 = 20 - 10 * acos(-1);

    if (x1 == x2) {
        int cnt = 0;
        for (int i = 0; i < n; ++i) {
            if (x[i] == x1 && y[i] >= y1 && y[i] <= y2) cnt++;
        }
        double ans = 100.0 * (y2 - y1) - cnt * kDiff2;
        printf("%.20lf\n", ans);
        return 0;
    }
    if (y1 == y2) {
        int cnt = 0;
        for (int i = 0; i < n; ++i) {
            if (y[i] == y1 && x[i] >= x1 && x[i] <= x2) cnt++;
        }
        double ans = 100.0 * (x2 - x1) - cnt * kDiff2;
        printf("%.20lf\n", ans);
        return 0;
    }
    x.resize(n + 2);
    y.resize(n + 2);
    x[n] = x1;
    y[n] = y1;
    x[n + 1] = x2;
    y[n + 1] = y2;
    n += 2;
    vector<int> ds(y.begin(), y.end());
    ds.push_back(y1), ds.push_back(y2);
    sort(ds.begin(), ds.end());
    vector<int> dy(n);
    for (int i = 0; i < n + 1; ++i) {
        dy[i] = lower_bound(ds.begin(), ds.end(), y[i]) - ds.begin();
    }
    vector<int> ord;
    SegTree st1(ds.size()), st2(ds.size());
    vector<double> dp1(n, -kInf), dp2(n, -kInf);

    for (int i = 0; i < n; ++i) {
        if (x[i] < x1 || x[i] > x2 || y[i] < y1 || y[i] > y2) continue;
        ord.push_back(i);
    }
    sort(ord.begin(), ord.end(), [&](int i, int j) { 
        if (x[i] == x[j]) return y[i] < y[j];
        return x[i] < x[j];
    });

    dp1[ord[0]] = 0;
    for (int i = 0, j = 0; i < ord.size(); ++i, i = j) {
        double prv = -kInf;
        for (j = i; j < ord.size() && x[ord[i]] == x[ord[j]]; ++j) {
            if (i == 0) {
                if (j > 0) dp2[ord[j]] = (j - 1) * kDiff2 + kDiff;
            } else {
                dp1[ord[j]] = max(st1.Query(dy[ord[j]] - 1) + kDiff, st1.Query(dy[ord[j]]) + kDiff2);
                dp1[ord[j]] = max(dp1[ord[j]], st2.Query(dy[ord[j]]) + kDiff);
                if (j > i) dp2[ord[j]] = prv + (j - 1) * kDiff2 + kDiff;
                prv = max(prv, dp1[ord[j]] - j * kDiff2);
            }
            // printf("dp1[%d] = %lf dp2[%d] = %lf\n", ord[j], dp1[ord[j]], ord[j], dp2[ord[j]]);
        }
        for (int k = i; k < j; ++k) {
            st1.Modify(dy[ord[k]], dp1[ord[k]]);
            st2.Modify(dy[ord[k]], dp2[ord[k]]);
        }
    }
    // printf("kDiff = %.20lf\n", kDiff);
    double ans = 100.0 * (x2 - x1 + y2 - y1) - (max(dp1[n - 1], dp2[n - 1]) - kDiff);
    printf("%.20lf\n", ans);
}

