    auto cmp_2 = [](const PLL& a, const PLL& b) {
        return a.first < b.first && a.second > b.second;
    };
    auto cmp = y1 <= y2 ? cmp_1 : cmp_2;

    int used = 0;
    for (int i = 0; i < n; ++i) {
        dp[i] = 1;
        for (int j = 0; j < i; ++j) {
            if (cmp(p[j], p[i])) dp[i] = max(dp[i], dp[j] + 1);
        }
        used = max(used, dp[i]);
    }
    int max_corner = min(x2 - x1, y_max - y_min);

    if (used < max_corner + 1) res += used * (quarter_circle - 2 * R);
    else res += max_corner * (quarter_circle - 2 * R) + (2 * quarter_circle - 2 * R);

    printf("%.15f\n", res);

    return 0;
}

