struct RMQ{
  int n;
  vector<double> dat;
  const double def=1e15;
  RMQ(){}
  RMQ(int n_){init(n_);}
  void init(int n_){
    n=1;
    while(n<n_) n*=2;
    dat.clear();
    dat.resize(2*n-1,def);
  }
  void update(int k,double a){
    k+=n-1;
    dat[k]=a;
    while(k>0){
      k=(k-1)/2;
      dat[k]=min(dat[k*2+1],dat[k*2+2]);
    }
  }
  double query(int a,int b,int k,int l,int r){
    if(r<=a||b<=l) return def;
    if(a<=l&&r<=b) return dat[k];
    double vl=query(a,b,k*2+1,l,(l+r)/2);
    double vr=query(a,b,k*2+2,(l+r)/2,r);
    return min(vl,vr);
  }
  double query(int a,int b){
    return query(a,b,0,0,n);
  }
  double query(int k){
    return dat[k+n-1];
  }
};

