    }
    x2 = (x2 - x1) * a;
    y2 = (y2 - y1) * b;
    x1 = y1 = 0;
    map<int, set<int>> fountain;
    for (int i = 0; i < N; i++) {
        if (0 <= X[i] && X[i] <= x2 && 0 <= Y[i] && Y[i] <= y2) {
            fountain[Y[i]].insert(X[i]);
        }
    }
    const double A = -20 + 5 * PI;
    const double B = -20 + 10 * PI;
    int last = -1;
    map<int, double> state = { {0, 0.0}, {1, 1e18} };
    if (fountain.size() == 0) state = { {0, 0.0} };
    for (auto &line : fountain) {
        if (line.first != last + 1) {
            double minimum = +1e18;
            for (auto it = begin(state); it != end(state);) {
                if (it->second >= minimum) {
                    it = state.erase(it);
                } else {
                    minimum = it->second;
                    ++it;
                }
            }
        }
        last = line.first;
        vector<int> pos;
        for (auto &s : state) pos.push_back(s.first);
        for (auto &p : line.second) {
