        for (auto &p : line.second) {
            fnt[lower_bound(begin(pos), end(pos), p) - begin(pos)] = 1;
        }
        int i = -1; double v = 0;
        for (auto &s : state) {
            if (i < 0) { i = 0, v = s.second; continue; }
            for (; pos[i] < s.first; i++) base[i] = v;
            v = s.second;
        }
        for (; i < pos.size(); i++) base[i] = v;
        double curr = +1e18;
        for (int i = 0; i < pos.size(); i++) {
            if (fnt[i]) {
                out[i] = min(curr + A, base[i] + B);
                curr = min(curr + B, base[i] + A);
            } else {
                out[i] = curr = min(curr, base[i]);
            }
        }
        map<int, double> newstate;
        double last = 1e18;
