    if (x1 > x2) {
        swap(x1, x2);
        swap(y1, y2);
    }
    bool flip = false;
    if (y1 > y2) {
        flip = true;
        y1 = MAXC - y1;
        y2 = MAXC - y2;
    }
    int left = x1, right = x2, bot = y1, top = y2;
    int n;
    scanf("%d", &n);
    vector<pt> a;
    for (int i = 0; i < n; ++i) {
        int x, y;
        scanf("%d %d", &x, &y);
        if (flip) 
            y = MAXC - y;
        if (left <= x && x <= right &&
            bot <= y && y <= top)
            a.push_back(pt(x, y));
    }
    n = a.size();
    sort(a.begin(), a.end());
    unordered_map<int, int> dp;
    for (int i = 0; i < n; ++i) {
        int cnt = get(1, 0, MAXC, 0, max(0, a[i].y - 1));
        dp[a[i].y] = max(dp[a[i].y], cnt + 1);
        upd(1, 0, MAXC, a[i].y, dp[a[i].y]);
    }
    long double ans = (x2 - x1) + abs(y2 - y1);
    int cc = get(1, 0, MAXC, 0, MAXC);
    if (x1 == x2 || y1 == y2)
        ans = ans * 100.0 + (pi * 10.0 - 20.0) * cc;
    else
        ans = ans * 100.0 - fo * cc;
    printf("%.11Lf", ans);
    return 0;
}

