bool inside(int x, int a, int b) {
  return min(a, b) <= x and x <= max(a, b);
}

long long dist(int x1, int y1, int x2, int y2) {
  return abs(x1 - x2) + abs(y1 - y2);
}

int LIS(vector<int> &v) {
  vector<int> lis;

  for (auto &x : v) {
    auto it = upper_bound(lis.begin(), lis.end(), x);
    if (it == lis.end()) {
      lis.push_back(x);
    } else {
      *it = x;
    }
  }

  return lis.size();
}

