int cn()//数最多有序的个数
{
    if(!cnt)
        return 0;
    sort(a,a+cnt,cmp);ge=1;
    if(cnt>=2)
    {
        if((a[cnt-2].y==ys2&&a[cnt-1].x==xs2)||(ys2==ys1)||xs2==xs1)
            ma=true;//没的选
    }
    if(cnt==1)
        if(ys2==ys1||xs2==xs1)
            ma=true;
    dp[0]=a[0].y;
    int re=1;
    tran=0;
    if(a[0].y==ys2||a[0].x==xs2)
    {
        ++tran;
    }
    else
        re2=re;
    for(int i=1;i<cnt;i++)
    {
        int l=0,r=ge-1,mid,ans=-1;
        while(l<=r)
        {
            mid=(l+r)/2;
            if(((dp[mid]-a[i].y)>0)==sty)
            {
                l=mid+1;
                ans=mid+1;
            }
            else
                r=mid-1;
        }
        if(ans!=-1)
        {
                dp[ans]=a[i].y,ge=ans+1;
                if(ge>re)
                {
                    re=ge;//包括必须走的
                    if(a[i].y==ys2||a[i].x==xs2)//有一个在
                    {
                        ++tran;
                    }
                    else
                        re2=re;//不必须走
                }
                if(ge>re2)
                {
                    if(a[i].y==ys2||a[i].x==xs2)
                        continue;
                    else
                        re2=ge;
                }
        }
        else
        {
            dp[0]=a[i].y,ge=1;
        }
    }
    return re;
}
