inline void update(int now)
{
	t[now]=max(t[now<<1],t[now<<1|1]);
}
void add(int p,int l,int r,int now,int num)
{
	if(l==r){t[now]=max(t[now],num);return;}
	int mid=(l+r)>>1;
	if(p<=mid) add(p,l,mid,now<<1,num);
	else add(p,mid+1,r,now<<1|1,num);
	update(now);
}
int ask(int L,int R,int l,int r,int now)
{
	if(L>R) return 0;
	if(L<=l&&r<=R) return t[now];
	int mid=(l+r)>>1,ans=0;
	if(L<=mid) ans=ask(L,R,l,mid,now<<1);
	if(R>mid) ans=max(ans,ask(L,R,mid+1,r,now<<1|1));
	return ans;
}
