    }
    sort(b+1, b+1+tot);
    int mx=0;
    for(int i=1;i<=tot;++i) {
        int pos=upper_bound(dp+1, dp+1+n, b[i].sd)-dp;
        dp[pos]=min(dp[pos], b[i].sd);
        mx=max(mx, pos);
    }
    // cerr<<mx<<endl;
    if(mx==tx-sx+1 || mx==ty-sy+1) {
        printf("%.15f\n", 100.*(tx-sx+ty-sy)+(mx-1)*(5.*PI-20.)+10.*PI-20.);
    } else {
