LL a[Max],N,dp[Max],c[Max];

LL bin(LL len,LL x)
{
	LL low = 0,high = len,mid,ans = -1;
	while(low <= high)
	{
		mid = (low + high) / 2;
		LL my = c[mid];
		if( my < x )
		{
			ans = mid;
			low = mid + 1;
		}
		else high = mid - 1;
	}
	assert( ans != -1 );
	assert( c[ans] < x && x <= c[ans+1] );
	return ans + 1;
}

LL LIS()
{
    LL len = 1,i;
    c[0] = -1;
    c[1] = a[1];
    dp[1] = 1;
    for(i = 2; i <= N; i++)
    {
        if(a[i] < c[1])
        {
            c[1] = a[i];
            dp[i] = 1;
        }
        else if(a[i] > c[len])
        {
            len++;
            c[len] = a[i];
            dp[i] = len;
        }
        else
        {
            LL k = bin(len,a[i]); /*we want to find k so that c[k-1] < ara[i] <= c[k]*/
            c[k] = a[i];
            dp[i] = k;
        }
    }
    LL ret = 0;
    rep(i,N) ret = max(ret,dp[i]);
    return ret;
}

