template <class IT> int count_lis(const IT &beg, const IT &end) {
  int n = end - beg;
  const auto inf = numeric_limits<typename IT::value_type>::max();
  vector<typename IT::value_type> dp(n, inf);
  for (auto it = beg; it < end; it++) *lower_bound(dp.begin(), dp.end(), *it) = *it;
  return lower_bound(dp.begin(), dp.end(), inf) - dp.begin();
}

double solve() {
	int x1 = ri(), y1 = ri(), x2 = ri(), y2 = ri();
	int n = ri();

	if (y1 > y2 && x1 > x2) {
		out("swap1");
		swap(x1, x2);
		swap(y1, y2);
	}

	vpii F(n);

	vi X(n);

	rep(i, n) {
		F[i].X = ri();
		F[i].Y = ri();
		X[i] = F[i].X;
	}

	const long double PI = 3.1415926535897932384626;
	const long double bene = 20 - 10 * 2 * PI / 4;
	const long double loss = 10 * 2 * PI / 2 - 20;
	ll massugu = (abs(x1 - x2) + abs(y1 - y2)) * ((ll) 100);

	out(bene, loss, massugu);

	if (x1 == x2) {
		int mi = min(y1, y2);
		int ma = max(y1, y2);
		int cnt = 0;
		rep(i, n) {
			if (F[i].X == x1) {
				if (F[i].Y >= mi && F[i].Y <= ma) cnt++;
			}
		}
		return massugu + loss * cnt;
	}

	if (y1 == y2) {
		int mi = min(x1, x2);
		int ma = max(x1, x2);
		int cnt = 0;
		rep(i, n) {
			if (F[i].Y == y1) {
				if (F[i].X >= mi && F[i].X <= ma) cnt++;
			}
		}
		return massugu + loss * cnt;
	}

	X.emplace_back(x1);
	X.emplace_back(x2);
	sort(all(X));
	X.erase(unique(X.begin(), X.end()), X.end());

	const int inf = 1e9;

	auto comp = [&](int x) {
		return lower_bound(all(X), x) - X.begin();
	};

	int c1 = comp(x1);
	int c2 = comp(x2);

	rep(i, n) {
		F[i].X = comp(F[i].X);
	}

	if (c1 > c2) {
		out("swap2");
		rep(i, n) {
			F[i].X = c1 - F[i].X;
		}
		c2 = c1 - c2;
		c1 = 0;
		swap(x1, x2);
	}

	if (y1 > y2) {
		out("swap3");
		rep(i, n) {
			F[i].Y = y1 - F[i].Y;
		}
		y2 = y1 - y2;
		y1 = 0;

		int mi = 0;
		rep(i, n) amin(mi, F[i].Y);

		rep(i, n) {
			F[i].Y -= mi;
		}
		y1 -= mi;
		y2 -= mi;
	}

	vi A(c2 - c1 + 1, inf);
	rep(i, n) {
		if (F[i].X >= c1 && F[i].X <= c2) {
			A[F[i].X-c1] = F[i].Y;
		}
	}

	vi B;
	forr(a, A) {
		if (a >= y1 && a <= y2) B.emplace_back(a + 1);
	}


	int lis = count_lis(all(B));
	out(massugu, lis);

	long double ans;
	out(y1, y2);
	out(x1, x2, c1, c2);
	int mind = min(y2 - y1, x2 - x1) + 1;

	if (lis && lis == mind) {
		out("p1");
		ans = massugu - (bene * (lis - 1) - loss);
	}
	else {
		out("p2");
		ans = massugu - bene * lis;
	}

	return ans;
}

void Main() {
	cout << fixed << setprecision(10);
	cout << solve() << endl;
}
