void update(ll idx,ll lo,ll hi,ll st,ll en,ll val){
    if(lo==st&&hi==en) {
        seg[idx]+=val;
        return;
    }

    ll mid=(lo+hi)/2;
    if(en<=mid) update(2*idx,lo,mid,st,en,val);
    else if(st>mid) update(2*idx+1,mid+1,hi,st,en,val);
    else{
        update(2*idx,lo,mid,st,mid,val);
        update(2*idx+1,mid+1,hi,mid+1,en,val);
    }
    seg[idx]=max(seg[2*idx],seg[2*idx+1]);
}
ll query(ll idx,ll lo,ll hi,ll st,ll en){
    if(lo==st&&hi==en) return seg[idx];

    ll mid=(lo+hi)/2;
    if(en<=mid) return query(2*idx,lo,mid,st,en);
    else if(st>mid) return query(2*idx+1,mid+1,hi,st,en);
    else return max(query(2*idx,lo,mid,st,mid),query(2*idx+1,mid+1,hi,mid+1,en));
}

