}

long double solve() {
  if (!n) return (t.first + t.second - s.first - s.second) * 100;
  for (int i = 0; i < n; ++i) {
    int id = mp[v[i].second];
    P now(0, 0);
    {  // over
      P tmp;
      if (id != 0) {
        tmp = seg.query(0, id);
        ++tmp.first, ++tmp.second;
        now = minP(now, tmp);
      }
      tmp = seg.query(id, id + 1);
      ++tmp.first, ++tmp.second;
      now = minP(now, tmp);
      if (id + 1 != mp.size()) seg.update(id + 1, mp.size(), dat(now, 0));
    }
    {  // just
      P tmp;
      now = P(0, 0);
      tmp = seg.query(id, id + 1);
      ++tmp.first, ++tmp.second;
      now = minP(now, tmp);
      if (id != 0) {
        tmp = seg.query(0, id);
        ++tmp.first, ++tmp.second;
        now = minP(now, tmp);
      }
      seg.update(id, id + 1, dat(now, 1));
    }
  }
  P res;
  if (n && v[n - 1].first == t.first)
    res = seg.query(mp[v[n - 1].second], mp.size());
  else
    res = seg.query(0, mp.size());
  if (n == mp.size() || n == (t.first - s.first + 1)) ++res.first;
  return calc(res) + (t.first + t.second - s.first - s.second) * 100;
}

