int ypos_cnt[2000001];


int get_change_cnt(int y, int max_cnt)
{
	int min_pos = 0;
	int max_pos = max_cnt+1;
	int mid_pos = (min_pos+max_pos+1)/2;

	for(;;) {
		if (y < ypos_cnt[mid_pos]) {
			max_pos = mid_pos;
		} else if (ypos_cnt[mid_pos] < y) {
			min_pos = mid_pos;
		}
		mid_pos = (min_pos+max_pos+1)/2;
		if (min_pos == mid_pos) {
			return min_pos+1;
		}
		if (max_pos == mid_pos) {
			return max_pos;
		}
	}
}


