vector<vector<int> > x_sort, y_sort;
void create_rmq(int i, int l, int r){
	if (r - l == 1){
		rmq[i].dp = 0;
	}
	else{
		int mid = (l + r) / 2;
		create_rmq(2*i+1, l, mid);
		create_rmq(2*i+2, mid, r);
		rmq[i].dp = 0;
	}
}
void add(int i, int l, int r, int ind, int value){
    if (r - l == 1){
		rmq[i].dp = value;
    }
    else{
		int mid = (l + r) / 2;
		if (ind < mid) add(2*i+1, l, mid, ind, value);
		else add(2*i+2, mid, r, ind, value);
		rmq[i].dp = max(rmq[2*i+1].dp, rmq[2*i+2].dp);
    }
}
int get(int i, int l, int r, int l1, int r1){
	if (l1 >= r1) return 0;
	if (l == l1 && r == r1) return rmq[i].dp;
	int mid = (l + r) / 2;
	return max(get(2*i+1, l, mid, l1, min(r1, mid)), get(2*i+2, mid, r, max(l1, mid), r1));
}
