template <typename RandomAccessIterator>
size_t lis_length(RandomAccessIterator first, RandomAccessIterator last) {
    using T = typename remove_reference<decltype(*first)>::type;
    size_t r = 0;
    vector<T> dp(distance(first, last), numeric_limits<T>::max());
    for (RandomAccessIterator vtr = first; vtr != last; ++vtr) {
        const T &x = *vtr;
        auto itr = lower_bound(dp.begin(), dp.end(), x);
        *itr = x;
        r = max<size_t>(r, itr - dp.begin() + 1);
    }
    return r;
}

constexpr ld pi              = M_PIl;
constexpr ld corner_shortcut = 20 - pi * 5;
constexpr ld detour          = pi * 10 - 20;

ld solve_regular(const vector<pair<ll, ll>> &yx, ll x1, ll y1, ll x2, ll y2) {

    auto ltr = lower_bound(ALL_OF(yx), make_pair(y1, 0LL));
    auto rtr = lower_bound(ALL_OF(yx), make_pair(y2+1, 0LL));

    ld ans = (abs(x1-x2) + abs(y1-y2)) * 100;

    vector<ll> xc;
    for (auto itr = ltr; itr < rtr; itr++) {
        ll xf = itr->second;
        if (min(x1, x2) <= xf && xf <= max(x1, x2)) {
            xc.push_back(xf);
        }
    }

    if (x1 > x2) for (ll &x : xc) x *= -1;
    ll lisl = lis_length(ALL_OF(xc));
    ans -= lisl * corner_shortcut;

    return ans;

}

ld solve_along_x_axis(const vector<pair<ll, ll>> &yx, ll x1, ll x2, ll y) {

    ld ans = abs(x1 - x2) * 100;
    auto itr = lower_bound(ALL_OF(yx), make_pair(y, 0LL));
    if (itr != yx.end() && min(x1, x2) < itr->second && itr->second < max(x1, x2)) {
        ans += detour;
    }

    return ans;

}

ld solve_along_y_axis(const vector<pair<ll, ll>> &yx, ll x, ll y1, ll y2) {

    if (y2 < y1) swap(y1, y2);

    map<ll, vector<ll>> m;

    vector<ll> dxs;

    for (const auto &p : yx) {
        ll yf, xf; tie(yf, xf) = p;
        if(y1 <= yf && yf <= y2) {
            dxs.push_back(abs(x - xf));
            m[xf].push_back(yf);
        }
    }

    ll minemptydx = LINF;
    sort(ALL_OF(dxs));
    if (dxs.front() > 0 || dxs.empty()) return abs(y1 - y2) * 100;
    REP(i, dxs.size()) if (dxs[i+1] - dxs[i] > 1) {
        minemptydx = dxs[i]+1;
        break;
    }
    ld ans = minemptydx * 200 + abs(y1 - y2) * 100;

    for (const auto &p : m) {
        const ll xc = p.first;
        const vector<ll> yc = p.second;
        ld cand = (abs(xc - x) * 2 + abs(y2 - y1)) * 100;
        cand -= (yc.front() == y1) * corner_shortcut;
        cand -= (yc.back () == y2) * corner_shortcut;
        for (const ll &yci : yc) if (y1 < yci && yci < y2) cand += detour;
        chmin(ans, cand);
    }

    return ans;

}

