template<class Value = int>
class SegmentTree{
  int n;
  vector<Value> V;
  Value DEFAULT_VALUE;

  //evaluation function
  static Value default_evaluate(Value a, Value b){
    return max(a,b);
  }

  function< Value(Value, Value) > evaluate;

  //return evaluated value in [a,b)
  //T[at] covers [l,r)
  Value RangeEvaluation(int a, int b, int at, int l, int r){
    //out of range
    if(r <= a || b <= l) return DEFAULT_VALUE;
    //covered
    if(a <= l && r <= b) return V[at];

    //partially covered
    else{
      Value val_left = RangeEvaluation(a,b, at*2+1, l, (l+r)/2);
      Value val_right = RangeEvaluation(a,b, at*2+2, (l+r)/2, r);
      return evaluate(val_left, val_right);
    }
  }

 public:
  SegmentTree(int size, Value DEFAULT = 0, function< Value(Value, Value) > eval = default_evaluate){
    DEFAULT_VALUE = DEFAULT;
    evaluate = eval;
    n=1;
    while(n<size) n <<= 1;
    V = vector<Value>(2*n - 1, DEFAULT_VALUE);
  }

  void update(int at, Value new_val){
    at += n-1;
    V[at] = new_val;
    while(at>0){
      at = (at-1)/2;
      V[at] = evaluate(V[at*2 + 1], V[at*2 + 2]);
    }
  }


  //return evaluated value in [l,r)
  Value RangeEvaluation(int l, int r){
    if(l>=r) return DEFAULT_VALUE;
    if(l>=n) return DEFAULT_VALUE;
    return RangeEvaluation(l,r, 0, 0, n);
  }
};

template<class T>
vector<T> compress(vector<T> a, vector<T>& b){
  b = a;
  sort(b.begin(), b.end());
  b.erase( unique(b.begin(), b.end()), b.end());
  for(int i=0; i<a.size(); i++){
    a[i] = lower_bound(b.begin(), b.end(), a[i]) - b.begin();
  }
  return a;
}

int main(){
  pair<int,int> s, t;
  cin >> s,t;

  int n;
  cin >> n;
  vector<pair<int,int>> f(n);
  cin >> f;

  // 右上へ
  if( s.first > t.first ){
    s.first *= -1;
    t.first *= -1;
    for(int i=0; i<n; i++){
      f[i].first *= -1;
    }
  }
  if( s.second > t.second ){
    s.second *= -1;
    t.second *= -1;
    for(int i=0; i<n; i++){
      f[i].second *= -1;
    }
  }
  assert( s.first <= t.first );
  assert( s.second <= t.second );

  if( s.first == t.first ){
    double ans = (t.second - s.second) * 100;
    for(int i=0; i<n; i++){
      if( f[i].first != s.first ) continue;
      if( f[i].second < s.second ) continue;
      if( f[i].second > t.second ) continue;
      ans += 10*PI - 20;
    }
    printf("%.16f\n", ans);
    return 0;
  }

  if( s.second == t.second ){
    double ans = (t.first - s.first) * 100;
    for(int i=0; i<n; i++){
      if( f[i].second != s.second ) continue;
      if( f[i].first < s.first ) continue;
      if( f[i].first > t.first ) continue;
      ans += 10*PI - 20;
    }
    printf("%.16f\n", ans);
    return 0;
  }

  map<int, vector<int>> xx;
  vector<int> yy;
  for(int i=0; i<n; i++){
    yy.push_back( f[i].second );
    if( f[i].first < s.first ) continue;
    if( f[i].first > t.first ) continue;
    xx[ f[i].first ].push_back( i );
  }

  xx[ s.first ].push_back( -1 );
  // yy.push_back( s.second );
  xx[ t.first ].push_back( n );
  yy.push_back( t.second );
  f.push_back( t );


  vector<int> dict_y;
  auto y_ = compress(yy, dict_y);

  SegmentTree<int> seg(y_.size()+1);

  auto itr = xx.begin();
  for(int i=0; i<xx.size(); i++){
    // 端以外は高々 1 つ
    for(auto idx : itr->second){
      if(idx == -1) continue;
      if(idx == n ) continue;
      int y = y_[idx];
      int cnt = seg.RangeEvaluation(0, y);
      cnt++;
      int cnt2 = seg.RangeEvaluation(y, y+1);

      seg.update( y, max(cnt,cnt2) );
    }
    itr = next(itr);
  }

  int mx_f = seg.RangeEvaluation(0, y_[n]+1);
  double ans = 100 * (t.first - s.first + t.second - s.second);
  ans += (5*PI - 20) * mx_f;

  printf("%.16f\n", ans);


  return 0;
}

