int len;
int a[MaxN + 5], d[MaxN + 5];

int bin_search(int x) {
	int l = 0, r = len;
	int mid = 0, ans = 0;
	while(l <= r) {
		mid = (l + r) >> 1;
		if(d[mid] >= x) ans = mid, r = mid - 1;
		else l = mid + 1;
	}
	return ans;
}

void getlen()
{
	len = 0;
	for(int i = 1; i <= tot; i++) {
		a[i] = tmp[i].y;
		//printf("%d ", a[i]);
	}
	//printf("\n");
	for(int i = 1; i <= tot; i++) {
		if(a[i] > d[len]) d[++len] = a[i];
		else {
			int pos = bin_search(a[i]);
			d[pos] = a[i];
		}
	}
}

