inline void umax(int& a, int b)
{
	if (b > a) a = b;
}

struct Node{
	int x, y;
	bool operator<(const Node& o) const
	{
		return x < o.x;
	}
}a[N];

struct BIT{
	int dp[N];
	bool f[N];
	int n;
	void init(int _n)
	{
		n = _n;
		memset(dp, 0, sizeof dp);
		memset(f, 0, sizeof f);
	}
	void modify(int i, int val, bool sta)
	{
		for (; i <= n; i += i & -i)
		{
			if (val > dp[i]) dp[i] = val, f[i] = sta;
			else if (val == dp[i]) f[i] |= sta;
		}
	}
	Node query(int i)
	{
		Node ret = Node{0, 1};
		for (; i; i -= i & -i)
		{
			if (dp[i] > ret.x) ret = Node{dp[i], f[i]};
			else if (dp[i] == ret.x) ret.y |= f[i];
		}
		return ret;
	}
}bit;

int main()
{
	int x1, y1, x2, y2; scanf("%d%d%d%d", &x1, &y1, &x2, &y2);
