	int p = -1, maxv = 0;
	for (int i = 0; i < cnt; i++)
	{
		int k = lower_bound(b, b + cnt, a[i].y) - b;
		if (a[i].x == x1 || a[i].y == y1)
		{
			bit.modify(k + 1, 1, 0);
			continue;
		}
		Node tmp = bit.query(k);
		bit.modify(k + 1, tmp.x + 1, tmp.y);
	}
	Node tmp = bit.query(cnt);
