      ps.emplace_back(x, y);
    }
  }
  sort(ps.begin(), ps.end());
  map<int, int> map_y;
  for (auto& p : ps) {
    map_y[p.second];
  }
  int size_y = 0;
  for (auto& it : map_y) {
    it.second = size_y++;
  }
  for (auto& p : ps) {
    p.second = map_y[p.second];
  }
  if (x1 > x2) {
    swap(x1, x2);
    swap(y1, y2);
  }
  fenwick f((int) ps.size());
  if (y1 > y2) {
    reverse(ps.begin(), ps.end());
  }
  int use = 0;
  for (int i = 0; i < (int) ps.size(); i++) {
