#include<bits/stdc++.h>
#define lowbit(x) ((x)&(-x))
using namespace std;

const int maxn = 200009;
const long double r = acos(-1) * 5;
int x[maxn], y[maxn], X[maxn], rk[maxn], c[maxn], f[maxn];
int sx, sy, tx, ty, n, N, cnt, flag, ans, p, flag2;

int search(int k){
	int l = 1, r = cnt, mid;
	while (l < r){
		mid = (l + r) >> 1;
		if (k <= X[mid]) r = mid;
		else l = mid + 1;
	}
	return l;
}

bool cmp(int a, int b){
	return y[a] < y[b];
}

void update(int x, int y){
	for (; x<=cnt; x+=lowbit(x)) c[x] = max(c[x], y);
}

int query(int x){
	int res = 0;
	for (; x; x-=lowbit(x)) res = max(res, c[x]);
	return res;
}

int main(){
	scanf("%d%d%d%d%d", &sx, &sy, &tx, &ty, &n);
	if (sx <= tx && sy > ty){
		flag = 1; 
		sy = 1e8 - sy; ty = 1e8 - ty;
	}
	else if (sx > tx && sy > ty){
		flag = 2; 
		sx = 1e8 - sx; sy = 1e8 - sy;
		tx = 1e8 - tx; ty = 1e8 - ty;
	}
	else if (sx > tx && sy <= ty){
		flag = 3; 
		sx = 1e8 - sx; tx = 1e8 - tx;
	}
	for (int i=1; i<=n; i++){ N++;
		scanf("%d%d", &x[N], &y[N]);
		if (flag == 1) y[N] = 1e8 - y[N];
		else if (flag == 2) { x[N] = 1e8 - x[N]; y[N] = 1e8 - y[N]; }
		else if (flag == 3) x[N] = 1e8 - x[N];
		if (x[N] < sx || x[N] > tx || y[N] < sy || y[N]  > ty){
			N--; continue;
		}
		X[++cnt] = x[N]; rk[N] = N;
	}
	sort(X+1, X+cnt+1); 
	if (sx == tx || sy == ty || !N){
		if (N) printf("%.16Lf\n", 100*(tx-sx + ty-sy) - 20 + 2*r);
		else printf("%.16Lf\n", 100*(tx-ty + ty-sy));
		return 0;
	}

	flag2 = (y[rk[1]] - sy != 0);
	for (int i=1; i<=N; i++){
		p = rk[i];
		f[i] = query(search(x[p])) + 1;
		if (f[i] != f[i-1] + 1 || i >= 2 && y[p] - y[rk[i-1]] != 1) flag2 = 1;
		ans = max(ans, f[i]);
		update(search(x[p]), f[i]);
	}
	flag2 |= (ty - y[rk[N]] != 0);
	if (flag2) printf("%.16Lf\n", 100.0*(tx-sx + ty-sy) + ans*(r-20));
	else printf("%.16Lf\n", 100.0*(tx-sx + ty-sy) + ans*(r-20) + r);

