using ll = long long;
const int N = 200500;
const double PI = acos(-1);

struct FenTree
{
    int a[N];
    FenTree(): a() {}
    void relax(int v, int x)
    {
        for (int i = v; i < N; i |= i + 1)
            a[i] = max(a[i], x);
    }
    int get(int v)
    {
        int s = 0;
        for (int i = v; i >= 0; i = (i & (i + 1)) - 1)
            s = max(s, a[i]);
        return s;
    }
};

int x1, y1, x2, y2;
vector<int> ys;
vector<pair<int, int>> founts;
FenTree fen;

void make_unique(vector<int>& v)
{
    sort(v.begin(), v.end());
    v.resize(unique(v.begin(), v.end()) - v.begin());
}

int get_crd(const vector<int>& v, int x)
{
    return lower_bound(v.begin(), v.end(), x) - v.begin();
}

void solve()
{
    scanf("%d%d%d%d", &x1, &y1, &x2, &y2);

    if (x1 == x2)
    {
        int n;
        scanf("%d", &n);
        double cost = abs(y2 - y1) * 100.0;
        for (int i = 0; i < n; i++)
        {
            int x, y;
            scanf("%d%d", &x, &y);
            if (x == x1 && min(y1, y2) <= y && y <= max(y1, y2))
                cost += 10 * PI - 20;
        }
        printf("%.20lf\n", cost);
        return;
    }

    if (y1 == y2)
    {
        int n;
        scanf("%d", &n);
        double cost = abs(x2 - x1) * 100.0;
        for (int i = 0; i < n; i++)
        {
            int x, y;
            scanf("%d%d", &x, &y);
            if (y == y1 && min(x1, x2) <= x && x <= max(x1, x2))
                cost += 10 * PI - 20;
        }
        printf("%.20lf\n", cost);
        return;
    }

    int n;
    scanf("%d", &n);
    for (int i = 0; i < n; i++)
    {
        int x, y;
        scanf("%d%d", &x, &y);
        if (!(min(x1, x2) <= x && x <= max(x1, x2)))
            continue;
        if (!(min(y1, y2) <= y && y <= max(y1, y2)))
            continue;
        ys.push_back(y);
        founts.emplace_back(x, y);
    }

    make_unique(ys);
    sort(founts.begin(), founts.end());
    if (x1 > x2)
        reverse(founts.begin(), founts.end());
    int best = 0;

    for (auto f : founts)
    {
        int y = get_crd(ys, f.second);
        if (y1 > y2)
            y = N - 1 - y;
        int ans = fen.get(y) + 1;
        best = max(best, ans);
        fen.relax(y, ans);
    }

    print_var(best);
    double cost = (abs(x2 - x1) + abs(y2 - y1)) * 100.0 + (5 * PI - 20) * best;
    printf("%.20lf\n", cost);
}

