bool cmp(Pair a, Pair b) {
  if (a.first != b.first) return a.first < b.first;
  return a.second > b.second;
}

void update_if(int k, int x) {
  k += size-1;
  if (seg[k] > x) return;
  seg[k] = x;
  while (k > 0) {
    k /= 2;
    seg[k] = max(seg[k*2+1], seg[k*2+2]);
  }
}

int getmax(int wishl, int wishr, int k, int watchl, int watchr) {
  int mid;
  int lval, rval;

  if (wishr <= watchl || watchr <= wishl) return 0;
  if (wishl <= watchl && watchr <= wishr) return seg[k];

  mid = (watchl+watchr)/2;
  lval = getmax(wishl, wishr, k*2+1, watchl, mid);
  rval = getmax(wishl, wishr, k*2+2, mid, watchr);
  return max(lval, rval);
}

