ll solve() {
    int i;

    ord.clear();
    for (auto e : aux) {
        auto it = lower_bound(ord.begin(), ord.end(), e.second);
        if (it == ord.end()) {
            ord.pb(e.second);
        } else {
            assert(*it != e.second);
            *it = e.second;
        }
    }

    return ord.size();
}

