    for(int i=0;i<n;i++){
        if(x1<=x[i] && x[i]<=x2 && y1<=y[i] && y[i]<=y2){
            px.push_back(x[i]);
            py.push_back(y[i]);
        }
    }

    int s=px.size();
    vector<pair<long long int,long long int>> pxy(s);

    for(int i=0;i<s;i++){
        pxy[i]={x[i],y[i]};
    }
    sort(pxy.begin(),pxy.end());
    const long long int INF=1e9;
    vector<int> dp(s+1,INF);
    long long int cnt=0;
    dp[0]=-INF;
    for(int i=0;i<s;i++){
        int val=pxy[i].second;
        auto it=lower_bound(dp.begin(),dp.end(),val);
        *it=val;
        cnt=max(cnt,int(it-dp.begin()));
    }
    const long double PI=acos(-1);
    long double cut=20-PI*5;
    long double dis=PI*10-20;
    long long int ccnt=cnt;
    long long int dcnt=0;
    if(cnt==min(x2-x1,y2-y1)+1){
        ccnt--;
        dcnt++;
    }
    long double res=100LL*(x2-x1+y2-y1)-ccnt*cut+dcnt*dis;
    cout<<setprecision(12)<<fixed;
    cout<<res<<endl;

    return 0;
}

