		cout << base << endl;
		return 0;
	}

	if (x[0] == x[1] || y[0] == y[1]) {
		cout << base - 20. + 2. * pr << endl;
		return 0;
	}

	SegmentTree< int, MaxCalc< int >, 0 > seg(m, 0);

	for_(ii,0,m) {
		int i = use[ii];
		int yi = lower_bound(allof(yset), Y[i]) - yset.begin();
		int add = seg.query(0, yi);
		seg.update(yi, add + 1);
	}

	int nc = seg.query(0, m);
	cout << base - 20. * nc + pr * nc << endl;
}

