bool cmp(node x,node y){return x.x<y.x;}

void work()
{
	scanf("%d %d %d %d %d",&sx,&sy,&tx,&ty,&n);
	if (sx>tx)  X=1,sx=1e8-sx,tx=1e8-tx;
	if (sy>ty)  Y=1,sy=1e8-sy,ty=1e8-ty;
