const int MAGIC = 1000 * 1000 * 100 - 1;
const long double Q = 5 * PI - 20;
const long double H = 10 * PI - 20;
int n;
struct point {
	int x, y;
} from, to, f[200010];

int t[800010];

void update(int v, int tl, int tr, int pos, int val) {
	if (tl == tr) {
		t[v] = max(t[v], val);
	}
	else {
		int mid = (tl + tr) / 2;
		if (pos <= mid) {
			update(2 * v, tl, mid, pos, val);
		}
		else {
			update(2 * v + 1, mid + 1, tr, pos, val);
		}
		t[v] = max(t[2 * v], t[2 * v + 1]);
	}
}

int query(int v, int tl, int tr, int l, int r) {
	if (l > r) {
		return 0;
	}
	if (tl == l && tr == r) {
		return t[v];
	}
	int mid = (tl + tr) / 2;
	return max(query(2 * v, tl, mid, l, min(r, mid)),
		query(2 * v + 1, mid + 1, tr, max(l, mid + 1), r));
}

