#define MaxN 200005
#define INF 2140000000
#define MOD 1000000007
#define pi 3.1415926535897932384626433832795
#define MaxT 600005
using namespace std;

int x1,x2,Y1,y2,N;
int T[MaxT];
long long Ans=0;
map <int,pair<bool,int> >Hash,Hash2;
int Pos,Val;
pair<int,int> dots[MaxN];
int D[MaxN],O[MaxN],Size=0,S2=0,S[MaxN];
void Update(int node,int Start,int End)
{
    if(Start==End)
        T[node]=Val;
    else
    {
        int mid=(Start+End)>>1;
        if(Pos>mid)
            Update(2*node+1,mid+1,End);
        else Update(2*node,Start,mid);
        T[node]=max(T[2*node],T[2*node+1]);
    }
}
void Query_Down(int node,int Start,int End)
{
    if(Start>=Pos)
        Val=max(Val,T[node]);
    else
    {
        int mid=(Start+End)>>1;
        Query_Down(2*node+1,mid+1,End);
        if(mid>=Pos)
            Query_Down(2*node,Start,mid);
    }
}
void Query_Up(int node,int Start,int End)
{
    if(End<=Pos)
        Val=max(Val,T[node]);
    else
    {
        int mid=(Start+End)>>1;
        Query_Up(2*node,Start,mid);
        if(mid<Pos)
            Query_Up(2*node+1,mid+1,End);
    }
}
int Search(int val)
{
    int lw=1,hi=S2,mid;
    while(lw<=hi)
    {
        mid=(lw+hi)>>1;
        if(S[mid]>val)
            hi=mid-1;
        else if(S[mid]<val)
            lw=mid+1;
        else return mid;
    }
}
void Normalize()
{
    for(int i=1;i<=Size;i++)
        S[i]=D[i];
    sort(S+1,S+1+Size);
    for(int i=1;i<=Size;i++)
        if(S[i]!=S[S2])
        S[++S2]=S[i];
    for(int i=1;i<=Size;i++)
        D[i]=Search(D[i]);
}
int main()
{
    cin>>x1>>Y1>>x2>>y2>>N;
    for(int i=1;i<=N;i++)
    {
        cin>>dots[i].first>>dots[i].second;
        Hash[dots[i].first]=make_pair(true,dots[i].second);
        Hash2[dots[i].second]=make_pair(true,dots[i].first);
    }
    sort(dots+1,dots+1+N);
    if(x1==x2)
    {
        if(Hash[x1].first&&Hash[x1].second>min(Y1,y2)&&Hash[x1].second<max(Y1,y2))
            cout<<setprecision(14)<<(long double)100LL*abs(Y1-y2)-20+10*pi;
        return 0;
    }
    if(Y1==y2)
    {
        if(Hash2[Y1].first&&Hash2[Y1].second>min(x1,x2)&&Hash2[Y1].second<max(x1,x2))
            cout<<setprecision(14)<<(long double)100LL*abs(x1-x2)-20+10*pi;
        return 0;
    }
    for(int i=1;i<=N;i++)
    {
        if(dots[i].first>=min(x2,x1)&&dots[i].first<=max(x1,x2)&&dots[i].second>=min(Y1,y2)&&dots[i].second<=max(Y1,y2))
            D[++Size]=dots[i].second;
    }
    Normalize();
    int Max=0;
    if(x1>x2)
        swap(Y1,y2);
    for(int i=1;i<=Size;i++)
    {
        Pos=D[i];
        Val=0;
        if(Y1<y2)Query_Up(1,1,S2);
        else Query_Down(1,1,S2);
        O[i]=1+Val;
        Max=max(Max,O[i]);
        Val=O[i];
        Update(1,1,S2);
    }
    cout<<setprecision(14)<<(long double)100LL*(abs(x1-x2)+abs(Y1-y2))-20*Max+5*Max*pi;
    return 0;
}

