struct segtree{
  int dat[segN*2];
  void init(){
    for(int i=0;i<segN*2;i++)
      dat[i]=0;
  }
  void update(int i,int x){
    i+=(segN-1);
    dat[i]=x;
    while(i){
      i=(i-1)/2;
      dat[i]=max(dat[i*2+1],dat[i*2+2]);
    }
  }

  int getMax(int a,int b,int k=0,int l=0,int r=segN){
    if(b<=l || r<=a)return -(1<<28);
    if(a<=l && r<=b)return dat[k];
    int m=(l+r)/2;
    int res= getMax(a,b,k*2+1,l,m);
    res=max(res, getMax(a,b,k*2+2,m,r) );
    return res;
  }
};

