double getans(vector<pair<int, int> > v)
{
	vector<int> result;
	for(int i = 0; i < v.size(); i++){
		if(result.size() == 0 || result[result.size() - 1] < v[i].second){
			result.push_back(v[i].second);
		} else {
			int l = 0, r = result.size();
			while(r - l > 1){
				int mid = (r + l) / 2;
				if(result[mid] > v[i].second) r = mid;
				else l = mid;
			}
			result[l] = v[i].second;
		}
	}
	// cout << result.size() << endl;
	double ans = calc(result.size());
	if(result.size() == v.size() && v.size() > 0){
		int maxsub = 1;
		for(int i = 1; i < result.size(); i++){
			maxsub = max(maxsub, result[i] - result[i - 1]);
		}
		if(maxsub == 1) ans += 5.0 * pi;
	}
	return ans;
}

