const int MAXN = 2E5 + 10;
const double PI = atan((double)1.0) * 4;

int canSee[MAXN], bit[MAXN], n;

vector<pair<int, int> > fount;
vector<int> yVals;
set<pair<int, pair<int, int>> > csVals;
set<pair<pair<int, int>, int> > fountS;
set<pair<int, int> > fountYS;

int bitQuery(int p) {
	int ret = 0;
	for (; p > 0; p -= p & -p) ret += bit[p];
	return ret;
}

void bitMod(int p, int v) {
	for (; p <= n; p += p & -p) bit[p] += v;
}

int main() {
	std::cin.tie(0);
	std::ios_base::sync_with_stdio(0);
	int x1, y1, x2, y2; cin >> x1 >> y1 >> x2 >> y2 >> n;
	if (x1 > x2) swap(x1, x2), swap(y1, y2);
	bool flip = false;
	if (y1 > y2) {
		flip = true;
		y1 = 1E9 - y1, y2 = 1E9 - y2;
	}
	for (int i = 1; i <= n; i++) {
		int x, y; cin >> x >> y;
		if (flip) y = 1E9 - y;
		if (x1 <= x && x <= x2 && y1 <= y && y <= y2) {
			fount.push_back({ x, y });
			yVals.push_back(y);
		}
	}
	sort(fount.begin(), fount.end());
	sort(yVals.begin(), yVals.end());
	bool sameLine = false;
	for (int i = 0; i < (int)fount.size(); i++) {
		int yComp =
			lower_bound(yVals.begin(), yVals.end(), fount[i].second) - yVals.begin() + 1;
		canSee[i] = bitQuery(yComp);
		fountS.insert(make_pair(fount[i], canSee[i]));
		fountYS.insert({ fount[i].second, fount[i].first });
		csVals.insert(make_pair(canSee[i], fount[i]));
		bitMod(yComp, 1);
		if ((x1 == x2 && fount[i].first == x1) ||
				(y1 == y2 && fount[i].second == y1)) {
			sameLine = true;
		}
	}
	int ans = 0;
	double gridAns = 100.0 * (x2 - x1 + y2 - y1);
	if (sameLine) {
		gridAns -= 20 - 10 * PI;
	} else {
		while (true) {
			auto it = fountS.lower_bound({ { x2, y2 }, 0 });
			while (it != fountS.end()) {
				auto it2 = csVals.find({ it->second, it->first });
				auto itYS = fountYS.find({ it->first.second, it->first.first });
				csVals.erase(it2);
				fountS.erase(it++);
				fountYS.erase(itYS);
			}
			auto it3 = fountYS.lower_bound({ y2, x2 });
			while (it3 != fountYS.end()) {
				auto itFs = fountS.lower_bound({ { it3->second, it3->first }, 0 });
				auto it2 = csVals.find({ itFs->second, itFs->first });
				fountS.erase(itFs);
				csVals.erase(it2);
				fountYS.erase(it3++);
			}
			if (csVals.empty()) break;
			auto mx = csVals.rbegin();
			x2 = mx->second.first, y2 = mx->second.second;
			fountS.erase(fountS.lower_bound({ mx->second, 0 }));
			fountYS.erase(fountYS.lower_bound({ y2, x2 }));
			csVals.erase(*mx);
			//cout << x2 << ' ' << y2 << '\n';
			ans++;
		}
	}
	cout << fixed << setprecision(15) << gridAns - ans * (20 - 5 * PI) << '\n';
}

