int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	int sx, sy, tx, ty, N;
	cin >> sx >> sy >> tx >> ty >> N;
	if (sx > tx) {
		swap(sx, tx);
		swap(sy, ty);
	}
	vector<pii> v;
	REP(i, N) {
		int x, y;
		cin >> x >> y;
		if (x >= sx&&x <= tx&&y >= min(sy, ty) && y <= max(sy, ty))v.push_back({ x,y });
	}
	sort(ALL(v));

	int n = v.size();
	vi dp(n + 1, INF);
	if (sy < ty) {

		REP(i, n) {
			int c = lower_bound(ALL(dp), v[i].second) - dp.begin();
			dp[c] = v[i].second;
		}
	}
	else {
		abort();
		REP(i, n) {
			int c = lower_bound(ALL(dp), -v[i].second) - dp.begin();
			dp[c] = -v[i].second;
		}
	}
	int k = lower_bound(ALL(dp), INF) - dp.begin();
