int x[2], y[2], N, X[200005], Y[200005];

const int MAX_Z = (int)(1e8)-1;

void reverseX() {
	for_(i,0,2) x[i] = MAX_Z - x[i];
	for_(i,0,N) X[i] = MAX_Z - X[i];
}

void reverseY() {
	for_(i,0,2) y[i] = MAX_Z - y[i];
	for_(i,0,N) Y[i] = MAX_Z - Y[i];
}

int main() {
	cin >> x[0] >> y[0] >> x[1] >> y[1];
	cin >> N;
	for_(i,0,N) cin >> X[i] >> Y[i];

	if (x[0] > x[1]) reverseX();
	if (y[0] > y[1]) reverseY();

	Vec< int > use, yset;
	for_(i,0,N) {
		if (in_range(X[i], x[0], x[1]+1) &&
			in_range(Y[i], y[0], y[1]+1)) {
			use.push_back(i);
			yset.push_back(Y[i]);
		}	
	}
	sort(allof(use), [&](int i, int j) { return X[i] == X[j] ? Y[i] < Y[j] : X[i] < X[j]; });
	sort(allof(yset));

	int m = use.size();
	long double pr = 0.5 * acos(-1) * 10, base = (x[1] - x[0] + y[1] - y[0]) * 100;

	cout << setprecision(15) << setiosflags(ios::fixed);
	if (m == 0) {
		cout << base << endl;
		return 0;
	}

	if (m == y[1]-y[0]+1) {
		bool flag = true;
		for_(ii,0,m-1) {
			int i = use[ii], j = use[ii+1];
			flag &= (X[i]+1 == X[j] && Y[i]+1 == Y[j]);
		}

		if (flag) {
			cout << base - 20. * m + pr * (m+1) << endl;
			return 0;
		}
	}

	SegmentTree< int, MaxCalc< int >, 0 > seg(m, 0);

	for_(ii,0,m) {
		int i = use[ii];
		int yi = lower_bound(allof(yset), Y[i]) - yset.begin();
		int add = seg.query(0, yi);
		seg.update(yi, add + 1);
	}

	int nc = seg.query(0, m);
	cout << base - 20. * nc + pr * nc << endl;
}

