template<typename T>
struct Segment_Tree {
	typedef function<T(T, T)> F;

	ll n;
	F f;//モノイドとしての演算(最小値、和　など)
	T unit;//単位元

	ll size;
	vector<T> seg;

	Segment_Tree(ll n0, F f0, T unit0) {
		n = n0;
		f = f0;
		unit = unit0;

		size = 1;
		while (size < n) {
			size *= 2;
		}
		seg.assign(2 * size, unit);
	}


	void update(ll k, T x) {//k番目の要素をxに更新
		k += size - 1;
		seg[k] = x;
		while (k > 1) {
			k /= 2;
			seg[k] = f(seg[2 * k], seg[2 * k + 1]);
		}
	}



	T query_prep(ll a, ll b, ll k, ll l, ll r) {//[a,b)とkに対応する区間[l,r)の共通部分でクエリ
		if (b <= l || a >= r) { return unit; }
		if (a <= l && r <= b) { return seg[k]; }

		T v1 = query_prep(a, b, 2 * k, l, (l + r) / 2);
		T v2 = query_prep(a, b, 2 * k + 1, (l + r) / 2, r);
		return f(v1, v2);

	}

	T query(ll a, ll b) {
		return query_prep(a, b, 1, 1, size + 1);
	}

};




int main() {
	ll x1, y1, x2, y2;
	cin >> x1 >> y1 >> x2 >> y2;

	ll N;
	cin >> N;
	vector<pair<ll, ll>> F(N + 1);
	repn(i, N) cin >> F[i].first >> F[i].second;

	ll X = x2 - x1;
	ll Y = y2 - y1;

	repn(i, N) {
		F[i].first -= x1;
		F[i].second -= y1;
	}

	if (X < 0) {
		X *= -1;
		repn(i, N) F[i].first *= -1;
	}
	if (Y < 0) {
		Y *= -1;
		repn(i, N) F[i].second *= -1;
	}
	if (X < Y) {
		swap(X, Y);
		repn(i, N) swap(F[i].first, F[i].second);
	}

	vector<pair<ll, ll>> newF;
	repn(i, N) {
		if (0 <= F[i].first&&F[i].first <= X && 0 <= F[i].second&&F[i].second <= Y) {
			newF.push_back(F[i]);
		}
	}

	ll M = newF.size();
	sort(newF.begin(), newF.end());
	rep(i, M) {
		newF[i].first = i+1;
		swap(newF[i].first, newF[i].second);
	}
	sort(newF.begin(), newF.end());

	Segment_Tree<ll> sg(M, [](ll a, ll b) {return max(a, b); }, 0);
