		ll t = sg.query(0, x);
		sg.update(x, t + 1);
		increase = max(increase, t + 1);
	}

	double ans = (double)(100*X) + (double)(100*Y);
	double cv = 10.0 * 2.0 - 5.0 * acos(-1);
	double st = 10.0 * acos(-1) - 10.0 * 2.0;

	if (increase <= Y) { ans = ans - (double)increase * cv; }
	else { ans = ans - (double)Y*cv + st; }

	cout << fixed << setprecision(15);
	cout << ans << endl;


	system("PAUSE");
}

