const double PAI = 3.141592653589793238;

signed main()
{
	int i;

	cin >> sx >> sy >> gx >> gy;
	cin >> n;
	for (i = 0; i < n; i++) cin >> x[i] >> y[i];

	if (sx > gx) { swap(sx, gx); swap(sy, gy); }

	for (i = 0; i < n; i++) {
		if (sx <= x[i] && x[i] <= gx && min(sy,gy)<= y[i] && y[i] <= max(sy,gy)) {
