  scanf("%d %d %d %d", &x1, &y1, &x2, &y2);
  if (x1 > x2) {
    swap(x1, x2);
    swap(y1, y2);
  }
  int x_min, x_max, y_min, y_max;
  x_min = min(x1, x2);
  x_max = max(x1, x2);
  y_min = min(y1, y2);
  y_max = max(y1, y2);

