  map<int, int> ytox;

  rep (i, n) {
    int x_, y_;
    scanf("%d %d", &x_, &y_);
    if (x_min <= x_ && x_ <= x_max && y_min <= y_ && y_ <= y_max) {
      xy.push_back(Point(x_, y_));
      ytox[y_] = x_;
    }
  }
  n = xy.size();

  double penalty = M_PI * 10 - 20;
  if (x_max == x_min || y_max == y_min) {
    printf("%.11f\n", 100.0 * (x_max - x_min + y_max - y_min) + (int)xy.size() * penalty);
