      }
      return a.x < b.x;
      });

  if (y1 > y2) {
    reverse(all(xy));
  }

  vi l;
  l.push_back(xy[0].y);
  for (int i = 1; i < n; ++i) {
    if (l[(int)l.size() - 1] < xy[i].y) {
      l.push_back(xy[i].y);
    } else {
      *lower_bound(all(l), xy[i].y) = xy[i].y;
