  if(fromY > toY) fromY *= -1, toY *= -1, revY = 1;
  using P = pair<int, int>;
  vector<P> v;
  vector<int> xs;
  toX -= fromX, toY -= fromY;
  for(int i = 0; i < n; i++) {
