    if(revY) y[i] *= -1;
    x[i] -= fromX;
    y[i] -= fromY;
    if(0 <= x[i] && x[i] <= toX && 0 <= y[i] && y[i] <= toY) {
      xs.emplace_back(x[i]);
      v.emplace_back(x[i], y[i]);
    }
  }
  fromX = fromY = 0;

  sort((v).begin(), (v).end());

  // 座圧
  xs.emplace_back(toX);
  uniq(xs);
  auto mp = compress(xs);

  for(auto p : v) ecas.index(mp[p.first], p.second);

  ecas.init(1);

  for(auto p : v) {
    int val = ecas.query(0, mp[p.first], 0, p.second) + 1;
    ecas.set(mp[p.first], p.second, val);
  }

  cout << fixed << setprecision(20);
  constexpr double PI = acos(-1);
  constexpr double A = 20 - 5 * PI;
  constexpr double B = 10 * PI - 20;

  int num = ecas.query(0, mp[toX] + 1, 0, toY + 1);

  double ans = 0;
  if(toX != 0 && toY != 0) {
    ans += (double) - num * A;
    ans += 100.0 * (toX + toY);
  } else {
    ans += (double) B * num;
    ans += (toX + toY) * 100.0;
  }

  cout << ans << endl;

  return 0;
}

