		cout << fixed << ans << endl;
		return 0;
	}


	if (sy > ty) {
		swap(sx, tx);
		swap(sy, ty);
	}

	bool flip = false;
	if (sx > tx) {
		flip = true;
		sx = -sx, tx = -tx;
	}

	R ans = 100.0 * (abs(sx - tx) + abs(sy - ty));

