const double P=acos(-1);
const int N=2e5+2;
int n,sx,tx,sy,ty;
struct pnt{
	int x,y;
}pt[N];

bool cmp_x(const pnt &a,const pnt &b){
	return a.x<b.x;
}

inline int nxi(){
	int x=0;
	char c;
	while((c=getchar())>'9'||c<'0');
	while(x=x*10-48+c,(c=getchar())>='0'&&c<='9');
	return x;
}

inline double solve(){
	static int buk[N];
	const double cost=2-P*0.5;
	const int miny=std::min(sy,ty),maxy=std::max(sy,ty);
	const int disx=abs(sx-tx),disy=abs(sy-ty);
	const bool x_bigger=disx>disy;
	bool connected=0,cut=0;
	int top=0;
	for(int i=1;i<=n&&pt[i].x<=tx;++i){
		if(pt[i].x<sx) continue;
		if(pt[i].y>maxy||pt[i].y<miny) continue;
		if(x_bigger){
			if(pt[i].x>=sx+1){
//				if(pt[i-1].x<sx+1) connected&=(pt[i].y==sy);
				if(pt[i].y==sy) connected=1;
				else connected&=(pt[i].y-pt[i-1].y)==(ty>sy?1:-1);
			}
			if(pt[i].y==ty&&connected) cut=1;
		}
		else{
			if(pt[i].x==sx) connected=1;
			if(pt[i-1].x>=sx){
				connected&=(pt[i].y-pt[i-1].y)==(ty>sy?1:-1);
			}
			if(pt[i].x==tx&&connected) cut=1;
		}

		if(!top||!(disx&&disy)||(pt[i].y>buk[top])==(ty>sy)){
			buk[++top]=pt[i].y;
		}
		else{
			int l=1,r=top,mid;
			while(l!=r){
				mid=(l+r)>>1;
				if((pt[i].y>mid)==(ty>sy)) l=mid+1;
				else r=mid;
			}
			buk[l]=pt[i].y;
		}
	}
//	printf("cut? %d\n",cut);
//	printf("%d,top%d\n",disx+disy,top);
//	printf("stk: ");
//	for(int i=1;i<=top;++i){
//		printf("%d ",buk[i]);
//	}
//	puts("");
	return ((disx+disy)*10-(top-cut)*cost+cut*(P-2))*10;
}

int main(){
#ifndef ONLINE_JUDGE
//	freopen("a.in","r",stdin);
#endif
	sx=nxi(),sy=nxi(),tx=nxi(),ty=nxi();
	n=nxi();
	if(sx>tx){
		std::swap(sx,tx);
		std::swap(sy,ty);
	}
	for(int i=1;i<=n;++i){
		pt[i].x=nxi(),pt[i].y=nxi();
	}
	std::sort(pt+1,pt+n+1,cmp_x);
	printf("%.15lf\n",solve());
	return 0;
}

