	if (y[0] > y[1]) reverseY();

	Vec< int > use, yset, xset;
	for_(i,0,N) {
		if (in_range(X[i], x[0], x[1]+1) &&
			in_range(Y[i], y[0], y[1]+1)) {
			use.push_back(i);
			xset.push_back(X[i]);
			yset.push_back(Y[i]);
		}	
	}
	sort(allof(use), [&](int i, int j) { return X[i] < X[j]; });
	sort(allof(yset));
	sort(allof(xset));

