const int N=200010;
const int MX=1e8+5;
int x1,yy1,x2,yy2,n,tot=0,lis;
int g[N],idx[N],a[N],f[N];
pii pnt[N];
bool deled[N];

int LIS()
{
    int res=0;
    memset(g,0x7f,sizeof(g));
    for(int i=1;i<=tot;i++)
    {
        f[i]=lower_bound(g+1,g+1+n,a[i])-g;
        if(g[f[i]]==0x7f7f7f7f) res++;
        if(a[i]<g[f[i]]) g[f[i]]=a[i],idx[f[i]]=i;
    }
    return res;
}

int LIS2()
{
    int res=0;
    memset(g,0x7f,sizeof(g));
    for(int i=1;i<=tot;i++)
    {
        if(deled[i]) continue;
        f[i]=lower_bound(g+1,g+1+n,a[i])-g;
        if(g[f[i]]==0x7f7f7f7f) res++;
        if(a[i]<g[f[i]]) g[f[i]]=a[i];
    }
    return res;
}

int main()
{
    x1=read();yy1=read();x2=read();yy2=read();n=read();
    for(int i=1;i<=n;i++) pnt[i].X=read(),pnt[i].Y=read();
    if(x2<x1)
    {
        x1=MX-x1;x2=MX-x2;
        for(int i=1;i<=n;i++) pnt[i].X=MX-pnt[i].X;
    }
    if(yy2<yy1)
    {
        yy1=MX-yy1;yy2=MX-yy2;
        for(int i=1;i<=n;i++) pnt[i].Y=MX-pnt[i].Y;
    }
    sort(pnt+1,pnt+1+n);
    for(int i=1;i<=n;i++)
        if(pnt[i].X>=x1&&pnt[i].X<=x2&&pnt[i].Y>=yy1&&pnt[i].Y<=yy2) a[++tot]=pnt[i].Y;
    double ans=100*(x2-x1+yy2-yy1)+(pi*5-20)*(lis=LIS());
    if(g[lis]==yy2)
    {
        int cnt=0;ans=ans-pi*5+pi*10;deled[idx[lis]]=1;
        while(g[lis-1]==g[lis]-1) cnt++,lis--,deled[idx[lis]]=1;
        if(g[lis]==yy1) goto output;
        ans=min(ans,100*(x2-x1+yy2-yy1)+(pi*5-20)*LIS2());
