const int MAXN = 400010;
const int INF = 2147483600;

int N;
const double Pi = acos(-1);
const double Ti = 20.0-5.0*Pi;
const double Ci = 10.0*Pi-20.0;

int x1,y1,x2,y2;
int dx[MAXN+1],dy[MAXN+1];
struct data{
	int x,y,opr;
}p[MAXN+1],to[MAXN+1];
bool cmp(data a,data b){
	if(a.x!=b.x) return a.x<b.x;
	return a.y<b.y;
} double ret=-INF; int f[MAXN+1];
int c[MAXN+1],cx,cy; int d[MAXN+1];

inline int lowbit(int x){return x&(-x);}
inline void Add(int k,int x){
	for(;k<=cy;k+=lowbit(k)) c[k]=max(c[k],x);
} inline int Query(int k){
	int ret=0; for(;k;k-=lowbit(k)) ret=max(ret,c[k]); return ret;
} int topx; double zei=INF;

inline void solve(){
	sort(p+1,p+N+1,cmp); memset(c,0,sizeof(c));
	int tmp=0; double num=0,rg=0;
	if(y1<y2){
		topx=0; data ng;
		for(int i=1;i<=N;i++){
			if(p[i].x>=x1&&p[i].x<=x2&&p[i].y==y2) ng=p[i],num=Ci,rg+=Ci;
			if(p[i].y>=y1&&p[i].y<=y2&&p[i].x==x1) rg+=Ci; 
			if(p[i].x>=x1&&p[i].x<=x2&&p[i].y<=y2&&p[i].y>=y1) to[++topx]=p[i]; 
		} int j=1,l=0;
		for(int i=x1;i<=x2;i++){
			int now=j; if(i==ng.x) num=0;
			while(j<=topx&&to[j].x==i) {
				f[j]=max(Query(to[j].y)+1,1);
				ret=max(ret,1.0*f[j]*Ti-num);++j;
			} for(int k=now;k<j;k++) Add(to[k].y,f[k]);
		}
	} else{
		topx=0; data ng;
		for(int i=1;i<=N;i++){
			if(p[i].x>=x1&&p[i].x<=x2&&p[i].y==y1) ng=p[i],num=Ci,rg+=Ci;
			if(p[i].y>=y2&&p[i].y<=y1&&p[i].x==x1) rg+=Ci; 
			if(p[i].x>=x1&&p[i].x<=x2&&p[i].y<=y1&&p[i].y>=y2) to[++topx]=p[i];
		} int j=1,l=0;
		for(int i=x1;i<=x2;i++){
			int now=j; if(i==ng.x) num=0;
			while(j<=topx&&to[j].x==i) {
				f[j]=max(Query(to[j].y)+1,1);
				ret=max(ret,f[j]*Ti-num);++j;
			} for(int k=now;k<j;k++) Add(cy-to[k].y+1,f[k]);
		}
	} zei=min(zei,rg);
}
int main(){
	//freopen(".in","r",stdin);
	//freopen(".out","w",stdout);
	x1=read(),y1=read(),x2=read(),y2=read();
	N=read(); for(int i=1;i<=N;i++){
		p[i].x=read(),p[i].y=read(); p[i].opr=1;
		c[++cx]=p[i].x,d[++cy]=p[i].y;
	} c[++cx]=x1; c[++cx]=x2; d[++cy]=y1; d[++cy]=y2;
	if(x1==x2||y1==y2){
		if(x1>x2) swap(x1,x2); if(y1>y2) swap(y1,y2); zei=0;
		for(int i=1;i<=N;i++){
			if(p[i].x>=x1&&p[i].x<=x2&&p[i].y>=y1&&p[i].y<=y2) zei+=Ci;
		} printf("%.11lf\n",abs(x1-x2)*100+abs(y1-y2)*100+zei);
		return 0;
	}
	sort(c+1,c+cx+1); sort(d+1,d+cy+1);
	cx=unique(c+1,c+cx+1)-c-1,cy=unique(d+1,d+cy+1)-d-1;
	for(int i=1;i<=N;i++){
		p[i].x=lower_bound(c+1,c+cx+1,p[i].x)-c;
		p[i].y=lower_bound(d+1,d+cy+1,p[i].y)-d;
	}
	x1=lower_bound(c+1,c+cx+1,x1)-c; y1=lower_bound(d+1,d+cy+1,y1)-d;
	x2=lower_bound(c+1,c+cx+1,x2)-c; y2=lower_bound(d+1,d+cy+1,y2)-d;
	double ans=abs(d[y1]-d[y2])*100+abs(c[x1]-c[x2])*100;
	if(x1>x2) swap(x1,x2),swap(y1,y2); solve();
	swap(x1,y1); swap(x2,y2); if(x1>x2) swap(x1,x2); 
	for(int i=1;i<=N;i++) swap(p[i].x,p[i].y); swap(cy,cx);
	solve(); printf("%.11lf\n",min(ans-ret,zei+ans));
}

