	for (int i = 1; i <= tp; i ++)
		if (c[i] < 1 << 30)
			m ++;
	ans -= (20 - 5 * pi) * m;
	if (m == min(x2 - x1, y2 - y1) + 1)
		ans += 5 * pi;
	return printf("%.12Lf\n", ans), 0;
}

