      for (i=0;i<cnt;i++) a[i]=p[i].y;
      sort(a,a+cnt);ma.clear();
      for (i=0;i<cnt;i++) ma[a[i]]=i+1;
      build(1,1,cnt);
      int k=0;
      for (i=0;i<cnt;i++){
        ql=1;qr=ma[p[i].y];
        f[i]=query(1,1,cnt)+1;
        k=max(k,f[i]);
        ql=qr;
