constexpr double pi = 3.141592653589793;

double solve(int x1, int y1, int x2, int y2, int N, const vector<pair<int, int>> & XYs){
    if (x1 > x2){
        swap(x1, x2);
        swap(y1, y2);
    }
    int maxy = max(y1, y2);
    int miny = min(y1, y2);
    vector<pair<int, int>> xys;
    for (const auto & xy : XYs){
        if (xy.first < x1 or xy.first > x2 or xy.second < miny or xy.second > maxy) continue;
        xys.push_back(xy);
    }
    sort(xys.begin(), xys.end());
    if (y1 > y2) reverse(xys.begin(), xys.end());
    vector<int> LIS = {-1};
    for (const auto & xy : xys){
        if (LIS.back() < xy.second){
            LIS.push_back(xy.second);
        }else{
            auto it = upper_bound(LIS.begin(), LIS.end(), xy.second);
            assert(*it > xy.second);
            *it = xy.second;
        }
    }
    int n = LIS.size() - 1;
    int m = min(x2 - x1, maxy - miny) + 1;
    double d = 100.0 * ((x2 - x1) + (maxy - miny)) - n * 5 * (4 - pi);
    if (n == m) d += 5 * pi;
    return d;
}


