#include<bits/stdc++.h>
using namespace std;

#define PI 3.1415926535
#define INF 0x7fffffffffffff
typedef long long int LLI;
typedef pair<LLI, LLI> Pair;

int N;
bool need_reverse;
double ans = 1.0/0.0;
LLI xs[2];
LLI ys[2];
vector<Pair> ps;

int main() {
  for (int i=0; i<2; i++) {
    scanf("%lld%lld", &xs[i], &ys[i]);
  }
  if (xs[1] < xs[0]) {
    swap(xs[0], xs[1]);
    swap(ys[0], ys[1]);
  }

  if (ys[1] < ys[0]) {
    need_reverse = true;
    ys[1] = -ys[1];
    ys[0] = -ys[0];
  }

  scanf("%d", &N);
  for (int i=0; i<N; i++) {
    LLI x, y;
    scanf("%lld%lld", &x, &y);
    if (need_reverse) y = -y;
    if (x < xs[0] || xs[1] < x) continue;
    if (y < ys[0] || ys[1] < y) continue;
    ps.emplace_back(Pair(x, y));
  }
  sort(ps.begin(), ps.end());
  vector<LLI> dp(ps.size(), INF);
  for (auto &p : ps) {
    LLI t = p.second;
    *lower_bound(dp.begin(), dp.end(), t) = t;
  }
  LLI t = lower_bound(dp.begin(), dp.end(), INF) - dp.begin();
  LLI dx = xs[1]-xs[0];
  LLI dy = ys[1]-ys[0];
  ans = 100.0*(dx+dy) - (2-PI/2)*10*double(t);
  if (t > min(dx, dy)) ans += PI/2*10;
  printf("%.13f\n", ans);
}

