ll nt,dat[4000001];

void init(ll n_){
	nt=1;
	while(nt< n_) nt*=2;
	rep(i,2*nt-1) dat[i]=0;
}

void update(ll k,ll a){
	k+=nt-1;
	dat[k]=a;
	while(k>0){
		k=(k-1)/2;
		dat[k]=max(dat[k*2+1],dat[k*2+2]);
	}
}

ll query(ll a,ll b,ll k,ll l,ll r){
	if(r<=a||b<=l) return 0;
	if(a<=l&&r<=b) return dat[k];
	else return max( query(a,b,k*2+1,l,(l+r)/2),query(a,b,k*2+2,(l+r)/2,r) );
}

