LL x[maxn], y[maxn], X[maxn], rk[maxn], c[maxn], f[maxn];
LL sx, sy, tx, ty, n, N, cnt, flag, ans, p;

LL search(LL k){
	LL l = 1, r = cnt, mid;
	while (l < r){
		mid = (l + r) >> 1;
		if (k <= X[mid]) r = mid;
		else l = mid + 1;
	}
	return l;
}

bool cmp(LL a, LL b){
	return y[a] < y[b];
}

void update(LL x, LL y){
	for (; x<=cnt; x+=lowbit(x)) c[x] = max(c[x], y);
}

LL query(LL x){
	LL res = 0;
	for (; x; x-=lowbit(x)) res = max(res, c[x]);
	return res;
}

signed main(){
	scanf("%lld%lld%lld%lld%lld", &sx, &sy, &tx, &ty, &n);
	if (sx <= tx && sy > ty){
		flag = 1; 
		sy = 1e8 - sy; ty = 1e8 - ty;
	}
	else if (sx > tx && sy > ty){
		flag = 2; 
		sx = 1e8 - sx; sy = 1e8 - sy;
		tx = 1e8 - tx; ty = 1e8 - ty;
	}
	else if (sx > tx && sy <= ty){
		flag = 3; 
		sx = 1e8 - sx; tx = 1e8 - tx;
	}
	for (LL i=1; i<=n; i++){ N++;
		scanf("%lld%lld", &x[N], &y[N]);
		if (flag == 1) y[N] = 1e8 - y[N];
		else if (flag == 2) { x[N] = 1e8 - x[N]; y[N] = 1e8 - y[N]; }
		else if (flag == 3) x[N] = 1e8 - x[N];
		if (x[N] < sx || x[N] > tx || y[N] < sy || y[N]  > ty){
			N--; continue;
		}
		X[++cnt] = x[N]; rk[N] = N;
	}
	sort(X+1, X+cnt+1); sort(rk+1, rk+N+1, cmp);
	if (sx == tx || sy == ty || !N){
		if (N) printf("%.16Lf\n", 100.0*(tx-sx + ty-sy) - 20 + 2*r);
		else printf("%.16Lf\n", 100.0*(tx-sx + ty-sy));
		return 0;
	}

	for (LL i=1; i<=N; i++){
		f[i] = query(search(x[rk[i]])) + 1;
		ans = max(ans, f[i]);
		update(search(x[rk[i]]), f[i]);
	}
	if (ans == tx-sx || ans == ty-sy) printf("%.16Lf\n", 100.0*(tx-sx + ty-sy) + ans*(r-20) + r);
	else printf("%.16Lf\n", 100.0*(tx-sx + ty-sy) + ans*(r-20));

	return 0;
}

