void change(int i, int xs) {
    d[i] = xs;
    while (i >> 1 > 0) {
        i >>= 1;
        d[i] = max(d[i << 1], d[(i << 1) + 1]);
    }
}


int rmq(int v, int vl, int vr, int l, int r) {
    if (vl > r || vr < l) {
        return 0;
    }
    if (l <= vl && vr <= r) {
        return d[v];
    }
    return max(rmq(v << 1, vl, (vl + vr) >> 1, l, r), rmq((v << 1) + 1, ((vl + vr) >> 1) + 1, vr, l, r));
}


