pair<int,int>solve(int y,int x){
	int k=100;
	while(true){
		if(abs(y)>abs(x)){
			while(y>=5){
				y-=5;
				x+=2;
			}
			while(y<0){
				y+=5;
				x-=2;
			}
		}else{
			while(x>=5){
				x-=5;
				y-=2;
			}
			while(x<0){
				x+=5;
				y+=2;
			}
		}

		k--;
	}
	return make_pair(x,y);
}
