						nxs[0].first=x+l_plus;
						nxs[0].second=nxs[0].first+pluss[n_flag];

						for(int y=1;y<19;++y){
							nxs[y].first=nxs[y-1].second-1;
							if(y+n_flag==19){
								nxs[y].first++;
							}
							nxs[y].second=nxs[y].first+pluss[(flag+y)%19];
						}
						bool ok_flag=true;
						bool aok_flag=true;
						for(int y=0;y<19;++y){
