								if(field[y][ax]=='.'){
									aok_flag=false;
								}
							}
						}
						//cout<<ok_flag<<endl;
						if(ok_flag){
							//WHATS(x)
							//WHATS(flag)
							//WHATS(l_plus)

							dp[x+l_plus][n_flag]=min(dp[x+l_plus][n_flag],dp[x][flag]+1);
							if(aok_flag){
