int main() {
	int L,U,R,D;cin>>L>>U>>R>>D;
	int N;cin>>N;
	vector<pair<int,int>>ps(N);
	for(int i=0;i<N;++i){
		int x,y;cin>>x>>y;
		ps[i]=make_pair(x,y);
	}
	if(L>R){
		swap(L,R);
		swap(U,D);
	}
	if(U>D){
		U=-U;
		D=-D;
		for(auto&p:ps){
			p.second=-p.second;
		}
	}
	ld plus=0;
	if(L==R){
		for(auto p:ps){
			if(p.first==L&&U<p.second&&p.second<D){
				plus+=11.415926535897938;
			}
		}
	}else if(U==D){
		for(auto p:ps){
			if(p.second==U&&L<p.first&&p.first<R){
				plus+=11.415926535897938;

			}
		}
	}else{
		sort(ps.begin(),ps.end());
		map<int,int>mp;
		mp[U]=0;
		for(auto p:ps){
			if(p.first<L||p.first>R)continue;
			else if(p.second<U|| p.second>D)continue;
			else{
				auto it=mp.upper_bound(p.second);
				if(it!=mp.begin()){
					mp[p.second]=max(mp[p.second],prev(it)->second+1);
				}
			}
		}
		// WHATS(ps)
		// WHATS(L)
		// WHATS(R)
		// WHATS(U)
		// WHATS(D)
		int cnt=0;
		for(auto m:mp){
			//WHATS(m)
			cnt=max(cnt,m.second);
		}

		ld xx=20-20*acos(-1.0)/4;
		plus=xx*(-cnt);
	}

	ld answer=((D-U)+(R-L))*100+plus;
	cout<<setprecision(10)<<fixed<<answer<<endl;
	return 0;
}

