constexpr float fou = 20 - 5 * 3.1415926535897932384626433832, ff = 10 * 3.1415926535897932384626433832 - 20;
long long int x[4], N, a, b, my, My, dp[364364], n, d;
vector<pair<long long, long long>> fs;
vector<long long> v;

int main(){
    scanf("%lld%lld%lld%lld%lld", x, x + 1, x + 2, x + 3, &N);
    if(*x > x[2]){swap(*x, x[2]); swap(x[1], x[3]);}
    my = min(x[1], x[3]);
    My = x[1] + x[3] - my;
    d = 1 - 2 * (x[1] > x[3]);
    for(int i = 0; i < N; ++i){
        scanf("%lld%lld", &a, &b);
        if(*x <= a && a <= x[2] && my <= b && b <= My){
            fs.push_back({a, b * d});
        }
    }
    if(*x != x[2] && x[1] != x[3]){
        sort(fs.begin(), fs.end());
        fill(dp, dp + 364364, 114514893);
        for(auto p : fs){
            *lower_bound(dp, dp + N, p.second) = p.second;
        }
        n = lower_bound(dp, dp + N, 114514893) - dp;
        if(n == min(x[2] - *x, My - my) + 1)printf("%.15f", (x[2] - *x + My - my) * 100 - fou * (n - 1) + ff);
        else printf("%.15f", (x[2] - *x + My - my) * 100 - fou * n);
    }else{
        printf("%.15f", (x[2] - *x + My - my) * 100 + (ff * fs.size()));
    }
    return 0;
}

