void update(int nod, int l, int r)
{
    int mid=(l+r)/2;
    if(l==r)
    {
        aint[nod]=d[poz];
        return;
    }
    else
    {
        if(poz<=mid) update(2*nod,l,mid);
        else update(2*nod+1,mid+1,r);
        aint[nod]=max(aint[2*nod],aint[2*nod+1]);
    }
}

int query(int nod, int l, int r)
{
    int mid=(l+r)/2;
    if(l>=st && r<=dr) return aint[nod];
    if(dr<=mid) return query(2*nod,l,mid);
    if(st>mid) return query(2*nod+1,mid+1,r);
    return max(query(2*nod,l,mid),query(2*nod+1,mid+1,r));
}

