const ll INF = 0x3fffffff;


int main(){
	//ios_base::sync_with_stdio(0);
	ll N;
	double ans=0;
	ll sx, sy, gx, gy;
	ll X[200005], Y[200005];

	cin >> sx >> sy >> gx >> gy;
	cin >> N;
	rep(i,N) cin >> X[i] >> Y[i];
	if( sx > gx ){
		swap(sx, gx);
		swap(sy, gy);
	}
	if( sy > gy ){
		sy *= -1;
		gy *= -1;
		rep(i,N) Y[i] *= -1;
	}
	if( sx == gx ){
		ans = (gy - sy) * 100.0;
		rep(i,N) if(X[i] == gx && sy < Y[i] && Y[i] < gy) ans += 10.0*M_PI - 20.0;
		printf("%.15f\n", ans);
		return 0;
	}
	if( sy == gy ){
		ans = (gx - sx) * 100.0;
		rep(i,N) if(Y[i] == gy && sx < X[i] && X[i] < gx) ans += 10.0*M_PI - 20.0;
		printf("%.15f\n", ans);
		return 0;
	}

	// zip
	set<ll> st;
	map<ll,ll> m[2];
	rep(i,N){
		st.emplace( X[i]-1 );
		st.emplace( X[i]   );
		m[0].emplace( X[i]-1, Y[i]   );
		m[1].emplace( X[i]  , Y[i]-1 );
	}

	// solve
	map<ll,double> dp;
	dp[sy] = 0.0;
	for(auto x: st){
		if( x < sx ) continue;
		// dp
		auto nx_dp = dp;
		rep(k,2) if( m[k][x] >= sy ){
			ll y = m[k][x];
			auto it = dp.lower_bound(y+1);
			it--;
			//cout << "hit " << x << "," << y << " " << it->first << endl;
			double sum = it->second;
			sum += 5.0 * M_PI - 20.0;
			auto it2 = dp.lower_bound(y+2);
			it2--;
			nx_dp[y+1] = min( it2->second, sum );
		}
		// erase
		map<ll,double> tmp;
		double mn = INF;
		for(auto t: nx_dp) if( t.Y < mn ){
			tmp.insert(t);
			mn = t.Y;
		}
		dp = tmp;
		//for(auto t: dp) cout << "(" << t.X << "," << t.Y << ") "; cout << endl;
	}

	auto it = dp.lower_bound(gy+1);
	it--;
	ans = ((gx-sx) + (gy-sy)) * 100.0 + it->second;
	printf("%.15f\n", ans);

	return 0;
}

