const double pi = acos(-1.), cir = 2 * pi * 10;

int n;

struct vec {
	int x, y;

	bool operator < (const vec &rhs) const {
		return x < rhs.x;
	}

	void scan() {
		::scan(x); ::scan(y);
	}
} p[200005];

int sorted[200005];

int hsh(int x) {
	return std::lower_bound(sorted + 1, sorted + n + 1, x) - sorted;
}

int xl, xr, yl, yr;

namespace BIT {
	int c[200005];

#define lowbit(x) ((x) & -(x))

	void modify(int a, int x) {
		for (int i = a; i <= n; i += lowbit(i))
			c[i] = std::max(c[i], x);
	}

	int query(int a) {
		int res = 0;
		for (int i = a; i > 0; i -= lowbit(i))
			res = std::max(res, c[i]);
		return res;
	}

	void modify2(int a, int x) {
		for (int i = a; i > 0; i -= lowbit(i))
			c[i] = std::max(c[i], x);
	}

	int query2(int a) {
		int res = 0;
		for (int i = a; i <= n; i += lowbit(i))
			res = std::max(res, c[i]);
		return res;
	}
}

int main() {
	scan(xl); scan(yl); scan(xr); scan(yr); scan(n);

	int tp = 0;
	if ((xl < xr) != (yl < yr)) tp = 1;

	if (xl > xr) std::swap(xl, xr);
	if (yl > yr) std::swap(yl, yr);

	for (int i = 1; i <= n; ++i) {
		p[i].scan();
		if (p[i].x < xl || p[i].x > xr || p[i].y < yl || p[i].y > yr) {
			--i; --n;
		}
		else {
			sorted[i] = p[i].y;
		}
	}

	std::sort(p + 1, p + n + 1);
	std::sort(sorted + 1, sorted + n + 1);

	int cnt = 0;
	if (tp == 0) {
		for (int i = 1; i <= n; ++i) {
			int t = hsh(p[i].y), tmp = BIT::query(t - 1);
			cnt = std::max(cnt, tmp + 1);
			BIT::modify(t, tmp + 1);
		}
	}
	else {
		for (int i = 1; i <= n; ++i) {
			int t = hsh(p[i].y), tmp = BIT::query2(t + 1);
			cnt = std::max(cnt, tmp + 1);
			BIT::modify2(t, tmp + 1);
		}
	}

	double ans = ((xr - xl) + (yr - yl)) * 100.;

//	std::cerr << cnt << std::endl;

	if (xl == xr || yl == yr) {
		ans = ans - cnt * 20 + cnt * cir * 0.5;
	}
	else {
		ans = ans - cnt * 20 + cnt * cir * 0.25;
	}

	printf("%.13f\n", ans);

	return 0;
}

