int LIS(const vector<int>& a) {
	int N = (int)a.size();
	vector<long long> dp(N, ten(9));
	for (int i = 0; i < N; ++i) {
		auto it = lower_bound(dp.begin(), dp.end(), a[i]);
		*it = a[i];
	}

	return lower_bound(dp.begin(), dp.end(), ten(9)) - dp.begin();
}

