	int x1, y1, x2, y2; reader(x1, y1, x2, y2);
	bool xflip = false, yflip = false;
	if (x1 > x2) x1 = ten(8) - x1, x2 = ten(8) - x2, xflip = true;
	if (y1 > y2) y1 = ten(8) - y1, y2 = ten(8) - y2, yflip = true;
