            root.reset(l, r, -1, -1);
            return;
        }
        int g = (l + r) >> 1;
        int leftChild = cnt++, rightChild = cnt++;
        buildTree(tree[leftChild], l, g);
        buildTree(tree[rightChild], g + 1, r);
        root.reset(l, r, leftChild, rightChild);
    }

    void init(int l, int r) {
        cnt = 1;
        buildTree(tree[0], l, r);
    }

    void update(node& root, int pos, int val) {
        if (root.leftIdx == root.rightIdx) {
            root.mx = max(root.mx, val);
            return;
        }
        int g = (root.leftIdx + root.rightIdx) >> 1;
        if (pos <= g)
            update(tree[root.leftChild], pos, val);
        else
            update(tree[root.rightChild], pos, val);
        root.mx = max(tree[root.leftChild].mx, tree[root.rightChild].mx);
        return;
    }

    void update(int pos, int val) {
        update(tree[0], pos, val);
    }

    ll get(node& root, int u, int v) {
        if (u <= root.leftIdx && root.rightIdx <= v) return root.mx;
        if (u > root.rightIdx || v < root.leftIdx) return 0;
        ll res = max(get(tree[root.leftChild], u, v),get(tree[root.rightChild], u, v));
        return res;
    }

    ll get(int u, int v) {
        assert(u <= v);
        return get(tree[0], u, v);
    }
} segmentTree;


