        }
    }
    if (v1 > v2) {
        inv(v1); inv(v2);
        rep(i, 0, n) inv(p[i].y);
    }

    if (u1 == u2 || v1 == v2) {
        ld res = (abs(u1 - u2) + abs(v1 - v2)) * 100ll;
        rep(i, 0, n) {
            if (p[i].x >= u1 && p[i].x <= u2 && p[i].y >= v1 && p[i].y <= v2) {
                res += 10 * pi - 10 * 2;
            }
        }
        printf("%.12LF\n", res);
        return;
    }
    int k = 0;
    rep(i, 0, n) {
        st[p[i].x] = 0;
        id[i] = i;
    }
    st[u1] = 0;
    st[u2] = 0;

    for (auto& it : st) {
        it.second = ++k;
    }

    sort(id, id + n, cmp);

    segmentTree.init(1, k);


    for (int j = 0; j < n; ++j) {
        int i = id[j];

        if (p[i].y >= v1 && p[i].y <= v2) {
            int xpoint = st[p[i].x];
            if (xpoint >= st[u1] && xpoint <= st[u2]) {
                if (p[i].y == v1) {
                    segmentTree.update(xpoint, 1);
                } else {
                    int tmp = 0;
                    if (xpoint > 1) tmp = segmentTree.get(1, xpoint - 1);
                    segmentTree.update(xpoint, tmp + 1);
                }
            }
        }
    }

    ld res = abs(u1 - u2) + abs(v1 - v2);
    int tmp = segmentTree.get(st[u1], st[u2]);
    res = res * 100 - tmp * (2 * 10 - 10 * pi / 2);

    printf("%.12LF\n", res);
}

