using pa2 = std::pair<long long, long long>;
std::vector<pa2> foun;

constexpr double pi = 3.141592653589793238;
long long n;
constexpr long long INF = 1e+12;


double dist(pa2 a, pa2 b){
    auto ite = std::lower_bound(foun.begin(), foun.end() , a);
    std::vector<long long> lis(n, INF);
    auto high = std::max(a.second, b.second);
    auto low = std::min(a.second, b.second);
    while(ite != foun.end() && ite->first <= b.first){
        auto y = ite->second;
        if(low <= y && y <= high){
            auto l = std::lower_bound(lis.begin(), lis.end() , y);
            *l = y;
        }
        ite++;
    }

    long long circ = std::lower_bound(lis.begin(), lis.end() , INF) - lis.begin();
//    double Loss = 10*pi - 20;
    double Gain = -20 + 5 * pi;
    long long dis = std::abs(a.first- b.first) + std::abs(a.second- b.second);
    double ret = dis*100. + circ * Gain;
    if(std::min(std::abs(a.second- b.second), std::abs(a.first- b.first) ) +1 == circ){
        ret += 5.*pi;
    }
    return ret;

}

