const double pi = 2 * asin(1.0);

vector<int> Symmetry(vector<int> x) {
  for (int i = 0; i < x.size(); ++i) x[i] *= -1;
  return x;
}

const int inf = 1000 * 1000 * 1000;

int LIS(const vector<int>& a) {
  int n = a.size();
  vector<int> d(n + 1);
  d[0] = -inf;
  for (int i = 1; i <= n; ++i) d[i] = inf; 

  for (int i = 0; i < n; ++i) {
    int j = int (upper_bound(d.begin(), d.end(), a[i]) - d.begin());
    if (d[j - 1] < a[i] && a[i] < d[j]) d[j] = a[i];
  }
  int j = n;
  while (d[j] == inf) --j;
  return j;
}

void Output(double x) {
  printf("%.10lf\n", x);
  exit(0);
}

int main()
{
  int x1, y1, x2, y2, n;
  cin >> x1 >> y1 >> x2 >> y2 >> n;
  double result = abs(x1 - x2) + abs(y1 - y2);
  result *= 100.0;
  vector<int> x(n), y(n);
  for (int i = 0; i < n; ++i) cin >> x[i] >> y[i];
  if (x1 > x2) {
    x1 *= -1;
    x2 *= -1;
    x = Symmetry(x);
  }
  if (y1 > y2) {
    y1 *= -1;
    y2 *= -1;
    y = Symmetry(y);
  }
  if (x2 - x1 > y2 - y1) {
    swap(x1, y1);
    swap(x2, y2);
    swap(x, y);
  }

  vector<pair<int, int>> p(n);
  for (int i = 0; i < n; ++i) p[i] = make_pair(x[i], y[i]);
  sort(p.begin(), p.end());
  vector<int> a;
  for (auto q : p) if (x1 <= q.first && q.first <= x2 && y1 <= q.second && q.second <= y2) a.push_back(q.second);

  int len = LIS(a);
  cerr << "len = " << len << endl;
  double result1 = result + (5 * pi - 20) * (len - 1) + 10 * pi - 20;
  double result2 = result + (5 * pi - 20) * len;

  Output((len == x2 - x1 + 1) ? result1 : result2);

  return 0;
}

