    if (a.isT) return false;
    if (b.isS) return false;
    return true;
}

void compress() {
    FOR(i, 1, n) b[i] = ii(a[i].x, i);
    sort(b+1, b+n+1);
    b[0] = ii(-1, -1);
    int cnt = 0;
