    if (Y1 > Y2) {
        F0(i, n) v[i].second=n+1-v[i].second;
    }

    int cnt = 0;   

    F0(i, n) {
        int x = get(v[i].second - 1) + 1;
        cnt = max(cnt, x); 
        add(v[i].second, x); 
    }

    double ans = 100.0*(X2-X1+MAXY-MINY) + cnt * (pi * 5 - 20);
    if (X1 == X2 || Y1 == Y2) {
        if (n) ans += pi * 5;
    }
    printf("%.10lf\n", ans);

    return 0;
}

