int main() {

    ios::sync_with_stdio(false); // stdioを使うときはコメントアウトすること
    cin.tie(nullptr);            // インタラクティブ問題ではコメントアウトすること

    ll x1, y1, x2, y2;
    cin >> x1 >> y1 >> x2 >> y2;
    ll n = in1;
    vector<pair<ll, ll>> yx(n);
    REP(i, n) {
        ll x, y; cin >> x >> y;
        yx[i] = make_pair(y, x);
    }
    sort(ALL_OF(yx));

    ld ans = 114514;

    if(y1 == y2) {
        ans = solve_along_x_axis(yx, x1, x2, y1);
    } else if (x1 == x2) {
        ans = solve_along_y_axis(yx, x1, y1, y2);
    } else {
        if (y1 > y2) {
            swap(y1, y2);
            swap(x1, x2);
        }
        ans = solve_regular(yx, x1, y1, x2, y2);
        {
            ll xx = x1 < x2 ? x1-1 : x1+1;
            auto u = make_pair(xx, y1);
            auto itr = lower_bound(ALL_OF(yx), u);
            ld cand = solve_regular(yx, xx, y1, x2, y2) + 100;
            if (itr != yx.end() && u == *itr) {
                cand -= corner_shortcut;
            }
            chmin(ans, cand);
        }
    }

