			sort(d+1,d+n+1,cmp1);
			for(RG int i=1;i<=n;++i)
				d[i].y=i;
			sort(d+1,d+n+1,cmp);
			dp[1]=1; mmax=1; add(n+1-d[1].y,dp[1]);
			for(RG int i=2;i<=n;++i)
				{
					dp[i]=ask(n+1-d[i].y)+1;
					add(n+1-d[i].y,dp[i]);
					mmax=max(mmax,dp[i]);
				}
			ans=ans-(db)20*mmax + (db)mmax*5*pi;
		}
	if(mmax==min(abs(s.x-t.x),abs(s.y-t.y))+1) ans+=5*pi;
	printf("%.15Lf",ans);
	//fclose(stdin);fclose(stdout);
	return 0;
}

