#define N 200005
using namespace std;
typedef long double ld;
struct P{
	int x,y;
}S,T,a[N];
int X,Y,n,wx[N],wy[N];
pair<int,int> b[N];
void get(int op){
	for(int i=1;i<=n;i++) b[i]=make_pair(!op?a[i].x:a[i].y,i);
	b[++n]=make_pair(!op?S.x:S.y,-1);
	b[++n]=make_pair(!op?T.x:T.y,0);
	sort(b+1,b+n+1);
	for(int i=1,cnt=0;i<=n;i++){
		if(i==1||b[i].first!=b[i-1].first){
			if(!op) wx[++cnt]=b[i].first;
			else wy[++cnt]=b[i].first;
		}
		if(b[i].second<=0){
			if(b[i].second==0){
				if(!op) T.x=cnt;
				else T.y=cnt;
			}
			else{
				if(!op) S.x=cnt;
				else S.y=cnt;
			}
			continue;
		}
		if(!op) a[b[i].second].x=cnt;
		else a[b[i].second].y=cnt;
	}
}
bool cmpx(P a,P b){
	return a.x<b.x;
}
int mx[N],f[N];
void upd(int k,int val){
	for(;k<=n;k+=k&-k) mx[k]=max(mx[k],val);
}
int find(int k){
	int ans=0;
	for(;k;k-=k&-k) ans=max(ans,mx[k]);
	return ans;
}
int main(){
	scanf("%d%d%d%d%d",&S.x,&S.y,&T.x,&T.y,&n);
	if(S.x>T.x) swap(S,T);
	for(int i=1;i<=n;i++) scanf("%d%d",&a[i].x,&a[i].y);
	if(S.y>T.y){
		S.y=-S.y;T.y=-T.y;
		for(int i=1;i<=n;i++) a[i].y=-a[i].y;
	}
	get(0);
	get(1);
	a[++n]=S;a[++n]=T;
	sort(a+1,a+n+1,cmpx);
	int lst=0;
	for(int i=1;i<=n;i++){
		if(a[i].x<S.x||a[i].y<S.y) continue;
		f[i]=find(a[i].y)+1;
		if(a[i].x==S.x&&a[i].y==S.y) f[i]=0;
		if(a[i].x==T.x&&a[i].y==T.y) lst=f[i];
		upd(a[i].y,f[i]);
	}
	const ld pi=acosl(ld(-1));
	long double ans=ld(wx[T.x]-wx[S.x]+wy[T.y]-wy[S.y])*100;
	ans+=ld(pi*5-20)*(lst-1);
	if(lst-1==min(wx[T.x]-wx[S.x]+1,wy[T.y]-wy[S.y]+1)&&lst) ans+=pi*5;
	printf("%.20Lf",ans);
	return 0;
}

#include <cstdio>
#include <algorithm>
