using namespace std;

#define mp make_pair
#define pb push_back
#define ll long long

#define maxN 200011

const ll def = 1000000000LL;
const double PI = 3.141592653589793;

ll px1, px2, py1, py2;
ll n, i;
pair<ll, ll> P[maxN];
bool rev;

vector< pair<ll, ll> > aux;
vector<ll> ord;
double ans;

bool special_cases() {
    if (px1 != px2 && py1 != py2)
        return false;

    if (px1 == px2 && py1 == py2) {
        cout << 0.00;
        return true;
    }

    double ans = 0.00;
    if (px1 == px2) {
        ans = 100LL * (py2 - py1);

        for (i = 1; i <= n; i++) {
            if (P[i].first == px1 && P[i].second > py1 && P[i].second < py2)
                ans += 10.00 * PI - 20.00;
        }
    } else {
        ans = 100LL * (px2 - px1);

        for (i = 1; i <= n; i++) {
            if (P[i].second == py1 && P[i].first > px1 && P[i].first < px2)
                ans += 10.00 * PI - 20.00;
        }
    }

    printf("%.16lf", ans);
    return true;
}

ll solve() {
    int i;

    ord.clear();
    for (auto e : aux) {
        auto it = lower_bound(ord.begin(), ord.end(), e.second);
        if (it == ord.end()) {
            ord.pb(e.second);
        } else {
            assert(*it != e.second);
            *it = e.second;
        }
    }

    return ord.size();
}

int main()
{
  //  freopen("test.in","r",stdin);

    cin >> px1 >> py1 >> px2 >> py2;
    if (px1 > px2) {
        swap(px1, px2);
        swap(py1, py2);
    }
    if (py1 > py2) {
        py1 = def - py1;
        py2 = def - py2;
        rev = true;
    }

    cin >> n;
    for (i = 1; i <= n; i++) {
        cin >> P[i].first >> P[i].second;
        if (rev) P[i].second = def - P[i].second;
    }

    if (special_cases())
        return 0;

    assert(px1 < px2);
    assert(py1 < py2);

    for (i = 1; i <= n; i++) {
        if (P[i].first >= px1 && P[i].first <= px2)
            if (P[i].second >= py1 && P[i].second <= py2)
                aux.pb(P[i]);
    }

    sort(aux.begin(), aux.end());
    ans = 100LL * (px2 - px1 + py2 - py1);
    ans += (5.00 * PI - 20.00) * (1.00 * solve());

    assert(ans > 0.00);

    printf("%.15lf", ans);

    return 0;
}

#include <bits/stdc++.h>

template <class T>
void scan(T &x) {
	register char ch; x = 0;
	for (ch = getchar(); ~ch && (ch < '0' || ch > '9'); ch = getchar());
	for (; ch >= '0' && ch <= '9'; ch = getchar()) x = x * 10 + ch - '0';
}

typedef __float128 ldb;

const ldb pi = acos(-1.), cir = 2. * pi * 10.;

int n;

struct vec {
	int x, y;

	bool operator < (const vec &rhs) const {
		return x < rhs.x;
	}

	void scan() {
		::scan(x); ::scan(y);
	}
} p[200005];

int sorted[200005];

int hsh(int x) {
	return std::lower_bound(sorted + 1, sorted + n + 1, x) - sorted;
}

int xl, xr, yl, yr;

struct St {
	int x, y, z;

	St() {
		x = 0; y = z = 0;
	}
	St(int x, int y, int z): x(x), y(y), z(z) {}

	bool operator < (const St &rhs) const {
		return x == rhs.x ? std::max(y, z) > std::max(rhs.y, rhs.z) : x < rhs.x;
	}

	St operator + (const St &rhs) const {
		return St(x + rhs.x, y + rhs.y, z + rhs.z);
	}
};

namespace BIT {
	St c[200005];

#define lowbit(x) ((x) & -(x))

	void modify(int a, St x) {
		for (int i = a; i <= n; i += lowbit(i))
			c[i] = std::max(c[i], x);
	}

	St query(int a) {
		St res;
		for (int i = a; i > 0; i -= lowbit(i))
			res = std::max(res, c[i]);
		return res;
	}

	void modify2(int a, St x) {
		for (int i = a; i > 0; i -= lowbit(i))
			c[i] = std::max(c[i], x);
	}

	St query2(int a) {
		St res;
		for (int i = a; i <= n; i += lowbit(i))
			res = std::max(res, c[i]);
		return res;
	}
}

int main() {
	scan(xl); scan(yl); scan(xr); scan(yr); scan(n);

	int tp = 0;
	if ((xl < xr) != (yl < yr)) tp = 1;

	if (xl > xr) std::swap(xl, xr);
	if (yl > yr) std::swap(yl, yr);

	for (int i = 1; i <= n; ++i) {
		p[i].scan();
		if (p[i].x < xl || p[i].x > xr || p[i].y < yl || p[i].y > yr) {
			--i; --n;
		}
		else {
			sorted[i] = p[i].y;
		}
	}

	std::sort(p + 1, p + n + 1);
	std::sort(sorted + 1, sorted + n + 1);

	St cnt;
	if (tp == 0) {
		for (int i = 1; i <= n; ++i) {
			int t = hsh(p[i].y);
			St tmp = BIT::query(t - 1);
			tmp = tmp + St(1, (p[i].x == xl || p[i].x == xr), (p[i].y == yl || p[i].y == yr));
			cnt = std::max(cnt, tmp);
			BIT::modify(t, tmp);
		}
	}
	else {
		for (int i = 1; i <= n; ++i) {
			int t = hsh(p[i].y);
			St tmp = BIT::query2(t + 1);
			tmp = tmp + St(1, (p[i].x == xl || p[i].x == xr), (p[i].y == yl || p[i].y == yr));
			cnt = std::max(cnt, tmp);
			BIT::modify2(t, tmp);
		}
	}

	ldb ans = (ldb)((xr - xl) + (yr - yl)) * 100.;

//	std::cerr << cnt << std::endl;

	if (xl == xr || yl == yr) {
		ans = ans - (ldb)cnt.x * 20. + cnt.x * cir * 0.5;
	}
	else {
		if (cnt.y == 2 || cnt.z == 2) --cnt.x;
		ans = ans - (ldb)cnt.x * 20. + cnt.x * cir * 0.25;
//		std::cerr << cnt.y << " " << cnt.z << std::endl;
	}

	printf("%.15f\n", (double)ans);

	return 0;
}

