#include<iostream>
#include<vector>
using namespace std;
typedef long long lint;
typedef vector<int>vi;
typedef pair<int,int>pii;
#define rep(i,n)for(int i=0;i<(int)(n);++i)
const double pi=acos(-1);

int lcs(const vector<pii> &pts){
  int n=pts.size();
  vi m(n+1);
  int maxl=0;
  rep(i,n){
    int p=0;
    int f=maxl+1;
    while(f-p>1){
      int x=(f+p)/2;
      if(pts[m[x]].second<pts[i].second){
	p=x;
      }else{
	f=x;
      }
    }
    m[p+1]=i;
    maxl=max(maxl,p+1);
  }
  return maxl;
}

double f(int goalx,int goaly,vector<pii> pts){
  if(0){
    cerr<<"goal:"<<goalx<<" "<<goaly<<endl;
    rep(i,pts.size()){
      cerr<<" "<<pts[i].first<<","<<pts[i].second;
    }
    cerr<<endl;
  }
  double base=(goalx+goaly)*100.0;
  sort(pts.begin(),pts.end());
  int lc=lcs(pts);
  double ans=1e30;
  int lim=min(goalx,goaly)+1;
  rep(i,lc+1){
    if(lc==lim&&i==0)continue;
    ans=min(ans,base+(5*pi-20)*i+(i==lim?5*pi:0));
  }
  return ans;
}


int main(){
  pii x[2];
  rep(i,2){
    cin>>x[i].first>>x[i].second;
  }
