  rep(i,n){
    cin>>a[i].first>>a[i].second;
  }
  if(x[0].first>x[1].first){
    rep(i,2){
      x[i].first=-x[i].first;
    }
    rep(i,n){
      a[i].first=-a[i].first;
    }
  }
  if(x[0].second>x[1].second){
    rep(i,2){
      x[i].second=-x[i].second;
    }
    rep(i,n){
      a[i].second=-a[i].second;
    }
  }
  vector<pii> rec;
  rep(i,n){
    int ax=a[i].first-x[0].first;
    int ay=a[i].second-x[0].second;
    if(ax>=0&&ax<=x[1].first-x[0].first&&ay>=0&&ay<=x[1].second-x[0].second){
      rec.push_back(pii(ax,ay));
    }
  }
  printf("%.15f\n",f(x[1].first-x[0].first,x[1].second-x[0].second,rec));
}

