#define all(v) (v).begin(), (v).end()

using li = long long;

int nvp(vector<int> a) {
    int n = a.size();
    const int INF = 1e9;

    vector<int> d(n + 1, INF);
    d[0] = -INF;

    for (int i=0; i<n; i++) {
        int j = int (upper_bound (d.begin(), d.end(), a[i]) - d.begin());
        if (d[j-1] < a[i] && a[i] < d[j]) {
            d[j] = a[i];
        }
    }

    int ans = 0;
    for (int i=1; i<=n; i++)
        if (d[i] != INF)
            ans = i;

    return ans;
}

