  if (xa > xb) {
    swap(xa, xb);
    swap(ya, yb);
  }
  vector <int> z;
  for (int i = 0; i < n; ++i) {
    int x = a[i].first;
    int y = a[i].second;
    if (x >= xa && x <= xb) {
      if (ya <= yb) {
        if (y >= ya && y <= yb) {
          z.push_back(y - ya);
        }
      } else {
        if (y >= yb && y <= ya) {
          z.push_back(ya - y);
        }
      }
    }
  }
  int sz = (int)z.size();
  for (int i = 1; i <= sz; ++i) {
    f[i] = inf;
  }
  for (int i = 0; i < sz; ++i) {
    int l = 0, r = sz;
    while (r - l > 1) {
      int s = (l + r) / 2;
      if (f[s] > z[i]) {
        r = s;
      } else {
        l = s;
      }
    }
    f[r] = z[i];
  }
  int cnt = 0;
  for (int i = 1; i <= sz; ++i) {
    if (f[i] != inf) {
      ++cnt;
    }
  }
  double v = 5 * acos(-1);
