int xx1, yy1, xx2, yy2;
int n;
VP V;
double PI = acos(-1.);

int LIS(VI a) {
	int n = SZ(a);
	VI d(n + 10, 1000000000);
	d[0] = -1000000000;

	int ret = 0;
	for (int i = 0; i < n; i++) {
		int j = int(upper_bound(d.begin(), d.end(), a[i]) - d.begin());
		ret = MAX(ret, j);
		d[j] = a[i];
	}
	return ret;
}

void conv(int& x, int &y) {
	int xd = y;
	int yd = 100000000 - x;
	x = xd;
	y = yd;
}

double solve() {
	if (xx1 == xx2) {
		if (yy1 > yy2) swap(yy1, yy2);
		for (int i = 0; i < n; i++) {
			if (V[i].first == xx1 && IN(V[i].second, (yy1), (yy2))) {
				return ABS(yy2 - yy1) * 100.0 - 20 + PI * 10;
			}
		}
		return ABS(yy2 - yy1) * 100.0;
	}

	if (yy1 == yy2) {
		if (xx2 < xx1) swap(xx1, xx2);
		for (int i = 0; i < n; i++) {
			if (V[i].second == yy1 && IN(V[i].first, xx1, xx2)) {
				return ABS(xx2 - xx1) * 100.0 - 20 + PI * 10;
			}
		}
		return ABS(xx2 - xx1) * 100.0;
	}

	if (xx1 > xx2 && yy1 > yy2) {
		swap(xx1, xx2);
		swap(yy1, yy2);
	}

	if (xx1 < xx2 && yy1 < yy2);
	else {
		conv(xx1, yy1);
		conv(xx2, yy2);
		for (int i = 0; i < n; i++) {
			conv(V[i].first, V[i].second);
		}
		return solve();
	}

	VP Z;
	for (int i = 0; i < n; i++) {
		if (IN(V[i].first, xx1, xx2) && IN(V[i].second, yy1, yy2)) {
			Z.push_back(V[i]);
		}
	}

	sort(ALL(Z));
	VI X;
	for (PII p : Z) X.push_back(p.second);
	int lis = LIS(X);
	double ret;
	if (lis == MIN(ABS(xx1 - xx2), ABS(yy1 - yy2)) + 1) {
		ret = ABS(xx1 - xx2) * 100.0 + ABS(yy1 - yy2) * 100.0 - lis * 20 + (lis + 1) * PI * 10 / 2;
	}
	else {
		ret = ABS(xx1 - xx2) * 100.0 + ABS(yy1 - yy2) * 100.0 - lis * 20 + lis * PI * 10 / 2;
	}
	//printf("lis=%d\n", lis);
	return ret;
}

