			A[i] = (long long int)X[i] * 100000000 + Y[i];
		}

		sort(A.begin(), A.end());

		int cnt = 0;
		int x = x1;
		int y = y1;
		int range = 1;
		vector<long long int>::iterator left, right;
		while (x2 - (x + range * dx) != dx * -1 && y2 - (y + range * dy) != dy * -1){
			if (dx == 1){
				left = lower_bound(A.begin(), A.end(), (long long int)x * 100000000);
				right = lower_bound(A.begin(), A.end(), ((long long int)x + range) * 100000000);
			} else {
				left = lower_bound(A.begin(), A.end(), ((long long int)x - range + 1) * 100000000);
				right = lower_bound(A.begin(), A.end(), ((long long int)x + 1) * 100000000);
			}

			bool flag = false;
			for (vector<long long int>::iterator it = left; it != right; it++){
				int bufY = *it % 100000000;
				if (dy == 1 && y <= bufY && bufY <= y + range){
					x += range * dx;
					y = bufY;

					flag = true;
					cnt++;
				} else if (y - range <= bufY && bufY <= y){
					x += range * dx;
					y = bufY;

					flag = true;
					cnt++;
				}
			}

			if (flag) range = 1;
			else range++;
		}

		ans -= cnt * 20;
		cnt *= 5;
		ans += cnt * PI;
	}
}

