const int INF = 0x3f3f3f3f; const lint BINF = 0x3f3f3f3f3f3f3f3fLL;

int n, xx1, yy1, xx2, yy2;

struct pt{
	int xx, yy;
	bool operator<(const pt &rhs) const{
		return yy < rhs.yy;
	}
} a[200005];

int lis(vector<int> a){
	if(a.size() == 0) return 0;
	vector<int> s(a.size());
	int l = 0;
	s[l++]=a[0];
	for(int i=1;i<(int)a.size();i++)
		if(a[i]>s[l-1])
			s[l++]=a[i];
		else
			*lower_bound(s.begin(),s.begin()+l,a[i])=a[i];
	return l;
}

int solve(){
	cin >> xx1 >> yy1 >> xx2 >> yy2 >> n;
	for(int i=0;i<n;i++) cin >> a[i].xx >> a[i].yy;
	if(xx1 > xx2){
		for(int i=0;i<n;i++) a[i].xx *= -1;
		xx1 *= -1, xx2 *= -1;
	}
	if(yy1 > yy2){
		for(int i=0;i<n;i++) a[i].yy *= -1;
		yy1 *= -1, yy2 *= -1;
	}

	long double orig = 100LL * (xx2 - xx1 + yy2 - yy1);

	if(xx1 == xx2){
		long double wtf = 20LL * atan((long double) 1) * 2LL - 20LL;
		int ok = 1;
		for(int i=0;i<n;i++) if(a[i].yy >= yy1 && a[i].yy <= yy2 && a[i].xx == xx1) ok = 0;
		cout << fixed << setprecision(15) << orig + (1 - ok) * wtf << endl;
		return 0;
	}
	if(yy1 == yy2){
		long double wtf = 20LL * atan((long double) 1) * 2LL - 20LL;
		int ok = 1;
		for(int i=0;i<n;i++) if(a[i].xx >= xx1 && a[i].xx <= xx2 && a[i].yy == yy1) ok = 0;
		cout << fixed << setprecision(15) << orig + (1 - ok) * wtf << endl;
		return 0;
	}

	sort(a, a+n);
	vector<int> b;
	for(int i=0;i<n;i++) if(a[i].yy >= yy1 && a[i].yy <= yy2 && a[i].xx >= xx1 && a[i].xx <= xx2) b.push_back(a[i].xx);
	int whyWA = lis(b);
	for(int i=0;i<n;i++) swap(a[i].xx, a[i].yy);
	swap(xx1, yy1); swap(xx2, yy2);
	sort(a, a+n);
	vector<int> c;
	for(int i=0;i<n;i++) if(a[i].yy >= yy1 && a[i].yy <= yy2 && a[i].xx >= xx1 && a[i].xx <= xx2) b.push_back(a[i].xx);
	whyWA = max(whyWA, lis(c));
	long double cand = 20LL - 20LL * atan((long double) 1LL);
	cout << fixed << setprecision(15) << orig - 1LL * whyWA * cand << endl;
    return 0;
}

int main(){
	ios::sync_with_stdio(0);
	// int t; cin >> t; while(t--)
	solve();
	// cout << (solve() ? "YES" : "NO") << endl;
	return 0;
}

