		for (int i = 0; i < N; i++){
			arr[i].first = 2*xone - arr[i].first;
		}
		ytwo = 2*yone - ytwo;
		for (int i = 0; i < N; i++){
			arr[i].second = 2*yone - arr[i].second;
		}
	}

	if (xone == xtwo){ //y-axis
