	if (yone == ytwo){ //x-axis
		//something
		for (int i = 0; i < N; i++){
			if (arr[i].second == yone && arr[i].first > xone && arr[i].first < xtwo){
				printf("%.20Lf\n", (long double)((long double)100)*(xtwo - xone) + pii*((long double)10) - 10.0 - 10.0);
