	for (int i = 0; i < vy.size(); i++) {
	    ll p = lower_bound(h, h+l, vy[i].second)-h;
	    h[p] = vy[i].second;
	    l = max(p+1, l);
	}

	answer = min(answer, (long double)((long double)100.0)*(xtwo - xone + ytwo - yone) - ((long double)l)*((long double)20.0) + ((long double)l)*(pii*5.0));

