const ll MAXL = 1e8;

template <typename T>
class SegmentTree {
public:
    ll size;
    vector<T> node;
    function<T(T, T)> comp;
    T identity_ele;  //comp(x, identity_ele) == x

    SegmentTree(const vector<T> &v, function<T(T, T)> comp, T identity_ele) 
        : comp(comp),
          identity_ele(identity_ele)
    {
        ll tmp = 1;
        while(tmp < v.size()) tmp = (tmp << 1);
        this->size = tmp;
        this->identity_ele = identity_ele;
        this->comp = comp;
        node = V<T>(2 * size - 1, identity_ele);
        for(ll i = 0; i < v.size(); i++) {
            node[i + size - 1] = v[i];
        }
        for(ll i = size - 2; 0 <= i; i--) {
            node[i] = comp(node[i * 2 + 1], node[i * 2 + 2]);
        }
    }

    void update(ll pos, T value) {
        pos += size - 1;
        node[pos] = value;
        while(pos > 0) {
            pos = (pos - 1) / 2;
            node[pos] = comp(node[2 * pos + 1], node[2 * pos + 2]);
        }
    }

    T query(ll a, ll b) {
        return sub_query(a, b, 0, 0, size);
    }

    T sub_query(ll a, ll b, ll k, ll l, ll r) {
        if(r <= a || b <= l) {
            return identity_ele;
        } else if(a <= l && r <= b) {
            return node[k];
        } else {
            T left = sub_query(a, b, k * 2 + 1, l, (l + r) / 2);
            T right = sub_query(a, b, k * 2 + 2, (l + r) / 2, r);
            return comp(left, right);
        }
    }
};

double solve() {
    ll x1, y1, x2, y2;
    cin >> x1 >> y1 >> x2 >> y2;
    ll N;
    cin >> N;
    V<PLL> xy(N);
    for(auto &&ele : xy) {
        ll x, y;
        cin >> x >> y;
        ele = PLL(x, y);
    }

    if(x2 < x1) {
        swap(x1, x2);
        swap(y1, y2);
    }
    if(y2 < y1) {
        y1 = MAXL - y1;
        y2 = MAXL - y2;
        for(auto &&ele : xy) {
            ll x, y;
            tie(x, y) = ele;
            y = MAXL - y;
            ele = PLL(x, y);
        }
    }

    double ans = (x2 - x1) + (y2 - y1);
    ans *= 100;

    if(x1 == x2 || y1 == y2) {
        for(auto &&ele : xy) {
            ll x, y;
            tie(x, y) = ele;
            if(x1 <= x && x <= x2 &&
               y1 <= y && y <= y2) {
                ans -= 20;
                ans += 20 / 2 * M_PI;
                return ans;
            }
        }
        return ans;
    }

    {
        V<ll> coors(2 * N + 5);
        for(ll i = 0; i < N; i++) {
            coors[2 * i] = xy[i].first;
            coors[2 * i + 1] = xy[i].second;
        }
        coors[2 * N] = x1;
        coors[2 * N + 1] = x2;
        coors[2 * N + 2] = y1;
        coors[2 * N + 3] = y2;
        coors[2 * N + 4] = -1;
        sort(ALL(coors));
        auto ite = unique(ALL(coors));
        coors.erase(ite, coors.end());
        auto get_idx = [&](ll x) {
            return distance(coors.begin(),
                            lower_bound(ALL(coors), x));
        };
        x1 = get_idx(x1);
        y1 = get_idx(y1);
        x2 = get_idx(x2);
        y2 = get_idx(y2);
        for(auto &&ele : xy) {
            ll x, y;
            tie(x, y) = ele;
            ele = PLL(get_idx(x), get_idx(y));
        }
    }

    SegmentTree<ll> seg_v(V<ll>(2 * N + 10, 0), [](ll a, ll b) { return max(a, b); }, 0);
    SegmentTree<ll> seg_h(V<ll>(2 * N + 10, 0), [](ll a, ll b) { return max(a, b); }, 0);
    sort(ALL(xy));
    ll px = x1, py = y1;
    for(auto &&ele : xy) {
        ll x, y;
        tie(x, y) = ele;
        if(!(x1 <= x && x <= x2 &&
             y1 <= y && y <= y2)) continue;
        if(x == x1) {
            seg_h.update(y, 1);
        } else if(y == y1) {
            seg_v.update(y, 1);
        } else {
            bool f = false;
            ll max_v = 0, max_h = 0;
            if(px + 1 == x && py + 1 == y) {
                f = true;
                ll vv = seg_v.query(py, py + 1);
                ll hv = seg_h.query(py, py + 1);
                chmax(max_v, vv + 1);
                chmax(max_h, hv + 1);
            }

            ll val = max(seg_v.query(0, (f ? py : y)), seg_h.query(0, (f ? py : y)));
            chmax(max_v, val + 1);
            chmax(max_h, val + 1);
            DEBUG(make_tuple(ele, max_v, max_h));
            seg_v.update(y, max_v);
            seg_h.update(y, max_h);
        }
        px = x;
        py = y;
    }

    double dec = 0;
    double d = 2 * 10 / 4 * M_PI;
    double diff = 2 * 10 - d;
    chmax(dec, diff * seg_h.query(0, y2));
    chmax(dec, diff * seg_h.query(y2, y2 + 1) - (px == x2 ? d : 0));
    chmax(dec, diff * seg_v.query(0, y2));
    chmax(dec, diff * seg_v.query(y2, y2 + 1) - d);
    DEBUG(make_tuple(seg_h.query(0, y2 + 1), seg_v.query(0, y2), seg_v.query(y2, y2 + 1)));
    DEBUG(dec);
    return ans - dec;
}

