	vector<pair<long double, long double> > V;
	for (int i = 0; i < N; i++) {
		long double X, Y;
		cin >> X >> Y;
		if ((X1 - X) * (X2 - X) <= 0 && (Y1 - Y) * (Y2 - Y) <= 0) {
			V.push_back({ X, Y });
		}
	}
	if (X1 <= X2) {
		for (int i = 0; i < V.size(); i++) V[i].first -= X1 ;
		X2 -= X1, X1 = 0;
	}
	else {
		for (int i = 0; i < V.size(); i++) V[i].first -= X2;
		X1 -= X2, X2 = 0;
		swap(X1, X2);
	}
	if (Y1 <= Y2) {
		for (int i = 0; i < V.size(); i++) V[i].second -= Y1;
		Y2 -= Y1, Y1 = 0;
	}
	else {
		for (int i = 0; i < V.size(); i++) V[i].second -= Y2;
		Y1 -= Y2, Y2 = 0;
		swap(Y1, Y2);
	}
	long double INF = 10000000000;
	vector<long double> DP(N + 1, INF);
	sort(V.begin(), V.end());
	for (int i = 0; i < V.size(); i++) {
		long long it = lower_bound(DP.begin(), DP.end(), V[i].second) - DP.begin();
		DP[it] = V[i].second;
	}
	long double COUNT = 0;
	while (DP[COUNT] < INF) COUNT++;
	if (COUNT <= min(X2, Y2)) {
		long double ANS = (X2 + Y2) * 100 - COUNT * (20 - 5 * PI);
		printf("%.15llf\n", ANS);
	}
	else {
		long double ANS = (X2 + Y2) * 100 - (COUNT - 1) * (20 - 5 * PI) + 10 * PI - 20;
		printf("%.15llf\n", ANS);
	}
}

