		}
	}
	a[++n].x=xr;a[n].y=yr;
	int num=0;
	for(int i=1;i<=n;i++){
		b[++num]=a[i].y;
	}
	sort(b+1,b+num+1);
	int tot=unique(b+1,b+num+1)-b-1;
	for(int i=1;i<=n;i++)a[i].y=lower_bound(b+1,b+tot+1,a[i].y)-b;
	sort(a+1,a+n+1);
	if(yl<=yr){
		for(int i=1;i<=n;i++)f[i]=inf;
		ld ans=100*fabs(yr-yl)+100*fabs(xr-xl);ld tmp;
		updata(1,n,1,1,0);
		for(int i=2;i<n;i++){
			tmp=query(1,n,1,1,a[i].y-1)+p1-20.0;
			if(tmp<f[i])f[i]=tmp;
			tmp=query(1,n,1,a[i].y,a[i].y)+p2-20.0;
			if(tmp<f[i])f[i]=tmp;
			updata(1,n,1,a[i].y,f[i]);
		}
		for(int i=2;i<=n;i++){
			if(a[n].y>=a[i].y)
				f[n]=min(f[n],f[i]);
		}
		if(n>2)ans+=f[n];
		printf("%.16Lf\n",ans);
	}
	else{
		for(int i=1;i<=n;i++)f[i]=inf;
		ld ans=100*fabs(yr-yl)+100*fabs(xr-xl);ld tmp;
		updata(1,n,1,1,0);
		for(int i=2;i<n;i++){
			tmp=query(1,n,1,a[i].y+1,n)+p1-20.0;
			if(tmp<f[i])f[i]=tmp;
			tmp=query(1,n,1,a[i].y,a[i].y)+p2-20.0;
			if(tmp<f[i])f[i]=tmp;
			updata(1,n,1,a[i].y,f[i]);
		}
		for(int i=2;i<=n;i++){
			if(a[n].y<=a[i].y)
				f[n]=min(f[n],f[i]);
		}
		if(n>2)ans+=f[n];
		printf("%.16Lf\n",ans);
	}
}

