const int LO = 0 , HI = (int)1e8;
struct segtree{
  struct node{
    ll rs,mx;
    node *lt,*rt;
    node(){rs=mx=0;lt=rt=NULL;}
  };
  typedef node* pn;
  pn root=NULL;
  void pull(pn&it){
    it->rs = (it->lt?it->lt->rs:0)+(it->rt?it->rt->rs:0);
    it->mx = max((it->lt?it->lt->mx:0),(it->rt?it->rt->mx:0));
  }

  void upd(int &pos,ll &val,pn&it,int lx=LO,int rx=HI){
    if(it==NULL)it=new node();
    if(lx==rx){//==pos
      it->rs+=val;
      it->mx = it->rs;
      return;
    }
    int m = lx+rx>>1;
    if(pos<=m)upd(pos,val,it->lt,lx,m);
    if(pos>m)upd(pos,val,it->rt,m+1,rx);
    pull(it);
  }void upd(int pos,ll val){upd(pos,val,root);}

  ll qry(int &u,int &v,pn&it,int lx=LO,int rx=HI){
    if(it==NULL or u>rx or v<lx)return 0;
    if(u<=lx and rx<=v)return it->mx;
    int m = lx+rx>>1;
    return max(qry(u,v,it->lt,lx,m),qry(u,v,it->rt,m+1,rx));
  }ll qry(int u,int v){return qry(u,v,root);}

} T;

int sx,sy,dx,dy;
int n;
vector<pair<int,int> > pts;
const double ppi = 3.14159265358979323846;

int main(){
  ios::sync_with_stdio(0);cin.tie(0);cout.tie(0);

  cin>>sx>>sy>>dx>>dy;
  cin>>n;
  for(int i=1;i<=n;i++){
    int u,v;
    cin>>u>>v;
    if(abs(u-sx)+abs(u-dx)==abs(sx-dx) and
       abs(v-sy)+abs(v-dy)==abs(sy-dy) ){
      pts.emplace_back(u,v);
    }
  }

  if(sx > dx){
    swap(sx,dx);
    for(auto&point:pts){
      point.ff = dx - ( point.ff - sx );
    }
  }

  if(sy > dy){
    swap(sy,dy);
    for(auto&point:pts){
      point.ss = dy - ( point.ss - sy );
    }
  }

  for(auto&point:pts){
    point.ff -= sx;
    point.ss -= sy;
  }
  dx -= sx;dy -= sy;

  if(pts.empty()){
    cout << fixed << setprecision(20) << 100.0*(dx+dy) << endl;
    return 0;
  }

  if(dx==0 or dy==0){
    double ans = 100.0*(dx+dy);
    double delta = -20.0*pts.size();
    delta += 10*ppi*pts.size();
    cout << fixed << setprecision(20) << ans + delta << endl;
    return 0;
  }

  sort(pts.begin(),pts.end());

  int fts = 0;
  for(int i=0;i<pts.size();){
    int j = i;
    for(;j<pts.size() and pts[i].ff==pts[j].ff;j++);
    reverse(pts.begin()+i,pts.begin()+j);//
    i=j;
  }
  for(auto&point:pts){
    int v = point.ss;
    int mx = T.qry(0,v-1);
    T.upd(v,mx+1);
    fts = max(fts,1+mx);
  }
  //cerr << fts << endl;

  double dist = 100.0*(dx+dy);
  double delta = -20.0*fts;
  delta += 5.0*ppi*fts;
  cout << fixed << setprecision(20) << dist + delta << endl;

  return 0;
};

