#define maxn 200005
int n,sz;
int tree[maxn*4];
point s,e;
point p[maxn];
map<double,int> mp;
map<double,double> ori;
void cpidx() {
    int i;
    map<double,int>::iterator it;
    mp[s.Y]; mp[e.Y];
    for(i=0;i<n;i++) mp[p[i].Y];
    for(it=mp.begin();it!=mp.end();++it) it->second = ++sz, ori[sz] = it->first;
    s.Y = mp[s.Y]; e.Y = mp[e.Y];
    for(i=0;i<n;i++) p[i].Y = mp[p[i].Y];
    if(s>e) swap(s,e);
    sort(&p[0],&p[n]);
}
void build(int pos,int l,int r) {
    if(l==r) {
        tree[pos] = -inf;
        return ;
    }
    int mid = (l+r)/2;
    build(pos<<1,l,mid); build(pos<<1|1,mid+1,r);
    tree[pos] = max(tree[pos<<1],tree[pos<<1|1]);
}
void update(int pos,int l,int r,int x,int val) {
    if(l>r || r<x || x<l) return ;
    if(l==r) {
        tree[pos] = max(tree[pos],val);
        return ;
    }
    int mid = (l+r)/2;
    update(pos<<1,l,mid,x,val); update(pos<<1|1,mid+1,r,x,val);
    tree[pos] = max(tree[pos<<1],tree[pos<<1|1]);
}
int query(int pos,int l,int r,int x,int y) {
    if(l>r || r<x || y<l) return -inf;
    if(x<=l && r<=y) return tree[pos];
    int mid = (l+r)/2;
    return max(query(pos<<1,l,mid,x,y), query(pos<<1|1,mid+1,r,x,y));
}
main() {
    int i,val;
