        int cnt = 0;
        for(int i = 0; i < N; i++) {
            if(P[i].first == X1 && min(Y1, Y2) <= P[i].second && P[i].second <= max(Y1, Y2)) cnt++;
        }
        lf ans = 100 * abs(Y1 - Y2);
        ans += (10*PI - 20);
        cout << ans;
        return 0;
    }
    if(Y1 == Y2) {
        int cnt = 0;
        for(int i = 0; i < N; i++) {
            if(P[i].first == Y1 && min(X1, X2) <= P[i].first && P[i].first <= max(X1, X2)) cnt++;
        }
        lf ans = 100 * abs(X1 - X2);
        ans += (10*PI - 20);
