double dist(const ST& a, const ST& b){
  return abs(a.x - b.x)*100.0 + abs(a.y - b.y)*100.0;
}


double dijkstra(int start, int goal){
  int N = 8*n+2;
  vector<int> trace(N, -2);
  priority_queue<Edge,vector<Edge>,greater<Edge> > q;
  q.push((Edge){-1,start,0});
  while(!q.empty()){
    Edge e=q.top();
    q.pop();
    if(trace[e.dest]>=0) continue;
    trace[e.dest]=e.src;
    if(e.dest==goal) return e.weight;
    FOR(it,G[e.dest])
      if(trace[it->dest]==-2){
        q.push((Edge){it->src,it->dest,e.weight+it->weight});
      }
  }
}

