	return a.y<b.y;
}


void calc(int rq, ll&b, ll&s)
{
	ll p=429203673205103380LL;
	ll m=100000000000000000LL;

	b=0;
	s=0;
	for(int i=0;i<rq;i++)
	{
		s+=p;
		b+=s/m;
		s%=m;
	}

	if(s)
	{
		b++;
		s=m-s;
	}
}


void print(int dx, int dy, int rq, int hq)
{
	ld round=5*PI;
	ll ans=(abs(dx)+abs(dy))*100LL;
//	314159265358979323
//	429203673205103380

	if(hq)
	{
		ans+=11;
		printf("%lld.415926535897932384626433832795\n", ans);
	}
	else
	{
		ll b, s;
		calc(rq, b, s);
		ans-=b;
		printf("%lld.%017lld\n", ans, s);
	}
}


int main(void)
{
	pos_t s, g;
	int n;

	while(scanf("%d%d%d%d%d", &s.x, &s.y, &g.x, &g.y, &n)==5)
	{
		vector<pos_t> p(n);

		for(int i=0;i<n;i++)
		{
			scanf("%d%d", &p[i].x, &p[i].y);
		}

		if(s.x==g.x)
		{
			sort(p.begin(), p.end(), cmp_x);
			auto it=lower_bound(p.begin(), p.end(), s, cmp_x);
			int is_hq=0;
			if(it->x==s.x)
			{
				if(s.y>g.y) swap(s, g);
				if(s.y<it->y && it->y<g.y) is_hq=1;
			}
			print(0, g.y-s.y, 0, is_hq);
			continue;
		}

		if(s.y==g.y)
		{
			sort(p.begin(), p.end(), cmp_y);
			auto it=lower_bound(p.begin(), p.end(), s, cmp_y);
			int is_hq=0;
			if(it->y==s.y)
			{
				if(s.x>g.x) swap(s, g);
				if(s.x<it->x && it->x<g.x) is_hq=1;
			}
			print(g.x-s.x, 0, 0, is_hq);
			continue;
		}

		if(s.x>g.x)
		{
			swap(s, g);
			swap(s, g);
		}
		if(s.y>g.y)
		{
			for(auto&pe:p) pe.y=-pe.y;
			s.y=-s.y;
			g.y=-g.y;
		}

		int min_y=min(s.y, g.y);
		int max_y=max(s.y, g.y);

		vector<pos_t> w;

		sort(p.begin(), p.end(), cmp_x);
		for(auto it=lower_bound(p.begin(), p.end(), s, cmp_x);it!=p.end();++it)
		{
			if(it->x>g.x) break;
			if(it->y<min_y || max_y<it->y) continue;
//printf("it=(%d,%d)\n", it->x, it->y);
			auto wit=lower_bound(w.begin(), w.end(), *it, cmp_y);
			if(wit==w.end())
