int timer,tag[400111],f[400111],bit[400111];
void change(int x,int v)
{
	for(;x<400111;x+=(x&-x))
	{
		if(tag[x]!=timer)
		{
			tag[x]=timer;
			bit[x]=v;
		}
		else bit[x]=max(bit[x],v);
	}
}
int query(int x)
{
	int ret=0;
	for(;x>0;x-=(x&-x))
		if(tag[x]==timer)
			ret=max(ret,bit[x]);
	return ret;
}
void solve(int l,int r)
{
	if(l==r)return;
	int mid=(l+r)>>1;
	solve(l,mid);
	vector<pair<pii,int> >v;
	for(int i=l;i<=r;i++)
		v.pb(mp(mp(p[i].ff,-i),p[i].ss));
	sort(v.begin(),v.end());
	timer++;
	for(int i=0;i<(int)v.size();i++)
	{
		v[i].ff.ss=-v[i].ff.ss;
		if(v[i].ff.ss<=mid)change(v[i].ss,f[v[i].ff.ss]);
		else
		{
			int tmp=query(v[i].ss-1);
			if(tmp+1>f[v[i].ff.ss])
				f[v[i].ff.ss]=tmp+1;
		}
	}
	solve(mid+1,r);
}
