typedef long double LD;
typedef long long LL;
typedef pair<int, int> pii;

const LD PI = atan(1.0) * 4.0;

int N;
int xst, yst, xfn, yfn;
vector<pii> v;

bool between(int x, int y, int z) { return min(x, z) <= y && y <= max(x, z); }

class Normalize
{
public:
    vector<int> ord;
    map<int, int> mp;

    int get(int x) { return mp[x]; }
    void add(int x) { if(mp.count(x)) return; mp[x]; ord.push_back(x); }

    void normalize()
    {
        sort(ord.begin(), ord.end());
        for(int i = 0; i < ord.size(); i++)
            mp[ ord[i] ] = i;
    }
} nrmX, nrmY;

void rotate90(int &x, int &y)
{
    int xx = x, yy = y;
    x = -yy, y = xx;
}

class SegmentTree
{
public:
    int aint[800005];
    int N, ans;

    void U(int nod, int st, int dr, int pos, int val)
    {
        if(st == dr)
        {
            aint[nod] = val;
            return;
        }

        int mij = st + (dr - st) / 2;
        if(pos <= mij)  U(nod * 2, st, mij, pos, val);
        else            U(nod * 2 + 1, mij + 1, dr, pos, val);

        aint[nod] = max(aint[nod * 2], aint[nod * 2 + 1]);
    }

    void Q(int nod, int st, int dr, int sti, int dri)
    {
        if(sti <= st && dr <= dri)
        {
            ans = max(ans, aint[nod]);
            return;
        }

        int mij = st + (dr - st) / 2;
        if(sti <= mij)  Q(nod * 2, st, mij, sti, dri);
        if(mij < dri)   Q(nod * 2 + 1, mij + 1, dr, sti, dri);
    }

    int query(int st, int dr)
    {
        ans = 0;
        Q(1, 0, N, st, dr);
        return ans;
    }
}aint;

int main()
{
    #ifdef FILE_IO
    freopen("1.in", "r", stdin);
    freopen("1.out", "w", stdout);
    #endif

    scanf("%d%d", &xst, &yst);
    scanf("%d%d", &xfn, &yfn);
    if(xst > xfn)   swap(xst, xfn), swap(yst, yfn);

    scanf("%d", &N);
    for(int i = 1; i <= N; i++)
    {
        int x, y;
        scanf("%d%d", &x, &y);

        if( !between(xst, x, xfn) || !between(yst, y, yfn) )    continue;
        v.push_back({x, y});
    }

    xfn -= xst; yfn -= yst;
    for(auto it = begin(v); it != end(v); it++)
    {
        (*it).first -= xst;
        (*it).second -= yst;
    }
    xst = yst = 0;

    if(yfn <= 0)
    {
        rotate90(xfn, yfn);
        for(auto it = begin(v); it != end(v); it++)
            rotate90( (*it).first, (*it).second );
    }

    if(yfn <= 0)
    {
        rotate90(xfn, yfn);
        for(auto it = begin(v); it != end(v); it++)
            rotate90( (*it).first, (*it).second );
    }

    sort(v.begin(), v.end());

    if(xfn - xst + 1 == v.size())
    {
        bool ok = true;
        for(int i = 1; i < v.size(); i++)
            if(v[i].first <= v[i - 1].first || v[i].second <= v[i - 1].second)
                ok = false;

        if(ok)
        {
            LD ans = (LD)yfn * 100.0;
            LD add = 10.0 * PI - 20.0;
            ans += add;
            LD mns = 20.0 - 5.0 * PI;
            ans -= mns * (LD)(xfn - xst);

            cout << fixed << setprecision(15) << ans << '\n';
            return 0;
        }
    }

    LD ans = (LD)(xfn + yfn) * 100.0;

    nrmX.add(0); nrmY.add(0);
    nrmX.add(xfn);
    nrmY.add(yfn);
    for(auto x: v)
        nrmX.add(x.first), nrmY.add(x.second);

    nrmX.normalize();
    nrmY.normalize();

    xfn = nrmX.get(xfn), yfn = nrmY.get(yfn);
    for(auto it = begin(v); it != end(v); it++)
        (*it).first = nrmX.get( (*it).first ), (*it).second = nrmY.get( (*it).second );

    sort(v.begin(), v.end());

    aint.N = nrmY.ord.size() - 1;
    for(auto x: v)
    {
        int val = aint.query(1, x.second);
        aint.U(1, 0, aint.N, x.second, val + 1);
    }

    int cnt = aint.query(0, aint.N);

    LD mns = 20.0 - 5.0 * PI;
    LD add = 10.0 * PI - 20.0;

    if(cnt == (xfn - xst + 1) || cnt == (yfn - yst + 1))
    {
        cnt--;
        ans += add;
    }

    ans = ans - mns * cnt;

    cout << fixed << setprecision(15) << ans << '\n';

    return 0;
}

