		rep(i, n) y[i] *= -1;
		sy *= -1;
		y2 *= -1;
	}

	rep(i, n) {
		if (x1 <= x[i] && x[i] <= x2 && sy <= y[i] && y[i] <= y2) {
			pos.push_back(P(x[i], y[i]));
		}
	}
	sort(pos.begin(), pos.end());

	int INF = 1145141919810;
	rep(i, n + 1) lis[i] = INF;
