int solve() {
  vector<int> b = a;
  sort(ALL(b));
  b.erase(unique(ALL(b)), b.end());
  seg.n = b.size() + 5;
  int ret = 0;
  for (int x : a) {
    x = lower_bound(ALL(b), x) - b.begin();
    int t = seg.query(0, x) + 1;
    ret = max(ret, t);
    seg.modify(x, t);
  }
  return ret;
}

