            p[top].x=tmpx;p[top].y=tmpy;
        }
        sort(p+1,p+top+1,mmp1);
    }
    else{
        for (int i=1,tmpx,tmpy;i<=n;i++){
            tmpx=read();tmpy=read();
            if (tmpx>=sta.x&&tmpx<=endd.x
                &&tmpy<=sta.y&&tmpy>=endd.y)
                top++;
            else    continue;
            p[top].x=tmpx;p[top].y=tmpy;
        }
        sort(p+1,p+top+1,mmp2);
    }
    n=top;
    //加上同行或同列的特判
    if (sta.x==endd.x||sta.y==endd.y){
        double anns=0.0;
        if(n>0)     anns=anns+pi*10.0-20.0;
