            x[i]=p[i].x;
    }
    sort(x+1,x+n+1);
    for (int i=1;i<=n;i++)  p[i].x=lower_bound(x+1,x+n+1,p[i].x)-x;
    for (int i=1;i<=n;i++){
        int num=read(1,1,n,1,p[i].x);
        write(1,1,n,p[i].x,num+1);
    }
    long long diff1=abs(sta.x-endd.x),diff2=abs(endd.y-sta.y);
    double ans=(pi*5-2*10)*t[1]+diff1*100.0+diff2*100.0;
    if (min(abs(sta.x-endd.x),abs(sta.y-endd.y))+1==t[1]) ans+=5.0*pi;
    printf("%.15lf\n",ans);
