    aly.insert(a[i].y);
  }

  int id = 0;
  for (auto it : alx) {
    allx.push_back(it);
    idx[it] = id++;
  }
  id = 0;
  for (auto it : aly) {
    ally.push_back(it);
    idy[it] = id++;
  }

  encode(from);
  encode(to);
  for (int i = 0; i < n; i++) encode(a[i]);

  if (from.x > to.x) reverse_x();
  if (from.y > to.y) reverse_y();

  a[n] = from;
  a[n + 1] = to;
  sort(a, a + n + 2);

  int best = 0;
  segtree seg(aly.size());
  for (int i = 0; i < n + 2; i++) {
    if (a[i] == from) {
      seg.update(a[i].y, 0);
      //puts("FROM");
    }
    if (a[i] == to) {
      best = seg.find(0, a[i].y);
