int NN = 200001;
class SegmentTree {
    vector<int> data;
public:
    SegmentTree() {
        data = vector<int>(4*NN,0);
    }

    void update(int a, int v, int i = 1, int l = 0, int r = NN) {
        if (a < l || a >= r) return;
        if (a == l && (r-l) == 1) {
            data[i] += v;
            return;
        }
        int mid = l + (r - l) / 2;
        update(a, v, 2*i, l, mid);
        update(a, v, 2*i+1, mid, r);
        data[i] = max(data[2*i], data[2*i+1]);
    }

    int query(int a, int b, int i = 1, int l = 0, int r = NN) {
        if (b <= l || a >= r) return 0;
        if (a <= l && r <= b) return data[i];
        int mid = l + (r - l) / 2;
        return max(query(a,b,2*i,l,mid),query(a,b,2*i+1,mid,r));
    }

};

