typedef long long int ll;
typedef pair<int, int> pii;
typedef pair<ll, int> pli;


const int MAX_N = 200000;
const ll INF = (ll)1e9;

int X1, Y1, X2, Y2;
int N, K;
int inv;
ll x[MAX_N], y[MAX_N];
pli rx[MAX_N];
vector<ll> a;
ll dp[MAX_N], dpi[MAX_N];

int main() {

    double ans;

    cin >> X1 >> Y1 >> X2 >> Y2;
    cin >> N;
    if (X1 > X2) {
        swap(X1, X2);
        swap(Y1, Y2);
    }
    inv = Y1 > Y2 ? -1 : 1;
    Y1 *= inv; Y2 *= inv;
    ans = ((X2 - X1) + (Y2 - Y1)) * 100;

    for (int i = 0; i < N; i++) {
        cin >> x[i] >> y[i];
        y[i] *= inv;
        rx[i] = pii(x[i], i);
    }
    sort(rx, rx + N);

    for (int i = 0; i < N; i++) {
        ll xx = rx[i].first;
        ll yy = y[rx[i].second];
        if (X1 <= xx && xx <= X2 && Y1 <= yy && yy <= Y2) {
            a.push_back(rx[i].second);
        }
    }
    K = a.size();

    fill(dp, dp + K, INF);
    for (int j = 0; j < K; j++) {
        int idx = lower_bound(dp, dp + K, y[a[j]]) - dp;
        dp[idx] = y[a[j]];
        dpi[idx] = a[j];
    }
    int cnt = lower_bound(dp, dp + K, INF) - dp;

    if (cnt == 0) {
        cout << ans << endl;
        return 0;
    }

    bool has_space = true;
    if (x[dpi[0]] == X1 && x[dpi[cnt - 1]] == X2) {
        has_space = false;
        for (int j = 1; j < cnt; j++) {
            if (x[j] - x[j - 1] > 1) {
                has_space = true;
                break;
            }
        }
    }
   if (y[dpi[0]] == Y1 && y[dpi[cnt - 1]] == Y2) {
        has_space = false;
        for (int j = 1; j < cnt; j++) {
            if (y[j] - y[j - 1] > 1) {
                has_space = true;
                break;
            }
        }
    }

    ans -= cnt * 20 - cnt * 5 * M_PI;
    if (!has_space) {
        ans += 5 * M_PI;
    }

    cout << setprecision(15) << ans << endl;

    return 0;

}

#include<bits/stdc++.h>
