// eine LIS dieser Länge endet; das Array ist per Def. aufsteigend sortiert

// Berechnet Länge der LIS (strict increasing, sequ[i1] < sequ[i2)
int LIS(int N) {
  int maxlen = 0;
  minval[0] = LLONG_MIN;          // Falls nur '<=' gelten muss:
  FOR (i, 0, N) {                 // lower_bound durch upper_bound ersetzen
    lis[i] = lower_bound(minval, minval + maxlen + 1, sequ[i]) - minval;
    if (lis[i] > maxlen) {
      maxlen = lis[i];
      minval[maxlen] = sequ[i];
    } else if (sequ[i] < minval[lis[i]]) {
      minval[lis[i]] = sequ[i];
    }
  }
  return maxlen;
}


