int lis(vi a) {
	vi c;
	for (int x : a) {
		c.pb(x);
	}
	sort(all(c));
	c.resize(unique(all(c)) - c.begin());
	for (int& x : a) {
		x = lower_bound(all(c), x) - c.begin(); 
	}

	const int INF = 1e9;
	vi dp(sz(a) + 1, INF);
	dp[0] = -INF;
	for (int x : a) {
		int pos = upper_bound(all(dp), x) - dp.begin();
		--pos;
		assert(pos >= 0);
		dp[pos + 1] = min(dp[pos + 1], x);
	}
	ford(i, sz(dp)) {
		if  (dp[i] < INF) {
			return i;
		}
	}
	assert(0);
	return -1;
