ld solve() {
	if  (S.x > F.x) {
		swap(S, F);
	}

	int x1 = S.x;
	int x2 = F.x;
	int y1 = S.y;
	int y2 = F.y;
	if  (y1 > y2) {
		swap(y1, y2);
	}

	auto contain = [&](const pnt& p) {
		return (x1 <= p.x && p.x <= x2) && (y1 <= p.y && p.y <= y2);
	};

	if  (S.x == F.x || S.y == F.y) {
		bool bad = 0;
		for (const auto& p : ps) {
			if  (contain(p)) {
				assert(!bad);
				bad = 1;
			}
		}

		ld ans = (abs(S.x - F.x) * 1ll + abs(S.y - F.y)) * 100.0;
		if  (bad) {
			ans -= r * 2;
			ans += PI * r;
		}
		return ans;
	}

	vector<pnt> nps;
	for (const auto& p : ps) {
		if  (contain(p)) {
			nps.pb(p);
		}
	}
	ps.swap(nps);

	sort(all(ps));
	vi ys;
	for (const auto& p : ps) {
		ys.pb(p.y);
