	ld corners = lis(ys);

	ld ans = (abs(S.x - F.x) * 1ll + abs(S.y - F.y)) * 100.0;

	// printf("init ans = %.10f\n", (double) ans);

	ans -= corners * (2 * r);
	ans += corners * ((r / 2) * PI);
	return ans;
}

