  inline T query(int l, int r){
    T ret = INF;
    for(l+=n, r+=n; l<r; l/=2, r/=2){
      if(l&1) ret = min(ret, data[l++]);
      if(r&1) ret = min(ret, data[--r]);
    }
    return ret;
  }
  inline void update(int k, T a){
    k+=n;
    data[k]=a;
    while(k>0){
      k = k/2;
      data[k] = min(data[k*2], data[k*2+1]);
    }
  }
  inline T operator[](int idx){ return data[idx+n]; }
};

int main(){
  int sx,sy,tx,ty;
  cin>>sx>>sy>>tx>>ty;
  int n;
  cin>>n;
  using P = pair<int,int>;
  vector<P> vec(n);
  rep(i,n) cin>>vec[i].first>>vec[i].second;

  auto hoge = [&](){
    double ans = abs(sy-ty)*100;
    int l = min(sy,ty);
    int r = max(sy,ty);
    rep(i,n){
      if(vec[i].first == sx && l<=vec[i].second && vec[i].second <= r){
        ans += (PI*10 - 20);
      }
    }
    printf("%.15f\n", ans);
  };

  if(sx==tx){
    hoge();
    return 0;
  } else if(sy==ty){
    swap(sx,sy); swap(tx,ty);
    rep(i,n) swap(vec[i].first, vec[i].second);
    hoge();
    return 0;
  }

  int l = min(sx,tx);
  int r = max(sx,tx);
  int u = max(sy,ty);
  int d = min(sy,ty);
  int m = u-d+1;

  auto in = [&](int p, int q){
    return l<=p && p<=r && d<=q && q<=u;
  };

  if( (l==sx && u==sy) || (l==tx && u==ty) ){
    rep(i,n) if( in(vec[i].fi, vec[i].se) ) vec[i].second = d + (u - vec[i].second);
  }

  sort(all(vec));
  SegTree<double> st(m+1);
  st.update(0, 0);

  rep(i,n) if( in(vec[i].fi, vec[i].se) ){
    if(vec[i].fi == r){
      double ans = min(st.query(0, vec[i].se-d) + (PI*10 - 20), st[vec[i].se-d] + (PI*5 - 20));
      ans = min(ans, st.query(vec[i].se-d+1, m+1));
      ans += (r-l + u-d)*100;
      printf("%.15f\n", ans);
      return 0;
    }
    if(vec[i].fi == l){
      st.update(vec[i].se-d, (PI*5 - 20));
      st.update(vec[i].se-d+1, (PI*10 - 20));
      continue;
    }

    if(i>0 && vec[i-1].fi+1 == vec[i].fi && vec[i-1].se+1 == vec[i].se){
      double prev = st[vec[i].se-d-1];
      double crnt = st[vec[i].se-d];

      st.update(vec[i].se-d, min(crnt + (PI*10 - 20), prev + (PI*5 - 20)));
      st.update(vec[i].se-d+1, min(crnt + (PI*5 - 20), prev + (PI*10 - 20)));
    }
    else {
      double val = st.query(0, vec[i].se - d+1) + (PI*5 - 20);
      st.update(vec[i].se-d, val);
      if(vec[i].se<u) st.update(vec[i].se-d+1, val);
    }
  }

  double ans = (r-l + u-d)*100 + st.query(0,m);
  printf("%.15f\n", ans);

  return 0;
}

