#include <bits/stdc++.h>
using namespace std;
typedef long long int ll;
typedef pair<int, int> pii;
typedef pair<ll, int> pli;


const int MAX_N = 200000;
const ll INF = (ll)1e9;

int X1, Y1, X2, Y2;
int N, K;
int inv_x, inv_y;
ll x[MAX_N], y[MAX_N];
pli rx[MAX_N];
vector<ll> a;
ll dp[MAX_N];

int main() {

    double ans;

    cin >> X1 >> Y1 >> X2 >> Y2;
    cin >> N;
    inv_x = X1 > X2 ? -1 : 1;
    inv_y = Y1 > Y2 ? -1 : 1;
    X1 *= inv_x; X2 *= inv_x;
    Y1 *= inv_y; Y2 *= inv_y;

    for (int i = 0; i < N; i++) {
        cin >> x[i] >> y[i];
        x[i] *= inv_x; y[i] *= inv_y;
        rx[i] = pii(x[i], i);
    }
    sort(rx, rx + N);

    for (int i = 0; i < N; i++) {
        ll xx = rx[i].first;
        ll yy = y[rx[i].second];
        if (X1 <= xx && xx <= X2 && Y1 <= yy && yy <= Y2) {
            a.push_back(rx[i].second);
        }
    }
    K = a.size();

    fill(dp, dp + K, INF);
    for (int j = 0; j < K; j++) {
        int idx = lower_bound(dp, dp + K, y[a[j]]) - dp;
        dp[idx] = y[a[j]];
    }
    int cnt = lower_bound(dp, dp + K, INF) - dp;

    ans = ((X2 - X1) + (Y2 - Y1)) * 100;
    ans -= cnt * 20 - cnt * 5 * M_PI;
    if (cnt == min(X2 - X1, Y2 - Y1) + 1) {
        ans += 5 * M_PI;
    }

    cout << setprecision(15) << ans << endl;

    return 0;

}

