typedef pair<int, int> PII;
typedef long long LL;
typedef unsigned long long ULL;
typedef double DB;
const double PI = acos(-1);
const int MaxN = 2e5;
int n;
int l[MaxN + 5], len[MaxN + 5], r[MaxN + 5];
vector<int>ans;
vector<int>res;
map<pair<int, int>, int>num;
struct Node {
	int x, y, p;
}a[MaxN + 5], b[MaxN + 5], s, t;
int tot = 0, Min_x, Max_x, Min_y, Max_y;

bool cmp(Node a, Node b) {
	if(a.x == b.x) return a.y < b.y;
	return a.x < b.x;
}

bool check(Node X){
	if(X.x >= Min_x && X.x <= Max_x && X.y >= Min_y && X.y <= Max_y) return true;
	return false;
}
void Init(){
	tot = 0;
	Min_x = min(s.x, t.x);
	Max_x = max(s.x, t.x);
	Min_y = min(s.y, t.y);
	Max_y = max(s.y, t.y);
	for(int i = 1; i <= n; i++) scanf("%d%d", &a[i].x, &a[i].y);
	for(int i = 1;i <= n;i++){
		if(check(a[i])){
			b[++tot] = a[i];
			b[tot].p = tot;
		}
	}
}
void Solve() {
	sort(b + 1, b + tot + 1, cmp); b[0].x = -(1 << 30); b[n + 1].x = 1 << 30;
	for(int i = 1; i <= tot; i++) len[i] = (1 << 30); len[0] = -(1 << 30);
	int p = 1;
	for(int i = 1; i <= tot; i++) {
		if(b[i].x >= b[i - 1].x) {
			for(int j = p; j < i; j++) len[l[j]] = min(len[l[j]], b[j].y);
			p = i;
		}
		int L = 0, R = n, mid, s = 0;
		while(L <= R) {
			mid = (L + R) >> 1;
			if(len[mid] <= b[i].y) s = mid, L = mid + 1;
			else R = mid - 1;
		}
		l[i] = s + 1;
	}
	if(s.x == t.x){
		printf("%.15lf\n", (abs(t.y - s.y) * 1.0 * 100 + 1.0 * tot * PI * 10 - 20.0 * tot));
		return;
	}
	if(s.y == t.y){
		printf("%.15lf\n", (abs(t.x - s.x) * 1.0 * 100 + 1.0 * tot * PI * 10 - 20.0 * tot));
		return;
	}
	int len_all = Max_x + Max_y - Min_x - Min_y;
	int Max = 0, cont = 0, cnt = 0;
	for(int i = 1;i <= tot;i++) Max = max(Max, l[i]);
	for(int i = 1;i <= tot;i++){
		if(l[i] == Max){
			cont++;
			if(b[i].y == s.y || b[i].y == t.y){
				cnt++;
			}
		}
	}
	if(cont != cnt) Max--;
	double res = 1.0 * len_all * 100.0 + 1.0 * Max * PI * 5 - 20.0 * Max;
	printf("%.15lf\n", res);
}

int main()
{
	while(~scanf("%d%d%d%d%d", &s.x, &s.y, &t.x, &t.y, &n)) {
		Init();
		Solve();
	}
}

#include <bits/stdc++.h>

#define ll long long
#define maxn 300000
#define pii pair<int, int>
#define M_PI 3.141592653589793238462643383279502884
using namespace std;

int vals[maxn];
int seg[maxn*4];
int n;


void update(int ss, int se, int cur, int up, int spot) {
	if (spot < ss || se < spot || ss > se) return;
	if (ss == se && ss == spot) {
		seg[cur] = up;
		return;
	}
	int mid = (ss+se)/2;
	update(ss, mid, cur*2+1, up, spot);
	update(mid+1, se, cur*2+2, up, spot);
	seg[cur] = max(seg[cur*2+1], seg[cur*2+2]);
}

void upd(int val, int spot) {
	update(0, n-1, 0, val, spot);
}

int qu(int qs, int qe, int ss, int se, int cur) {
	if (qe < ss || se < qs) return -1;
	// cout << "   " << ss << " " << se << endl;

	if (qs <= ss && se <= qe) return seg[cur];
	int mid = (ss+se)/2;
	return max(qu(qs, qe, ss, mid, cur*2+1), 
		qu(qs, qe, mid+1, se, cur*2+2));
