	cin >> x1 >> y1 >> x2 >> y2 >> n;
	if(y1 > y2){
		swap(x1, x2);
		swap(y1, y2);
	}
	const int min_x = min(x1, x2), max_x = max(x1, x2);
	vector<pii> points;
	for(int i = 0; i < n; ++i){
		int x, y;
		cin >> x >> y;
		if(y < y1 || y2 < y){ continue; }
		if(x < min_x || max_x < x){ continue; }
		if(x1 < x2){
			points.emplace_back(y - y1, x - x1);
		}else{
			points.emplace_back(y - y1, x1 - x);
		}
	}
	const int w = max_x - min_x, h = y2 - y1;
	if(w == 0 || h == 0){
		double answer = (w + h) * 100.0;
		if(!points.empty()){ answer += (20 * M_PI / 2 - 20); }
		cout << answer << endl;
		return 0;
	}
	vector<int> xc = { 0, w, w + 1 };
	for(const auto& p : points){
		xc.push_back(p.second);
		xc.push_back(p.second + 1);
	}
	sort(xc.begin(), xc.end());
	xc.erase(unique(xc.begin(), xc.end()), xc.end());
	loquat::segment_tree<range_query_behavior> st(xc.size());
	st.update(0, 0);
	for(const auto& p : points){
		const int xx = lower_bound(xc.begin(), xc.end(), p.second) - xc.begin();
		const int val = st[xx];
		const int mv = st.query(0, xx), mh = max(mv, val);
		st.update(xx, mv + 1);
		st.update(xx + 1, max(st[xx + 1], mh + 1));
	}
	const double reduce = max(
		(20 - 20 * M_PI / 4) * st.query(0, xc.size() - 1),
		(20 - 20 * M_PI / 4) * st.query(0, xc.size()) - (20 * M_PI / 2 - 20));
	const double answer = (w + h) * 100.0 - reduce;
	cout << answer << endl;
	return 0;
}

