template <typename T>
int LIS(int a[], int n, T cmp){
	static int cnt, len[MAXN];
	len[cnt = 0] = -1;
	for (int i = 0; i < n; ++i)
		(cmp(len[cnt], a[i]) ? len[++cnt] : *lower_bound(len, len + cnt + 1, a[i], cmp)) = a[i];
	return cnt;
}

