int main(){
    cout<<fixed<<setprecision(12);
    int x1,y1,x2,y2;
    cin>>x1>>y1>>x2>>y2;
    int n;
    cin>>n;
    vector<int> a(n),b(n);
    rep(i,n){
        cin>>a[i]>>b[i];
    }
    if(x1>x2){
        swap(x1,x2);swap(y1,y2);
    }
    if(y1>y2){
        y1=-y1;y2=-y2;
        rep(i,n)b[i]=-b[i];
    }
    vector<int> na,nb;
    rep(i,n){
        if(x1<=a[i] && a[i]<=x2 && y1<=b[i] && b[i] <= y2){
            na.push_back(a[i]);
            nb.push_back(b[i]);
        }
    }
    a.swap(na);b.swap(nb);
    n=a.size();
    vector<int> ord(n);
    rep(i,n)ord[i]=i;
    sort(ord.begin(),ord.end(),[&](int x,int y){
        return b[x]==b[y]?a[x]>a[y]:b[x]<b[y];
    });
    vector<ll> dp(n+1,longinf);
    dp[0]=-longinf;
    for(auto i:ord){
        auto itr = lower_bound(dp.begin(),dp.end(),a[i]);
        *itr = a[i];
    }
    int ans= 0;
    rep(i,n+1){
        if(dp[i]!=longinf)ans = i;
    }
    double dist = (x2-x1)+(y2-y1);
    if(ans == min(y2-y1,x2-x1)+1){
        --ans;
        dist += (10*acos(-1)-20);
    }
    cout<<100*dist+(10*asin(1)-20)*ans<<endl;
    return 0;
}

