struct BIT {
  vi A;
  BIT(lli n) : A(n+1,0){ }

  lli get(lli i){
    i += 1;
    lli r = 0;
    for(; i > 0; i -= i &-i){
      r=max(r,A[i]);
    }
    return r;
  }

  // lli getR(lli l, lli r) {
  //   lli ans = get(r);
  //   if(l) ans -= get(l-1);
  //   return ans;
  // }

  void add(lli i, lli v){
    i += 1;
    for(; i < (lli)A.size(); i += i & -i){
      A[i] = max(A[i],v);
    }
  }
};

