const int N = 2e5 + 10; 
struct point {
	int x, y; 
	point (int x = 0, int y = 0) : x(x), y(y) { }
} a[N]; 
int realn, n, command; 
point start, finish;

bool inside (point p) {
	return min(start.x, finish.x) <= p.x && p.x <= max(start.x, finish.x) && min(start.y, finish.y) <= p.y && p.y <= max(start.y, finish.y); 
}

void compress () {
	sort (a + 1, a + 1 + n); 
	vector<int> rar; 
	for (int i = 1; i <= n; i++) {
		rar.push_back(a[i].y); 
	}
	removeDuplicate(rar); 
	for (int i = 1; i <= n; i++) {
		a[i].y = lower_bound(rar.begin(), rar.end(), a[i].y) - rar.begin() + 1; 
	}

}

bool operator < (point a, point b) {
	if (command == 0) return a.x > b.x; 
	return a.x < b.x; 	
}
int f[N]; 
namespace BIT {
	int bit[N];
	void assign (int key, int value) {
		for (; key <= n; key += key & -key) {
			bit[key] = max(bit[key], value); 
		} 

	}
	int prefMax (int key) {
		int res = 0; 
		for (; key > 0; key -= key & -key) {
			res = max(res, bit[key]); 
		}
		return res; 
	}
}

