#include "bits/stdc++.h"
using namespace std;
const int N = 2e5 + 5;
const int M = 100000000;
const double pi = acos(-1);
int n;
pair < int , int > arr[N];
int dp[N];
int bit[N];
map < int , int > mp;
int ori[N];
void update(int idx , int val){
	while(idx <= n){
		bit[idx] = max(bit[idx] , val);
		idx += idx & -idx;
	}
}
int query(int idx){
	int res = 0;
	while(idx){
		res = max(res , bit[idx]);
		idx -= idx & -idx;
	}
	return res;
}
int main(){
	int x1 , y1 , x2 , y2;
	scanf("%d %d %d %d" , &x1 , &y1 , &x2 , &y2);
	scanf("%d" , &n);
	for(int i = 1 ; i <= n ; ++i){
		scanf("%d %d" , &arr[i].first , &arr[i].second);
	}
	if(x1 > x2){
		x1 = M - x1;
		x2 = M - x2;
		for(int i = 1 ; i <= n ; ++i){
			arr[i].first = M - arr[i].first;
		}
	}
	if(y1 > y2){
		y1 = M - y1;
		y2 = M - y2;
		for(int i = 1 ; i <= n ; ++i){
			arr[i].second = M - arr[i].second;
		}
	}
	mp.clear();
	for(int i = 1 ; i <= n ; ++i){
		mp[arr[i].second];	
	}
	int cur = 0;
	for(auto &it : mp){
		it.second = ++cur;
		ori[cur] = it.first;
	}
	for(int i = 1 ; i <= n ; ++i){
		arr[i].second = mp[arr[i].second];
	}
	sort(arr + 1 , arr + 1 + n);
	int profit = 0;
	for(int i = 1 ; i <= n ; ++i){
		if(arr[i].first < x1 || arr[i].first > x2 || ori[arr[i].second] < y1 || ori[arr[i].second] > y2){
			continue;
		}
		dp[i] = query(arr[i].second - 1) + 1;
		update(arr[i].second , dp[i]);
		profit = max(profit , dp[i]);
	}
	printf("%.12lf\n" , (x2 - x1 + y2 - y1) * 100LL - 10LL * ((2.0 - (pi / 2.0)) * profit) + ((profit > min(y2 - y1 , x2 - x1)) ? 5 * pi : 0));
}

