namespace bit {
	double t[N+10];
	void clear() {
		for (int i=0;i<=N;i++) t[i]=1e18;
		return;
	}
	int lowbit(int x) {
		return x&(-x);
	}
	double Query(int x) {
		double minx=1e18;
		while (x>0) {
			minx=min(minx,t[x]);
			x-=lowbit(x);
		}
		return minx;
	}
	void Add(int x,double va) {
		while (x<=N) {
			t[x]=min(t[x],va);
			x+=lowbit(x);
		}
	}
}
bool cmpx(point p,point q) {
	return p.x<q.x;
}
bool cmpy(point p,point q) {
