	a[0].x=a[0].y=0;
	a[n+1].x=tx;
	a[n+1].y=ty;
}
bool find(int x,int y) {
	int l=1,r=n;
	while (l<=r) {
		int mid=(l+r)/2;
		if (b[mid].x==x) {
			if (b[mid].y!=y) return 0;
			return 1;
		}
		if (b[mid].x<x) l=r+1;else r=l-1;
	}
	return 0;
}
void prework() {
	sort(a+1,a+n+1,cmpx);
	for (int i=0;i<=n+1;i++) a[i].loc=i;
	for (int i=1;i<=n;i++) b[i]=a[i];
	discretization();
	int k=1e9;
	for (int i=1;i<=n;i++) {
		bool judge=1;
		for (int j=max(0,i-ty);j<=i&&j<=tx;j++) {
			int nowx=j,nowy=i-j;
			if (!find(nowx,nowy)) {
				judge=0;
				break;
			}
		}
		if (judge) {
			k=i;
			break;
		}
	}
	for (int i=1;i<=n;i++)
		if (a[i].x+a[i].y<=k) {
			viss[i]=1;
