	cx=unique(c+1,c+cx+1)-c-1,cy=unique(d+1,d+cy+1)-d-1;
	for(int i=1;i<=N;i++){
		p[i].x=lower_bound(c+1,c+cx+1,p[i].x)-c;
		p[i].y=lower_bound(d+1,d+cy+1,p[i].y)-d;
	}
	x1=lower_bound(c+1,c+cx+1,x1)-c; y1=lower_bound(d+1,d+cy+1,y1)-d;
	x2=lower_bound(c+1,c+cx+1,x2)-c; y2=lower_bound(d+1,d+cy+1,y2)-d;
	double ans=abs(d[y1]-d[y2])*100+abs(c[x1]-c[x2])*100;
	if(x1>x2) swap(x1,x2),swap(y1,y2); solve();
	swap(x1,y1); swap(x2,y2); if(x1>x2) swap(x1,x2); 
	for(int i=1;i<=N;i++) swap(p[i].x,p[i].y); swap(cy,cx);
	solve(); printf("%.14lf\n",min(ans-ret,zei+ans));
}

