		return;
	}
	int Query(int x) {
		int maxx=0;
		while (x>0) {
			maxx=max(maxx,t[x]);
			x-=lowbit(x);
		}
		return maxx;
	}
	void Add(int x,int va) {
		while (x<=N) {
			t[x]=max(t[x],va);
			x+=lowbit(x);
		}
	}
