struct node {
    node *l, *r;
    int val, tl, tr;
    node(int tll, int trr) {
        tl = tll;
        tr = trr;
        val = 0;
        l = r = NULL;
    }
    void add(int pos, int newval) {
        if (pos == tl && pos == tr) {
            val = newval;
            return;
        }
        int mid = (tl + tr) / 2;
        if (pos <= mid) {
            if (!l) {
                l = new node(tl, mid);
            }
            l->add(pos, newval);
        } else {
            if (!r) {
                r = new node(mid + 1, tr);
            }
            r->add(pos, newval);
        }
        if (l) val = max(val, l->val);
        if (r) val = max(val, r->val);
    }
    int get(int ll, int rr) {
        if (ll == tl && rr == tr) {
            return val;
        }
        int mid = (tl + tr) / 2;
        if (rr <= mid) {
            if (l) return l->get(ll, rr);
            else return 0;
        } else if (ll > mid) {
            if (r) return r->get(ll, rr);
            else return 0;
        }
        int ans = 0;
        if (l) ans = max(ans, l->get(ll, mid));
        if (r) ans = max(ans, r->get(mid + 1, rr));
        return ans;
    }
};

