 vl lis;
 ll LIS(vl & v) {
     lis.assign(sz(v), 0);
     vl minval(1);
     ll maxlen = 0;
     minval[0] = LLONG_MIN;
     FOR (i, 0, sz(v)) {
         lis[i] = lower_bound(all(minval), v[i]) - minval.begin();
         if (lis[i] > maxlen) {
             maxlen = lis[i];
             minval.push_back(v[i]);
         } else {
             minval[lis[i]] = min(minval[lis[i]], v[i]);
         }
     }
     return maxlen;
 }


