// DAG
vector<long long int> dp;
vector<vector<int>> graph;

long long int DFS(int v){
    if(dp[v] != -1) return dp[v];

    dp[v] = 0;// if no next_v (i.e. sink) dp[v] = 0, visited[v] = true
    for(int next_v : graph[v]){
        dp[v] = max(dp[v], DFS(next_v) + 1);
    }
    return dp[v];
}

int main(){
    int x1, y1, x2, y2, n;
    cin >> x1 >> y1 >> x2 >> y2 >> n;

    bool flagx = false;
    bool flagy = false;
    vector<pair<int,int>> fountain;
    if(x1 > x2){ x1 *= -1; x2 *= -1; flagx = true; }
    if(y1 > y2){ y1 *= -1; y2 *= -1; flagy = false; }
    fountain.push_back({x1,y1});
    fountain.push_back({x2,y2});

    map<int,int> fx, fy;

    for(int i=0; i<n; i++){
        int x, y;
        cin >> x >> y;

        if(flagx == true) x *= -1;
        if(flagy == true) y *= -1;

        if(x < x1 || x2 < x
        || y < y1 || y2 < y) continue;

        fx[x] = y;
        fy[y] = x;
        fountain.push_back({x,y});
    }

    long double ans = abs(x2 - x1) * 100 + abs(y2 - y1) * 100;

    if(x1 == x2){
        if(fx.find(x1) != fx.end()
        && y1 < fx[x1] && fx[x1] < y2) ans += 10 * PI - 20;
    }
    else if(y1 == y2){
        if(fy.find(y1) != fy.end()
        && x1 < fy[y1] && fy[y1] < x2) ans += 10 * PI - 20;
    }
    else{
        n = fountain.size();
        dp.assign(n, -1);
        graph.resize(n);

        for(int i=0; i<n; i++){
            //cout << fountain[i].first << " " << fountain[i].second << endl;
            for(int j=0; j<n; j++){
                if(i == j) continue;

                if(fountain[i].first  <= fountain[j].first
                && fountain[i].second <= fountain[j].second){
                    graph[i].push_back(j);
                }
            }
        }
        int fmax = DFS(0) - 1;
        ans -= (20 - 5*PI) * fmax;
    }
    cout << fixed << setprecision(12) << ans << endl;
    return 0;
}

