void normalize(vector<pair<ll,ll>>& v, int N) {
  vector<pair<ll,int> > t(N+2);
  {
    REP(i, N) {
      t[i].first = v[i].first;
      t[i].second = i;
    }
    sort(ALL(t));
    int r = 0;
    REP(i, N) {
      r += (i > 0 && t[i - 1].first != t[i].first);
      v[t[i].second].first = r;
    }
  }
  {
    REP(i, N) {
      t[i].first = v[i].second;
      t[i].second = i;
    }
    sort(ALL(t));
    int r = 0;
    REP(i, N) {
      r += (i > 0 && t[i - 1].first != t[i].first);
      v[t[i].second].second = r;
    }
  }
  return;
}

