int Max = 1e8;
int inf = 1e9;
long double S = (long double)5.0 * (long double)acos(-1);
long double D = S - (long double)20.0;

int x_1, y_1, x_2, y_2;

bool izryt(pair<int, int> a, pair<int, int> b) {
  if (a.first == b.first) {
    return a.second > b.second;
  }
  return a.first < b.first;
}

bool h, w;
pair<int, int> solve(int x, int y) {
  if (h) y = Max - y;
  if (w) x = Max - x;

  return pair<int, int>(x, y);
}

bool outside(pair<int, int> a, pair<int, int> s, pair<int, int> g) {
  return a.first < s.first || g.first < a.first ||
         a.second < s.second || g.second < a.second;
}

long double dist(pair<int, int> a, pair<int, int> b) {
  long double res = (long double)b.first - (long double)a.first + (long double)b.second - (long double)a.second;
  return res * (long double)100.0;
}

int main() {
  cin >> x_1 >> y_1 >> x_2 >> y_2;

  if (x_1 > x_2) w = true;
  if (y_1 > y_2) h = true;

  pair<int, int> s = solve(x_1, y_1),
                 g = solve(x_2, y_2);

  int n;
  cin >> n;

  vector<pair<int, int>> v;
  for (int i = 0; i < n; ++i) {
    int x, y;
    cin >> x >> y;
    pair<int, int> p = solve(x, y);

    if (outside(p, s, g)) continue;
    v.push_back(p);
  }

  sort(v.begin(), v.end(), izryt);

  vector<int> dp(n + 1, inf);
  for (int i = 0; i < v.size(); ++i) {
    *lower_bound(dp.begin(), dp.end(), v[i].second) = v[i].second;
  }

  int ans = lower_bound(dp.begin(), dp.end(), inf) - dp.begin();
  if (s.first == g.first || s.second == g.second) {
    cout << fixed << setprecision(18) << dist(s, g) + (v.size() ? - (long double)20.0 + (long double)2.0 * S : (long double)0) << endl;
  } else {
    cout << fixed << setprecision(18) << dist(s, g) + (long double)ans * D << endl;
  }
}

