}

int main() {
    auto from = ReadPoint(), to = ReadPoint();
    int n; cin >> n;
    vector<Point> points;
    while (n--) {
        points.push_back(ReadPoint());
    }

    if (to.x < from.x) {
        to.x = -to.x;
        from.x = -from.x;
        for (auto& p : points)
            p.x = -p.x;
    }

    if (to.y < from.y) {
        to.y = -to.y;
        from.y = -from.y;
        for (auto& p : points)
            p.y = -p.y;
    }

    const double bullshit = 20.0 * atan(1.0);

    cout << fixed << setprecision(12);

    if (to.x == from.x) {
        double ans = to.y - from.y;
        ans *= 100;

        for (auto& p : points) {
            if (p.x == to.x && p.y > from.y && p.y < to.y)
                ans += 2 * bullshit - 2 * 10;
        }
        cout << ans << endl;
        return 0;
    }


    if (to.y == from.y) {
        double ans = to.x - from.x;
        ans *= 100;

        for (auto& p : points) {
            if (p.y == to.y && p.x > from.x && p.x < to.x)
                ans += 2 * bullshit - 2 * 10;
        }
        cout << ans << endl;
        return 0;
    }


    points.erase(remove_if(
        points.begin(),
        points.end(),
        [&](Point p) {
            return p.x < from.x or p.x > to.x or p.y < from.y or p.y > to.y;
        }
    ), points.end());

    sort(points.begin(), points.end(), [](Point a, Point b) {
            return a.x < b.x;
    });
    vector<int> allYs;
    for (auto& p : points)
        allYs.push_back(p.y);
    sort(allYs.begin(), allYs.end());

    vector<int> T(points.size() + 1, 0);

    auto update = [&](int pos, int val) {
        for (++pos; pos < (int)T.size(); pos += (pos & -pos))
            T[pos] = max(T[pos], val);
    };
    auto query = [&](int pos) {
        int ans = 0;
        for (++pos; pos > 0; pos -= (pos & -pos))
            ans = max(ans, T[pos]);
        return ans;
    };

    int best = 0;
    for (auto p : points) {
        p.y = lower_bound(allYs.begin(), allYs.end(), p.y) - allYs.begin();
        int now = 1 + query(p.y);
        best = max(best, now);
        update(p.y, now);
    }

    cerr << "Best: " << best << endl;

    double ans = to.x - from.x + to.y - from.y;
    ans *= 100;

    ans -= 20 * best;
    ans += bullshit * best;


    cout << ans << endl;

    return 0;
}

