std::vector<P> vec;

int memo[200000];

int dfs(int m) {

	if (memo[m] >= 0)
		return memo[m];

	int res = 0;

	used[m] = true;

	int v = std::upper_bound(vec.begin(), vec.end(), vec[m]) - vec.begin();

	for (int i = v; i<vec.size(); ++i) {
		if (vec[m].second<vec[i].second)
			res = std::max(res, dfs(i));
	}

	used[m] = false;

	return memo[m] = res + 1;
}

int main() {

	int x1, y1, x2, y2;

