			cnt = std::max(cnt, dfs(i));
	}

	long double ans = (std::abs(x1 - x2) + std::abs(y1 - y2)) * 100.0 - 20.0 * (1.0 - PI/4)*(double)cnt;

	std::cout << std::fixed << std::setprecision(15) << ans << std::endl;


	return 0;
}

