		for(pii &p : P)
			p.se = -p.se;
	}
	for(pii &p : P)
		if(X1 <= p.fi && p.fi <= X2 && Y1 <= p.se && p.se <= Y2) {
			ir.pb(p);
			cc.insert(p.se);
		}
	int ctr = 0;
	for(int a : cc)
		lab[a] = ctr++;
	sort(ir.begin(),ir.end());
	n = ir.size();
	// for(int i = 0; i < n; ++i)
	// 	A[i] = lab[ir[i].se];
	t = segt<int>(n);
	int ans = 0;
	for(int i = 0; i < n; ++i) {
		int a = lab[ir[i].se];
		int bst = 1+t.query(0,a-1);
		t.update(a,bst-t.query(a,a));
