            return x = pll(-x.first, x.second);
        };
        flip(start);
        flip(goal);
        foreach(i, supring){
            flip(i);
        }
    }
    if(start.second==goal.second){
        foreach(i, supring){
            if(i.second!=start.second)continue;
            if(start.first<=i.first&&i.first<goal.first){
                return abs(start.first-goal.first)*100 + half_cir - 20;
            }
        }
        return abs(start.first-goal.first) * 100;
    }
    vector<ll> memo(n+2, INFLL);
    sort(all(supring));
    foreach(i, supring){
        if(i.first<start.first||goal.first<i.first)continue;
        if(i.second<start.second||goal.second<i.second)continue;
        *lower_bound(all(memo), i.second) = i.second;
    }

    int cnt = 0;

    rep(i, n+2){
        if(memo[i]!=INFLL){
            cnt = i + 1;
        }
    }
    if(goal.second-start.second+1==cnt){
        return (abs(start.first-goal.first)+abs(start.second-goal.second))*100+(cnt-1)*(quot_cir-20)+half_cir-20;
    }
    return (abs(start.first-goal.first)+abs(start.second-goal.second))*100+cnt*(quot_cir-20);
}

int main(){
    input();
    printf("%.20Lf\n", solve());
    return 0;
}

