		swap(Y1, y2);
	}
	bool rev = 0;
	if(Y1 > y2){
		rev = 1;
		Y1 = -Y1;
		y2 = -y2;
	}
	int N;
	cin >> N;
	rep(i,0,N){
		int X, Y;
		cin >> X >> Y;
		if(rev)
			Y = -Y;
		F.emplace_back(X, Y);
	}
	sort(all(F));
	M[Y1] = 0;
	rep(i,0,N){
		ll X = F[i].first;
		ll Y = F[i].second;
		if(X < x1 || X > x2 || Y < Y1 || Y > y2)
			continue;
		for(int j = i; j < N; ++j){
			int x = F[j].first;
			int y = F[j].second;
			if(x != x1+j-i || y != Y+j-i)
				break;
			if(x == x2){
				printf("%.13lf\n", 100.0*(y2-Y1+x2-x1)+(x2-x1+2)*(5*PI)-(x2-x1+1)*20.0);
				return 0;
			}
		}
		for(int j = i; j < N; ++j){
			int x = F[j].first;
			int y = F[j].second;
			if(x != X+j-i || y != Y1+j-i)
				break;
			if(y == y2){
				printf("%.13lf\n", 100.0*(y2-Y1+x2-x1)+(y2-Y1+2)*(5*PI)-(y2-Y1+1)*20.0);
				return 0;
			}
		}
		auto it = M.upper_bound(Y);
		if(it == M.begin())
			continue;
		--it;
		M[Y] = it->second+1;
		it = M.upper_bound(Y);
		if(it != M.end())
			M.erase(it);
	}
	auto it = M.upper_bound(y2);
	--it;
	int num = it->second;
	double ans = 100.0*(x2-x1+y2-Y1)+num*(5.0*PI-20.0);
	printf("%.13lf\n", ans);
}

