const LL MAXN = 400010;
const LL INF = 2147483600;

LL N;
const double Pi = 3.1415926535897932384626;
const double Ti = 20.0-5.0*Pi;
const double Ci = 10.0*Pi-20.0;

LL x1,y1,x2,y2;
LL dx[MAXN+1],dy[MAXN+1];
struct data{
	LL x,y;
}p[MAXN+1],to[MAXN+1];
bool cmp(data a,data b){
	if(a.x!=b.x) return a.x<b.x;
	return a.y<b.y;
} double ret=-INF; LL f[MAXN+1];
LL c[MAXN+1],cx,cy; LL d[MAXN+1];

inline LL lowbit(LL x){return x&(-x);}
inline void Add(LL k,LL x){
	for(;k<=cy;k+=lowbit(k)) c[k]=max(c[k],x);
} inline LL Query(LL k){
	LL ret=0; for(;k;k-=lowbit(k)) ret=max(ret,c[k]); return ret;
} LL topx; double zei=INF;

inline void solve(){
	sort(p+1,p+N+1,cmp); memset(c,0,sizeof(c));
	LL tmp=0; double num=0,rg=0;
	if(y1<y2){
		topx=0; data ng;
		for(LL i=1;i<=N;i++){
			if(p[i].x>=x1&&p[i].x<=x2&&p[i].y==y2) ng=p[i],num=Ci,rg+=Ci;
			if(p[i].y>=y1&&p[i].y<=y2&&p[i].x==x1) rg+=Ci; 
			if(p[i].x>=x1&&p[i].x<=x2&&p[i].y<=y2&&p[i].y>=y1) to[++topx]=p[i]; 
		} LL j=1,l=0;
		for(LL i=x1;i<=x2;i++){
			LL now=j; if(i==ng.x) num=0;
			while(j<=topx&&to[j].x==i) {
				f[j]=max(Query(to[j].y)+1,1LL);
				ret=max(ret,1.0*f[j]*Ti-num);++j;
			} for(LL k=now;k<j;k++) Add(to[k].y,f[k]);
		}
	} else{
		topx=0; data ng;
		for(LL i=1;i<=N;i++){
			if(p[i].x>=x1&&p[i].x<=x2&&p[i].y==y1) ng=p[i],num=Ci,rg+=Ci;
			if(p[i].y>=y2&&p[i].y<=y1&&p[i].x==x1) rg+=Ci; 
			if(p[i].x>=x1&&p[i].x<=x2&&p[i].y<=y1&&p[i].y>=y2) to[++topx]=p[i];
		} LL j=1,l=0;
		for(LL i=x1;i<=x2;i++){
			LL now=j; if(i==ng.x) num=0;
			while(j<=topx&&to[j].x==i) {
				f[j]=max(Query(to[j].y)+1,1LL);
				ret=max(ret,f[j]*Ti-num);++j;
			} for(LL k=now;k<j;k++) Add(cy-to[k].y+1,f[k]);
		}
	} zei=min(zei,rg);
}
