    cin >> n;
    for (int i = 1; i <= n; i++)
        scanf("%d%d", &p[i].fr, &p[i].sc);

    if ( st.fr > en.fr )
        swap(st, en);

    if (st.sc > en.sc)
    {
        st.fr = mx - st.fr;
        en.fr = mx - en.fr;
        for (int i = 1; i <= n; i++)
            p[i].fr = mx - p[i].fr;
        swap(st, en);
    }
    sort( p + 1, p + n + 1, cmp );
    if ( Check1() )
    {
        assert(0);
        cout << fixed << setprecision(12) << (en.sc - st.sc) * 100 + (en.fr - st.fr) * 100 - F * (en.sc - st.sc) + Q << endl;
        return 0;
    }
    sort( p + 1, p + n + 1 );
    if ( Check2() )
    {
        assert(0);
        cout << fixed << setprecision(12) << (en.sc - st.sc) * 100 + (en.fr - st.fr) * 100 - F * (en.fr - st.fr) + Q << endl;
        return 0;
    }
    for (int i = 1; i <= n; i++)
    {
        if ( p[i].fr < st.fr || p[i].fr > en.fr || p[i].sc < st.sc || p[i].sc > en.sc ) continue;

        dp[i] = get( 0, p[i].sc ) + 1;

        ans = max(ans, dp[i]);

        update( p[i].sc, dp[i] );
    }
    cout << fixed << setprecision(12) << (en.sc - st.sc) * 100 + (en.fr - st.fr) * 100 - F * ans << endl;
}

