        for(int i = 0;i < m;i++){
            int id = lower_bound(dp, dp + n + 1, A[i]) - dp - 1;
            dp[id + 1] = min(dp[id + 1], A[i]);
        }
        for(int i = 0;i <= n;i++){
            if(dp[i] != 0x3f3f3f3f){
                ans = max(ans, i);
            }
        }
        cout << (abs(X1 - X2) + abs(Y1 - Y2)) * 100.0 + ans * (pi * 5 - 20) << endl;
    }
    return 0;
}

