	a[0].x=a[0].y=0;
}
bool find(int x,int y) {
	int l=1,r=n;
	while (l<=r) {
		int mid=(l+r)/2;
		if (b[mid].x==x) {
			if (b[mid].y!=y) return 0;
			return 1;
		}
		if (b[mid].x<x) l=mid+1;else r=mid-1;
	}
	return 0;
}
void prework() {
	sort(a+1,a+n+1,cmpx);
	for (int i=1;i<=n;i++) a[i].loc=i;
	for (int i=1;i<=n;i++) b[i]=a[i];
	for (int i=1;i<=n;i++) c[i]=a[i].x+a[i].y;
	sort(c+1,c+n+1);
	discretization();
	int k1=1e9,k2=-1e9,k3=1e9,k4=-1e9;
	for (int i=1;i<=n;i++) {
		bool judge=1;
		for (int j=max(0,c[i]-ty);j<=c[i]&&j<=tx;j++) {
			int nowx=j,nowy=c[i]-j;
			if (!find(nowx,nowy)) {
				judge=0;
				break;
			}
		}
		if (judge) {
			k1=min(k1,c[i]);
			k2=max(k2,c[i]);
		}
	}
	for (int i=1;i<=n;i++) {
		bool judge=1;
		for (int j=0;j<=ty;j++) {
			int nowx=j+a[i].x,nowy=j;
			if (!find(nowx,nowy)) {
				judge=0;
				break;
			}
		}
		if (judge) {
			k3=min(k3,a[i].x);
			k4=max(k4,a[i].x);
		}
	}
	if (k1==1e9&&k3==1e9) ansjudge=1;
	for (int i=1;i<=n;i++)
		if (a[i].x+a[i].y<=k1&&a[i].x-a[i].y<=k3) {
			viss[i]=1;
			if (a[i].x==0) {
				viss[i]=2;
				continue;
			}
			if (a[i].y==0) {
				viss[i]=3;
				continue;
			}
			if (i>1&&a[i].x-a[i-1].x==1&&a[i-1].y<=a[i].y) {
				int nowy1=a[i-1].y,nowy2=nowy1;
				bool judge1=1,judge2=1;
				for (int j=a[i-1].x-1;j>=0;j--) {
					nowy1--;
					nowy2++;
					if (!find(j,nowy1)) judge1=0;
					if (!find(j,nowy2)) judge2=0;
					if (!judge1&&!judge2) break;
				}
				if (judge1||judge2) viss[i]=2;//up gg
			}
			if (a[i].nxt&&a[i].y-a[a[i].nxt].y==1&&a[i].nxt<=i) {
				int nowx1=a[a[i].nxt].x,nowx2=nowx1;
				bool judge1=1,judge2=1;
				for (int j=a[a[i].nxt].y-1;j>=0;j--) {
					nowx1--;
					nowx2++;
					if (!find(nowx1,j)) judge1=0;
					if (!find(nowx2,j)) judge2=0;
					if (!judge1&&!judge2) break;
				}
				if (judge1||judge2) viss[i]=3;//right gg
			}
		}
	for (int i=1;i<=n;i++)
		if (a[i].x+a[i].y>=k2&&a[i].x-a[i].y>=k4) {
			vist[i]=1;
			if (a[i].x==tx) {
				vist[i]=2;
				continue;
			}
			if (a[i].y==ty) {
				vist[i]=3;
				continue;
			}
			if (i>1&&a[i+1].x-a[i].x==1&&a[i+1].y>=a[i].y) {
				int nowy1=a[i+1].y,nowy2=nowy1;
				bool judge1=1,judge2=1;
				for (int j=a[i+1].x+1;j<=tx;j++) {
					nowy1--;
					nowy2++;
					if (!find(j,nowy1)) judge1=0;
					if (!find(j,nowy2)) judge2=0;
					if (!judge1&&!judge2) break;
				}
				if (judge1||judge2) vist[i]=2;//right gg
			}
			if (a[i].lat&&a[a[i].lat].y-a[i].y==1&&a[i].lat>=i) {
				int nowx1=a[a[i].lat].x,nowx2=nowx1;
				bool judge1=1,judge2=1;
				for (int j=a[a[i].lat].y+1;j<=ty;j++) {
					nowx1--;
					nowx2++;
					if (!find(nowx1,j)) judge1=0;
					if (!find(nowx2,j)) judge2=0;
					if (!judge1&&!judge2) break;
				}
				if (judge1||judge2) vist[i]=3;//up gg
			}
		}
}
double work() {
	prework();
	bit1.clear();
	bit2.clear();
	//for (int i=1;i<=n;i++) printf("%d: %d %d\n",i,viss[i],vist[i]);
	int nowk=1;
	for (int i=1;i<=n;i++) {
		if (viss[i]==1) ans1[i]=ans2[i]=(a[i].x+a[i].y)*100.0-10+5*pi;//1 right 2 up
			else if (viss[i]==2) {
				ans1[i]=(a[i].x+a[i].y)*100.0-10+5*pi;
				ans2[i]=(a[i].x+a[i].y)*100.0-10+10*pi;
			}
			else if (viss[i]==3) {
				ans2[i]=(a[i].x+a[i].y)*100.0-10+5*pi;
				ans1[i]=(a[i].x+a[i].y)*100.0-10+10*pi;
			}
			else ans1[i]=ans2[i]=1e18;
		double now=a[i].x*100.0+a[i].y*100.0-20.0+5*pi,now2=now;
		now+=bit1.Query(a[i].num-1);
		ans1[i]=min(ans1[i],now);
		now2+=bit2.Query(a[i].num-1);
		ans2[i]=min(ans2[i],now2);
		if (i==n) break;
		if (ans1[i]+5*pi<ans2[i]) ans2[i]=ans1[i]+5*pi;
		if (ans2[i]+5*pi<ans1[i]) ans1[i]=ans2[i]+5*pi;
		bit1.Add(a[i].num,ans1[i]-100.0*(a[i].x+a[i].y));
		bit2.Add(a[i].num,ans2[i]-100.0*(a[i].x+a[i].y));
	}
//	for (int i=1;i<=n;i++) printf("%d: %.10lf %.10lf\n",i,ans1[i],ans2[i]);
	double ans=1e18;
	if (ansjudge) ans=100.0*(tx+ty);
	for (int i=1;i<=n;i++) {
		if (!vist[i]) continue;
		double now=100.0*(tx+ty-a[i].x-a[i].y)-10;
		if (vist[i]==1) ans=min(ans,min(ans1[i],ans2[i])+now);
		else if (vist[i]==2) ans=min(ans,ans2[i]+now);
		else ans=min(ans,ans1[i]+now);
	}
	return ans;
}
