	if (st.x > fin.x) {
		st.x = LEN - st.x;
		fin.x = LEN - fin.x;
		forn (i, n)
			p[i].x = LEN - p[i].x;
	}
	if (st.y > fin.y) {
		st.y = LEN - st.y;
		fin.y = LEN - fin.y;
		forn (i, n)
			p[i].y = LEN - p[i].y;
	}

	vector<pt> q;

	forn (i, n) {
		if (p[i].x >= st.x && p[i].y >= st.y && p[i].x <= fin.x && p[i].y <= fin.y) {
			q.pb(mp(p[i].x - st.x, p[i].y - st.y));
		}
	}		

	fin.y -= st.y;
	fin.x -= st.x;
	st = {0, 0};

	n = sz(q);
	forn (i, n)
		p[i] = q[i];

	sort(p, p + n);	

	return true;
}

int f[N];

void inc(int pos, int val) {
	for (; pos < N; pos |= pos + 1)
		f[pos] = max(f[pos], val);
}

int get(int pos) {
	int res = 0;
	for (; pos >= 0; pos = (pos & (pos + 1)) - 1)
		res = max(res, f[pos]);
	return res;
}

int dp[N];

int up[N];

inline void solve() {   

	ld ans = ld(fin.x - st.x) * 100 + ld(fin.y - st.y) * 100;

	if (st.y == fin.y || st.x == fin.x) {
		ans -= 20 * n;
		ans += 10 * PI * n;
		cout << ans << endl;
		return;
	}

	vector<int> ys;
	ys.pb(st.y);
	ys.pb(fin.y);
	forn (i, n)
		ys.pb(p[i].y);
	sort(all(ys));
	forn (i, n)
		p[i].y = lower_bound(all(ys), p[i].y) - ys.begin();
	st.y = lower_bound(all(ys), st.y) - ys.begin();
	fin.y = lower_bound(all(ys), fin.y) - ys.begin();

	int l = 0;
	while(l < n) {
		int r = l;
		while(r < n && p[r].x == p[l].x) 
			r++;
		int ll = l;
		while(ll < r) {
			dp[ll] = get(p[ll].y) + 1;
			ll++;
		}
		for (int i = r - 1; i >= l; --i) {
			if (l && i - 1 >= l) {
				up[i] = dp[i - 1] + 1;
				inc(p[i].y, up[i]);
			}
			inc(p[i].y, dp[i]);
			dp[i] = max(dp[i], up[i]);
		}
		l = r;
	}	
	int cnt = get(N - 1);
	cerr << cnt << endl;
	ans -= 20 * cnt - 5 * cnt * PI;
	cout << ans << endl;
}

