        (t.y > bnode.y && t.y > enode.y)) continue;
    cir[++cnt] = t;
  }
  n = cnt, cnt = 0;
  sort(cir + 1, cir + n + 1, [=] (Node a, Node b) { 
      return (bnode.x < enode.x) ^ (a.x > b.x);
      });
  for (int i = 1; i <= n; ++i) num[++cnt] = cir[i].y;
  sort(num + 1, num + cnt + 1);
  cnt = unique(num + 1, num + cnt + 1) - num - 1;

  /*
  for (int i = 1; i <= n; ++i) printf("%d %d\n", cir[i].x, cir[i].y);
  puts("");
  */

  /*
  for (int i = 1; i <= cnt; ++i) printf("%d ", num[i]);
  puts("");
  */

  int res = 0;
  for (int i = 1; i <= n; ++i) {
    int k = upper_bound(num + 1, num + cnt + 1, cir[i].y) - num - 1, t = query(k) + 1;
    modify(k, t);
    res = max(res, t);
  }

  // printf("%d %d\n", res, n);

  var xdist = abs(enode.x - bnode.x), ydist = abs(enode.y - bnode.y);
  long double dist = 100 * (xdist + ydist);
  // printf("%.13Lf\n", dist);
  dist += (var) res * (5 * Pi - 20);
  dist += (res > xdist || res > ydist) * 5 * Pi;
  printf("%.13Lf\n", dist);
  return 0;
}

namespace TreeArray {
  void modify(int t, int v) {
    for (int i = t; i <= cnt; i += i & -i) 
      tree[i] = max(tree[i], v);
  }
  int query(int t) {
    int res = 0;
    for (int i = t; i; i -= i & -i) 
      res = max(res, tree[i]);
    return res;
  }
}

