using namespace std;

using LL = long long;

void solve() {
    int x1,y1, x2,y2;
    cin >> x1 >> y1 >> x2 >> y2;

    int n;
    cin >> n;

    if(x1 > x2) {
        swap(x1, x2);
        swap(y1, y2);
    }

    bool rev = y1 > y2;
    if(rev) {
        y1 *= -1;
        y2 *= -1;
    }

    vector<pair<int, int>> a(n);
    for(auto &it : a) {
        cin >> it.first >> it.second;
        if(rev) {
            it.second *= -1;
        }
    }

    sort(a.begin(), a.end());

    vector<int> cl;
    for(auto it : a)  {
        if (x1 <= it.first && it.first <= x2 &&
            y1 <= it.second && it.second <= y2) {
            cl.push_back(it.second);
        }
    }

    vector<int> dp(n + 1, 1000*1000*1000);
    dp[0] = -1000*1000*1000;
    for(int i = 0; i < cl.size(); ++i) {
        int pos = upper_bound(dp.begin(), dp.end(), cl[i]) - dp.begin();
        if(dp[pos - 1] < cl[i] && cl[i] < dp[pos])
            dp[pos] = cl[i];
    }

    int cnt = 0;
    for(int i = 0; i <= n; ++i) {
        if(dp[i] != 1000*1000*1000) {
            cnt = i;
        }
    }

    LL ans = 100*LL(abs(x2 - x1) + abs(y2 - y1)) - 20*cnt;

    if(cnt == abs(y2 - y1) + 1 || cnt == abs(x2 - x1) + 1) {
        cnt++;
    }

    cout << ans + 5.0*cnt*acos(-1) << endl;
}

int main() {
    cout.precision(30);
    solve();
}

