// T           : データ型
// UpdateFunc  : (以前の値, 適用する値) => 新しい値 結合性必要
// update_unit : UpdateFuncの単位元 (= 配列の初期値)
template<class T, class UpdateFunc, T update_unit>
class SegmentTree {
  public:
    int n; 
    vector<T> data;
    UpdateFunc uf;
    SegmentTree(int nn) : n(1) {
        while(n < nn) n *= 2;
        data.resize( 2 * n - 1, update_unit);
    }
    SegmentTree(vector<T> init) : n(1) {
        int nn= init.size();
        while(n < nn) n *= 2;
        data.resize( 2 * n - 1, update_unit);
        copy(begin(init), end(init), begin(data) + n - 1);
    }
    // get value of index(i)
    T query(int i) {
        assert(0 <= i and i < n);
        return query(i, 0, 0, n);
    }
    // apply f(_, v) to [a, b)
    void update(int a, int b, T v) {
        assert(0 <= a and a < b and b <= n);
        update(a, b, 0, 0, n, v);
    }
  private:
    // [a, b) 更新区間, i 今いるNode, [l, r) はNode[i]の担当区間
    void update(int a, int b, int i, int l, int r, T v) {
        if(out_of_range(a, b, l, r)) return;
        if(within_range(a, b, l, r)) data[i] = uf(data[i], v);
        else {
            // 遅延伝搬させる
            int m = (l + r) / 2;
            // 関係ない範囲は今までの値を流す
            if(l < a) { // l .. a .(r). b ..(r)
                update(l, a, left_child(i), l, m, data[i]);
                update(l, a, right_child(i), m, r, data[i]);
            }
            if(b < r) { // (l).. a .(l). b .. r
                update(b, r, left_child(i), l, m, data[i]);
                update(b, r, right_child(i), m, r, data[i]);
            }
            // 関係する範囲は今の値を合わせて流す
            update(a, b, left_child(i), l, m, uf(data[i], v));
            update(a, b, right_child(i), m, r, uf(data[i], v)); 
            data[i] = update_unit; // 子に全て流したから
        }
    }
    // index(a) の値を求める, 今node[i], 
    T query(int a, int i, int l, int r) {
        if(data.size() <= i) return update_unit;
        assert(l <= a and a < r);
        int m = (l + r) / 2;
        T v = a < m ? query(a, left_child(i), l, m) : query(a, right_child(i), m, r);
        return uf(v, data[i]); // 先に流しているのでvの方が古い値
    }
    static bool out_of_range(int a, int b, int l, int r) { return r <= a or b <= l; }
    static bool within_range(int a, int b, int l, int r) { return a <= l and r <= b; }
    static int left_child(int i) { return i * 2 + 1; }
    static int right_child(int i) { return i * 2 + 2; }
    static int parent(int i) { return (i - 1) / 2; }
};

template <class T> struct OverWrite {
    T operator() (const T& x, const T& y) const { return y; }
};
template <class T> struct Max {
    T operator() (const T& x, const T& y) const { return max(x, y); }
};

template<class T, T INIT>
using RangeMaxQuery = SegmentTree<T, Max<T>, INIT>;

struct P {
    int x;
    int y;
};
istream& operator >> (istream &is , P &p) { return is >> p.x >> p.y; }
ostream& operator << (ostream &os , const P &p) { return os << "(" << p.x << "," << p.y << ")"; }

map<int, int> compress(vector<int> &x) {
    map<int,int> zip;
    sort(x.begin(), x.end());
    x.erase(unique(x.begin(),x.end()),x.end());
    for(int i = 0; i < x.size(); i++){
        zip[x[i]] = i;
    }
    return zip;
}


class Solver {
  public:
    double solve2(int sx, int ex, P s, P e, vector<P> &S, int y_size) {
        RangeMaxQuery<ll, 0LL> query(y_size);
        for(int i = S.size() - 1; i >= 0; i--) {
            if(S[i].x >= e.x) continue;
            if(S[i].x <= s.x) break;
            if(s.y < S[i].y and S[i].y < e.y)
                query.update(0, S[i].y + 1, query.query(S[i].y) + 1);
        }
        ll num = query.query(s.y);
        return num;
    }

    bool solve() {
        P s, e; cin >> s >> e;
        if(s.x > e.x) swap(s, e);
        bool reverse_y = e.y < s.y;
        if(reverse_y) {
            s.y *= -1;
            e.y *= -1;
        }
        ll N; cin >> N;
        vector<int> xs, ys;
        xs.push_back(s.x);
        ys.push_back(s.y);
        xs.push_back(e.x);
        ys.push_back(e.y);
        vector<P> S(N);
        rep(i, N) {
            cin >> S[i];
            if(reverse_y) S[i].y *= -1;
            xs.push_back(S[i].x);
            ys.push_back(S[i].y);
        }
        double ans = e.x - s.x + e.y - s.y;
        ans *= 100;
        map<int, int> map_x = compress(xs);
        map<int, int> map_y = compress(ys);
        auto map = [&] (P &a) {
            a.x = map_x.at(a.x);
            a.y = map_y.at(a.y);
        };
        map(s); map(e);
        rep(i, S.size()) map(S[i]);



        vector<P> Sx = S;
        sort(all(Sx), [](P &a, P &b) { return a.x < b.x; });

        int num = solve2(s.x, e.x, s, e, Sx, map_y.size());

        ans -= num * 20.0;
        ans += 2 * M_PI * 10.0 / 4.0 * num;
        bool x_exist= false, y_exist = false;
        rep(i, N) {
            x_exist |= S[i].x == s.x;
            y_exist |= S[i].y == s.y;
        }
        if(s.x == e.x and x_exist) ans += 2 * M_PI * 10 / 2.0 - 20.0;
        if(s.y == e.y and y_exist) ans += 2 * M_PI * 10 / 2.0 - 20.0;

        printf("%.10lf\n", ans);

        return 0;
    }
};

int main() {
    Solver s;
    s.solve();
    return 0;
}

