}

int get(int l, int r) {
	int ret = 0;
	for(l += n, r += n; l <= r; l = (l + 1) >> 1, r = (r - 1) >> 1) {
		if(l & 1) ret = max(ret, t[l]);
		if(!(r & 1)) ret = max(ret, t[r]);
	}
	return ret;
}

