#define maxn 200005
int n,sz;
int tree[maxn*4];
point s,e;
point p[maxn];
map<double,int> mp;
map<double,double> ori;
void cpidx() {
    int i;
    map<double,int>::iterator it;
    mp[s.Y]; mp[e.Y];
    for(i=0;i<n;i++) mp[p[i].Y];
    for(it=mp.begin();it!=mp.end();++it) it->second = ++sz, ori[sz] = it->first;
    s.Y = mp[s.Y]; e.Y = mp[e.Y];
    for(i=0;i<n;i++) p[i].Y = mp[p[i].Y];
    if(s>e) swap(s,e);
    sort(&p[0],&p[n]);
}
void build(int pos,int l,int r) {
    if(l==r) {
        tree[pos] = -inf;
        return ;
    }
    int mid = (l+r)/2;
    build(pos<<1,l,mid); build(pos<<1|1,mid+1,r);
    tree[pos] = max(tree[pos<<1],tree[pos<<1|1]);
}
void update(int pos,int l,int r,int x,int val) {
    if(l>r || r<x || x<l) return ;
    if(l==r) {
        tree[pos] = max(tree[pos],val);
        return ;
    }
    int mid = (l+r)/2;
    update(pos<<1,l,mid,x,val); update(pos<<1|1,mid+1,r,x,val);
    tree[pos] = max(tree[pos<<1],tree[pos<<1|1]);
}
int query(int pos,int l,int r,int x,int y) {
    if(l>r || r<x || y<l) return -inf;
    if(x<=l && r<=y) return tree[pos];
    int mid = (l+r)/2;
    return max(query(pos<<1,l,mid,x,y), query(pos<<1|1,mid+1,r,x,y));
}
main() {
    int i,val;
    double temp,ans;
    scanf("%lf%lf%lf%lf",&s.X,&s.Y,&e.X,&e.Y);
    scanf("%d",&n);
    for(i=0;i<n;i++) scanf("%lf%lf",&p[i].X,&p[i].Y);
    cpidx();
    //Case Straight path
    if(s.X==e.X) {
        ans = (ori[e.Y]-ori[s.Y])*100;
        for(i=0;i<n;i++) if(p[i].X==s.X) if(s.Y < p[i].Y && p[i].Y < e.Y) ans += 10*PI - 20;
        printf("%.15lf",ans);
        return 0;
    }
    if(s.Y==e.Y) {
        ans = (e.X-s.X)*100;
        for(i=0;i<n;i++) if(p[i].Y==s.Y) if(s.X < p[i].X && p[i].X < e.X) ans += 10*PI - 20;
        printf("%.15lf",ans);
        return 0;
    }
    //Case s.X<e.X and s.Y<e.Y
    if(s.Y<=e.Y) {
        //Init
        build(1,1,sz);
        update(1,1,sz,s.Y,0);
        //for i choose the best j that j.Y <= i.Y
        ans = 0;
        for(i=0;i<n;i++) {
            if(p[i].X<s.X || p[i].X>e.X) continue;
            val = query(1,1,sz,1,p[i].Y);
            update(1,1,sz,p[i].Y,val+1);
            if(p[i].X==e.X || p[i].Y==e.Y) temp = val*(20-5*PI) + (20-10*PI);
            else temp = (val+1)*(20-5*PI);
            if(p[i].Y<=e.Y) ans = max(ans,temp);
//            printf("(%lf, %lf) : %d : %lf\n",p[i].X,p[i].Y,val,temp);
        }
        printf("%.15lf",100*(e.X-s.X+ori[e.Y]-ori[s.Y])-ans);
        return 0;
    }
    if(s.Y>=e.Y) {
        printf("%d",1/0);
        //Init
        build(1,1,sz);
        update(1,1,sz,s.Y,0);
        //for i choose the best j that j.Y >= i.Y
        ans = 0;
        for(i=0;i<n;i++) {
            if(p[i].X<s.X || p[i].X>e.X) continue;
            val = query(1,1,sz,p[i].Y,sz);
            update(1,1,sz,p[i].Y,val+1);
            if(p[i].X==e.X || p[i].Y==e.Y) temp = val*(20-5*PI) + (20-10*PI);
            else temp = (val+1)*(20-5*PI);
            if(p[i].Y>=e.Y) ans = max(ans,temp);
//            printf("(%lf, %lf) : %d : %lf\n",p[i].X,p[i].Y,val,temp);
        }
        printf("%.15lf",100*(e.X-s.X+ori[s.Y]-ori[e.Y])-ans);
        return 0;
    }
}

