#include <bits/stdc++.h>
using namespace std;
#define f(i, x, n) for (int i = x; i < (int)(n); ++i)
#define ll long long

int n;
vector<int> mpx, mpy;
double pi = acos(-1), sq = 5.0 * pi;

struct P{
	int x, y, idx, idy;
	P(){}
	P(int a, int b):x(a), y(b) {}
	int gtidx() { return lower_bound(mpx.begin(), mpx.end(), x) - mpx.begin(); }
	int gtidy() { return lower_bound(mpy.begin(), mpy.end(), y) - mpy.begin(); }
	void pl(){
		idx = gtidx();
		idy = gtidy();
	}
	void rd() { scanf("%d%d", &x, &y); }
	void psh(){
		mpx.push_back(x);
		mpy.push_back(y);
	}
	void fl(){
		y = -y;
	}
	bool operator <(P const o)const { return idx < o.idx; }
}p[200002];

double s[800010], z[800010];

inline void sl(int id){
	int a = id << 1, b = a | 1;
	s[a] = min(s[a], z[id]);
	s[b] = min(s[b], z[id]);
	z[a] = min(z[a], z[id]);
	z[b] = min(z[b], z[id]);
	z[id] = 1e10;
}

void bld(int l = 0, int r = n + 2, int id = 1){
	if (l + 1 == r) { s[id] = z[id] = 1e10; return; }
	int m = l + r >> 1, a = id << 1, b = a | 1;
	bld(l, m, a);
	bld(m, r, b);
}

void up(int x, int y, double v, int l = 0, int r = n + 2, int id = 1){
	if (l >= y || r <= x)return;
	if (l >= x && r <= y) { s[id] = min(s[id], v), z[id] = min(z[id], v); return; }
	sl(id);
	int m = l + r >> 1, a = id << 1, b = a | 1;
	up(x, y, v, l, m, a);
	up(x, y, v, m, r, b);
	s[id] = min(s[a], s[b]);
}

void upH(int i, double v, int l = 0, int r = n + 2, int id = 1){
	if (l + 1 == r) { s[id] = v; return; }
	int m = l + r >> 1, a = id << 1, b = a | 1;
	sl(id);
	if (i < m)upH(i, v, l, m, a);
	else upH(i, v, m, r, b);
	s[id] = min(s[a], s[b]);
}

double gt(int x, int y, int l = 0, int r = n + 2, int id = 1){
	if (l >= y || r <= x)return 1e10;
	if (l >= x && r <= y)return s[id];
	sl(id);
	int m = l + r >> 1, a = id << 1, b = a | 1;
	return min(gt(x, y, l, m, a), gt(x, y, m, r, b));
}

int main(){
	P st, ed;
	st.rd();
	ed.rd();
	scanf("%d", &n);
	f(i, 0, n)p[i].rd();

	bld();

	if (st.x > ed.x)swap(st, ed);
	if (st.y > ed.y){
		st.fl();
		ed.fl();
		f(i, 0, n)p[i].fl();
	}

	f(i, 0, n)p[i].psh();
	mpy.push_back(st.y);
	mpy.push_back(ed.y);
	sort(mpx.begin(), mpx.end());
	sort(mpy.begin(), mpy.end());

	f(i, 0, n)p[i].pl();
	st.pl();
	ed.pl();

	sort(p, p + n);

	double an = (ed.x - st.x + ed.y - st.y) * 100.0;

	int j = st.gtidx();
	if (j < n && p[j].idx == j && p[j].idy > st.idy){
		up(st.idy, p[j].idy, 0.0);
		upH(p[j].idy, -20.0 + sq);
		up(p[j].idy + 1, n + 2, -20.0 + sq * 2.0);
	}else up(st.idy, n + 2, 0.0);

	int lm = ed.gtidx();
	f(i, st.idx, lm){
		int lc = p[i].idy;
		if (lc > ed.idy || lc < st.idy)continue;
		double t = gt(st.idy, lc), tt = t - 20.0 + sq;
		up(lc + 1, n + 2, t - 20.0 + sq * 2.0);
		t = gt(lc, lc + 1);
		tt = min(tt, t - 20.0 + sq * 2.0);
		up(lc + 1, n + 2, t - 20.0 + sq);
		upH(lc, tt);
	}

	j = ed.gtidx();
	double z = 1e9;
	if (j < n && p[j].idx == j && p[j].idy < ed.idy){
		z = gt(p[j].idy, p[j].idy + 1) - 20.0 + sq;
		z = min(z, gt(p[j].idy + 1, ed.idy));
		z = min(z, gt(st.idy, p[j].idy) - 20.0 + sq * 2.0);
	}else z = gt(st.idy, ed.idy + 1);

	printf("%.12lf\n", an + z);
}

