	pt tmp = p1;
	p1 = pt(0, 0);
	V.pb(p2);

	for (pt &p : V) {
		p -= tmp;

		if (p.y < 0) {
			p.y *= -1;
		}
	}

	p2 = V.back();
	V.pop_back();
}

void solve() {
	pA.read();
	pB.read();                  	
	scanf("%d", &n);    

	for (int i = 1; i <= n; ++i) {
		pt p;
		p.read();         
		arr.pb(p);
	}

	initiate(arr, pA, pB);
	assert(pB.x * pB.y < (int)3e6);

	vector<vector<double>> dp[2];
	vector<vector<char>> F;

	F = vector<vector<char>>(pB.x + 1, vector<char>(pB.y + 1, 0));

	for (pt p : arr) {
		F[p.x][p.y] = 1;
	}

	for (int s = 0; s < 2; ++s) {
		dp[s] = vector<vector<double>>(pB.x + 1, vector<double>(pB.y + 1, 1e9));
	}	     

	dp[0][0][0] = dp[1][0][0] = 0.0;

	for (int s = 1; s <= pB.x + pB.y; ++s) {
		for (int x = 0; x <= pB.x; ++x) {
			int y = s - x;

			if (y < 0) {
				break;
			}

			if (y > pB.y) {
				continue;
			}

			if (F[x][y]) {
				if (x > 0) {
					dp[0][x][y] = min(dp[0][x - 1][y], dp[1][x - 1][y]) + 90.0;
				}

				if (y > 0) {
					dp[1][x][y] = min(dp[0][x][y - 1], dp[1][x][y - 1]) + 90.0;				
				}
			}			
			else {
				if (x > 0) {
					if (F[x - 1][y]) {
						dp[0][x][y] = min(dp[0][x][y], dp[0][x - 1][y] - 10.0 + DI * 2.0 + 100.0);
						dp[0][x][y] = min(dp[0][x][y], dp[1][x - 1][y] - 10.0 + DI + 100.0);
					}
					else {
						dp[0][x][y] = min(dp[0][x - 1][y], dp[1][x - 1][y]) + 100.0;
					}
				}

			 	if (y > 0) {
			 		if (F[x][y - 1]) {
			 			dp[1][x][y] = min(dp[1][x][y], dp[1][x][y - 1] - 10.0 + DI * 2.0 + 100.0);
			 			dp[1][x][y] = min(dp[1][x][y], dp[0][x][y - 1] - 10.0 + DI + 100.0);
			 		}
			 		else {
			 			dp[1][x][y] = min(dp[0][x][y - 1], dp[1][x][y - 1]) + 100.0;
			 		}
			 	}
			}
		}
	}

	printf("%.9f\n", min(dp[0][pB.x][pB.y], dp[1][pB.x][pB.y]));
}                         

