struct indexed_tree {
	vector<int> tree;
	int k = 1;
	indexed_tree(int n) {
		while (k < n)k *= 2;
		tree.resize(k * 2 + 10, 0);
	}
	void update(int idx, int a) {
		idx += k;
		while (idx) {
			tree[idx] = std::max(tree[idx], a);
			idx /= 2;
		}
	}
	int getRange(int left, int right) {
		left += k;
		right += k;
		int ret = 0;
		while (left <= right) {
			if (left % 2 == 1)ret = std::max(ret, tree[left]);
			if (right % 2 == 0)ret = std::max(ret, tree[right]);
			left = (left + 1) / 2;
			right = (right - 1) / 2;
		}
		return ret;
	}
};
