const int MAXN = 1e6 + 2;
const int INF = 1e9;
const double PI = 3.141592653589793;

int lc(vector<int>& a) {
    int n = a.size();
    if (n == 0) {
        return 0;
    }
    vector<int> d(n + 1);
    d[0] = -INF;
    for (int i=1; i<=n; ++i) {
        d[i] = INF;
    }

    for (int i=0; i<n; i++) {
        int j = upper_bound(d.begin(), d.end(), a[i]) - d.begin();
        if (d[j-1] < a[i] && a[i] < d[j]) {
            d[j] = a[i];
        }
    }
    for (int i = n; i >= 0; --i) {
        if (d[i] != INF) {
            return i;
        }
    }
    return 0;
}

double find_min(vector<pair<int, int>>& a, int x1, int y1, int x2, int y2) {
    int n = a.size();
    if (y2 < y1) {
        y1 *= -1;
        y2 *= -1;
        for (int i = 0; i < n; ++i) {
            a[i].second *= -1;
        }
    }
    std::vector<pair<int, int>> cur;
    for (int i = 0; i < n; ++i) {
        if (a[i].first <= x2 && a[i].first >= x1 && a[i].second <= y2 && a[i].second >= y1) {
            cur.push_back(a[i]);
        }
    }
    double ans = 0;
    vector<int> k(cur.size());
    sort(cur.begin(), cur.end());
    for (int i = 0; i < (int)cur.size(); ++i) {
        k[i] = cur[i].second;
    }
    int lcs = lc(k);
    if (lcs == x2 - x1 + 1 || lcs == y2 - y1 + 1) {
        ans += 10 * PI - 20.0;
        ans += (20.0 - 5 * PI);
    }
    return 100.0*((double)x2 - (double)x1 + (double)y2 - (double)y1) + ans - (double)lcs * (20.0 - 5 * PI);
}

int main(void) {
