		int xi = lower_bound(allof(xset), X[i]) - xset.begin();
		int add = seg.query(0, xi);
		seg.update(xi, add + 1);
	}

	nc = max(nc, seg.query(0, m));
	cout << base - 20. * nc + pr * nc << endl;
}

