double best(vector<pair<int, int>> vv) {
	vector<int> dp(vv.size(), 1);

	for (int i = 0; i < vv.size(); ++i) {
		for (int j = 0; j < i; ++j) {
			if (vv[j].se < vv[i].se) {
				dp[i] = max(dp[i], dp[j] + 1);
			}
		}
	}

	return *max_element(all(dp)) * (20.0 - 5.0 * PI);
}

double calc(vector<pair<int, int>> vv) {
	if (vv.empty()) {
		return 0.0;
	}	

	double ret = -1e9;

	for (int step = 0; step < 2; ++step) {
		sort(all(vv));
		int cnt = 1;

		for (int i = 1; i < vv.size(); ++i) {
			cnt += (vv[i].se <= vv[i - 1].se);
		}

		if (cnt == bx - ax + 1) {
			return (20.0 - 5.0 * PI) * (bx - ax) + (20.0 - 10.0 * PI);
		}

		ret = max(ret, best(vv));

		for (pair<int, int> &x : vv) {
			swap(x.fi, x.se);
		}

		swap(ax, ay);
		swap(bx, by);
	}

	return ret;
}

