int ntem, dat[2000000];

void init(int n_){
    ntem = 1;
    while (ntem < n_) ntem *= 2;
    for(int i = 0; i < 2 * ntem - 1; i ++) dat[i] = -1;

}

void update(int k, int a){ // k-th value change to a
    k += ntem - 1;
    dat[k] = a;
    while(k > 0){ // update upper node
        k = (k - 1) / 2;
        dat[k] = max(dat[k * 2 + 1], dat[k * 2 + 2]);
    }
}

int query(int a, int b, int k, int l, int r){ //find [a,b) smallest value,now node k,and range k = [l,r)
    if(r <= a || b <= l) return -1;
    if(a <= l && r <= b) return dat[k];
    else{
        int vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
        int vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
        return max(vl, vr);
    }
}

