			b[cnt++] = y;
		}
	}
	sort(a, a + cnt);
	sort(b, b + cnt);
	bit.init(cnt);
	for (int i = 0; i < cnt; i++)
	{
		int k = lower_bound(b, b + cnt, a[i].y) - b;
		bit.modify(k + 1, bit.query(k) + 1);
	}
	double ans = (x2 - x1 + y2 - y1) * 100 + bit.query(cnt) * (5 * PI - 20);
	if ((x1 == x2 || y1 == y2) && bit.query(cnt)) ans = (x2 - x1 + y2 - y1) * 100 + 10 * PI - 20;
	printf("%.15f\n", ans);
	return 0;
}

