int search(int k){
	int l = 1, r = cnt, mid;
	while (l < r){
		mid = (l + r) >> 1;
		if (k <= X[mid]) r = mid;
		else l = mid + 1;
	}
	return l;
}

bool cmp(int a, int b){
	return y[a] < y[b];
}

void update(int x, int y){
	for (; x<=cnt; x+=lowbit(x)) c[x] = max(c[x], y);
}

int query(int x){
	int res = 0;
	for (; x; x-=lowbit(x)) res = max(res, c[x]);
	return res;
}

int main(){
