		sy = 1e8 - sy; ty = 1e8 - ty;
	}
	else if (sx > tx && sy > ty){
		flag = 2; 
		sx = 1e8 - sx; sy = 1e8 - sy;
		tx = 1e8 - tx; ty = 1e8 - ty;
	}
	else if (sx > tx && sy <= ty){
		flag = 3; 
		sx = 1e8 - sx; tx = 1e8 - tx;
	}
	for (int i=1; i<=n; i++){ N++;
		scanf("%d%d", &x[N], &y[N]);
		if (flag == 1) y[N] = 1e8 - y[N];
		else if (flag == 2) { x[N] = 1e8 - x[N]; y[N] = 1e8 - y[N]; }
		else if (flag == 3) x[N] = 1e8 - x[N];
