			}
		}
		return ABS(y2 - y1) * 100.0;
	}

	if (y1 == y2) {
		for (int i = 0; i < n; i++) {
			if (V[i].second == y1 && IN(V[i].first, MIN(x1, x2), MAX(x1, x2))) {
				return ABS(x2 - x1) * 100.0 - 20 + PI * 10;
			}
		}
		return ABS(x2 - x1) * 100.0;
	}

	if (x1 > x2 && y1 > y2) {
		swap(x1, x2);
		swap(y1, y2);
	}

	if (x1 < x2 && y1 < y2);
	else {
