  int l = min(sx,tx);
  int r = max(sx,tx);
  int u = max(sy,ty);
  int d = min(sy,ty);

  auto in = [&](int p, int q){
    return l<=p && p<=r && d<=q && q<=u;
  };

  if( (l==sx && u==sy) || (l==tx && u==ty) ){
    rep(i,n) if( in(vec[i].fi, vec[i].se) ) vec[i].second = d + (u - vec[i].second);
  }
  sort(all(vec));

  vector<int> v;
  rep(i,n) if( in(vec[i].fi, vec[i].se) ) v.pb(vec[i].se);

  vector<int> dp(v.size()+1, INF);
  rep(i,v.size()){
    int idx = lower_bound(all(dp), v[i]) - dp.begin();
    dp[idx] = v[i];
  }

  int lis = lower_bound(all(dp), INF) - dp.begin();

  double ans = (r-l + u-d)*100.0 + (PI*5 - 20)*lis;

  if(lis == min(r-l+1, u-d+1)) ans += PI*5;

  printf("%.15f\n", ans);

  return 0;
}

