double ans;
void change(int x, int d) { for( ; x <= n; x += x&-x) t[x] = max(t[x], d); }
int ask(int x) { int ret = 0; for( ; x; x -= x&-x) ret = max(ret, t[x]); return ret; }
int main()
{
    x1 = read(), y1 = read(), x2 = read()-x1, y2 = read()-y1, m = read(), rx = ry = 1;
