        if (i >= 0) {
            d[j] = d[i] + 1;
        }
        else {
            d[j] = 1;
        }
        mx = max(mx, d[j]);
    }
    s -= mx * 5.0 * (4.0 - Pi);
    s += c * 10.0 * (Pi - 2.0);
    printf("%.13f", s);
}

