struct SegmentTree{
	int treeN;
	vector<int> tree;
	SegmentTree(int N){
		treeN = N;
		tree.resize(2*treeN, 0);
	}
	SegmentTree(vector<int>& nums){
		treeN = nums.size();
		tree.resize(2*treeN, 0);
		for (int i=0;i<treeN;i++){
			tree[treeN+i] = nums[i];
		}
		for (int i=treeN-1;i>0;i--){
			tree[i] = max(tree[i<<1], tree[i<<1|1]);
		}
	}
	int query(int l, int r){
		int res = 0;
		for (l+=treeN,r+=treeN;l<r;l>>=1,r>>=1){
			if (l&1) res = max(res, tree[l++]);
			if (r&1) res = max(res, tree[--r]);
		}
		return res;
	}
	void modifyadd(int p,int val){
		p += treeN;
		tree[p] = max(tree[p], val);
		for (;p>0;p>>=1){
			p >>= 1;
			tree[p] = max(tree[p], val);
		}
	}
};

