	for (i = n; i > 0; i--) {
		if (dp[i] < INF) break;
	}

	//LISの長さ
	int Count = i;

	//場合分け
	double ans;

	if (min(gx - sx, gy - sy) + 1 > Count) {
		ans = (gy - sy + gx - sx) * 100 - (double)Count * (20.0 - PAI * 5.0);
	}
	else {
		ans = (gy - sy + gx - sx) * 100 - (Count - 1.0) * (20 - PAI * 5) + (PAI * 10 - 20);
	}

	printf("%.20Lf\n", ans);
	return 0;
}

