#include <bits/stdc++.h>

using namespace std;

const double pi = acos(-1.0);

const double fo = 20.0 - pi * 5.0;

struct pt {
    int x, y;
    pt(int x = 0, int y = 0) : x(x), y(y) {}
    bool operator<(const pt& p) const {
        if (x == p.x)
            return y < p.y;
        return x < p.x;
    }
};

const int MAXC = 1e8 - 1;
unordered_map<int, int> t;

void upd(int v, int tl, int tr, int pos, int val) {
    if (tl == tr)
        t[v] = val;
    else {
        int tm = (tl + tr) / 2;
        if (pos <= tm)
            upd(v * 2, tl, tm, pos, val);
        else
            upd(v * 2 + 1, tm + 1, tr, pos, val);
        t[v] = max(t[v * 2], t[v * 2 + 1]);
    }
}

int get(int v, int tl, int tr, int l, int r) {
    if (l > r)
        return 0;
    if (l == tl && r == tr)
        return t[v];
    int tm = (tl + tr) / 2;
    return max(get(v * 2, tl, tm, l, min(r, tm)),
               get(v * 2 + 1, tm + 1, tr, max(l, tm + 1), r));
}

int main() {
#ifdef __APPLE__
    freopen("input.txt", "r", stdin);
    freopen("output.txt", "w", stdout);
#endif

    int x1, y1, x2, y2;
    scanf("%d %d %d %d", &x1, &y1, &x2, &y2);
    if (x1 > x2) {
        swap(x1, x2);
        swap(y1, y2);
    }
    bool flip = false;
    if (y1 > y2) {
        flip = true;
        y1 = MAXC - y1;
        y2 = MAXC - y2;
    }
    int left = x1, right = x2, bot = y1, top = y2;
    int n;
    scanf("%d", &n);
    vector<pt> a;
    for (int i = 0; i < n; ++i) {
        int x, y;
        scanf("%d %d", &x, &y);
        if (flip) 
            y = MAXC - y;
        if (left <= x && x <= right &&
            bot <= y && y <= top)
            a.push_back(pt(x, y));
    }
    n = a.size();
    sort(a.begin(), a.end());
    unordered_map<int, int> dp;
    for (int i = 0; i < n; ++i) {
        int cnt = get(1, 0, MAXC, 0, max(0, a[i].y - 1));
        dp[a[i].y] = max(dp[a[i].y], cnt + 1);
        upd(1, 0, MAXC, a[i].y, dp[a[i].y]);
    }
    double ans = (x2 - x1) + abs(y2 - y1);
    int cc = get(1, 0, MAXC, 0, MAXC);
    if (x1 == x2 || y1 == y2)
        ans = ans * 100.0 + (pi * 10.0 - 20.0) * cc;
    else
        ans = ans * 100.0 - fo * cc;
    printf("%.12lf", ans);
    return 0;
}

