using lint = long long;

using pii = pair<lint, lint>;
long double PI = acos(-1);
struct indexed_tree {
	vector<lint> tree;
	int k = 1;
	indexed_tree(int n) {
		while (k < n)k *= 2;
		tree.resize(k * 2 + 10, 0);
	}
	void update(int idx, lint a) {
		idx += k;
		while (idx) {
			tree[idx] = std::max(tree[idx], a);
			idx /= 2;
		}
	}
	lint getRange(int left, int right) {
		left += k;
		right += k;
		lint ret = 0;
		while (left <= right) {
			if (left % 2 == 1)ret = std::max(ret, tree[left]);
			if (right % 2 == 0)ret = std::max(ret, tree[right]);
			left = (left + 1) / 2;
			right = (right - 1) / 2;
		}
		return ret;
	}
};
lint abss(int a) {
	if (a < 0)return -a;
	return a;
}
int main() {
	std::vector<lint> X, Y;
	lint x1, y1, x2, y2;
	scanf("%lld%lld%lld%lld", &x1, &y1, &x2, &y2);
	X.push_back(x1);
	X.push_back(x2);
	Y.push_back(y1);
	Y.push_back(y2);
	int n;
	scanf("%d", &n);
	vector<pii> F;
	if (x1 > x2) {
		std::swap(x1, x2);
		std::swap(y1, y2);
	}
	F.push_back({ x1,y1 });
	for (int i = 0; i < n; i++) {
		lint x, y;
		scanf("%lld%lld", &x, &y);
		if (std::min(x1, x2) <= x && x <= std::max(x1, x2) &&
			std::min(y1, y2) <= y && y <= std::max(y1, y2)) {
			F.push_back({ x,y });
			Y.push_back(y);
		}
	}
	std::sort(F.begin() + 1, F.end());
	F.push_back({ x2,y2 });
	std::sort(Y.begin(), Y.end());
	Y.erase(std::unique(Y.begin(), Y.end()), Y.end());
	if (x1 == x2 || y1 == y2) {
		long double ans = (abss(x1 - x2) + abss(y1 - y2))*100.0;
		ans -= (20.0 - (10.0*PI))*(F.size() - 2);
		printf("%.15Lf", ans);
	}
	else {
		indexed_tree tree(Y.size());
		for (int i = 0; i < F.size(); i++) {
			int y = std::lower_bound(Y.begin(), Y.end(), F[i].second) - Y.begin();
			if (y1 < y2) {
				lint p = tree.getRange(0, y);
				tree.update(y, p + 1);
			}
			else {
				lint p = tree.getRange(y, Y.size()-1);
				tree.update(y, p + 1);
			}
		}

		lint p = 0;
		if (y1 < y2) {
			p = tree.getRange(Y.size() - 1, Y.size() - 1) - 2;
		}
		else {
			p = tree.getRange(0, 0) - 2;
		}

		long double ans = (abss(x1 - x2) + abss(y1 - y2))*100.0;
		int len = std::min(abss(x1 - x2), abss(y1 - y2))+1;
		if (len == p) {
			p--;
			ans -= (20.0 - (10.0*PI));
		}
		ans -= (20.0 - (5.0*PI) )*p;
		printf("%.15Lf", ans);
	}

}

