const int N=201000;
const double pi=acos(-1.0);

namespace Worker
{
	int stk[N],tot;
	int solve(int *s,int n)
	{
		tot=0;
		for(int i=1;i<=n;i++)
		{
			if(s[i]>=stk[tot])stk[++tot]=s[i];
			else (*std::upper_bound(stk+1,stk+tot+1,s[i]))=s[i];
		}

		return tot;
	}
}

namespace ShuiTi
{
	typedef std::pair<int,int> pii;

	pii s[N];
	int t[N];
	int x0,x1,y0,y1,n;

	void initialize()
	{
		scanf("%d%d%d%d",&x0,&y0,&x1,&y1);
		if(x0>x1)std::swap(x0,x1),std::swap(y0,y1);

		scanf("%d",&n);
		int tmp=0,miny=std::min(y0,y1),maxy=std::max(y0,y1);
		for(int i=1;i<=n;i++)
		{
			scanf("%d%d",&s[i].x,&s[i].y);
			if(s[i].x<x0 || s[i].x>x1 || s[i].y<miny || s[i].y>maxy)continue;
			s[++tmp]=s[i];
		}
		n=tmp;
		std::sort(s+1,s+n+1);
		for(int i=1;i<=n;i++)
			t[i]=s[i].y;
	}

	void solve()
	{
		initialize();
		if(y0>y1)for(int i=1;i<=n;i++)t[i]*=-1;

		int m=Worker::solve(t,n);

//		printf(":%d\n",x);

		int dx=std::abs(x0-x1)+1,dy=std::abs(y0-y1)+1;

		double delta=pi*5-20,ans=(dx+dy-2)*100.0;
		ans+=delta*m;

		if(m==dx || m==dy)ans+=pi*5;

		printf("%.20lf\n",ans);
	}
}

int main()
{
	ShuiTi::solve();
	return 0;
}

