LL h[maxn],Hash[maxn];
LL c[maxn];
long double Ans;
#define lowbit(x) ((x & (-x)))
void update(LL x,LL val){
	for (;x<=Hash[0];x+=lowbit(x)){
		c[x] = max(c[x],val);
	}
}
LL get(LL x){
	LL ans = -0x3fffffff;
	for (;x>0;x-=lowbit(x)){
		ans = max(ans,c[x]);
	}
	return ans;
}
LL find(LL x){
	LL L = 1,R = Hash[0];
	while (L <= R){
		LL mid = (L + R) >> 1;
		if (Hash[mid] > x){
			R = mid-1;
		} else
		if (Hash[mid] < x){
			L = mid+1;
		} else
			return mid;
	}
	return -1;
}
