void initiate(vector<pt> &V, pt &p1, pt &p2) {
	if (p1.x > p2.x) {
		swap(p1, p2);
	}

	{
		vector<pt> tmp;

		for (pt p : V) {
			if (p1.x <= p.x && p.x <= p2.x && min(p1.y, p2.y) <= p.y && p.y <= max(p1.y, p2.y)) {
				tmp.pb(p);
			}
		}

		V = tmp;
	}

	pt tmp = p1;
	p1 = pt(0, 0);
	V.pb(p2);

	for (pt &p : V) {
		p -= tmp;

		if (p.y < 0) {
			p.y *= -1;
		}
	}

	p2 = V.back();
	V.pop_back();
}

