{
	for(int i=1;i<=n;i++)
		a[i]=e[i].y;
	st[0]=-1;
	for(int i=1;i<=n;i++)
	{
		if(a[i]>st[r]) st[++r]=a[i];
		else
		{
			int p=upper_bound(st,st+r+1,a[i])-st;
			st[p]=a[i];
		}
	}
}
