void update(int o,int L,int R,int pos,double val){
    //cout << o <<" "<<L<<" "<<R<<endl;
    if(L == R){
        tr[o] = min(tr[o],val);
        return;
    }
    if(pos <= mid){
        update(ls,L,mid,pos,val);
    }else{
        update(rs,mid + 1,R,pos,val);
    }
    tr[o] = min(tr[ls],tr[rs]);
}
double Q(int o,int L,int R,int l,int r){
    if(l > r) return 1e18;
    if(l <= L && R<= r)return tr[o];
    double res = 1e18;
    if(l <= mid){
        res = min(res,Q(ls,L,mid,l,r));
    }
    if(r > mid){
        res = min(res,Q(rs,mid +1,R,l,r));
    }
    return res;
}
