        swap(x1, x2);
        swap(y1, y2);
    }
    vector<PII> pts, pty;
    unordered_map<int, int> M;
    for(int i = 0; i < N; i++) {
        scanf("%d %d", &x, &y);
        if (x < min(x1, x2) || x > max(x1, x2) || y < min(y1,y2) || y > max(y1,y2)) continue;
        pts.push_back(PII(x,y));
        pty.push_back(PII(y,x));
    }
    sort(pts.begin(), pts.end());
    if (y2 >= y1) {
        sort(pty.begin(), pty.end());
    } else {
        sort(pty.begin(), pty.end(), greater<PII>());
    }
    int L = pts.size();
    for(int i = 0; i < L; i++) M.insert(PII(pty[i].first, i+1));
    SegmentTree st;
    for(int i = 0; i < L; i++) {
        // cerr << M[pts[i].second] << "," << st.query(0, M[pts[i].second]) << endl;
        st.update(M[pts[i].second], st.query(0, M[pts[i].second])+1);
    }
    long double res = 100.0 * (max(y1,y2) - min(y1,y2) + max(x1,x2) - min(x1,x2));
    int qqq = st.query(0, NN);
    res = res + (5 * M_PI - 20) * qqq;
    if ((qqq-1) == min((max(y1,y2) - min(y1,y2)), max(x1,x2) - min(x1,x2))) res = res + 5 * M_PI;
    cout << fixed << setprecision(16) << res << endl;
