inline void ins(int i, int x, int y, int L, int R){
	t[i].mx=max(t[i].mx, y); if(L==R)return;
	int mid=(L+R)>>1;
	if(x<=mid){
		if(!t[i].l){l++; t[l].l=t[l].r=t[l].mx=0; t[i].l=l;}
		ins(t[i].l, x, y, L, mid);
	}else{
		if(!t[i].r){l++; t[l].l=t[l].r=t[l].mx=0; t[i].r=l;}
		ins(t[i].r, x, y, mid+1, R);
	}
	t[i].mx=max(t[t[i].l].mx, t[t[i].r].mx);
}
inline int cmx(int i, int a, int b, int L, int R){
	if(!i)return 0;
	if(a<=L&&R<=b)return t[i].mx;
	int mid=(L+R)>>1, mx=0;
	if(a<=mid)mx=max(mx, cmx(t[i].l, a, b, L, mid));
	if(mid<b)mx=max(mx, cmx(t[i].r, a, b, mid+1, R));
	return mx;
}

