		f.first = -f.first;
		for (int i = 0; i < n; ++i)
			pts[i].first = -pts[i].first;
	}
	if (s.second > f.second)
	{
		s.second = -s.second;
		f.second = -f.second;
		for (int i = 0; i < n; ++i)
			pts[i].second = -pts[i].second;
	}
	double manh = (f.first - s.first + f.second - s.second) * 100;
	auto w = f.first - s.first;
