	s = trans(s);
	f = trans(f);
	for (int i = 0; i < n; ++i)
		pts[i] = trans(pts[i]);
	sort(pts, pts + n);
	int mx = 0;
	for (int i = 0; i < n; ++i)
	{
		auto p = pts[i];
		if (p.first < s.first || p.first > f.first || p.second < s.second || p.second > f.second)
			continue;
