long long LIS(vector<long long> nums){
	long long dp[200005];
	fill(dp, dp + nums.size(), INT_MAX);
	for (int i=0; i<nums.size(); ++i) {
		*lower_bound(dp, dp+nums.size(), nums[i]) = nums[i];
	}
	return lower_bound(dp, dp + nums.size(), INT_MAX) - dp;
}


