#define ls node*2
#define rs node*2+1
#define M 400010
using namespace std;
const double Pi=3.141592653589793238;
int n,x1,x2,y1,y2,len;bool flag;
int b[M],f[M],val[M<<2];
struct point{int x,y;}a[M];
bool cmp1(point a1,point a2) {return a1.x<a2.x;}
bool cmp2(point a1,point a2) {return a1.y<a2.y;}
int get(int x) {int l=1,r=n;while(l<=r){int mid=(l+r)/2;if(b[mid]==x) return mid;else if(b[mid]<x) l=mid+1;else r=mid-1;}}
void update(int node) {val[node]=max(val[ls],val[rs]);}
void insert(int node,int l,int r,int x,int k)
{
	if(l==r) {val[node]=k;return;}
	int mid=(l+r)/2;
	if(x<=mid) insert(ls,l,mid,x,k);
	else insert(rs,mid+1,r,x,k);
	update(node);
}
int query(int node,int l,int r,int l1,int r1)
{
	if(l1<=l&&r1>=r) return val[node];
	if(l1>r||r1<l) return 0;
	int mid=(l+r)/2;
	return max(query(ls,l,mid,l1,r1),query(rs,mid+1,r,l1,r1));
}
int main()
{
	scanf("%d%d%d%d",&x1,&y1,&x2,&y2);
	if(x1>x2) swap(x1,x2),swap(y1,y2);
	flag=y1<=y2;
	scanf("%d",&n);
	for(int i=1;i<=n;i++) scanf("%d%d",&a[i].x,&a[i].y);
	sort(a+1,a+1+n,cmp2);
	for(int i=1;i<=n;i++) b[i]=a[i].y;
	sort(a+1,a+1+n,cmp1);
	for(int i=1;i<=n;i++)
	{
		if(a[i].x>x2||a[i].x<x1) continue;
		if(flag&&a[i].y>=y1&&a[i].y<=y2)
		{
			int r=get(a[i].y);
			f[r]=query(1,1,n,1,r)+1;
			insert(1,1,n,r,f[r]);
		}
		else if(!flag&&a[i].y<=y1&&a[i].y>=y2)
		{
			int r=get(a[i].y);
			f[r]=query(1,1,n,r,n)+1;
			insert(1,1,n,r,f[r]);
		}
	}
	for(int i=1;i<=n;i++)
	{
		if(a[i].x>x2||a[i].x<x1) continue;
		if(flag&&a[i].y>=y1&&a[i].y<=y2) len=max(len,f[get(a[i].y)]);
		else if(!flag&&a[i].y<=y1&&a[i].y>=y2) len=max(len,f[get(a[i].y)]);
	}
	int num=min(abs(x1-x2),abs(y1-y2))+1;double res;
	if(num==len) res=100.0*(abs(x1-x2)+abs(y1-y2))-20.0*len+(len-1)*5*Pi+10*Pi;
	else res=100.0*(abs(x1-x2)+abs(y1-y2))-20.0*len+len*5*Pi;
	printf("%.15lf",res);
	return 0;
}

