		if(p.size())
			ans += 2.0 * del - 20.0; 

		cout << fixed << setprecision(22) << ans << endl;
		return 0;
	}

	n = p.size();
	for(ll i = 0; i < n; i++)
		temp.pb(p[i].se);

	sort(temp.begin(), temp.end());

	ll cnt = 0;

	for(ll i = 0; i < n; i++)
		p[i].se = lower_bound(temp.begin(), temp.end(), p[i].se) - temp.begin() + 1;

	for(ll i = 0; i < n; i++){
		cnt = max(cnt, get(p[i].se) + 1);
		add(p[i].se, 1);
	}
	ans = pot - cnt * (20.0 - del);
	cout << fixed << setprecision(44) << ans << endl;
	return 0;
}

