int lis(const vector<int> &arr){
	vector<int> t;
	for(int i=0;i<arr.size();++i){
		vector<int>::iterator it = lower_bound(t.begin(),t.end(),arr[i]);
		if(it==t.end())
			t.emplace_back(arr[i]);
		else
			*it = arr[i];
	}
	return t.size();
}
