int find(int x) {
	int l = 1, r = d[0] ;
	for ( ; l <= r; ) {
		int mid = (l + r) / 2 ;
		if (d[mid] == x) return mid ;
		if (x < d[mid]) r = mid - 1 ; 
			else l = mid + 1 ;
	}
	return 0 ;
}

void pre() {
	d[0] = 0 ;
