        return y < rhs.y;
    }

    bool operator>(const PT &rhs) const {
        return rhs < *this;
    }

    bool operator<=(const PT &rhs) const {
        return !(rhs < *this);
    }

    bool operator>=(const PT &rhs) const {
        return !(*this < rhs);
    }

    bool operator==(const PT &rhs) const {
        return x == rhs.x &&
               y == rhs.y;
    }

    bool operator!=(const PT &rhs) const {
        return !(rhs == *this);
    }

    friend ostream &operator<<(ostream &os, const PT &pt) {
        os << "x: " << pt.x << " y: " << pt.y;
        return os;
    }

    friend istream &operator>>(istream &is, PT &pt) {
        is >> pt.x >> pt.y;
        return is;
    }
};

