typedef pair<int,int> pii;

#define pb push_back
typedef vector<int> vi;

typedef long long ll;
typedef long double ld;

const int N = 2e5 + 7;
const double PI = acos(-1.0);
pii S, T;
void rev(int &a) { a = 100000000 - a; }
pii operator -(const pii &a, const pii &b) { return {a.fi - b.fi, a.se - b.se}; }
///----------------------------------------------
pii p[N]; int n;
int ans[N], met[N], pre[N];
int main() {

	///read
	scanf("%d%d%d%d", &S.fi, &S.se, &T.fi, &T.se);
	if (S.fi > T.fi) swap(S, T);
	cin >> n;
	rep(i, 0, n) scanf("%d%d", &p[i].fi, &p[i].se);

	///prework
	sort(p, p + n);
	if (S.se > T.se) {
		rev(S.se); rev(T.se);
		rep(i, 0, n) rev(p[i].se);
	}
	T = T - S;
	rep(i, 0, n) p[i] = p[i] - S;
	S = S - S;
	//rep(i, 0, n) de(p[i].fi), de(p[i].se);

	///work
	vector<pii> np;
	rep(i, 0, n) {
		if (p[i].fi < 0 || p[i].fi > T.fi) continue;
		if (p[i].se < 0 || p[i].se > T.se) continue;
		np.pb(p[i]);
	}
	n = sz(np);
	memset(ans, 0x3f, sizeof(ans)); ans[0] = -1; met[0] = -1;
	rep(i, 0, n) {
		int pos = lower_bound(ans, ans + n, p[i].se) - ans;
		pre[i] = met[pos - 1];
		met[pos] = i;
		ans[pos] = p[i].se;
	}
	int ret = 0; while(ans[ret + 1] < 0x3f3f3f3f) ret++;
	double result = (T.fi + T.se) * 100.0 + ret * (0.5 * PI * 10.0 - 2.0 * 10.0);
	//de(ret);
	if (!ret) {
		printf("%.15f", result);
		return 0;
	}

	///check
	vi pat; for (int u = met[ret]; ~u; u = pre[u]) pat.pb(u); reverse(all(pat));
	bool ok = false;
	int dir;
	if (np[pat[0]].fi > S.fi && np[pat[0]].se > S.se) ok = true;
	else if (np[pat[0]].fi ==  S.fi) dir = 2; else dir = 1;
	rep(i, 1, ret) {
		if (dir == 1) {// >
			if (np[pat[i]].se > np[pat[i - 1]].se + 1) { ok = true; break; }
		} else { // ^
			if (np[pat[i]].fi > np[pat[i - 1]].fi + 1) { ok = true; break; }
		}
	}
	if (!ok) {
		if (dir == 1 && np[pat[ret - 1]].se == T.se) { result += 0.5 * PI * 10.0;  }
		if (dir == 2 && np[pat[ret - 1]].fi == T.fi) { result += 0.5 * PI * 10.0;  }
	}

	///print
	printf("%.15f", result);


}

