using namespace std;
typedef long long int ll;
typedef pair <int,int> P;
typedef long double ld;

int dp[SIZE];
int n;

ld solve(vector <P> vx,int x1,int x2,int y1,int y2)
{
	vector <P> vec;
	for(int i=0;i<n;i++)
	{
		int x=vx[i].first,y=vx[i].second;
		if(min(x1,x2)<=x&&x<=max(x1,x2)&&min(y1,y2)<=y&&y<=max(y1,y2))
		{
			vec.push_back(P(x,y));
		}
	}
	ld ret=100.0*(ll) (abs(x1-x2)+abs(y1-y2));
	if(x1==x2||y1==y2)
	{
		if(!vec.empty())
		{
			ld add=10.0*PI-20.0;
			ret+=add;
		}
	}
	else
	{
		if(x1>x2)
		{
			swap(x1,x2);
			swap(y1,y2);
		}
		if(y1>y2)
		{
			for(int i=0;i<vec.size();i++) vec[i].second*=-1;
			y1*=-1,y2*=-1;
		}
		int sz=vec.size()+1;
		for(int i=0;i<sz;i++) dp[i]=INF;
		dp[0]=-INF;
		sort(vec.begin(),vec.end());
		ld mn=20.0-5.0*PI;
		ld add=10.0*PI-20.0;
		bool up=true;
		int lx=x1-1,ly=-INF;
		for(int i=0;i<vec.size();i++)
		{
			if(up&&vec[i].first==lx+1&&vec[i].second>ly)
			{
				lx++;
				ly=vec[i].second;
			}
			else
			{
				up=false;
				int y=vec[i].second;
				int pos=lower_bound(dp,dp+sz,y)-dp;
				dp[pos]=y;
			}
		}
		if(up&&lx==x2) ret+=add;
		else
		{
			int len=0;
			for(int i=0;i<sz;i++) if(dp[i]<INF) len=i;
			if(len==y2-y1+1) ret+=-(ld) (len-1)*mn+add;
			else ret+=-(ld) len*mn;
		}
	}
	return ret;
}
int main()
{
	int x1,x2,y1,y2;
	scanf("%d %d %d %d",&x1,&y1,&x2,&y2);
	scanf("%d",&n);
	vector <P> vx;
	for(int i=0;i<n;i++)
	{
		int x,y;
		scanf("%d %d",&x,&y);
		vx.push_back(P(x,y));
	}
	ld ret=solve(vx,x1,x2,y1,y2);
	for(int i=0;i<n;i++) swap(vx[i].first,vx[i].second);
	swap(x1,y1);
	swap(x2,y2);
	ret=min(ret,solve(vx,x1,x2,y1,y2));
	printf("%.12f\n",(double) ret);
	return 0;
}

