			&& ((sy <= tmp_y && tmp_y <= gy) || (sy >= tmp_y && tmp_y >= gy))) {
			pair<long long, long long> tmp;
			tmp.first = tmp_x;
			if ((sx - gx) * (sy - gy) >= 0 ) tmp.second = tmp_y;
			else tmp.second = -1 * tmp_y;
			inputs.push_back(tmp);
		}
	}
	sort(inputs.begin(), inputs.end());

	fill(dp, dp + inputs.size(), INF);
	for (long long i = 0; i < inputs.size(); ++i) {
		*lower_bound(dp, dp + inputs.size(), inputs[i].second) = inputs[i].second; // 最初に見つかるinputs[i]以上の要素をinputs[i]で置き換える
	}

	long long load_num = abs(sx - gx) + abs(sy - gy);
	long long spring_num = (lower_bound(dp, dp + inputs.size(), INF) - dp);

	if (sx == gx || sy == gy) {
		double dist = load_num * 100.0;
		dist += spring_num * (PI - 2) * 10.0;
		cout << setprecision(20) << dist << endl;
	}
	else if (spring_num == min(abs(sx - gx), abs(sy - gy)) + 1) {
		double dist = load_num * 100.0;
		dist += (spring_num - 1) * (PI / 2 - 2) * 10.0 + (PI - 2) * 10.0;
		cout << setprecision(20) << dist << endl;
	}
	else {
		double dist = load_num * 100.0;
		dist += spring_num * (PI / 2 - 2) * 10.0;
		cout << setprecision(20) << dist << endl;
	}

	return 0;
}

