struct RMQ{
  int n;
  vector<double> dat;
  const double def=1e15;
  RMQ(){}
  RMQ(int n_){init(n_);}
  void init(int n_){
    n=1;
    while(n<n_) n*=2;
    dat.clear();
    dat.resize(2*n-1,def);
  }
  void update(int k,double a){
    k+=n-1;
    dat[k]=a;
    while(k>0){
      k=(k-1)/2;
      dat[k]=min(dat[k*2+1],dat[k*2+2]);
    }
  }
  double query(int a,int b,int k,int l,int r){
    if(r<=a||b<=l) return def;
    if(a<=l&&r<=b) return dat[k];
    double vl=query(a,b,k*2+1,l,(l+r)/2);
    double vr=query(a,b,k*2+2,(l+r)/2,r);
    return min(vl,vr);
  }
  double query(int a,int b){
    return query(a,b,0,0,n);
  }
};

typedef pair<int,int> P;
signed main(){
  int x1,y1,x2,y2;
  cin>>x1>>y1>>x2>>y2;

  int n;
  cin>>n;
  P p[n];
  for(int i=0;i<n;i++) cin>>p[i].first>>p[i].second;
  if(x1>x2){
    swap(x1,x2);
    swap(y1,y2);
  }
  if(y1>y2){
    for(int i=0;i<n;i++) p[i].second*=-1;
    y1*=-1;
    y2*=-1;
  }
  sort(p,p+n);
  vector<int> cx,cy;
  cx.push_back(x1);
  cy.push_back(y1);
  cx.push_back(x2);
  cy.push_back(y2);

  for(int i=0;i<n;i++){
    cx.push_back(p[i].first);
    cy.push_back(p[i].second);
  }
  sort(cx.begin(),cx.end());
  cx.erase(unique(cx.begin(),cx.end()),cx.end());
  sort(cy.begin(),cy.end());
  cy.erase(unique(cy.begin(),cy.end()),cy.end());
  map<int,int> mx,my;
  for(int i=0;i<(int)cx.size();i++) mx[cx[i]]=i;
  for(int i=0;i<(int)cy.size();i++) my[cy[i]]=i;
  map<int,int> px,py;
  for(int i=0;i<n;i++){
    px[p[i].second]=p[i].first;
    py[p[i].first]=p[i].second;
  }
  RMQ rmq(cy.size()+100);
  double base=(abs(x1-x2)+abs(y1-y2))*100;
  double diff=5*PI-20,diff2=10*PI-20;
  double ans=1e15;
  if(px.count(y1)&&px[y1]==x2) ans=min(ans,base-diff);

  for(int i=my[y1];i<=my[y2];i++){
    if(!py.count(x1)||cy[i]<py[x1]){
      rmq.update(i,0);
    }
  } 

  for(int i=mx[x1];i<mx[x2];i++){
    int x=cx[i];
    if(!py.count(x)) continue;
    int y=py[x];
    double t=rmq.query(0,my[y]+1);
    //cout<<i<<" "<<cx[i]<<":"<<t<<endl;

    if(x!=x1) rmq.update(my[y]+1,t+diff);

    t=rmq.query(0,my[y]);
    rmq.update(my[y],t+diff);

    if(y==y1) rmq.update(my[y1],diff2);
  }

  for(int i=my[y1];i<=my[y2];i++){
    //cout<<cy[i]<<":"<<rmq.query(i,i+1)<<endl;
    if(py.count(x2)&&cy[i]<py[x2])
      ans=min(ans,base+rmq.query(i,i+1)+diff2);
    else if(py.count(x2)&&cy[i]==py[x2])
      ans=min(ans,base+rmq.query(i,i+1)+diff);
    else
      ans=min(ans,base+rmq.query(i,i+1));
  }
  /*//
  for(int i=0;i<(int)cy.size();i++)
    cout<<cy[i]<<":"<<rmq.query(i,i+1)<<endl;
  //*/
  printf("%.15Lf\n",ans);
  return 0;
}

