using namespace std;
int n;

struct point{
    int x, y;
    point(int x, int y) : x(x), y(y){}
    point(){}
    bool operator < (const point b) const{
        return (x == b.x) ? y < b.y : x < b.x;
    }
}save[maxn], st, ed;
int sx[maxn], sy[maxn];

int c[maxn];
void update(int p, int v){
    while (p <= n + 2){
        c[p] = max(c[p], v);
        p += lowbit(p);
    }
}
int get(int p){
    int ans = 0;
    while (p){
        ans = max(ans, c[p]);
        p -= lowbit(p);
    }
    return ans;
}

int main(){
    int x, y, z, w;
    scanf("%d%d%d%d", &x, &y, &z, &w);
    st = point(x, y);
    ed = point(z, w);
    scanf("%d", &n);
    rep(i, 1, n) scanf("%d%d", &save[i].x, &save[i].y);

    /*--------------------------*/
    sx[1] = x, sx[2] = z;
    rep(i, 1, n) sx[i + 2] = save[i].x;
    sy[1] = y, sy[2] = w;
    rep(i, 1, n) sy[i + 2] = save[i].y;
    sort(sx + 1, sx + 3 + n);
    int nx = unique(sx + 1, sx + 3 + n) - 1 - sx;
    sort(sy + 1, sy + 3 + n);
    int ny = unique(sy + 1, sy + 3 + n) - 1 - sy;
    st = point(lower_bound(sx + 1, sx + 3 + nx, st.x) - sx, 
    lower_bound(sy + 1, sy + 3 + ny, st.y) - sy);
    ed = point(lower_bound(sx + 1, sx + 3 + nx, ed.x) - sx, 
    lower_bound(sy + 1, sy + 3 + ny, ed.y) - sy);
    rep(i, 1, n) save[i] = point(lower_bound(sx + 1, sx + 3 + nx, save[i].x) - sx, 
    lower_bound(sy + 1, sy + 3 + ny, save[i].y) - sy);
    sort(save + 1, save + 1 + n);
    /*--------------------------*/

    if (st.x > ed.x) swap(st, ed);
    int now = lower_bound(save + 1, save + 1 + n, point(st.x, -1)) - save;
    int end = lower_bound(save + 1, save + 1 + n, point(ed.x + 1, -1)) - 1 - save;
    int lb = min(st.y, ed.y);
    int ub = max(st.y, ed.y);
    rep(i, now, end){
        if (save[i].y < lb || save[i].y > ub) continue;
        int mx = get(save[i].y);
        update(save[i].y, mx + 1);
    }
    int num = get(ed.y);
    if (st.y != ed.y) {
        long double dist = (long double) 100.0 * (abs(x - z) + abs(y - w));
        dist += num * (pi * 5.0 - 20.0);
        printf("%.15Lf", dist);
    }
    else {
        long double dist = (long double) 100.0 * (abs(x - z) + abs(y - w));
        dist += num * (pi * 10.0 - 20.0);
        printf("%.15Lf", dist);
    }
    return 0;
}

