namespace seg{
	int t[N*4];
	int insert(int i,int l,int r,int x,int a){
		if(l==r)return t[i]=max(t[i],a);
		int mid=(l+r)/2;
		if(x<=mid)insert(i*2,l,mid,x,a);
		else insert(i*2+1,mid+1,r,x,a);
		t[i]=max(t[i*2],t[i*2+1]);
	}
	int query(int i,int l,int r,int x,int y){
		if(y<x)return 0;
		if(x<=l&&y>=r)return t[i];
		int ans=0,mid=(l+r)/2;
		if(x<=mid)ans=max(ans,query(i*2,l,mid,x,y));
		if(y>mid)ans=max(ans,query(i*2+1,mid+1,r,x,y));
		return ans;
	}
}
