pair<int, int> s[MAXN];
int f[MAXN], k = 0;

double calc_ans(int line, int qua, int hal)
{
	return 100.0 * line + (5.0 * M_PI - 20.0) * qua + (10.0 * M_PI - 20.0) * hal;
}

void solve()
{
	sort(s + 1, s + n + 1);
	for(int i = 1; i <= n; i++)
	{
		int v = s[i].second;
		if(!k || f[k] < v)
			f[++k] = v;
		else
		{
			int p = lower_bound(f + 1, f + k + 1, v) - f;
			f[p] = v;
		}
	}
	bool half = (k == min(tx - sx, ty - sy) + 1);
	double ans = calc_ans(tx - sx + ty - sy, k - half, half);
	cout << fixed << setprecision(15) << ans << endl;
}

