    nums.pb(vec[i].se-1);
    nums.pb(vec[i].se);
    nums.pb(vec[i].se+1);
  }
  uniq(nums);
  int m = nums.size();

  if(m==0){
    printf("%.15f\n", (r-l + u-d)*100.0);
    return 0;
  }

  sort(all(vec));
  SegTree<double> st(m+1);
  st.update(0, 0);

  rep(i,n) if( in(vec[i].fi, vec[i].se) ){
    int id = lower_bound(all(nums), vec[i].se) - nums.begin();
    if(vec[i].fi == r){
      double ans = min(st.query(0, id) + (PI*10 - 20), st[id] + (PI*5 - 20));
