      ans += (r-l + u-d)*100;
      printf("%.15f\n", ans);
      return 0;
    }
    if(vec[i].fi == l){
      st.update(id, (PI*5 - 20));
      st.update(id+1, (PI*10 - 20));
      continue;
    }

    if(i>0 && vec[i-1].fi+1 == vec[i].fi && vec[i-1].se+1 == vec[i].se){
      double prev = st[id-1];
      double crnt = st[id];

      st.update(id, min(crnt + (PI*10 - 20), prev + (PI*5 - 20)));
      st.update(id+1, min(crnt + (PI*5 - 20), prev + (PI*10 - 20)));
    }
    else {
      double val = st.query(0, id+1) + (PI*5 - 20);
      st.update(id, val);
      if(vec[i].se<u) st.update(id+1, val);
    }
  }

  double ans = (r-l + u-d)*100 + st.query(0,m);
  printf("%.15f\n", ans);

  return 0;
}

