using namespace std;

#define INF 1e+9
#define MAX_N 200000

int dp[MAX_N];


struct Point {
  int x,y;
  operator<(const Point& right) {
    return x < right.x;
  }
};

int solve(int n, const vector<int>& a) {

  fill(dp, dp+n, INF);
  for (int i=0; i<n; ++i) {
    *lower_bound(dp, dp+n, a[i]) = a[i];
  }
  return lower_bound(dp, dp+n, INF) - dp ;
}

int main(){
  Point p1,p2;
  int N;
  cin>>p1.x>>p1.y>>p2.x>>p2.y;
  cin>>N;
  vector<Point> points(N);
  for(int i=0;i<N;i++)
    cin>>points[i].x>>points[i].y;

  double result;
  if(p1.x==p2.x){
    bool pexit = false;
    int ymin=min(p1.y,p2.y);
    int ymax=max(p1.y,p2.y);
    int x=p1.x;
    for(int i=0;i<N;i++){
      if(x==points[i].x){
	int y=points[i].y;
	if(ymin<y&&y<ymax){
	  pexit = true;
	}
      }
    }
    result = 100 * (ymax-ymin);
    if (pexit)result += 10 * M_PI - 20;

  } else if (p1.y==p2.y) {
    bool pexit = false;
    int xmin=min(p1.x,p2.x);
    int xmax=max(p1.x,p2.x);
    int y=p1.y;
    for(int i=0;i<N;i++){
      if(y==points[i].y){
	int x=points[i].x;
	if(xmin<x&&x<xmax){
	  pexit = true;
	}
      }
    }
    result = 100 * (xmax-xmin);
    if (pexit)result += 10 * M_PI - 20;

  } else {

    Point start;
    Point end;
    if (p1<p2){
      start = p1;
      end   = p2;
    }else{
      start = p2;
      end   = p1;
    }
    sort(points.begin(),points.end());

    int xmin = min(start.x,end.x);
    int xmax = max(start.x,end.x);

    int ymin = min(start.y,end.y);
    int ymax = max(start.y,end.y);

    vector<int> data;
    for (int i=0;i<N;i++) {
      if (start.x<=points[i].x&&points[i].x<=end.x&&
	  ymin<=points[i].y&&points[i].y<=ymax)
	{
	  int d;
	  if (start.y<start.y)
	    d=points[i].y - start.y;
	  else
	    d=start.y - points[i].y;
	  data.push_back(d);
	}
    }
    result = 100 * (xmax - xmin + ymax - ymin) + solve(data.size(), data) * (5 * M_PI - 20);
  }

  cout << setprecision(18) << result << endl;
  return 0;
}

#include<stdio.h>
