int MIN(int a,int b){return a<b?a:b;}
int MAX(int a,int b){return a<b?b:a;}
int f(int a,int b,int c){return (MIN(a,b)<=c&&c<=MAX(a,b))?1:0;}
int R=1,C=1,H[2000010],N[2000010];
//評価関数（いまはMIN）
int hyouka(int a,int b){
  if(C<b)return 1;
  if(C<a||b==0)return 0;
  return N[H[a]]<N[H[b]]?1:0;
}
//挿入関数
void hin(int a){
  int i=C++;
  for(N[H[0]=R]=a;hyouka(0,i/2);i/=2)H[i]=H[i/2];
  H[i]=R++;
}
//取り出す関数
int hout(){
  int rt=H[1],i,j=2,k=H[--C];
  for(i=1;hyouka(i,C);i=j)H[i]=H[j=i*2+1-hyouka(i*2,i*2+1)];
  H[j/2]=k;
  return rt;
}
int lb(int l,int r,int n,int *d){
  int m=(l+r)/2;
  if(l==r)return m;
  return n<=d[m]?lb(l,m,n,d):lb(m+1,r,n,d);
}
int lis(int n,int *d){
  if(n==0)return 0;
  int r=0,i,s[10000]={d[0]};
  for(i=1;i<n;i++)s[r]<d[i]?(s[++r]=d[i]):(s[lb(0,r,d[i],s)]=d[i]);
  return r+1;
}
int main(){
  int sx,sy,gx,gy,n,r=0,x,y,i,M[200010],d[200010],a;
  double l=20-5*acos(-1),ans=0;
  scanf("%d %d %d %d %d",&sx,&sy,&gx,&gy,&n);
  ans=(abs(sx-gx)+abs(sy-gy))*100;//printf("%f\n",ans);
  if(sx==gx||sy==gy){
    for(i=0;i<n;i++){
      scanf("%d %d",&x,&y);
      if(sx==gx&&f(sy,gy,y)||sy==gy&&f(sx,gx,x))ans+=10-l;
    }
    printf("%.13f\n",ans);
    return 0;
  }
  for(i=0;i<n;i++){
    scanf("%d %d",&x,&y);
    if(f(sx,gx,x)&&f(sy,gy,y)){
      M[R]=y;//printf("%d %d\n",x,y);
      hin(x);
    }
  }
  while(C-1)d[r++]=M[hout()];
  a=lis(r,d);//printf("%d\n",a);
  printf("%.13lf\n",ans-a*l);
  return 0;
}

