int fountain(int x1, int y1, int x2, int y2, int y[]) {
	int a = 0, b = 0;
	if (y1 <= y[x1] && y[x1] <= y2)
	{
		a = fountain(x1, x2, y[x1], y2, y);
		b = fountain(x1 + 1, x2, y[x1] + 1, y2, y);
		a = (a > b) ? a + 1 : b;
	}
	return a;
}

