		return 0;
	}
	qsort(pos,s,sizeof(Pos),comp1);
	a=pos[0].x,b=pos[0].y;
	FOR(i,1,s){
		if((a<pos[i].x)==f1&&(b<pos[i].y)==f2){
			c1++;
			a=pos[i].x,b=pos[i].y;
		}
	}
	if(a==tx||b==ty){
		if(c1>2) t1=ans-(c1-1)*p+q;
		else t1=ans;
	}else t1=ans-c1*p;
	qsort(pos,s,sizeof(Pos),comp2);
	a=pos[0].x,b=pos[0].y;
	FOR(i,1,s){
		if((a<pos[i].x)==f1&&(b<pos[i].y)==f2){
			c2++;
			a=pos[i].x,b=pos[i].y;
		}
	}
	if(a==tx||b==ty){
		if(c2>2) t2=ans-(c2-1)*p+q;
		else t2=ans;
	}else t2=ans-c2*p;
	printf("%.20llf\n",MIN(t1,t2));
	return 0;
}

