class SegmentTree( size: Int ) {

    val s: Int
    val a: IntArray

    init {
        s = size.closest2Pow()
        a = IntArray( 2 * s )
    }

    fun put( p: Int, value: Int ) {
        var c = s + p
        a[c] = value
        while ( c > 1 ) {
            c /= 2
            a[c] = Math.max( a[c * 2], a[c * 2 + 1] )
        }
    }

    fun max( until: Int ): Int {
        if ( until >= s ) return a[1]
        var m = 0
        var c = 1
        var l = 0
        var r = s
        while ( c < a.size ) {
            if ( l >= until ) break
            c *= 2
            val mid = ( l + r ) / 2
            if ( mid > until ) {
                r = mid
            } else {
                m = Math.max( m, a[c] )
                l = mid
                c ++
            }
        }
        return m
    }
}

