    var y1 = st.nextInt()
    var x2 = st.nextInt()
    var y2 = st.nextInt()
    val n = st.nextInt()
    val x = IntArray( n )
    val y = IntArray( n )
    for ( i in 0 until n ) {
        x[i] = st.nextInt() * if ( x1 <= x2 ) 1 else -1
        y[i] = st.nextInt() * if ( y1 <= y2 ) 1 else -1
    }
    if ( x1 > x2 ) {
        x1 = -x1
        x2 = -x2
    }
    if ( y1 > y2 ) {
        y1 = -y1
        y2 = -y2
    }
    val inside = x.indices.filter { i -> x[i] in x1 .. x2 && y[i] in y1 .. y2 }
    val byX = inside.indices.sortedBy { x[inside[it]] }
    val Y = byX.map { y[inside[it]] }
    val byY = Y.indices.sortedBy { Y[it] }
    val yToPos = HashMap<Int, Int>()
    for ( i in byY.indices ) {
        yToPos[Y[i]] = i
    }
    val segTree = SegmentTree( Y.size )
    for ( i in Y.indices ) {
        val value = segTree.max( yToPos[Y[byY[i]]]!! ) + 1
        segTree.put( yToPos[Y[byY[i]]]!!, value )
    }
    println( ( Math.abs( x2 - x1 ) + Math.abs( y2 - y1 ) ) * 100.0 +
            segTree.max( Y.size + 1 ) * 10.0 * ( Math.PI / 2 - 2 ) +
            if ( x2 - x1 + 1 == inside.size || y2 - y1 + 1 == inside.size ) 10 * Math.PI / 2 else 0.0
    )
}

class SegmentTree( size: Int ) {

    val s: Int
    val a: IntArray

    init {
        s = size.closest2Pow()
        a = IntArray( 2 * s )
    }

    fun put( p: Int, value: Int ) {
        var c = s + p
        a[c] = value
        while ( c > 1 ) {
            c /= 2
            a[c] = Math.max( a[c * 2], a[c * 2 + 1] )
        }
    }

    fun max( until: Int ): Int {
        if ( until >= s ) return a[1]
        var m = 0
        var c = 1
        var l = 0
        var r = s
        while ( c * 2 < a.size ) {
            if ( l >= until ) break
            c *= 2
            val mid = ( l + r ) / 2
            if ( mid > until ) {
                r = mid
            } else {
                m = Math.max( m, a[c] )
                l = mid
                c ++
            }
        }
        return m
    }
}

private fun Int.closest2Pow(): Int {
    var r = 1
    while ( r < this ) r *= 2
    return r
}

