    if (x1 > x2) { var t = x1; x1 = x2; x2 = t; t = y1; y1 = y2; y2 = t }
    val swapY: (Int) -> Int = if (y1 > y2) {{99999999 - it}} else {{it}}
    val p1 = Point(x1, swapY(y1))
