    static class FountainWalk {
        double circle = Math.PI * 10 / 2;

        public void solve(int testNumber, FastInput in, PrintWriter out) {
            Point begin = new Point();
            begin.x = in.readInt();
            begin.y = in.readInt();

            Point end = new Point();
            end.x = in.readInt();
            end.y = in.readInt();

            int n = in.readInt();
            List<Point> pts = new ArrayList<>(n);

            for (int i = 0; i < n; i++) {
                Point pt = new Point();
                pt.x = in.readInt();
                pt.y = in.readInt();
                pts.add(pt);
            }

            if (begin.x > end.x) {
                begin.x = -begin.x;
                end.x = -end.x;
                for (Point pt : pts) {
                    pt.x = -pt.x;
                }
            }
            if (begin.y > end.y) {
                begin.y = -begin.y;
                end.y = -end.y;
                for (Point pt : pts) {
                    pt.y = -pt.y;
                }
            }

            Point[] ptArray = pts.stream().filter(x -> inRange(begin, end, x.x, x.y)).toArray(x -> new Point[x]);
            Arrays.sort(ptArray, (a, b) -> Integer.compare(a.x, b.x));

            TreeMap<Integer, Integer> map = new TreeMap<>();
            for (int i = 0; i < ptArray.length; i++) {
                Point pt = ptArray[i];
                Map.Entry<Integer, Integer> floor = map.floorEntry(pt.y);
                int dp = (floor == null ? 0 : floor.getValue()) + 1;
                while (true) {
                    Map.Entry<Integer, Integer> ceil = map.ceilingEntry(pt.y);
                    if (ceil == null || ceil.getValue() >= dp) {
                        break;
                    }
                    map.remove(ceil.getKey());
                }
                map.put(pt.y, dp);
            }

            int cnt = map.isEmpty() ? 0 : map.lastEntry().getValue();
            double ans = (double) (end.x - begin.x + end.y - begin.y) * 100;
            ans = ans + cnt * (circle - 20);

            if (cnt == (end.x - begin.x + 1) || cnt == (end.y - begin.y + 1)) {
                ans += circle;
            }

            out.printf("%.15f", ans);
        }

        public boolean inRange(Point lb, Point rt, int x, int y) {
            return lb.x <= x && rt.x >= x && lb.y <= y && rt.y >= y;
        }

    }
    static class Point {
        int x;
        int y;

    }
    static class FastInput {
        private final InputStream is;
        private byte[] buf = new byte[1 << 13];
        private int bufLen;
        private int bufOffset;
        private int next;

        public FastInput(InputStream is) {
            this.is = is;
        }

        private int read() {
            while (bufLen == bufOffset) {
                bufOffset = 0;
                try {
                    bufLen = is.read(buf);
                } catch (IOException e) {
                    bufLen = -1;
                }
                if (bufLen == -1) {
                    return -1;
                }
            }
            return buf[bufOffset++];
        }

        public void skipBlank() {
            while (next >= 0 && next <= 32) {
                next = read();
            }
        }

        public int readInt() {
            int sign = 1;

            skipBlank();
            if (next == '+' || next == '-') {
                sign = next == '+' ? 1 : -1;
                next = read();
            }

            int val = 0;
            if (sign == 1) {
                while (next >= '0' && next <= '9') {
                    val = val * 10 + next - '0';
                    next = read();
                }
            } else {
                while (next >= '0' && next <= '9') {
                    val = val * 10 - next + '0';
                    next = read();
                }
            }

            return val;
        }

    }
}

import java.io.*;
import java.util.*;

class Solver {
  // x1 <= x2
  // y1 <= y2
  final int x1, y1, x2, y2, n;
  final int[] xs, ys;

  private Solver(int x1, int y1, int x2, int y2, int n, int[] xs, int[] ys) {
    this.x1 = x1;
    this.y1 = y1;
    this.x2 = x2;
    this.y2 = y2;
    this.n = n;
    this.xs = xs;
    this.ys = ys;
  }

  private static int flipIfNeeded(int v, boolean flip) {
    if (flip) {
      return 100_000_000 - v - 1;
    } else {
      return v;
    }
  }

  public static Solver createInstance(int x1, int y1, int x2, int y2, int n, int[][] xys) {
    boolean xFlip = x1 > x2;
    int normX1 = flipIfNeeded(x1, xFlip);
    int normX2 = flipIfNeeded(x2, xFlip);

    boolean yFlip = y1 > y2;
    int normY1 = flipIfNeeded(y1, yFlip);
    int normY2 = flipIfNeeded(y2, yFlip);

    int[] normXs = new int[n];
    int[] normYs = new int[n];
    for (int i = 0; i < n; i++) {
      normXs[i] = flipIfNeeded(xys[i][0], xFlip);
      normYs[i] = flipIfNeeded(xys[i][1], yFlip);
    }

    return new Solver(normX1, normY1, normX2, normY2, n, normXs, normYs);
  }

  private boolean existBetween(int a, int bMin, int bMax, int[] as, int[] bs) {
    for (int i = 0; i < n; i++) {
      if (as[i] == a && bMin < bs[i] && bs[i] < bMax) {
        return true;
      }
    }
    return false;
  }

  public double solve() {
    if (x1 == x2) {
      if (existBetween(x1, y1, y2, xs, ys)) {
        return 100.0 * (y2 - y1) + Math.PI * 10.0 - 20.0;
      }
      return 100.0 * (y2 - y1);
    }
    if (y1 == y2) {
      if (existBetween(y1, x1, x2, ys, xs)) {
        return 100.0 * (x2 - x1) + Math.PI * 10.0 - 20.0;
      }
      return 100.0 * (x2 - x1);
    }

    TreeMap<Integer, Integer> xToY = new TreeMap<>();
    for (int i = 0; i < n; i++) {
      if (xs[i] < x1 || x2 < xs[i] || ys[i] < y1 || y2 < ys[i]) {
        continue;
      }
      xToY.put(xs[i], ys[i]);
    }

    TreeMap<Integer, Integer> yToCount = new TreeMap<>();
    yToCount.put(y1 - 1, 0);
    for (int y : xToY.values()) {
      int countForY = yToCount.lowerEntry(y).getValue() + 1;
      Integer existingHigherKey = yToCount.higherKey(y);
      if (existingHigherKey != null) {
        yToCount.remove(existingHigherKey);
      }
      yToCount.put(y, countForY);
    }
    int maxCount = yToCount.lastEntry().getValue();
    return 100.0 * (x2 - x1) + 100.0 * (y2 - y1) + Math.PI * 5.0 * maxCount - 20.0 * maxCount;
  }
}

