        int res = 0;
        for(int i = 0; i < n; i++){
            if(m[i][0]>=minx&&m[i][0]<=maxx&&m[i][1]>=miny&&m[i][1]<=maxy){
                res++;
            }
        }
        int[] a1 = new int[res];
        int[] a2 = new int[res];
