		for(int i=0; i<a.length; ++i)
			a[i]=ptsList.get(i).y*sign;
		double t=(x2-x1+Math.abs(y1-y2))*100L+(5*Math.PI-20)*LongestIncreasingSubsequenceLength(a, a.length);
		boolean addExtra=true;
		for(int i=0; i<a.length-1; ++i) {
			if(a[i+1]-a[i]!=1||ptsList.get(i+1).x-ptsList.get(i).x!=1) {
				addExtra=false;
				break;
			}
		}
		if(addExtra&&(x1==ptsList.get(0).x&&x2==ptsList.get(ptsList.size()-1).x||y1==sign*a[0]&&y2==sign*a[a.length-1]))
			t+=Math.PI*5;
