// import java.awt.Point;

public class Main {
    InputStream is;
    PrintWriter out;
    String INPUT = "";

    long MOD = 1_000_000_007;
    int inf = Integer.MAX_VALUE/2;

    void solve(){
        int[] s = new int[]{ni(), ni()};
        int[] g = new int[]{ni(), ni()};
        int minx= Math.min(s[0],g[0]);
        int maxx= Math.max(s[0],g[0]);
        int miny= Math.min(s[1],g[1]);
        int maxy= Math.max(s[1],g[1]);
        int n = ni();
        int[][] m = new int[n][2];
        for(int i = 0; i < n; i++){
            m[i][0] = ni();
            m[i][1] = ni();
        }
        Arrays.sort(m, (a,b)-> a[0]-b[0]);
        int res = 0;
        for(int i = 0; i < n; i++){
            if(m[i][0]>=minx&&m[i][0]<=maxx&&m[i][1]>=miny&&m[i][1]<=maxy){
                res++;
            }
        }
        int[] a1 = new int[res];
        int[] a2 = new int[res];
        int res2 = 0;
        for(int i = 0; i < n; i++){
            if(m[i][0]>=minx&&m[i][0]<=maxx&&m[i][1]>=miny&&m[i][1]<=maxy){
                a1[res2] = m[i][1];
                a2[res2] = m[i][1];
                res2++;
            }
        }
        Arrays.sort(a2);
        HashMap<Integer,Integer> map = new HashMap<>();
        for(int i = 0; i < res; i++){
            map.put(a2[i],i);
        }
        for(int i = 0; i < res; i++){
            a1[i] = map.get(a1[i]);
        }
        double ans = (double)((maxx-minx)+(maxy-miny))*100;
        ans -= (double)lis(a1)*(20-Math.PI*5);
        if(lis(a1)==Math.min(maxx-minx, maxy-miny)+1) ans = ans + 20-Math.PI*5 + 10*Math.PI-20;
        out.println(ans);
    }

    public static int lis(int[] in)
    {
        int n = in.length;
        int ret = 0;
        int[] h = new int[n + 1];
        Arrays.fill(h, Integer.MIN_VALUE / 2);
        for(int i = 0;i < n;i++){
            int ind = Arrays.binarySearch(h, 0, ret + 1, in[i]);
            if(ind < 0){
                ind = -ind-2;
                h[ind+1] = in[i];
                if(ind >= ret)ret++;
            }
        }
        return ret;
    }


    void run() throws Exception
    {
        is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
        out = new PrintWriter(System.out);
        long s = System.currentTimeMillis();
        solve();
        out.flush();
        if(!INPUT.isEmpty())tr(System.currentTimeMillis()-s+"ms");
    }

    public static void main(String[] args) throws Exception { new Main().run(); }

    private byte[] inbuf = new byte[1024];
    private int lenbuf = 0, ptrbuf = 0;

    private int readByte()
    {
        if(lenbuf == -1)throw new InputMismatchException();
        if(ptrbuf >= lenbuf){
            ptrbuf = 0;
            try { lenbuf = is.read(inbuf); } catch (IOException e) { throw new InputMismatchException(); }
            if(lenbuf <= 0)return -1;
        }
        return inbuf[ptrbuf++];
    }

    private boolean isSpaceChar(int c) { return !(c >= 33 && c <= 126); }
    private int skip() { int b; while((b = readByte()) != -1 && isSpaceChar(b)); return b; }

    private double nd() { return Double.parseDouble(ns()); }
    private char nc() { return (char)skip(); }

    private String ns()
    {
        int b = skip();
        StringBuilder sb = new StringBuilder();
        while(!(isSpaceChar(b) && b != ' ')){
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    private char[] ns(int n)
    {
        char[] buf = new char[n];
        int b = skip(), p = 0;
        while(p < n && !(isSpaceChar(b))){
            buf[p++] = (char)b;
            b = readByte();
        }
        return n == p ? buf : Arrays.copyOf(buf, p);
    }

    private char[][] nm(int n, int m)
    {
        char[][] map = new char[n][];
        for(int i = 0;i < n;i++)map[i] = ns(m);
        return map;
    }

    private int[] na(int n)
    {
        int[] a = new int[n];
        for(int i = 0;i < n;i++)a[i] = ni();
        return a;
    }

    private int ni()
    {
        int num = 0, b;
        boolean minus = false;
        while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
        if(b == '-'){
            minus = true;
            b = readByte();
        }

        while(true){
            if(b >= '0' && b <= '9'){
                num = num * 10 + (b - '0');
            }else{
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private long nl()
    {
        long num = 0;
        int b;
        boolean minus = false;
        while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
        if(b == '-'){
            minus = true;
            b = readByte();
        }

        while(true){
            if(b >= '0' && b <= '9'){
                num = num * 10 + (b - '0');
            }else{
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private static void tr(Object... o) { System.out.println(Arrays.deepToString(o)); }

}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.TreeMap;
import java.util.TreeSet;

public class Main {
	//噴水通過180度
	final double FH = 10 * Math.PI - 20;
	//噴水通過90度
	final double FQ = 5 * Math.PI - 20;

	public static long l=0,l2=0;
	public static void main(String[] args) throws IOException {
		l = System.currentTimeMillis();
		new Main().exec();
		l2 = System.currentTimeMillis();

	}

	public void exec() throws IOException {

		InputUtil in = new InputUtil();
		PrintWriter out = new PrintWriter(System.out);
		int x1 = (int)in.nextInt();
		int y1 = (int)in.nextInt();
		int x2 = (int)in.nextInt();
		int y2 = (int)in.nextInt();
		int N = (int)in.nextInt();
		int dx = (x2 - x1>0)?1:-1;
		int dy = (y2 - y1>0)?1:-1;
		TreeMap<Integer,Integer> FXMap = new TreeMap<>();
		for(int i=0; i<N; i++) {
			int fx = in.nextInt();
			int fy = in.nextInt();
			if(checkBetween(x1,x2,fx) && checkBetween(y1,y2,fy)) {
				FXMap.put(fx,fy);
			}
		}
		TreeMap<Integer,Integer> FYMap = new TreeMap<>();
		Integer key = null;
		int max = 0;
		while((key = nextEntry(FXMap,key,-dx)) != null){
			int count = 1;
			int y = FXMap.get(key);
			Integer nextY = nextEntry(FYMap,y,dy);
			if(nextY != null) {
				count += FYMap.get(nextY);
			}
			FYMap.put(y,count);
			max = Math.max(max, count);
		}
		int dirX=(x2-x1)*dx;
		int dirY=(y2-y1)*dy;
		long base_dir = dirX + dirY;
		base_dir *= 100;
		double gosa = 0;
		if(x1==x2 || y1==y2){
			gosa += FH * max;
		} else {
			gosa += FQ * max;
			if(max == Math.min(dirX+1, dirY+1)) {
				gosa += FQ;
			}
		}
		double dir = base_dir + gosa;
		out.printf("%.12f",dir);
		out.flush();
	}

	Integer nextEntry(TreeMap<Integer,Integer> FXMap, Integer key, int dir) {
		if(FXMap.isEmpty())
			return null;
		else if(dir == 1){
			if(key == null)
				return FXMap.firstKey();
			else  
				return FXMap.ceilingKey(key+1);
		}else{
			if(key == null)
				return FXMap.lastKey();
			else  
				return FXMap.floorKey(key-1);
		}
	}

	boolean checkBetween(int v1, int v2, int vc) {
		if(v1==v2){
			return v1==vc;
		}else if(v1>v2) {
			return (v2 <= vc && vc <= v1);
		} else {
			return (v1 <= vc && vc <= v2);
		}
	}

}




class InputUtil {
	//Static Fields
	private static final int BUFSIZ = 100000;

	//Fields
	protected InputStream in;
	private char[] buf = null;
	private int ptr = 0;
	private int max = -1;
	private BufferedReader br = null;

	//Constructors
	public InputUtil() {this(System.in,BUFSIZ);}
	public InputUtil(InputStream in, int bufsiz) {
		initBuf(bufsiz);
		initIn(in);
	}

	//Methods
	//Initializer
	protected void initIn(InputStream in) {br = new BufferedReader(new InputStreamReader(this.in = in));}
	protected void initBuf(int bufsiz) {buf = new char[bufsiz];}

	//buffer operation
	private void next() throws IOException {ptr++; readBuf();}
	private void readBuf() throws IOException {
		if(ptr >= max && br.ready()) {
			if(max>0) Arrays.fill(buf,0,max,(char)0);
			max = br.read(buf);
			ptr = 0;
		}
	}

	//Number Input Reader/Parser
	private boolean isNum(char b) {return '0' <= b && b <= '9'; }
	private boolean isMinus(char b) {return b=='-'; }

	private int _nextInt() throws IOException {
		int sign = 1;
		int res = 0;
		char c;
		while (!isNum(c=buf[ptr]) && !isMinus(c)) 
			next();
		if (isMinus(buf[ptr])) {
			sign = -1;
			next();
		}
		while (isNum(c=buf[ptr])) {
			res *= 10;
			res += c - '0' ;
			next();
		}
		next();
		return sign * res;
	}

	public int nextInt() throws IOException {
		readBuf();
		return _nextInt();
	}

	public int[] nextInt(int[] result) throws IOException {
		readBuf();
		for(int i=0; i<result.length; i++) {
			result[i] = _nextInt();
		}
		return result;
	}

	//Close 
	public void close() throws IOException {
		if(!this.in.equals(System.in)) 
			this.in.close();
	}

}

