public class Main {

  private static void solve() {
    int x1 = ni();
    int y1 = ni();
    int x2 = ni();
    int y2 = ni();

    int n = ni();
    int[] x = new int[n];
    int[] y = new int[n];
    int m = 0;
    int f1 = 1;
    int f2 = 1;
    if (x1 > x2) {
      f1 = -1;
      x1 = -x1;
      x2 = -x2;
    }
    if (y1 > y2) {
      f2 = -1;
      y1 = -y1;
      y2 = -y2;
    }
    for (int i = 0; i < n; i ++) {
      int nx = f1 * ni();
      int ny = f2 * ni();
      if (x1 <= nx && nx <= x2 && y1 <= ny && ny <= y2) {
        x[m] = nx;
        y[m] = ny;
        m ++;
      }
    }
    x = Arrays.copyOf(x, m);
    y = Arrays.copyOf(y, m);
    Compress cmp = new Compress(y);

    int[][] pos = new int[m + 1][2];
    for (int i = 0; i < m; i ++) {
      pos[i][0] = x[i];
      pos[i][1] = cmp.list[i];
    }
    pos[m][0] = x2;
    pos[m][1] = y2;

    Arrays.sort(pos, (o1, o2) -> o1[0] == o2[0] ? o1[1] - o2[1] : o1[0] - o2[0]);
    int ST = 201000;
    SegmentTreeRMQ st = new SegmentTreeRMQ(ST);
    for (int i = 0; i < ST; i ++) st.update(i, 0);
    st.update(pos[m][1], 0);
    for (int i = m - 1; i >= 0; i --) {
      int z = pos[i][1];
      int min = st.min(z, ST);
      st.update(z, min - 1);
    }

    int ball = -st.min(0,  201000);

    double total = (Math.abs(x1 - x2) + Math.abs(y1 - y2)) * 100.0;
    double arg1 = 20.0 - Math.PI * 5.0;
    double arg2 = Math.PI * 10.0 - 20.0;

    int lenMin = Math.min(Math.abs(x2 - x1), Math.abs(y1 - y2));
    if (lenMin <= ball - 1) {
      out.printf("%.13f\n", total - arg1 * lenMin + arg2);
    } else {
      out.printf("%.13f\n", total - arg1 * ball);
    }
  }

