import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.StringTokenizer;
import java.io.BufferedReader;
import java.util.Collections;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
	public static void main(String[] args) {
		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		FastScanner in = new FastScanner(inputStream);
		PrintWriter out = new PrintWriter(outputStream);
		ProblemC solver = new ProblemC();
		solver.solve(1, in, out);
		out.close();
	}

	static class ProblemC {
		public void solve(int testNumber, FastScanner in, PrintWriter out) {
			int x1 = in.nextInt();
			int y1 = in.nextInt();
			int x2 = in.nextInt();
			int y2 = in.nextInt();
			int n = in.nextInt();
			int[] x = new int[n];
			int[] y = new int[n];
			for (int i = 0; i < n; i++) {
				x[i] = in.nextInt();
				y[i] = in.nextInt();
			}
			if (x1 > x2) {
				x1 = -x1;
				x2 = -x2;
				for (int i = 0; i < n; i++) {
					x[i] = -x[i];
				}
			}
			if (y1 > y2) {
				y1 = -y1;
				y2 = -y2;
				for (int i = 0; i < n; i++) {
					y[i] = -y[i];
				}
			}

			double ans = 100 * (x2 - x1 + y2 - y1);
			if (x1 == x2) {
				for (int i = 0; i < n; i++) {
					if (x[i] == x1 && y[i] >= y1 && y[i] <= y2) {
						ans -= 20;
						ans += Math.PI * 10;
					}
				}
			} else if (y1 == y2) {
				for (int i = 0; i < n; i++) {
					if (y[i] == y1 && x[i] >= x1 && x[i] <= x2) {
						ans -= 20;
						ans += Math.PI * 10;
					}
				}
			} else {
				List<Point> ps = new ArrayList<>();
				ps.add(new Point(x2, y2));
				for (int i = 0; i < n; i++) {
					if (x[i] >= x1 && x[i] <= x2 && y[i] >= y1 && y[i] <= y2) {
						ps.add(new Point(x[i], y[i]));
					}
				}
				Collections.sort(ps);
				Set<Integer> xs = new HashSet<>();
				for (Point p : ps) {
					xs.add(p.x);
				}
				int[] interestingX = new int[xs.size()];
				int ptr = 0;
				for (int cx : xs) {
					interestingX[ptr++] = cx;
				}
				Arrays.sort(interestingX);
				int[] d = new int[ps.size()];
				IntervalTree tree = new IntervalTree(xs.size());
				for (int i = 0; i < d.length; i++) {
					int id = Arrays.binarySearch(interestingX, ps.get(i).x);
					d[i] = 1 + tree.getMax(0, id);
					tree.set(id, d[i]);
				}
				int c = d[d.length - 1] - 1;
				ans -= c * 20;
				ans += c * Math.PI * 5;
			}
			out.printf("%.15f\n", ans);
		}

		class Point implements Comparable<Point> {
			int x;
			int y;

			Point(int x, int y) {
				this.x = x;
				this.y = y;
			}

			public int compareTo(Point o) {
				if (x != o.x) {
					return x - o.x;
				}
				if (y != o.y) {
					return y - o.y;
				}
				return 0;
			}

		}

		class IntervalTree {
			int[] max;
			int n;

			IntervalTree(int n) {
				this.n = n;
				max = new int[4 * n];
			}

			void set(int pos, int val) {
				set(0, pos, 0, n - 1, val);
			}

			int getMax(int l, int r) {
				return get(0, l, r, 0, n - 1);
			}

			private void set(int root, int pos, int L, int R, int val) {
				if (pos < L || pos > R) {
					return;
				}
				if (pos == L) {
					max[root] = val;
					return;
				}
				int M = (L + R) / 2;
				set(2 * root + 1, pos, L, M, val);
				set(2 * root + 2, pos, M + 1, R, val);
				max[root] = Math.max(max[2 * root + 1], max[2 * root + 2]);
			}

			private int get(int root, int l, int r, int L, int R) {
				if (l > r || l > R || L > r || L > R) {
					return 0;
				}
				if (l == L && r == R) {
					return max[root];
				}
				int M = (L + R) / 2;
				int res = 0;
				res = Math.max(res, get(2 * root + 1, l, Math.min(r, M), L, M));
				res = Math.max(res, get(2 * root + 2, Math.max(l, M + 1), r, M + 1, R));
				return res;
			}

		}

	}

	static class FastScanner {
		private BufferedReader in;
		private StringTokenizer st;

		public FastScanner(InputStream stream) {
			in = new BufferedReader(new InputStreamReader(stream));
		}

		public String next() {
			while (st == null || !st.hasMoreTokens()) {
				try {
					st = new StringTokenizer(in.readLine());
				} catch (IOException e) {
					throw new RuntimeException(e);
				}
			}
			return st.nextToken();
		}

		public int nextInt() {
			return Integer.parseInt(next());
		}

	}
}

import java.io.*;
import java.util.*;

class Solver {
  // x1 <= x2
  // y1 <= y2
  final int x1, y1, x2, y2, n;
  final int[] xs, ys;

  private Solver(int x1, int y1, int x2, int y2, int n, int[] xs, int[] ys) {
    this.x1 = x1;
    this.y1 = y1;
    this.x2 = x2;
    this.y2 = y2;
    this.n = n;
    this.xs = xs;
    this.ys = ys;
  }

  private static int flipIfNeeded(int v, boolean flip) {
    if (flip) {
      return 100_000_000 - v - 1;
    } else {
      return v;
    }
  }

  public static Solver createInstance(int x1, int y1, int x2, int y2, int n, int[][] xys) {
    boolean xFlip = x1 > x2;
    int normX1 = flipIfNeeded(x1, xFlip);
    int normX2 = flipIfNeeded(x2, xFlip);

    boolean yFlip = y1 > y2;
    int normY1 = flipIfNeeded(y1, yFlip);
    int normY2 = flipIfNeeded(y2, yFlip);

    int[] normXs = new int[n];
    int[] normYs = new int[n];
    for (int i = 0; i < n; i++) {
      normXs[i] = flipIfNeeded(xys[i][0], xFlip);
      normYs[i] = flipIfNeeded(xys[i][1], yFlip);
    }

    return new Solver(normX1, normY1, normX2, normY2, n, normXs, normYs);
  }

  private boolean existBetween(int a, int bMin, int bMax, int[] as, int[] bs) {
    for (int i = 0; i < n; i++) {
      if (as[i] == a && bMin < bs[i] && bs[i] < bMax) {
        return true;
      }
    }
    return false;
  }

  public double solve() {
    if (x1 == x2) {
      if (existBetween(x1, y1, y2, xs, ys)) {
        return (y2 - y1) * 100 + Math.PI * 10.0 - 20.0;
      }
      return (y2 - y1) * 100;
    }
    if (y1 == y2) {
      if (existBetween(y1, x1, x2, ys, xs)) {
        return (x2 - x1) * 100 + Math.PI * 10.0 - 20.0;
      }
      return (x2 - x1) * 100;
    }

    TreeMap<Integer, Integer> xToY = new TreeMap<>();
    for (int i = 0; i < n; i++) {
      if (xs[i] < x1 || x2 < xs[i] || ys[i] < y1 || y2 < ys[i]) {
        continue;
      }
      xToY.put(xs[i], ys[i]);
    }

    TreeMap<Integer, Integer> yToCount = new TreeMap<>();
    yToCount.put(y1 - 1, 0);
    for (int y : xToY.values()) {
      int countForY = yToCount.lowerEntry(y).getValue() + 1;
      Integer existingHigherKey = yToCount.higherKey(y);
      if (existingHigherKey != null) {
        yToCount.remove(existingHigherKey);
      }
      yToCount.put(y, countForY);
    }
    int maxCount = yToCount.lastEntry().getValue();
    return 100.0 * (x2 - x1) + 100.0 * (y2 - y1) + Math.PI * 5.0 * maxCount - 20.0 * maxCount;
  }
}

