	public static void main(String[] args) {
		StdIn in = new StdIn();
		int x1=in.nextInt(), y1=in.nextInt(), x2=in.nextInt(), y2=in.nextInt(), n=in.nextInt();
		if(x2<x1) {
			int temp=x1;
			x1=x2;
			x2=temp;
			temp=y1;
			y1=y2;
			y2=temp;
		}
		int minY=Math.min(y1, y2), maxY=Math.max(y1, y2);
		List<Point> ptsList = new ArrayList<Point>();
		for(int i=0; i<n; ++i) {
			int xi=in.nextInt(), yi=in.nextInt();
			if(xi<x1||xi>x2||yi<minY||yi>maxY)
				continue;
			ptsList.add(new Point(xi, yi));
		}
		if(ptsList.size()==0) {
			System.out.printf("%.12f\n", (x2-x1+Math.abs(y1-y2))*100.);
			return;
		}
		if(x1==x2||y1==y2) {
			System.out.printf("%.12f\n", (x2-x1+Math.abs(y1-y2))*100L+10*Math.PI-20);
			return;
		}
		ptsList.sort(new Comparator<Point>() {
			public int compare(Point a, Point b) {
				return a.x-b.x;
			}
		});
		int[] a = new int[ptsList.size()];
		int sign=y2-y1>0?1:-1;
		for(int i=0; i<a.length; ++i)
			a[i]=ptsList.get(i).y*sign;
		System.out.printf("%.12f\n", (x2-x1+Math.abs(y1-y2))*100L+(5*Math.PI-20)*LongestIncreasingSubsequenceLength(a, a.length));
	}

	static int CeilIndex(int A[], int l, int r, int key)
    {
        while (r - l > 1)
        {
            int m = l + (r - l)/2;
            if (A[m]>=key)
                r = m;
            else
                l = m;
        }

        return r;
    }

    static int LongestIncreasingSubsequenceLength(int A[], int size)
    {
        // Add boundary case, when array size is one

        int[] tailTable   = new int[size];
        int len; // always points empty slot

        tailTable[0] = A[0];
        len = 1;
        for (int i = 1; i < size; i++)
        {
            if (A[i] < tailTable[0])
                // new smallest value
                tailTable[0] = A[i];

            else if (A[i] > tailTable[len-1])
                // A[i] wants to extend largest subsequence
                tailTable[len++] = A[i];

            else
                // A[i] wants to be current end candidate of an existing
                // subsequence. It will replace ceil value in tailTable
                tailTable[CeilIndex(tailTable, -1, len-1, A[i])] = A[i];
        }

        return len;
    }

	interface Input {
		public String next();
		public String nextLine();
		public int nextInt();
		public long nextLong();
		public double nextDouble();
	}
	static class StdIn implements Input {
		final private int BUFFER_SIZE = 1 << 16;
		private DataInputStream din;
		private byte[] buffer;
		private int bufferPointer, bytesRead;

		public StdIn() {
			din = new DataInputStream(System.in);
			buffer = new byte[BUFFER_SIZE];
			bufferPointer = bytesRead = 0;
		}

		public StdIn(String filename) {
			try{
				din = new DataInputStream(new FileInputStream(filename));
			} catch(Exception e) {
				throw new RuntimeException();
			}
			buffer = new byte[BUFFER_SIZE];
			bufferPointer = bytesRead = 0;
		}

		public String next() {
			int c;
			while((c=read())!=-1&&(c==' '||c=='\n'||c=='\r'));
			StringBuilder s = new StringBuilder();
			while (c != -1)
			{
				if (c == ' ' || c == '\n'||c=='\r')
					break;
				s.append((char)c);
				c=read();
			}
			return s.toString();
		}

		public String nextLine() {
			int c;
			while((c=read())!=-1&&(c==' '||c=='\n'||c=='\r'));
			StringBuilder s = new StringBuilder();
			while (c != -1)
			{
				if (c == '\n'||c=='\r')
					break;
				s.append((char)c);
				c = read();
			}
			return s.toString();
		}

		public int nextInt() {
			int ret = 0;
			byte c = read();
			while (c <= ' ')
				c = read();
			boolean neg = (c == '-');
			if (neg)
				c = read();
			do
			{
				ret = ret * 10 + c - '0';
			}  while ((c = read()) >= '0' && c <= '9');

			if (neg)
				return -ret;
			return ret;
		}

		public int[] readIntArray(int n) {
			int[] ar = new int[n];
			for(int i=0; i<n; ++i)
				ar[i]=nextInt();
			return ar;
		}

		public long nextLong() {
			long ret = 0;
			byte c = read();
			while (c <= ' ')
				c = read();
			boolean neg = (c == '-');
			if (neg)
				c = read();
			do {
				ret = ret * 10 + c - '0';
			}
			while ((c = read()) >= '0' && c <= '9');
			if (neg)
				return -ret;
			return ret;
		}

		public long[] readLongArray(int n) {
			long[] ar = new long[n];
			for(int i=0; i<n; ++i)
				ar[i]=nextLong();
			return ar;
		}

		public double nextDouble() {
			double ret = 0, div = 1;
			byte c = read();
			while (c <= ' ')
				c = read();
			boolean neg = (c == '-');
			if (neg)
				c = read();

			do {
				ret = ret * 10 + c - '0';
			}
			while ((c = read()) >= '0' && c <= '9');

			if (c == '.')
			{
				while ((c = read()) >= '0' && c <= '9')
				{
					ret += (c - '0') / (div *= 10);
				}
			}

			if (neg)
				return -ret;
			return ret;
		}

		private void fillBuffer() throws IOException {
			bytesRead = din.read(buffer, bufferPointer = 0, BUFFER_SIZE);
			if (bytesRead == -1)
				buffer[0] = -1;
		}

		private byte read() {
			try{
				if (bufferPointer == bytesRead)
					fillBuffer();
				return buffer[bufferPointer++];
			} catch(IOException e) {
				throw new RuntimeException();
			}
		}

		public void close() throws IOException {
			if (din == null)
				return;
			din.close();
		}
	}
}

import java.io.*;
import java.util.*;

public class Main {
    private FastScanner in;
    private PrintWriter out;

    class Rat {
        long a, b;

        public Rat(long a, long b) {
            this.a = a;
            this.b = b;
            good();
        }

        Rat add(Rat an) {
            return new Rat(an.a * b + a * an.b, an.b * b);
        }

        Rat mul(Rat o) {
            return new Rat(a * o.a, b * o.b);
        }

        void good() {
            long g = gcd(a, b);
            a /= g;
            b /= g;
        }

        @Override
        public String toString() {
            String res = a + "/" + b;
            while (res.length() < 10) {
                res += " ";
            }
            return res;
        }
    }

    long gcd(long x, long y) {
        return x == 0 ? y : gcd(y % x, x);
    }

    class Point implements Comparable<Point> {
        int x, y;

        public Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        public Point() {
            x = in.nextInt();
            y = in.nextInt();
        }

        @Override
        public int compareTo(Point o) {
            return Integer.compare(x, o.x);
        }
    }

    void solve() {
        Point from = new Point();
        Point to = new Point();
        int n = in.nextInt();
        Point[] a = new Point[n];
        for (int i = 0; i < n; i++) {
            a[i] = new Point();
        }
        if (from.x > to.x) {
            from.x = -from.x;
            to.x = -to.x;
            for (Point p : a) {
                p.x = -p.x;
            }
        }
        if (from.y > to.y) {
            from.y = -from.y;
            to.y = -to.y;
            for (Point p : a) {
                p.y = -p.y;
            }
        }
        double q = Math.PI * 5;
        double len = 100.0 * (to.x - from.x + to.y - from.y);
        if (from.x == to.x || from.y == to.y) {
            boolean have = false;
            for (Point p : a) {
                if (p.x >= from.x && p.x <= to.x && p.y >= from.y && p.y <= to.y) {
                    have = true;
                }
            }
            if (have) {
                len -= 20;
                len += 2 * q;
            }
            out.println(len);
            return;
        }
        Arrays.sort(a);
        ArrayList<Integer> all = new ArrayList<>();
        for (Point p : a) {
            if (p.x >= from.x && p.x <= to.x && p.y >= from.y && p.y <= to.y) {
                all.add(p.y);
            }
        }
        int cnt = getMax(all);
        System.err.println("cnt = " + cnt);
        len -= 20 * cnt;
        len += q * cnt;
        out.println(len);
    }

    int getMax(ArrayList<Integer> all) {
        int n = all.size();
        int[] d = new int[n + 1];
        Arrays.fill(d, Integer.MAX_VALUE);
        d[0] = Integer.MIN_VALUE;

        for (int i = 0; i < n; i++) {
            int l = 0, r = n;
            while (r - l > 1) {
                int mid = (l + r) >> 1;
                if (d[mid] >= all.get(i)) {
                    r = mid;
                } else {
                    l = mid;
                }
            }
            d[r] = Math.min(d[r], all.get(i));
        }
        for (int res = n; res >= 0; res--) {
            if (d[res] != Integer.MAX_VALUE) {
                return res;
            }
        }
        return -1;
    }

    void solve332() {
        String s = in.next();
        int n = s.length();
        long res = n * 1L * (n - 1) / 2 + 1;
        int[] sum = new int[256];
        for (char c : s.toCharArray()) {
            res -= sum[c];
            sum[c]++;
        }
        out.println(res);
    }

    private void solve123() {

        final int n = 10;
        Rat[][] dp = new Rat[n][n];
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[0][i] = new Rat(i, 1);
        }
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                if (i <= j) {
                    Rat left = new Rat(j, i + j + 0).mul(new Rat(1, 1).add(dp[i][j - 1]));
                    Rat right = new Rat(i, (i + j)).mul(dp[i - 1][j]);
                    dp[i][j] = left.add(right);
                } else {
                    dp[i][j] = dp[j][i];
                }
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                System.err.printf(dp[i][j] + " ");
            }
            System.err.println("");
        }
        System.err.println(dp[3][4]);
    }

    private void run() {
        try {
            in = new FastScanner(new File("Main.in"));
            out = new PrintWriter(new File("Main.out"));

            solve();

            out.close();
        } catch (FileNotFoundException e) {
            e.printStackTrace();
        }
    }

    private void runIO() {
        in = new FastScanner(System.in);
        out = new PrintWriter(System.out);

        solve();

        out.close();
    }

    private class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        FastScanner(File f) {
            try {
                br = new BufferedReader(new FileReader(f));
            } catch (FileNotFoundException e) {
                e.printStackTrace();
            }
        }

        FastScanner(InputStream f) {
            br = new BufferedReader(new InputStreamReader(f));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                String s = null;
                try {
                    s = br.readLine();
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (s == null)
                    return null;
                st = new StringTokenizer(s);
            }
            return st.nextToken();
        }

        boolean hasMoreTokens() {
            while (st == null || !st.hasMoreTokens()) {
                String s = null;
                try {
                    s = br.readLine();
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (s == null)
                    return false;
                st = new StringTokenizer(s);
            }
            return true;
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }
    }

    public static void main(String[] args) {
        new Main().runIO();
    }
}

import java.awt.Point;
import java.util.ArrayList;
import java.util.PriorityQueue;
import java.util.Scanner;

public class Main {

	private void solve() {
		Scanner in = new Scanner(System.in);
		int x1 = in.nextInt();
		int y1 = in.nextInt();
		int x2 = in.nextInt();
		int y2 = in.nextInt();

		if(y2<y1){
			int sp = y2;
			y2 = y1;
			y1 =sp;
			sp = x2;
			x2 = x1;
			x1 = sp;
		} // y1 < y2

		int N = in.nextInt();

		if(x1==x2){
			boolean exist = false;
			for (int i = 0; i < N; i++) {
				int x = in.nextInt();
				int y = in.nextInt();
				if(x==x1 && y1<y && y<y2) exist = true;
			}
			System.out.println(100L*(y2-y1)+((!exist)?0:10*Math.PI-20));

		}else if(y1==y2){
			boolean exist = false;
			if(x1>x2){
				int sp = x2; x2 = x1; x1 = sp;
			}
			for (int i = 0; i < N; i++) {
				int x = in.nextInt();
				int y = in.nextInt();
				if(y==y1 && x1<x && x<x2) exist = true;
			}
			System.out.println(100L*(x2-x1)+((!exist)?0:10*Math.PI-20));

		}else if(x1<x2){
			PriorityQueue<Point> queue = new PriorityQueue<>(
					(a,b)->((Point)a).x-((Point)b).x
			);
			for (int i = 0; i < N; i++) {
				queue.add(new Point(in.nextInt(),in.nextInt()));
			}
			BinaryPoints tree = new BinaryPoints();
			while(!queue.isEmpty()){
				Point p = queue.poll(); 
				if(x1<=p.x && p.x<=x2 && y1<=p.y && p.y<=y2) tree.add(p.y);
			}
			System.out.println(100L*((x2-x1)+(y2-y1))+(5*Math.PI-20)*tree.max);

		}else if(x1>x2){
			PriorityQueue<Point> queue = new PriorityQueue<>(
					(a,b)->((Point)b).x-((Point)a).x
			);
			for (int i = 0; i < N; i++) {
				queue.add(new Point(in.nextInt(),in.nextInt()));
			}
			BinaryPoints tree = new BinaryPoints();
			while(!queue.isEmpty()){
				Point p = queue.poll(); 
				if(x2<=p.x && p.x<=x1 && y1<=p.y && p.y<=y2) tree.add(p.y);
			}
			System.out.println(100L*((x1-x2)+(y2-y1))+(5*Math.PI-20)*tree.max);
		}
	}

	public static void main(String[] args) {
		new Main().solve();
	}
}

class BinaryPoints{
	ArrayList<Point> points;
	int max;

	public BinaryPoints(){
		points = new ArrayList<Point>();
		points.add(new Point(-1,0));
		max = 0;
	}

	public void add(int y){
		int index = bSerch(y,0,points.size());
		int count = points.get(index).y + 1;
		points.add(index+1, new Point(y,count));
		max = Math.max(max, count);
	}

	public int bSerch(int y,int left,int right){
		if(left+1>=right) return left;
		if(points.get((left+right)/2).x < y){
			return bSerch(y,(left+right)/2+1,right);
		}else{
			return bSerch(y,left,(left+right)/2);
		}
	}
}

