		result = prime * result + v1;
		result = prime * result + v2;
		return result;
	}
	@Override
	public boolean equals(Object obj) {
		if (this == obj)
			return true;
		if (obj == null)
			return false;
		if (getClass() != obj.getClass())
			return false;
		Pair other = (Pair) obj;
		if (v1 != other.v1)
			return false;
		if (v2 != other.v2)
			return false;
		return true;
	}

	@Override
	public int compareTo(Pair arg0) {
		return getSortKey() - arg0.getSortKey();
	}

}




