/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskC solver = new TaskC();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskC {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            double x1 = in.nextInt();
            double y1 = in.nextInt();
            double x2 = in.nextInt();
            double y2 = in.nextInt();

            double maxX = Math.max(x1, x2);
            double minX = Math.min(x1, x2);
            double maxY = Math.max(y1, y2);
            double minY = Math.min(y1, y2);

            int n = in.nextInt();
            if (x1 == x2) {
                int count = 0;
                for (int i = 0; i < n; i++) {
                    int x = in.nextInt();
                    int y = in.nextInt();

                    if (x == x1 && minY < y && y < maxY) {
                        count++;
                    }
                }

                double ans = (maxY - minY) * 100 + Math.PI * 10 * count;
                out.println(ans);
                return;
            }

            if (y1 == y2) {
                int count = 0;
                for (int i = 0; i < n; i++) {
                    int x = in.nextInt();
                    int y = in.nextInt();

                    if (y == y1 && minX < x && x < maxX) {
                        count++;
                    }
                }

                double ans = (maxX - minX) * 100 + Math.PI * 10 * count;
                out.println(ans);
                return;
            }

            boolean flg = (x2 - x1) * (y2 - y1) < 0;

            List<Point> points = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                int x = in.nextInt();
                int y = in.nextInt();

                if (minX < x && x < maxX && minY < y && y < maxY) {
                    points.add(new Point(x, y));
                }
            }
            points.sort((p1, p2) -> {
                int compareX = Double.compare(p1.x, p2.x);
                return compareX != 0 ? compareX : Double.compare(p2.y, p1.y);
            });

            int[] array = new int[points.size()];
            for (int i = 0; i < points.size(); i++) {
                array[i] = (flg ? -1 : 1) * (int) points.get(i).y;
            }

            int len = array.length == 0 ? 0 : Lis.getLis(array).length;
            double ans = 100 * (maxY - minY + maxX - minX) + len * (2 * Math.PI * 10 / 4 - 20);

            out.println(ans);
        }

    }

    static class Point {
        public double x;
        public double y;

        public Point(double x, double y) {
            this.x = x;
            this.y = y;
        }

    }

    static class Lis {
        public static int[] getLis(int[] x) {
            int n = x.length;
            int[] len = new int[n];
            Arrays.fill(len, 1);
            int[] pred = new int[n];
            Arrays.fill(pred, -1);
            int bi = 0;
            for (int i = 1; i < n; i++) {
                for (int j = 0; j < i; j++) {
                    if (x[j] < x[i] && len[i] < len[j] + 1) {
                        len[i] = len[j] + 1;
                        pred[i] = j;
                    }
                }
                if (len[bi] < len[i]) {
                    bi = i;
                }
            }
            int cnt = len[bi];
            int[] res = new int[cnt];
            for (int i = bi; i != -1; i = pred[i]) {
                res[--cnt] = x[i];
            }
            return res;
        }

    }

    static class InputReader {
        BufferedReader in;
        StringTokenizer tok;

        public String nextString() {
            while (!tok.hasMoreTokens()) {
                try {
                    tok = new StringTokenizer(in.readLine(), " ");
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
            }
            return tok.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(nextString());
        }

        public InputReader(InputStream inputStream) {
            in = new BufferedReader(new InputStreamReader(inputStream));
            tok = new StringTokenizer("");
        }

    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.Comparator;

import template.Pair;

public class Main {
	//噴水通過180度
	final double FH = 10 * Math.PI - 20;
	//噴水通過90度
	final double FQ = 5 * Math.PI - 20;

	public static long l=0,l2=0;
	public static void main(String[] args) throws IOException {
		l = System.currentTimeMillis();
		new Main().exec();
		l2 = System.currentTimeMillis();

	}

	public void exec() throws IOException {

		InputUtil in = new InputUtil();
		PrintWriter out = new PrintWriter(System.out);
		int x1 = (int)in.nextInt();
		int y1 = (int)in.nextInt();
		int x2 = (int)in.nextInt();
		int y2 = (int)in.nextInt();
		int N = (int)in.nextInt();

		if(x2 < x1){
			int t=x1; x1=x2; x2=t;
			t=y1; y1=y2; y2=t;
		}
		boolean fRevY = (y2 < y1);
		int dirX=x2-x1;
		int dirY=fRevY?(y1-y2):(y2-y1);

		int[] FX = new int[N];
		int[] FY = new int[N];
		Integer[] F = new Integer[N];
		int index=0;
		for(int i=0; i<N; i++) {
			int x = in.nextInt();
			int y = in.nextInt();
			if(checkBetween(x1,x2,x,false) 
					&& checkBetween(y1,y2,y,fRevY)) {
				FX[index] = x;
				FY[index] = y;
				F[index] = index;
				index++;
			}
		}
		double dir = (long)(dirX+dirY)*100;
		if ( (dirX==0 || dirY==0) && index>0 ){
			dir += FH;
		}else if (index>0) {
			F = Arrays.copyOf(F, index);
			Arrays.sort(F,new Comparator<Integer>(){
				@Override
				public int compare(Integer o1, Integer o2) {
					return FX[o1.intValue()]-FX[o2.intValue()];
				}
			});
			int max = getLongestIncreasingSequence(F,FY,index,Integer.MIN_VALUE,fRevY);

			if(max == Math.min(dirX+1, dirY+1)) {
				dir += FQ * (max-1) + FH;
			} else {
				dir += FQ * max;
			}
		}
		out.printf("%.12f\n",dir);
		out.flush();
	}

	boolean checkBetween(int v1, int v2, int vc, boolean reverse) {
		if(!reverse)
			return (v1 <= vc && vc <= v2);
		else
			return (v2 <= vc && vc <= v1);
	}

	int getLongestIncreasingSequence(Integer[] F, int[] FY, int len, int minValue, boolean reverse) {
		int maxPath = 0;
		int[] maxSeq = new int[len];
		Arrays.fill(maxSeq,minValue);
		for(int i=0; i<len; i++) {
			int y = FY[F[i]];
			if(maxPath == 0){
				maxSeq[0] = y;
				maxPath = 1;
			} else {
				int insIdx = binarySearch(maxSeq, 0, maxPath, y, reverse);
				maxSeq[insIdx] = y;
				if(maxPath==insIdx) maxPath ++;
			}
		}
		return maxPath;
	}

	int binarySearch(int S[], int from, int to, int search, boolean reverse) {
		if(!reverse) {
			while (from + 1 < to) {
				int mid = (from + to)/2;
				if (search > S[mid-1])
					from = mid;
				else
					to = mid;
			}
			return (search > S[from])?(from+1):from;
		} else {
			while (from + 1 < to) {
				int mid = (from + to)/2;
				if (search < S[mid-1])
					from = mid;
				else
					to = mid;
			}
			return (search < S[from])?(from+1):from;
		}
    }
	int reverse(boolean rev,int xOrY) {
		return rev ? (99999999 - xOrY) : xOrY;
	}

}




