    void solve(){
        int[] s = new int[]{ni(), ni()};
        int[] g = new int[]{ni(), ni()};
        int minx= Math.min(s[0],g[0]);
        int maxx= Math.max(s[0],g[0]);
        int miny= Math.min(s[1],g[1]);
        int maxy= Math.max(s[1],g[1]);
        int n = ni();
        int[][] m = new int[n][2];
        for(int i = 0; i < n; i++){
            m[i][0] = ni();
            m[i][1] = ni();
        }
        Arrays.sort(m, (a,b)-> a[0]-b[0]);
        int res = 0;
        for(int i = 0; i < n; i++){
            if(m[i][0]>=minx&&m[i][0]<=maxx&&m[i][1]>=miny&&m[i][1]<=maxy){
                res++;
            }
        }
        int[] a1 = new int[res];
        int[] a2 = new int[res];
        int res2 = 0;
        for(int i = 0; i < n; i++){
            if(m[i][0]>=minx&&m[i][0]<=maxx&&m[i][1]>=miny&&m[i][1]<=maxy){
                a1[res2] = m[i][1];
                a2[res2] = m[i][1];
                res2++;
            }
        }
        Arrays.sort(a2);
        HashMap<Integer,Integer> map = new HashMap<>();
        for(int i = 0; i < res; i++){
            map.put(a2[i],i);
        }
