	}

	public int lis(int[] list){
		int[] dp = new int[list.length];
		Arrays.fill(dp, Integer.MAX_VALUE);
		for (int h : list) {
			int index = -Arrays.binarySearch(dp, h)-1;
			dp[index] = h;
		}
		return -Arrays.binarySearch(dp,Integer.MAX_VALUE-1)-1;
	}
}

