/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskC solver = new TaskC();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskC {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int x1 = in.nextInt();
            int y1 = in.nextInt();
            int x2 = in.nextInt();
            int y2 = in.nextInt();

            int maxX = Math.max(x1, x2);
            int minX = Math.min(x1, x2);
            int maxY = Math.max(y1, y2);
            int minY = Math.min(y1, y2);

            int n = in.nextInt();
            if (x1 == x2) {
                int count = 0;
                for (int i = 0; i < n; i++) {
                    int x = in.nextInt();
                    int y = in.nextInt();

                    if (x == x1 && minY < y && y < maxY) {
                        count++;
                    }
                }

                double ans = (maxY - minY) * 100 + Math.PI * 10 * count;
                out.println(ans);
                return;
            }

            if (y1 == y2) {
                int count = 0;
                for (int i = 0; i < n; i++) {
                    int x = in.nextInt();
                    int y = in.nextInt();

                    if (y == y1 && minX < x && x < maxX) {
                        count++;
                    }
                }

                double ans = (maxX - minX) * 100 + Math.PI * 10 * count;
                out.println(ans);
                return;
            }

            boolean flg = (x2 - x1) * (y2 - y1) < 0;

            List<Point> points = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                int x = in.nextInt();
                int y = in.nextInt();

                if (minX < x && x < maxX && minY < y && y < maxY) {
                    points.add(new Point(x, y));
                }
            }
            Collections.sort(points, (p1, p2) -> {
                int compareX = Double.compare(p1.x, p2.x);
                return compareX != 0 ? compareX : Double.compare(p2.y, p1.y);
            });

            int[] array = new int[points.size()];
            for (int i = 0; i < points.size(); i++) {
                array[i] = (flg ? -1 : 1) * (int) points.get(i).y;
            }

            int len = Lis.getLis(array).length;
            double ans = 100 * (maxY - minY + maxX - minX) + len * (2 * Math.PI * 10 / 4 - 20);

            out.println(ans);
        }

    }

    static class Point {
        public double x;
        public double y;

        public Point(double x, double y) {
            this.x = x;
            this.y = y;
        }

    }

    static class Lis {
        public static int[] getLis(int[] x) {
            int n = x.length;
            int[] len = new int[n];
            Arrays.fill(len, 1);
            int[] pred = new int[n];
            Arrays.fill(pred, -1);
            int bi = 0;
            for (int i = 1; i < n; i++) {
                for (int j = 0; j < i; j++) {
                    if (x[j] < x[i] && len[i] < len[j] + 1) {
                        len[i] = len[j] + 1;
                        pred[i] = j;
                    }
                }
                if (len[bi] < len[i]) {
                    bi = i;
                }
            }
            int cnt = len[bi];
            int[] res = new int[cnt];
            for (int i = bi; i != -1; i = pred[i]) {
                res[--cnt] = x[i];
            }
            return res;
        }

    }

    static class InputReader {
        BufferedReader in;
        StringTokenizer tok;

        public String nextString() {
            while (!tok.hasMoreTokens()) {
                try {
                    tok = new StringTokenizer(in.readLine(), " ");
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
            }
            return tok.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(nextString());
        }

        public InputReader(InputStream inputStream) {
            in = new BufferedReader(new InputStreamReader(inputStream));
            tok = new StringTokenizer("");
        }

    }
}

import java.util.Arrays;
import java.util.Comparator;
import java.util.Scanner;

class Main {
	public static void main(String[] args) {
		new Main().run();
	}

	void run() {
		Scanner sc = new Scanner(System.in);
		long[] p1 = { sc.nextLong(), sc.nextLong() };
		long[] p2 = { sc.nextLong(), sc.nextLong() };
		if (p1[0] > p2[0]) {
			long tmp = p1[0];
			p1[0] = p2[0];
			p2[0] = tmp;
			tmp = p1[1];
			p1[1] = p2[1];
			p2[1] = tmp;
		}
		int coe = 1;
		if (p1[1] > p2[1]) {
			coe = -1;
			p1[1] *= coe;
			p2[1] *= coe;
		}
		int n = sc.nextInt();
		long[][] p = new long[n][2];
		for (int i = 0; i < n; ++i) {
			p[i][0] = sc.nextLong();
			p[i][1] = sc.nextLong() * coe;
		}
		Arrays.sort(p, new Comparator<long[]>() {
			@Override
			public int compare(long[] o1, long[] o2) {
				return Long.compare(o1[0], o2[0]);
			}
		});
		int sz = 0;
		for (int i = 0; i < n; ++i) {
			if (p1[0] <= p[i][0] && p[i][0] <= p2[0] && p1[1] <= p[i][1] && p[i][1] <= p2[1])
				++sz;
		}
		long[] a = new long[sz];
		sz = 0;
		for (int i = 0; i < n; ++i) {
			if (p1[0] <= p[i][0] && p[i][0] <= p2[0] && p1[1] <= p[i][1] && p[i][1] <= p2[1]) {
				a[sz++] = p[i][1];
			}
		}
		long lis = LIS(a.length, a);
		double ans = (p2[0] - p1[0] + p2[1] - p1[1]) * 100 + (Math.PI * 5 - 20) * lis;
		if (lis == Math.min(p2[0] - p1[0] + 1, p2[1] - p1[1] + 1))
			ans += Math.PI * 5;
		System.out.println(String.format("%.20f", ans));
	}

	long LIS(int n, long[] a) {
		long[] f = new long[n];
		int sz = 0;
		for (int i = 0; i < n; ++i) {
			if (sz == 0) {
				f[sz] = a[0];
				++sz;
			} else {
				int ok = -1;
				int ng = sz;
				while (ng - ok > 1) {
					int middle = (ok + ng) / 2;
					if (f[middle] < a[i]) {
						ok = middle;
					} else {
						ng = middle;
					}
				}

				f[ok + 1] = a[i];
				if (ok + 1 == sz)
					++sz;
			}
		}
		return sz;
	}

	void tr(Object... objects) {
		System.out.println(Arrays.deepToString(objects));
	}
}

import java.io.OutputStream;
