			int count=0;
			for(int i=0;i<n;i++) {
				int x=sc.nextInt();
				int y=sc.nextInt();
				if(x==x1 && between(y1,y2,y)) {
					count++;
				}
			}
			System.out.println(100*Math.abs(y2-y1)+(10*Math.PI-20)*count);
		} else if(y1==y2) {
			int count=0;
			for(int i=0;i<n;i++) {
