import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int x1 = in.nextInt();
        int y1 = in.nextInt();
        int x2 = in.nextInt();
        int y2 = in.nextInt();
        int n = in.nextInt();
        int[][] fountains = new int[n][2];
        for (int i = 0; i < n ; i++) {
            for (int j = 0; j < 2 ; j++) {
                fountains[i][j] = in.nextInt();
            }
        }
        int minX = Math.min(x1, x2);
        int maxX = Math.max(x1, x2);
        int minY = Math.min(y1, y2);
        int maxY = Math.max(y1, y2);

        List<int[]> availablefountains = new ArrayList<>();
        for (int i = 0 ; i < n ; i++) {
            if (minX <= fountains[i][0] && fountains[i][0] <= maxX) {
                if (minY <= fountains[i][1] && fountains[i][1] <= maxY) {
                    availablefountains.add(new int[]{ Math.abs(x1-fountains[i][0]), Math.abs(y1-fountains[i][1])});
                }
            }
        }

        out.println(String.format("%.15f", solve(maxX-minX, maxY-minY, availablefountains)));
        out.flush();
    }

    static final double HALF = 20 * Math.PI / 2;
    static final double QUARTER = HALF / 2;
    static final double CORNER = 20;
    static final double HALF_LOSS = HALF - CORNER;
    static final double QUARTER_GAIN = QUARTER - CORNER;
    static final double LATTICE_SIZE = 100;

    private static double solve(int W, int H, List<int[]> fountains) {
        int n = fountains.size();
        Collections.sort(fountains, (u, v) ->  u[0] - v[0]);

        int[] a = new int[n];
        for (int i = 0; i < n ; i++) {
            a[i] = fountains.get(i)[1];
        }

        int x = lis(a);

        double base = (W + H) * LATTICE_SIZE;
        if (x == Math.min(W, H) + 1) {
            if (x == 1) {
                return base + HALF_LOSS;
            }
            return base + Math.min((x - 1) * QUARTER_GAIN + HALF_LOSS, (x - 2) * QUARTER_GAIN);
        }
        return base + x * QUARTER_GAIN;
    }

    /**
     * Computes longest increasing sequence.
     * If you want to get actual sequence, see dp[1..ans].
     * <p>
     * O(nlogn)
     *
     * @param values
     * @return
     */
    public static int lis(int[] values) {
        int n = values.length;
        long[] lval = new long[n];
        for (int i = 0; i < values.length; i++) {
            lval[i] = values[i] * 1000000000L + i;
        }
        int ans = 0;
        long[] dp = new long[n + 1];
        Arrays.fill(dp, Long.MIN_VALUE);
        for (int i = 0; i < n; i++) {
            int idx = Arrays.binarySearch(dp, 0, ans + 1, lval[i]);
            if (idx < 0) {
                idx = -idx - 2;
                dp[idx + 1] = lval[i];
                if (idx >= ans) {
                    ans++;
                }
            }
        }
        return ans;
    }


    public static void debug(Object... o) {
        System.err.println(Arrays.deepToString(o));
    }

    public static class InputReader {
        private static final int BUFFER_LENGTH = 1 << 12;
        private InputStream stream;
        private byte[] buf = new byte[BUFFER_LENGTH];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int next() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public char nextChar() {
            return (char) skipWhileSpace();
        }

        public String nextToken() {
            int c = skipWhileSpace();
            StringBuilder res = new StringBuilder();
            do {
                res.append((char) c);
                c = next();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public int nextInt() {
            return (int) nextLong();
        }

        public long nextLong() {
            int c = skipWhileSpace();
            long sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = next();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = next();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public double nextDouble() {
            return Double.valueOf(nextToken());
        }

        int skipWhileSpace() {
            int c = next();
            while (isSpaceChar(c)) {
                c = next();
            }
            return c;
        }

        boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.Comparator;
import java.util.InputMismatchException;

public class Main {
	static InputStream is;
	static PrintWriter out;
	static String INPUT = "";

	static void solve()
	{
		int r1 = ni(), c1 = ni(), r2 = ni(), c2 = ni();
		if(r1 > r2){
			{int r = r1; r1 = r2; r2 = r;}
			{int r = c1; c1 = c2; c2 = r;}
		}
		int n = ni();
		int[][] co = new int[n][];
		for(int i = 0;i < n;i++){
			co[i] = new int[]{ni(), ni()};
		}
		if(c1 > c2){
			c1 = 100000000-c1;
			c2 = 100000000-c2;
			for(int i = 0;i < n;i++){
				co[i][1] = 100000000-co[i][1];
			}
		}
		assert r1 <= r2;
		assert c1 <= c2;
		if(r1 == r2){
			int f = 0;
			for(int i = 0;i < n;i++){
				if(co[i][0] == r1 && c1 <= co[i][1] && co[i][1] <= c2){
					f++;
				}
			}
			out.printf("%.14f\n", (double)(c2-c1)*100+f*(-20+Math.PI*10));
			return;
		}
		if(c1 == c2){
			int f = 0;
			for(int i = 0;i < n;i++){
				if(co[i][1] == c1 && r1 <= co[i][0] && co[i][0] <= r2){
					f++;
				}
			}
			out.printf("%.14f\n", (double)(r2-r1)*100+f*(-20+Math.PI*10));
			return;
		}
		int[][] vs = new int[n][];
		int p = 0;
		for(int i = 0;i < n;i++){
			if(r1 <= co[i][0] && co[i][0] <= r2 &&
					c1 <= co[i][1] &&
					co[i][1] <= c2){
				vs[p++] = co[i];
			}
		}
		vs = Arrays.copyOf(vs, p);
		Arrays.sort(vs, new Comparator<int[]>() {
			public int compare(int[] a, int[] b) {
				return a[0] - b[0];
			}
		});
		int[] a = new int[p];
		for(int i = 0;i < p;i++)a[i] = vs[i][1];
		int lis = lis(a);
		if(lis == Math.min(r2-r1+1, c2-c1+1)){
			out.printf("%.14f\n", (double)(r2-r1+c2-c1)*100 + lis*(-20+5*Math.PI)+Math.PI*5);
		}else{
			out.printf("%.14f\n", (double)(r2-r1+c2-c1)*100 + lis*(-20+5*Math.PI));
		}
	}

	public static int lis(int[] in)
	{
		int n = in.length;
		int ret = 0;
		int[] h = new int[n + 1];
		Arrays.fill(h, Integer.MIN_VALUE / 2);
		for(int i = 0;i < n;i++){
			int ind = Arrays.binarySearch(h, 0, ret + 1, in[i]);
			if(ind < 0){
				ind = -ind-2;
				h[ind+1] = in[i];
				if(ind >= ret)ret++;
			}
		}
		return ret;
	}


	public static void main(String[] args) throws Exception
	{
		long S = System.currentTimeMillis();
		is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
		out = new PrintWriter(System.out);

		solve();
		out.flush();
		long G = System.currentTimeMillis();
		tr(G-S+"ms");
	}

	private static boolean eof()
	{
		if(lenbuf == -1)return true;
		int lptr = ptrbuf;
		while(lptr < lenbuf)if(!isSpaceChar(inbuf[lptr++]))return false;

		try {
			is.mark(1000);
			while(true){
				int b = is.read();
				if(b == -1){
					is.reset();
					return true;
				}else if(!isSpaceChar(b)){
					is.reset();
					return false;
				}
			}
		} catch (IOException e) {
			return true;
		}
	}

	private static byte[] inbuf = new byte[1024];
	static int lenbuf = 0, ptrbuf = 0;

	private static int readByte()
	{
		if(lenbuf == -1)throw new InputMismatchException();
		if(ptrbuf >= lenbuf){
			ptrbuf = 0;
			try { lenbuf = is.read(inbuf); } catch (IOException e) { throw new InputMismatchException(); }
			if(lenbuf <= 0)return -1;
		}
		return inbuf[ptrbuf++];
	}

	private static boolean isSpaceChar(int c) { return !(c >= 33 && c <= 126); }
//	private static boolean isSpaceChar(int c) { return !(c >= 32 && c <= 126); }
	private static int skip() { int b; while((b = readByte()) != -1 && isSpaceChar(b)); return b; }

	private static double nd() { return Double.parseDouble(ns()); }
	private static char nc() { return (char)skip(); }

	private static String ns()
	{
		int b = skip();
		StringBuilder sb = new StringBuilder();
		while(!(isSpaceChar(b))){
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}

	private static char[] ns(int n)
	{
		char[] buf = new char[n];
		int b = skip(), p = 0;
		while(p < n && !(isSpaceChar(b))){
			buf[p++] = (char)b;
			b = readByte();
		}
		return n == p ? buf : Arrays.copyOf(buf, p);
	}

	private static char[][] nm(int n, int m)
	{
		char[][] map = new char[n][];
		for(int i = 0;i < n;i++)map[i] = ns(m);
		return map;
	}

	private static int[] na(int n)
	{
		int[] a = new int[n];
		for(int i = 0;i < n;i++)a[i] = ni();
		return a;
	}

	private static int ni()
	{
		int num = 0, b;
		boolean minus = false;
		while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
		if(b == '-'){
			minus = true;
			b = readByte();
		}

		while(true){
			if(b >= '0' && b <= '9'){
				num = num * 10 + (b - '0');
			}else{
				return minus ? -num : num;
			}
			b = readByte();
		}
	}

	private static long nl()
	{
		long num = 0;
		int b;
		boolean minus = false;
		while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
		if(b == '-'){
			minus = true;
			b = readByte();
		}

		while(true){
			if(b >= '0' && b <= '9'){
				num = num * 10 + (b - '0');
			}else{
				return minus ? -num : num;
			}
			b = readByte();
		}
	}

	private static void tr(Object... o) { if(INPUT.length() != 0)System.out.println(Arrays.deepToString(o)); }
}

import java.util.Arrays;
import java.util.Comparator;
import java.util.Scanner;

class Main {
	public static void main(String[] args) {
		new Main().run();
	}

	void run() {
		Scanner sc = new Scanner(System.in);
		long[] p1 = { sc.nextLong(), sc.nextLong() };
		long[] p2 = { sc.nextLong(), sc.nextLong() };
		if (p1[0] > p2[0]) {
			long[] tmp = p1;
			p1 = p2;
			p2 = tmp;
		}
		int coe = 1;
		if (p1[1] > p2[1]) {
			coe = -1;
			p1[1] *= coe;
			p2[1] *= coe;
		}
		int n = sc.nextInt();
		long[][] p = new long[n][2];
		for (int i = 0; i < n; ++i) {
			p[i][0] = sc.nextLong() * coe;
			p[i][1] = sc.nextLong() * coe;
		}
		Arrays.sort(p, new Comparator<long[]>() {
			@Override
			public int compare(long[] o1, long[] o2) {
				return Long.compare(o1[0], o2[0]);
			}
		});
		int sz = 0;
		for (int i = 0; i < n; ++i) {
			if (p1[0] <= p[i][0] && p[i][0] <= p2[0] && p1[1] <= p[i][1] && p[i][1] <= p2[1])
				++sz;
		}
		long[] a = new long[sz];
		sz = 0;
		for (int i = 0; i < n; ++i) {
			if (p1[0] <= p[i][0] && p[i][0] <= p2[0] && p1[1] <= p[i][1] && p[i][1] <= p2[1]) {
				a[sz++] = p[i][1];
			}
		}
		long lis = LIS(a.length, a);
		double ans = (p2[0] - p1[0]) * 100 + (p2[1] - p1[1]) * 100 + (Math.PI / 2 * 10 - 20) * lis;
		if (lis == Math.min(p2[0] - p1[0] + 1, p2[1] - p1[1] + 1))
			ans += Math.PI / 2 * 10;
		System.out.println(String.format("%.20f", ans));
	}

	long LIS(int n, long[] a) {
		long[] f = new long[n];
		int sz = 0;
		for (int i = 0; i < n; ++i) {
			if (sz == 0) {
				f[sz] = a[0];
				++sz;
			} else {

				int ok = -1;
				int ng = sz;
				while (ng - ok > 1) {
					int middle = (ok + ng) / 2;
					if (f[middle] < a[i]) {
						ok = middle;
					} else {
						ng = middle;
					}
				}

				f[ok + 1] = a[i];
				if (ok + 1 == sz)
					++sz;
			}
		}
		return sz;
	}

	void tr(Object... objects) {
		System.out.println(Arrays.deepToString(objects));
	}
}

