    }

    static final double HALF = 20 * Math.PI / 2;
    static final double QUARTER = HALF / 2;
    static final double CORNER = 20;
    static final double HALF_LOSS = HALF - CORNER;
    static final double QUARTER_GAIN = QUARTER - CORNER;
    static final double LATTICE_SIZE = 100;

    private static double solve(int W, int H, List<int[]> fountains) {
        int n = fountains.size();
        Collections.sort(fountains, (u, v) ->  u[0] - v[0]);

        int[] a = new int[n];
        for (int i = 0; i < n ; i++) {
            a[i] = fountains.get(i)[1];
        }

        int x = lis(a);

        double base = (W + H) * LATTICE_SIZE;
        if (x == Math.min(W, H) + 1) {
            if (x == 1) {
                return base + HALF_LOSS;
            }
            return base + (x - 1) * QUARTER_GAIN + HALF_LOSS;
        }
        return base + x * QUARTER_GAIN;
    }

    /**
     * Computes longest increasing sequence.
     * If you want to get actual sequence, see dp[1..ans].
     * <p>
     * O(nlogn)
     *
     * @param values
     * @return
     */
    public static int lis(int[] values) {
        int n = values.length;
        long[] lval = new long[n];
        for (int i = 0; i < values.length; i++) {
            lval[i] = values[i] * 1000000000L + i;
        }
        int ans = 0;
        long[] dp = new long[n + 1];
        Arrays.fill(dp, Long.MIN_VALUE);
        for (int i = 0; i < n; i++) {
            int idx = Arrays.binarySearch(dp, 0, ans + 1, lval[i]);
            if (idx < 0) {
                idx = -idx - 2;
                dp[idx + 1] = lval[i];
                if (idx >= ans) {
                    ans++;
                }
            }
        }
        return ans;
    }


    public static void debug(Object... o) {
        System.err.println(Arrays.deepToString(o));
    }

    public static class InputReader {
        private static final int BUFFER_LENGTH = 1 << 12;
        private InputStream stream;
        private byte[] buf = new byte[BUFFER_LENGTH];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int next() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public char nextChar() {
            return (char) skipWhileSpace();
        }

        public String nextToken() {
            int c = skipWhileSpace();
            StringBuilder res = new StringBuilder();
            do {
                res.append((char) c);
                c = next();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public int nextInt() {
            return (int) nextLong();
        }

        public long nextLong() {
            int c = skipWhileSpace();
            long sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = next();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = next();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public double nextDouble() {
            return Double.valueOf(nextToken());
        }

        int skipWhileSpace() {
            int c = next();
            while (isSpaceChar(c)) {
                c = next();
            }
            return c;
        }

        boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.util.Arrays;
import java.util.function.Predicate;

public class Main {

  private static void solve() {
    int[] sg = na(4);
    int maxX = Math.max(sg[0], sg[2]);
    int minX = Math.min(sg[0], sg[2]);
    int maxY = Math.max(sg[1], sg[3]);
    int minY = Math.min(sg[1], sg[3]);
    int flg = sg[1] > sg[3] ? -1 : 1;

    int n = ni();
    int[][] p = ntable(n, 2);
    Arrays.sort(p, (o1, o2) -> o1[0] == o2[0] ? o1[1] - o2[1] : o1[0] - o2[0]);
    Predicate<int[]> pred = v -> minX <= v[0] && v[0] <= maxX && minY <= v[1] && v[1] <= maxX;
    int[] y = Arrays.stream(p).filter(pred).mapToInt(v -> v[1] * flg).toArray();
    int ball = lis(y);

    double total = ((maxX - minX) + (maxY - minY)) * 100.0;
    double arg1 = 20.0 - Math.PI * 5.0;
    double arg2 = Math.PI * 10.0 - 20.0;

    int lenMin = Math.min(maxX - minX, maxY - minY);
    if (lenMin <= ball - 1) {
      out.printf("%.13f\n", total - arg1 * lenMin + arg2);
    } else {
      out.printf("%.13f\n", total - arg1 * ball);
    }
  }

  public static int lis(int[] in)
  {
      int n = in.length;
      int ret = 0;
      int[] h = new int[n + 1];
      Arrays.fill(h, Integer.MIN_VALUE / 2);
      for(int i = 0;i < n;i++){
          int ind = Arrays.binarySearch(h, 0, ret + 1, in[i]);
          if(ind < 0){
              ind = -ind-2;
              h[ind+1] = in[i];
              if(ind >= ret)ret++;
          }
      }
      return ret;
  }

  public static void main(String[] args) {
    new Thread(null, new Runnable() {
      @Override
      public void run() {
        long start = System.currentTimeMillis();
        String debug = System.getProperty("debug");
        if (debug != null) {
          try {
            is = java.nio.file.Files.newInputStream(java.nio.file.Paths.get(debug));
          } catch (Exception e) {
            throw new RuntimeException(e);
          }
        }
        reader = new java.io.BufferedReader(new java.io.InputStreamReader(is), 32768);
        solve();
        out.flush();
        tr((System.currentTimeMillis() - start) + "ms");
      }
    }, "", 64000000).start();
  }

  private static java.io.InputStream is = System.in;
  private static java.io.PrintWriter out = new java.io.PrintWriter(System.out);
  private static java.util.StringTokenizer tokenizer = null;
  private static java.io.BufferedReader reader;

  public static String next() {
    while (tokenizer == null || !tokenizer.hasMoreTokens()) {
      try {
        tokenizer = new java.util.StringTokenizer(reader.readLine());
      } catch (Exception e) {
        throw new RuntimeException(e);
      }
    }
    return tokenizer.nextToken();
  }

  private static double nd() {
    return Double.parseDouble(next());
  }

  private static long nl() {
    return Long.parseLong(next());
  }

  private static int[] na(int n) {
    int[] a = new int[n];
    for (int i = 0; i < n; i++)
      a[i] = ni();
    return a;
  }

  private static char[] ns() {
    return next().toCharArray();
  }

  private static long[] nal(int n) {
    long[] a = new long[n];
    for (int i = 0; i < n; i++)
      a[i] = ni();
    return a;
  }

  private static int[][] ntable(int n, int m) {
    int[][] table = new int[n][m];
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < m; j++) {
        table[i][j] = ni();
      }
    }
    return table;
  }

  private static int[][] nlist(int n, int m) {
    int[][] table = new int[m][n];
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < m; j++) {
        table[j][i] = ni();
      }
    }
    return table;
  }

  private static int ni() {
