    for (int[] v : p) {
      if (s[0] <= v[0] && v[0] <= g[0] && Math.min(s[1], g[1]) <= v[1]
          && v[1] <= Math.max(s[1], g[1])) {
        a[ptr++] = v[1];
      }
    }
    a = Arrays.copyOf(a, ptr);

    // sx <= gx
    double ret;

    if (s[1] == g[1] || s[0] == g[0]) {
      ret = (Math.abs(s[0] - g[0]) + Math.abs(s[1] - g[1])) * 100.0;
      ret += a.length * (20 * Math.PI / 2 - 10.0 * 2);
