/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author amotoma3
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskC solver = new TaskC();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskC {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int x1 = in.nextInt();
            int y1 = in.nextInt();
            int x2 = in.nextInt();
            int y2 = in.nextInt();

            if (x1 > x2) {
                int tmp;

                tmp = x1;
                x1 = x2;
                x2 = tmp;

                tmp = y1;
                y1 = y2;
                y2 = tmp;
            }

            int sign = y1 < y2 ? 1 : -1;
            y1 *= sign;
            y2 *= sign;

            int n = in.nextInt();
            TreeMap<Integer, Integer> map = new TreeMap<>();
            for (int i = 0; i < n; i++) {
                int x = in.nextInt();
                int y = sign * in.nextInt();

                if (x1 <= x && x <= x2 && y1 <= y && y <= y2) {
                    map.put(x, y);
                }
            }

            int[] lis = IntStream.generate(() -> (int) 1e9).limit(map.size()).toArray();
            for (int x : map.values()) {
                int index = ArrayUtils.lowerBound(lis, x);
                lis[index] = x;
            }
            int len = ArrayUtils.lowerBound(lis, (int) 1e9);

            if (len == Math.min(x2 - x1, y2 - y1) + 1) {
                out.println(100 * (x2 - x1 + y2 - y1) + (20 * Math.PI / 4 - 20) * (len - 1) + 20 * Math.PI / 2 - 20);
            } else {
                out.println(100 * (x2 - x1 + y2 - y1) + (20 * Math.PI / 4 - 20) * len);
            }
        }

    }

    static class InputReader {
        BufferedReader in;
        StringTokenizer tok;

        public String nextString() {
            while (!tok.hasMoreTokens()) {
                try {
                    tok = new StringTokenizer(in.readLine(), " ");
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
            }
            return tok.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(nextString());
        }

        public InputReader(InputStream inputStream) {
            in = new BufferedReader(new InputStreamReader(inputStream));
            tok = new StringTokenizer("");
        }

    }

    static class ArrayUtils {
        public static int lowerBound(int[] a, int x) {
            int high = a.length;
            int low = -1;
            while (high - low > 1) {
                int mid = (high + low) / 2;
                if (a[mid] < x) {
                    low = mid;
                } else {
                    high = mid;
                }
            }
            return high;
        }

    }
}

import java.io.*;
import java.util.*;

public class Main {
    private FastScanner in;
    private PrintWriter out;

    class Rat {
        long a, b;

        public Rat(long a, long b) {
            this.a = a;
            this.b = b;
            good();
        }

        Rat add(Rat an) {
            return new Rat(an.a * b + a * an.b, an.b * b);
        }

        Rat mul(Rat o) {
            return new Rat(a * o.a, b * o.b);
        }

        void good() {
            long g = gcd(a, b);
            a /= g;
            b /= g;
        }

        @Override
        public String toString() {
            String res = a + "/" + b;
            while (res.length() < 10) {
                res += " ";
            }
            return res;
        }
    }

    long gcd(long x, long y) {
        return x == 0 ? y : gcd(y % x, x);
    }

    class Point implements Comparable<Point> {
        int x, y;

        public Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        public Point() {
            x = in.nextInt();
            y = in.nextInt();
        }

        @Override
        public int compareTo(Point o) {
            return Integer.compare(x, o.y);
        }
    }

    void solve() {
        Point from = new Point();
        Point to = new Point();
        int n = in.nextInt();
        Point[] a = new Point[n];
        for (int i = 0; i < n; i++) {
            a[i] = new Point();
        }
        if (from.x > to.x) {
            from.x = -from.x;
            to.x = -to.x;
            for (Point p : a) {
                p.x = -p.x;
            }
        }
        if (from.y > to.y) {
            from.y = -from.y;
            to.y = -to.y;
            for (Point p : a) {
                p.y = -p.y;
            }
        }
        double q = Math.PI * 5;
        double len = 100.0 * (to.x - from.x + to.y - from.y);
        if (from.x == to.x || from.y == to.y) {
            boolean have = false;
            for (Point p : a) {
                if (p.x >= from.x && p.x <= to.x && p.y >= from.y && p.y <= to.y) {
                    have = true;
                }
            }
            if (have) {
                len -= 20;
                len += 2 * q;
            }
            out.println(len);
            return;
        }
        Arrays.sort(a);
        ArrayList<Integer> all = new ArrayList<>();
        for (Point p : a) {
            if (p.x >= from.x && p.x <= to.x && p.y >= from.y && p.y <= to.y) {
                all.add(p.y);
            }
        }
        int cnt = getMax(all);
        len -= 20 * cnt;
        len += q * cnt;
        out.println(len);
    }

    int getMax(ArrayList<Integer> all) {
        int n = all.size();
        int[] d = new int[n + 1];
        Arrays.fill(d, Integer.MAX_VALUE);
        d[0] = Integer.MIN_VALUE;

        for (int i=0; i<n; i++) {
            int l = 0, r = n;
            while (r - l > 1) {
                int mid = (l + r) >> 1;
                if (d[mid] >= all.get(i)) {
                    r = mid;
                } else {
                    l = mid;
                }
            }
            d[r] =Math.min(d[r], all.get(i));
        }
        for (int res = n; res >= 0; res--) {
            if (d[res] !=Integer.MAX_VALUE) {
                return res;
            }
        }
        return -1;
    }

