			}
		Collections.sort(arr);
		int [] a=new int [arr.size()];
		for(int i=0;i<a.length;i++)
			a[i]=arr.get(i).y;
		int l=lis(a, a.length);
		if(minX!=maxX && minY!=maxY){			
			if(l==maxY-minY+1)
				l--;
			dis=Math.min(dis, init-l*(20-circ/4));
		}
		pw.println(dis);
