import java.util.Arrays;



public class Main {

  private static void solve() {
    int x1 = ni();
    int y1 = ni();
    int x2 = ni();
    int y2 = ni();
    int N = ni();
    int[][] p = new int[N + 2][3];
    p[0] = new int[]{x1, y1, 1};
    p[N + 1] = new int[]{x2, y2, 2};
    for (int i = 1; i <= N; i++) {
      p[i] = new int[] {ni(), ni(), 0};
    }

    Arrays.sort(p, (o1, o2) -> o1[0] - o2[0]);

    int sgPtr = 0;
    int[] sg = new int[2];
    for (int i = 0; i < N + 2; i ++) {
      if (p[i][2] > 0) {
        sg[sgPtr ++] = i;
        if (sgPtr == 2) break;
      }
    }
    Arrays.sort(sg);
    int start = sg[0];
    int goal = sg[1];

    int[] x = new int[N + 2];
    int[] y = new int[N + 2];
    for (int i = 0; i < N + 2; i ++) {
      x[i] = p[i][0];
      y[i] = p[i][1];
    }

    y = shrink(y);

    double ret;
    if (y[start] == y[goal]) {
      boolean flg = false;
      for (int i = 0; i < N + 2; i ++) {
        if (i != start && i != goal && p[start][0] < p[i][0] && p[i][0] < p[goal][0]) {
          flg = true;
          break;
        }
      }
      ret = Math.abs(x1 - x2) * 100.0 + (flg ? Math.PI * 10 - 20 : 0);
    } else if (p[start][0] == p[goal][0]) {
      boolean flg = false;
      for (int i = 0; i < N + 2; i ++) {
        if (i != start && i != goal && p[start][1] < p[i][1] && p[i][1] < p[goal][1]) {
          flg = true;
          break;
        }
      }
      ret = Math.abs(y1 - y2) * 100.0 + (flg ? Math.PI * 10 - 20 : 0);

    } else  {
      if (y[start] > y[goal]) {
        for (int i = 0; i < N + 2; i ++) {
          y[i] = N + 1 - y[i];
        }
      }

      int inf = Integer.MAX_VALUE / 2;
      SegmentTreeRMQ st = new SegmentTreeRMQ(N + 2);
      st.update(y[start], inf);
      for (int i = start + 1; i < goal; i ++) {
        int max = inf - st.min(0, y[i]);
        st.update(y[i], inf - (max + 1));
      }
      int max = inf - st.min(0, y[goal]);
      double rad = Math.PI * 5 - 20;
      ret = Math.abs(x1 - x2) * 100.0 + Math.abs(y1 - y2) * 100.0 + rad * max;
    }
    System.out.printf("%.13f\n", ret);

  }

  public static int[] shrink(int[] a)
  {
      int n = a.length;
      long[] b = new long[n];
      for(int i = 0;i < n;i++)b[i] = (long)a[i]<<32|i;
      Arrays.sort(b);
      int[] ret = new int[n];
      int p = 0;
      for(int i = 0;i < n;i++) {
          if(i>0 && (b[i]^b[i-1])>>32!=0)p++;
          ret[(int)b[i]] = p;
      }
      return ret;
  }



