/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author amotoma3
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskC solver = new TaskC();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskC {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int x1 = in.nextInt();
            int y1 = in.nextInt();
            int x2 = in.nextInt();
            int y2 = in.nextInt();

            if (x1 > x2) {
                int tmp;

                tmp = x1;
                x1 = x2;
                x2 = tmp;

                tmp = y1;
                y1 = y2;
                y2 = tmp;
            }

            int sign = y1 < y2 ? 1 : -1;
            y1 *= sign;
            y2 *= sign;

            int n = in.nextInt();
            TreeMap<Integer, Integer> map = new TreeMap<>();
            for (int i = 0; i < n; i++) {
                int x = in.nextInt();
                int y = sign * in.nextInt();

                if (x1 <= x && x <= x2 && y1 <= y && y <= y2) {
                    map.put(x, y);
                }
            }

            int[] lis = IntStream.generate(() -> (int) 1e9).limit(map.size()).toArray();
            for (int x : map.values()) {
                int index = ArrayUtils.lowerBound(lis, x);
                lis[index] = x;
            }
            int len = ArrayUtils.lowerBound(lis, (int) 1e9);

            if (len == Math.min(x2 - x1, y2 - y1) + 1) {
                out.println(100 * (x2 - x1 + y2 - y1) + (20 * Math.PI / 4 - 20) * (len - 1) + 20 * Math.PI / 2 - 20);
            } else {
                out.println(100 * (x2 - x1 + y2 - y1) + (20 * Math.PI / 4 - 20) * len);
            }
        }

    }

    static class InputReader {
        BufferedReader in;
        StringTokenizer tok;

        public String nextString() {
            while (!tok.hasMoreTokens()) {
                try {
                    tok = new StringTokenizer(in.readLine(), " ");
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
            }
            return tok.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(nextString());
        }

        public InputReader(InputStream inputStream) {
            in = new BufferedReader(new InputStreamReader(inputStream));
            tok = new StringTokenizer("");
        }

    }

    static class ArrayUtils {
        public static int lowerBound(int[] a, int x) {
            int high = a.length;
            int low = -1;
            while (high - low > 1) {
                int mid = (high + low) / 2;
                if (a[mid] < x) {
                    low = mid;
                } else {
                    high = mid;
                }
            }
            return high;
        }

    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.TreeMap;
import java.util.TreeSet;

public class Main {
	//噴水通過180度
	final double FH = 10 * Math.PI - 20;
	//噴水通過90度
	final double FQ = 5 * Math.PI - 20;

	public static long l=0,l2=0;
	public static void main(String[] args) throws IOException {
		l = System.currentTimeMillis();
		new Main().exec();
		l2 = System.currentTimeMillis();

	}

	public void exec() throws IOException {

		InputUtil in = new InputUtil();
		PrintWriter out = new PrintWriter(System.out);
		int x1 = (int)in.nextInt();
		int y1 = (int)in.nextInt();
		int x2 = (int)in.nextInt();
		int y2 = (int)in.nextInt();
		int N = (int)in.nextInt();
		int dx = (x2 - x1>0)?1:-1;
		int dy = (y2 - y1>0)?1:-1;
		TreeMap<Integer,Integer> FXMap = new TreeMap<>();
		for(int i=0; i<N; i++) {
			int fx = in.nextInt();
			int fy = in.nextInt();
			if(checkBetween(x1,x2,fx) && checkBetween(y1,y2,fy)) {
				FXMap.put(fx,fy);
			}
		}
		Integer key = null;
		int max = 0;

		TreeMap<Integer,Integer> FYMap = new TreeMap<>();
		int[] FYMapArray = new int[N+1];

		while((key = nextEntry(FXMap,key,-dx)) != null){
			int count = 1;
			int y = FXMap.get(key);
			Integer nextY = nextEntry(FYMap,y,dy);
			if(nextY != null) {
				count += FYMap.get(nextY);
			}
			FYMap.put(y,count);
			if(FYMapArray[count] > 0) {
				FYMap.remove(FYMapArray[count]);
			}
			FYMapArray[count] = y;
			max = Math.max(max, count);
		}


		int dirX=(x2-x1)*dx;
		int dirY=(y2-y1)*dy;
		long base_dir = dirX + dirY;
		base_dir *= 100;
		double gosa = 0;
		if(x1==x2 || y1==y2){
			gosa += FH * max;
		} else {
			gosa += FQ * max;
			if(max == Math.min(dirX+1, dirY+1)) {
				gosa += FH - FQ;
			}
		}
		double dir = base_dir + gosa;
		out.printf("%.12f\n",dir);
		out.flush();
	}

	Integer nextEntry(TreeMap<Integer,Integer> FXMap, Integer key, int dir) {
		if(FXMap.isEmpty())
			return null;
		else if(dir == 1){
			if(key == null)
				return FXMap.firstKey();
			else  
				return FXMap.ceilingKey(key+1);
		}else{
			if(key == null)
				return FXMap.lastKey();
			else  
				return FXMap.floorKey(key-1);
		}
	}

	boolean checkBetween(int v1, int v2, int vc) {
		if(v1==v2){
			return v1==vc;
		}else if(v1>v2) {
			return (v2 <= vc && vc <= v1);
		} else {
			return (v1 <= vc && vc <= v2);
		}
	}

}




class InputUtil {
	//Static Fields
	private static final int BUFSIZ = 100000;

	//Fields
	protected InputStream in;
	private char[] buf = null;
	private int ptr = 0;
	private int max = -1;
	private BufferedReader br = null;

	//Constructors
	public InputUtil() {this(System.in,BUFSIZ);}
	public InputUtil(InputStream in, int bufsiz) {
		initBuf(bufsiz);
		initIn(in);
	}

	//Methods
	//Initializer
	protected void initIn(InputStream in) {br = new BufferedReader(new InputStreamReader(this.in = in));}
	protected void initBuf(int bufsiz) {buf = new char[bufsiz];}

	//buffer operation
	private void next() throws IOException {ptr++; readBuf();}
	private void readBuf() throws IOException {
		if(ptr >= max && br.ready()) {
			if(max>0) Arrays.fill(buf,0,max,(char)0);
			max = br.read(buf);
			ptr = 0;
		}
	}

	//Number Input Reader/Parser
	private boolean isNum(char b) {return '0' <= b && b <= '9'; }
	private boolean isMinus(char b) {return b=='-'; }

	private int _nextInt() throws IOException {
		int sign = 1;
		int res = 0;
		char c;
		while (!isNum(c=buf[ptr]) && !isMinus(c)) 
			next();
		if (isMinus(buf[ptr])) {
			sign = -1;
			next();
		}
		while (isNum(c=buf[ptr])) {
			res *= 10;
			res += c - '0' ;
			next();
		}
		next();
		return sign * res;
	}

	public int nextInt() throws IOException {
		readBuf();
		return _nextInt();
	}

	public int[] nextInt(int[] result) throws IOException {
		readBuf();
		for(int i=0; i<result.length; i++) {
			result[i] = _nextInt();
		}
		return result;
	}

	//Close 
	public void close() throws IOException {
		if(!this.in.equals(System.in)) 
			this.in.close();
	}

}

