public class Main {

	public static void main(String[] args) {
		StdIn in = new StdIn();
		int x1=in.nextInt(), y1=in.nextInt(), x2=in.nextInt(), y2=in.nextInt(), n=in.nextInt();
		if(x2<x1) {
			int temp=x1;
			x1=x2;
			x2=temp;
			temp=y1;
			y1=y2;
			y2=temp;
		}
		int minY=Math.min(y1, y2), maxY=Math.max(y1, y2);
		List<Point> ptsList = new ArrayList<Point>();
		for(int i=0; i<n; ++i) {
			int xi=in.nextInt(), yi=in.nextInt();
			if(xi<x1||xi>x2||yi<minY||yi>maxY)
				continue;
			ptsList.add(new Point(xi, yi));
		}
		if(ptsList.size()==0) {
			System.out.printf("%.12f\n", (x2-x1+Math.abs(y1-y2))*100.);
			return;
		}
		if(x1==x2||y1==y2) {
			System.out.printf("%.12f\n", (x2-x1+Math.abs(y1-y2))*100L+10*Math.PI-20);
			return;
		}
		ptsList.sort(new Comparator<Point>() {
			public int compare(Point a, Point b) {
				return a.x-b.x;
			}
		});
		int[] a = new int[ptsList.size()];
		int sign=y2-y1>0?1:-1;
		for(int i=0; i<a.length; ++i)
			a[i]=ptsList.get(i).y*sign;
		double t=(x2-x1+Math.abs(y1-y2))*100L+(5*Math.PI-20)*LongestIncreasingSubsequenceLength(a, a.length);
		boolean addExtra=true;
		for(int i=0; i<a.length-1; ++i) {
			if(a[i+1]-a[i]!=1) {
				addExtra=false;
				break;
			}
		}
		if(addExtra&&y1==sign*a[0]&&y2==sign*a[a.length-1])
			t+=Math.PI*5;
		System.out.printf("%.12f\n", t);
	}

	static int CeilIndex(int A[], int l, int r, int key)
    {
        while (r - l > 1)
        {
            int m = l + (r - l)/2;
            if (A[m]>=key)
                r = m;
            else
                l = m;
        }

        return r;
    }

    static int LongestIncreasingSubsequenceLength(int A[], int size)
    {
        // Add boundary case, when array size is one

        int[] tailTable   = new int[size];
        int len; // always points empty slot

        tailTable[0] = A[0];
        len = 1;
        for (int i = 1; i < size; i++)
        {
            if (A[i] < tailTable[0])
                // new smallest value
                tailTable[0] = A[i];

            else if (A[i] > tailTable[len-1])
                // A[i] wants to extend largest subsequence
                tailTable[len++] = A[i];

            else
                // A[i] wants to be current end candidate of an existing
                // subsequence. It will replace ceil value in tailTable
                tailTable[CeilIndex(tailTable, -1, len-1, A[i])] = A[i];
        }

        return len;
    }

	interface Input {
		public String next();
		public String nextLine();
		public int nextInt();
		public long nextLong();
		public double nextDouble();
	}
	static class StdIn implements Input {
		final private int BUFFER_SIZE = 1 << 16;
		private DataInputStream din;
		private byte[] buffer;
		private int bufferPointer, bytesRead;

		public StdIn() {
			din = new DataInputStream(System.in);
			buffer = new byte[BUFFER_SIZE];
			bufferPointer = bytesRead = 0;
		}

		public StdIn(String filename) {
			try{
				din = new DataInputStream(new FileInputStream(filename));
			} catch(Exception e) {
				throw new RuntimeException();
			}
			buffer = new byte[BUFFER_SIZE];
			bufferPointer = bytesRead = 0;
		}

		public String next() {
			int c;
			while((c=read())!=-1&&(c==' '||c=='\n'||c=='\r'));
			StringBuilder s = new StringBuilder();
			while (c != -1)
			{
				if (c == ' ' || c == '\n'||c=='\r')
					break;
				s.append((char)c);
				c=read();
			}
			return s.toString();
		}

		public String nextLine() {
			int c;
			while((c=read())!=-1&&(c==' '||c=='\n'||c=='\r'));
			StringBuilder s = new StringBuilder();
			while (c != -1)
			{
				if (c == '\n'||c=='\r')
					break;
				s.append((char)c);
				c = read();
			}
			return s.toString();
		}

		public int nextInt() {
			int ret = 0;
			byte c = read();
			while (c <= ' ')
				c = read();
			boolean neg = (c == '-');
			if (neg)
				c = read();
			do
			{
				ret = ret * 10 + c - '0';
			}  while ((c = read()) >= '0' && c <= '9');

			if (neg)
				return -ret;
			return ret;
		}

		public int[] readIntArray(int n) {
			int[] ar = new int[n];
			for(int i=0; i<n; ++i)
				ar[i]=nextInt();
			return ar;
		}

		public long nextLong() {
			long ret = 0;
			byte c = read();
			while (c <= ' ')
				c = read();
			boolean neg = (c == '-');
			if (neg)
				c = read();
			do {
				ret = ret * 10 + c - '0';
			}
			while ((c = read()) >= '0' && c <= '9');
			if (neg)
				return -ret;
			return ret;
		}

		public long[] readLongArray(int n) {
			long[] ar = new long[n];
			for(int i=0; i<n; ++i)
				ar[i]=nextLong();
			return ar;
		}

		public double nextDouble() {
			double ret = 0, div = 1;
			byte c = read();
			while (c <= ' ')
				c = read();
			boolean neg = (c == '-');
			if (neg)
				c = read();

			do {
				ret = ret * 10 + c - '0';
			}
			while ((c = read()) >= '0' && c <= '9');

			if (c == '.')
			{
				while ((c = read()) >= '0' && c <= '9')
				{
					ret += (c - '0') / (div *= 10);
				}
			}

			if (neg)
				return -ret;
			return ret;
		}

		private void fillBuffer() throws IOException {
			bytesRead = din.read(buffer, bufferPointer = 0, BUFFER_SIZE);
			if (bytesRead == -1)
				buffer[0] = -1;
		}

		private byte read() {
			try{
				if (bufferPointer == bytesRead)
					fillBuffer();
				return buffer[bufferPointer++];
			} catch(IOException e) {
				throw new RuntimeException();
			}
		}

		public void close() throws IOException {
			if (din == null)
				return;
			din.close();
		}
	}
}

import java.util.Arrays;



public class Main {

  private static void solve() {
    int x1 = ni();
    int y1 = ni();
    int x2 = ni();
    int y2 = ni();
    int N = ni();
    int[][] p = new int[N + 2][3];
    p[0] = new int[]{x1, y1, 1};
    p[N + 1] = new int[]{x2, y2, 2};
    for (int i = 1; i <= N; i++) {
      p[i] = new int[] {ni(), ni(), 0};
    }

    Arrays.sort(p, (o1, o2) -> o1[0] == o2[0] ? o1[1] - o2[1] : o1[0] - o2[0]);

    int sgPtr = 0;
    int[] sg = new int[2];
    for (int i = 0; i < N + 2; i ++) {
      if (p[i][2] > 0) {
        sg[sgPtr ++] = i;
        if (sgPtr == 2) break;
      }
    }
    Arrays.sort(sg);
    int start = sg[0];
    int goal = sg[1];

    int[] x = new int[N + 2];
    int[] y = new int[N + 2];
    for (int i = 0; i < N + 2; i ++) {
      x[i] = p[i][0];
      y[i] = p[i][1];
    }

    y = shrink(y);
    x = shrink(y);
    if (y[start] > y[goal]) {
      for (int i = 0; i < N + 2; i ++) {
        y[i] = N + 1 - y[i];
      }
    }

    int shFlg = -1;
    int ghFlg = -1;
    int svFlg = -1;
    int gvFlg = -1;
    for (int i = 0; i < N + 2; i ++) {
      if (i != start && i != goal) {
        if (p[start][0] < p[i][0] && p[i][0] < p[goal][0]) {
          if (p[start][1] == p[i][1]) shFlg = i;
          if (p[goal][1] == p[i][1]) ghFlg = i;
        }
        if (y[start] < y[i] && y[i] < y[goal]) {
          if (p[start][0] == p[i][0]) svFlg = i;
          if (p[goal][0] == p[i][0]) gvFlg = i;

        }
      }
    }


    double ret;
    if (y[start] == y[goal]) {
      boolean flg = shFlg >= 0 || ghFlg >= 0;
      ret = Math.abs(x1 - x2) * 100.0 + (flg ? Math.PI * 10 - 20 : 0);
    } else if (p[start][0] == p[goal][0]) {
      boolean flg = svFlg >= 0 || gvFlg >= 0;
      ret = Math.abs(y1 - y2) * 100.0 + (flg ? Math.PI * 10 - 20 : 0);

    } else  {


      int inf = Integer.MAX_VALUE / 2;
      SegmentTreeRMQ st = new SegmentTreeRMQ(N + 2);
      st.update(y[start], inf);
      for (int i = start + 1; i < goal; i ++) {
        int max = inf - st.min(0, y[i]);
        st.update(y[i], inf - (max + 1));
      }
      int max = inf - st.min(0, y[goal]);
      double rad = Math.PI * 5 - 20;
      ret = Math.abs(x1 - x2) * 100.0 + Math.abs(y1 - y2) * 100.0 + rad * max;
    }
    System.out.printf("%.13f\n", ret);

  }

  public static int[] shrink(int[] a)
  {
      int n = a.length;
      long[] b = new long[n];
      for(int i = 0;i < n;i++)b[i] = (long)a[i]<<32|i;
      Arrays.sort(b);
      int[] ret = new int[n];
      int p = 0;
      for(int i = 0;i < n;i++) {
          if(i>0 && (b[i]^b[i-1])>>32!=0)p++;
          ret[(int)b[i]] = p;
      }
      return ret;
  }



