class Compress {
  public final Map<Integer, Integer> zip = new HashMap<>();;
  public final long[] unzip;
  public final int[] list;

  public Compress(int[] src) {
      int n = src.length;
      int[] tmp = Arrays.copyOf(src, n);
      Arrays.sort(tmp);

      unzip = new long[n];
      int index = 0;
      for (int i = 0; i < n; i ++) {
        int v = tmp[i];
          if (!zip.containsKey(v)) {
              zip.put(v, index ++);
              unzip[i] = v;
          }
      }

      list = new int[n];
      for (int i = 0; i < n; i ++) {
          list[i] = zip.get(src[i]);
      }
  }
}
class SegmentTreeRMQ {
  public int M, H, N;
  public int[] st;

  public SegmentTreeRMQ(int n)
  {
      N = n;
      M = Integer.highestOneBit(Math.max(N-1, 1))<<2;
      H = M>>>1;
      st = new int[M];
      Arrays.fill(st, 0, M, -1);
  }

  public SegmentTreeRMQ(int[] a)
  {
      N = a.length;
      M = Integer.highestOneBit(Math.max(N-1, 1))<<2;
      H = M>>>1;
      st = new int[M];
      for(int i = 0;i < N;i++){
          st[H+i] = a[i];
      }
      Arrays.fill(st, H+N, M, Integer.MAX_VALUE);
      for(int i = H-1;i >= 1;i--)propagate(i);
  }

  public void update(int pos, int x)
  {
      st[H+pos] = x;
      for(int i = (H+pos)>>>1;i >= 1;i >>>= 1)propagate(i);
  }

  private void propagate(int i)
  {
      st[i] = Math.min(st[2*i], st[2*i+1]);
  }

  public int minx(int l, int r){
      int min = Integer.MAX_VALUE;
      if(l >= r)return min;
      while(l != 0){
          int f = l&-l;
          if(l+f > r)break;
          int v = st[(H+l)/f];
          if(v < min)min = v;
          l += f;
      }

      while(l < r){
          int f = r&-r;
          int v = st[(H+r)/f-1];
          if(v < min)min = v;
          r -= f;
      }
      return min;
  }

  public int min(int l, int r){ return l >= r ? 0 : min(l, r, 0, H, 1);}

  private int min(int l, int r, int cl, int cr, int cur)
  {
      if(l <= cl && cr <= r){
          return st[cur];
      }else{
          int mid = cl+cr>>>1;
          int ret = Integer.MAX_VALUE;
          if(cl < r && l < mid){
              ret = Math.min(ret, min(l, r, cl, mid, 2*cur));
          }
          if(mid < r && l < cr){
              ret = Math.min(ret, min(l, r, mid, cr, 2*cur+1));
          }
          return ret;
      }
  }

  public int firstle(int l, int v) {
      int cur = H+l;
      while(true){
          if(st[cur] <= v){
              if(cur < H){
                  cur = 2*cur;
              }else{
                  return cur-H;
              }
          }else{
              cur++;
              if((cur&cur-1) == 0)return -1;
              if((cur&1)==0)cur>>>=1;
          }
      }
  }

  public int lastle(int l, int v) {
      int cur = H+l;
      while(true){
          if(st[cur] <= v){
              if(cur < H){
                  cur = 2*cur+1;
              }else{
                  return cur-H;
              }
          }else{
              if((cur&cur-1) == 0)return -1;
              cur--;
              if((cur&1)==1)cur>>>=1;
          }
      }
  }
}

import java.util.*;
import java.util.stream.Collectors;
import java.io.*;

public class Main {

	int MAX = 100_000_000;

	class Point {
		int x, y;

		public Point(int x, int y) {
			this.x = x;
			this.y = y;
		}

		@Override
		public String toString() {
			return "Point [x=" + x + ", y=" + y + "]";
		}

	}

	void solve() {
		List<Point> pts = new ArrayList<>();
		pts.add(new Point(in.nextInt(), in.nextInt()));
		pts.add(new Point(in.nextInt(), in.nextInt()));
		int n = in.nextInt();
		for (int i = 0; i < n; i++) {
			pts.add(new Point(in.nextInt(), in.nextInt()));
		}

		Point start = pts.get(0);
		Point finish = pts.get(1);
		if (start.x > finish.x) {
			for (Point p : pts) {
				p.x = MAX - 1 - p.x;
			}
		}
		if (start.y > finish.y) {
			for (Point p : pts) {
				p.y = MAX - 1 - p.y;
			}
		}

		if (start.x == finish.x) {
			double result = 100.0 * (finish.y - start.y);
			for (Point p : pts) {
				if (p.x == start.x && start.y < p.y && p.y < finish.y) {
					result += Math.PI * 10 - 20;
					break;
				}
			}
			out.println(result);
			return;
		}

		if (start.y == finish.y) {
			double result = 100.0 * (finish.x - start.x);
			for (Point p : pts) {
				if (p.y == start.y && start.x < p.x && p.x < finish.x) {
					result += Math.PI * 10 - 20;
					break;
				}
			}
			out.println(result);
			return;
		}
		double result = 100.0 * (finish.x + finish.y - start.x - start.y);
		pts = pts.stream().filter(p -> start.x <= p.x && p.x <= finish.x && start.y <= p.y && p.y <= finish.y)
				.collect(Collectors.toList());
		n = pts.size();
		int[] x = new int[n], y = new int[n];
		for (int i = 0; i < n; i++) {
			x[i] = pts.get(i).x;
			y[i] = pts.get(i).y;
		}
		x = removeDupes(x);
		y = removeDupes(y);
		for (int i = 0; i < n; i++) {
			pts.get(i).x = Arrays.binarySearch(x, pts.get(i).x);
			pts.get(i).y = Arrays.binarySearch(y, pts.get(i).y);
		}

		Collections.sort(pts, (o1, o2) -> {
			if (o1.x != o2.x) {
				return o1.x - o2.x;
			}
			return o1.y - o2.y;
		});

		SegmentTree tree = new SegmentTree(y.length + 1);
		if (pts.get(1).x == start.x) {
			tree.set(0, 0);
		} else {
			tree.updateMax(0, y.length, 0);
		}

		for (int i = 1; i < pts.size() - 1; i++) {
			double down = tree.get(0, pts.get(i).y - 1);
			double same = tree.get(pts.get(i).y, pts.get(i).y);
			{ // update same
				double cur1 = down + (20 - 5 * Math.PI);
				double cur2 = same + (20 - 10 * Math.PI);
				tree.set(pts.get(i).y, Math.max(cur1, cur2));
			}
			{ // update up
				double cur1 = same + 20 - 5 * Math.PI;
				double cur2 = down + 20 - 10 * Math.PI;
				tree.updateMax(pts.get(i).y + 1, y.length, Math.max(cur1, cur2));
			}
		}

		result -= tree.get(finish.y, finish.y);
		out.println(result);
	}

	int[] removeDupes(int[] x) {
		Arrays.sort(x);
		int cnt = 0;
		for (int i = 0; i < x.length; i++) {
			if (i == 0 || x[i] > x[i - 1]) {
				cnt++;
			}
		}
		int[] result = new int[cnt];
		for (int i = 0, j = 0; i < x.length; i++) {
			if (i == 0 || x[i] > x[i - 1]) {
				result[j++] = x[i];
			}
		}
		return result;
	}

	double INF = Integer.MIN_VALUE;

	class SegmentTree {
		double[] max;
		double[] push;
		int size;

		public SegmentTree(int n) {
			max = new double[4 * n];
			push = new double[4 * n];
			size = n;
			Arrays.fill(max, INF);
			Arrays.fill(push, INF);
		}

		void set(int pos, double val) {
			set(0, size, pos, val, 0);
		}

		void set(int l, int r, int pos, double val, int i) {
			if (l + 1 == r) {
				max[i] = val;
				return;
			}
			push(i);
			int m = (l + r) >> 1;
			if (pos < m) {
				set(l, m, pos, val, 2 * i + 1);
			} else {
				set(m, r, pos, val, 2 * i + 2);
			}
			refresh(i);
		}

		double get(int l, int r) {
			return get(0, size, l, r + 1, 0);
		}

		double get(int l, int r, int left, int right, int i) {
			if (left <= l && r <= right) {
				return max[i];
			} else if (right <= l || r <= left) {
				return INF;
			} else {
				push(i);
				int m = (l + r) >> 1;
				double ret = Math.max(get(l, m, left, right, 2 * i + 1), get(m, r, left, right, 2 * i + 2));
				refresh(i);
				return ret;
			}
		}

		void updateMax(int from, int to, double val) {
			updateMax(0, size, from, to + 1, val, 0);
		}

		void push(int i) {
			if (push[i] != INF) {
				updateOne(2 * i + 1, push[i]);
				updateOne(2 * i + 2, push[i]);
				push[i] = INF;
			}
		}

		void updateOne(int i, double value) {
			max[i] = Math.max(max[i], value);
			push[i] = Math.max(push[i], value);
		}

		void refresh(int i) {
			max[i] = Math.max(max[2 * i + 1], max[2 * i + 2]);
		}

		void updateMax(int l, int r, int left, int right, double value, int i) {
			if (left <= l && r <= right) {
				updateOne(i, value);
			} else if (right <= l || r <= left) {
				return;
			} else {
				push(i);
				int m = (l + r) >> 1;
				updateMax(l, m, left, right, value, 2 * i + 1);
				updateMax(m, r, left, right, value, 2 * i + 2);
				refresh(i);
			}
		}
	}

	FastScanner in;
	PrintWriter out;

	void run() {
		in = new FastScanner();
		out = new PrintWriter(System.out);
		solve();
		out.close();
	}

	class FastScanner {
		BufferedReader br;
		StringTokenizer st;

		public FastScanner() {
			br = new BufferedReader(new InputStreamReader(System.in));
