public class Main{
	static IntStream REPS(int v){return IntStream.range(0,v);}
	static IntStream REPS(int l,int r){return IntStream.rangeClosed(l,r);}
	static IntStream INS(int n) {return REPS(n).map(i->getInt());}
	static Scanner s=new Scanner(System.in);
	static int getInt(){return Integer.parseInt(s.next());}

	public static void main(String[]$){
		Point st=new Point(getInt(),getInt()),go=new Point(getInt(),getInt());
		if(st.x==go.x) {
			for(int i=getInt();i>0;--i) {
				if(getInt()==st.x) {
					long y=getInt();
					if((st.y-y)*(go.y-y)<0) {
						ko(st,go);
						return;
					}
					break;
				}
			}
			System.out.println(m(st,go));
			return;
		}
		if(st.y==go.y) {
			for(int i=getInt();i>0;--i) {
				long x=getInt();
				if((st.x-x)*(go.x-x)<0) {
					if(getInt()==st.y) {
						ko(st,go);
						return;
					}
					break;
				}
			}
			System.out.println(m(st,go));
			return;
		}
		if(st.y>go.y) {
			Point buf=go;
			go=st;
			st=buf;
		}
		TreeSet<Point>p=
				st.x<go.x?
				new TreeSet<>(Comparator.comparingDouble(Point::getX)):
				new TreeSet<>(Comparator.comparingDouble(Point::getX).reversed());

		TreeMap<Integer,Integer> res=new TreeMap<>();
		for(int i=getInt();i>0;--i) {
			int x=getInt(),y=getInt();
			if(st.y<=y&&y<=go.y)
				p.add(new Point(x,y));
		}
		res.put(st.y-1,0);
		for(Point e:p.subSet(st,true,go,true))
			res.put(e.y,res.floorEntry(e.y).getValue()+1);
		int v=res.values().stream().mapToInt(i->i).max().getAsInt();
		int d=Math.min(go.y-st.y,Math.abs(go.x-st.x));
		System.out.println(
				m(st,go)
				+Math.min(v,d)*5*Math.PI
				+Math.min(v,d)*-20
				+v==d?10*Math.PI:0
				);
	}
	static void ko(Point st,Point go){
		System.out.println(m(st,go)+11.41592653589794);
	}
	static long m(Point st,Point go){
		return (Math.abs(st.x-go.x)+Math.abs(st.y-go.y))*100;
	}
}

import java.util.*;
import java.util.stream.Collectors;
import java.io.*;

public class Main {

	int MAX = 100_000_000;

	class Point {
		int x, y;

		public Point(int x, int y) {
			this.x = x;
			this.y = y;
		}

		@Override
		public String toString() {
			return "Point [x=" + x + ", y=" + y + "]";
		}


	}

	void solve() {
		List<Point> pts = new ArrayList<>();
		pts.add(new Point(in.nextInt(), in.nextInt()));
		pts.add(new Point(in.nextInt(), in.nextInt()));
		int n = in.nextInt();
		for (int i = 0; i < n; i++) {
			pts.add(new Point(in.nextInt(), in.nextInt()));
		}

		Point start = pts.get(0);
		Point finish = pts.get(1);
		if (start.x > finish.x) {
			for (Point p : pts) {
				p.x = MAX - 1 - p.x;
			}
		}
		if (start.y > finish.y) {
			for (Point p : pts) {
				p.y = MAX - 1 - p.y;
			}
		}

		if (start.x == finish.x) {
			double result = 100.0 * (finish.y - start.y);
			for (Point p : pts) {
				if (p.x == start.x && start.y < p.y && p.y < finish.y) {
					result += Math.PI * 10 - 20;
					break;
				}
			}
			out.println(result);
			return;
		}

		if (start.y == finish.y) {
			double result = 100.0 * (finish.x - start.x);
			for (Point p : pts) {
				if (p.y == start.y && start.x < p.x && p.x < finish.x) {
					result += Math.PI * 10 - 20;
					break;
				}
			}
			out.println(result);
			return;
		}
		double result = 100.0 * (finish.x + finish.y - start.x - start.y);
		pts = pts.stream().filter(p -> start.x <= p.x && p.x <= finish.x && start.y <= p.y && p.y <= finish.y)
				.collect(Collectors.toList());
		n = pts.size();
		int[] x = new int[n], y = new int[n];
		for (int i = 0; i < n; i++) {
			x[i] = pts.get(i).x;
			y[i] = pts.get(i).y;
		}
		x = removeDupes(x);
		y = removeDupes(y);
		for (int i = 0; i < n; i++) {
			pts.get(i).x = Arrays.binarySearch(x, pts.get(i).x);
			pts.get(i).y = Arrays.binarySearch(y, pts.get(i).y);
		}

		Collections.sort(pts, (o1, o2) -> {
			if (o1.x != o2.x) {
				return o1.x - o2.x;
			}
			return o1.y - o2.y;
		});

		SegmentTree tree = new SegmentTree(y.length);
		Point postFirst = pts.get(1);
		if (postFirst.x == start.x) {
			for (int i = 0; i < postFirst.y; i++) {
				tree.set(i, 0);
			}
			tree.set(postFirst.y, 20 - 5 * Math.PI);
			for (int i = postFirst.y + 1; i < y.length; i++) {
				tree.set(i, 20 - 10 * Math.PI);
			}

		} else {
			for (int i = 0; i < y.length; i++) {
				tree.set(i, 0);
			}
		}

		for (int i = 0; i < pts.size() - 1; i++) {
			if (pts.get(i).x == start.x || pts.get(i).x == finish.x) {
				continue;
			}
			double cur1 = tree.get(0, pts.get(i).y - 1) + (20 - 5 * Math.PI);
			double cur2 = tree.get(pts.get(i).y, pts.get(i).y) + (20 - 10 * Math.PI);
			tree.set(pts.get(i).y, Math.max(cur1, cur2));
		}

		Point preLast = pts.get(pts.size() - 2);
		if (preLast.x == finish.x) {
			double best = INF;
			best = Math.max(best, tree.get(0, preLast.y - 1) + 20 - 10 * Math.PI);
			best = Math.max(best, tree.get(preLast.y, preLast.y) + 20 - 5 * Math.PI);
			best = Math.max(best, tree.get(preLast.y + 1, finish.y));
			result -= best;
		} else {
			result -= tree.get(0, finish.y);
		}
		out.println(result);
	}

	int[] removeDupes(int[] x) {
		Arrays.sort(x);
		int cnt = 0;
		for (int i = 0; i < x.length; i++) {
			if (i == 0 || x[i] > x[i - 1]) {
				cnt++;
			}
		}
		int[] result = new int[cnt];
		for (int i = 0, j =0; i < x.length; i++) {
			if (i == 0 || x[i] > x[i - 1]) {
				result[j++] = x[i];
			}
		}
		return result;
	}

	double INF = Integer.MIN_VALUE;

	class SegmentTree {
		double[] max;
		int size;
		public SegmentTree(int n) {
			max = new double[4 * n];
			size = n;
			Arrays.fill(max, INF);
		}

		void set(int pos, double val) {
			set(0, size, pos, val, 0);
		}
		void set(int l, int r, int pos, double val, int i) {
			if (l + 1 == r) {
				max[i] = val;
				return;
			}
			int m = (l + r) >>> 1;
			if (pos < m) {
				set(l, m, pos, val, 2 * i + 1);
			} else {
				set(m, r, pos, val, 2 * i + 2);
			}
			max[i] = Math.max(max[2 * i + 1], max[2 * i + 2]);
		}
		double get(int l, int r) {
			return get(0, size, l, r + 1, 0);
		}

		double get(int l, int r, int left, int right, int i) {
			if (left <= l && r <= right) {
				return max[i];
			} else if (right <= l || r <= left) {
				return INF;
			} else {
				int m = (l + r) >> 1;
				return Math.max(get(l, m, left, right, 2 * i + 1), get(m, r, left, right, 2 * i + 2));
			}
		}
	}

	FastScanner in;
	PrintWriter out;

	void run() {
		in = new FastScanner();
		out = new PrintWriter(System.out);
		solve();
		out.close();
	}

