			double ans = 100.00 * (Math.abs(a - c) + Math.abs(b - d));

			if(a > c) {
				int temp = b;
				b = d;
				d = temp;
				temp = a;
				a = c;
				c = temp;
			}
			if(a == c) {
				int cnt = 0;
				for(int i = 0; i < n; i++) {
					if(a <= x[i] && x[i] <= c) {
						if(Math.min(b, d) <= y[i] && y[i] <= Math.max(b, d)) {
							++cnt;
						}
					}
				}
				if(cnt > 0) {
					ans += 10.0 * (PI - 2);
				}
				System.out.printf("%.10f\n", ans);
				System.exit(0);
			}
			if(b == d) {
				int cnt = 0;
				for(int i = 0; i < n; i++) {
					if(a <= x[i] && x[i] <= c) {
						if(Math.min(b, d) <= y[i] && y[i] <= Math.max(b, d)) {
							++cnt;
						}
					}
				}
				if(cnt > 0) {
					ans += 10.0 * (PI - 2);
				}
				System.out.printf("%.10f\n", ans);
				System.exit(0);
			}
			ArrayList <Pair> rel = new ArrayList <> ();
			for(int i = 0; i < n; i++) {
				if(a <= x[i] && x[i] <= c) {
					if(Math.min(b, d) <= y[i] && y[i] <= Math.max(b, d)) {
						rel.add(new Pair(x[i], y[i]));
					}
				}
			}
			Collections.sort(rel, new Pair());

			System.out.println(new Pair(a, b));
			System.out.println(new Pair(c, d));

			arr = new ArrayList <> ();
			for(Pair i : rel) {
				int var;
				if(b < d) var = i.second - b;
				else var = d - i.second;
				arr.add(var);
			}
			int lcs = 0;
			for(int i = 0; i < arr.size(); i++) {
				dp[i] = 1;
				for(int j = 0; j < i; j++) {
					if(arr.get(j) < arr.get(i)) {
						dp[i] = Math.max(dp[i], 1 + dp[j]);
					}
				}
				lcs = Math.max(lcs, dp[i]);
			} 
			ans += 10.0 * lcs * ((PI / 2.0) - 2);
			System.out.printf("%.10f\n", ans);
