/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        MyInput in = new MyInput(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskC solver = new TaskC();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskC {
        public void solve(int testNumber, MyInput in, PrintWriter out) {
            int x1 = in.nextInt();
            int y1 = in.nextInt();
            int x2 = in.nextInt();
            int y2 = in.nextInt();
            int sx = 1, sy = 1;

            if (x1 > x2) {
                x1 = -x1;
                x2 = -x2;
                sx = -1;
            }
            if (y1 > y2) {
                y1 = -y1;
                y2 = -y2;
                sy = -1;
            }

            int n = in.nextInt();
            int[][] pos = new int[n][];
            int len = 0;
            for (int i = 0; i < n; i++) {
                int x = sx * in.nextInt();
                int y = sy * in.nextInt();
                if (x >= x1 && x <= x2 && y >= y1 && y <= y2) {
                    pos[len++] = new int[]{x, y,};
                }
            }
            pos = Arrays.copyOf(pos, len);
            Arrays.sort(pos, (a, b) -> a[0] - b[0]);
            n = len;
            int[] ys = new int[n];
            for (int i = 0; i < n; i++) ys[i] = pos[i][1];
            int lis = LIS(ys);
            double r = 10;
            double gain = Math.PI * r / 2 - r * 2;
            double penalty = Math.PI * r - r * 2;
            double ans = 100.0 * (y2 - y1 + x2 - x1) + lis * gain;
            if (lis == Math.min(x2 - x1, y2 - y1) + 1) {
                ans += penalty - gain;
            }
            out.printf("%.15f\n", ans);

        }

        private static int LIS(int[] ys) {
            final int n = ys.length;
            final int[] res = new int[n];
            Arrays.fill(res, Integer.MAX_VALUE);
            for (int i = 0; i < n; i++) {
                res[lowerBound(res, ys[i])] = ys[i];
            }
            return lowerBound(res, Integer.MAX_VALUE);
        }

        private static int lowerBound(final int[] xs, final int x) {
            int low = 0, high = xs.length;
            while (low < high) {
                final int mid = (low + high) / 2;
                final int cmp = xs[mid] < x ? -1 : xs[mid] == x ? 0 : 1;
                if (cmp >= 0) high = mid;
                else low = mid + 1;
            }
            return low;
        }

    }

    static class MyInput {
        private final BufferedReader in;
        private static int pos;
        private static int readLen;
        private static final char[] buffer = new char[1024 * 8];
        private static char[] str = new char[500 * 8 * 2];
        private static boolean[] isDigit = new boolean[256];
        private static boolean[] isSpace = new boolean[256];
        private static boolean[] isLineSep = new boolean[256];

        static {
            for (int i = 0; i < 10; i++) {
                isDigit['0' + i] = true;
            }
            isDigit['-'] = true;
            isSpace[' '] = isSpace['\r'] = isSpace['\n'] = isSpace['\t'] = true;
            isLineSep['\r'] = isLineSep['\n'] = true;
        }

        public MyInput(InputStream is) {
            in = new BufferedReader(new InputStreamReader(is));
        }

        public int read() {
            if (pos >= readLen) {
                pos = 0;
                try {
                    readLen = in.read(buffer);
                } catch (IOException e) {
                    throw new RuntimeException();
                }
                if (readLen <= 0) {
                    throw new MyInput.EndOfFileRuntimeException();
                }
            }
            return buffer[pos++];
        }

        public int nextInt() {
            int len = 0;
            str[len++] = nextChar();
            len = reads(len, isSpace);
            int i = 0;
            int ret = 0;
            if (str[0] == '-') {
                i = 1;
            }
            for (; i < len; i++) ret = ret * 10 + str[i] - '0';
            if (str[0] == '-') {
                ret = -ret;
            }
            return ret;
        }

        public char nextChar() {
            while (true) {
                final int c = read();
                if (!isSpace[c]) {
                    return (char) c;
                }
            }
        }

        int reads(int len, boolean[] accept) {
            try {
                while (true) {
                    final int c = read();
                    if (accept[c]) {
                        break;
                    }
                    if (str.length == len) {
                        char[] rep = new char[str.length * 3 / 2];
                        System.arraycopy(str, 0, rep, 0, str.length);
                        str = rep;
                    }
                    str[len++] = (char) c;
                }
            } catch (MyInput.EndOfFileRuntimeException e) {
            }
            return len;
        }

        static class EndOfFileRuntimeException extends RuntimeException {
        }

    }
}

import java.util.Arrays;
import java.util.Comparator;
import java.util.Scanner;

class Main {
	public static void main(String[] args) {
		new Main().run();
	}

	void run() {
		Scanner sc = new Scanner(System.in);
		long[] p1 = { sc.nextLong(), sc.nextLong() };
		long[] p2 = { sc.nextLong(), sc.nextLong() };
		if (p1[0] > p2[0]) {
			long[] tmp = p1;
			p1 = p2;
			p2=tmp;
		}
		int coe = 1;
		if (p1[1] > p2[1]) {
			coe = -1;
			p1[1] *= coe;
			p2[1] *= coe;
		}
		int n = sc.nextInt();
		long[][] p = new long[n][2];
		for (int i = 0; i < n; ++i) {
			p[i][0] = sc.nextLong();
			p[i][1] = sc.nextLong() * coe;
		}
		Arrays.sort(p, new Comparator<long[]>() {
			@Override
			public int compare(long[] o1, long[] o2) {
				return Long.compare(o1[0], o2[0]);
			}
		});
		int sz = 0;
		for (int i = 0; i < n; ++i) {
			if (p1[0] <= p[i][0] && p[i][0] <= p2[0] && p1[1] <= p[i][1] && p[i][1] <= p2[1])
				++sz;
		}
		long[] a = new long[sz];
		sz = 0;
		for (int i = 0; i < n; ++i) {
			if (p1[0] <= p[i][0] && p[i][0] <= p2[0] && p1[1] <= p[i][1] && p[i][1] <= p2[1]) {
				a[sz++] = p[i][1];
			}
		}
		long lis = LIS(a.length, a);
		double ans = (p2[0] - p1[0] + p2[1] - p1[1]) * 100 + (Math.PI * 5 - 20) * lis;
		if (lis == Math.min(p2[0] - p1[0] + 1, p2[1] - p1[1] + 1))
			ans += Math.PI * 5;
		System.out.println(String.format("%.20f", ans));
	}

	long LIS(int n, long[] a) {
		long[] f = new long[n];
		int sz = 0;
		for (int i = 0; i < n; ++i) {
			if (sz == 0) {
				f[sz] = a[0];
				++sz;
			} else {
				int ok = -1;
				int ng = sz;
				while (ng - ok > 1) {
					int middle = (ok + ng) / 2;
					if (f[middle] < a[i]) {
						ok = middle;
					} else {
						ng = middle;
					}
				}

				f[ok + 1] = a[i];
				if (ok + 1 == sz)
					++sz;
			}
		}
		return sz;
	}

	void tr(Object... objects) {
		System.out.println(Arrays.deepToString(objects));
	}
}

import java.util.*;
import java.util.stream.Collectors;
import java.io.*;

public class Main {

	int MAX = 100_000_000;

	class Point {
		int x, y;

		public Point(int x, int y) {
			this.x = x;
			this.y = y;
		}

		@Override
		public String toString() {
			return "Point [x=" + x + ", y=" + y + "]";
		}

	}

	void solve() {
		List<Point> pts = new ArrayList<>();
		pts.add(new Point(in.nextInt(), in.nextInt()));
		pts.add(new Point(in.nextInt(), in.nextInt()));
		int n = in.nextInt();
		for (int i = 0; i < n; i++) {
			pts.add(new Point(in.nextInt(), in.nextInt()));
		}

		Point start = pts.get(0);
		Point finish = pts.get(1);
		if (start.x > finish.x) {
			for (Point p : pts) {
				p.x = MAX - 1 - p.x;
			}
		}
		if (start.y > finish.y) {
			for (Point p : pts) {
				p.y = MAX - 1 - p.y;
			}
		}

		double result = 100.0 * (0.0 + finish.x + finish.y - start.x - start.y);
		pts = pts.stream().filter(p -> start.x <= p.x && p.x <= finish.x && start.y <= p.y && p.y <= finish.y)
				.collect(Collectors.toList());
		n = pts.size();
		int[] x = new int[n], y = new int[n];
		for (int i = 0; i < n; i++) {
			x[i] = pts.get(i).x;
			y[i] = pts.get(i).y;
		}
		x = removeDupes(x);
		y = removeDupes(y);
		for (int i = 0; i < n; i++) {
			pts.get(i).x = Arrays.binarySearch(x, pts.get(i).x);
			pts.get(i).y = Arrays.binarySearch(y, pts.get(i).y);
		}

		Collections.sort(pts, (o1, o2) -> {
			if (o1.x != o2.x) {
				return o1.x - o2.x;
			}
			return o1.y - o2.y;
		});

		SegmentTree tree = new SegmentTree(y.length + 1);
		if (pts.get(1).x == start.x) {
			tree.set(0, 0);
		} else {
			tree.updateMax(0, y.length, 0);
		}

		for (int i = 1; i < pts.size() - 1; i++) {
			double down = tree.get(0, pts.get(i).y - 1);
			double same = tree.get(pts.get(i).y, pts.get(i).y);
			{ // update same
				double cur1 = down + (20 - 5 * Math.PI);
				double cur2 = same + (20 - 10 * Math.PI);
				tree.set(pts.get(i).y, Math.max(cur1, cur2));
			}
			{ // update up
				double cur1 = same + 20 - 5 * Math.PI;
				double cur2 = down + 20 - 10 * Math.PI;
				tree.updateMax(pts.get(i).y + 1, y.length, Math.max(cur1, cur2));
			}
		}

		result -= tree.get(finish.y, finish.y);
		out.println(result);
	}

	int[] removeDupes(int[] x) {
		Arrays.sort(x);
		int cnt = 0;
		for (int i = 0; i < x.length; i++) {
			if (i == 0 || x[i] > x[i - 1]) {
				cnt++;
			}
		}
		int[] result = new int[cnt];
		for (int i = 0, j = 0; i < x.length; i++) {
			if (i == 0 || x[i] != x[i - 1]) {
				result[j++] = x[i];
			}
		}
		return result;
	}

	double INF = Integer.MIN_VALUE;

	class SegmentTree {
		double[] max;
		double[] push;
		int size;

		public SegmentTree(int n) {
			max = new double[4 * n];
			push = new double[4 * n];
			size = n;
			Arrays.fill(max, INF);
			Arrays.fill(push, INF);
		}

		void set(int pos, double val) {
			set(0, size, pos, val, 0);
		}

		void set(int l, int r, int pos, double val, int i) {
			if (l + 1 == r) {
				max[i] = val;
				return;
			}
			push(i);
			int m = (l + r) >> 1;
			if (pos < m) {
				set(l, m, pos, val, 2 * i + 1);
			} else {
				set(m, r, pos, val, 2 * i + 2);
			}
			refresh(i);
		}

		double get(int l, int r) {
			return get(0, size, l, r + 1, 0);
		}

		double get(int l, int r, int left, int right, int i) {
			if (left <= l && r <= right) {
				return max[i];
			} else if (right <= l || r <= left) {
				return INF;
			} else {
				push(i);
				int m = (l + r) >> 1;
				double ret = Math.max(get(l, m, left, right, 2 * i + 1), get(m, r, left, right, 2 * i + 2));
				refresh(i);
				return ret;
			}
		}

		void updateMax(int from, int to, double val) {
			updateMax(0, size, from, to + 1, val, 0);
		}

		void push(int i) {
			if (push[i] != INF) {
				updateOne(2 * i + 1, push[i]);
				updateOne(2 * i + 2, push[i]);
				push[i] = INF;
			}
		}

		void updateOne(int i, double value) {
			max[i] = Math.max(max[i], value);
			push[i] = Math.max(push[i], value);
		}

		void refresh(int i) {
			max[i] = Math.max(max[2 * i + 1], max[2 * i + 2]);
		}

		void updateMax(int l, int r, int left, int right, double value, int i) {
			if (left <= l && r <= right) {
				updateOne(i, value);
			} else if (right <= l || r <= left) {
				return;
			} else {
				push(i);
				int m = (l + r) >> 1;
				updateMax(l, m, left, right, value, 2 * i + 1);
				updateMax(m, r, left, right, value, 2 * i + 2);
				refresh(i);
			}
		}
	}

	FastScanner in;
	PrintWriter out;

	void run() {
		in = new FastScanner();
		out = new PrintWriter(System.out);
		solve();
		out.close();
	}

	class FastScanner {
		BufferedReader br;
		StringTokenizer st;

		public FastScanner() {
			br = new BufferedReader(new InputStreamReader(System.in));
		}

		public FastScanner(String s) {
			try {
				br = new BufferedReader(new FileReader(s));
			} catch (FileNotFoundException e) {
				// TODO Auto-generated catch block
				e.printStackTrace();
			}
		}

		public String nextToken() {
			while (st == null || !st.hasMoreTokens()) {
				try {
					st = new StringTokenizer(br.readLine());
				} catch (IOException e) {
				}
			}
			return st.nextToken();
		}

		public int nextInt() {
			return Integer.parseInt(nextToken());
		}

		public long nextLong() {
			return Long.parseLong(nextToken());
		}

		public double nextDouble() {
			return Double.parseDouble(nextToken());
		}
	}

	public static void main(String[] args) {
		new Main().run();
	}
}

