import java.util.*;
import java.io.*;

public class Main {
    public static void main(String [] args) {	
    	Solver s = new Solver();
    }
    static class Solver { 
		ArrayList <Integer> arr;
		int [] dp = new int [1000010];

		int search(int b, int e, int val) {
			if(b == e) {
				return b;
			}
			int m = (b + e + 1) >> 1;
			if(dp[m] < val) return search(m, e, val);
			else return search(b, m-1, val);
		}

		Solver() {
		    Reader in = new Reader ();
		    Writer out = new Writer ();

			final double PI = Math.acos(-1.0);	

			int a = in.nextInt();
			int b = in.nextInt();
			int c = in.nextInt();
			int d = in.nextInt();

			int n = in.nextInt();
			int [] x = new int [n];
			int [] y = new int [n];
			for(int i = 0; i < n; i++) {
				x[i] = in.nextInt();
				y[i] = in.nextInt();
			}
			double ans = 100.00 * (Math.abs(a - c) + Math.abs(b - d));

			if(a > c) {
				int temp = b;
				b = d;
				d = temp;
				temp = a;
				a = c;
				c = temp;
			}
			ArrayList <Pair> rel = new ArrayList <> ();
			for(int i = 0; i < n; i++) {
				if(a <= x[i] && x[i] <= c) {
					if(Math.min(b, d) <= y[i] && y[i] <= Math.max(b, d)) {
						rel.add(new Pair(x[i], y[i]));
					}
				}
			}
			Collections.sort(rel, new Pair());
			arr = new ArrayList <> ();
			for(Pair i : rel) {
				int var;
				if(b < d) var = i.second - b;
				else var = d - i.second;
				arr.add(var);
			}
			for(int i = 0; i <= arr.size(); i++) dp[i] = Integer.MAX_VALUE;
			dp[0] = -1;

			int lcs = 0;
			for(int i = 0; i < arr.size(); i++) {
				int opt = search(0, i, arr.get(i)) + 1;
				dp[opt] = Math.min(dp[opt], arr.get(i));
				lcs = Math.max(lcs, opt);
			} 
			ans += 10.0 * lcs * ((PI / 2.0) - 2);
			if(lcs == Math.min(Math.abs(a - c), Math.abs(b - d)) + 1) {
				ans += 10.0 * (PI / 2.0);
			}
			System.out.printf("%.15f\n", ans);
		}
    }
    static class Reader {
        private StringTokenizer a;
        private BufferedReader b;
        Reader () {
            a = null;
            b = new BufferedReader (new InputStreamReader (System.in));
        }
        public String next () {
            while(a == null || !a.hasMoreTokens()) {
                try {
                    a = new StringTokenizer (b.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return a.nextToken();
        }
        public int nextInt() {
            return Integer.parseInt(this.next());
        }
        public long nextLong () {
            return Long.parseLong(this.next());
        }
        public double nextDouble () {
            return Double.parseDouble(this.next());
        }
        public String nextLine() {
            try {
                return b.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return "";
        }
    }
    static class Writer {
        private PrintWriter a;
        private StringBuffer b;
        Writer () {
            a = new PrintWriter (System.out);
            b = new StringBuffer ("");
        }
        public void write (Object s) {
            b.append(s);
        }
        public void writeln(Object s) {
            b.append(s).append('\n');
        }
        public void flush () {
            a.print(b);
            a.flush();
            a.close();
        }
    }
    static class Pair implements Comparator <Pair> {
        int first;
        int second;
        Pair  (int a, int b) {
            this.first = a;
            this.second = b;
        }
        Pair (Pair a) {
            this.first = a.first;
            this.second = a.second;
        } 
        Pair () {}
        public String toString () {
            return "[" + first + ", " + second + "]";
        }
        public int compare (Pair a, Pair b) {
            if(a.first == b.first) {
                return a.second - b.second;
            } else {
                return a.first - b.first;
            }
        }
    } 
}

import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.stream.IntStream;
import java.util.TreeMap;
import java.util.StringTokenizer;
import java.io.IOException;
import java.util.InputMismatchException;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author amotoma3
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskC solver = new TaskC();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskC {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int x1 = in.nextInt();
            int y1 = in.nextInt();
            int x2 = in.nextInt();
            int y2 = in.nextInt();

            if (x1 > x2) {
                int tmp;

                tmp = x1;
                x1 = x2;
                x2 = tmp;

                tmp = y1;
                y1 = y2;
                y2 = tmp;
            }

            int sign = y1 < y2 ? 1 : -1;
            y1 *= sign;
            y2 *= sign;

            int n = in.nextInt();
            TreeMap<Integer, Integer> map = new TreeMap<>();
            for (int i = 0; i < n; i++) {
                int x = in.nextInt();
                int y = sign * in.nextInt();

                if (x1 <= x && x <= x2 && y1 <= y && y <= y2) {
                    map.put(x, y);
                }
            }

            int[] lis = IntStream.generate(() -> (int) 1e9).limit(map.size()).toArray();
            for (int x : map.values()) {
                int index = ArrayUtils.lowerBound(lis, x);
                lis[index] = Math.min(lis[index], x);
            }
            int len = ArrayUtils.lowerBound(lis, (int) 1e9);

            if (len == Math.min(x2 - x1, y2 - y1) + 1) {
                out.println(100 * (x2 - x1 + y2 - y1) + (20 * Math.PI / 4 - 20) * (len - 1) + 20 * Math.PI / 2 - 20);
            } else {
                out.println(100 * (x2 - x1 + y2 - y1) + (20 * Math.PI / 4 - 20) * len);
            }
        }

    }

    static class InputReader {
        BufferedReader in;
        StringTokenizer tok;

        public String nextString() {
            while (!tok.hasMoreTokens()) {
                try {
                    tok = new StringTokenizer(in.readLine(), " ");
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
            }
            return tok.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(nextString());
        }

        public InputReader(InputStream inputStream) {
            in = new BufferedReader(new InputStreamReader(inputStream));
            tok = new StringTokenizer("");
        }

    }

    static class ArrayUtils {
        public static int lowerBound(int[] a, int x) {
            int high = a.length;
            int low = -1;
            while (high - low > 1) {
                int mid = (high + low) / 2;
                if (a[mid] < x) {
                    low = mid;
                } else {
                    high = mid;
                }
            }
            return high;
        }

    }
}

import java.util.Arrays;
import java.util.Scanner;

class Fountain{
    int X,Y;
    public Fountain(int x,int y){
        X = x;
        Y = y;
    }
}

class Main{

    public static void main(String[] args){
        Scanner scan = new Scanner(System.in);
        int x1 = scan.nextInt();
        int y1 = scan.nextInt();
        int x2 = scan.nextInt();
        int y2 = scan.nextInt();

        if(x1>x2){
            int tmp = x1;
            x1 = x2;
            x2 = tmp;
            tmp = y1;
            y1 = y2;
            y2 = tmp;
        }
        int N = scan.nextInt();
        Fountain[] fountain = new Fountain[N];
        for(int i=0;i<N;++i){
        fountain[i] = new Fountain(scan.nextInt(), scan.nextInt());
        }
        if(y1 > y2){
            y1 = (int)1e8 -1 - y1;
            y2 = (int)1e8 -1 - y2;
            for(int i=0;i<N;++i){
                fountain[i].Y = (int)1e8 -1 -fountain[i].Y;
            }
        }
        Arrays.sort(fountain, (a,b) -> a.X-b.X);
        int[] lis = new int[N+1];
        Arrays.fill(lis,Integer.MAX_VALUE);
        lis[0] = 0;
        for(int i=0;i<N;++i){
            if(fountain[i].X < x1 || fountain[i].X > x2)continue;
            if(fountain[i].Y < y1 || fountain[i].Y > y2)continue;
            int left = 0;
            int right = N+1;
            while(true){
                int center = (left+right)/2;
                if(lis[center] > fountain[i].Y){
                    right = center;
                }else{
                    left = center;
                }
                if(right - left ==1)break;
            }
            lis[right] = fountain[i].Y;
        }
        for(int i=N;i>=0;i--){
            if(lis[i] < Integer.MAX_VALUE){
                double ans = (double)(x2 - x1 + y2 - y1) * 100;
                ans -= i*(20 - 5*Math.PI);
                if(i > Math.min(x2-x1,y2-y1)){
                    ans += 10*Math.PI - 20;
                    ans += 20 - 5*Math.PI;
                }
                System.out.println(ans);
                break;
            }
        }



    }
}

