    const decimal PI = 3.14159265358979323846264338327950288M;
    void input()
    {
        sx = cin.nextint;
        sy = cin.nextint;
        gx = cin.nextint;
        gy = cin.nextint;
        N = cin.nextint;
        X = new int[N];
        Y = new int[N];
        for (int i = 0; i < N; i++)
        {
            X[i] = cin.nextint;
            Y[i] = cin.nextint;
        }
        dis = (decimal)(Math.Abs(sx - gx) + Math.Abs(sy - gy)) * 100;
    }

    void straight()
    {
        if (G.Count > 0)
        {
            dis = dis - 20 + 20 / 2 * PI;
        }
        WriteLine(dis.ToString("F12"));
    }
    void solve()
    {
        input();
        Array.Sort(Y, X);
        int MinY = Math.Min(sy, gy);
        int MaxY = Math.Max(sy, gy);
        int MinX = Math.Min(sx, gx);
        int MaxX = Math.Max(sx, gx);


        //t == -1のときどうなるか
        //WriteLine(MinY + " " + MaxY);
        int s = LowerBound(Y, MinY);
        int t = UpperBound(Y, MaxY) - 1;
        //WriteLine(s + " " + t);
        // s <= i <= tは可能性あり

        G = new List<int>();
        for (int i = s; i <= t; i++)
        {
            if (MinX <= X[i] && X[i] <= MaxX)
            {
                G.Add(X[i]);
                //WriteLine(X[i]);
            }
        }
        if (sx == gx || sy == gy)
        {
            straight();
            return;
        }
        //var A = G.ToArray();
        int F = G.Count;
        if (F == 0)
        {
            WriteLine(dis.ToString("F12"));
            return;
        }


        var dp = new int[F];

        int cnt = 0;
        if ((sx < gx && sy < gy) || (gx < sx && gy < sy))
        {
            //WriteLine(1);
            for (int i = 0; i < F; i++)
            {
                dp[i] = int.MaxValue;
            }

            for (int i = 0; i < F; i++)
            {
                dp[LowerBound(dp, G[i])] = G[i];
            }
            cnt = LowerBound(dp, int.MaxValue);
        }
        else
        {
            //WriteLine(2);
            for (int i = 0; i < F; i++)
            {
                dp[i] = int.MinValue;
            }
            for (int i = 0; i < F; i++)
            {
                //int k = F - i - 1;
                dp[_LowerBound(dp, G[i])] = G[i];
            }
            cnt = _LowerBound(dp, int.MinValue);
        }
        //int cnt = LowerBound(dp, int.MaxValue);
        //WriteLine(cnt + " " + dis);

        dis = dis - 20 * cnt + cnt * 20 / 4 * PI;
        WriteLine(dis.ToString("F12"));

    }
    int _LowerBound(int[] arr, int val)
    {
        int low = 0, high = arr.Length;
        int mid;

        while (low < high)
        {
            mid = ((high - low) >> 1) + low;
            if (arr[mid] > val) low = mid + 1;
            else high = mid;
        }
        return low;
    }

    int _UpperBound(int[] arr, int val)
    {
        int low = 0, high = arr.Length;
        int mid;

        while (low < high)
        {
            mid = ((high - low) >> 1) + low;
            if (arr[mid] >= val) low = mid + 1;
            else high = mid;
        }
        return low;
    }

    int LowerBound(int[] arr, int val)
    {
        int low = 0, high = arr.Length;
        int mid;

        while (low < high)
        {
            mid = ((high - low) >> 1) + low;
            if (arr[mid] < val) low = mid + 1;
            else high = mid;
        }
        return low;
    }

    int UpperBound(int[] arr, int val)
    {
        int low = 0, high = arr.Length;
        int mid;

        while (low < high)
        {
            mid = ((high - low) >> 1) + low;
            if (arr[mid] <= val) low = mid + 1;
            else high = mid;
        }
        return low;
    }

}

