class Program
{
static string[] input = Console.ReadLine().Split(' ');//Splitで区切り文字を指定して複数個受け取る。
static long xa = long.Parse(input[0]);
static long ya = long.Parse(input[1]);
static long xb = long.Parse(input[2]);
static long yb = long.Parse(input[3]);
static long n = long.Parse(Console.ReadLine());
static long[][] vertexes = new long[n][];//ここに受け取る
static long[] LISnums;
static long[] rightMin;//長さがi+1のときの右端の最小値
static long LISnum = 1;
static long compareMemo = 0;
static long LIScount = 0;

	static void Main()
	{
    for(long i = 0; i < n; i++)
    {
      vertexes[i] = new long[2];
      long[] nums = Array.ConvertAll(Console.ReadLine().Split(' '),long.Parse);
      vertexes[i][0] = nums[0];
      vertexes[i][1] = nums[1];
      if(Math.Min(xa,xb)<=nums[0] && nums[0]<=Math.Max(xa,xb)) LIScount++;
    }
    LISnums = new long[LIScount];
    rightMin = new long[LIScount];

    Array.Sort(vertexes, (a, b) => a[0].CompareTo(b[0]));
    double answer = (Math.Abs(xa-xb) + Math.Abs(ya-yb))*100;

    for(long i = 0; i < LIScount; i++)
    {
      if(Math.Min(xa,xb)<=vertexes[i][1] && vertexes[i][1]<=Math.Max(xa,xb)) 
        LISnums[i] = vertexes[i][1];
    }
    rightMin[0] = LISnums[0];

    for(long i = 1; i < n; i++)
    {
      if(LISnums[i] > rightMin[LISnum-1])
      {
        rightMin[LISnum] = LISnums[i];
        LISnum++;
      }else
      {
        compareMemo = LISnums[i];
        rightMin[Search(0, LISnum-1)] = LISnums[i];//更新位置を二部探索する
      }
    }

    if(LISnum < Math.Min(Math.Abs(xa-xb), Math.Abs(ya-yb))+1)
    {
      answer = answer + (-20+5*Math.PI)*LISnum;
