	public static long ChineseRemainder(params Tuple<long, long>[] modRemainder)
	{
		if (modRemainder.Length == 0) throw new DivideByZeroException();
		if (modRemainder.Length == 1) return modRemainder[0].Item2;
		if (modRemainder.Length == 2) return ChineseRemainder(modRemainder[0], modRemainder[1]);
		var tuple = new Tuple<long, long>(1, 0);
		for (var i = 0; i < modRemainder.Length; i++) tuple = new Tuple<long, long>(tuple.Item1 * modRemainder[i].Item1, ChineseRemainder(tuple, modRemainder[i]));
		return tuple.Item2;
	}
