class Process
{
    public Process(IIO io)
    {
        this.io = io;
    }

    IIO io;

    public void Run()
    {
        var xy = io.GetLongArray();
        var n = io.GetLong();

        var p1 = new Point(xy[0], xy[1]);
        var p2 = new Point(xy[2], xy[3]);

        if (p1.x > p2.x)
        {
            var temp = p1;
            p1 = p2;
            p2 = temp;
        }

        var signY = p1.y > p2.y ? -1 : +1;
        p1 = new Point(p1.x, p1.y * signY);
        p2 = new Point(p2.x, p2.y * signY);

        var ps = new List<Point>();
        for (int i = 0; i < n; i++)
        {
            var p = io.GetLongArray();
            ps.Add(new Point(p[0], p[1] * signY));
        }

        ps = ps.Where(p =>
            p1.x <= p.x && p.x <= p2.x &&
            p1.y <= p.y && p.y <= p2.y).ToList();

        ps.Insert(0, p1);
        ps.Insert(ps.Count, p2);

        long[] dp = new long[ps.Count];
        for (int i = 0; i < ps.Count; i++)
        {
            dp[i] = 1;
            for (int j = 0; j < i; j++)
            {
                if (ps[j].x <= ps[i].x && ps[j].y <= ps[i].y)
                {
                    dp[i] = Math.Max(dp[i], dp[j] + 1);
                }
            }
        }

        var fCount = dp.Last() - 2;
        double r;

        io.Write(fCount.ToString());

        if (fCount == Math.Min(p2.x - p1.x + 1, p2.y - p1.y + 1))
        {
            r = ((p2.x - p1.x) + (p2.y - p1.y)) * 100 - 20 * fCount + (10 + 5 * (fCount - 1)) * Math.PI;
        }
        else
        {
            r = ((p2.x - p1.x) + (p2.y - p1.y)) * 100 - 20 * fCount + (5 * fCount) * Math.PI;
        }

        io.Write(r.ToString());
    }

    public struct Point
    {
        public Point(long x, long y)
        {
            this.x = x;
            this.y = y;
        }

        public long x;
        public long y;
    }
