            int y = int.Parse(line[1]);

            // Only care about fountains between them:
            if ((x2 - x) * (x1 - x) <= 0)
            {
                if ((y2 - y) * (y1 - y) <= 0)
                {
                    // And make x1 <= x2 and y1 <= y2
                    if (x1 > x2) x *= -1;
                    if (y1 > y2) y *= -1;
                    fountains.Add(new Tuple<int, int>(x, y));
                }
            }
        }

        if (x1 > x2)
        {
            x1 *= -1;
            x2 *= -1;
        }
        if (y1 > y2)
        {
            y1 *= -1;
            y2 *= -1;
        }

        // Sort by y and then put the x into a longest-increasing-subsequence
        fountains.Sort((o1, o2) => o1.Item2.CompareTo(o2.Item2));

        int[] s = new int[fountains.Count];
        for (int i = 0; i < fountains.Count; i++)
        {
            s[i] = fountains[i].Item1;
        }
        int[] lis = LIS_nlogn(s);

        int dx = x2 - x1;
        int dy = y2 - y1;

        double score = 100.0 * (dx + dy);

        double cornerBonus = 20 - 5 * Math.PI;
        double straightThroughMalus = 10 * Math.PI - 20;
        int bounces = lis.Length;

        // There's a special case where a straight-through is unavoidable. You take one less shortcut and a longcut instead.
        if (Math.Min(dx, dy) == lis.Length - 1)
        {
            score += -cornerBonus * (lis.Length - 1) + straightThroughMalus;
        }
        else
        {
            score += -cornerBonus * (lis.Length);
        }

        Console.WriteLine(score);
        Console.ReadLine();


    }

    static int[] LIS_nlogn(int[] s)
    {
        int N = s.Length;
        int[] M = new int[N + 1];
        int[] prev = new int[N];
        int bestL = 0;

        for (int i = 0; i < N; i++)
        {
            int low = 1;
            int high = bestL;

            while (low <= high)
            {
                int mid = (low + high + 1) / 2;

                if (s[M[mid]] < s[i])
                {
                    low = mid + 1;
                }
                else high = mid - 1;
            }

            int L = low;
            prev[i] = M[L - 1];
            M[L] = i;

            if (L > bestL) bestL = L;
        }

        int[] lis = new int[bestL];
        int k = M[bestL];
        for (int i = bestL - 1; i >= 0; i--)
        {
            lis[i] = s[k];
            k = prev[k];
        }

        return lis;
    }
}

