using Enu = System.Linq.Enumerable;

public class Program
{
    static readonly int INF = (int)1e9;

    public void Solve()
    {
        int X1 = Reader.Int(), Y1 = Reader.Int(), X2 = Reader.Int(), Y2 = Reader.Int();
        int N = Reader.Int();
        int[] X = new int[N], Y = new int[N];
        int num = 0;

        for (int i = 0; i < N; i++)
        {
            int x = Reader.Int(), y = Reader.Int();
            if (x < Math.Min(X1, X2) || x > Math.Max(X1, X2)) continue;
            if (y < Math.Min(Y1, Y2) || y > Math.Max(Y1, Y2)) continue;
            x -= Math.Min(X1, X2);
            y -= Math.Min(Y1, Y2);
            X[num] = x;
            Y[num] = y;
            num++;
        }
        Array.Resize(ref X, num); Array.Resize(ref Y, num);
        Array.Sort(X, Y);
        var DP = Enu.Repeat(INF, num + 1).ToArray();
        for (int i = 0; i < num; i++)
            DP[LowerBound(DP, Y[i])] = Y[i];
        int circles = LowerBound(DP, INF);
        double ans = (Math.Abs(X1 - X2) + Math.Abs(Y1 - Y2)) * 100L - circles * (20 - 5 * Math.PI);
        if (circles > 0)
        {
            var YtoX = Y.Select((v, i) => X[i]).ToArray();
            if (DP.Take(circles).Any(y => y == Math.Abs(Y1 - Y2) || YtoX[y] == Math.Abs(X1 - X2)))
                ans += (20 - 5 * Math.PI) - (20 - 10 * Math.PI);
        }

        Console.WriteLine(ans);
    }

    static int LowerBound(int[] A, int val, int L = 0, int R = -1)
    {
        if (R == -1) R = A.Length;
        while (R - L >= 1)
        {
            int mid = (L + R) / 2;
            if (A[mid] >= val) R = mid;
            else L = mid + 1;
        }
        return R;
    }
}


