    const double eps = 1e-11;
    static readonly int[] dd = { 0, 1, 0, -1, 0 };
    static void Main()
    {
        int sx, sy, gx, gy;
        sc.Multi(out sx, out sy, out gx, out gy);
        int xl = Math.Min(sx, gx), xr = Math.Max(sx, gx), yl = Math.Min(sy, gy), yr = Math.Max(sy, gy);
        int n = sc.Int;

        var lis = new List<int[]>();
        for (int i = 0; i < n; i++)
        {
            int x, y;
            sc.Multi(out x, out y);
            if (xl <= x && x <= xr && yl <= y && y <= yr) {
                if (sy <= gy)
                    lis.Add(new int[]{x, y});
                else
                    lis.Add(new int[]{x, -y});
            }
        }
        lis.Sort((x, y) => x[0].CompareTo(y[0]));
        var dp = new int[n];
        for (int i = 0; i < n; i++)
        {
            dp[i] = M;
        }
        foreach (var item in lis)
        {
            dp[dp.UpperBound(item[1])] = item[1];
        }
