		max--;
		ans -= max * 20;
		ans += 0.5 * Math.PI * 10 * max;
		Console.WriteLine(ans);
	}

	void LIS(int[] a, out int[] dp, out int[] route){

		int n = a.Length;
		dp = new int[n+1];
		int[] dp2 = new int[n+1];
		route = new int[n];
		dp[0] = int.MinValue;
		dp2[0] = -1;
		for(int i=1;i<=n;i++){
			dp[i] = int.MaxValue;
			dp2[i] = -1;
		}

		for(int i=0;i<n;i++){
			int l = 0;
			int r = n + 1;
			while(r - l > 1){
				int c = (l + r) / 2;
				if(dp[c] < a[i]){
					l = c;
				} else {
					r = c;
				}
			}
			dp[r] = a[i];
			dp2[r] = i;
			route[i] = dp2[l];
		}
	}


