class SegTree{
	//segment Tree 
	// 0-origin
	public int[] Data;	//実体
	public int Inf;	//初期化用のlargeNumber
	public int N;		//size 
	public int n;		//size (2の冪)

	//コンストラクタ
	public SegTree(int n_,int inf_){
		N=n_;Inf=inf_;
		n=1;
		while(n<n_)n*=2;
		Data=new int[2*n-1];
		for(int i=0;i<2*n-1;i++)Data[i]=Inf;
	}
	public SegTree(int n_){
		N=n_;Inf=(int)2e9;
		n=1;
		while(n<n_)n*=2;
		Data=new int[2*n-1];
		for(int i=0;i<2*n-1;i++)Data[i]=Inf;
	}

	//k-番目の値をaに変更(ヒープ：各ノードは両手のMinを値に持つ）
	//	   0
	//	 1   2
	//	3 4 5 6
	public void Update(int k,int a){
		k+=n-1;	//上にはn-1個乗る
		Data[k]=a;
		while(k>0){
			k=(k-1)/2;
			Data[k]=Math.Min(Data[k*2+1],Data[k*2+2]);
		}
	}


	public int MinQuery(int l,int r){
		return Query(l,r,0,0,n);
	}
	//RMQ;
	//	[a,b) のMinを返す
	//	後ろ3つの引数は	k,l,r：ヒープのk-ノードが範囲 [l,r) に対応していることを示す
	//	外から呼ぶ時は Query(a,b,0,0,n) の形で呼ぶ
	public int Query(int a,int b,int k,int l,int r){
		// [a,b) ∩ [l,r) =φ　⇒Infを返す
		if(r<=a || b<=l) return Inf;
		// [a,b) ⊃ [l,r) ⇒Data[k]を返す 
		if(a<=l && r<=b)return Data[k];
		// さもなくば、両手のうち小さい方を返す
		int vl=Query(a,b,k*2+1,l,(l+r)/2);
		int vr=Query(a,b,k*2+2,(l+r)/2,r);
		return Math.Min(vl,vr);
	}


	//派生メソッド
	public int Min{
		get{return Data[0];}
	}

	public int LMinIdx(){
		int ret=0;
		int min=this.Min;
		while(ret<Data.Length){
			if(ret*2+1<Data.Length){
				if(Data[ret*2+1]==min){
					ret=ret*2+1;
				}else{
					ret=ret*2+2;
				}
			}else{
				break;
			}
		}
		return ret-(n-1);
	}

	public void UniqInit(int val){
		for(int i=0+n-1;i<N+n-1;i++)Data[i]=val;
		int l=n-1;int r=N+n-1-1;
		while(l>0){
			l=(l-1)/2;r=(r-1)/2;
			for(int i=l;i<=r;i++)Data[i]=val;
		}
	}

	public void AddUpdate(int k,int a){
		//usage overflow注意
		Update(k,Data[k+n-1]+a);
	}

	public void Dump(){
		Console.WriteLine();
		int h=0;
		int cnt=0;
		for(int i=0;i<Data.Length;i++){
			Console.Write("{0} ",Data[i]);
			cnt++;
			if(cnt==1<<h){
				cnt=0;
				h++;
				Console.WriteLine();
			}
		}
	}

}

