		public SlideMaximum(long[] x) { a = x; deq = new Deque<int>(); }
		public void Add(int index)
		{
			while (deq.Count > 0 && a[deq.PeekBack()] <= a[index]) deq.PopBack();
			deq.PushBack(index);
		}
