		{
			LazyEvaluate(node);
			if (to <= l || r <= from) return Unit;
			else if (from <= l && r <= to) return seg[node];
			else return Math.Max(Max(from, to, 2 * node + 1, l, (l + r) >> 1), Max(from, to, 2 * node + 2, (l + r) >> 1, r));
		}
