using Enu = System.Linq.Enumerable;

public class Program
{
    static readonly int INF = (int)1e9;

    public void Solve()
    {
        int X1 = Reader.Int(), Y1 = Reader.Int(), X2 = Reader.Int(), Y2 = Reader.Int();
        int N = Reader.Int();
        var list = new List<Point>();

        for (int i = 0; i < N; i++)
        {
            int x = Reader.Int(), y = Reader.Int();
            if (x < Math.Min(X1, X2) || x > Math.Max(X1, X2)) continue;
            if (y < Math.Min(Y1, Y2) || y > Math.Max(Y1, Y2)) continue;
            x -= Math.Min(X1, X2);
            y -= Math.Min(Y1, Y2);
            list.Add(new Point(x, y));
        }
        double ans = (Math.Abs(X1 - X2) + Math.Abs(Y1 - Y2)) * 100L;
        if (list.Count == 1 && (X1 == X2 && list[0].X == 0 || Y1 == Y2 && list[0].Y == 0))
        {
            ans -= 20 - 10 * Math.PI;
            Console.WriteLine(ans);
            return;
        }
        list.Sort();
        var DP = Enu.Repeat(INF, list.Count + 1).ToArray();
        foreach (var p in list)
            DP[LowerBound(DP, p.Y)] = p.Y;
        ans -= LowerBound(DP, INF) * (20 - 5 * Math.PI);

        Console.WriteLine(ans);
    }

    static int LowerBound(int[] A, int val, int L = 0, int R = -1)
    {
        if (R == -1) R = A.Length;
        while (R - L >= 1)
        {
            int mid = (L + R) / 2;
            if (A[mid] >= val) R = mid;
            else L = mid + 1;
        }
        return R;
    }


    struct Point : IComparable<Point>
    {
        public int X;
        public int Y;
        public Point(int X, int Y)
        {
            this.X = X;
            this.Y = Y;
        }
        public int CompareTo(Point B)
        {
            return X != B.X ? X.CompareTo(B.X) : B.Y.CompareTo(Y);
        }
        public override string ToString()
        {
            return "X:" + X + " Y:" + Y;
        }
    }

}


