namespace Tmp
{
    class Problem : IDisposable
    {
        bool IsGCJ;
        int Repeat;
        Scanner sc;
        Printer pr;
        public Problem(bool isGCJ, Scanner scanner, Printer printer)
        {
            sc = scanner;
            pr = printer;
            IsGCJ = isGCJ;
            if (isGCJ) Repeat = sc.nextInt();
            else Read();
        }
        public Problem(bool isGCJ) : this(isGCJ, new Scanner(), new Printer()) { }
        public Problem(bool isGCJ, Scanner scanner) : this(isGCJ, scanner, new Printer()) { }
        public Problem(bool isGCJ, Printer printer) : this(isGCJ, new Scanner(), printer) { }
        public void Solve()
        {
            if (IsGCJ) for (var i = 0; i < Repeat; i++) { Read(); pr.Write("Case #" + (i + 1) + ": "); SolveOne(); }
            else SolveOne();
        }
        public void Dispose()
        {
            sc.Dispose();
            pr.Dispose();
        }
        public int Size { get { return 1; } }
        public const long Mod = 1000000007;

        // 使用する変数をここに書く
        // string S;
        // int a;
        /// <summary>
        /// 読み込み処理をここに書く
        /// </summary>
        void Read()
        {

        }
        /// <summary>
        /// メイン処理をここに書く
        /// </summary>
        void SolveOne()
        {
            long x1 = sc.nextLong();
            long y1 = sc.nextLong();
            long x2 = sc.nextLong();
            long y2 = sc.nextLong();
            if (x1 > x2 || (x1 == x2 && y1 > y2))
            {
                Swap(ref x1, ref x2);
                Swap(ref y1, ref y2);
            }
            bool yflag = false;
            if (y1 > y2)
            {
                yflag = true;
                Swap(ref y1, ref y2);
            }

            int n = sc.nextInt();
            List<long> ls = new List<long>();

            for (int i = 0; i < n; i++)
            {
                long x = sc.nextLong();
                long y = sc.nextLong();
                if (yflag)
                {
                    y = y1 + (y2 - y);
                }
                if (x < x1 || x2 < x) continue;
                if (y < y1 || y2 < y) continue;
                ls.Add((x << 32) + y);
            }
            ls.Sort();

            long[] dp = new long[n + 1];
            long Max = long.MaxValue / 2;
            for (int i = 0; i < n + 1; i++)
            {
                dp[i] = Max;
            }
            dp[0] = -1;

            foreach (var l in ls)
            {
                long y = (l & 0xFFFFFFFF);
                int lb = 0;
                int ub = n + 1;
                while (ub - lb > 1)
                {
                    int mid = (ub + lb) / 2;
                    if (dp[mid] <= y) lb = mid;
                    else ub = mid;
                }
                dp[ub] = y;
            }
            long cnt = 0;
            for (int i = 0; i < n + 1; i++)
            {
                if (dp[i] != Max) cnt = i;
            }

            double ans = 100L * (x2 - x1 + y2 - y1);
            ans += (5 * Math.PI - 20) * cnt;
            if (cnt == Math.Min(x2 - x1, y2 - y1) + 1)
            {
                ans += 10 * Math.PI - 20 - (5 * Math.PI - 20);
            }
            Console.WriteLine(ans);

        }
        void Swap<T>(ref T x, ref T y)
        {
            T tmp = x;
            x = y;
            y = tmp;
        }
    }
}
