	//using GeometryLong;
	class Problem : IDisposable
	{
		bool IsGCJ;
		int Repeat;
		Scanner sc;
		Printer pr;
		public Problem(bool isGCJ, Scanner scanner, Printer printer)
		{
			sc = scanner;
			pr = printer;
			IsGCJ = isGCJ;
			if (isGCJ) Repeat = sc.Get<int>();
			else Read();
		}
		public Problem(bool isGCJ) : this(isGCJ, new Scanner(), new Printer()) { }
		public Problem(bool isGCJ, Scanner scanner) : this(isGCJ, scanner, new Printer()) { }
		public Problem(bool isGCJ, Printer printer) : this(isGCJ, new Scanner(), printer) { }
		public void Solve()
		{
			if (IsGCJ) for (var i = 0; i < Repeat; i++) { Read(); pr.Write("Case #" + (i + 1) + ": "); SolveOne(); }
			else SolveOne();
		}
		public void Dispose()
		{
			sc.Dispose();
			pr.Dispose();
		}
		public int Size => 1;
		public const long Mod = 1000000007;
		//public const long Mod = 924844033;
		RandomSFMT rand = Program.rand;
		int x1, y1, x2, y2;
		int N;
		Tuple<int, int>[] ft;
		void Read()
		{
			sc.Read(out x1, out y1, out x2, out y2);
			N = sc.Int;
			ft = sc.ReadManyLines<int, int>(N);
		}
		void SolveOne()
		{
			pr.WriteLine("{0:f16}", Calc());
		}
		struct P : IComparable<P>
		{
			public int X, Y;
			public P(int x, int y) { X = x; Y = y; }
			public int CompareTo(P q) => X.CompareTo(q.X);
			public void S(int x, int y) { X *= x; Y *= y; }
			public override string ToString() => $"({X}, {Y})";
		}
		double Calc()
		{
			if (x1 == x2)
			{
				throw new Exception();
				if (y1 > y2) Swap(ref y1, ref y2);
				foreach (var f in ft) if (f.Item1 == x1) return (y2 - y1) * 100.0 + (y1 < f.Item2 && f.Item2 < y2 ? 10 * PI - 20 : 0);
				return (y2 - y1) * 100.0;
			}
			if (y1 == y2)
			{
				throw new Exception();
				if (x1 > x2) Swap(ref x1, ref x2);
				foreach (var f in ft) if (f.Item2 == y1) return (x2 - x1) * 100.0 + (x1 < f.Item1 && f.Item1 < x2 ? 10 * PI - 20 : 0);
				return (x2 - x1) * 100.0;
			}
			var g = new P(x2 - x1, y2 - y1);
			var sx = g.X > 0 ? 1 : -1;
			var sy = g.Y > 0 ? 1 : -1;
			g.S(sx, sy);
			var ps = new List<P>(N);
			foreach (var f in ft)
			{
				var t = new P(f.Item1 - x1, f.Item2 - y1);
				t.S(sx, sy);
				if (0 <= t.X && t.X <= g.X && 0 <= t.Y && t.Y <= g.Y) ps.Add(t);
			}
			ps.Sort();
			var l = ps.Select(p => p.Y).ToArray();
			var c = LongestIncreasingSubsequence(l);
			return (g.X + g.Y) * 100.0 - c * (20 - 5 * PI);
		}
		int[] SuffixArray(string S)
		{
			var N = S.Length;
			var sa = new int[N + 1];
			var r = new int[N + 1];
			for (var i = 0; i <= N; i++)
			{
				sa[i] = i;
				r[i] = i < N ? S[i] : -1;
			}
			var k = 1;
			Comparison<int> comp = (i, j) =>
			{
				if (r[i] != r[j]) return r[i] - r[j];
				var a = i + k <= N ? r[i + k] : -1;
				var b = j + k <= N ? r[j + k] : -1;
				return a - b;
			};
			for (; k <= N; k *= 2)
			{
				Array.Sort(sa, comp);
				var tmp = new int[N + 1];
				for (var i = 1; i <= N; i++) tmp[sa[i]] = tmp[sa[i - 1]] + (comp(sa[i - 1], sa[i]) < 0 ? 1 : 0);
				r = tmp;
			}
			return sa;
		}
	}
	class RangeSegmentTree
	{
		int N2;
		int[] seg, unif;
		public RangeSegmentTree(int N)
		{
			N2 = 1;
			while (N2 < N) N2 <<= 1;
			seg = new int[2 * N2 - 1];
			unif = new int[2 * N2 - 1];
		}
		void LazyEvaluate(int node)
		{
			if (unif[node] == 0) return;
			seg[node] += unif[node];
			if (node < N2 - 1)
			{
				unif[2 * node + 1] += unif[node];
				unif[2 * node + 2] += unif[node];
			}
			unif[node] = 0;
		}
		void Update(int node) => seg[node] = seg[2 * node + 1] + seg[2 * node + 2];
		public void AddRange(int from, int to, int value) => AddRange(from, to, value, 0, 0, N2);
		void AddRange(int from, int to, int value, int node, int l, int r)
		{
