    int sx, sy, tx, ty;
    sc.read(sx, sy, tx, ty);
    int n;
    sc.read(n);
    int[2][] p = new int[2][n];
    foreach (i; 0..n) {
        sc.read(p[i][0], p[i][1]);
    }
    if (sx > tx) {
        sx = L - 1 - sx;
        tx = L - 1 - tx;
        foreach (i; 0..n) {
            p[i][0] = L - 1 - p[i][0];
        }
    }
    if (sy > ty) {
        sy = L - 1 - sy;
        ty = L - 1 - ty;
        foreach (i; 0..n) {
            p[i][1] = L - 1 - p[i][1];
        }
    }
    if (sx == tx) {
        swap(sx, sy);
        swap(tx, ty);
        foreach (i; 0..n) {
            swap(p[i][0], p[i][1]);
        }
    }
    p = p.filter!(a =>
