double solve(int sx, int sy, int tx, int ty, int[2][] p) {
    assert(sx != tx && sy != ty);

    int[] v = [sy, ty] ~ p.map!"a[1]".array;
    v = v.sort!"a<b".uniq.array;
    int getI(int x) {
        return v.assumeSorted.lowerBound(x).length.to!int;
    }


    auto M = v.length.to!int;
    auto seg = SimpleSeg!(int, (a, b) => max(a, b), -(10^^9))(M);
    seg[0] = 0;
    foreach (d; p) {
        int py = getI(d[1]);
        seg[py] = seg[0..py].sum() + 1;
    }
    int c = seg[0..M].sum();
    double off = (tx-sx + ty-sy) * 100.0;
    off += c * (-20.0 + 5*PI);
    if (c == 1+min(tx-sx, ty-sy)) {
        off += 5*PI;
    }
    return off;
}

int main() {
    Scanner sc = new Scanner(stdin);
    int sx, sy, tx, ty;
    sc.read(sx, sy, tx, ty);
    int n;
    sc.read(n);
    int[2][] p = new int[2][n];
    foreach (i; 0..n) {
        sc.read(p[i][0], p[i][1]);
    }
    if (sx > tx) {
        sx = L - 1 - sx;
        tx = L - 1 - tx;
        foreach (i; 0..n) {
            p[i][0] = L - 1 - p[i][0];
        }
    }
    if (sy > ty) {
        sy = L - 1 - sy;
        ty = L - 1 - ty;
        foreach (i; 0..n) {
            p[i][1] = L - 1 - p[i][1];
        }
    }
    if (sx == tx) {
        swap(sx, sy);
        swap(tx, ty);
        foreach (i; 0..n) {
            swap(p[i][0], p[i][1]);
        }
    }
    p = p.filter!(a =>
        sx <= a[0] && a[0] <= tx &&
        sy <= a[1] && a[1] <= ty).array;
    p.sort!"a[0] < b[0]";
    debug {
