Node [] t;
int nodes;
int root;

void tRecalc (int v)
{
	t[v].best = max (t[v].value, t[t[v].left].best, t[t[v].right].best);
	t[v].num = 1 + t[t[v].left].num + t[t[v].right].num;
}

int [2] tSplit (int v, int x)
{
	if (v == nil)
	{
		return [nil, nil];
	}
	if (t[v].coord < x)
	{
		auto temp = tSplit (t[v].right, x);
		t[v].right = temp[0];
		tRecalc (v);
		return [v, temp[1]];
	}
	else
	{
		auto temp = tSplit (t[v].left, x);
		t[v].left = temp[1];
		tRecalc (v);
		return [temp[0], v];
	}
}

int tMerge (int u, int v)
{
	if (u == nil)
	{
		return v;
	}
	if (v == nil)
	{
		return u;
	}
	if (uniform (0, t[u].num + t[v].num) < t[u].num)
	{
		t[u].right = tMerge (t[u].right, v);
		tRecalc (u);
		return u;
	}
	else
	{
		t[v].left = tMerge (u, t[v].left);
		tRecalc (v);
		return v;
	}
}

