immutable L = 10^^8;

double solve(int sx, int sy, int tx, int ty, int[2][] p) {
    assert(sx != tx && sy != ty);

    int[] v = [sy, sy+1, ty-1, ty];
    foreach (d; p) {
        v ~= max(sy, d[1]-1);
        v ~= d[1];
        v ~= min(ty, d[1]+1);
    }
    v = v.sort!"a<b".uniq.array;
    int getI(int x) {
        return v.assumeSorted.lowerBound(x).length.to!int;
    }

    double off = (tx-sx + ty-sy) * 100.0;

    auto M = v.length.to!int;
    auto seg = LazySeg!(double, double,
        (a, b) => min(a, b),
        (a, b) => min(a, b),
        (a, b) => min(a, b),
        1e12, 1e12)(M);
    seg[0..M] += 0;

    int ba = -1;
    foreach (d; p) {
        int py = getI(d[1]);
        bool di = (d[0] - ba) > 1;
        ba = d[0];
        if (d[0] == sx) {
            //start
            seg[py] = -20.0 + 5*PI;
            foreach (i; py+1..M) {
                seg[i] = -20.0 + 10*PI;
            }
            continue;
        } else if (d[0] == tx) {
            //last
            double ans = 1e12;
            ans = min(ans, seg[py+1..M].sum());
            ans = min(ans, seg[py] - 20.0 + 5*PI);
            if (di) {
                ans = min(ans, seg[0..py].sum() - 20.0 + 5*PI);
            }
            ans = min(ans, seg[0..py].sum() - 20.0 + 10*PI);
            return off + ans;
        } else {
            //mid
            if (di) {
                seg[py+1..M] += seg[0..py].sum() - 20.0 + 5*PI;
            }
            seg[py+1..M] += min(seg[0..py].sum() - 20.0 + 10*PI, seg[py] - 20.0 + 5*PI);
            seg[py] = min(seg[py] - 20.0 + 10*PI, seg[0..py].sum() - 20.0 + 5*PI);
        }
    }
    return off + seg[0..M].sum();
}

int main() {
    Scanner sc = new Scanner(stdin);
    int sx, sy, tx, ty;
    sc.read(sx, sy, tx, ty);
    int n;
    sc.read(n);
    int[2][] p = new int[2][n];
    foreach (i; 0..n) {
        sc.read(p[i][0], p[i][1]);
    }
    if (sx > tx) {
        sx = L - 1 - sx;
        tx = L - 1 - tx;
        foreach (i; 0..n) {
            p[i][0] = L - 1 - p[i][0];
        }
    }
    if (sy > ty) {
        sy = L - 1 - sy;
        ty = L - 1 - ty;
        foreach (i; 0..n) {
            p[i][1] = L - 1 - p[i][1];
        }
    }
    if (sx == tx) {
        swap(sx, sy);
        swap(tx, ty);
        foreach (i; 0..n) {
            swap(p[i][0], p[i][1]);
        }
    }
    p = p.filter!(a =>
        sx <= a[0] && a[0] <= tx &&
        sy <= a[1] && a[1] <= ty).array;
    p.sort!"a[0] < b[0]";
    debug {
        writeln(sx, " ", sy, " ", tx, " ", ty);
        writeln(p);
    }
    if (sy == ty) {
        double r = (tx - sx) * 100.0;
        if (p.length) {
            r -= 20;
            r += 10 * PI;
        }
        writefln("%.20f", r);
        return 0;
    }
    writefln("%.20f", solve(sx, sy, tx, ty, p));
    return 0;
}
