def ILI(): return list(map(int, input().split()))

PI = math.pi
kado = 5 * PI - 20
choku = 10 * PI - 20


def read():
    x_1, y_1, x_2, y_2 = ILI()
    x_1, x_2 = min(x_1, x_2), max(x_1, x_2)
    y_1, y_2 = min(y_1, y_2), max(y_1, y_2)
    N = II()
    points = []
    for __ in range(N):
        x, y = ILI()
        if x_1 <= x <= x_2 and y_1 <= y <= y_2:
            points.append((x, y))
    return x_1, y_1, x_2, y_2, N, points


def solve(x_1, y_1, x_2, y_2, N, points):
    if len(points) == 0:
        ans = ((x_2 - x_1) + (y_2 - y_1)) * 100
    else:
        x_dif = x_2 - x_1
        y_dif = y_2 - y_1
        if x_dif == 0:
            ans = y_dif * 100
            for p in points:
                if p[0] == x_1:
                    ans += choku
                    break
        elif y_dif == 0:
            ans = x_dif * 100
            for p in points:
                if p[1] == y_1:
                    ans += choku
                    break
        else:
            points.sort(key=lambda x: x[0])
            count = [1] * len(points)
            for i in range(len(points) - 1, -1, -1):
                for j in range(i + 1, len(points)):
                    if points[i][1] < points[j][1]:
                        count[i] = max(count[i], count[j] + 1)
            max_count = max(count)
            ans = (x_dif + y_dif) * 100 + max_count * kado
    return ans


def main():
    params = read()
    print(solve(*params))


