    for n,p in enumerate(pool): ##(X, Y, V)
        if subset(p[:2], f):
            max_value = max(max_value, p[2])
        else:
            notsubset.append(n)
    new_pool = [ pool[i] for i in notsubset]
    new_pool.append(
        f + [max_value + 1]
    )
    return new_pool
