macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String {
            bytes
                .by_ref()
                .map(|r| r.unwrap() as char)
                .skip_while(|c| c.is_whitespace())
                .take_while(|c| !c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };

    ($next:expr, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, [ $t:tt ]) => {
        {
            let len = read_value!($next, usize);
            (0..len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
        }
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

#[allow(unused_imports)]
use std::cmp::{min, max};

fn main() {
    input!{
        s: (i64, i64),
        t: (i64, i64),
        n: usize,
        mut v: [(i64, i64); n]
    }
    let mut g = (t.0 - s.0, t.1 - s.1);
    v = v.iter().map(|x| (x.0 - s.0, x.1 - s.1)).filter(|x| x.0 * (x.0 - g.0) <= 0 && x.1 * (x.1 - g.1) <= 0).collect();
    if g.0 < 0 {
        g.0 *= -1;
        for i in 0..v.len() {
            v[i].0 *= -1;
        }
    }
    if g.1 < 0 {
        g.1 *= -1;
        for i in 0..v.len() {
            v[i].1 *= -1;
        }
    }
    let pi = std::f64::consts::PI;
    let mut d0 = (g.0 + g.1) as f64 * 100.0;
    if v.len() == 0 {
        println!("{}", d0);
        return;
    }
    if g.0 as usize == v.len() - 1 || g.1 as usize == v.len() - 1 {
        d0 += 5.0 * pi;
    }
    v.sort_by_key(|x| x.0);
    let mut comp: Vec<i64> = v.iter().map(|x| x.1).collect();
    comp.sort();
    let mut bit = BIT::new(v.len() + 1);
    for &(_, y) in &v {
        let i = comp.binary_search(&y).unwrap();
        let m = bit.max(i);
        bit.update(i, m + 1);
    }
    println!("{}", d0 + (5.0 * pi - 20.0) * bit.max(v.len()) as f64);
}

struct BIT {
    v: Vec<usize>,
    n: usize
}

impl BIT {
    fn new(n: usize) -> BIT {
        BIT{v: vec![0; n + 1], n: n}
    }

    // update i th element by x
    fn update(&mut self, i: usize, x: usize) {
        let mut id = i as i64 + 1;
        while id <= self.n as i64 && self.v[id as usize] < x {
            self.v[id as usize] = x;
            id += id & -id;
        }
    }

    // max in 0 to i th element
    fn max(&self, i: usize) -> usize {
        let mut id = i + 1;
        let mut ret = 0;
        while id > 0 {
            ret = std::cmp::max(ret, self.v[id]);
            id &= id - 1;
        }
        ret
    }
}

use std::cmp::min;

const INF: i64 = 1 << 50;
fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());
    let x1: i64 = sc.read();
    let y1: i64 = sc.read();
    let x2: i64 = sc.read();
    let y2: i64 = sc.read();

    let base = ((x1 - x2).abs() + (y1 - y2).abs()) as f64 * 100.0;
    let reduce = 20.0 - 5.0 * std::f64::consts::PI;

    let ((x1, y1), (x2, y2)) = if y1 > y2 {
        ((x2, y2), (x1, y1))
    } else {
        ((x1, y1), (x2, y2))
    };

    let (x1, x2, x_reversed) = if x1 > x2 {
        (-x1, -x2, true)
    } else {
        (x1, x2, false)
    };

    let mut xy = vec![];
    let n: usize = sc.read();
    for _ in 0..n {
        let x: i64 = sc.read();
        let y: i64 = sc.read();
        if y < y1 || y2 < y {
            continue;
        }

        let x = if x_reversed { -x } else { x };
        if x < x1 || x2 < x {
            continue;
        }

        xy.push((x, y));
    }

    assert!(x1 <= x2 && y1 <= y2);
    // let (x1, x2, y1, y2, xy) = if x1 == x2 {
    //     let mut xy = xy.into_iter().map(|(x, y)| (y, x)).collect::<Vec<_>>();
    //     xy.sort();
    //     (y1, y2, x1, x2, xy)
    // } else {
    //     xy.sort();
    //     (x1, x2, y1, y2, xy)
    // };

    xy.sort();
    let mut ans = vec![INF; n + 1];
    ans[0] = y1;

    for (_, y) in xy
        .into_iter()
        .skip_while(|&(x, _)| x < x1)
        .take_while(|&(x, _)| x <= x2)
    {
        match ans.binary_search(&y) {
            Ok(count) => {
                ans[count + 1] = min(ans[count + 1], y + 1);
                if count == 0 || ans[count - 1] == -1 {
                    ans[count] = -1;
                }
            }
            Err(i) => {
                assert!(i > 0);
                ans[i] = min(ans[i], y);
            }
        }
    }

    match ans.binary_search(&y2) {
        Ok(i) => {
            let ans = base - reduce * (i as f64);
            println!("{}", ans);
        }
        Err(i) => {
            assert!(i > 0);
            if ans[i - 1] == -1 {
                let ans = base - reduce * ((i - 1) as f64);
                println!("{}", ans + 10.0 * std::f64::consts::PI - 20.0);
            } else {
                let ans = base - reduce * ((i - 1) as f64);
                let h = (y1 - y2).abs();
                let w = (x1 - x2).abs();

                if i - 1 == min(h, w) as usize + 1 {
                    println!("{}", ans + 5.0 * std::f64::consts::PI);
                } else {
                    println!("{}", ans);
                }
            }
        }
    }
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> Self {
        IO(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: ToString>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.to_string().as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

use std::io::{BufRead, Write};
use std::io;

fn solve<R: BufRead, W: Write>(mut input: R, mut output: W) {
    let mut buf = String::new();
    input.read_line(&mut buf).unwrap();
    let (mut x1, mut y1, mut x2, mut y2): (usize, usize, usize, usize) = {
        let mut split = buf.split_whitespace();
        (
            split.next().unwrap().parse().unwrap(),
            split.next().unwrap().parse().unwrap(),
            split.next().unwrap().parse().unwrap(),
            split.next().unwrap().parse().unwrap(),
        )
    };
    if x1 > x2 {
        std::mem::swap(&mut x1, &mut x2);
    }
    if y1 > y2 {
        std::mem::swap(&mut y1, &mut y2);
    }
    buf.clear();
    input.read_line(&mut buf).unwrap();
    let n: usize = buf.trim().parse().unwrap();
    let mut x_index: Vec<(usize, usize)> = Vec::new();
    for _ in 0..n {
        buf.clear();
        input.read_line(&mut buf).unwrap();
        let (x, y): (usize, usize) = {
            let mut split = buf.split_whitespace();
            (
                split.next().unwrap().parse().unwrap(),
                split.next().unwrap().parse().unwrap(),
            )
        };
        x_index.push((x, y));
    }
    x_index.sort();
    let items: Vec<usize> = x_index
        .iter()
        .filter(|&&(x, y)| x >= x1 && x <= x2 && y >= y1 && y <= y2)
        .map(|&(_, y)| y)
        .collect();
    let mut l: Vec<usize> = vec![std::usize::MAX; items.len()];
    for &k in &items {
        if let Err(idx) = l.binary_search(&k) {
            l[idx] = k;
        }
    }
    let lis = l.iter()
        .position(|&x| x == std::usize::MAX)
        .unwrap_or(l.len());
    let result = (((x2 - x1) + (y2 - y1)) * 100) as f64 -
        (lis as f64) * (20. - std::f64::consts::PI * 5.) +
        if x2 - x1 + 1 == lis || y2 - y1 + 1 == lis {
            std::f64::consts::PI * 5.
        } else {
            0.
        };
    writeln!(output, "{:.13}", result).unwrap();
}

fn main() {
    let stdin = io::stdin();
    let stdout = io::stdout();
    solve(stdin.lock(), stdout.lock());
}

