fn get_line() -> String {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).ok();
    s.trim().to_string()
}

fn reads<T>() -> Vec<T>
    where
        T: std::str::FromStr,
        <T as std::str::FromStr>::Err: std::fmt::Debug {
    get_line().split(' ').map(|x| x.parse().unwrap()).collect()
}

fn readln<T>() -> T
    where
        T: std::str::FromStr,
        <T as std::str::FromStr>::Err: std::fmt::Debug {
    get_line().parse().unwrap()
}

use std::cmp;

use std::cmp::Ordering;

#[derive(Clone, Copy, Eq, PartialEq)]
struct E {
    x: i64,
    y: i64,
}

impl Ord for E {
    fn cmp(&self, other: &Self) -> Ordering {
        (self.x + self.y).cmp(&(other.x + other.y))
    }
}

impl PartialOrd for E {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

fn main() {
    let xys: Vec<i64> = reads();
    let n = readln();
    let mut xs = vec![];

    let mut lx = cmp::min(xys[0], xys[2]);
    let ux = cmp::max(xys[0], xys[2]);
    let mut ly = cmp::min(xys[1], xys[3]);
    let uy = cmp::max(xys[1], xys[3]);

    let mut res = (ux - lx + uy - ly) as f64 * 100f64;

    for _ in 0..n {
        let xy: Vec<i64> = reads();

        if ux >= xy[0] && xy[0] >= lx && uy >= xy[1] && xy[1] >= ly {
            xs.push(E {x: xy[0], y: xy[1]});
        }
    }

    if lx == ux || ly == uy {
        let d = 10f64 * std::f64::consts::PI - 20f64;

        res += xs.len() as f64 * d;
    }
    else {
        xs.sort();
        let d = 20f64 - 5f64 * std::f64::consts::PI;
        for e in xs {
            if e.x >= lx && e.y >= ly {
                lx = e.x;
                ly = e.y;

                res -= d;
            }
        }
    }


    println!("{}", res);
}
